INSERT INTO `jobs` VALUES (1, '哆啦搜保', '互联网', '100-499人', '不需要融资', '大专', '<p>岗位名称：初级开发工程师（AI应用方向）</p><p><strong>岗位背景</strong></p><p>我们是一家运⽤AI技术驱动的互联⽹保险公司，⽬前已搭建了完善的AI系统框架（涵盖智能客服、核运营自动化等多个AI应用场景）。现需要⼀位基础程序员，在现有技术框架下执行编码工作，并负责日常AI系统的运维监测、问题排查与调试优化。简单来说：框架有人搭好了，需要你来填代码、保稳定。</p><p><strong>岗位职责</strong></p><ul><li>代码开发与实现：在现有技术架构和设计方案的指导下，完成业务系统及AI应用相关模块的代码编写、单元测试与上线工作。</li><li>AI系统日常运维：负责公司AI应用的日常巡检、服务监控、日志整理与系统备份，保障业务系统稳定运行。</li><li>故障排查与调试：及时响应并处理AI系统及业务系统的日常异常问题，完成问题诊断、解决实施与闭环反馈。</li><li>接口开发与联调：参与后端接口的开发与联调工作，确保各系统模块之间的数据交互顺畅。</li><li>技术文档输出：编写和维护相关技术文档、运维报告，整理故障台账。</li></ul><p><strong>任职要求必备条件</strong></p><ul><li>大专及以上学历，计算机、软件工程、信息技术等相关专业优先。（可接受应届毕业生）--熟练掌握至少一种主流编程语言（Python 或 Java 优先），具备独立完成模块编码的能力。</li><li>熟悉常用的数据库操作（如 MySQL、PostgreSQL 等）。</li><li>熟悉 Linux 操作系统基本操作，能进行基础的服务器运维和日志查看。</li><li>具备良好的学习能力、逻辑思维能力和问题解决能力。</li><li>有责任心，工作严谨，具备良好的团队协作和沟通能力。加分项：了解 Docker、Kubernetes 等容器化技术。有 AI 相关产品（如智能问答、RAG、大模型应用等）的开发或运维经验。了解 CI/CD 自动化部署流程。有互联网或保险行业从业背景。</li></ul><p><strong>四、薪资福利</strong></p><ol><li>工作时间：双休，9:00-18:</li><li>薪资：8K-12K，具体根据面试结果3、工作地点：深圳市南山区讯美科技大厦1306</li></ol><p><strong>五、职位福利</strong></p><p>五险一金、绩效奖金、年终奖、加班补助、餐补、过节</p><p><strong>福利</strong></p><p>、季度团建、周末双休等</p>', '1-3年', '2c5bec296b1854ce0nJ70t27EFBX', '深圳 · 南山区 · 科技园', '8-13K', 'Java, 大数据经验, Docker, PostgreSQL, MySQL, Python', '初级开发工程师（AI应用方向）', 'https://www.zhipin.com/job_detail/2c5bec296b1854ce0nJ70t27EFBX.html', '生日福利, 加班补助, 通讯补贴, 底薪加提成, 绩效奖金, 带薪年假, 五险一金, 零食下午茶, 年终奖, 夜班补助, 全勤奖, 保底工资, 团建聚餐, 节日福利, 交通补助, 股票期权, 工龄奖, 员工旅游');
INSERT INTO `jobs` VALUES (2, '卓智达科技', '互联网', '20-99人', '不需要融资', '本科', '<ol><li>全日制统招大学本科学历，计算机相关专业，1-2年相关工作经验,有Android和Flutter开发经验优；</li><li>熟悉网络通信机制，对Socket通信、TCP/IP和HTTP有较深刻的理解和经验，有⽹络编程经验；</li><li>扎实的Java语⾔基础，深⼊理解常见的数据结构及算法；</li><li>具备良好的分析与解决问题能力，能独立承担任务和有系统进度把控能⼒；</li><li>责任心强，良好的对外沟通和团队协作能力，主动，好学。</li></ol><p><strong>岗位职责</strong></p><ol><li>负责公司移动端产品在Android和web平台上的程序设计和开发；</li><li>完成功能模块开发和自测；</li><li>负责代码的维护和改进工作；</li><li>根据项目进度，按需按时完成功能开发；</li><li>学习和研究新技术以满足产品的需求，根据开发过程中的体验对产品提出改进建议。</li></ol>', '1-3年', 'e24de31af0dbf8ca0nF43Nm8F1ZV', '深圳 · 南山区 · 西丽', '8-13K·15薪', 'Java, MySQL, flutter, Android', 'Java软件工程师（有移动前端开发经验优）', 'https://www.zhipin.com/job_detail/e24de31af0dbf8ca0nF43Nm8F1ZV.html', '定期体检, 零食下午茶, 带薪年假, 节日福利, 五险一金, 员工旅游, 年终奖, 补充医疗保险');
INSERT INTO `jobs` VALUES (3, '飞豹互娱', '游戏', '100-499人', '天使轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责回合制卡牌游戏服务端功能的开发与维护，包括卡牌养成、任务、活动、商店、邮件、排行榜和奖励结算等业务系统。</li><li>参与需求分析、服务端方案设计、协议设计、数据结构设计及功能实现，完成自测、联调、测试问题修复和版本上线。</li><li>维护成熟运营项目，在保证线上稳定和数据兼容的前提下完成业务迭代、功能优化及历史问题修复。</li><li>保障玩家资产、业务状态、活动奖励和⽀付订单等关键数据的正确性，妥善处理重复请求、断线重连、跨天重置、异常重试等场景。</li><li>参与多个游戏版本的并⾏开发，负责公共功能复⽤、配置化开发以及不同版本业务逻辑的差异化实现。</li><li>配合客户端、策划、测试和运营团队完成需求确认、接口联调、版本发布及上线后的问题跟进。</li><li>负责线上问题的分析和处理，通过日志、数据库、缓存和配置定位问题，完成代码修复、影响评估及必要的数据处理。</li><li>参与腾讯及海外版本的登录、支付、防沉迷、时区及其他平台接口开发和维护。</li><li>遵守团队代码规范，编写必要的接口和开发⽂档，参与代码评审，持续提高代码质量和项目维护效率。</li><li>熟悉项目后，能够独立负责业务模块从需求分析、开发、自测、联调、上线到线上维护的完整闭环。</li></ol><p><strong>岗位要求</strong></p><ol><li>具有 1–3 年服务端开发经验，有完整功能开发、联调、测试、上线或线上维护经历。</li><li>有实际业务系统开发经验，能够独立完成普通功能从需求理解、代码开发、自测、联调到问题修复的基本流程。</li><li>有数据库、缓存、网络通信、配置读取和日志排查等实际使用经验。</li><li>有线上项目维护经验者优先，包括线上问题定位、数据异常分析、版本发布、配置更新、玩家数据处理或事故复盘等。</li><li>有游戏服务端开发经验者优先，特别是卡牌、RPG、SLG、放置、回合制或其他长线运营游戏项目。</li><li>有多版本、多渠道、换皮项目或长期运营项目开发经验者优先。</li><li>能够对自己负责的工作跟进到底，不把“代码写完”当作任务完成。能够主动完成自测、联调、问题修复、上线确认和上线后的结果验证，线上稳定优先8．熟练掌握java服务端开发语言，能够使用项目实际采用的语言独立完成业务功能开发。</li></ol>', '1-3年', '2769eb41755a975a0nBz29W-EVFQ', '深圳 · 龙岗区 · 坂田', '13-20K·13薪', 'Java, 团队管理经验, 不接受居家办公, MySQL, Netty, Redis, 游戏后端经验', '游戏服务器开发工程师', 'https://www.zhipin.com/job_detail/2769eb41755a975a0nBz29W-EVFQ.html', '交通补助, 员工旅游, 团建聚餐, 餐补, 零食下午茶, 五险一金, 定期体检, 绩效奖金, 年终奖, 带薪年假, 节日福利');
INSERT INTO `jobs` VALUES (4, '秋日', '电子商务', '20-99人', '', '本科', '<p><strong>岗位职责</strong></p><ol><li>参与项目需求分析与讨论，理解功能需求，设计系统架构，确保技术实现方案合理可行。</li><li>负责后台服务开发，主导或参与Java后台服务的开发工作，编写⾼质量的核⼼代码，确保功能按时交付。</li><li>与前端开发团队紧密配合，共同完成接口对接、功能联调，确保前后端功能⽆缝衔接。</li><li>编写符合规范的Java代码，注重代码的可读性和可维护性，同时进行代码优化，提升运行效率。</li><li>维护和优化现有系统，并对现有系统进⾏性能优化和稳定性维护，及时排查并解决技术问题，确保系统高效运行。</li><li>关注新技术动态，学习和了解Java及相关领域的最新技术动态，尤其是AI技术在开发中的应用，探索如何提升开发效率和产品质量。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历,计算机、软件工程或相关专业；</li><li>2-3 年 Java 开发经验，有电商行业、数据分析相关经验优先；</li><li>JAVA基础扎实，理解 IO、多线程、集合等基础及底层框架实现，并了解设计模式；</li><li>熟悉 Spring, Spring Boot 等主流框架；</li><li>熟悉 RESTful API 设计和实现；</li><li>熟练使用关系型数据库（如 MySQL等）和 NoSQL 数据库（如 Redis,MongoDB等）；</li><li>了解消息中间件（如 Kafka, RocketMQ, RabbitMQ）的使用。</li><li>有严密的逻辑思维能力，善于思考，具备良好的分析问题和解决问题的能力,良好的编码习惯；</li><li>有分布式系统、微服务架构相关项目经验者优先；</li><li>熟悉 Docker 和 Kubernetes 容器化技术；</li><li>具有良好的沟通能力，良好的团队合作精神，责任心强、勤奋敬业，执行力强。</li></ol>', '1-3年', 'dd4d76861572e9710nJ709W6E1BV', '深圳 · 龙岗区 · 坂田', '10-15K', 'Java, C++, Spring, MyBatis, SpringCloud, MySQL, 架构设计经验, 分布式经验, 云计算经验, 不接受居家办公', '初级java工程师', 'https://www.zhipin.com/job_detail/dd4d76861572e9710nJ709W6E1BV.html', '');
INSERT INTO `jobs` VALUES (5, '昆仲云', '互联网金融', '20-99人', '', '大专', '<p>我们需要一位技术底子扎实，具备前端、后端经验和视野的全栈工程师。你将主导公司产品在 Web 端及多端移动端程序（基于uni-app）的视觉呈现与交互逻辑实现。同时，我们希望你具备一定的后端开发能⼒（Java 尤佳，但也欢迎 Go/Python 等背景），能够独⽴完成业务闭环。核⼼</p><p><strong>职责</strong></p><p>多端开发：负责基于Vue 3的管理后台及基于uni-app的多端小程序/H5核心功能研发。前后端联调：独⽴或协同进行接口设计与数据对接，确保端到端业务逻辑的顺畅与高效。后端辅助开发：根据项目需求，参与后端业务接口的开发与维护（1-2年经验水平即可）。性能体验：负责产品的性能优化、浏览器/终端兼容性处理，提升用户极致体验。</p><p><strong>技术要求</strong></p><ol><li>后端（核心功底）Java优先：如果你熟悉Spring Boot、MyBatis等Java技术栈，我们将优先考虑。灵活背景：如果你不擅长Java，但在 Python (FastAPI/Django) 或 Go等领域有1-2年开发经验，我们也同样欢迎。通用技能：熟悉MySQL/PostgreSQL数据库，掌握基本的SQL优化；了解Redis缓存。</li><li>前端（加分项）Vue栈：精通Vue 2/3、Pinia/Vuex、Vite，有复杂组件库封装或大型单页应用开发经验。跨端能力：精通uni-app，有完整的上线经验。基础扎实：精通CSS3（Flex/Grid/动画）、TypeScript。3.</li></ol><p><strong>综合素质</strong></p><p>熟悉Git工作流，有基本的Linux命令基础。全栈思维：不设限，愿意根据业务需求学习并使用新的技术栈。有半年及以上使用AI开发工具编程的经验。</p>', '1-3年', '5d4488c085881fe60nJ52t--GFJQ', '深圳', '12-15K', 'Java, Nginx, MySQL, 云计算经验, 不接受居家办公', '初级全栈工程师', 'https://www.zhipin.com/job_detail/5d4488c085881fe60nJ52t--GFJQ.html', '团建聚餐, 绩效奖金, 带薪年假, 五险一金, 员工旅游, 全勤奖, 年终奖, 零食下午茶, 生日福利, 通讯补贴, 节日福利');
INSERT INTO `jobs` VALUES (6, '酷特宠物', '电子/硬件开发', '20-99人', '不需要融资', '大专', '<p><strong>岗位职责</strong></p><ol><li>参与宠物管理软件的设计、开发与维护工作；</li><li>负责后端服务的架构设计与性能优化，确保系统稳定性和高效性；</li><li>编写高质量的代码，进行单元测试和代码评审，保证代码质量；</li><li>与前端开发及产品经理紧密合作，确保功能准确实现；</li><li>持续关注技术发展趋势，提出创新解决方案以提升产品竞争力。</li></ol><p><strong>任职要求</strong></p><ol><li>计算机或相关专业背景，具备扎实的编程基础；</li><li>熟悉Java或Python等主流编程语言及常用开发框架；</li><li>了解数据库设计及SQL语言，具备数据库优化经验；</li><li>具有良好的问题分析和解决能力，能够快速定位并修复Bug；</li><li>强烈的责任心和团队合作精神，善于沟通，能够承受一定的工作压力。</li></ol>', '1-3年', 'c1285faecc7746b103F-39S9F1JU', '深圳 · 宝安区 · 福永', '10-12K', 'Java, 不接受居家办公, 团队管理经验, MySQL, Spring, Python', '软件工程师', 'https://www.zhipin.com/job_detail/c1285faecc7746b103F-39S9F1JU.html', '全勤奖, 节日福利, 通讯补贴, 五险, 带薪年假, 工龄奖, 零食下午茶, 员工旅游, 补充医疗保险');
INSERT INTO `jobs` VALUES (7, '云逸传媒', '广告/公关/会展', '20-99人', '未融资', '大专', '<p>薪资面议，请带纸质简历！！！</p><p><strong>主要工作职责描述</strong></p><ol><li>对接各大媒体:腾讯广点通、华为⼴告、⼩⽶营销、巨量等平台2.配置广告监测链路:搭建追踪链接、拼装clickid、各类渠道参数、落地页跳转参数;</li><li>联调转化API回传(Postback):把用户注册、付费等转化⾏为上报广告平台;</li><li>排查问题:广告后台转化数据缺失、数据对不上、归因失效、回传延迟、参数丢失;</li><li>和投放优化师配合:搭建oCPM/oCPA深度转化链路，让广告模型学习精准用户;</li><li>整理各媒体接口文档、规范回传事件(激活、表单、付费、到店等);</li><li>核对媒体后台数据和自身业务数据，处理数据差异、漏量问题。</li></ol><p><strong>任职资格</strong></p><ol><li>具有熟练制作符合标准、兼容各浏览器页面的经验；</li><li>能用JavaScript完成广告产品的各种特效，并保持页面前端性能，优秀的代码可维护性，良好的浏览器兼容性；</li><li>有解决问题、钻研新技术的兴趣和能力，有较好的沟通能力、高度的责任感、良好的团队合作精神；</li><li>对网站信息管理系统（CMS）有一定的了解与维护经验优先；</li><li>了解 Python 或者 PHP 开发优先。工作时间：9：00-12：00，13：30-18：30，双休，入职一周后购买社保。</li></ol>', '1-3年', 'c748d2dd354acabe0nJ73t29FVZS', '深圳 · 光明区 · 光明', '8-13K', 'Java, Python, SpringCloud, SQL Server, 搜索/推荐/广告经验, 分布式经验, ERP开发经验, 架构设计经验, 广告行业, CPA广告', '广告技术研发', 'https://www.zhipin.com/job_detail/c748d2dd354acabe0nJ73t29FVZS.html', '餐补, 员工旅游, 社保, 节日福利, 加班补助, 有无线网, 交通补助, 五险一金, 零食下午茶');
INSERT INTO `jobs` VALUES (8, '增量科技', '计算机软件', '0-20人', '天使轮', '本科', '<p><strong>职位亮点</strong></p><ol><li>直面最前沿的AI落地战场：你是产品、业务专家、项目经理与全栈技术的超级复合体，你从0到1搭建的解决方案，将直接沉淀为我们产品的核心模块，影响成千上万的卖家。</li><li>与顶尖团队并肩，客户即导师：与创始⼈、产品和技术核⼼团队紧密协作，深度服务⾏业头部卖家，获得一线最真实的商业洞察。【</li></ol><p><strong>岗位职责</strong></p><ol><li>解决方案设计：与客户业务团队协作，诊断核心痛点，设计基于AI的自动化工作流解决方案，并明确成功指标。</li><li>需求反哺与产品化：将客户落地中验证的通用需求、最佳实践反馈给产品与研发团队，推动核心产品的迭代升级。</li><li>成功保障：为客户提供技术培训、上线支持与持续优化，确保AI解决方案持续产生业务价值，提升客户满意度与续约率。【</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，两年以上后端或全栈开发经验，精通Java/Python/Nodejs，有扎实的系统设计和调试能力。</li><li>出色的沟通与协作能力，对解决模糊、复杂的业务问题有极高的热情和耐心。</li><li>强烈的责任心和主人翁意识，能对最终的业务结果负责。优先项（有则大加分）：</li><li>有跨境电商、供应链、SaaS企业服务等相关行业经验，熟悉ERP、OMS等系统者优先。</li><li>有AI项目落地经验，了解大模型API调用、Agent框架（如LangChain）、RAG等概念与实践。</li><li>有创业公司或从0到1项目经历，能在资源有限、方向快速变化的环境中高效工作。【公司介绍】我们是一家专注于帮助跨境卖家提升利润和效率的综合服务商。增量树团队具备跨境行业头部公司复合背景，专注于帮助跨境卖家萃取最佳实践，定制化打造AI明星员工，赋能跨境卖家实现智能化、自动化转型。</li></ol>', '1-3年', '35b97547a92ca61e0nB92t64EVRQ', '深圳 · 龙岗区 · 坂田', '15-20K', 'Java, MySQL, Spring', 'AI应用开发工程师（FDE方向）', 'https://www.zhipin.com/job_detail/35b97547a92ca61e0nB92t64EVRQ.html', '年终奖, 五险一金, 生日福利, 团建聚餐, 带薪年假, 节日福利, 零食下午茶, 员工旅游');
INSERT INTO `jobs` VALUES (9, '优钱科技', '互联网', '100-499人', '不需要融资', '本科', '<p><strong>一、岗位职责</strong></p><p>1、参与公司核心业务系统的设计、开发、测试与上线，负责后端服务的架构优化与性能提升，保障系统高可用、⾼并发运⾏；​2、主导或参与需求分析、技术⽅案评审，结合业务场景提供合理的技术实现建议，解决开发过程中的复杂技术问题；​3、编写清晰、规范的技术文档（含设计文档、接口⽂档等），参与团队技术分享与代码评审，提升团队整体开发效率与代码质量；​4、对接前端开发团队，协同完成前后端交互功能开发，优化接口设计与数据传输效率，确保用户体验流畅；​5、关注行业技术动态，引入合适的新技术、新框架应用于项目开发，持续迭代系统功能与技术架构。</p><p><strong>二、任职要求</strong></p><p>1、本科及以上学历，计算机相关专业（如计算机科学与技术、软件工程等），2-5 年 Java 后端开发经验，有完整项目从开发到上线的全流程经验；​2、精通 Java 基础语法，熟练掌握 Spring Boot、Spring Cloud、MyBatis 等主流开发框架，理解微服务架构设计思想与实践方案；​3、熟悉 MySQL、Redis 等数据库 / 缓存技术，具备数据库索引优化、SQL 调优能力，了解分布式事务、分布式锁等解决方案；​4、掌握 RESTful API 设计规范，具备前后端分离项目开发经验，能独立完成接口设计与联调；​5、优先条件：具备前端开发技能，熟练使用 Vue、React、JavaScript、HTML/CSS 等技术，能独立完成简单前端页面开发与交互逻辑实现；​熟悉 Git 版本控制工具，具备良好的代码习惯与团队协作意识，能快速适应业务变化，抗压能力强；​6、具备问题排查、性能调优经验，了解消息队列（如 RabbitMQ、Kafka）、容器化技术（Docker、K8s）者优先。</p>', '1-3年', '308b2dab365c03760nF529m0FVtT', '深圳 · 南山区 · 前海', '10-15K', 'Java, SpringCloud, MySQL', 'Java开发工程师', 'https://www.zhipin.com/job_detail/308b2dab365c03760nF529m0FVtT.html', '生日福利, 工龄奖, 带薪年假, 绩效奖金, 员工旅游, 股票期权, 团建聚餐, 年终奖, 节日福利, 节假日加班费, 加班补助, 法定节假日三薪, 五险一金, 零食下午茶');
INSERT INTO `jobs` VALUES (10, '某中型电子/半导体/集成电路公司', '电子/半导体/集成电路', '100-499人', '', '本科', '<p><strong>岗位职责</strong></p><p>JAVA开发：\"参与或负责HR/办公/行政领域/IOC IT建设，包括客户需求到软件产品定义、架构设计、开发实现、测试验证、维护运营全生命周期活动。分析并解决开发及生产环境中的技术问题，持续优化系统性能和稳定性\"</p>', '1-3年', '8792fd41ac0f25f60nFz39i5GFRY', '深圳', '15-25K·13薪', '', 'java', 'https://www.zhipin.com/job_detail/8792fd41ac0f25f60nFz39i5GFRY.html', '');
INSERT INTO `jobs` VALUES (11, '华氏实业', '电子商务', '100-499人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>根据公司业务需求选择合适的大模boss型，开发对应的Skill技能包；跨境电商业务场景落地：深入挖掘跨境电商核心业务模块（如选品、Listing优化、多语种客服、广告营销、供应链管理等），将业务痛点转化为AI⾃动化解决⽅案，推动AI⼯具在实际业务中的集成与落地；</li><li>工作流与Agent架构设计：基于飞书等协同平台，设计并搭建跨部门的AI自动化⼯作流（Workflow）；参与构建企业级AI Agent，实现多智能体协同，打通ERP、WMS等业务系统的数据链路；</li><li>私有知识库与RAG建设：搭建并维护公司私有化知识库，运用RAG（检索增强生成）技术，实现跨境平台规则、历史运营数据、产品文档的结构化存储与精准智能检索；</li><li>模型评估与效果调优：持续跟踪多模态大模型及AI前沿技术，对模型输出结果进行业务侧的评估与测试；通过优化Prompt、微调（SFT）等手段，不断提升AI在特定场景下的准确率和响应效率；</li><li>内部AI赋能与推广：作为公司的AI“布道者”，制定内部AI应用推广计划；为业务团队提供AI工具培训、技术支持与答疑，沉淀AI应用最佳实践与SOP，提升全员数字化素养。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机、软件、数据相关专业优先；</li><li>熟练使用Python、Java、C#任一语言，能够独立完成API对接、脚本开发和数据处理；</li><li>具备飞书开放平台开发经验和企业级工作流设计的优先；</li><li>了解LLM基本原理和Prompt、Skill技能开发；</li><li>了解市面上的多模态大模型，并有实际的API调用、接入或微调经验，熟悉LangChain、AutoGPT等主流AI应用开发框架者优先；</li><li>行业认知：深度了解跨境电商业务流程（如Amazon、TikTok、独立站等平台运营规则），有跨境电商AI应用落地经验者优先；</li><li>技术栈扩展：熟悉RAG（检索增强生成）原理，有企业私有知识库搭建、多智能体（Multi-Agent）协同系统开发经验者优先；8.</li></ol><p><strong>综合素质</strong></p><p>具备极强的跨部门沟通协作能力与业务敏感度，能够“听得懂业务需求，落得下技术方案”；拥有持续学习的热情，能快速跟进AI前沿技术并转化为业务生产力。</p><p><strong>薪资福利</strong></p><ol><li>工作时间：双休，8：30～12:10 14：00～18：10 节假日按照国家法走2.薪酬架构：底薪8000-12000，入职即交五险一金，薪资结构为基本工资+提成+丰厚年终奖，提供行业极具竞争力薪资。</li><li>生日</li></ol><p><strong>福利</strong></p><p>每位公司小伙伴生日当天会收到人资为你精心准备的SURPRISE，并且公司小伙伴的父母生日也会收到公司的祝福还有礼品哦，中秋节、端午节公司定制礼品，</p><p><strong>福利</strong></p><ol><li>工作氛围：团队成员以90后为主，年轻有活力，上班期间可自由播放音乐，提供丰富美味下午茶（蛋糕、水果、零食）,每月各部门一次聚餐，力造一个轻松愉快的工作环境，在愉快中高效工作。</li><li>旅游团建：公司安排每年1-2次国内外旅游团建，目前已去过去过惠州、东莞、厦门游，优秀员工安排一年一次国外游，快来和我们一起玩转地球吧！</li></ol>', '1-3年', '22201fa46af07a0a0nF929y9FFtX', '深圳 · 宝安区 · 沙井', '8-12K·13薪', 'Java, C#, Python', 'AI应用开发工程师', 'https://www.zhipin.com/job_detail/22201fa46af07a0a0nF929y9FFtX.html', '底薪加提成, 五险一金, 工龄奖, 绩效奖金, 包吃, 生日福利, 员工旅游, 节日福利, 餐补, 零食下午茶, 包住, 团建聚餐, 保底工资, 定期体检, 宿舍有空调, 带薪年假, 有无线网, 年终奖');
INSERT INTO `jobs` VALUES (12, '鸿湾软件', '计算机软件', '20-99人', '未融资', '本科', '<p><strong>职位描述</strong></p><p>Java\n数据库\n系统架构\n独立开发能力，分析能力\n陆代春\n在线\n鸿湾软件\n·\n招聘者\n竞争力分析\n查看完整个人竞争力\n个人综合排名：在人中排名第\n你在？位置\n一般 良好 优秀 极好\nBOSS 安全提示\n严禁用人单位和招聘者用户做出任何损害求职者合法权益的违法违规行为，包括但不限于扣押求职者证件、收取求职者财物、向求职者集资、让求职者入股、诱导求职者异地入职、异地参加培训、违法违规使用求职者简历等，您一旦发现此类行为， 请立即举报\n公司介绍\n公司简介\n深圳市鸿湾软件科技有限公司成立于2005年，主营行政事业单位内部控制管理系统，政府财务软件、固定资产等管理软件的开发和服务。\n工商信息\n公司名称\n深圳市鸿湾软件科技有限公司\n法定代表人\n陆代春\n成立日期\n2005-08-15\n企业类型\n有限责任公司\n经营状态\n存续\n注册资金\n100万人民币\n查看全部\n工作地址\n深圳福田区锦文阁大厦1203\n点击查看地图\n更多职位\n看过该职位的人还看了\nJava开发工程师（珠海项目，线上面试）\n10-14K\n长亮科技\n深圳\njava开发工程师\n10-15K\n软通动力\n深圳\njava开发工程师\n10-15K\n中航信息\n深圳\n中级JAVA开发工程师\n10-15K\n超光速国际物流\n深圳\nJava\n10-15K\n峰峻智能\n深圳\n金融项目Java开发\n11-16K\n中电金信\n深圳\n精选职位\nJava/Python开发工程师（AI方向）\n10-15K\n云仓库\n深圳\njava开发工程师\n11-16K·13薪\n汇合发展\n深圳\nJava开发运维工程师（DevSecOps 方向）\n11-18K\n四方精创\n深圳\nJava\n10-11K\n上海恒格信息\n深圳\nJAVA开发工程师（驻场某券商）\n11-14K\n新华三技术有限公司\n深圳\n中级java开发工程师\n10-15K\n智慧林网络\n深圳\n深圳\n搜索\n城市招聘 热门职位 推荐公司 热门企业\n东方招聘\n连云港招聘\n黄石招聘\n咸宁招聘\n宿州招聘\n阳江招聘\n固原招聘\n通化招聘\n贵港招聘\n铜川招聘\n首页深圳招聘·Java招聘深圳Java招聘鸿湾软件Java招聘\n页面更新时间：2026-08-05\n企业服务热线和算法/未成年人等举报渠道 400 065 5799\n老年人直连热线400 661 6030\n工作日 8:00 - 22:00\n休息日 8:00 - 22:00\n企业服务\n职位搜索\nAPP\n投资者关系 Investor Relations\n直品公益基金会\n求职技巧\n使用与帮助\n协议与规则\n隐私政策\n防骗指南\n使用帮助\n联系\n北京华品博睿网络技术有限公司\n公司地址 北京市朝阳区太阳宫中路16号院1号楼18层1801内09\n违法和不良信息举报邮箱/未成年人举报渠道 jubao@.com\nCopyright © 2026 京ICP备14013441号-5京ICP证150923号 电子营业执照 京公网安备11010502032801 朝阳网警 人力资源服务许可证 网上有害信息举报专区 朝阳区人社局监督电话 算法备案信息</p>', '1-3年', 'd7f874e36b45b15503Fy3t2_Fls~', '深圳 · 福田区 · 景田', '10-15K', 'Java, 数据库, 系统架构', 'Java', 'https://www.zhipin.com/job_detail/d7f874e36b45b15503Fy3t2_Fls~.html', '五险一金');
INSERT INTO `jobs` VALUES (13, '中诺思', '人工智能', '100-499人', '不需要融资', '本科', '<p><strong>工作职责</strong></p><ol><li>负责软件系统代码的实现，编写代码和开发文档，分析并解决软件开发过程中的问题；</li><li>能运用AI coding辅助编程工具提升编码效率，并对AI⽣成的代码进⾏审查与优化，确保代码质量与安全性；</li><li>负责与硬件（如RF⼿持、智能货架、AGV、立库、机械臂、机器人等）的业务系统集成；</li><li>负责完成软件模块的编码实现、集成测试；5 完成领导安排的其他⼯作任务。</li></ol><p><strong>任职资格</strong></p><ol><li>计算机、软件工程、物联网、自动化等相关专业，本科及以上学历，2年或以上Java Web、Python开发经验；</li><li>熟练使用常见Java框架，如：Spring、Spring Boot、Spring MVC、MyBatis等开源框架；</li><li>熟悉Python编程，有后端开发经验，能使用Flask或FastAPI框架进行开发，具备数据处理能力；</li><li>有Claude Code、GitHub Copilot、Cursor等AI辅助编程工具的实际使用经验，能将AI工具融入日常开发流程，具备基本的Prompt Engineering能力；</li><li>熟悉MySQL、PostgreSQL等数据库及Linux操作系统，具备一定的数据库性能优化经验；</li><li>熟悉Docker等容器化部署工具7. 工作认真，有耐心，具有良好的团队合作精神及沟通能力，学习能力强，工作效率高；</li><li>能适应适量出差</li></ol>', '1-3年', '5bbb20819b9f49de0nFz3t-1GVNT', '深圳 · 南山区 · 西丽', '10-12K', 'Java, 大数据经验, 不接受居家办公, MySQL, Spring', '后端开发工程师(AI+机器人领域)', 'https://www.zhipin.com/job_detail/5bbb20819b9f49de0nFz3t-1GVNT.html', '节日福利, 生日福利, 工龄奖, 交通补助, 团建聚餐, 餐补, 五险一金, 绩效奖金, 底薪加提成, 员工旅游, 年终奖, 零食下午茶, 带薪年假');
INSERT INTO `jobs` VALUES (14, '深圳中充服数字科技', '物联网', '0-20人', '', '本科', '<p>教育程度 本科及以上学历专业类别 计算机、软件工程等相关专业知识要求1、精通Java核心技术体系，掌握SpringBoot/Cloud、MyBatis等主流框架原理，熟悉分布式系统、微服务架构设计知识2、具备数据库设计与优化知识，熟悉MySQL等关系型数据库及Redis等中间件，了解数据存储、缓存、事务等核心机制经历与经验1、2年以上Java后端开发经验，参与过完整的项目研发周期，独⽴负责过核⼼业务模块开发2、分布式平台产品、SaaS系统开发经验，有⾼并发、高可用场景下的项⽬落地案例技能要求1、精通Java基础及并发编程，熟练使用SpringCloud、SpringBoot框架开发微服务应用2、熟悉MySQL数据库优化、Redis缓存设计，能独立完成数据层方案的落地与调优3、掌握Kafka/RabbitMQ等MQ中间件，实现分布式系统间的异步通信与解耦4、了解Netty框架核心原理，能参与物联网设备的高并发数据接入与报文处理5、熟练使用Git、Maven等工具，遵循编码规范，具备良好的代码评审与协同开发能力6、具备排查系统性能问题的能力，能通过日志分析、压测工具定位并解决技术卡点特殊才能要求1、较强的逻辑思维与问题拆解能力，能应对复杂业务场景的技术实现挑战2、主动跟进Java技术生态趋势，有技术创新与方案优化的意识和落地能力3、良好的沟通协作与文档编写能力，能清晰沉淀技术方案与开发经验4、抗压能力强，可适应多任务并行与紧急需求响应，保障研发进度与质量5、对海外平台、共享服务、互联网等行业业务有经验，能快速理解业务逻辑并转化为技术方案</p>', '1-3年', '254f29d834ab9f500nJ40t67FlVS', '深圳', '15-20K', 'Java, Spring, SpringCloud, MySQL, 物联网经验', 'java后端开发工程师', 'https://www.zhipin.com/job_detail/254f29d834ab9f500nJ40t67FlVS.html', '');
INSERT INTO `jobs` VALUES (15, '零与壹软件', '计算机软件', '20-99人', '未融资', '大专', '<p><strong>岗位职责</strong></p><ol><li>负责公司AI产品项目开发与维护；</li><li>基于Java 框架的代码编写与整合，实现满足设计规范的软件；</li><li>负责公司产品的功能规划、需求分析设计、技术实现和用户体验；</li><li>负责所属模块的代码开发、调试与维护工作；</li><li>解决开发过程中遇到的业务、技术⽅⾯问题，寻找可⾏的改进方案并推行。</li></ol><p><strong>任职要求</strong></p><ol><li>计算机或相关专业⼤专及以上学历；</li><li>有Java开发经验，熟悉主流Java框架（Spring Boot、Spring Cloud、MyBatis）；</li><li>精通 Java 8+，熟悉新特性，深入理解JVM原理，掌握多线程编程；</li><li>熟练使用MySQL，熟悉Redis，熟悉 Spring Cloud 生态；</li><li>有AI项目经验的优先考虑。</li></ol>', '1-3年', 'cb41e6fc7148eb0103N-09i6EFdQ', '深圳 · 南山区 · 科技园', '8-13K', 'Java, MySQL, Redis, Spring', 'java开发工程师', 'https://www.zhipin.com/job_detail/cb41e6fc7148eb0103N-09i6EFdQ.html', '生日福利, 节日福利, 五险一金, 带薪年假, 员工旅游, 餐补, 年终奖, 零食下午茶, 团建聚餐');
INSERT INTO `jobs` VALUES (16, '仟川网络科技有限公司', '互联网金融', '20-99人', '不需要融资', '本科', '<p>【岗位介绍】如果你想摆脱重复业务开发、深耕技术、积累核心项目经验，这个岗位非常适合你！我们团队专注后端研发，项目体量稳定，愿意培养每⼀位想成长的技术⼈员。现招聘 2-3 年经验 Java 开发⼯程师，在这里你可以参与架构设计、核心功能研发，结合 AI ⼯具优化工作流程，全方位提升综合技术实力。【</p><p><strong>岗位职责</strong></p><ol><li>参与需求分析和技术方案设计，完成高质量代码编写和单元测试。</li><li>解决项目中的技术难题，持续优化系统性能和用户体验。</li><li>配合团队完成模块集成与协作开发，保障项目进度与交付质量。 【</li></ol><p><strong>任职要求</strong></p><ol><li>熟悉主流开发框架及常用中间件的技术原理与应用场景。</li><li>有良好的编码习惯，能够编写清晰、可维护的代码。</li><li>具备较强的问题分析与解决能力，能独立承担开发任务。</li><li>具备团队协作意识，能够高效沟通并推动项目顺利进行。</li><li>熟悉使用AI提升工作效率【岗位优势】1.核心业务项目，技术场景丰富，个人成长空间大；</li><li>团队技术氛围浓厚，定期组织技术研讨，共享学习资源；</li><li>扁平化管理，流程简单，专注技术研发，无繁杂内耗；</li><li>支持 AI 赋能开发，紧跟行业主流工作方式。</li></ol>', '1-3年', 'f4970e45ec04bcf90nB70tu6F1BV', '深圳 · 福田区 · 车公庙', '10-12K', 'Java, Spring, SpringCloud, MyBatis, Nginx, JVM, MySQL, Redis, 核心项目, 技术成长, 五险一金', 'java开发工程师', 'https://www.zhipin.com/job_detail/f4970e45ec04bcf90nB70tu6F1BV.html', '五险一金, 餐补, 带薪年假, 绩效奖金, 全勤奖, 年终奖, 节日福利');
INSERT INTO `jobs` VALUES (17, '深圳云星眸技术', '互联网', '20-99人', '不需要融资', '本科', '<p>boss后端开发工程师（Java / Go 均boss可） 工作地点：深圳薪资：10K–15K/月作息：双休，不卷无偿加班，法定节假⽇正常休学历：全⽇制本科及以上 30岁以下项⽬背景：社交App生态 + AI智能硬件联动业务</p><p><strong>岗位职责</strong></p><ol><li>负责公司核心社交App后端服务全栈开发与迭代，⽀撑用户体系、好友关系、社群互动、动态广场、私信IM聊天全套核心社交业务接口开发。</li><li>负责后端与AI大模型能力接口深度对接、调度封装、异步队列处理，承接App内全部AI问答、AI互动、AI推荐相关业务后台服务。</li><li>负责轻量智能硬件设备数据通信、用户设备绑定、云端数据同步、设备权限管理等后端逻辑开发，纯接口层面对接，不用懂硬件底层。</li><li>独立设计数据库表结构、业务微服务拆分、接口规范定义，保障社交App高并发、高可用、消息不丢失、互动不卡顿。</li><li>负责后端性能压测、接口优化、慢查询优化、服务器资源调优，保障高峰期用户在线稳定不掉线。</li><li>配合前端、算法、产品全团队联调，输出稳定、安全、可扩展的后端能力，保障版本按期上线。</li><li>做好日志监控、线上问题排查、安全漏洞修复，保障用户数据隐私与账号安全合规。</li></ol><p><strong>任职要求</strong></p><ol><li>全日制本科及以上学历，计算机、软件工程、大数据等相关专业，计算机基础扎实。</li><li>1年以上互联网社交App、C端用户产品后端实战开发经验，有线上高并发项目经验优先。</li><li>主力熟练 Java 或 Go 任意一门语言，深耕后端业务开发，代码规范，架构思维清晰。</li><li>熟悉常用微服务架构、分布式事务、高并发处理、限流熔断、消息队列实战落地。</li><li>熟练MySQL索引优化、分库分表、Redis缓存全套实操，会排查线上慢接口、性能瓶颈。</li><li>对接过AI接口、第三方消息推送、实时聊天服务后端开发者优先。</li><li>逻辑强、沟通顺畅、干活踏实，能快速融入团队推进项目上线。 必备技术栈（二选一即可） 会Java就用这套 - Java、SpringBoot、SpringCloud、微服务- MySQL、Redis、RabbitMQ / Kafka- 接口开发、鉴权、社交关系链设计- Linux、Git、Docker基础部署 会Go就用这套 - Golang、Gin / Zero 框架- 高性能接口开发、长连接、消息推送- MySQL、Redis、消息队列- 轻量高并发服务搭建、接口快速迭代 加分项（优先面试、优先定高薪） 1. 做过社交APP、同城社交、兴趣社交、即时聊天后端真实项目。</li><li>有对接过大模型API、AI对话后台服务开发经验。</li><li>做过智能硬件、物联网设备云端后台对接经验。</li><li>熟悉高并发用户场景，能独立扛压做服务扩容优化。 我们</li></ol><p><strong>福利</strong></p><p>- 标准双休，团队年轻化，办公简单轻松不内耗- 全额五险一金 + 项目奖金 + 绩效激励- 核心社交+AI项目从0搭建，履历直接升值- 扁平化管理，技术说了算，不搞复杂流程</p>', '1-3年', '14c60ca9040636970nd409i_GFNZ', '深圳 · 福田区 · 车公庙', '10-15K', 'Java, Golang, SpringCloud, MySQL', '后端开发工程师（Java/Go均可）', 'https://www.zhipin.com/job_detail/14c60ca9040636970nd409i_GFNZ.html', '零食下午茶, 五险一金, 绩效奖金, 底薪加提成, 年终奖, 餐补, 保底工资, 团建聚餐');
INSERT INTO `jobs` VALUES (18, '深圳市品创互联科技', '互联网', '20-99人', '不需要融资', '本科', '<p><strong>工作职责</strong></p><ol><li>负责公司服务端应用的设计、开发与维护，保证系统的高可用性与高性能；</li><li>参与系统架构设计和优化，提升系统的扩展性和可维护性；</li><li>编写高质量的代码，并进行单元测试与性能调优；</li><li>使用Python进行自动化工具开发、数据处理与分析；</li><li>协作团队成员，确保项目进度与质量；</li><li>根据业务需求，编写和维护相关文档。</li></ol><p><strong>职位要求</strong></p><ol><li>本科及以上学历，计算机相关专业；</li><li>1年以上Java开发经验，熟悉Java语言、SpringBoot等常用框架；</li><li>熟悉MySQL、Redis等常用数据库与缓存技术；</li><li>掌握Python语言，具备一定的数据处理、自动化脚本开发能力者优先；</li><li>有意向从事大数据分析者优先；</li><li>具有良好的代码习惯，能撰写高质量、可维护的代码；</li><li>具有良好的团队合作精神与沟通能力，能主动解决问题。</li></ol><p><strong>福利</strong></p><ul><li>氛围积极、活跃、成长、收获，每天都是晴天；</li><li>不定期聚餐、每周团建运动，快乐享不停；</li><li>各种节日礼品祝福礼金，满满都是爱；</li><li>无限量零食供应，不定时下午茶，生活充满美滋味；</li><li>团建、年会出游，世界那么美，一起去看看！~</li></ul>', '1-3年', 'b4dd35cbc74a5a6203d62NS9F1ZQ', '深圳 · 南山区 · 大学城', '9-14K', 'Java, Python, Spring, 不接受居家办公, MySQL, Redis, 大数据经验, 服务端开发, 中台', '服务端开发工程师', 'https://www.zhipin.com/job_detail/b4dd35cbc74a5a6203d62NS9F1ZQ.html', '年终奖, 带薪病假, 扁平化管理, 定期体检, 节日福利, 员工旅游, 交通补助, 加班补助, 零食下午茶, 团建聚餐, 带薪年假, 工龄奖, 每周运动福利, 超强年终大奖, 五险一金, 补充医疗保险');
INSERT INTO `jobs` VALUES (19, '雨阳电子技术', '计算机服务', '20-99人', '未融资', '本科', '<p></p><p><strong>岗位职责</strong></p><ol><li>plm项目功能开发，按照详细设计文档要求进行功能开发，满足客户使⽤需求。</li><li>负责开发、测试、优化和维护平台应⽤程序。</li><li>负责编写代码、测试⽤例、文档等相关工作。</li><li>跟踪并解决软件应⽤程序中的问题。Ø</li></ol><p><strong>任职要求</strong></p><ol><li>计算机或相关专业的专科及以上学历，或同等学历背景。</li><li>熟悉西门子TC平台/AWC端的相关技术和应用场景，具备1年以上的TC平台/AWC端软件开发经验，熟练掌握Java、C++等编程语言。</li><li>熟悉Web开发技术，熟悉Web前端技术，如HTML5、CSS、JavaScript、jQuery等，熟悉Web服务端技术，如J2EE、Tomcat等。</li><li>具备良好的沟通和团队协作能力，能够与客户和团队成员进行有效的沟通和协作。</li><li>具备较强的问题分析和解决能力，能够快速定位和解决软件开发中的问题。</li><li>能完成Teamcenter AWC 二次开发优先。</li></ol>', '1-3年', 'f306ea05a54071d10nR93tS0GFdQ', '深圳 · 南山区 · 科技园', '11-22K', 'MES开发经验, Java, 不接受居家办公, C++, TC开发, web开发', 'Teamcenter开发顾问', 'https://www.zhipin.com/job_detail/f306ea05a54071d10nR93tS0GFdQ.html', '');
INSERT INTO `jobs` VALUES (20, '数鑫科技', '计算机软件', '20-99人', 'A轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>在高级工程师的带领下，参与软件模块层面的设计工作、以及设计文档输出工作；</li><li>参与软件模块内部的结构设计；</li><li>负责软件模块的代码编写、单元测试工作，确保代码与架构设计、软件模块规格的一致性，确保代码质量；</li><li>参与核心框架、核心组件的技术积累工作；</li><li>参与对服务端工程师之间的交叉代码REVIEW；</li><li>负责现网问题的定位和解决；</li></ol><p><strong>岗位要求</strong></p><ol><li>良好的团队沟通协作能力；</li><li>有互联网＋或者移动互联网平台的项目开发经验；</li><li>熟悉面向对象程序设计，熟悉各种主流的设计模式；</li><li>熟悉微服务架构技术，精通SpringBoot、SpringCloud等技术框架的编程；</li><li>熟悉nginx的部署和配置；</li><li>熟悉Lua、OpenResty的编程；</li><li>熟悉Redis集群、ElastichSearch集群的部署和编程；</li><li>熟悉MySQL集群的部署、以及MySQL编程；</li><li>熟悉Linux环境；熟悉SVN、GIT、禅道等工具的部署和使用；</li><li>了解OpenAPI规范体系，熟悉RESTFull规范体系；熟悉Swagger技术体系；</li><li>熟悉docker、K8S者优先；</li></ol><p><strong>岗位职责</strong></p><ol><li>在高级工程师的带领下，参与软件模块层面的设计工作、以及设计文档输出工作；</li><li>参与软件模块内部的结构设计；</li><li>负责软件模块的代码编写、单元测试工作，确保代码与架构设计、软件模块规格的一致性，确保代码质量；</li><li>参与核心框架、核心组件的技术积累工作；</li><li>参与对服务端工程师之间的交叉代码REVIEW；</li><li>负责现网问题的定位和解决；</li></ol><p><strong>岗位要求</strong></p><ol><li>良好的团队沟通协作能力；</li><li>有互联网＋或者移动互联网平台的项目开发经验；</li><li>熟悉面向对象程序设计，熟悉各种主流的设计模式；</li><li>熟悉微服务架构技术，精通SpringBoot、SpringCloud等技术框架的编程；</li><li>熟悉nginx的部署和配置；</li><li>熟悉Lua、OpenResty的编程；</li><li>熟悉Redis集群、ElastichSearch集群的部署和编程；</li><li>熟悉MySQL集群的部署、以及MySQL编程；</li><li>熟悉Linux环境；熟悉SVN、GIT、禅道等工具的部署和使用；</li><li>了解OpenAPI规范体系，熟悉RESTFull规范体系；熟悉Swagger技术体系；</li><li>熟悉docker、K8S者优先；</li></ol>', '1-3年', '2f34e9f1c90a244103Z92dy9GVBY', '深圳 · 南山区 · 蛇口', '13-20K', 'Java, Nginx, Kafka, Redis, Spring', '服务端工程师', 'https://www.zhipin.com/job_detail/2f34e9f1c90a244103Z92dy9GVBY.html', '股票期权, 生日福利, 团建聚餐, 零食下午茶, 员工旅游, 带薪年假, 节日福利, 五险一金');
INSERT INTO `jobs` VALUES (21, '金源码', '计算机软件', '20-99人', '不需要融资', '大专', '<p><strong>一、岗位职责</strong></p><ol><li>根据详细需求进行金蝶AI星空产品（旗舰版/星瀚）二次开发、代码调试、系统测试⼯作2. 能够完成业务系统之间接口开发⼯作3. 保证代码的⾼质量、稳定性与高性能4. 项目内技术难点的攻克5. 编写有关开发计划、技术⽅案、系统文档、测试文档二、能力要求：</li><li>熟悉金蝶苍穹开发，有实际金蝶苍穹项目开发经验，具备初级/中级证书2. 具备金蝶AI星空产品的生产制造、供应链、存货成本、财务领域基本知识3. 有Spring、Mybatis、SpringBoot、SpringCloud等框架的相关开发经验4. 熟练使用PostgreSQL、MySQL、Oracle等数据库，具备sql优化经验，熟悉Redis使用5. 熟练使用消息队列，主要是RocketMQ6. 扎实的java语言功底，熟悉常用的一些设计模式和算法，有利用主流AI工具编写代码及相关文档的实际经验。</li><li>较强的学习意识和快速学习能力，能编写相关的设计文档、开发文档，具备良好的代码开发规范，8. 清晰的表达能力和流畅的沟通能力，有良好的客户服务精神及团队合作能力9. 行业要求：3C电子行业、跨境电商行业、研发制造行业、新能源行业（熟悉至少2个以上行业）</li></ol><p><strong>三、福利待遇</strong></p><ol><li>月薪、补贴、项目奖、年终奖，应有尽有；</li><li>实行弹性工作制，每天工作8小时；</li><li>按政府规定购买社会保险；</li><li>有带薪年假，并随工龄不断增加；</li><li>公司每年一次全员体检，帮助员工做好健康管理。</li></ol>', '1-3年', '3e584f1cdf8219be0nZ83967EFpR', '深圳 · 宝安区 · 西乡', '12-18K', 'Java, 不接受居家办公, 分布式经验, 微服务经验, PostgreSQL, SpringCloud, MySQL, MyBatis, SQL Server, Spring, Oracle, ERP开发经验', '金蝶AI星空/苍穹平台开发工程师', 'https://www.zhipin.com/job_detail/3e584f1cdf8219be0nZ83967EFpR.html', '五险一金, 带薪年假, 员工旅游, 节日福利, 项目提成, 加班补助, 交通补助, 年终奖, 定期体检');
INSERT INTO `jobs` VALUES (22, '天磊卫士', '信息安全', '20-99人', '未融资', '本科', '<p>我们正在组建一支专注于大模型与智能体安全的核心研发团队，致⼒于打造业界领先的AI安全产品体系。你将深度参与从安全风险研究、技术攻关到产品落地的全流程，负责构建⼤模型训练/推理安全防护、智能体全⽣命周期安全管控、生成式内容安全治理等核心产品模块，为企业级客户提供可靠的AI安全解决⽅案，守护人工智能技术的安全应用边界。注：不同职级要求差异及薪资待遇如下，只要您有AI智能体相关开发经历，不同经验程度的均可接受，欢迎咨询和投递！初级工程师（1-3 年）（10k-20k）协助完成智能体安全 / 大模型安全模块开发，按方案实现指定功能复现常见 AI 安全漏洞与攻击场景，完成基础验证与测试编写规范的技术文档、接口说明及单元测试，保障代码质量中级工程师（3-5 年）（15k-25k）独立负责安全沙箱、权限管控、输入输出过滤等子系统设计与研发自主研究新型攻击手段，输出可落地的防护策略与实现方案指导初级工程师开发，参与方案评审与代码质量把控高级工程师（5 年 +）（20k-30k）主导智能体安全体系/大模型安全产品架构设计与技术选型攻坚关键技术难题，推动安全能力创新与性能优化结合行业合规与需求，规划产品路线与技术方向统筹跨团队协作与项目推进，保障复杂安全产品落地【</p><p><strong>岗位职责</strong></p><ol><li>大模型安全产品研发：负责LLM安全体系设计与实现，包括输入输出安全过滤、对抗攻击防护、数据投毒检测、模型水印溯源、隐私计算集成、越狱 / 提示注入防御。</li><li>安全平台与产品交付：构建AI安全运营平台，提供风险监控、告警响应、合规报表、自动化测试；优化性能与体验，确保安全能力无感知嵌入 AI 系统。</li><li>前沿研究与合规落地：研究 AI 安全前沿与漏洞挖掘，落地对齐、差分隐私、联邦学习等技术；将法规合规转化为产品能力，输出解决方案与技术文档。【</li></ol><p><strong>任职要求</strong></p><ol><li>熟悉LLM与智能体基本原理，具备安全产品设计与落地能力。</li><li>优先：有 LangChain/AutoGPT 等 Agent 开发/安全经验；大模型安全、安全产品（WAF/IDS/ 数据安全）研发经验；漏洞挖掘、云原生安全经验。</li><li>加分：在顶会（如S&P、USENIX Security、CCS、NDSS、ICML、NeurIPS）发表过AI安全相关论文、AI安全项目开源贡献、安全合规经验、掌握 Go/Rust/C++、大型企业安全建设服务经验。【相关介绍】 1.薪资待遇：10k-30k（视您的经验能力、面试情况而定），发薪日10号 。2.</li></ol><p><strong>福利待遇</strong></p><ol><li>公司业务：主营信息安全服务、信息安全产品、等保一站式服务等，长期深耕于网络AI安全领域，业务聚焦AI数字内容伪造检测、多模态内容安全及AI大模型安全赛道，为政府机构、金融、交通、教育、医疗等多行业客户，提供全栈式网络安全解决方案。在北京、上海、深圳、海南、贵州、汕尾均设有公司和分公司。</li><li>官网网址：https://www.uguardsec.com（可详细了解我们），官方公众号：天磊卫士/天磊卫士官方 6办公地点：海口龙华区通信广场西附5楼整层-天磊卫士 （到通信广场后，请从万和证券入口进来，上电梯3楼，出电梯后右转再上半层楼梯即可）。</li></ol>', '1-3年', '0185fe031549f7770nV_3968EldQ', '深圳 · 光明区 · 光明', '15-30K', 'C++, Golang, Python, Spring, SpringCloud, Elasticsearch, Redis, 云计算经验, 不接受居家办公, Golang, Elasticsearch, MySQL, 安全防护, 智能体安全', 'ai开发工程师', 'https://www.zhipin.com/job_detail/0185fe031549f7770nV_3968EldQ.html', '生日福利, 工龄奖, 加班补助, 零食下午茶, 年终奖, 五险一金');
INSERT INTO `jobs` VALUES (23, '深圳尚麻时代电子商务', '电子商务', '20-99人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>基于公司的发展业务，负责公司内部ERP系统的框架设计、开发与迭代优化，聚焦采购单管理、核价、跟单/采购，供应链监管、各项目状态同步等全生命周期管理；</li><li>独⽴完成ERP软件开发全流程⼯作，包括但不限于负责业务部门的需求调研、需求分析、代码编写、测试部署，制定有效的系统稳定性解决⽅案和迭代计划，并推动落地；</li><li>根据业务部门的需求进行分析整理，提出产品解决方案，编写产品操作⼿册，并为业务部门提供相关的文档和培训；</li><li>对产品的使用场景流程、业务实体、界面原型进行设计，输出需求设计文档，持续优化系统性能，提升ERP系统在跨境业务场景的适配性；</li><li>制定和执行公司的数据安全和备份策略，并对突发的IT事件制定应急计划，确保公司的数据和备份得到充分保护，且保证日常正常运行。</li></ol><p><strong>任职要求</strong></p><ol><li>本科以上学历，计算机、软件工程等相关专业，2年以上ERP行业项目经验，有跨境电商女装类目搭建经验、曾任职领星/赛狐等ERP企业优先考虑；</li><li>熟练掌握Java/Python等后端开发语言，熟悉MySQL，掌握分区、分表、集群等相关高可用设计方案具备MySQL优化经验，有从0-1搭建经验；</li><li>熟悉跨境电商各种业务的流程和逻辑，了解各环节的重点及对异常情况的处理；</li><li>有较强的信息规划能力、逻辑思维能力、学习创新能力、数据分析能力，具备IT架构管理和应用能力；</li><li>具备良好的沟通协调能力和跨部门协助能力，能够与不同部门有效沟通并达成协同工作目标。我们提供：</li><li>富有竞争力的薪资体系：基本工资，绩效；</li><li>健全的培训学习体系：新员工入职培训与公司概况；</li><li>入职即购买五险：非深户医疗二档，深户一档；</li><li>年度体检：入职满一年享受体检费用报销；</li><li>带薪休假：享受各种法定带薪假期（婚假、产假、陪产假），工作满一年的员工按公司规定享受5天的带薪年假，依次递增；</li><li>团建活动：每季度部门内部定期组织活动（看电影、 K 歌、轰趴、保龄球、桌球、羽毛球、篮球、健身房、以及户外烧烤、登山活动）；</li><li>节日</li></ol><p><strong>福利</strong></p><p>春节／三八妇女节／端午节／中秋节等重大节日为伙伴们发放贴心礼品；9、简单开放的办公环境，年轻靠谱好玩的队友，轻松的人际关系，公开透明的晋升机制。公司对内部员工，每年开放1-2次零元购大</p><p><strong>福利</strong></p><p>，可根据各自喜好对内部时尚服装随心选，10-30件/人/次。工作时间： 上午9:00-12:00 下午13:45-18:30 双休，月底最后一周单休</p>', '1-3年', '76ddff4620102b7e0nBy3t-8FlVV', '深圳', '11-20K', 'Java, 全栈工程师, C++, SpringCloud, Redis, 跨境电商/亚马逊, Spring, ERP开发经验, 服装/女装, MySQL, PHP, 架构设计经验, Oracle, Python', '跨境电商ERP软件开发工程师', 'https://www.zhipin.com/job_detail/76ddff4620102b7e0nBy3t-8FlVV.html', '五险, 零食下午茶, 带薪年假, 生日福利, 节日福利');
INSERT INTO `jobs` VALUES (24, '北半球网络科技', '电子商务', '100-499人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>Java后端开发：负责基于Java语言的后台业务系统、API接口、微服务的设计、开发、测试、部署、运维与持续优化，保障系统稳定性和性能。</li><li>Web前端开发与维护：负责公司Web应用的前端页面开发（HTML, CSS, JavaScript/Vue）及交互实现，确保良好的用户体验和兼容性。</li><li>RPA流程设计与开发：分析业务部门⾃动化需求，设计、开发、测试、部署基于影⼑RPA平台的机器⼈流程，并负责已部署流程的监控、运行维护与优化升级</li></ol><p><strong>岗位要求</strong></p><p>1.有2年以上的Java开发经验，熟悉Java RESTful API，熟悉Spring Boot/MyBatis等开发框架2.熟悉数据库系统，如MySQL、Oracle等，熟悉SQL语言3.熟悉常⽤的前端技术，如HTML/JavaScript/CSS/Vue等4.熟悉Linux系统，了解Linux的命令和操作5.具有Python经验优先，了解AI行业发展，有AI编程经验6.熟悉财务、金蝶云星空丶AWS等系统对接开发经验优先</p>', '1-3年', '1719cc5f7814c58d0nFz0tq5FVFZ', '深圳 · 龙岗区 · 坂田', '13-18K·13薪', 'Java, MyBatis, SpringCloud, MySQL, Oracle, ERP开发经验, 不接受居家办公', 'Java', 'https://www.zhipin.com/job_detail/1719cc5f7814c58d0nFz0tq5FVFZ.html', '补充医疗保险, 股票期权, 餐补, 员工旅游, 读书资金, 带薪年假, 企业年金, 交通补助, 有无线网, 绩效奖金, 意外险, 全勤奖, 加班补助, 定期体检, 五险一金, 团建聚餐, 底薪加提成, 节日福利, 年终奖, 零食下午茶');
INSERT INTO `jobs` VALUES (25, '深圳市亦方创新科技', '智能硬件/消费电子', '20-99人', 'A轮', '本科', '<p>硬性要求： 必须有金蝶ERP / MES / OA / 工作流相关系统开发经验，十分 熟悉金蝶API接口对接开发</p><p><strong>岗位职责</strong></p><p>- 参与企业内部系统的后端开发与迭代 - 负责业务模块的接口实现，包括物料管理、⼯单流转、审批流等 - 与产品协作，实现需求上线落地 - 排查并修复线上问题 ---</p><p><strong>任职要求</strong></p><p>- 1-2 年 Java 后端开发经验 - 熟悉 Spring Boot 等主流框架，了解 RESTful API 设计规范 - 掌握主流数据库，具备 SQL 与⾮ SQL 数据库的基本使⽤能力 - 熟悉 Git，有多人协作开发经验 - 对 AI 有真实理解与实践，具备 Vibe Coding 能⼒，能熟练驾驭 Claude、Codex 等 AI 编程工具，真正将 AI 融入开发流程以提升效率，而非停留在表层使用 - 具备飞书或企业微信 SDK 对接能力，如机器人消息推送、审批回调、应用事件订阅、通讯录同步等 - 思维清晰，善于沟通，能准确理解业务需求并转化为技术方案 --- 加分项 - 了解审批流、状态机等业务设计模式 - 有 Vue 2/3 基础，能独立完成简单业务页面 - 了解 Redis、消息队列等中间件基本用法 - 有 Docker 基础，能看懂部署配置</p>', '1-3年', '9be3d066f1b5c7830nBy29q4EVVX', '深圳 · 南山区 · 科技园', '12-15K·14薪', 'Java, Nginx, Docker, PostgreSQL, SpringCloud, MySQL, MyBatis, Redis, Spring, HBase', '初级后端开发工程师', 'https://www.zhipin.com/job_detail/9be3d066f1b5c7830nBy29q4EVVX.html', '交通补助, 定期体检, 团建聚餐, 股票期权, 零食下午茶, 年终奖, 带薪年假, 五险一金');
INSERT INTO `jobs` VALUES (26, '广州易云', '计算机软件', '20-99人', '未融资', '本科', '<ol><li>3年以上开发经验。</li><li>熟悉SpringBoot SpringCloud微服务开发框架。</li><li>熟悉vue.js前端开发。</li><li>熟悉Redis Nginx MQ等中间件和 MySQL数据库，熟悉Idea Git Maven等开发工具。</li><li>熟悉Linux常用命令和docker容器化部署。</li></ol>', '1-3年', '0aeb1c32063bcc4e1HJ809--GVFV', '深圳 · 福田区 · 车公庙', '8-13K', 'Java, Tomcat, SpringCloud, Redis, 架构设计经验, Spring, 有前端经验/技能', '资深java开发工程师', 'https://www.zhipin.com/job_detail/0aeb1c32063bcc4e1HJ809--GVFV.html', '');
INSERT INTO `jobs` VALUES (27, '晓多科技', '企业服务', '100-499人', 'D轮及以上', '本科', '<p>晓多科技 & 北大信息科技高等研究院AI应用服务联合实验室招聘如果你：对AI充满热情，渴望用技术解决现实问题；勇于躬身实践，而不是临渊羡鱼，希望在AI浪潮之颠有所作为；相信创新源于热爱、好奇心和快速行动，而非循规蹈矩；那么，你就是我们正在寻找的人！</p><p><strong>岗位职责</strong></p><ol><li>负责AI技术在创新业务场景的工程化落地，重点推进大模型应用相关算法在业务中的创新和规模化； a. 结合业务需求，实施和优化大模型应用（包括Prompt工程/RAG/Agent开发等），深入理解和应用大模型特性，确保技术方案满足业务目标； b. 主导AI技术的工程集成，包括系统设计、开发和部署，确保模型在系统中的稳定性、高性能和扩展性；</li><li>与产品、中台、预研等跨职能团队高效沟通协作，及时推动解决协作中的卡点；</li><li>用AI编程等工具来解决实际问题；</li><li>提炼公用模块（或给中台团队提需求），提升代码复用性和扩展性。</li></ol><p><strong>任职要求</strong></p><ol><li>工程开发能力： a. 熟练掌握至少一种后端开发语言，具备扎实的编程功底和丰富的工程化实践经验，能够独立完成高质量的代码开发； b. 善用AI编程和利用开源项目来解决问题。</li><li>创新与主动性： a. 对前沿技术和新事物充满好奇心，乐于动手探索和实践，勇于接受挑战并推动技术创新。 b. 具备较强的主观能动性，能主动提出改进和优化建议，在不确定性环境中具备解决问题的创造力。 c. 有良好的问题发现和分析能力，能及时识别项目中潜在的技术风险并提出应对方案。</li><li>能够根据业务需求选择合适的大模型解决方案，清晰理解其在项目中的应用潜力和局限性。</li><li>学习与协作能力： a. 具备快速学习和适应能力，能够在短时间内掌握新技术并应用于实际项目。 b. 具有较强的团队协作意识和沟通能力，能够与跨职能团队紧密合作，解决问题。 c. 有清晰的工作规划和自我管理能力，能够在较高压力下高效执行并保证任务质量。加分项：</li><li>AI技术与大模型应用： 有实际的大模型使用经验（如通过Prompt工程优化生成效果、调用API进行定制化应用等），具备使用大模型实现业务需求的能力。</li><li>具有参与技术竞赛并获得优异成绩的经验，或在创新项目中有突出表现的候选人优先。</li><li>有个人技术积累和分享习惯（如技术博客、开源项目、技术社区参与等），具备知识传递和团队赋能能力。</li><li>有全栈开发经验或能够跨前后端独立实现完整业务链路者优先。</li></ol>', '1-3年', '23f45f7cd418f14703Z829u6GFdQ', '深圳 · 龙岗区 · 坂田', '18-35K', 'Java, Nginx, 不接受居家办公, Redis, 搜索/推荐/广告经验, Spring, Elasticsearch, 微服务经验, MySQL, MongoDB, Spark, 架构设计经验, Python', 'AI产品研发工程师', 'https://www.zhipin.com/job_detail/23f45f7cd418f14703Z829u6GFdQ.html', '五险一金, 带薪年假, 生日福利, 绩效奖金, 节日福利, 团建聚餐, 年终奖, 股票期权');
INSERT INTO `jobs` VALUES (28, '费滋', '互联网', '100-499人', '未融资', '本科', '<p>boss</p><p><strong>岗位职责</strong></p><p>1、参与即时通讯平台核心模块的开发与维护2、负责功能模块的代码编写、单元测试与问题排查3、参与技术方案评审，学习并实践分布式系统设计4、配合团队完成需求开发与线上问题处理5、持续学习，逐步承担核心模块的设计与优化工作</p><p><strong>任职要求</strong></p><ol><li>985/211 院校本科及以上学历，计算机相关专业2、毕业 3 年以内，有扎实的计算机基础3、熟悉 Java 核⼼，了解多线程、集合、IO 等基础知识4、熟悉 Spring Boot / MyBatis 等主流框架，有实际项⽬经验5、了解 MySQL、Redis 等常⽤存储系统6、熟练使用 AI 工具辅助开发，包括 AI 编码（如 Cursor、Claude Code）、AI 测试、AI 辅助调试等7、具备良好的编码习惯和代码规范意识8、对技术有热情，具备较强的学习能⼒与自驱力加分项：</li><li>有即时通讯/消息系统相关项目经验优先2、有 Netty、NIO 网络编程经验优先3、有分布式系统相关课程或实践项目优先4、有开源项目贡献或技术博客优先5、ACM/ICPC 等算法竞赛获奖优先培养方向：导师制： 资深架构师一对一指导AI 辅助开发： 团队全面拥抱 AI 工具，提升研发效能核心业务： 参与 IM 核心模块开发，快速成长技术视野： 接触高并发、大规模分布式系统实战晋升通道： 明确的技术晋升路径，表现优秀可快速晋升</li></ol>', '1-3年', '3ae9041e610ef9770nF92960EFBT', '深圳 · 南山区 · 科技园', '10-15K', '', '初级Java工程师', 'https://www.zhipin.com/job_detail/3ae9041e610ef9770nF92960EFBT.html', '绩效奖金, 定期体检, 零食下午茶, 节日福利, 五险一金, 带薪年假, 生日福利');
INSERT INTO `jobs` VALUES (29, '招商永隆银行深圳分行', '计算机服务', '100-499人', '', '本科', '<p><strong>工作职责</strong></p><p>1.根据项目要求，承担相关功能的开发工作并按计划完成任务目标2.配合系统分析人员相关的需求调研及分析工作3.完成项目相关功能程序设计及代码的编写4.完成对应功能模块的单元测试，联调等工作</p><p><strong>任职要求</strong></p><ol><li>本科及以上学历；计算机、软件工程等相关专业，掌握计算机开发、软件测试等基础理论；</li><li>熟练使用Java编程语言，两年及以上项目开发经验，有银行软件开发项目经验优先；</li><li>熟练掌握Vue/JavaScript/HTML5/CSS3等Web前端技术4.熟练掌握SpringCloud/SpringBoot等框架的使用；</li><li>熟练掌握至少一种后台开发语言（Node.js/PHP/Python/Java等），对前后端联合开发的技术原理有全面的认识；</li><li>熟悉MySQL、ORACLE、SQL Server等主流数据库；</li><li>熟悉Linux命令和shell脚本的编写。</li><li>熟悉Docker等容器化平台的部署和维护。</li><li>熟悉redis、kafka等中间件者优先 10.熟悉分布式系统设计与开发、负载均衡技术、系统容灾设计、高可用系统等相关知识者优先；该岗位为招商永隆银行子公司---- 招商永隆信息技术（深圳）有限公司正式编制。</li></ol>', '1-3年', '356854e85f5109f61HVy39m6FltU', '深圳 · 龙岗区 · 平湖', '11-20K', 'Java, Spring, MySQL', '软件开发工程师（初级）', 'https://www.zhipin.com/job_detail/356854e85f5109f61HVy39m6FltU.html', '');
INSERT INTO `jobs` VALUES (30, '盼贤智能科技', '进出口贸易', '100-499人', '不需要融资', '本科', '<p>本岗位硬性要求是具备跨境电商erp项目开发经验，没有跨境电商ERP开发经验的勿投哦！</p><p><strong>岗位职责</strong></p><ol><li>负责跨境电商 ERP 系统全栈开发与迭代，完成 亚马逊 / Temu / Shein / 沃尔玛 等平台对接、多仓库 / 多币种、订单 / 库存 / 物流 / 财务 等核心模块开发，独立完成后端开发到前端页面实现、开发与部署、数据库设计优化及部署上线。</li><li>跟踪⾏业技术趋势，推进 AI、⾃动化等新技术在 ERP 业务落地。</li><li>参与需求分析、⽅案设计、接口联调、问题排查全流程，协同跨团队保障项目交付。</li><li>遵循开发规范，编写代码与技术文档，主导代码评审、性能优化与技术沉淀。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上计算机相关专业，2 年及以上 Java 全栈开发经验，有跨境电商 ERP 开发经验优先。</li><li>具备 ERP 系统 0-1 搭建或深度⼆次开发经验，熟悉订单、库存、物流、财务、平台同步、客户管理等核心模块开发，能独立主导或核心参与ERP系统的架构设计、模块开发、上线迭代全流程。</li><li>后端：精通 Java（JDK8+），熟练掌握 Spring Boot、Spring Cloud、MyBatis-Plus，理解Spring Cloud微服务架构。</li><li>数据库与中间件：熟练使用 MySQL/Oracle/PostgreSQL，具备数据库设计、SQL / 索引优化、分库分表经验。</li><li>前端：熟练掌握 Vue3、ES6+、Node.js，精通 Element Plus、uni-app，具备响应式开发、移动端适配、前端性能优化能力。</li><li>熟悉亚马逊 / Temu/Shein/ 沃尔玛等 1-2 个跨境电商平台 API 对接流程，理解跨境电商业务。</li><li>具备独立需求分析、方案设计、问题排查能力；熟悉敏捷开发，有良好代码规范、协作、执行与抗压能力，学习与推进能力强。</li></ol><p><strong>薪资福利</strong></p><ol><li>工作时间上午9：00-12：00，下午；13：30--18：15，实行大小周，法定节假日正常休息。</li><li>薪资待遇月薪8K–12K，能力优秀者可面议谈薪。</li><li>员工</li></ol><p><strong>福利</strong></p><p>提供五险一金</p><p><strong>福利</strong></p><p>，基础保障及时到位。依法享有带薪年假，法定节假日正常休息，工作生活平衡。提供年度定期体检，关注员工身体健康与长期发展。配备节日</p><p><strong>福利</strong></p><p>、日常下午茶，定期组织团建活动，氛围轻松。</p>', '1-3年', '6f3d346bdd18d92a0nd40tq_FFpR', '深圳 · 龙岗区 · 坂田', '10-12K', '', 'Java 全栈工程师（跨境电商 ERP 方向）', 'https://www.zhipin.com/job_detail/6f3d346bdd18d92a0nd40tq_FFpR.html', '带薪年假, 底薪加提成, 生日福利, 五险一金, 团建聚餐, 加班补助, 绩效奖金, 节日福利, 零食下午茶, 定期体检, 法定节假日三薪, 有无线网');
INSERT INTO `jobs` VALUES (31, '漠阳风', '互联网', '0-20人', '未融资', '本科', '<p><strong>岗位职责</strong></p><p>负责 Java 团队的产品研发，能与团队共同进步，攻克难关，承受压⼒与责任；负责技术框架和开发⼯具的搭建，核⼼代码的编写，系统性能优化，主导技术难题攻关；负责产品进度跟踪和控制，风险监控，问题的协调和解决，确保工作按计划完成；对团队开发人员进⾏有效辅导，帮助其快速成长；关注并结合新技术对现有或未来系统提出创新性解决方案。</p><p><strong>任职要求</strong></p><p>本科学历2年以上Java开发经验，熟练微服务架构及Spring Cloud全家桶；熟悉Spring、Spring Mvc、Mybatis、Ajax、Jquery等主流Java Web框架及技术栈；掌握前端框架Vue、js、Bootstrap等前端框架，有前端开发经验优先；熟悉Tomcat、Kafka、Redis、Oracle、Mysql等中间件和数据库；熟悉Linux系统及shell；具有Docker和Kubernetes相关的DevOps工作相关工作优先；有物流系统的开发经验优先。岗位</p><p><strong>福利</strong></p><p>薪资范围：15k-20k</p>', '1-3年', '3ab5a4344f6bd1ea0nB72Nm_FVBY', '深圳 · 福田区 · 车公庙', '15-20K', '', 'Java开发工程师', 'https://www.zhipin.com/job_detail/3ab5a4344f6bd1ea0nB72Nm_FVBY.html', '交通补助, 五险一金, 员工旅游, 绩效奖金, 节日福利, 底薪加提成, 带薪年假');
INSERT INTO `jobs` VALUES (32, '优力特', '智能硬件', '20-99人', '未融资', '本科', '<p>招聘需求：Java 开发工程师（充电桩运维 / 运营平台方向）一、岗位名称Java 开发工程师（充电桩⾏业平台开发）⼆、</p><p><strong>岗位职责</strong></p><p>参与充电桩运维平台、运营平台的全⽣命周期开发，涵盖需求分析、方案设计、编码实现、测试优化及上线运维；负责平台核心功能模块开发，如设备故障统计、充电账单明细、设备状态监控、操作记录管理等功能；对接充电桩硬件数据接口，实现设备状态实时⾤集、指令下发、数据解析与存储；优化平台性能，保障高并发场景下（如大规模充电桩数据同步、多用户同时操作）的系统稳定性；参与技术方案评审，推动代码规范与质量提升，解决开发过程中的技术难点；配合产品、测试团队完成需求迭代与系统故障排查。</p><p><strong>三、任职要求</strong></p><p>（一）技术技能Java 基础：精通 Java 语言，熟练掌握 Spring Boot、Spring Cloud 等主流框架，具备扎实的 Java 多线程、集合、设计模式知识；数据库：熟练使用 MySQL/Oracle，掌握 SQL 优化、索引设计，了解 Redis 等缓存中间件在数据高并发场景的应用；开发工具：熟练使用 IDEA、Git、Maven 等开发及版本管理工具；接口与协议：熟悉 HTTP、TCP/IP 协议，能独立完成设备端与平台端的接口对接、报文解析（如充电桩设备的自定义报文解析）；前端协作：了解 Vue、React 等前端技术，能与前端团队高效协作完成前后端联调；可选加分项：有物联网（IoT）平台开发经验、充电桩行业项目经验、DevOps（Docker、K8s）实践经验者优先。（二）项目经验具备至少 2 年 Java 后端开发经验，有企业级平台开发经历（如运维管理平台、运营管理系统）优先；参与过设备管理类系统（如硬件状态监控、故障统计、数据报表）开发，理解设备端与服务端的数据交互逻辑；有高并发、高可用系统开发经验者优先（如支持千级以上设备同时在线的平台）。（三）通用能力具备良好的需求分析与逻辑思维能力，能快速理解业务场景并转化为技术方案；有较强的问题排查与解决能力，能独立定位并解决开发、运维过程中的技术问题；具备良好的团队协作与沟通能力，能高效对接产品、测试、运维等跨部门团队；对充电桩行业有一定认知，或有意愿深入了解新能源领域业务者优先</p>', '1-3年', '17f8bd5d59efeb4203163960E1pY', '深圳 · 龙华区 · 民治', '13-20K', 'Java, 物联网经验, 不接受居家办公, SpringCloud, 其他, SQL Server, 架构设计经验, Oracle', '充电运维平台开发工程师', 'https://www.zhipin.com/job_detail/17f8bd5d59efeb4203163960E1pY.html', '零食下午茶, 定期体检, 年终奖, 五险一金, 员工旅游, 通讯补贴, 节日福利, 补充医疗保险');
INSERT INTO `jobs` VALUES (33, '鼎丰', '跨境物流', '100-499人', '', '本科', '<p><strong>岗位职责</strong></p><ol><li>收集并整理各部门的业务需求，确保需求清晰、完整。</li><li>分析需求，提出解决方案，设计原型图或流程图以支持需求确认。</li><li>根据需求，按时完成开发任务（包括但不限于后端、前端及移动端），涵盖编码、测试和优化。</li><li>参与系统设计，提供技术可行性建议，确保功能实现和性能稳定。</li><li>快速解决生产环境问题，确保系统稳定运⾏。分析问题根因，提出改进措施。</li><li>梳理公司业务流程，识别流程中的痛点并提出优化建议。</li><li>根据部门安排，提供需求分析、开发技术相关的专业知识和技能培训。</li><li>持续学习⾏业新技术，提升⾃身专业能力，为团队提供技术⽀持。</li><li>完成领导交办的其他任务，积极配合部门工作安排。</li></ol><p><strong>岗位要求</strong></p><ol><li>熟悉 Java 开发，具备扎实的后端开发基础，能够独立完成业务功能、接口及数据库相关开发工作。</li><li>熟悉 Spring、SpringMVC、Spring Boot、Spring Cloud、MyBatis 等主流 Java 技术框架，有实际项目开发经验；</li><li>熟悉 MySQL 数据库，能够编写常用 SQL，具备表结构设计、索引优化和慢 SQL 排查能力；</li><li>熟悉前端基础技术，熟悉 Vue / Vue3 开发，能够完成管理后台页面开发、接口联调和基础交互功能。</li><li>具备前后端一体化开发能力，能够根据业务需求完成从数据库、后端接口到前端页面的完整功能开发。</li><li>了解 Flutter、小程序等移动端开发技术者优先。</li><li>熟悉 Git 等版本管理工具，具备良好的代码规范、文档意识和问题排查能力。</li><li>具备较强的业务理解能力、沟通能力和责任心，能够主动推进任务并及时反馈开发进度和问题。</li></ol>', '1-3年', 'a7722b98ceea61010nF-3tW8E1tW', '深圳 · 福田区 · 车公庙', '9-13K', 'Java, Spring, SpringCloud, MyBatis, Elasticsearch, MySQL, Redis, Oracle, 微服务经验, ERP开发经验', 'JAVA 开发工程师', 'https://www.zhipin.com/job_detail/a7722b98ceea61010nF-3tW8E1tW.html', '通讯补贴, 全勤奖, 年终奖, 五险一金, 员工旅游, 节日福利, 商业意外险, 深圳重疾险, 员工体检, 带薪年假');
INSERT INTO `jobs` VALUES (34, '深圳融慧数科有限公司', '计算机服务', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责公司后端系统的需求分析与技术设计工作；</li><li>参与核心模块的架构设计、技术选型及方案落地；</li><li>完成关键功能的代码编写、接口开发及性能优化；</li><li>配合前端、测试团队推进产品迭代并保障系统稳定运行；</li><li>持续优化系统架构，提升服务的⾼并发处理能⼒与可维护性。</li></ol><p><strong>任职要求</strong></p><ol><li>具备良好的沟通能⼒和团队协作意识，能高效协同跨职能团队；</li><li>熟悉主流后端开发语言及框架，具备扎实的编程基础；</li><li>掌握数据库设计与优化，熟悉缓存、消息队列等中间件技术；</li><li>理解分布式系统原理，具备微服务架构相关实践经验；</li><li>有较强的问题分析与解决能⼒，对待工作认真负责。注：此岗位是给肇庆蓝带啤酒招聘，工作地址肇庆或广州。（介意者慎投）</li></ol>', '1-3年', '7d05e98fb3aef34f0nJ7092_FVNQ', '深圳 · 宝安区 · 西乡', '10-12K', 'Java, SpringCloud, Docker, MySQL, Oracle, SQL Server, 架构设计经验, 大数据经验, 分布式经验, 不接受居家办公', '后端开发工程师', 'https://www.zhipin.com/job_detail/7d05e98fb3aef34f0nJ7092_FVNQ.html', '带薪年假, 年终奖, 员工旅游, 团建聚餐, 全勤奖, 意外险, 绩效奖金, 股票期权, 五险一金, 免费工装, 节日福利, 定期体检');
INSERT INTO `jobs` VALUES (35, '深圳中泓在线', '互联网', '100-499人', '', '本科', '<p>自研产品，非外包，接受应届生【</p><p><strong>岗位职责</strong></p><ol><li>参与需求评审和技术方案讨论，负责平台核心模块方案设计、代码编写工作，确保代码质量，保证系统的安全稳定和高性能；</li><li>参与线上系统的维护与迭代，快速响应并解决生产环境问题，保障服务稳定性； 【</li></ol><p><strong>任职要求</strong></p><ol><li>具备1年左右Java开发经验，具备较强的设计和开发能力，欢迎优秀应届生投递；有前端基础加分。</li><li>Java基础扎实，熟悉熟悉JVM、NIO、多线程、集合等基础框架，熟悉J2EE体系结构；</li><li>熟练掌握Spring Cloud、Spring Boot、Mybatis等开源框架的使用和原理；掌握分布式微服务系统的架构技术，具有实际项目实践经验；</li><li>熟练掌握MySQL、ElasticSearch、Redis等数据库中间件、Kafka消息队列中间件的使用；</li><li>熟练使用Maven、Git管理项目，熟悉DevOps开发流程；</li><li>有SaaS多租户平台及开放平台设计实践经验者优先；对人工智能大模型有一定的了解，学习或使用过Spring AI框架。【岗位优势】1、参与公司战略型平台建设，成长空间大、机会多，为个人履历增色；</li><li>公司近3年保持25%以上的增长，17年来一直专注于自主核心产品研发；</li><li>公司主要为G端业务，互联网+大数据+新媒体模式，赛道优质且稳定；4、</li></ol><p><strong>任职资格</strong></p><p>体系健全，职业发展路径明确。技术通道：中级工程师-高级工程师-主任工程师；管理通道：中级工程师-技术经理/总监。</p>', '1-3年', '59eb4e933c99dcb603F43tS1F1ZT', '深圳 · 南山区 · 科技园', '10-15K·14薪', 'JVM, Java, 不接受居家办公, 分布式经验, 微服务经验, SpringCloud, MySQL, Redis, Spring', '初级java开发工程师', 'https://www.zhipin.com/job_detail/59eb4e933c99dcb603F43tS1F1ZT.html', '');
INSERT INTO `jobs` VALUES (36, '申创衡金', '计算机软件', '20-99人', '未融资', '本科', '<ol><li>统招本科及以上学历，计算机科学与技术、软件工程等计算机相关专业，毕业满2年；</li><li>一年以上保险、金融或其他类似行业业务应⽤系统开发经验；有产险开发经验优先；</li><li>精通Java编程语⾔的基本语法和常⽤类库，能够熟练使用Java开发常见应用程序、Web应⽤程序、企业级应用程序等。</li><li>熟悉关系型数据库（如Oracle、MySQL等）的基本原理，能够使用SQL语言进行数据库操作，了解数据库连接池、事务管理等相关技术。</li><li>Web开发：熟悉Web开发相关技术，如HTML、CSS、JavaScript、AJAX等，能够使用Servlet、JSP、Spring MVC等技术进行Web应用程序开发。</li><li>框架和技术：熟悉常见的Java框架和技术，如Spring、Hibernate、MyBatis、Struts等，了解面向对象设计、设计模式、反射机制、类加载机制等相关知识。</li><li>并发编程：熟悉并发编程相关技术，如多线程、线程池、锁机制、原子操作等，能够编写高并发、高可用的Java程序。</li><li>工具和环境：熟悉常用的Java开发工具和环境，如Eclipse、IntelliJ IDEA、Maven、Git等，能够进行代码管理、构建和调试等工作。</li></ol>', '1-3年', '7754d049dd2253a70nZ-2Nq9GFpW', '深圳 · 龙岗区 · 南联', '11-13K', 'Java, 不接受居家办公, 保险, SpringCloud, MySQL, MyBatis, Spring, Oracle, 金融', 'JAVA开发', 'https://www.zhipin.com/job_detail/7754d049dd2253a70nZ-2Nq9GFpW.html', '节日福利, 员工旅游, 补充医疗保险, 带薪年假, 年终奖, 通讯补贴, 股票期权');
INSERT INTO `jobs` VALUES (37, '国信合成', '计算机软件', '100-499人', '未融资', '本科', '<ol><li>逻辑思路清晰，能够按照软件工程要求进行架构设计及开发；</li><li>精通Java和面向对象的程序设计，熟悉mvc开发框架；</li><li>精通J2EE架构，熟悉Struts、Hibernate、Spring等，精通前端Servlet、JSP、js、jquery等框架；</li><li>熟悉springboot、SpringCloud、nacos等框架，熟悉vue+elmentui的框架并能够熟练使用；</li><li>熟悉Weblogic、WebSphere、Tomcat等J2EE应用服务器其中的一种或多种，了解应用服务器的工作原理、能够对应用服务器进行高级配置和性能优化；熟练使用Eclipse、IDEA等Java开发工具；</li><li>熟悉WebService，包括SOAP、WSDL等，熟悉RESTFUL接口调用客户端及服务端；</li><li>熟悉oracle和mysql数据库；</li><li>有安全架构设计经验优先，有大型项目的设计开发经验优先；</li></ol>', '1-3年', 'a4eaf52d103fa30f1nB52tS0GFNS', '深圳 · 南山区 · 科技园', '6-11K', 'Java, CSS, Oracle, Spring, Struts', 'JAVA开发工程师', 'https://www.zhipin.com/job_detail/a4eaf52d103fa30f1nB52tS0GFNS.html', '交通补助, 带薪年假, 员工旅游, 五险一金, 节日福利');
INSERT INTO `jobs` VALUES (38, '深圳利新胜技术服务', '银行', '100-499人', '已上市', '本科', '<p>初级开发工程师（985,211）</p><p><strong>岗位职责</strong></p><ol><li>负责券商柜台系统的后端开发与维护，确保系统高效稳定运行；</li><li>参与需求分析，设计并实现系统架构及业务逻辑；</li><li>编写高质量的代码并优化系统性能；</li><li>与前端、测试及其他团队密切合作，保证系统顺利上线；</li><li>负责系统⽇常运维⼯作，快速响应并解决⽣产环境问题；</li><li>跟踪并应用最新的技术和工具，推动系统架构的持续优化。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历（985,211），计算机或数学等相关专业；</li><li>1年以上Java后端开发经验；</li></ol><p><strong>技术要求</strong></p><ol><li>熟悉Java语⾔及技术体系，熟悉Spring等主流框架；</li><li>熟悉Spring/Spring Boot、MyBatis等框架；</li><li>熟悉Linux操作系统，能独立完成环境部署和运维；</li><li>熟悉分布式系统设计，了解微服务架构；</li><li>熟悉MySQL、Redis等数据库，具备数据库调优经验；</li><li>熟悉消息队列（如Kafka、RabbitMQ等）和缓存技术；</li><li>具有高并发、高可用系统开发经验;其他要求：</li><li>具备较强的分析和解决问题的能力，工作积极主动；</li><li>有良好的团队合作和沟通能力，能与跨部门同事高效协作；</li><li>关注金融科技前沿，有较强的学习能力。</li></ol>', '1-3年', 'a383d3c73eb55e8d0nZ52tu_GFpR', '深圳 · 南山区 · 前海', '16-25K', 'Java, Nginx, 物联网经验, 不接受居家办公, 分布式经验, PostgreSQL, Redis, SQL Server, Spring, 大数据经验, MySQL, MyBatis, 架构设计经验, 区块链经验, Python', '初级java开发工程师', 'https://www.zhipin.com/job_detail/a383d3c73eb55e8d0nZ52tu_GFpR.html', '员工旅游, 五险一金, 定期体检, 保底工资, 生日福利, 零食下午茶, 节日福利, 绩效奖金, 年终奖, 带薪年假, 团建聚餐, 股票期权');
INSERT INTO `jobs` VALUES (39, '弘量科技', '互联网金融', '100-499人', 'B轮', '本科', '<p><strong>岗位职责</strong></p><p>1. 负责自研产品后端服务的设计和开发2. 跟踪业务的运营情况，并从研发角度推动业务的发展3. 对效率有一定敏感度，致力于提高公司的工作效率</p><p><strong>任职条件</strong></p><p>1. 熟悉JAVA开发，掌握JAVA多线程，IO等知识，拥有3年左右的J2EE开发经验2. 熟悉Spring，SpringMVC等主流开源架构及原理3. 熟悉微服务，设计模式，缓存技术，和流行的中间件4. 能够在工作过程中积极主动提出解决方案并解决实际问题5. 性格开朗，稳重责任心强以下条件优先：1，有创业的热情，熟悉 fintech2，背景优秀3，对源码有热情或研究者加分公司提供有竞争力的工资+奖金+股权激励，正规的五险一金、休假等</p><p><strong>福利</strong></p><p>，额外有各种小</p><p><strong>福利</strong></p><p>。公司团队来自腾讯、华为等知名企业。产品线有：1、资管业务，由公司Algo团队支持，提供给公募私募策略2、2B2C业务，公司给大型金融机构提供算法+IT的完整解决方案3、2C业务，在香港和内地均有财富管理产品推出目前和多家知名VC在洽谈融资，发展前景良好。</p>', '1-3年', '78f43182084d32731nx73NW_FlBQ', '深圳 · 福田区 · 石厦', '11-20K', '多线程, 微服务架构, MVC开发, Spring, 后端开发', 'java开发工程师', 'https://www.zhipin.com/job_detail/78f43182084d32731nx73NW_FlBQ.html', '年终奖, 团建聚餐, 带薪年假, 工龄奖, 股票期权, 餐补, 加班补助, 零食下午茶, 绩效奖金, 节日福利, 补充医疗保险, 五险一金');
INSERT INTO `jobs` VALUES (40, '深圳爱七普科技', '人工智能', '0-20人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责公司核心后端系统的设计与开发，支持AI能力接入及业务落地</li><li>独⽴完成模块设计与实现，保障系统在⾼并发、⾼可用场景下稳定运行</li><li>基于实际业务场景，持续优化系统架构、性能及存储⽅案</li><li>主动发现并解决技术问题，而不是仅执行需求</li><li>熟练使用AI工具（如Claude、ChatGPT等）提升开发效率，参与AI辅助编程实践</li><li>持续关注新技术与开源生态（如GitHub），并尝试在项目中落地</li></ol><p><strong>任职要求</strong></p><ol><li>1-3年Java后端开发经验，基础扎实（多线程、集合、JVM、网络等）</li><li>有完整项目经验，能独立负责模块开发，而非仅参与局部功能实现</li><li>熟悉常见后端技术栈（Spring Boot / MySQL / Redis 等），具备高并发或大数据量处理经验</li><li>具备良好的系统设计能力，对高并发、高可用、高扩展有基本认知</li><li>有实际使用AI工具辅助开发的经验（如Claude Code、Copilot等），能提升开发效率</li><li>逻辑清晰，具备独立分析和解决问题的能力，遇到问题有主动推进意识</li><li>学习能力强，对新技术保持持续探索，有GitHub项目或开源参与经验优先</li><li>具备良好的沟通能力，能够在快速变化的业务中高效协作</li></ol>', '1-3年', '26cde257b681c9090nJ70t24EFpR', '深圳', '10-15K·14薪', '不接受居家办公, Java, Spring, SpringCloud, MyBatis, Hibernate, MySQL, Redis, Oracle, MongoDB, HBase', 'JAVA后端', 'https://www.zhipin.com/job_detail/26cde257b681c9090nJ70t24EFpR.html', '员工旅游, 五险一金, 团建聚餐, 绩效奖金, 带薪年假, 年终奖');
INSERT INTO `jobs` VALUES (41, '江南月', '互联网', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>根据设计需求，负责游戏业务功能模块的开发和优化；</li><li>主动测试游戏，完成对应的单元测试，确保游戏服务器运行高效稳定；</li><li>有较强的责任强和担当，能与团队很好的合作；</li><li>负责对于技术难题组织攻关。</li></ol><p><strong>岗位要求</strong></p><ol><li>1-3年以上Java游戏服务器编程经验；</li><li>有较扎实的Java基础知识，能够熟练使用Java相关技术进行独立开发；</li><li>熟悉Java多线程、并发库、熟悉TCP/IP协议，NIO，熟悉Netty框架，基础的算法和数据结构；</li><li>熟悉MySql数据库及MySql的优化，熟悉redis缓存技术，熟悉protobuf协议；</li><li>熟悉Maven或Gradle等构建工具；</li><li>熟悉Linux常用命令，有基于Linux的程序部署、管理及优化配置和Shell脚本编写；</li><li>对Java虚拟机有深入的了解优先，有多人在线游戏分布式架构经验优先。</li></ol>', '1-3年', '665965fa91d7256003V50tm6E1U~', '深圳 · 宝安区 · 西乡', '14-20K', 'Java, 后端开发, 游戏开发', 'java工程师', 'https://www.zhipin.com/job_detail/665965fa91d7256003V50tm6E1U~.html', '年终奖, 带薪年假, 五险一金, 交通补助, 免费班车, 住房补贴, 全勤奖, 节日福利, 通讯补贴, 员工旅游, 餐补, 加班补助, 包吃, 股票期权');
INSERT INTO `jobs` VALUES (42, '颖鑫商贸', '电子商务', '20-99人', '未融资', '大专', '<p><strong>岗位职责</strong></p><ol><li>负责 TikTok Shop Partner Center 开放平台 API 的对接、二次开发与集成测试，保障数据传输的稳定与安全。</li><li>参与公司电商业务系统/工具（如订单管理、商品上架、数据看板等）的 Web/App 端架构设计与功能实现。</li><li>协助完成 API 调优、接口异常排查及日常系统维护，提升系统吞吐量与稳定性。</li><li>编写清晰的开发文档、接口调⽤规范及测试⽤例。</li></ol><p><strong>任职要求</strong></p><ol><li>经验要求：具备 1 年及以上软件/ Web 开发经验，有完整的项⽬落地经验。</li><li>技术栈要求：①熟练掌握至少一门后端开发语⾔（如 Java、Go 或 Node.js），具备良好的代码规范和面向对象/函数式编程思维。②熟练掌握至少一门脚本语言（如 Python），能高效编写自动化脚本、数据处理或接口测试工具。</li><li>平台经验：具备 TikTok Shop Partner Center API 的实际对接、接口调用、签名认证及联调测试经验（熟悉第三方应用授权流程机制者优先）。</li><li>基础能力：①熟悉 RESTful API、Websocket 等通信协议及 JSON 数据格式。②熟悉常用数据库（如 MySQL、Redis）及基本的SQL调优。③熟练使用 Postman、Swagger 等接口测试与文档工具。</li><li>加分项①熟悉跨境电商业务流程（如 ERP 系统、物流履约、店铺数据分析等）。②了解主流前端框架（如 React、Vue.js），具备全栈开发能力。③有应对 API 限流、重试机制、高并发场景的实际处理经验。薪酬待遇：</li><li>工作时间：双休，上午9:00-12:00，下午14:00-18:00；无任何强制加班，提倡高效工作，完成工作到点即可下班；</li><li>凡入职员工，公司统一购买五险一金（养老保险、工伤保险、失业保险、医疗保险、生育保险、住房公积金）；</li><li>无责任底薪，每月按时足额发放薪资；</li><li>每周下午茶， 公司内设有茶水间，微波炉和冰箱，提供员工使用；</li><li>团队以90后、00后为主，工作氛围轻松简单，人文气息温馨，不定期举行公司聚餐或其他娱乐活动。</li></ol>', '1-3年', 'ce1e23f98ef1aee60nJ63di8F1FY', '深圳 · 盐田区 · 沙头角', '12-20K', 'Java, Python, JVM, MySQL, ERP开发经验, React, Websocket, RESTful API', 'TikTok Shop Partner Center Web开发工程师', 'https://www.zhipin.com/job_detail/ce1e23f98ef1aee60nJ63di8F1FY.html', '年终奖, 带薪年假, 五险一金, 节日福利');
INSERT INTO `jobs` VALUES (43, '黔仁信息', '广告营销', '20-99人', '', '本科', '<p><strong>工作职责</strong></p><ol><li>负boss责公司内部系统开发；</li><li>负责对外接口处理</li></ol><p><strong>任职要求</strong></p><ol><li>精通主流的java框架，springmvc，springboot.</li><li>精通前端主流框架，vue2，vue3。精通html，熟练把图切成html.</li><li>精通响应式设计开发，比如bootstrap，elementui等.</li><li>精通js，typescript语言,5、精通中间件tomcat。</li><li>精通数据库mysql。</li><li>熟练使用开发工具eclipse，Intellij IDEA.vscode.</li><li>3年以上开发者优先考虑</li></ol>', '1-3年', 'd5ad90dc0cd01e8e0nB-39m4F1FT', '深圳', '10-15K', 'Java, MySQL, Spring', 'web工程师开发', 'https://www.zhipin.com/job_detail/d5ad90dc0cd01e8e0nB-39m4F1FT.html', '节日福利, 意外险, 零食下午茶, 带薪年假, 社会保险');
INSERT INTO `jobs` VALUES (44, '恒娱科技', '游戏', '0-20人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责手游服务器功能的开发和优化；</li><li>维护管理后台系统的稳定。</li></ol><p><strong>任职资格</strong></p><ol><li>1年以上手游服务器相关研发的经验；</li><li>精通Java编程，熟悉Java常用框架Spring、SpringMVC、Mybatis，熟悉事务；</li><li>熟悉多线程，了解线程安全和线程可见性，能编写正确高效的多线程代码；</li><li>熟悉缓存的原理和使用，比如：redis等， 了解mysql索引优化；</li><li>责任心强，良好的沟通和团队协作能力，主动好学有进取心；</li><li>熟悉nodejs更佳。</li></ol>', '1-3年', '84effe0b81b6cf651nV73928ElFX', '深圳 · 南山区 · 科技园', '10-15K', 'Java, Linux, MySQL, 多线程, Redis, Spring, 后端开发, 游戏开发', '游戏Java工程师', 'https://www.zhipin.com/job_detail/84effe0b81b6cf651nV73928ElFX.html', '零食下午茶, 餐补, 带薪年假, 股票期权, 加班补助, 员工旅游, 五险一金, 节日福利, 年终奖');
INSERT INTO `jobs` VALUES (45, '广东云云律师事务所', '法律', '100-499人', '不需要融资', '本科', '<p><strong>工作职责</strong></p><ol><li>负责工单系统开发；</li><li>梳理工单相关业务流程梳理并推动对接；</li><li>参与技术难点攻关，主导或配合完成系统性能优化、故障排查，保障业务系统平稳运行；</li><li>协助团队进⾏技术沉淀和知识分享，完善开发规范，提升团队整体技术⽔平；</li><li>配合公司整体项⽬进度，与产品、测试等相关部门高效协作，确保项目按时按质交付。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机，数学相关专业，1-5年Java服务端开发经验；</li><li>精通Java基础，多线程，JVM调优，幂等，⼀致性原理；熟练使用缓存，消息队列，分布式调度等中间件；</li><li>精通SpringBoot，Mybatis-Plus，Mysql，有flowable, activiti, camunda, jBPM开发经验；</li><li>能熟练使用Claude Code、CodeX，Cursor等主流编程工具；</li><li>思维敏捷，具有良好的逻辑思维，能发现，分析，快速合理化解决问题能力；</li><li>具备以下任一系统研发经验者优先：法催系统、诉讼管理系统、催收系统、银行交易或风控系统。</li></ol>', '1-3年', 'abd3997348b766570nF62N6-E1NV', '深圳 · 福田区 · 车公庙', '15-20K', '不接受居家办公, Java, Spring, MySQL, 分布式经验, 微服务经验, 工单系统', 'java工程师（工单系统）', 'https://www.zhipin.com/job_detail/abd3997348b766570nF62N6-E1NV.html', '午休, 团建聚餐, 底薪加提成, 绩效奖金');
INSERT INTO `jobs` VALUES (46, '安居智联', '物联网', '0-20人', '', '大专', '<p>技能经验**： - 精通Java开发框架，如SpringBoot、Spring Cloud、Quartz等，并有相关的项目经验 - 熟悉物联网平台开发及相关协议，如MQTT、TCP、MODBUS、PLC-S7等 - 具备分布式系统设计与实现的经验，了解高并发、高可用的后端模型设计 - 对Linux操作系统及数据库技术（如MySQL、Redis/MongoDB、Memcached等）有深厚的理解和应用等个人素质**： - 良好的问题分析、解决能力及创新能力，能独立面对和解决复杂问题 - 热爱技术，具备较强的自我学习和主动学习的能力 - 良好的沟通表达和团队协作能力，能够与团队成员及其他部门有效合作，能接受工作强度等</p><p><strong>工作职责</strong></p><p>**： - 负责物联网平台的研发工作，包括物接入、物管理、物引擎和时序数据库等产品的开发与维护 - 参与需求分析、系统架构设计、模块开发、测试与部署等软件开发全过程 - 负责设备后端软件开发，确保设备通过app、H5、小程序等控制设备的使用功能等同时需具备良好的个人素质和能够胜任多样的</p><p><strong>工作职责</strong></p><p>。</p>', '1-3年', '8994381b8105a3731XF409W-FlRQ', '深圳 · 罗湖区 · 东湖', '9-14K', 'Java, JavaScript, MySQL, Java开发经验, 中大型项目架构设计经验, 大数据处理经验', 'Java', 'https://www.zhipin.com/job_detail/8994381b8105a3731XF409W-FlRQ.html', '');
INSERT INTO `jobs` VALUES (47, '深圳辰普森', '建筑工程咨询服务', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责后台系统的需求分析和功能设计，完成产品的开发和维护；</li><li>参与业务需求讨论，评审产品设计，驱动研发团队一起按时、高质量完成产品交付；</li><li>调研新技术，参与各类技术难题的攻关，沉淀技术能力和行业经验，与平台一起成长和发展。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机相关专业，至少具备1年以上后端开发经验；</li><li>熟悉Java/JEE，基础扎实，熟练掌握常用Java技术框架，能编写高质量简洁清晰的代码；</li><li>熟练使用springboot框架，熟悉springcloud体系；</li><li>熟练使用mysql关系数据库、redis非关系型数据库、消息中间件等技术；</li><li>熟悉基本Linux命令，了解docker容器基本知识；</li><li>了解sql优化，对新技术有较好的敏感度，有较强的驱动力去研究新的技术。</li><li>能看得懂前端简单的代码</li></ol>', '1-3年', 'd9fc27077a8cc9d91XJ42t61EFtY', '深圳 · 光明区 · 光明', '8-13K', '', '后端开发', 'https://www.zhipin.com/job_detail/d9fc27077a8cc9d91XJ42t61EFtY.html', '五险一金, 餐补, 节日福利, 交通补助, 团建聚餐, 保底工资, 带薪年假, 零食下午茶, 股票期权, 绩效奖金, 员工旅游, 加班补助, 年终奖');
INSERT INTO `jobs` VALUES (48, 'Ricequant', '计算机软件', '20-99人', 'B轮', '本科', '<p>RiceQuant（米筐）专注于金融数据与量化投资科技，围绕数据、研究、交易与风险管理构建产品和技术服务。我们重视数据质量、工程可靠性、风险边界和长期可维护性，倡导以严谨、协作和持续学习解决真实问题，拒绝无效加班，追求⾼效产出。【</p><p><strong>岗位职责</strong></p><ol><li>监控行情新鲜度与完整性、策略进程、委托、成交、撤单、拒单、延迟、 Gateway / 通道连接、告警和系统资源；</li><li>对异常进⾏初步定位，在授权范围内采取隔离或风险控制措施，结合日志、 指标和链路状态判断影响范围，及时升级，并完整记录时间线、处置动作与结果；</li><li>使用 Java / Python 开发和维护交易支持工具、监控、告警、核对及自动化流程，为关键逻辑补充测试、审计信息和运行文档；</li><li>核对策略信号、订单、成交、持仓和资金在相关系统中的一致性，识别重复、 遗漏、状态不同步和数据口径问题；</li><li>与策略、数据、研发、运维及实际使用的交易通道负责人协作， 支持上线、排障、回滚和复盘；</li><li>学习交易所规则、交易日历、订单生命周期、程序化交易行为和策略执行逻辑， 持续沉淀 Runbook、检查清单和工程规范。【</li></ol><p><strong>岗位要求</strong></p><ol><li>本科及以上学历，计算机、软件工程、电子信息、数学、统计、物理、金融 工程等相关专业；专业背景不完全匹配但工程能力和项目经历突出者，可综合评估；</li><li>掌握常用数据结构、算法和复杂度分析，能结合约束解释工程取舍；</li><li>具备良好的面向对象基础，理解抽象、封装、接口、模块边界和可维护性；</li><li>能使用 Python 编写结构清晰、可测试的数据处理或自动化工具；</li><li>具备 Java 基础，能够阅读、编写和调试业务代码，熟悉集合、异常、I/O、 OOP 和基本并发概念；</li><li>熟悉 Linux、Git、SQL 和基础网络知识，能够使用日志与指标定位问题；</li><li>理解测试、可观测性、数据一致性、最小权限和变更控制的重要性；</li><li>做事细致，沟通清晰，能在时间敏感场景中保持严谨并按流程升级问题。【加分项】1.有量化机构、券商交易台、期货公司、交易所或金融科技相关实习或项目经历；</li><li>接触过任一种交易 API、柜台或消息协议，例如 CTP、FIX、DMA、WebSocket 或 Protobuf，并理解订单生命周期；</li><li>有 Java 服务端、并发与异步编程、数据库、消息系统、监控告警或分布式系统实践；</li><li>了解股票、期货、期权等任一市场的交易规则、微观结构、执行成本或基差；</li><li>做过行情质量、交易日历、订单成交核对、持仓资金核对或异常检测相关工作；</li><li>有清晰的事故复盘、Runbook、自动化测试或可观测性建设作品。</li></ol>', '1-3年', '351cc2100edb6fa30nFz29y7EFJQ', '深圳 · 南山区 · 科技园', '10-14K·13薪', 'JVM, Java, 低延迟, 虚拟线程, MySQL, Netty, Redis, MongoDB, 交易系统, Vert.X, Python, 量化交易', '初级量化交易工程师', 'https://www.zhipin.com/job_detail/351cc2100edb6fa30nFz29y7EFJQ.html', '带薪年假, 餐补, 加班补助, 通讯补贴, 零食下午茶, 交通补助, 全勤奖, 年终奖, 股票期权, 五险一金, 定期体检, 节日福利, 员工旅游');
INSERT INTO `jobs` VALUES (49, '某大型银行公司', '银行', '100-499人', '', '本科', '<p><strong>职位描述</strong></p><p>1-3年工作经验\n做过小微贷款项目优先\n认证资质\n人力资源服务许可证\n赵女士\n猎头\n·\n猎头顾问\n竞争力分析\n查看完整个人竞争力\n个人综合排名：在人中排名第\n你在？位置\n一般 良好 优秀 极好\nBOSS 安全提示\n严禁用人单位和招聘者用户做出任何损害求职者合法权益的违法违规行为，包括但不限于扣押求职者证件、收取求职者财物、向求职者集资、让求职者入股、诱导求职者异地入职、异地参加培训、违法违规使用求职者简历等，您一旦发现此类行为， 请立即举报\n更多职位\n看过该职位的人还看了\njava开发（半导体大厂）\n15-25K\n某知名半导体/芯片公司\n深圳\nJava工程师\n15-30K·15薪\n某知名公司\n深圳\nweb3后端开发工程师\n15-20K\n深圳通盛源科技\n深圳\njava开发（半导体大厂\\国企\\六险一金）\n15-25K·13薪\n某大型公司\n深圳\nFDE工程师（跨境电商+AI）\n15-20K\n增量科技\n深圳\nJava开发（大厂，六险一金）\n15-25K·13薪\n某大型公司\n深圳\n精选职位\nJAVA（双倍工资+六险一金）\n15-30K\n华为\n深圳\n高级java开发工程师\n15-30K\n嘉立创\n深圳\nFDE工程师（跨境电商+AI员工方向）\n15-18K·13薪\n增量科技\n深圳\nJava\n15-16K\n同和信息技术有限公司\n深圳\n中级java开发工程师\n15-18K\n众投互联\n深圳\nJava\n15-30K·14薪\n艾麦物流\n深圳\n深圳\n搜索\n城市招聘 热门职位 推荐公司 热门企业\n伊犁哈萨克自治州招聘\n东莞招聘\n阿拉尔招聘\n河源招聘\n忻州招聘\n阳江招聘\n兴安盟招聘\n河池招聘\n西安招聘\n遵义招聘\n首页深圳招聘·Java招聘深圳Java招聘某大型银行公司Java招聘\n页面更新时间：2026-08-05\n企业服务热线和算法/未成年人等举报渠道 400 065 5799\n老年人直连热线400 661 6030\n工作日 8:00 - 22:00\n休息日 8:00 - 22:00\n企业服务\n职位搜索\nAPP\n投资者关系 Investor Relations\n直品公益基金会\n求职技巧\n使用与帮助\n协议与规则\n隐私政策\n防骗指南\n使用帮助\n联系\n北京华品博睿网络技术有限公司\n公司地址 北京市朝阳区太阳宫中路16号院1号楼18层1801内09\n违法和不良信息举报邮箱/未成年人举报渠道 jubao@.com\nCopyright © 2026 京ICP备14013441号-5京ICP证150923号 电子营业执照 京公网安备11010502032801 朝阳网警 人力资源服务许可证 网上有害信息举报专区 朝阳区人社局监督电话 算法备案信息</p>', '1-3年', '7c54047f1ef68b880nF92d66F1FQ', '深圳', '15-25K·14薪', '', 'java开发（小微贷款）--深圳福田某银行正编', 'https://www.zhipin.com/job_detail/7c54047f1ef68b880nF92d66F1FQ.html', '');
INSERT INTO `jobs` VALUES (50, '遇创科技', '游戏', '20-99人', '未融资', '大专', '<p><strong>岗位职责</strong></p><p>1. 负责游戏运营管理后台研发，主攻节假日营销活动模块开发维护，涵盖春节、端午、中秋、国庆、周年庆、各类节日</p><p><strong>福利</strong></p><p>、充值活动、签到、抽奖、礼包、累充返利、限时玩法等活动后台逻辑开发2. 搭建可视化活动配置后台，支持运营自主配置活动时间、奖励档位、区服范围、参与门槛、活动开关、灰度测试等，快速落地节⽇营销⽅案3. 对接游戏服务端、客户端、充值SDK、道具系统、邮件系统，完成活动接口开发、联调、压测与全流程上线4. 开发活动数据统计、流⽔报表、参与数据、奖励发放、核销复盘等运营数据看板，支撑活动效果数据分析5. 完善活动风控逻辑，做好防刷、重复领取拦截、异常发放拦截、高并发流量适配，保障节假⽇大流量活动稳定运行6. 封装通用活动组件与活动模板，沉淀可复用营销活动框架，缩短节日活动迭代上线周期7. 负责线上活动日常运维、问题排查、紧急需求迭代、奖励补发、活动上下线等工作</p><p><strong>任职要求</strong></p><ol><li>计算机专业，1~3年以上java开发工作经验；</li><li>扎实java基础，有多线程开发及NIO开发工作经验；</li><li>熟练使用spring框架以及相关组件，有过微服务开发经验；</li><li>有丰富的MySQL数据库查询和调优经验。</li><li>熟练使用git，maven，gradle，idea等各种开发工具。</li><li>有高并发程序设计经验，对jvm工作原理和内存分析有一定的工作经验。</li><li>有jQuery，vue2/3，jsp，uniapp，layui，element ui等网页开发经验。</li><li>熟练操作linux常用的各种命令和工具软件。 薪资待遇 - 薪资：11k-15k，根据能力与经验定级，能力优异可面议-</li></ol><p><strong>福利</strong></p><p>五险一金、带薪年假、节日</p><p><strong>福利</strong></p><p>、项目奖金、绩效奖金- 日常：弹性作息、下午茶、团队团建、技术成长培训- 晋升：后端开发→活动负责人→后台技术主管</p>', '1-3年', 'd4277f8801718dcf0nB42t68GVFX', '深圳 · 南山区 · 科技园', '11-15K·13薪', '', 'Java游戏后台开发工程师', 'https://www.zhipin.com/job_detail/d4277f8801718dcf0nB42t68GVFX.html', '五险一金, 年终奖, 定期体检, 绩效奖金, 员工旅游, 通讯补贴, 节日福利, 带薪年假, 交通补助, 零食下午茶, 餐补');
INSERT INTO `jobs` VALUES (51, '东朗', '进出口贸易', '20-99人', '不需要融资', '本科', '<p>全日制公办本科以上学历，英语四级（此为硬性要求，不满足勿扰）。薪资架构：底薪+绩效奖金+餐补上班时间：09:00-12:30，14:00-18:30，双休。</p><p><strong>职位福利</strong></p><p>每天30分钟休闲放松时间、每周下午茶、节日</p><p><strong>福利</strong></p><p>、员⼯旅游、定期体检、带薪年假、绩效奖⾦、五险⼀金、过年带薪11天、春节返乡来回高铁实报实销试⽤期3个月，表现优异者可提前申请转正。</p><p><strong>岗位职责</strong></p><ol><li>负责公司内部系统（简道云、领星、飞书等）的数据搭建、迁移与分析，优化数据流程，支持运营、财务、供应链等部门的数据需求；</li><li>与业务部门沟通，梳理重复性工作流程，利用RPA工具和AI技术设计并开发自动化解决方案，提升工作效率；</li><li>负责人事招聘版块的自动化筛选功能开发与维护，结合AI智能体实现简历初筛、候选人匹配等；</li><li>参与公司业财融合项目，通过系统对接与数据整合，实现业务数据与财务数据的联动分析；</li><li>使用Python或Java进行后端开发，处理复杂业务逻辑，实现系统间的API接口对接；</li><li>管理数据库（如MySQL、SQL Server等），编写高效SQL，确保数据准确性和查询性能；</li><li>跟踪AI技术发展，创建和优化智能体应用，推动AI在业务场景中的落地。</li></ol><p><strong>岗位要求</strong></p><ol><li>公办本科及以上学历，英语四级（此为硬性指标，不满足者勿扰）计算机科学、软件工程、信息管理等相关专业；</li><li>熟练掌握Python或Java编程语言，具备扎实的编码能力；</li><li>熟悉数据库操作，能够编写复杂SQL语句，具备数据库设计和优化经验；</li><li>了解AI技术，能够利用大模型或相关工具创建和编辑智能体（如基于LangChain、RAG等）；</li><li>至少掌握一种RPA工具（如UiPath、影刀、阿里云RPA等），并有实际项目经验；</li><li>学习能力强，具备良好的沟通能力和跨部门协作精神，能快速理解业务需求；</li><li>有跨境电商行业经验，或熟悉简道云、领星、飞书等平台者优先。公司信息公司创立于2016年，是一家专业跨境电商公司。我们有丰富的外贸平台经营经验。我司主做亚马逊、Ebay、Temu平台。亚马逊平台主要市场为美国、德国、英国站点，产品以户外、家居为主，也有做个护、厨具、母婴等类目。运营思路以精品为主，不跟买、不铺货，全FBA。公司具有十分强劲的销售能力，对于打造爆款精品review有成熟打法和充分经验。主推类目排名能稳居前几名。Ebay平台与temu平台主要市场为美国、德国、英国、澳大利亚。产品以户外、家居为主。运营思路以海外仓为主，少量小包测款，期待您的加入！在供应链方面，供应商实力雄厚，在销售端具有明显竞争力。主要</li></ol><p><strong>福利</strong></p><ol><li>公司上班地点上塘路口、龙华地铁站附近，老板蛮有亲和力~团队氛围有爱和谐，关系简单，没有勾心斗角，也不喜欢勾心斗角；</li><li>节假日大小</li></ol><p><strong>福利</strong></p><ol><li>公司重视个人发展，只要完成该完成的事情，人品能力达到，升职、加薪、绩效奖金、年终奖金等你来拿；</li><li>在团队内部，注重团队成员能力进步和提升，团队的整体进步才是我们所看重的，公司内部倡导交流氛围，也组织学习亚马逊新政策和交流新打法新思路；</li><li>公司走品牌化精品化经营路线，配备专业的职能部门打造独立品牌。有专业的产品开发和品质监控人员，为打造独立品牌奠定基础；</li><li>定期体检：免费入职体检，公司定期安排一次员工体检，体检费约1500元，公司支付；</li><li>调薪政策：公司会根据工作表现对正式员工进行不定期加薪；</li><li>带薪年假：正式员工享有带薪休假，除了国家法定假期（法定假日、婚假、产假等），春节享受11天的带薪假。</li><li>返乡补贴：正式员工享有春节期间返乡往返高铁补贴，实报实销。</li></ol>', '1-3年', '3e9b31b0ecd4137b0nZ82d27F1dW', '深圳 · 龙华区 · 民治', '8-13K·13薪', 'Java, Nginx, 不接受居家办公, RPA, MySQL, Spring, Python', 'rpa开发工程师(双休/跨境电商）', 'https://www.zhipin.com/job_detail/3e9b31b0ecd4137b0nZ82d27F1dW.html', '员工旅游, 节日福利, 底薪加提成, 定期体检, 餐补, 13天年假带薪, 零食下午茶, 补贴, 团建聚餐, 带薪年假, 节假日加班费, 加班补助, 五险一金, 绩效奖金, 生日福利, 年终奖, 交通补助');
INSERT INTO `jobs` VALUES (52, '深圳昌原科技有限公司', '互联网', '20-99人', '不需要融资', '大专', '<p>【</p><p><strong>岗位职责</strong></p><ol><li>对接各业务部门，精准拆解需求，独立完成表单设计、流程建模、数据关联、API接口调用及第三⽅系统集成（飞书、企业微信、领星、亚马逊）；</li><li>运⽤⾼阶JavaScript编写自定义脚本与拓展组件，突破平台限制，解决复杂业务痛点及性能瓶颈；</li><li>负责项目全流程⽂档编制(需求文档、设计文档、测试报告、操作手册)，推动内部知识沉淀；</li><li>跟踪AI低代码技术趋势，基于MCP协议落地AI Agent多智能体协作场景，运用AI组件实现智能表单、智能审批、自动化分析；</li><li>为内部用户提供平台操作培训与技术支持，负责系统上线后的运维与迭代优化；</li><li>具备Java开发大型ERP系统经验，熟悉Spring全家桶；</li><li>熟悉服务器运维技术。【</li></ol><p><strong>任职要求</strong></p><ol><li>熟练掌握低代码平台核心模块（织信Informat优先），包括表单设计器、BPMN流程设计器、数据仪表盘、组件设计器等；</li><li>精通高阶JavaScript，熟悉MySQL/SQL Server，具备复杂SQL编写及性能调优能力；</li><li>精通企业级API集成，熟悉第三方系统对接、异常重试、数据一致性处理；</li><li>1-3年低代码开发经验，至少成功交付过1个中大型企业级项目；</li><li>了解AI Agent及大模型基础原理，熟悉MCP协议，有多智能体协作开发经验者优先；</li><li>扎实的Java功底，熟练使用SpringBoot、Spring MVC，能独立完成后端定制开发与第三方服务对接。【加分项】有Python开发经验熟悉跨境电商业务流程具备敏捷开发、DevOps实施经验</li></ol>', '1-3年', '32489cdec4315dd60nJ63dq-FVRR', '深圳 · 龙华区 · 民治', '15-25K', 'Java, Spring, MySQL, SQL Server, 不接受居家办公, 全栈开发工程师, 织信低代码, 织信 |nformat 平台, 高阶JavaScript, 跟踪织信 |nformat', '织信低代码全栈开发工程师', 'https://www.zhipin.com/job_detail/32489cdec4315dd60nJ63dq-FVRR.html', '零食下午茶, 年终奖, 工龄奖, 绩效奖金, 底薪加提成, 保底工资, 带薪年假, 全勤奖, 五险一金, 员工旅游, 节日福利');
INSERT INTO `jobs` VALUES (53, '深圳市新佳邮科技物流', '跨境物流', '100-499人', '未融资', '大专', '<p><strong>岗位职责</strong></p><ol><li>根据产品需求，分析并提出合理的后端解决方案，进行后端框架设计及开发；</li><li>根据研发分配和需求，完成相应模块的程序设计和开发任务；</li><li>参与部门项目维护，性能优化和bug修复。</li></ol><p><strong>任职要求</strong></p><ol><li>全日制⼤专及以上学历，计算机软件相关专业优先；</li><li>熟悉Java、Go等⾄少⼀种后端开发语言，有扎实的编程基础；</li><li>熟练掌握SpringCloud、SpringBoot等至少⼀种后端开发框架；</li><li>熟悉MySQL、Redis、MongoDB、ELK等数据库，熟悉数据库设计和SQL优化；</li><li>熟悉Ubuntu操作系统，熟悉常用命令，能够熟练使用Shell编写脚本；</li><li>熟悉Docker、K8S等容器技术，熟悉微服务架构，有相关项目经验者优先；</li><li>有大数据、人工智能、区块链等相关技术经验者优先；</li><li>有良好的英语听说读写能力者优先，有财务、BI、统计报表工作经历优先</li></ol>', '1-3年', '6d8a6f910a6a2ee70nFy3tW5FVFY', '深圳 · 龙华区 · 民治', '10-15K·13薪', 'Golang, Java, Docker, PHP', '后端开发工程师（财务方向）', 'https://www.zhipin.com/job_detail/6d8a6f910a6a2ee70nFy3tW5FVFY.html', '工龄奖, 节日福利, 五险一金, 员工旅游, 带薪年假, 全勤奖, 年终奖, 团建聚餐, 生日福利, 节假日加班费');
INSERT INTO `jobs` VALUES (54, '深圳市超牛牙业科技', '物流/仓储', '20-99人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>核心开发：负责企业级后端系统开发，基于Spring Boot构建高可用微服务架构，优化API性能与安全性；设计并实现消息中间件（Kafka/MQTT）的集成方案，⽀持千万级设备接⼊与实时数据处理；</li><li>使⽤ Golang 语言负责储能EMS（Energy Management System）系统的架构设计，利用 Angular 进⾏前端开发，确保前后端的高效协同和用户体验优化；</li><li>工业物联网系统搭建：开发工业协议（Modbus/698/645）通信模块，实现PLC、传感器数据采集与协议转换；构建设备管理平台，整合MQTT/Kafka实现数据从边缘到云端的全链路传输；</li><li>技术攻关与优化：解决分布式场景下的消息积压、重复消费、设备断连重试等稳定性问题；</li><li>熟练使用Maven/Gradle构建Spring Boot可执行JAR，掌握生产环境参数配置（如--spring.profiles.active=prod ）熟悉JVM调优技巧，包括堆内存分配（-Xmx）、GC算法选择（ZGC/Shenandoah）及JMX监控集成，精通Dockerfile多阶段构建，优化镜像层体积（基础镜像选择、依赖分层打包）；</li><li>掌握Docker Compose编排Spring Boot+Kafka+MySQL等微服务集群，实现网络隔离与资源限制（CPU/Memory约束）。</li></ol><p><strong>任职要求</strong></p><ol><li>1-3年以上Java开发经验，Golang 语言开发经验，扎实的JVM、多线程、网络编程基础，有储能EMS系统开发经验者；</li><li>精通java语言、Spring Boot、Spring Cloud，熟悉MyBatis/Redis/RocketMQ等主流中间件；</li><li>精通Kafka集群部署与运维（吞吐量优化、监控告警）；</li><li>精通MQTT协议开发（EMQX/HiveMQ服务端集成）；</li><li>精通 Modbus/TCP工业设备通信（j2mod库应用）；</li><li>精通 mysql等关系型数据库，对时序数据库IOTDB有一定了解，并具备开发能力；</li><li>熟悉DDD领域驱动设计，能独立完成模块架构设计及文档编写；</li><li>熟悉 Golang 开发，有储能EMS系统开发，熟悉 Angular 框架，有前端开发经验。</li><li>熟悉 Linux 操作系统，具备 Shell 脚本编写能力；</li><li>懂Photoshop、有UI设计能力；</li></ol>', '1-3年', '74809f7c5989d7f803x_3tm5FlBX', '深圳 · 福田区 · 车公庙', '9-14K', 'Java, Golang, Spring, Kafka, PostgreSQL, MongoDB, Redis, 云计算经验, 架构设计经验, 不接受居家办公', '全栈软件开发工程师', 'https://www.zhipin.com/job_detail/74809f7c5989d7f803x_3tm5FlBX.html', '五险一金');
INSERT INTO `jobs` VALUES (55, '广东仟锐', '计算机软件', '20-99人', '未融资', '大专', '<p>工作boss</p><p><strong>职责</strong></p><p>1、负责MES系统开发与现场实施2、负责与客户、产线、IT部门对接，协调业务需求、解决现场使用问题3、负责MES与ERP/WMS 等第三方系统接口联调、测试及问题闭环4、负责基于公司产品进行系统⼆次开发、接口定制、报表开发、功能扩展及现场问题修复；</p><p><strong>任职资格</strong></p><ol><li>专科及以上学历，计算机、软件⼯程、信息管理专业；</li><li>熟悉 Java 语⾔，精通 SpringBoot 框架，熟悉Spring MVC、Spring Data、Spring Security 等常用模块；熟悉 MyBatis / MyBatis-Plus 或 JPA 等ORM 框架；掌握 Maven / Gradle 构建工具及 Git 版本控制；</li><li>具备独⽴接口开发、业务逻辑调试、代码阅读与问题排查能力；熟悉 Linux 基础命令，能在服务器环境下进行应用部署、日志查看及简单故障处理；了解 Java 多线程、并发编程基础及常用设计模式；</li><li>熟悉 JavaScript，了解 Polymer 框架或 Web Components 技术，能进行前端页面调试、组件定制及基础交互开发；</li><li>需掌握 Oracle / MySQL / PostgreSQL / SQLServer 中至少一种数据库，能独立进行SQL开发、数据同步、报表统计及基础运维；</li><li>熟悉工厂生产业务流程，了解车间制造、生产工单、物料、工序、报工、质检等 MES 核心业务场景；</li><li>具备良好沟通表达，工作严谨负责、抗压能力强，能接受出差 / 现场驻场实施；</li><li>有 MES / WMS 项目实施、需求调研、方案梳理、上线交付、用户培训经验，或有 WMS 与 EAP、MES、ERP、设备系统接口对接、联调测试、数据打通经验者优先；</li></ol>', '1-3年', '80e1ec8a505d79ad0nF82Ny_E1BW', '深圳 · 坪山区 · 坪山', '10-15K', 'Java, MES开发经验, 不接受居家办公', 'Java（6个月）', 'https://www.zhipin.com/job_detail/80e1ec8a505d79ad0nF82Ny_E1BW.html', '五险一金, 加班补助');
INSERT INTO `jobs` VALUES (56, '崛胜科技有限公司', '进出口贸易', '20-99人', '', '本科', '<p>双休（不支持线上面试），工作时间8:30~9:00-18:00~18:30，午休1.5小时，8⼩时⼯作制，弹性上下班我们正在建设⾯向 B 端客户的商城网站，后端以 Java 技术栈为主。这个岗位会参与商城核心业务、第三⽅平台 API 对接和系统稳定性建设，同时要求候选人能把 AI 工具真正用于项目开发、重构、排障和效率提升。岗位概览岗位方向：B 端商城网站后端研发，重点支撑商品、订单、支付、会员和第三方平台集成。技术栈：Java、Spring Boot / Spring Cloud、MyBatis(-Plus) / JPA、MySQL / PostgreSQL、Redis。工作经验：1-3 年 Java 后端开发经验。薪资范围：10-16K/月，具体根据项目经验、能力匹配度和面试结果综合评估。核心要求：熟练使用 Cursor / VS Code Copilot / Antigravity 等 AI 开发工具，并有使用 AI 工具完成网站项目开发的实际经验。业务背景：B 端商城无自有库存，核心能力之一是与第三方平台 API、供应链和内部业务系统稳定打通。</p><p><strong>岗位职责</strong></p><p>后端架构与工程建设参与公司新 B 端商城网站的后端架构搭建与持续迭代，围绕 Java / Spring Boot / Spring Cloud 完成项目初始化、模块划分、API 设计、数据库设计和工程规范建设。设计清晰、稳定、可维护的接口和业务模块。配合前端完成接口联调，保障前后端分离协作效率。持续优化服务端性能、并发处理能力和系统稳定性。商城核心业务开发负责商品、商品分类、购物车、下单结算、订单、会员、支付、权限等核心后端功能开发。根据业务流程完成接口需求分析、领域模型设计和业务逻辑实现。编写必要的单元测试、集成测试和接口文档，支撑上线验收。对线上问题进行定位、复盘和持续优化。第三方平台 API 对接围绕无自有库存的业务特点，设计并实现与支付、物流、短信、供应链、企业系统等第三方平台的接口对接。处理 API Key / OAuth2 / 签名验签、参数映射、数据同步、异步回调和 Webhook。建设幂等、对账、失败重试、限流降级、监控告警和异常排查机制。按需打通 MES / CRM / WMS / ERP 等内部系统，支撑商城与生产供应链联动。AI 驱动的高效开发在真实开发流程中使用 AI 代码编辑器辅助需求拆解、代码生成、重构、测试补全、问题定位和性能优化。能判断 AI 生成代码的可靠性，主动审查安全、事务、并发、边界条件和可维护性。投递时请注明常用 AI 工具、典型使用场景，以及可脱敏的项目案例。稳定性优化与技术沉淀针对复杂业务场景进行数据库优化、缓存策略、消息队列、错误监控和可观测性建设，并沉淀 API 文档、接口规范、上线流程、故障复盘等资料。参与团队知识沉淀和技术分享，帮助项目长期可维护。配合团队完成与项目交付、上线和问题复盘相关的开发工作。</p><p><strong>任职要求</strong></p><p>1-3 年 Java 后端开发经验，具备完整项目交付经历；本科及以上学历，学信网可查，一本及以上背景优先。熟悉 Spring Boot / Spring MVC / Spring Cloud、MyBatis(-Plus) / JPA，掌握 RESTful API 设计和常见性能优化思路。具备扎实 Java 基础，理解集合、并发、JVM、异常处理和常用设计模式。熟悉数据库设计与操作，具备 SQL、索引优化、事务处理经验，常用 MySQL / PostgreSQL / MongoDB 等数据库。熟悉 Redis 等缓存中间件；了解 RabbitMQ / Kafka 等消息队列为加分。有第三方平台或开放平台 API 对接经验，了解 Webhook / 回调、签名验签、幂等和对账设计。必备：至少熟练使用 Cursor / VS Code Copilot / Antigravity 等 AI 开发工具之一，并有使用 AI 工具完成网站项目开发的真实经验。具备接口安全与鉴权意识，如 JWT / OAuth2、参数校验、防越权等；熟悉 Git 工作流和团队协作规范。暂不开放实习岗位；投递时建议附线上项目或可验证的项目说明（可脱敏）。加分项（非必须）有 B 端商城、电商、订单、支付或会员系统开发经验。有支付、物流、ERP、供应链等第三方 / 开放平台 API 对接经验，做过网关或开放平台建设更佳。有高并发、分布式、微服务、消息队列、缓存架构经验。有数据库调优、分库分表或 Elasticsearch 搜索相关经验。熟悉 Docker、K8s、云平台部署和 CI/CD 流程。有与 ERP / MES / CRM / WMS 等企业系统集成对接经验。有 B2B、电商或制造业系统开发经验，熟悉 Swagger / OpenAPI 文档规范。</p><p><strong>薪资福利</strong></p><p>法定保障：五险一金。假期</p><p><strong>福利</strong></p><p>工作满 1 年享 5 天带薪年假。家企联动：生日</p><p><strong>福利</strong></p><p>、节日礼品、父母感恩礼、婚庆礼、生育礼、子女大学奖学金。激励奖励：工龄奖（100 元/月起，最高 200 元/月）、绩效年终奖、优秀团队定制团建、开工红包、月度/年度优秀员工、五年贡献奖。关于我们拥有博士设计团队。国内首批互联网平台 PCBA 快捷厂商。PCBA 最快 8 小时完成，48 小时准交率 > 95%。自主研发 SMT 首件测试仪。自主开发 MES、CRM、WMS、APS、QMS、SIS、TPM、SCADA、IOT 等智能管理系统。3 万余种常见元器件快速供货，原厂代理供应链。深圳、杭州、惠州设有生产工厂。</p>', '1-3年', 'e90777731d60e80d0nF_3dy_GFdZ', '深圳 · 宝安区 · 西乡', '10-15K', 'Java, 物联网经验, 不接受居家办公, Java + Spring Boot, 架构设计经验, B 端商城网站后端研发, Spring', '后端开发工程师（Java）', 'https://www.zhipin.com/job_detail/e90777731d60e80d0nF_3dy_GFdZ.html', '节日福利, 加班补助, 年终奖, 零食下午茶, 全勤奖, 员工旅游, 绩效奖金, 带薪年假, 五险一金');
INSERT INTO `jobs` VALUES (57, '星尚智能', '进出口贸易', '0-20人', '未融资', '本科', '<p><strong>职责描述</strong></p><ol><li>负责公司自建跨境商城及APP, 产业互联APP，搜索、支付，拼团活动和分销裂变等后端, 前段开发工作；</li><li>负责面向APP、小程序、M端等多端尤其后端技术解决方案；</li><li>负责项目中技术难点攻坚和技术优化工作。</li><li>熟悉跨境外贸实务，了解海外市场和客户需求优先。</li></ol><p><strong>任职要求</strong></p><ol><li>计算机，人工智能相关专业本科以上学历，2年以上开发经验；</li><li>精通TCP/IP协议，进程间通讯编程，熟悉Unix/Linux下常用架构设计方法；</li><li>熟悉Unix/Linux操作系统原理，常用工具；</li><li>熟悉Mysql/Oracle等数据库管理、开发,SQL调优；</li><li>精通面向对象设计，熟悉UML等建模工具；</li><li>要求熟悉 Java, C++, Python了解中间件的技术以及基于中间件的开发模式；</li><li>全面的软件知识结构(操作系统、软件工程、设计模式、数据结构、数据库系统、网络安全)；</li><li>具备良好的分析解决问题能力，能独立承担任务和有系统进度把控能力；</li><li>责任心强，良好的对外沟通和团队协作能力，主动，好学；</li><li>具备Mysql数据库相关优化经验或大容量通信系统开发经验优先。</li></ol>', '1-3年', '6b68e590f299d0b41nZz3dW9GVtR', '深圳 · 福田区 · 园岭', '8-13K', 'SQL, 数据结构, Oracle, MySQL, Linux, Spring, 软件工程师, 客户端开发', 'Java', 'https://www.zhipin.com/job_detail/6b68e590f299d0b41nZz3dW9GVtR.html', '年终奖, 带薪年假, 五险一金, 节日福利');
INSERT INTO `jobs` VALUES (58, '必力储能', '储能', '20-99人', '', '本科', '<p><strong>岗位职责</strong></p><p>1. 根据需求和设计文档完成后台系统功能模块的代码编写、测试和维护工作2. 系统开发过程中的问题跟踪与解决3. 系统上线后的持续优化与系统维护4. 参与系统设计和需求的归纳和采集工作 任职</p><p><strong>技术要求</strong></p><ol><li>2年以上Java语⾔开发经验，了解J2EE体系结构，并有基于Java Spring框架的微服务开发经验2. 具备后台接口（Restful API）设计和⾃测调试能⼒（如利用Postman工具）3. 了解和掌握SQL语⾔, 具有MySQL或PostgreSQL数据库结构设计和开发经验4. 有使用版本控制工具经验（git， SVN等）5. 对Java开放框架有了解（RuoYi，Pig等）6. 了解WEB前端开放技术：Html5，CSS3，javascript 任职其他要求：</li><li>计算机或相关专业，全日制公办本科学历以上；211院校优先2. 具备较强的逻辑分析和问题解决能力，具备良好的编码风格和编程习惯3. 具备良好的学习能力，乐于学习和探索新技术并愿意与团队分享，并勇于承担不熟悉的新任务4. 责任心强、工作积极主动、富有团队精神 优先考虑条件（非必须）：</li><li>有云服务开发经验（AWS, 阿里云等）2. 有能源互联网和物联网开发经验3. 熟悉Linux/Unix系统环境，具备利用Docker，Kubernetes，nginx等工具进行系统部署和运维经验4. 有Python开发经验，通过Python进行简单的算法与功能逻辑开发与调试</li></ol>', '1-3年', '31c8eb0f114049eb0nFy09q6EFFX', '深圳 · 罗湖区 · 清水河', '8-11K', 'Java, 不接受居家办公, MySQL, 云计算经验, Spring', 'java开发工程师', 'https://www.zhipin.com/job_detail/31c8eb0f114049eb0nFy09q6EFFX.html', '');
INSERT INTO `jobs` VALUES (59, '鼎金', '批发/零售', '20-99人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>精通Java语言，数据结构；</li><li>熟悉Springboot，Springcloud，Spring, Spring MVC, MyBatis等主流开发框架；</li><li>熟悉分布式运算，网络架构，服务器，中间件，DB，缓存，存储解决方案等优先；</li><li>熟练掌握SQL编程；熟悉SQLServer及mysql等数据库中的其中至少⼀种；熟悉数据库设计、存储过程，触发器者优先；</li><li>熟悉Tomcat、Apache、Nginx等主流应⽤服务器的配置和部署；</li><li>熟悉Redis，Memcached等缓存框架；</li><li>熟练使⽤Idea，Eclipse等开发工具，以及Git、Jenkins等代码管理和发布工具；</li><li>了解HTML，JavaScript、Ajax、JQuery、CSS等web前端技术，掌握⾄少一种前端开发框架（JQuery，vue、Reactor等）；</li><li>具备良好而规范的设计和技术文档编写能力，拥有良好的编写代码习惯；</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机软件或相关专业；</li><li>2年以上java实际项目开发经验3.具备良好的问题分析与解决能力，责任心强，工作细致；</li><li>了解常见运维工具及开发语言，具备一定的系统部署与调试能力；</li><li>有较强的学习能力，能够适应快速发展的技术环境。</li></ol>', '1-3年', 'e240d11a559cfddc0nVz3N-0EFVV', '深圳 · 罗湖区 · 东门', '11-22K·13薪', 'Java, Spring, SpringCloud, MyBatis, MySQL, SQL Server, 架构设计经验, Redis，Memcached, Idea，Eclipse, Git、Jenkins, JQuery，vue、Reactor', '软件运维开发工程师', 'https://www.zhipin.com/job_detail/e240d11a559cfddc0nVz3N-0EFVV.html', '宿舍有空调, 补充医疗保险, 工龄奖, 团建聚餐, 包吃, 全勤奖, 零食下午茶, 五险一金, 包住, 节日福利, 带薪年假, 意外险, 有无线网, 年终奖, 绩效奖金, 底薪加提成');
INSERT INTO `jobs` VALUES (60, '智保惠众', '通信/网络设备', '100-499人', '不需要融资', '本科', '<p>需现场复试！</p><p><strong>任职要求</strong></p><ol><li>大学本科及以上学历，计算机科学与技术、软件工程专业毕业；</li><li>二年以上保险、金融或其他类似⾏业业务应⽤系统开发经验；有产险开发经验优先；</li><li>能独⽴完成功能模块开发，并具有复杂需求的独立分析和设计能力，参与过2个或以上新建项⽬优先；</li><li>熟练掌握Java编程语言，并具备扎实的编程基础，熟悉VUE等前端主流技术；</li><li>熟悉并熟练使用Spring、Springboot、SpringCloud、MyBatis等主流开发框架和工具；</li><li>具备良好的数据库设计和开发能力，有至少2个以上基于Oracle数据库相关的应用开发经验，熟练掌握MySQL、Oracle等数据库语言；</li><li>熟悉基本编码规范，能高效完成编码工作；</li><li>对缓存、事务、日志、分布式等有深入了解；</li><li>有良好的程序性能调优能力；</li><li>有良好的沟通能力和团队协作精神；</li></ol>', '1-3年', '2a38c66ad42078830nJ429y7GVJS', '深圳 · 龙岗区 · 南联', '10-14K', 'Java, MyBatis, Spring, MySQL, Oracle, 保险, 产险, 金融, AI', 'Java开发（外包生命保险，现场复试！）', 'https://www.zhipin.com/job_detail/2a38c66ad42078830nJ429y7GVJS.html', '定期体检, 年终奖, 带薪年假, 节日福利, 五险一金, 零食下午茶');
INSERT INTO `jobs` VALUES (61, '新联鑫科技', '互联网金融', '100-499人', '不需要融资', '本科', '<ol><li>参与反洗钱应用系统软件开发，编写项目文档；</li><li>能够理解业务需求，进行相关系统的设计和开发；</li><li>⾃主完成代码单元测试，参与完成项⽬的集成测试、系统交付⼯作，对项目实施提供一定⽀持。</li></ol><p><strong>任职要求</strong></p><p>•统招本科或以上学历，1年以上工作经验；•计算机相关专业，拥有实际项目开发经验；•熟练掌握Java语言，熟悉网络、IO、多线程、JDBC等技术，以及JVM原理；•熟悉SpringMVC、Spring、MyBatis、SpringBoot等相关框架，有相应框架的实际项目开发经验，熟悉分布式、缓存、消息通信等机制；•熟练使用Maven和代码版本管理工具Git、Svn等；•熟悉MySQL、Oracle等数据库，具有较好的数据库设计和SQL优化能力；• 熟系linux 基本操作指令• 平时自己或在公司有使用过AI编程• 有银行项目工作经验优先。</p>', '1-3年', '188c239680dcc6540nF50t-6FFpW', '深圳 · 南山区 · 前海', '9-11K', 'Java, Spring, MySQL, Oracle', 'Java（本科/1年以上）', 'https://www.zhipin.com/job_detail/188c239680dcc6540nF50t-6FFpW.html', '补充医疗保险, 节日福利, 通讯补贴, 员工旅游, 五险一金, 定期体检, 年终奖, 带薪年假');
INSERT INTO `jobs` VALUES (62, '灯盏屋科技', '计算机软件', '0-20人', '天使轮', '本科', '<p><strong>职位描述</strong></p><p>我们正在寻找一位经验丰富且热情的 Java 后端工程师，加入我们的技术团队。该职位将负责设计和开发高性能的后端服务，支持公司核心业务功能。作为 Java 后端工程师，你将：* 参与后台服务的需求分析、设计和研发；* 与前端和移动开发团队紧密合作，共同实现各类功能；* 编写高质量的代码，确保代码的可靠性和可维护性；* 优化和维护现有系统，提升性能和稳定性；* 关注业界最新技术动态，不断优化和创新产品。</p><p><strong>任职要求</strong></p><ol><li>计算机科学或相关领域的学士学位；</li><li>1-3 年 Java 开发经验；</li><li>熟悉 Spring, Spring Boot 等主流框架；</li><li>熟悉 RESTful API 设计和实现；</li><li>熟练使用关系型数据库（如 MySQL, PostgreSQL）和 NoSQL 数据库（如 MongoDB, Redis）；</li><li>具备优秀的分析和解决问题的能力，良好的代码习惯；</li><li>有分布式系统、微服务架构相关项目经验者优先；</li><li>良好的团队合作精神和沟通能力。加分项：</li><li>熟悉 Docker 和 Kubernetes 容器化技术；</li><li>了解消息中间件（如 Kafka, RabbitMQ）的使用；</li><li>有云服务平台（如 AWS, Azure, 阿里云）的使用经验。</li></ol>', '1-3年', '8e4f0d06490a3f9803R629W9GFJX', '深圳 · 宝安区 · 宝安中心区', '10-15K', 'Java, SpringCloud, MySQL, SQL Server, 架构设计经验, Spring', 'Java 后端工程师', 'https://www.zhipin.com/job_detail/8e4f0d06490a3f9803R629W9GFJX.html', '节假日加班费, 五险一金, 有无线网, 年终奖, 保底工资, 零食下午茶, 股票期权, 团建聚餐, 带薪年假, 定期体检, 员工旅游, 节日福利');
INSERT INTO `jobs` VALUES (63, '环海运通', '物流/仓储', '100-499人', '未融资', '大专', '<p><strong>岗位职责</strong></p><p>1、负责公司内部系统的开发与维护(WMS、订单系统等)2、参与系统架构设计及技术选型3、负责前端页面开发与优化(PC端为主)4、负责后端接口开发、现有功能优化5、与业务团队沟通需求，将业务流程转化为系统逻辑6、持续优化系统稳定性与用户体验</p><p><strong>任职要求</strong></p><p>1、2年以上全栈开发经验(能力强者可放宽)2、熟悉以下技术栈(至少掌握⼀套完整体系):前端: Vue / unipp 后端:Java(主) / Python 熟悉数据库(MySQL) 熟悉利⽤ai来提升开发效率3、有系统架构或中⼤型项目经验优先4、有ERP/WMS/物流系统开发经验优先5、具备良好的逻辑能力及沟通能⼒6、有责任心，能独立推进项目</p>', '1-3年', '0c77c25da67a657e0nJ729u7FldT', '深圳 · 龙华区 · 民治', '8-13K', 'Java, ERP开发经验, 架构设计经验, 不接受居家办公', 'it', 'https://www.zhipin.com/job_detail/0c77c25da67a657e0nJ729u7FldT.html', '保底工资, 底薪加提成, 意外险, 节假日加班费, 带薪年假, 有无线网, 股票期权, 补充医疗保险, 员工旅游, 生日福利, 零食下午茶, 节日福利, 团建聚餐, 加班补助');
INSERT INTO `jobs` VALUES (64, '品声科技', '半导体/芯片', '100-499人', '天使轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责公司核心产品（Web/App/小程序）后端服务器架构设计、模块拆分以及业务代码实现。</li><li>参与系统架构设计，主导技术难题攻关，提升系统在高并发、海量数据场景下的性能、高可⽤性及可扩展性。</li><li>负责设计并编写⾼兼容性、⾼安全性的RESTful API或GraphQL接口，编写清晰的接口文档。</li><li>负责数据库（MySQL/PostgreSQL等）的表结构设计与优化，对慢查询进行调优。</li><li>熟练运⽤Redis、消息队列（Kafka/RabbitMQ/RocketMQ）等中间件解决缓存、削峰、解耦等实际问题。</li><li>编写单元测试和集成测试，参与Code Review，确保代码质量的健壮性与安全性。</li><li>配合运维或DBA进行服务器环境部署、Docker容器化、CI/CD流水线配置及线上问题排查。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机相关专业，具备 2 年以上后端开发经验。</li><li>精通Java，熟悉JVM原理、并发编程、内存模型，熟悉Spring Boot/Cloud全家桶。</li><li>深刻理解TCP/IP、HTTP/HTTPS、WebSocket协议，熟悉Nginx配置与反向代理原理。</li><li>精通MySQL，具备索引优化、SQL调优能力；熟悉至少一种NoSQL（Redis, MongoDB, Elasticsearch）。</li><li>熟练掌握Linux操作系统常用命令，能够在Linux环境下进行开发、部署及Shell脚本编写。</li><li>熟练使用Git及团队协作流程（Git Flow / GitHub Flow）。</li><li>有高并发、高可用、分布式系统（如秒杀系统、千万级DAU项目）实际经验。</li><li>熟悉微服务架构（Spring Cloud / Dubbo / Istio）及服务治理（限流、熔断、降级）。</li><li>有责任心，具备良好的文档编写习惯和极强的Code Review精神。</li></ol>', '1-3年', 'f27a382343524bca0nB92N67ElRT', '深圳 · 宝安区 · 沙井', '8-12K', 'Java, C, Spring, MySQL', '后端开发工程师', 'https://www.zhipin.com/job_detail/f27a382343524bca0nB92N67ElRT.html', '带薪年假, 有无线网, 免费工装, 零食下午茶, 团建聚餐, 包吃, 员工旅游, 年终奖, 五险一金, 节日福利, 定期体检');
INSERT INTO `jobs` VALUES (65, '佳翔', '电子商务', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><p>1. 负责跨境电商场景下AI应用系统的设计、开发和落地（如智能客服、商品文案生成、广告投放优化等）2. 对接跨境电商亚马逊平台-API，实现数据⾃动化处理3. 结合⼤语⾔模型（LLM）和RAG技术，构建业务智能体（Agent）或工作流4. 参与AI应用的后端服务架构设计、性能优化和⽇常维护</p><p><strong>任职要求</strong></p><p>学历：本科及以上学历，计算机、软件工程、人工智能等相关专业经验：2年以上相关工作经验，必须有跨境电商AI应用开发经验（硬性条件）技术能力：1. 精通Python/Java至少一门语言，有扎实的后端开发基础2. 熟悉大语言模型API调用（如OpenAI、Claude、通义千问等），了解RAG、Prompt Engineering3. 有电商平台API对接经验（SP-API、TikTok Shop API等）者优先4. 了解RPA、Agent框架（LangChain等）者加分加分项：有独立完成的AI应用落地项目有团队管理或项目主导经验</p>', '1-3年', '90a13284a64ee45b0nB93tS4FFBQ', '深圳 · 龙岗区 · 南联', '10-15K', 'Java, 不接受居家办公, 亚马逊, 分布式经验, PostgreSQL, Redis, 搜索/推荐/广告经验, 跨境电商, Docker, MySQL, 云计算经验, 架构设计经验, Amazon, Python', 'AI应用开发工程师（跨境电商）', 'https://www.zhipin.com/job_detail/90a13284a64ee45b0nB93tS4FFBQ.html', '节日福利, 底薪加提成, 员工旅游, 年终奖, 零食下午茶, 带薪年假, 五险一金');
INSERT INTO `jobs` VALUES (66, '深圳市盈华八方科技', '互联网', '100-499人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>系统二次开发：负责金蝶云星空（K/3 Cloud）系统的功能扩展与定制开发，基于BOS平台完成单据、报表、插件及业务逻辑的开发与调试。</li><li>数据集成与API对接：负责金蝶云星空与第三方系统（如领星、飞书等）的数据集成，基于WebAPI进⾏接口开发、调⽤与维护，确保跨系统数据的⾼效流转与一致性。</li><li>自动化与脚本开发：运⽤ Python 或 Java 编写自动化脚本，处理数据清洗、批量导入导出、定时任务调度等日常运维需求，提升系统运行效率。</li><li>系统运维与优化：负责ERP系统的日常维护，包括用户权限管理、业务流程配置、性能监控与故障排查，保障系统稳定运行。</li><li>需求分析与方案落地：深入理解财务、供应链、跨境运营等业务场景，配合业务部门梳理需求，提供技术解决方案并推动项目落地。</li></ol><p><strong>任职要求</strong></p><ol><li>学历与经验：本科及以上学历，计算机、软件工程、信息管理等相关专业；</li><li>编程语言：熟练掌握 Python 或 Java 至少一种主流开发语言，具备良好的面向对象编程思想和代码规范。</li><li>金蝶技术栈：熟悉金蝶云星空 BOS 开发平台、插件开发机制及 WebAPI 接口规范；了解 C#/.NET 体系者优先。</li><li>数据库能力：熟练使用 SQL Server 或 MySQL 数据库，具备复杂的 SQL 编写、存储过程开发及性能调优能力。</li><li>集成技术：熟悉 RESTful API 设计、JSON/XML 数据格式，了解常见的中间件（如 Tomcat、Nginx）及消息队列技术。6.</li></ol><p><strong>综合素质</strong></p><p>具备良好的业务理解能力、沟通协调能力和问题解决能力，责任心强，能够承受一定的工作压力。加分项- 有金蝶云星空（K/3 Cloud）项目二开经验者优先。- 持有金蝶证书者优先。- 具备金蝶云星空二次开发或企业级数据集成项目经验。【公司简介】公司主要做跨境电商（亚马逊），300人左右规模，工作时间：8:30-12:10 14:00-18:10 【</p><p><strong>薪资福利</strong></p><p>】1、工作时间：周末双休，八小时工作制，享有国家标准的有薪假期及带薪休假。2、入职缴纳五险一金，发薪日15号3、</p><p><strong>福利待遇</strong></p><p>园区设有酒店公寓和称重食堂，员工享有折扣价租住（500-900 / 间，餐补 500 元 / 月，看综合</p><p><strong>福利待遇</strong></p><p>，让伙伴们工作开心生活幸福。4、节日活动：每位公司小伙伴生日月会收到人资为你精心准备的 SURPRISE，并且公司小伙伴的父母生日也会收到公司的祝福还有礼品哦，中秋节、端午节公司定制礼品，</p><p><strong>福利</strong></p><ol><li>工作氛围：团队成员以 90 后为主，年轻有活力，上班期间可自由播放音乐，提供丰富美味下午茶（蛋糕、水果、零食），每季度一次聚餐，力造一个轻松愉快的工作环境，在愉快中高效工作。</li><li>旅游团建：公司安排每年 1-2 次国内外旅游团建，目前已去过珠三角、广西湖南、云南黑龙江等热门旅行地，优秀员工有机会国外游，快来和我们一起玩转地球吧！</li></ol>', '1-3年', '1fac20f2956d4d7c0nFz29S6F1FX', '深圳 · 宝安区 · 沙井', '8-11K', 'Java, SpringCloud, MySQL, 领星, ERP开发经验, Python, 金蝶云星空', '金蝶云星空二开工程师（双休+食堂+宿舍）', 'https://www.zhipin.com/job_detail/1fac20f2956d4d7c0nFz29S6F1FX.html', '节日福利, 包住, 带薪年假, 定期体检, 底薪加提成, 保底工资, 员工旅游, 宿舍有空调, 绩效奖金, 免费班车, 餐补, 交通补助, 工龄奖, 生日福利, 年终奖, 团建聚餐, 有无线网, 零食下午茶, 五险一金, 包吃');
INSERT INTO `jobs` VALUES (67, '深圳车圈圈科技', '通信/网络设备', '0-20人', '未融资', '本科', '<p><strong>工作内容</strong></p><ol><li>负责公司Java相关项目的开发与维护工作。</li><li>参与系统设计，确保代码质量，配合完成模块测试。</li><li>快速响应并解决技术问题，保障系统稳定运行。</li><li>熟悉呼叫中心的优先5、熟悉freeswitch的优先6、熟悉Linux系统的优先7、英语6级的优先8.熟悉通信设备方面优先9.公司上班时间9点到18点30分，午休1个半个小时，大小周9.公司主营海外电话和短信通信设备供应商10.工资待遇8k-15k</li></ol><p><strong>任职要求</strong></p><ol><li>具备扎实的Java编程能力，熟悉Spring等主流框架。</li><li>熟练使用MySQL，具备良好的SQL编写能力。</li><li>具有良好的团队合作精神，能够有效沟通，具备较强的问题解决能力。</li></ol>', '1-3年', '5f733af7462d406b03d53di6FlVU', '深圳 · 龙华区 · 民治', '8-13K', 'Java, Nginx, 不接受居家办公, Tomcat, C, Linux, MySQL, Redis, 呼叫中心, 架构设计经验, Spring', '中级java开发工程师', 'https://www.zhipin.com/job_detail/5f733af7462d406b03d53di6FlVU.html', '保底工资, 绩效奖金, 五险一金');
INSERT INTO `jobs` VALUES (68, '东舟科技', '电子商务', '0-20人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>根据公司各跨境电商平台实际业务运营情况，主导负责公司内部全链路智能系统架构设计、自研开发与迭代升级，覆盖选品、供应链、仓储库存、店铺运营等全业务模块（实现AI自动化选品→采购→仓储库存→物流履约→生图/⽣视频→⽂案→listing制作→上架发布→运营数据等全业务闭环功能），推动业务智能化、数字化提效。</li><li>对接亚马逊SP-API，以及领星第三⽅ERP或业务平台接口，实现订单、商品、库存、广告、报表等数据的同步与整合。</li><li>深度对接跨境业务，精准拆解选品、运营、采购、物流等业务需求，转化为落地可⾏的技术方案，独立完成ERP开发、测试、上线、优化全流程。</li><li>基于Claude、Codex等AI工具进行二次开发与场景落地，优化业务自动化流程，降低人工成本，提升运营效率。</li><li>负责系统日常维护、bug修复、性能优化，持续迭代适配多平台跨境业务规则与玩法更新。</li><li>协同运营、供应链团队沟通协作，梳理业务流程，输出标准化技术文档，保障系统稳定高效运行。</li></ol><p><strong>任职要求</strong></p><ol><li>统招本科及以上学历，计算机、软件工程、人工智能等相关理科专业；至少2年以上跨境电商ERP项目开发实操经验，理解跨境电商多平台运营逻辑（亚马逊、美客多、TikTok优先），熟悉选品、供应链、仓储库存、店铺运营等全业务闭环流程；曾任职领星/赛狐等ERP企业优先考虑。</li><li>熟练掌握Python/Java/Go任一主流技术栈，熟悉Vue、React等前端框架，开发基础扎实，代码规范，具备独立项目开发、问题排查能力，可独立承接完整业务模块开发。</li><li>熟练使用 Claude、Codex 等AI开发工具，并能对AI生成代码进行审查、调试和优化。</li><li>具备全链路系统思维，逻辑清晰，擅长梳理复杂业务流程，能精准将业务需求转化为技术方案。</li><li>沟通协作能力强，悟性高，能快速理解业务诉求，主动推进项目迭代，适配小企业灵活高效的工作节奏。公司</li></ol><p><strong>福利</strong></p><p>【上班时间】双休，每日在岗7.5小时（9:00-12:00 13:30-18:00）~不内卷，高效干活。【薪资保障】提供行业有竞争力的薪酬及激励机制~入职购买社保保险，每月10号发薪。【假期</p><p><strong>福利</strong></p><p>】法定节假日、带薪年假、婚假、产假等一应俱全。【重视人才】积极向上的年轻伙伴，团队氛围纯粹，管理轻松人性化，没有层层束缚，工作想法、优化建议都可以大胆提出，沟通高效不内耗。【配置齐全】虽为精简小团队，但各职能部门配置完整；专属 AI 团队全程助力，减负提效，帮助聚焦核心业务。【灵活试用期】试用期表现突出，可提前转正~不用等满期限，节奏由你的产出决定。【休闲下午茶】零食天天有，下午茶周周约，生日会暖心相聚，工作之余乐享美好。【员工关怀】春节、女生节、端午、中秋、圣诞节……节日礼品不断。【文化活动】定期组织羽毛球、聚餐、户外团建等丰富多彩的集体活动。【便利交通】 距离5号线民治站A出口约200米~通勤不折腾，上班好心情。</p>', '1-3年', 'd4de007eecdd20df0nJ73ty5F1JX', '深圳 · 龙华区 · 民治', '11-16K', 'Golang, Java, 亚马逊/美客多, 分布式经验, PostgreSQL, ERP开发经验, Claude/Codex, AI智能化, Docker, 跨境ERP系统开发, 内部自动化系统, 架构设计经验, Python', '双休跨境软件开发工程师（内部自动化系统）', 'https://www.zhipin.com/job_detail/d4de007eecdd20df0nJ73ty5F1JX.html', '团建聚餐, 生日福利, 五险, 节日福利, 零食下午茶, 年终奖, 带薪年假, 员工旅游, 绩效奖金');
INSERT INTO `jobs` VALUES (69, '航鸿达科技', '物联网', '100-499人', '未融资', '本科', '<p><strong>工作职责</strong></p><p>1、负责iot物联网(物模型)平台系统的开发和维护2、负责开发需求分析并解决软件开发过程中的问题3、负责线上问题排查，回复客户对接api过程中产生的问题</p><p><strong>岗位要求</strong></p><ol><li>全日制本科以上，具有2年以上JAVA后端开发以及微服务框架，数据库工作经验;</li><li>熟悉面向对象设计原则、设计模式，熟悉iot物联网开发方向优先;</li><li>能够熟练使用docker、nginx、Kafka、Redis、mysql、rocketMq等，熟练使用各种Java中间件技术;</li><li>熟悉Git等项目管理和持续集成工具，能够独立排查系统问题;</li><li>具备对应用业务有较强的理解能力，具有良好的编程习惯和开发规范;</li><li>责任心强，自我约束力强，具备良好的团队合作精神和承受压力的能力。</li><li>仅线下面试，大小周不接受勿扰哦</li></ol>', '1-3年', '346065df8048e05403d70ty6FVVR', '深圳 · 宝安区 · 沙井', '12-16K', 'Java, Nginx, 物联网经验, Docker, 微服务经验, Kafka', 'Java中级开发工程师', 'https://www.zhipin.com/job_detail/346065df8048e05403d70ty6FVVR.html', '年终奖');
INSERT INTO `jobs` VALUES (70, '深圳市中创智宇科技', '互联网', '20-99人', '', '本科', '<p>1、本科自考、函授等学信网可查即可2、2年以上Java开发经验3、有大型项目经验优先，有从0-1开发项目经验优先</p>', '1-3年', '2d57f25b62d8d8eb0nJ72tW7E1RV', '深圳 · 福田区 · 上步', '8-11K', 'Java, 微服务经验, SpringCloud, MySQL', 'Java', 'https://www.zhipin.com/job_detail/2d57f25b62d8d8eb0nJ72tW7E1RV.html', '');
INSERT INTO `jobs` VALUES (71, '冰兰智能', '人工智能', '20-99人', '未融资', '本科', '<p><strong>职位描述</strong></p><p>负责构建与优化基于大语言模型（LLM）的智能应用系统，推动AI技术在业务场景中的落地。</p><p><strong>核心职责</strong></p><ol><li>构建大模型与业务系统的数据交互管道，优化模型调用效率与稳定性。· 核心系统开发1)使用Java技术栈（SpringBoot/SpringCloud）开发高并发、分布式后端服务，保障系统高性能与高可用。熟悉使用MySQL、PostgreSQL数据库设计及性能优化，Elasticsearch全文检索方案实现，RabbitMQ消息队列开发。· 智能语音集成（优先方向）1)对接呼叫中心系统，开发集成TTS（文本转语音）、ASR（语音识别）、降噪算法等模块的智能语音交互功能。</li><li>使用Docker容器化技术部署服务，参与CI/CD流程设计与优化，提升交付效率。</li><li>攻克大模型应用中的技术难点（如延迟优化、提示工程、流式响应等），编写技术文档并与算法团队紧密协作。</li></ol><p><strong>任职要求</strong></p><p>· 计算机科学、软件工程或相关专业本科及以上学历。· 扎实的计算机基础，熟悉数据结构、设计模式、多线程及分布式系统原理。· 精通Java及SpringBoot/SpringCloud生态，具备微服务架构设计和开发经验。· 熟练使用MySQL/PostgreSQL数据库，掌握SQL优化及事务管理机制。· 熟悉RabbitMQ消息中间件应用场景，具备Elasticsearch检索方案实战经验。· 掌握Docker容器化部署，了解Kubernetes者优先。· 大模型相关：具备大模型API集成经验，熟悉LangChain、LlamaIndex等框架者优先。加分项（优先考虑）智能语音领域：· 熟悉呼叫中心系统（如FreeSWITCH、Asterisk）开发，或具有TTS/ASR引擎（如阿里云语音、讯飞引擎）集成经验。 · 了解音频降噪算法（如RNNoise、WebRTC NS）或实时音频流处理技术。工程效能：· 熟悉DevOps工具链（GitLab CI），有性能调优或高并发系统设计经验。· 了解Prometheus/Grafana监控体系，具备云服务（火山引擎/阿里云/华为云）开发经验。</p>', '1-3年', 'cee22207ea549ba2031z09u9GFZV', '深圳', '10-15K', '', 'Java开发工程师', 'https://www.zhipin.com/job_detail/cee22207ea549ba2031z09u9GFZV.html', '团建聚餐, 五险一金, 绩效奖金, 生日福利, 年终奖, 节日福利, 零食下午茶, 餐补, 员工旅游, 股票期权, 加班补助, 带薪年假');
INSERT INTO `jobs` VALUES (72, '医友天下科技', '医疗健康', '20-99人', 'A轮', '本科', '<p><strong>工作职责</strong></p><ol><li>参与物联网设备(MQTT)接入、开发远程控制、测试和部署</li><li>参与AI 开发 python开发、测试和部署</li><li>参与后端开发、测试和部署</li></ol><p><strong>岗位要求</strong></p><ol><li>本科以上学历、计算机、物联网、AI等相关专业 2.有java项目开发、需求分析、功能设计经验 3.熟练Spring boot,SpringCloud,MyBatis等主流JAVA开发杠架，熟悉Mysql，redis，MogngoDB 4.具备物联网设备和AI领域有浓厚兴趣和理解 5.有强烈的责任心和团队精神，善于沟通和合作，对技术敏感,喜欢钻研； 加分项目:</li><li>有物联网(IOT)或AI方面有实际项目经验 2.有python方面有实际项目经验</li></ol>', '1-3年', '616ae6dd2a511c6803B82d-_FFJS', '深圳 · 龙岗区 · 龙岗中心城', '9-14K·13薪', 'Java, 物联网经验, 分布式经验, 微服务经验, SpringCloud, MySQL, Redis, MongoDB, Spring, Python', 'java全栈工程师', 'https://www.zhipin.com/job_detail/616ae6dd2a511c6803B82d-_FFJS.html', '工龄奖, 节日福利, 带薪年假, 通讯补贴, 员工旅游, 定期体检, 五险一金, 股票期权, 交通补助, 年终奖');
INSERT INTO `jobs` VALUES (73, '沙山路投资', '投资/融资', '0-20人', '未融资', '本科', '<p>寻找有能力、有理想、想改命、肯努力、有态度的团队骨干！【</p><p><strong>岗位职责</strong></p><ol><li>基于⼤模型能力，搭建和优化 Agent、Workflow、Evolve、RAG、工具调⽤、记忆管理等核心模块。</li><li>负责 AI 工作流和智能体系统设计，打通任务拆解、执行、反馈、异常处理等完整链路。</li><li>基于用户反馈、运行日志、评测结果，持续优化 Prompt、检索、策略和执行效果，推动 AI 系统不断自我进化。</li><li>负责相关后端服务、接口、部署和工程化建设，保障系统稳定、高效、可扩展。</li><li>与产品、开发、运营等团队紧密协作，推动 AI 能力真正落地到业务中。【</li></ol><p><strong>任职要求</strong></p><ol><li>熟悉 Python、Java 等一至两门语言，具备良好的工程开发能力。</li><li>熟悉大模型应用开发相关技术，如 Prompt、RAG、Embedding、向量检索、Function Calling、Memory、Tool Use 等。</li><li>有 Agent、Workflow、知识库问答、自动化流程、企业 Copilot 等相关项目经验者优先。</li><li>熟悉 LangChain、LangGraph、LlamaIndex、Dify、AutoGen、CrewAI、Flowise 等框架或平台者优先。</li><li>具备后端基础，熟悉数据库、接口开发、Docker、Git、服务部署等能力。</li><li>逻辑清晰，执行力强，能独立解决问题，也能推动跨团队协作。</li><li>为人踏实本分，有责任心，有理想，想抓住 AI 时代机会，愿意和公司一起成长。【我们提供什么】1. 公司计划 3-5 年实现 IPO，核心骨干有机会获得 500万-1000万元人民币 股票期权。</li><li>公司提供工作餐，让你专注搞事业。</li><li>直接参与公司核心 AI 产品和业务系统建设，成长空间大，机会多，不做边缘角色。</li></ol>', '1-3年', 'fc20657b3fa518dd0nd63dS1FVRW', '深圳 · 南山区 · 科技园', '10-15K', 'Python, MySQL, 架构设计经验, 不接受居家办公', 'AI应用工程师-工作流 / Agent / 自我进化', 'https://www.zhipin.com/job_detail/fc20657b3fa518dd0nd63dS1FVRW.html', '包吃, 股票期权');
INSERT INTO `jobs` VALUES (74, '深圳思能动力科技有限', '其他制造业', '20-99人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责PLM系统功能开发、功能迭代与接口开发，配合团队完成ERP、CRM、SRM等企业系统的功能迭代与跨系统接口集成、数据对接工作。</li><li>参与项目需求分析、业务梳理与技术方案设计，独立完成PLM核⼼模块编码开发、迭代优化及单元测试，保障功能稳定落地。</li><li>具备全栈独⽴开发能⼒，负责接口与代码优化、逻辑重构，提升系统性能、并发能力及运行稳定性。</li><li>编写完善技术、接口相关⽂档，协助排查系统部署及运维过程中的技术问题，保障系统平稳运行。</li></ol><p><strong>岗位要求</strong></p><ol><li>学历：本科及以上学历（能力优秀者可放宽至大专），计算机、软件工程、信息技术等相关专业。</li><li>经验：拥有1-3年Java后端开发工作经验，有企业级业务系统开发经验优先，有制造业经验的优先。</li><li>技能要求：•有鼎捷PLM二次开发、系统集成或制造类企业项目开发经验者优先。•熟练使用MySQL、SQL Server主流数据库，精通SQL编写、索引优化、慢查询优化，掌握Redis、MongoDB等NoSQL缓存技术及实际落地应用；•熟练掌握Spring Cloud微服务架构体系，了解容器化部署相关技术，适配企业微服务项目开发；•熟悉RESTful API接口开发规范，熟练完成前后端、跨系统接口联调，了解RabbitMQ、RocketMQ、Kafka等主流消息队列的使用场景及开发应用；•了解Vue、React前端技术栈，熟悉低代码平台，能够独立完成简单前端页面开发调试，具备全栈开发能力者优先；•熟悉Linux服务器环境，具备项目部署、日志排查、问题定位分析能力，熟练使用Git版本控制工具；•熟悉 Activiti 流程引擎，了解多租户系统开发；•了解 Java C/S 架构、RMI 调用、JFace 组件库；</li></ol>', '1-3年', 'b7b9e07cb2bca90e0nF42d-_FVNX', '深圳 · 坪山区 · 坪山', '12-18K', 'MES开发经验, Java, Tomcat, 不接受居家办公, SpringCloud, MySQL, Kafka, Redis, MongoDB, Spring, ERP开发经验', 'Java开发工程师', 'https://www.zhipin.com/job_detail/b7b9e07cb2bca90e0nF42d-_FVNX.html', '五险一金, 免费工装, 员工旅游, 年终奖, 意外险, 零食下午茶, 节日福利, 绩效奖金, 带薪年假, 团建聚餐, 工龄奖');
INSERT INTO `jobs` VALUES (75, '深圳天夏智合科技', '计算机软件', '0-20人', '天使轮', '本科', '<p>AI协同开发：基于公司boss自研的AI原生应用开发平台，通过精准的需求拆解和逻辑描述（Prompt），引导AI完成绝大部分Java后端代码的⽣成。代码审查与把关：作为代码的“最终责任⼈”，对AI⽣成的代码进行严格的Code Review，排查逻辑漏洞、安全隐患及性能瓶颈。架构与系统设计：负责核心业务的系统架构设计、数据库表结构设计及API规范制定，为AI⽣成代码提供清晰的框架边界。复杂逻辑攻坚：手动编写、完善和调试AI难以处理的少量复杂业务逻辑、底层核心算法或第三方复杂系统对接。质量保障：主导系统排错与调优，沉淀AI辅助开发的最佳实践，协助优化内部AI开发平台的效能。【</p><p><strong>任职要求</strong></p><p>】扎实的技术底盘：本科及以上学历，半年以上Java后端开发经验。精通Java基础、JVM、并发编程，熟练掌握Spring Boot/Spring Cloud等主流生态（注：因为要审查代码，基础必须极度扎实）。极强的代码阅读与审查能力：具备“火眼金睛”，能快速理解他人（或AI）编写的代码，对代码规范、设计模式、代码坏味道（Smell）有极高的敏感度。优秀的系统抽象能力：具备扎实的数据库设计（MySQL/Redis等）和微服务架构能力，能将复杂业务精准拆解为高内聚、低耦合的模块。AI工具使用与逻辑表达：对AI大模型有强烈兴趣并有日常使用习惯；具备优秀的逻辑思维和文字表达能力，能清晰、准确地向AI描述技术需求。严谨负责：具备极强的责任心和细节控特质，不放过任何一个潜在的Bug。熟悉Prompt Engineering（提示词工程），或有AI Agent、LLM相关应用开发经验者优先。活跃的开源社区贡献者优先。</p>', '1-3年', '3101611e9d3839250nZ-09u5GVFQ', '深圳 · 南山区 · 科技园', '10-12K', '', 'Java后端开发工程师（AI研发方向）', 'https://www.zhipin.com/job_detail/3101611e9d3839250nZ-09u5GVFQ.html', '绩效奖金, 年终奖, 五险一金');
INSERT INTO `jobs` VALUES (76, '数新智能', '互联网', '100-499人', 'A轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>参与公司自主研发产品的设计、开发、优化及升级工作；</li><li>负责项目的技术方案制定与提交，调研与⽐较不同技术⽅案的优缺点，并根据实际条件选择合理的技术⽅案；</li><li>高质量完成项目的研发⼯作，组织项目组进行代码review；</li><li>发现项目组研发过程中出现的问题，并予以优化、解决，以提升研发效率和研发质量；</li></ol><p><strong>任职要求</strong></p><ol><li>计算机或软件工程相关专业本科及以上学历；</li><li>扎实的计算机基础知识，对操作系统、网络、数据结构及算法等有较为深入的理解；</li><li>精通Java编程语言，熟练掌握JVM原理及调优，熟练掌握Web后端开发框架；</li><li>熟悉MySQL数据库，熟悉其工作原理、数据库设计、SQL优化、存储优化等；</li><li>熟悉Linux系统，熟练使用各种Linux常用命令及组件，熟悉常用的运维工具和问题排查方法；</li><li>熟练掌握中间件技术的原理及使用方法，包括消息队列、远程过程调用、分布式事务、服务发现与路由等；</li><li>熟悉云原生技术，熟练使用Docker和K8s框架，熟悉各个组件流程及原理，具备丰富的微服务开发经验，熟练使用Gitlab/Jenkins/Harbor/Nexus/Minio等CI/CD工具；</li><li>具备良好的需求分析能力、业务和技术方案策划和设计能力。</li></ol>', '1-3年', '8e535c8d74a0a9ad0ndz3Ny0F1BQ', '深圳 · 南山区 · 科技园', '12-20K', 'Java, Spring, MySQL', '后端开发工程师', 'https://www.zhipin.com/job_detail/8e535c8d74a0a9ad0ndz3Ny0F1BQ.html', '育儿假, 补充医疗保险, 餐补, 零食下午茶, 员工旅游, 定期体检, 节日福利, 包吃, 五险一金, 年终奖, 带薪年假');
INSERT INTO `jobs` VALUES (77, '讯鹏科技', '互联网', '100-499人', '不需要融资', '本科', '<p><strong>一、任职要求</strong></p><ol><li>本科以上学历（开发经验丰者可放宽为大专）；</li><li>熟悉（苍穹）金蝶云星空旗舰版开发平台，能独立完成功能模块开发、插件开发、报表开发等；</li><li>熟悉⾦蝶BOS开发平台，独⽴完成表单配置和逻辑开发；</li><li>懂⼀般制造行业业务流程；</li><li>3年以上Java开发经验，有金蝶ERP系统⼆次开发经验；</li><li>熟练掌握 Java / JDK 1.8，熟悉常用设计模式及多线程编程；</li><li>有实际的生产环境部署经验，熟练使用Linux、Docker；</li><li>熟练掌握Vue、Uniapp前端开发技术；</li><li>熟悉Claude code或者Codex；</li><li>熟悉主流数据库(有金蝶AI套件开发经验、了解苍穹平台、飞书生态、有ERP与 OA/MES/PLM/WMS 系统集成项目、企业数据平台建设经验任意一项优先)</li></ol><p><strong>二、岗位职责</strong></p><ol><li>承接各业务部门的个性化需求，将业务需求转化为可落地的技术方案，独立完成ERP定制功能开发，满足各部门的需求；</li><li>各系统集成开发。包含不限于OA、PLM、MES、CRM数据接口开发，保障跨系统数据交互顺畅准确;</li><li>按照规范编写代码注释、开发文档以及用户操作手册，保障项目可交付、可维护;</li><li>配合实施与运维团队完成功能测试、上线部署，处理系统运行过程中出现的数据问题与功能异常，保障系统稳定运行;</li><li>其它系统、平台的建设任务。如数据平台、经营看板等。</li></ol>', '1-3年', 'e2951aaa67ff64a20nB839i0FFdR', '深圳 · 龙岗区 · 丹竹头', '11-20K·13薪', 'Java, Docker, MySQL, ERP开发经验, 金蝶ERP, 金蝶ERP云星空', '软件开发工程师（金蝶ERP系统）', 'https://www.zhipin.com/job_detail/e2951aaa67ff64a20nB839i0FFdR.html', '有无线网, 通讯补贴, 加班补助, 生日会, 住房补贴, 餐补, 工龄奖, 宿舍有空调, 节假日加班费, 带薪年假, 绩效奖金, 生日福利, 部门团建, 五险一金, 年终奖, 免费工装, 包住, 全勤奖, 员工旅游, 团建聚餐');
INSERT INTO `jobs` VALUES (78, '深圳市盈汇环球科技', '电子商务', '0-20人', '', '本科', '<p>岗位boss</p><p><strong>职责</strong></p><ol><li>负责Java语言的软件开发及系统维护工作；</li><li>参与项目需求分析与技术方案设计，完成模块开发任务；</li><li>编写⾼质量、可维护的代码，持续优化系统性能；</li><li>配合团队完成系统集成、测试与上线⽀持；</li></ol><p><strong>任职要求</strong></p><ol><li>熟悉Java编程语⾔及相关主流开发框架；</li><li>了解常用数据库操作及SQL编写；</li><li>具备良好的逻辑思维和问题解决能力；</li><li>具有较强的团队协作意识和责任⼼；</li></ol>', '1-3年', '32a78e0aa54aa73c0nF8296_EVNR', '深圳 · 龙岗区 · 坂田', '15-16K', '不接受居家办公, C, SpringCloud, Oracle, 架构设计经验', 'Java', 'https://www.zhipin.com/job_detail/32a78e0aa54aa73c0nF8296_EVNR.html', '');
INSERT INTO `jobs` VALUES (79, '千百炼科技', '互联网', '20-99人', '未融资', '本科', '<ol><li>公司文化：管理宽松，靠自觉，多劳多得，不自觉的，平时不学习的、养⽼摸鱼的不要来。</li><li>⼯资构成：基本⼯资+岗位工资70%，绩效工资30%（做得好，绩效⼯资能翻倍）。</li><li>业务：主要是给气象局做软件系统开发维护、智能体开发。</li><li>十多人的团队。能接受的再投简历！</li></ol><p><strong>岗位职责</strong></p><ol><li>使用 Java 开发多智能体（Agent）系统，实现工具调用、流程编排、自主决策。</li><li>对接大模型，完成 Agent 工程化、服务化与高可用部署。</li><li>设计并实现 RAG、知识库、插件化能力，落地业务场景。</li><li>优化 Agent 稳定性、响应速度与执行准确率。</li></ol><p><strong>岗位要求</strong></p><ol><li>扎实 Java 后端，熟练 Spring Boot、微服务、中间件。</li><li>了解 LLM、Agent、FunctionCall、RAG 基本原理。</li><li>有智能体/大模型应用开发、向量库使用经验优先。</li><li>学习能力强，能快速落地 AI 业务。有气象软件开发经验或大模型微调经验优先</li></ol>', '1-3年', '151fc177931cddab0nZ_2t65FlJX', '深圳 · 龙岗区 · 布吉', '9-14K', '智能体, Java, PostgreSQL, SpringCloud, Redis, 大模型, 微服务经验, MySQL, MyBatis, Spark, 架构设计经验, openclaw, Oracle', 'Java大模型/智能体开发工程师', 'https://www.zhipin.com/job_detail/151fc177931cddab0nZ_2t65FlJX.html', '全勤奖, 法定节假日三薪, 意外险, 节假日加班费, 员工旅游, 加班补助, 年终奖, 节日福利, 有无线网, 夜班补助, 带薪年假, 五险一金, 股票期权');
INSERT INTO `jobs` VALUES (80, '妍希美', '电子商务', '100-499人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责AI Agent系统的技术方案设计、开发、调试、部署和维护。</li><li>根据业务场景设计Agent能力，包括意图识别、多轮对话、任务拆解、信息检索、工具调用和结果反馈。</li><li>搭建垂类知识库，⽀持业务规则、操作流程、⾏业知识、平台⽂档等内容的检索与问答。</li><li>设计并优化 Prompt、Agent行为规则、上下文管理、记忆机制和回答约束。</li><li>接⼊业务系统接口，使Agent能够读取必要数据并完成指定辅助任务。</li><li>支持Agent调用第三方工具或内部工具，包括AIGC工具、数据查询工具、内容处理工具等。</li><li>设计Agent的异常兜底、人工接管、权限控制、操作确认和日志记录机制。</li><li>建立Agent效果评估机制，持续优化回答准确率、任务完成率、用户满意度和安全性。</li><li>配合产品、设计、前端、后端和AIGC团队完成Agent功能落地和体验优化。</li></ol><p><strong>任职要求</strong></p><ol><li>有AI Agent、LLM应用、智能客服、RAG、AI Copilot或工作流自动化相关开发经验。</li><li>熟悉至少一种 Agent或LLM应用开发框架，如LangChain, LangGraph, Llamalndex, AutoGen, CrewAI、OpenAI Agents SDK 或同类框架。</li><li>熟悉大模型 API接入，包括OpenAl、Claude、Gemini、DeepSeek、Qwen、火山引、智谱、MiniMax等任一模型服务。</li><li>熟悉Prompt Engineering、函数调用、工具调用、结构化输出、多轮对话和上下文管理。</li><li>熟悉RAG知识库搭建流程，包括文档切分、向量化、召回、重排、引用溯源和回答约束。</li><li>能够将复杂业务流程拆解为Agent可执行的任务链路，而不是只做简单聊天机器人。</li><li>具备基础后端开发能力，能够与业务接口、数据库、任务队列和第三方API对接。</li><li>具备良好的产品理解能力，能够判断哪些任务适合Agent自动处理，哪些任务需要人工确认。</li><li>重视模型输出风险、数据权限、用户隐私和业务安全边界。加分项1.有影视、短剧、新媒体、内容平台、交易平台、创作者平台或垂直行业Agent经验。</li><li>有智能客服、销售助手、运营助手、项目管理助手、创作助手或企业知识库问答系统经验。</li><li>有 Tool Calling、 Workflow Agent, Multi-Agent, Planning Agent, Browser Agent 或 Background Agent开发经验。</li><li>有AIGC工具调用经验，能够让Agent调用图片生成、视频生成、文案生成、分镜生成或素材生成等工具。</li><li>熟悉业务流程型SaaS、撮合平台、电商平台、B2B平台或复杂后台系统。</li><li>有Agent评测体系建设经验，能够设计测试集、任务成功率评、幻觉检测和人工回归测试流程。</li><li>有Agent权限控制、人工接管、操作确认、日志审计和异常兜底经验。</li><li>有前端Agent交互经验，如聊天侧栏、任务卡片、状态流、建议按钮、轻提示和后台任务提醒。合作要求:</li><li>能够根据 PRD、业务流程和产品原型拆分Agent功能模块，并评估开发排期。</li><li>能够输出Agent技术方案、Prompt规则、工具调用方案、知识库结构和评测方案。</li><li>对Agent的准确性、可控性、可解释性</li></ol>', '1-3年', '659aa14e96d9543c0nFy2NS8EVtU', '深圳', '15-20K', 'Java, 不接受居家办公, 需要外出, 双休, AI, LLM, API', 'AI Agent工程师', 'https://www.zhipin.com/job_detail/659aa14e96d9543c0nFy2NS8EVtU.html', '节日福利, 全勤奖, 员工旅游, 带薪年假, 五险一金, 零食下午茶');
INSERT INTO `jobs` VALUES (81, '宏逸信息', '医疗健康', '20-99人', '不需要融资', '大专', '<p><strong>岗位职责</strong></p><ol><li>参与项目的需求分析和技术方案设计，能独立完成项目模块开发；</li><li>负责相关技术文档的撰写和维护；</li><li>分析并解决开发中遇到的问题，维护线上系统的稳定性；</li><li>能够对技术难点进行攻关，具备一定的技术研究能力；</li><li>注重系统高可用、可靠、可扩展及安全方面的细节；</li><li>具有良好的团队合作和沟通能力。</li></ol><p><strong>任职要求</strong></p><ol><li>全日制大专以上学历，计算机相关专业，1年以上基于JAVA开发经验；</li><li>熟悉JavaEE技术，熟练掌握JAVA主流框架Springboot、springMVC、Mybatis等3、熟悉JavaScript，有Jquery等框架使用1-3年经验，具有丰富JavaScrpit调试经验；</li><li>熟悉Dubbo、Spring-cloud等服务框架，并对系统微服务化拆分有一定的理解；</li><li>熟悉RabbitMQ、Redis、Nginx等主流消息中间件；</li><li>熟悉Web容器Tomcat、Jboss、Weblogic等，以及能了解运行原理和机制，有一定调优经验；</li><li>熟悉Oracle、Mysql等主流数据库，有参与过数据库设计工作；</li><li>具有并发编程意识，能处理并发情况下的系统开发工作。</li><li>有医疗信息系统平台开发经验优先，有自助终端服务系统开发经验优先。</li><li>熟悉.net 开发优先考虑。</li></ol>', '1-3年', '88eb759b90f3bea31HN539-9F1dQ', '深圳 · 龙岗区 · 横岗', '6-11K', 'Java, Nginx, 不接受居家办公, Tomcat, Redis, 自助机, SQL Server, Spring, 自助终端, 医疗信息, 自助系统, 架构设计经验, Oracle', 'java开发工程师', 'https://www.zhipin.com/job_detail/88eb759b90f3bea31HN539-9F1dQ.html', '带薪年假, 绩效奖金, 年终奖, 五险一金');
INSERT INTO `jobs` VALUES (82, '深圳仟维动力智能科技', '智能硬件/消费电子', '0-20人', 'A轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>参与软件系统的设计与开发，协助完成模块编码工作；</li><li>根据指导完成接口对接、功能实现及基础测试；</li><li>配合团队进行系统调试和问题修复；</li><li>编写相关技术文档，参与代码评审与优化。</li></ol><p><strong>任职要求</strong></p><ol><li>具备扎实的编程基础，熟悉主流开发语言中的⼀种或多种；</li><li>了解常⽤数据结构、算法及数据库操作；</li><li>熟悉版本控制⼯具的基本使用，具备良好的代码规范意识；</li><li>具有较强的学习能力、沟通能⼒和团队协作精神。</li></ol>', '1-3年', '0a79c712911e2dd90nF829W9ElRZ', '深圳', '10-15K', 'Java, C, C++, Docker, JVM, MySQL, Spark, Hive', '软件开发实习生', 'https://www.zhipin.com/job_detail/0a79c712911e2dd90nF829W9ElRZ.html', '包吃, 绩效奖金, 零食下午茶, 有无线网, 员工旅游, 年终奖, 五险一金');
INSERT INTO `jobs` VALUES (83, '上海博达瑞科技', '互联网', '100-499人', '未融资', '本科', '<p>【岗位概boss述】负责开发和维护全球用户服务组相关系统boss的JAVA后端需求。【</p><p><strong>任职资格</strong></p><ol><li>熟练掌握 java1.8,Spring Boot, Spring Cloud, Spring MVC, MyBatis 等技术栈，并有实际微服务项⽬开发经验。</li><li>熟练使⽤ MySQL, Oracle 等至少一种数据库，具备良好的SQL编写及优化能⼒。</li><li>熟练使用 RabbitMQ, Redis, Kafka 等至少两种中间件，理解其使用场景与核心原理。</li><li>熟练使用 Linux 常用操作命令，能独立完成服务部署、日志排查及性能监控。</li><li>熟练使用 IDEA, Maven, Git 等开发与管理工具，具备良好的代码规范和工程化意识。</li><li>熟悉K8s的基本概念和操作流程，了解容器化部署。</li><li>有实际项目中使用AI代码助手的经验，熟悉基于大语言模型的代码生成、补全、解释及单元测试等常见AI辅助编程实践。其他：</li><li>有售后服务项目经验优先2、有AI智能体建设提效经验优先。</li></ol>', '1-3年', '842e7dd1963ddb390nZy2dq0F1FT', '深圳 · 南山区 · 科技园', '14-19K', 'Java, 不接受居家办公, SpringCloud, MySQL, Kafka, MyBatis, Redis', '中级java开发工程师', 'https://www.zhipin.com/job_detail/842e7dd1963ddb390nZy2dq0F1FT.html', '');
INSERT INTO `jobs` VALUES (84, '高竞文化', '互联网', '100-499人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责社交直播 App 的 C 端后台服务及 B 端运营系统的设计、开发与维护；</li><li>独立完成需求分析、技术方案设计、编码实现及上线支持，保障系统稳定运行；</li><li>参与代码 Review，持续优化代码质量、系统性能与架构可扩展性；</li><li>与产品、客户端、测试等团队协作，推动业务需求⾼质量落地；</li><li>在项⽬推进过程中沉淀技术⽂档、设计文档和业务知识，形成规范化、可复用的研发资产；</li><li>关注 AI 技术在研发场景中的应⽤，能够借助 AI 工具提升需求开发效率与交付质量。</li></ol><p><strong>岗位要求</strong></p><ol><li>本科及以上学历，1-3 年 Java 开发经验；</li><li>扎实的 Java 基础，熟悉 IO、多线程、集合等核心知识，理解常见设计模式并能灵活应用；</li><li>熟悉 Spring Boot、Spring Cloud Alibaba、Dubbo 等主流框架，了解其原理和机制；</li><li>熟悉分布式系统、缓存、消息队列等技术体系，具备高并发、高可用系统开发经验；</li><li>熟悉 JVM、Web、Redis、Kafka、RabbitMQ 等中间件及相关原理；</li><li>熟悉 MySQL、MongoDB，具备 SQL 优化经验，能结合业务场景合理设计数据存储方案；</li><li>有良好的开发规范意识，工作细致严谨，具备较强的文档编写、总结沉淀和知识传递能力；</li><li>能清晰输出技术设计思路、业务流程和功能使用说明，便于团队协作与后续维护；</li><li>具备较强的学习能力、沟通能力和团队合作精神，积极主动，执行力强；</li><li>能够使用 AI 工具辅助需求分析、开发实现和效率提升，对 AI 前沿技术有浓厚兴趣；</li><li>具备产品设计思维者优先，能够从技术视角对产品方案提出建设性建议；</li><li>有社交、直播相关产品开发经验者优先，包括但不限于社交类 App、音视频直播类 App、大型直播间业务及营收活动平台等；</li><li>有 K8s 容器化部署经验者优先。</li></ol>', '1-3年', '9faa47cc1f18d8c50nBz3d-9GVNT', '深圳 · 南山区 · 科技园', '9-14K', 'Java, SpringCloud, MySQL, 游戏后端经验, 语音社交, 音频直播', 'Java 开发工程师', 'https://www.zhipin.com/job_detail/9faa47cc1f18d8c50nBz3d-9GVNT.html', '零食下午茶, 节日福利, 团建聚餐, 社团活动, 员工旅游, 股票期权, 生日福利, 法定节假日三薪, 定期体检, 绩效奖金, 年终奖, 带薪年假, 补充医疗保险, 五险一金, 夜班补助');
INSERT INTO `jobs` VALUES (85, '东莞映界科技', '人工智能', '0-20人', '天使轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>参与软件系统的需求分析、设计、编码和测试⼯作；</li><li>根据项⽬计划完成代码编写与单元测试，确保开发进度和质量；</li><li>负责现有系统的维护、优化和性能提升；</li><li>编写相关技术⽂档，配合团队完成项目交付。</li></ol><p><strong>任职要求</strong></p><ol><li>具备计算机或相关专业背景；</li><li>熟悉主流编程语言和开发框架；</li><li>具有良好的沟通能⼒和团队协作精神；</li><li>能够独立解决问题，具备较强的学习能力。</li></ol>', '1-3年', 'd7dffe159a9997f10nJ70tm4F1pZ', '深圳', '15-16K', '不接受居家办公, Java, Zookeeper, MySQL, 团队管理经验, 架构设计经验', '软件开发工程师', 'https://www.zhipin.com/job_detail/d7dffe159a9997f10nJ70tm4F1pZ.html', '带薪年假, 五险一金, 绩效奖金, 定期体检');
INSERT INTO `jobs` VALUES (86, '枫果信息', '计算机软件', '0-20人', '', '本科', '<p>学历要求：统招四年制本科，双证齐全，学信⽹可查。初级: 2年以上，24个⽉以上社保缴纳记录。</p><p><strong>技术要求</strong></p><p>兴业海外产品团队托管项⽬组计划新增一名初级后端开发，主要技术栈要求：spring cloud，k8s，mockito，kafka，elasticsearch，ai编程，领域驱动设计，第一个也就是spring cloud必须，其他的可选但会的越多越好。总体可以要求业务理解不需要很深，但相关的纯技术能⼒要比较强比较熟练，进项目组也是主要负责做技术改造优化任务。</p>', '1-3年', 'ad7a00fa503c3fdc0nJ709W9GFJU', '深圳 · 福田区 · 香蜜湖', '12-13K', 'Java, SpringCloud, Docker, Elasticsearch, Kafka, Redis, 微服务经验, 分布式经验, k8s, mockito, ai编程, 域驱动设计', '初级java开发---深圳', 'https://www.zhipin.com/job_detail/ad7a00fa503c3fdc0nJ709W9GFJU.html', '通讯补贴, 带薪年假, 餐补, 节日福利, 交通补助, 五险一金');
INSERT INTO `jobs` VALUES (87, '北斗信息数据产业湖北', '通信/网络设备', '20-99人', '未融资', '本科', '<p><strong>一、岗位职责</strong></p><ol><li>负责后端系统开发、迭代、性能优化、线上故障排查，保障系统稳定运行；</li><li>基于 SpringBoot 技术栈开发业务接口，完成第三方服务、跨系统数据对接交互；</li><li>熟练使用低代码、物联⽹可视化、建站类平台快速搭建业务表单、流程、设备数据看板，快速落地业务功能；</li><li>编写 Python 脚本，实现数据同步、批量处理、⾃动报表等⾃动化任务；</li><li>负责数据库设计、SQL 编写与性能调优，完成多源数据清洗、指标建模、统计分析功能开发；</li><li>维护存量 PHP 业务系统，处理线上 BUG 与需求迭代；</li><li>规范输出接口、数据库设计等技术文档，配合版本测试上线。</li></ol><p><strong>二、 任职要求</strong></p><ol><li>本科及以上，计算机、软件⼯程、信息技术相关专业；</li><li>1 年及以上后端独立开发经验；</li><li>责任心强，逻辑清晰，学习能力、沟通协作良好，可适配项目迭代阶段性工作压力。三、硬性技术能力1. 熟练 Java 开发，精通 Spring、SpringBoot、Redis、Kafka 等主流框架与中间件；</li><li>精通 MySQL，掌握库表设计、索引、慢 SQL 调优，了解 Oracle、SQL Server；</li><li>掌握 PHP 开发，可独立完成存量系统 bug 修复、功能迭代；</li><li>熟悉 RESTful 接口规范，具备第三方系统对接开发经验；</li><li>可使用 Python 编写定时任务、数据处理类自动化脚本；</li><li>具备数据治理、指标建模、数据分析功能开发能力；</li><li>熟练运用低代码平台、物联网可视化平台、通用建站平台快速配置搭建业务流程、数据看板、业务门户。</li></ol>', '1-3年', 'e3af7de6ffbd4c420nFy0tu4EVJY', '深圳 · 龙岗区 · 横岗', '10-15K', '不接受居家办公, Java, Python, PHP, Spring, Oracle, SQL Server, 架构设计经验, 大数据经验', '后台开发工程师', 'https://www.zhipin.com/job_detail/e3af7de6ffbd4c420nFy0tu4EVJY.html', '保底工资, 五险一金, 加班补助, 年终奖, 绩效奖金, 员工旅游, 底薪加提成');
INSERT INTO `jobs` VALUES (88, '深圳市铂云瑞网络信息', '互联网', '100-499人', '天使轮', '本科', '<p><strong>职位描述</strong></p><ol><li>负责服务器端架构设计、web 端程序的设计及代码编写；</li><li>参与相关⽂档编写；</li><li>参与系统稳定性、性能和扩展性调整优化；</li><li>参与公司项⽬的实施和软件研发。</li></ol><p><strong>任职要求</strong></p><ol><li>计算机相关专业，本科以上学历，有较好的理论知识基础，具有⼯作经验；</li><li>熟悉Java开发，熟悉JVM、多线程、Socket编程、NIO等技术，熟悉常用的数据结构，了解常用的设计模式，拥有良好的编码习惯；</li><li>熟悉 springMVC、Netty、Springboot、SpringCloud 等主流开源框架并且能够对不同框架进⾏整合；</li><li>具备后端系统开发全栈技能，包括前后端 API 设计、加密、缓存技术、负载均衡；</li><li>熟悉 Nginx，Tomcat、Redis 使用经验，服务器监控；</li><li>熟悉主流关系/非关系型数据库如MySQL、mongodb等的设计和开发；</li><li>良好的沟通协作，乐于技术交流分享。</li></ol>', '1-3年', 'd7b6f94eeca17da20nFy39q1FlRS', '深圳 · 龙华区 · 龙华', '8-11K·13薪', 'Golang, JVM, Java, SpringCloud, MySQL, Netty, MongoDB, Python', '后端开发工程师', 'https://www.zhipin.com/job_detail/d7b6f94eeca17da20nFy39q1FlRS.html', '定期体检, 五险一金');
INSERT INTO `jobs` VALUES (89, '墨影科技', '智能硬件', '100-499人', 'A轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责工业机器人相关软件系统在工业互联网场景下的部署实施。</li><li>基于Java/Kotlin语⾔开展软件⼆次开发⼯作，根据客户业务需求及工业现场场景，完成功能定制、接口适配、数据交互逻辑优化等开发任务，确保系统满足⼯业生产实际需求。</li><li>对接工业现场客户，收集业务需求与使用反馈，梳理二次开发需求边界，协调研发团队确认技术方案，推进定制功能落地与验收。</li><li>排查解决实施及二次开发过程中的技术问题，包括Linux系统环境异常、数据库连接故障、Java/Kotlin代码Bug、工业现场系统适配冲突等，保障项目进度。 5 编写并完善实施相关技术文档，包括Linux部署手册、数据库操作指南、二次开发说明文档、系统运维手册及项目验收报告等，确保文档的准确性与实用性。</li><li>为客户提供工业机器人软件系统的操作培训、技术答疑及后续运维支持，协助客户快速掌握系统使用方法，提升客户满意度。</li><li>跟进项目实施进度，把控交付节点，协调内部产品、研发团队解决项目推进中的问题，确保项目按时、按质完成验收交付。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机、软件工程、自动化等相关专业优先；</li><li>具备 1-3 年以上代码开发经验，熟练掌握 Java/Kotlin 语言，能独立完成简单功能开发、接口适配等二次开发工作；</li><li>熟悉 MySQL、MongoDB 数据库，能熟练进行 SQL 编写、数据查询、表结构设计及基础维护操作；</li><li>熟练运用 Linux 常用命令，能独立完成软件安装、环境配置、日志排查及系统基础运维；</li><li>了解 MQTT、RabbitMQ 等消息中间件的基本原理与使用场景，能配合完成数据传输适配；</li><li>了解 Modbus 等工业通讯协议，具备工业现场设备数据对接、通讯调试的基础能力；</li><li>有工业互联网、工业软件实施或相关领域开发经验者优先；</li><li>具备良好的沟通协调能力、问题解决能力，能快速响应客户需求，适应短期出差及驻场实施。</li></ol>', '1-3年', 'f267a45745dfbb630nBy39u1GFpT', '深圳 · 宝安区 · 西乡', '10-15K', 'Java, 不接受居家办公, 机器人, MySQL, MongoDB, SQL Server', 'Java软件实施工程师', 'https://www.zhipin.com/job_detail/f267a45745dfbb630nBy39u1GFpT.html', '意外险, 免费工装, 高温补贴, 年终奖, 团建聚餐, 绩效奖金, 生日福利, 带薪年假, 交通补助, 股票期权, 五险一金, 法定节假日三薪, 定期体检, 节日福利, 零食下午茶');
INSERT INTO `jobs` VALUES (90, '深圳市屿智同行科技', '人工智能', '20-99人', 'A轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>负boss责 APP（C端）及企业端核心业务系统的后端设计与开发，基于 Spring Boot 构建高可用服务。</li><li>负责用户体系、权限体系、订单与⽀付、⾯试数据管理、推荐匹配接口等核⼼模块的设计与实现。</li><li>设计并优化高并发 RESTful API，保障系统在高峰期的稳定性与响应速度。</li><li>对接 AI 算法与推荐团队，完成⼤模型推理接口封装、评分系统接入与数据链路打通。</li><li>参与多模态数据（视频 / 语音 / 行为数据）存储与处理流程设计。</li><li>负责数据库建模、性能调优、缓存设计及线上问题排查。</li><li>参与系统架构优化、接口压测、稳定性建设与安全加固。</li></ol><p><strong>岗位要求</strong></p><ol><li>计算机相关专业优先，2年以上 Java 后端开发经验。</li><li>熟练掌握 Java 及 Spring Boot / Spring Cloud 技术栈。</li><li>熟悉 MySQL 数据库设计与优化，理解事务与索引原理。</li><li>熟悉 Redis 等缓存机制及常见应用场景。</li><li>熟悉 RESTful API 设计规范，具备良好的接口抽象能力。</li><li>熟悉 Linux 服务器环境与常规部署流程。</li><li>具备良好的编码规范与工程质量意识，能够独立负责模块开发。</li></ol>', '1-3年', '452f42339311392b0nB-3t29EFtU', '深圳 · 南山区 · 科技园', '18-30K·13薪', '', '后端开发工程师（Agent相关)', 'https://www.zhipin.com/job_detail/452f42339311392b0nB-3t29EFtU.html', '五险一金, 带薪年假, 零食下午茶, 股票期权, 定期体检, 法定节假日三薪, 年终奖, 绩效奖金, 节假日加班费');
INSERT INTO `jobs` VALUES (91, '普蓝机器人', '自动化设备', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>参与Java安卓相关系统的开发与功能实现，熟悉wifi p2p通信方式、熟悉websocket、熟悉json等，参与AI玩具的研发；</li><li>配合团队完成系统架构设计与技术方案制定；</li><li>负责代码编写、调试及性能优化，保障系统稳定运行；</li><li>协助完成项目⽂档的整理与维护。</li></ol><p><strong>任职要求</strong></p><ol><li>熟悉Java语⾔，具备扎实的编程能⼒；</li><li>了解常用开发框架及工具，具备独⽴开发能力；</li><li>具备良好的逻辑思维和问题分析能力；</li><li>有良好的沟通能力和团队协作意识。</li></ol>', '1-3年', 'be9d563f798afc590nRy2Nq7FlFZ', '深圳 · 宝安区 · 石岩', '10-11K', 'Java, 不接受居家办公, C++, SpringCloud, SQL Server, 架构设计经验, Spring', '中级java开发工程师', 'https://www.zhipin.com/job_detail/be9d563f798afc590nRy2Nq7FlFZ.html', '加班补助, 团建聚餐, 员工旅游, 有无线网, 带薪年假, 年终奖');
INSERT INTO `jobs` VALUES (92, '曦鲸', '计算机软件', '20-99人', '未融资', '大专', '<ol><li>跨境电商业务落地1）协助运营、客服、美工等团队把AI用到日常工作中。</li><li>⽀持选品分析、竞品调研、Listing优化、⼴告投放与优化、专利查询、客服回复、邮件处理、评论分析、产品资料整理、⽣图和视频脚本、利润核算、库存分析等场景;</li><li>根据业务反馈整理提示词模板、操作流程和案例，形成可复用⽅法;</li><li>对接领星、卖家精灵等跨境ERP工具与飞书生态，实现跨系统数据互通与流程自动化；</li><li>跟进使用效果，持续优化工具配置、提示词和流程。</li><li>Agent与工作流搭建1）使用claude code 和 codex等工具搭建简单Agent、知识库问答和自动化工作流;</li><li>将成熟的业务经验、提示词、操作步骤、文件模板和工具调用方式整理成可复用Skill;</li><li>沉淀常用Skill，如Listing优化、竞品调研、评论分析、客服邮件、广告投放与优化、产品资料整理等；</li><li>对Agent和工作流进行测试、排错、优化，并整理使用说明。</li><li>培训与文档1）编写工具教程、配置文档、SOP、FAQ和排障手册;</li><li>面向非技术同事做基础培训和日常答疑;</li><li>建立AI工具、Agent和自动化流程的使用。</li></ol><p><strong>任职要求</strong></p><ol><li>统招专科及以上学历，计算机、软件工程、自动化等相关专业优先，1年以上跨境电商AI开发项目落地经验(有完整工作流或Agent案例优先)；</li><li>对AI技术有深度理解，熟悉常用大模型GPT、Gemini、Claude Code、codex，了解大模型之间的差异化与适用场景；</li><li>熟练掌握至少一种编程语言（如Python/java）,了解Prompt Engineering，能够编写并优化提示词；</li><li>善于理解业务需求，能够独立完成流程梳理、方案设计、脚本开发及落地、推广培训全过程。</li><li>逻辑清晰、学习能力强，主动性强，乐于分享，能快速试错和迭代，具备优秀的跨部门沟通和需求分析能力。</li></ol>', '1-3年', 'd73227b5a79d64930nB73NS7GFFT', '深圳 · 龙华区 · 民治', '15-20K', 'Java, 不接受居家办公, MySQL, Redis, Spring', 'AI开发工程师', 'https://www.zhipin.com/job_detail/d73227b5a79d64930nB73NS7GFFT.html', '员工旅游, 零食下午茶, 年终奖, 节日福利, 股票期权, 五险一金, 带薪年假, 定期体检');
INSERT INTO `jobs` VALUES (93, '郑州宣延', '广告/公关/会展', '0-20人', '', '本科', '<p><strong>岗位职责</strong></p><p>参与互联网金融产品的后台业务系统开boss发和维护，负责系统架构设计、功能开发及性能优化；与团队成员紧密合作，确保项目按时交付，满足业务需求；参与业务数据库设计、优化及维护，确保数据安全与⾼效访问；参与技术难题攻关，提升系统的稳定性和扩展性。</p><p><strong>任职要求</strong></p><p>计算机科学或相关专业本科及以上学历，应届毕业⽣或1-3年相关⼯作经验，有保险业务开发经验优先；熟悉至少一种后端开发语⾔：Go、C++ 或 Java，具备良好的编程习惯和代码质量意识，能够理解并掌控AI 能力提升自己的开发效率熟悉数据库原理，有MySQL、PostgreSQL等关系型数据库开发经验，熟悉数据库设计原则，能够进行SQL优化和数据库性能调优；熟练使用Shell或Python脚本，能够编写自动化工具和脚本；具备良好的沟通能力和团队协作精神，能够承受工作压力。责任感强、有较强的逻辑思维能力、沟通能力和学习能力；有高性能、分布式系统以及熟悉微服务架构者优先。</p>', '1-3年', '08be9d007c60731e0nJ629y4GVZR', '深圳 · 南山区 · 科技园', '17-27K·17薪', 'C++, Java, MongoDB', '后台开发工程师（核心系统开发）', 'https://www.zhipin.com/job_detail/08be9d007c60731e0nJ629y4GVZR.html', '');
INSERT INTO `jobs` VALUES (94, '深圳招商永隆信息技术', '计算机软件', '100-499人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责Murex系统的升级和维护。</li><li>负责编写和执⾏⾃动化脚本，简化和优化系统管理任务跟踪和分析系统性能、⽇志和事件，诊断和解决问题制定和执行备份和恢复策略。</li><li>负责Murex报表开发。</li></ol><p><strong>任职要求</strong></p><ol><li>熟悉MySQL、ORACLE、SQL Server等主流数据库；熟悉Linux命令和shell脚本的编写。</li><li>有银⾏软件开发项目经验优先</li></ol>', '1-3年', '53713a764e431c6f0nB509u6FVZU', '深圳 · 龙岗区 · 平湖', '15-30K', 'Java, Hive, 不接受居家办公, SpringCloud, Spring', 'java开发工程师（Murex系统）', 'https://www.zhipin.com/job_detail/53713a764e431c6f0nB509u6FVZU.html', '通讯补贴, 年终奖, 节日福利, 五险一金, 补充医疗保险, 定期体检, 交通补助, 高温补贴, 绩效奖金, 餐补, 生日福利, 带薪年假, 节假日加班费');
INSERT INTO `jobs` VALUES (95, '上海舟恩信息', '计算机软件', '100-499人', '不需要融资', '本科', '<p>技术能力要求1. 掌握 Java 语言，熟练使用 Spring、SpringMVC、SpringBoot、SpringCloud、MyBatis 等开源框架2. 对常用的设计模式、设计原则、数据结构等有⼀定的理解和掌握，对⾯向对象思想有深⼊的理解3. 熟悉 Nginx、Redis、Kafka、Jenkins 等中间件的使用及部署；熟练使用 Linux 命令4. 熟练掌握 MySQL/ORACLE 等数据库，具备数据库分析 + 设计 + 开发的能⼒，有数据库性能调优经验5. 熟悉各种通讯接口，如：WebService、http、https、Restful、RPC，熟悉 OSI 网络模型及 TCP/IP 等通讯原理项目经验要求1. 至少 3 年以上 Java 开发经验，能够独立完成模块的设计与开发，有团险核心系统开发经验者优先。2. 有完整的项目开发经验，包括架构设计、编码、性能优化等。</p>', '1-3年', 'd9f3e6a3bdd60d110nJ709W8EFBR', '深圳 · 福田区 · 石厦', '12-13K', 'Java, Spring, SpringCloud, MyBatis, MySQL, 分布式经验, 微服务经验, 架构设计经验, 不接受居家办公, 保险', 'JAVA工程师-线下面试-全额缴纳', 'https://www.zhipin.com/job_detail/d9f3e6a3bdd60d110nJ709W8EFBR.html', '五险一金, 节日福利, 带薪年假, 意外险, 零食下午茶');
INSERT INTO `jobs` VALUES (96, '湘聚', '自动化设备', '100-499人', '不需要融资', '本科', '<p>岗位boss</p><p><strong>职责</strong></p><ol><li>负责对定位软件的技术⽀持和维护；</li><li>负责智能制造软件项⽬的实施、陪产、售后；</li><li>负责对智能制造软件的数据⾤集开发；</li></ol><p><strong>任职要求</strong></p><ol><li>熟悉linux和其常用指令；</li><li>熟悉C/C++开发、熟悉Java开发；</li><li>了解AGV和智能物流相关项目经验者优先（有海康、华睿AGV的实施经验优先）；</li><li>根据项⽬需要，有出差驻厂的情况；</li></ol>', '1-3年', '94b30a986061e1fa0nZ82Nu-F1tR', '深圳 · 宝安区 · 福永', '10-12K', '', '【双休/急招】软件开发工程师', 'https://www.zhipin.com/job_detail/94b30a986061e1fa0nZ82Nu-F1tR.html', '绩效奖金, 节日福利, 免费工装, 出国旅游, 宿舍有空调, 保底工资, 年终奖, 有无线网, 加班补助, 生日福利, 员工旅游, 节假日加班费, 生日礼物, 五险一金, 带薪年假, 零食下午茶, 补充医疗保险, 团建聚餐, 底薪加提成, 意外险');
INSERT INTO `jobs` VALUES (97, '大简', '专用设备', '20-99人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>参与算法系统的设计与实现，完成核心代码编写和功能开发；</li><li>根据业务需求进行数据建模与算法设计，提升系统的智能化水平；</li><li>优化算法性能，确保在大规模数据场景下的⾼效运⾏；</li><li>与团队协作完成技术⽅案评审，保障算法模块的可维护性和扩展性；</li><li>跟踪前沿算法技术，推动算法能力在实际项目中的落地应⽤。</li></ol><p><strong>任职要求</strong></p><ol><li>熟悉Java语言，具备扎实的算法和数据结构基础；</li><li>掌握常见算法设计方法，能够独立完成算法逻辑实现；</li><li>具备良好的编程习惯，能够编写高质量、可读性强的代码；</li><li>具有较强的问题分析与解决能力，能应对复杂技术挑战；</li><li>具备良好的沟通能力和团队协作意识，适应技术迭代节奏。</li></ol>', '1-3年', '3d6426106cd99e180nF83di7E1dX', '深圳', '12-20K', 'Java, 大数据经验, 不接受居家办公, Elasticsearch, PostgreSQL, SpringCloud, MySQL, SQL Server, 架构设计经验, Spring, Oracle', 'java算法工程师', 'https://www.zhipin.com/job_detail/3d6426106cd99e180nF83di7E1dX.html', '夜班补助, 补充医疗保险, 法定节假日三薪, 包住, 年终奖, 节日福利, 团建聚餐, 住房补贴, 生日福利, 宿舍有空调, 餐补, 五险一金, 员工旅游, 绩效奖金, 有无线网, 全勤奖, 带薪年假');
INSERT INTO `jobs` VALUES (98, '申灿科技', '计算机软件', '20-99人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ul><li>负责现有老旧政企系统、业务管理系统的日常开发、功能迭代、BUG修复及性能优化工作，保障系统稳定运行。</li><li>基于Struts2+Spring+Hibernate经典技术栈进⾏后端业务逻辑开发、接口开发与数据层适配，根据业务需求完成代码编写、调试与单元测试。</li><li>负责前端页⾯开发与优化，使⽤JSP+JavaScript完成页面功能实现、数据交互、页面适配及兼容性调整，配合业务需求完成前端页⾯迭代更新。</li><li>参与项目需求对接、技术方案讨论、需求评审，精准理解客户业务需求，输出合规、规范的开发代码及技术文档。</li><li>长期驻场对接客户现场，及时响应客户问题，处理系统运行过程中的各类突发问题，配合客户完成系统验收、运维支撑及版本上线工作。</li><li>配合团队完成项目进度把控、代码复盘、版本迭代，持续优化系统架构及业务逻辑，提升系统运行效率。</li></ul><p><strong>任职要求</strong></p><ul><li>后端技术：熟练掌握 Java 基础语法及常用工具，精通 Spring、Hibernate 框架核心原理及实际项目落地，熟悉SSH架构项目开发流程，能够独立完成后端业务模块开发、数据持久化、事务处理等工作。</li><li>前端技术：熟练使用 Struts2 框架进行请求分发、业务控制开发，精通 JSP、JavaScript 前端开发，熟悉JSTL标签、页面数据渲染、前后端数据交互、表单校验等常用功能开发。</li><li>熟练掌握Oracle等关系型数据库，熟悉SQL编写、索引优化、数据查询、事务管理，具备数据库问题排查及优化能力。</li><li>熟悉传统Java Web项目开发流程，了解Tomcat服务器部署、调试及日常运维，能够独立完成项目打包、上线、问题排查。</li><li>1-3年及以上Java Web开发经验，有完整SSH架构项目实战经验者优先，接受能力优秀、基础扎实的应届生。</li><li>接受长期现场驻场，能够稳定驻场工作，驻场机构为海关，配合客户现场作息及项目节奏，无驻场抵触情况。</li><li>具备良好的代码编写规范，逻辑清晰，具备独立问题排查、BUG修复、需求落地能力。</li><li>沟通能力良好，能够高效对接客户及团队，工作认真负责、稳定性强，具备较强的执行力和抗压能力。</li><li>有政企、政务、企业内部管理系统开发经验者优先。</li></ul>', '1-3年', '7c3e2613bf1e31a50nF92tm-GVVR', '深圳 · 福田区 · 石厦', '8-12K', 'Java, Spring, Hibernate, Oracle, 不接受居家办公', 'java开发工程师（驻场）', 'https://www.zhipin.com/job_detail/7c3e2613bf1e31a50nF92tm-GVVR.html', '年终奖, 五险一金');
INSERT INTO `jobs` VALUES (99, '巨龙创视', '智能硬件', '100-499人', '未融资', '本科', '<p><strong>岗位职责</strong></p><p>1、参与系统相关模块的库表设计与代码编写2、参与所负责需求、模块的产品方案评审会议，可对产品方案提出优化意见建议与技术实现上的意见建议3、完成所安排的研发任务的代码编写，当所负责功能在线上环境发生问题故障时能快速解决问题</p><p><strong>任职要求</strong></p><p>1、有Java后端开发实际项目经验，对于数据库SQL有⼀定优化能⼒与经验，接受有相关实习经验的应届毕业⽣2、熟悉SprintBoot、Redis、RabbitMQ、MySQL、Linux服务器常用命令等技术与实际开发应用经验者可优先考虑3、有中⼤型项目系统的实际项目经验者可优先考虑4、做事认真负责，能够自我驱动不断学习提升技术能力</p>', '1-3年', '307ca2fa5b5c4a0c0nF92N2_E1FR', '深圳 · 南山区 · 科技园', '15-25K', 'Java, MySQL, Spring', 'java后端工程师', 'https://www.zhipin.com/job_detail/307ca2fa5b5c4a0c0nF92N2_E1FR.html', '带薪年假, 零食下午茶, 节日福利, 员工旅游, 每年多次调薪, 年终奖, 餐补, 五险一金, 定期体检');
INSERT INTO `jobs` VALUES (100, '深圳科先人工智能系统', '人工智能', '0-20人', '', '本科', '<ol><li>本科及以上学历，1到3年后端开发经验，2. 有架构设计能⼒，熟悉分布式架构设计，精通RabbitMQ/RocketMQ/Kafka等消息中间件，掌握Node.js底层机制，具备JVM调优实战经验3、前端技术：掌握或至少了解React18版本、Vue3、typescript、Electron等前端开发语言，掌握组件、路由、数据绑定、表单、组件间通信等操作。</li><li>后端技术：精通Java，同时了解Golang、Node.JS、Python等其他编程语言之一者优先框架：Spring Boot、Spring Cloud 阿里巴巴等微服务框架5、熟练使用关系型数据库，如Oracle，MySql，PostgreSql等、理解Redis集群架构与缓存击穿/穿透/雪崩解决方案6、熟悉常用代码管理工具Git，SVN等7：Ai爬虫。通用爬虫系统的编写。使用过PlayWright MCP等技术优先8. 擅长熟练：AI编程软件：Claude Code，Cursor，Trae.gemini3 擅长AI协同编程工作，整合AI协同编程工作9： Agent,langchain4j ,RAG大模型有了解个人的见解输出10：市场需求分析{痛点} →调研 → 架构方案设计 → 前后端开发 → 测试→ 部署上线 → 落地→ 运维→业务的闭环能力加分项：1:会粤语优先考虑，香港工作过的优先考虑2：复合型人才优先、整合性思维3：在学校做过：班长或者学生会主席 或者宿舍管理人之类的4：学校 专业排名靠前/ 省级市级的一些奖项/人才培养计划其中一员5：AI社区有技术输出(个人博客/开源项目/论文)，或者有单独接过项目，或者 赋能增效过业务的某个功能模块，或者有单独接过项目6：独立全链路，端到端的的完成整个落地过程7：具备：用户 产品思维/业务逻辑/懂ai/系统架构/跨部门协同的能力，以及实际场景和业务逻辑落地的能力8：有自己对行业或者业务理解的建树岗位</li></ol><p><strong>福利</strong></p><p>1：双休2：国家法定节假日正常休假{带薪年假}3：五险一金4：项目奖金6：Claude/Cursor等顶级AI工具全年订阅</p>', '1-3年', '067b5223134d93fd0nd63924E1NV', '深圳 · 南山区 · 科技园', '7-12K', 'Java, 不接受居家办公, agent, 粤语, SpringCloud, Redis, Spring, AI工具, 微服务经验, MySQL, MyBatis, 架构设计经验, Oracle, 从0到1', 'jave 26届应届生', 'https://www.zhipin.com/job_detail/067b5223134d93fd0nd63924E1NV.html', '保底工资, 生日福利, 团建聚餐, 公司分润, 五险一金, 绩效奖金, 全勤奖, 带薪年假, 企业年金, 股票期权, 加班补助');
INSERT INTO `jobs` VALUES (101, '阿甘到', '互联网', '20-99人', '不需要融资', '本科', '<p>核心</p><p><strong>工作职责</strong></p><ol><li>后端服务开发与优化：基于主流后端技术栈（Java/Spring Boot、Node.js/Express、.NET Core等），设计并开发符合RESTful规范的后端接口，适配UniApp跨端开发需求，优化接口响应速度与服务性能，处理高并发场景下的接口请求问题。</li><li>UniApp前后端对接：深入理解UniApp跨端原理，熟悉UniApp⽹络请求机制（如uni-request），负责与前端团队协同，完成接口联调、数据格式定义、请求拦截与响应处理，解决跨端（⼩程序、H5、App）接口适配差异问题，确保数据交互⼀致。</li><li>数据层设计与维护：负责MySQL、SQL Server等数据库的设计、数据建模与SQL优化，合理运用Redis等缓存技术实现数据缓存策略，保障数据存储的安全性、完整性与查询效率，支持UniApp前端各类数据展⽰与交互需求。</li><li>系统稳定性保障：负责后端服务的部署（如Docker）、监控、日志管理与故障排查，处理线上服务异常、接口报错等问题，制定应急预案，确保服务7×24小时稳定运行，支撑UniApp应用的正常使用。</li><li>接口安全与权限控制：实现接口权限校验、参数加密传输、防SQL注入等安全机制，对接UniApp前端的登录认证、token管理等功能，保障用户数据与接口安全，符合相关合规要求。</li></ol><p><strong>三、任职要求</strong></p><ol><li>学历与专业：本科及以上学历，计算机、软件工程、电子信息等相关专业，1-3年及以上后端开发经验，有UniApp跨端项目后端对接经验者优先。</li><li>技术能力：熟练掌握至少一种主流后端技术栈（Java/Spring Boot优先），熟悉RESTful接口设计规范；熟悉MySQL、SQL Server等关系型数据库，掌握Redis等缓存技术的使用与优化；了解Docker部署、Linux系统基础操作。</li><li>UniApp相关经验：熟悉UniApp跨端开发流程，掌握UniApp网络请求机制（uni-request），有UniApp前端对接后端接口的实际项目经验，能独立解决跨端接口适配、数据交互相关问题。</li><li>其他能力：具备良好的代码规范与编程习惯，较强的问题排查、逻辑思维与沟通协作能力；能快速适应业务需求变化，有责任心，具备团队协作精神；了解接口安全相关知识，有高并发、高可用系统开发经验者加分。四、其他要求1. 能承受一定的工作压力，配合项目迭代进度，按时完成开发任务；</li><li>主动关注行业新技术、新动态，愿意学习并应用到实际工作中，提升系统开发效率与质量；</li><li>具备良好的文档编写能力，能规范编写接口文档、技术文档，方便团队协作与后期维护。</li></ol>', '1-3年', '1b045ad57ea2149b0nZz2dW8EFpW', '深圳', '8-13K', 'Java, uni, C++, 不接受居家办公, C, SpringCloud, MySQL, Spring, ERP开发经验', '高级后端工程师', 'https://www.zhipin.com/job_detail/1b045ad57ea2149b0nZz2dW8EFpW.html', '全勤奖, 五险一金, 零食下午茶, 节日福利, 生日福利, 带薪年假, 工龄奖, 年终奖, 团建聚餐, 员工旅游, 绩效奖金');
INSERT INTO `jobs` VALUES (102, '和光医疗', '医疗器械', '20-99人', '天使轮', '本科', '<ol><li>如果您是一名核心软件工程师并希望构建万能应用程序，请boss加⼊我们2.我们不关⼼你在哪⾥上学，甚至不关心你是否上过学，也不关⼼你在哪家“大牌”公司工作。</li><li>只需向我们展示您的代码即可。</li></ol>', '1-3年', 'abe5cb3031d7c2f60nB_092-EFRX', '深圳', '12-24K', '', 'AI软件工程师', 'https://www.zhipin.com/job_detail/abe5cb3031d7c2f60nB_092-EFRX.html', '员工旅游, 年终奖, 五险一金, 包住, 住房补贴, 有无线网, 带薪年假, 股票期权, 绩效奖金, 餐补, 定期体检, 宿舍有空调, 节日福利, 零食下午茶');
INSERT INTO `jobs` VALUES (103, '广东字量科技', '计算机服务', '0-20人', '不需要融资', '本科', '<p><strong>一、核心职责</strong></p><p>•参与公司核心业务系统的设计、开发、测试及上线工作，确保系统的稳定性、⾼效性和可扩展性；•根据需求⽂档完成模块功能编码，严格遵循编码规范，主动进⾏代码自查和优化；•配合测试人员定位并修复系统中的bug，参与技术评审和问题复盘，持续提升代码质量；•关注⾏业新技术动态，将合适的技术方案应用到实际工作中，助力团队技术迭代；•与产品、前端、测试等跨部门团队协作，高效推进项目进度，保障项目按时交付。</p><p><strong>二、任职要求</strong></p><p>1. 专业技能要求•本科及以上学历，计算机相关专业（能力优秀者学历可放宽），1~3年Java开发经验；•精通Java基础语法，深入理解面向对象编程思想，熟悉集合框架、多线程、IO、反射等核心技术；•熟悉主流开发框架，如Spring、Spring Boot、Spring Cloud、MyBatis等，能熟练运用框架进行项目开发；•掌握关系型数据库（如MySQL、Oracle），熟悉SQL语句优化、索引设计，了解数据库事务原理；•了解分布式系统相关概念，如负载均衡、服务注册与发现、熔断降级、分布式事务等；•熟悉常用的开发工具和版本控制工具，如IDEA、Git、Maven/Gradle等；•了解前端基础技术（HTML、CSS、JavaScript、Vue/React等）者优先；•有微服务项目开发经验、高并发/高可用系统设计经验者优先；•熟悉Redis、Kafka等中间件的使用及原理者优先。2.</p><p><strong>综合素质</strong></p><p>要求•具备强烈的责任心和敬业精神，工作积极主动，有良好的沟通协调能力和团队合作意识；•具备较强的学习能力和问题解决能力，能快速适应新的技术环境和业务需求；•有清晰的逻辑思维和严谨的工作态度，注重代码规范和文档编写；•能承受一定的工作压力，具备按时完成项目任务的执行力。</p>', '1-3年', '4287846035a8234f0nZ63d24F1VQ', '深圳 · 南山区 · 科技园', '10-15K·13薪', 'Java, 不接受居家办公, 分布式经验, SpringCloud, MySQL, MyBatis, Spring, Oracle', 'java软件工程师（1~3年）', 'https://www.zhipin.com/job_detail/4287846035a8234f0nZ63d24F1VQ.html', '年终奖, 定期体检, 五险一金');
INSERT INTO `jobs` VALUES (104, '中南通达', '跨境物流', '20-99人', '未融资', '大专', '<p>⼯作</p><p><strong>职责</strong></p><ol><li>评估业务需求，设计并实施RPA解决⽅案并满⾜⾃动化需求;</li><li>负责RPA系统的开发、测试、部署和维护，确保系统的稳定运⾏;</li><li>负责影⼑RPA项⽬落地，提⾼⾃动化程度和运⾏效率;</li><li>与业务部⻔保持密切沟通，理解业务痛点，提供⾃动化解决⽅案;</li><li>跟踪RPA技术的发展趋势，研究并应⽤新技术以提⾼⾃动化⽔平;</li><li>负责RPA相关的培训与制度，以提⾼业务的认知⽔平;</li></ol><p><strong>任职资格</strong></p><ol><li>计算机科学、软件⼯程或相关专业⼤专及以上学历，1年以上RPA开发经验；</li><li>熟练掌握RPA开发⼯具（熟悉影⼑RPA优先考虑）和编程语⾔（如Python, Java, JS等）3.对RPA领域有浓厚兴趣，了解RPA的最新发展动态和技术趋势；</li><li>具备较强的分析问题和解决问题的能⼒，能够独⽴思考并解决技术难题；</li><li>具备良好的团队合作精神和沟通能⼒，能够与不同部⻔有效协作；</li><li>有良好的英⽂读写能⼒，能够阅读英⽂技术⽂档和资料优先；</li><li>有跨境物流，跨境电商RPA项⽬经验者优先。深圳市中南通达国际物流有限公司，2015年起专注于跨境电商物流领域。专业“跨境电商物流服务商”，专注为跨境电商提供FBA双清到门海空运服务。主要线路有美国FBA海空派、加拿⼤海空派服务、欧洲海空派、欧洲铁路、澳洲海运。公司秉承“客户***，安全准时”的理念，竭诚为每⼀位客户提供⾼效放心的物流服务。深圳市中南通达国际物流有限公司总部设在深圳，并在上海、宁波、青岛、厦门等港口城市设立了代理处。有⼀支专业和富有经验的团队致力服务于各类型企业，在欧洲、北美、澳洲、欧洲地区均有专业的海外代理负责处理货物。</li></ol>', '1-3年', 'd0801fb6d8a9782a0nF92NS-E1RV', '深圳', '9-14K', 'Java, Python, Spring, SQL Server, RPA开发, RPA实施, 影⼑开发, 跨境电商物流, 国际物流', 'RPA开发⼯程师（影刀 国际物流）', 'https://www.zhipin.com/job_detail/d0801fb6d8a9782a0nF92NS-E1RV.html', '底薪加提成, 意外险, 补充医疗保险, 年终奖, 带薪年假, 生日福利, 加班补助, 全勤奖, 员工旅游, 团建聚餐, 节日福利, 零食下午茶, 五险一金');
INSERT INTO `jobs` VALUES (105, '酷宅科技', '智能硬件', '100-499人', 'A轮', '本科', '<p>后端开发工程师（多语言方向）</p><p><strong>岗位亮点</strong></p><ol><li>开放技术转型：欢迎Java技术栈开发者投递，可选择转向 Node.js 或 C语言 开发方向；</li><li>经验复用场景：基于成熟后端开发经验，快速切入高并发/微服务/分布式系统（Node.js方向）或 MCU/Linux 系统级开发（C语言方向）；</li><li>技术定位：• Node.js方向：聚焦服务端开发，负责请求量上亿的高并发服务端业务场景（中间件开发、云原生应用构建）。深入参与从数据库优化到分布式系统设计的完整技术链路；• C语言方向：聚焦物联网设备(MCU)、网关(Linux)的系统及应用开发，涉及底层协议优化、基础组件研发、嵌入式或网络服务模块，提升系统资源利用率和稳定性。</li></ol><p><strong>工作内容</strong></p><ol><li>基于C语言进行系统模块或基础中间件的开发与优化；</li><li>参与网络通信、数据处理、内存管理等底层逻辑的设计与调优；</li><li>支撑上层业务对性能、稳定性、资源占用的高要求。</li></ol><p><strong>任职要求</strong></p><ol><li>全日制本科及以上学历，计算机相关专业，通过英语四级；</li><li>精通Java语言，具备扎实的后端开发基础，愿意转型 Node.js 或 C语言 开发；</li><li>熟悉 MySQL、Redis 等相关数据库的使用；</li><li>熟悉 Linux 系统，掌握常用的 shell 命令；</li><li>具备基础的网络知识，了解 TCP/IP, HTTP 等网络协议；</li><li>熟悉常见的开发框架和工具；</li><li>有全栈开发经验者优先；</li><li>针对C语言方向加分项：了解指针、内存管理、多线程编程、Makefile、GDB调试等C语言底层特性</li></ol>', '1-3年', '83d8296ccd16a5301HJy0tS6FFRW', '深圳 · 龙岗区 · 坂田', '9-14K·14薪', 'Java, 不接受居家办公, 分布式经验, SpringCloud, MySQL', '后台开发工程师', 'https://www.zhipin.com/job_detail/83d8296ccd16a5301HJy0tS6FFRW.html', '团建聚餐, 定期体检, 股票期权, 员工旅游, 五险一金, 全勤奖, 节日福利, 零食下午茶, 带薪年假, 绩效奖金, 年终奖');
INSERT INTO `jobs` VALUES (106, '深圳市智序恒泰信...', '电子/硬件开发', '0-20人', '不需要融资', '大专', '<p><strong>岗位职责</strong></p><ol><li>精通嵌入式LINUX或RTOS系统下C语言编程;</li><li>熟悉ARM(或DSP)、FPGA、CPLD、单片机等软件设计、应用;</li><li>有实际项⽬开发经验，能独⽴完成项⽬;</li><li>配合、协助团队和相关团队完成相关任务目标。</li></ol><p><strong>任职要求</strong></p><ol><li>计算机、电子、通信、⾃动化等相关专业专科以上学历;</li><li>熟悉软件技术文档的编写;具备良好的文档编制习惯和代码书写规范;</li><li>熟练掌握CC程序设计语言和数据结构，能够进行简单的嵌入式应用软件架构设计;</li><li>熟悉Linux系统和常规shel处理命令，能够在Linux系统上做软件开发，掌握基本的Linux软件开发平台，如minigui;优选条件:</li><li>2年以嵌入式软件开发经验;</li><li>具有硬件开发背景和经验，嵌入式底层驱动开发经验优选;</li><li>具有车机，行车记录仪，运动DV开发经验优选;</li></ol>', '1-3年', '554d84b1ac5af6c60nJ63N28E1BR', '深圳', '15-20K', 'Java, 大数据经验, 不接受居家办公, C++, MySQL, MyBatis, Dubbo, SQL Server, 架构设计经验, Oracle, Python', '软件工程师', 'https://www.zhipin.com/job_detail/554d84b1ac5af6c60nJ63N28E1BR.html', '年终奖, 保底工资, 节假日加班费, 绩效奖金, 五险一金');
INSERT INTO `jobs` VALUES (107, '未来绿能', '储能', '20-99人', '未融资', '本科', '<p>此岗位惠州上班</p><p><strong>岗位职责</strong></p><p>核心业务开发：独立负责光伏储能系统的PC端运营管理平台网页端和移动端（H5/APP）的功能开发与迭代升级；后期负责该平台的升级和优化，及运维。支付对接：负责开发与开源⽀付应⽤的对接，类似购买⼿机分期付款。独立模块交付：基于现有Spring Boot（后端）和Vue.js（前端）代码架构，独立完成从接口设计、数据库操作到页⾯交互的完整功能闭环。联调与质量保障：参与技术方案设计，完成新旧系统的联调测试，编写核心模块的单元测试，确保金融级数据的一致性和安全性。</p><p><strong>岗位要求</strong></p><p>性要求学历/经验：统招专科及以上学历，计算机、软件工程相关专业，2年以上全栈开发经验。后端能力：熟悉 Java (SpringBoot) + Vue/React + 移动端 H5/APP 开发前端能力：能独立完成响应式页面开发，熟悉Element UI/Ant Design等组件库。独立交付：具备良好的抽象设计能力，不依赖他人手把手带，能独立完成一个完整应用的全链路开发。代码习惯：有良好的代码注释习惯和清晰的接口文档编写能力（方便团队协作与知识传承）。行业背景：有储能、新能源、电力物联网行业系统开发经验优先。金融/支付经验：有消费分期、账务系统或支付网关实际对接经验优先。跨端开发：有uniapp或Flutter跨平台开发经验（可一套代码覆盖小程序/H5/APP）。</p>', '1-3年', 'a08810c060cbc38b0nF63dW1F1dZ', '深圳 · 宝安区 · 石岩', '12-24K', 'Java, 不接受居家办公, 架构设计经验, Spring, 区块链经验', 'java全栈工程师（惠州上班，包吃住）', 'https://www.zhipin.com/job_detail/a08810c060cbc38b0nF63dW1F1dZ.html', '团建聚餐, 保底工资, 五险一金, 绩效奖金, 年终奖, 带薪年假, 节日福利, 交通补助, 底薪加提成, 通讯补贴');
INSERT INTO `jobs` VALUES (108, '可可', '互联网', '100-499人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责出海DSP广告平台核心引擎研发，搭建RTB实时竞价链路、完成全球媒体流量接入，持续选代引擎架构保障海量海外流量高并发稳定吞吐;</li><li>负责智能投放⼯具、流量优选、出价⼯程化、实时数据体系核⼼模块的设计与开发，提升平台自动化、智能化投放能力;</li><li>搭建⾼并发、低延迟的广告实时统计、计费系统，持续优化RTB链路耗时、服务稳定性与容灾能力;</li><li>基于线上业务数据，通过引擎优化、链路改造、出价策略选代，提升eCPM与转化效率、降低投放成本，持续优化整体广告变现收益。</li></ol><p><strong>任职要求</strong></p><ol><li>有出海DSP/RTB广告平台真实落地经验，熟悉ADX竞价流程、流量选、0CPX出价、RTA投放核心业务;</li><li>熟练 Go/Java/C++/Rust 任意一门后端语言，精通 Redis、Kafka、ClickHouse、Flink 等大数据及高并发中间件;</li><li>具备高QPS、低延迟分布式系统开发经验，有广告引擎性能调优、链路降延迟实战经验优先;</li><li>工程化能力扎实，可独立负责核心模块设计、开发与线上问题排查，有出海效果广告平台经验优先。</li></ol>', '1-3年', '84420822903d460f0nF63t-5EVJT', '深圳 · 福田区 · 车公庙', '15-30K', 'Java, Golang, Spring, MySQL, 程序化, DSP, ADX', 'dsp研发工程师', 'https://www.zhipin.com/job_detail/84420822903d460f0nF63t-5EVJT.html', '带薪年假, 年终奖, 绩效奖金, 团建聚餐, 员工旅游, 补充医疗保险, 生日福利, 五险一金, 节日福利, 加班补助');
INSERT INTO `jobs` VALUES (109, '深蓝信息', '计算机软件', '20-99人', '不需要融资', '本科', '<p><strong>岗位要求</strong></p><ol><li>参与并负责部分产品的需求、功能设计和技术调研；</li><li>负责项目框架构建、核心模块开发及功能优化改进；</li><li>独立完成核心/重要模块的设计、编码；</li><li>参与代码设计、审核和检查，负责相关技术文档的编写；</li><li>兼项目管理，关注项目进度，负责独立模块/项目的进度管理；</li><li>参与系统维护、运营过程中技术问题的解决；</li><li>负责公司企业应用平台的开发和架构设计，保证设计和编码的质量，承担重点、难点的技术攻坚。</li></ol><p><strong>任职要求</strong></p><ol><li>全日制硕士及以上学历优先，计算机相关专业，接受实习生；</li><li>熟悉Mysql,oracle等数据库，具有较好的数据库设计经验和sql优化能力；</li><li>扎实的java编程基础，理解IO、多线程、集合、JVM原理等，并具备一定线上故障排查经验；对微服务架构设计、系统分析、性能优化等有一定经验；</li><li>熟练使用Spring、SpringCloud、dubbo、MyBatis、redis、Springboot等开源框架；熟悉Linux及相关shell命令；</li><li>具有良好的沟通和团队协作能力、良好的学习能力、思维能力，有强烈的工作责任心；</li><li>有足够的大局观和技术视野，具备团队管理能力，能带领开发团队完成复杂项目的需求分析和架构设计；</li><li>工作积极主动，有责任心，能够承担压力，并具有很强的分析能力和解决问题的能力，较强的学习能力和沟通能力，具备良好的团队合作精神；</li><li>有扎实的编程能力，有优秀的设计能力和代码品位，热爱编程；</li><li>较好的产品意识，愿意将产品效果做为工作最重要的驱动因素；</li><li>对软件产品有强烈的责任心，具备良好的沟通能力和优秀的团队协作能力。</li></ol>', '1-3年', '85ba7e054487f0e21Xx629W0F1dU', '深圳 · 龙岗区 · 平湖', '10-15K·13薪', 'Java, 物联网经验, 大数据经验, SpringCloud, 接受无前端经验/技能, MyBatis, Redis, 云计算经验, Dubbo, Spring', '初级java开发工程师', 'https://www.zhipin.com/job_detail/85ba7e054487f0e21Xx629W0F1dU.html', '加班补助, 定期体检, 节日福利, 节假日加班费, 生日福利, 零食下午茶, 工龄奖, 法定节假日三薪, 员工旅游, 全勤奖, 年终奖, 交通补助, 带薪年假, 团建聚餐, 五险一金');
INSERT INTO `jobs` VALUES (110, 'iKKO', '智能硬件', '20-99人', '不需要融资', '本科', '<p>【关于我们】iKKO，先锋AI科技品牌。首创卡片式AI手机，开创AI终端新品类。官网：ikko.com⼩红书：@iKKO / Instagram: @ikko.tech</p><p><strong>岗位职责</strong></p><ol><li>负责平台服务端系统架构设计与开发;</li><li>持续优化系统架构，提⾼系统在⾼并发、大流量下的容灾容错能力，保证系统的⾼可用性；</li><li>对现存或末来的系统能进行宏观的思考，规划形成统一的框架、平台、体系或组件。</li></ol><p><strong>任职要求</strong></p><ol><li>学历背景：全日制本科或以上学历（必要项）；计算机专业或者相关专业背景；</li><li>工作经验：3年及以上工作经验，云服务器部署经验。有运维平台工作经验优先。熟悉 Java、golang、C/C++任一开发语言，熟悉 Spring 体系、go-zero、分布式技术栈 (消息队列、分布式事务、微服务） 等；</li><li>扎实的编码基础，熟悉常用的数据结构、多线程并发、网络等基础知识;</li><li>具备良好的算法、设计模式、操作系统、数据库功底;</li><li>具备优秀的技术架构的设计能力，熟悉常用面向对象设计原则，熟练掌握设计模式及应用场景；</li><li>熟悉分布式场景常用算法及中间件，具有高并发高可用服务接口设计开发经验，有大型互联网分布式应用架构研发经验；【</li></ol><p><strong>福利</strong></p><p>】- 五险一金、年终奖、出国旅游- 不定时下午茶和公司团建，无限量饮料供应- 国际化的工作环境和职业发展机会</p>', '1-3年', '561ec6199e32c7920nB_2dW7GFtQ', '深圳 · 南山区 · 蛇口', '11-22K', 'Java, Golang, C, C++, Spring, 架构设计经验, 音视频经验, 不接受居家办公', 'Java后端工程师', 'https://www.zhipin.com/job_detail/561ec6199e32c7920nB_2dW7GFtQ.html', '绩效奖金, 五险一金, 生日福利, 员工旅游, 零食下午茶, 节日福利, 年终奖');
INSERT INTO `jobs` VALUES (111, '巨沃科技', '计算机软件', '100-499人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>完成软件功能设计；</li><li>负责核心模块的开发，解决复杂的技术问题；</li><li>制定开发计划，并严格监控执行；</li><li>参与软件需求评审、测试用例评审；</li><li>对开发人员的代码进行定期走查，并提出改进意见；</li><li>指导其他开发工程师进行功能开发；</li><li>对开发的功能进行单元测试；</li><li>协助项目经理进行团队管理工作；</li></ol><p><strong>任职要求</strong></p><ol><li>具有2年以上B/S应用系统项目开发经验，充分理解面向对象编程思想，有较强的逻辑思维能力 ；</li><li>熟练掌握J2EE相关技术和MVC设计模式，熟练掌握Spring，SpringMVC 常用开发框架，熟悉redis，ActiveMQ，dubbo，mongodb；</li><li>熟悉html，css，jquery，ajax开发等前端基本技术，有easyUI使用经验优先考虑；</li><li>熟练使用Eclipse开发工具，及SVN，Maven等项目管理工具 ；</li><li>熟练掌握Mysql，SQL SERVER 数据库开发，能编写复杂SQL语句，视图，存储过程 ；</li><li>能从事较复杂业务模块的设计和开发工作，对电商仓储物流行业有一定的了解， 从ERP，订单管理系统，仓储管理系统，物流管理系统，计费系统项目开发人员优先考虑；</li><li>有良好的学习能力、团队协作能力，主动沟通能力，能够在较大的压力下工作，愿意在团队中共享自己的经验与知识 ；</li><li>有良好的开发习惯，重视开发规程和基础文档制作，具有规范的开发文档编写能力 ；</li><li>有需求分析或系统分析设计经验者优先。</li></ol>', '1-3年', '98b7ca54d1cdc8bb1HV929i5FlFU', '深圳 · 福田区 · 八卦岭', '10-14K', 'MES开发经验, Java, MySQL, Spring, ERP开发经验, 有前端经验/技能', 'Java研发工程师', 'https://www.zhipin.com/job_detail/98b7ca54d1cdc8bb1HV929i5FlFU.html', '节日福利, 通讯补贴, 五险一金, 餐补, 带薪年假, 员工旅游, 定期体检, 零食下午茶, 年终奖, 交通补助');
INSERT INTO `jobs` VALUES (112, '深圳沃浦思必特信...', '计算机软件', '0-20人', '不需要融资', '本科', '<p><strong>职位描述</strong></p><ol><li>参与大数据系统的建模、开发、优化与维护，确保系统在高并发、高负载的环境下稳定高效运⾏；</li><li>关键技术研究和攻关，提供技术指导和⽀持；</li><li>系统架构的持续优化和重构，提⾼系统的容错能力和可维护性，确保系统在复杂环境下的稳定运行；</li><li>参与分析性能瓶颈，定位系统问题，并通过代码优化、并发控制、数据库优化等⼿段，提升系统性能；</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机、软件工程、电子信息等相关专业；</li><li>3 年以上 java 后端开发经验和 1 年大数据开发；</li><li>基础扎实，精通 Java 并发编程、JVM，理解网络通信、多线程等基础框架，对各种开源开发框架如 Spring boot、mybatis，springcloud，zk，kafka 等开发体系有深入的应用和优化经验，掌握它的原理和机制；</li><li>有 Hadoop 体系相关开发经验，熟悉 hive/clickhouse/doris 的开发；</li><li>有 CDH、DataX、数湖等工具的使用经验；</li></ol>', '1-3年', '9b694af434a2d7950nF92N-0FVRU', '深圳 · 福田区 · 会展中心', '15-22K', 'Java, C++, Golang, Python, PHP, Spring, SpringCloud, MyBatis, Hibernate, Kafka, MySQL, Redis, Oracle, MongoDB, HBase, 团队管理经验, 架构设计经验, 分布式经验, 微服务经验, 大数据经验, 后端开发', '大数据高级java开发工程师', 'https://www.zhipin.com/job_detail/9b694af434a2d7950nF92N-0FVRU.html', '五险一金, 法定节假日三薪, 全勤奖, 年终奖, 保底工资, 绩效奖金, 定期体检, 节假日加班费');
INSERT INTO `jobs` VALUES (113, '谷从', '计算机软件', '20-99人', '不需要融资', '大专', '<p>1、负责公司中后台系统的整体架构设计、模块开发及接口对接等⼯作全流程把控2、负责公司⼴告变现产品 投放中台搭建3、对于⼴告风控控制，对广告业务熟悉有自⼰的见解</p><p><strong>任职要求</strong></p><p>负责公司广告业务线公司做广告业务，必须有相关业务经验；技术栈要求：spring全家桶；有ai开发经验</p>', '1-3年', 'b1f6b6c73caea6a40nF43tm0EVFR', '深圳 · 南山区 · 科技园', '15-30K', 'Java, Spring, MySQL, 搜索/推荐/广告经验, 广告, 广告归因, 广告投放平台, 广告中台', 'Java开发-广告变现业务', 'https://www.zhipin.com/job_detail/b1f6b6c73caea6a40nF43tm0EVFR.html', '意外险, 补充医疗保险, 员工旅游, 零食下午茶, 团建聚餐, 五险一金, 生日福利, 带薪年假, 节日福利, 绩效奖金, 定期体检, 餐补');
INSERT INTO `jobs` VALUES (114, '小石科技', '政府/公共事业', '20-99人', '未融资', '本科', '<p>* boss</p><p><strong>岗位职责</strong></p><ol><li>负责Java项目的开发、维护，参与产品架构设计和需求分析及开发。</li><li>配合项目计划，编写高质量的代码并完成开发任务。</li><li>承担接口设计、设计方案等文档的编写。*</li></ol><p><strong>任职要求</strong></p><ol><li>计算机相关专业，本科以上学历，2年及以上JAVA开发经验。</li><li>扎实的JAVA编程基础，熟悉各种开源的框架如Spring、Mybatis、SpringMVC、Spring Cloud等。</li><li>熟练使用MySQL数据库，掌握基本的SQL优化技巧。</li><li>熟练使用常用的设计模式，注重代码质量与可维护性。</li><li>熟悉基本的linux命令，掌握NoSQL、MQ、Cache等中间件的机制和应用。</li><li>工作积极，具备较强的团队协作能力，对技术充满热情，学习能力强，在某个技术领域有自己的见解。* 教育背景：“985、211、双一流”高校毕业优先考虑。</li></ol>', '1-3年', '3f1803a580d421f81nJz3tm_GVZV', '深圳 · 南山区 · 科技园', '10-15K', 'SpringCloud, 分布式技术, SpringMVC, Spring', 'java开发工程师', 'https://www.zhipin.com/job_detail/3f1803a580d421f81nJz3tm_GVZV.html', '五险一金, 股票期权, 带薪年假');
INSERT INTO `jobs` VALUES (115, '比苛电池', '电子/半导体/集成电路', '100-499人', '未融资', '本科', '<p><strong>工作职责</strong></p><ol><li>负责公司管理产品后端开发工作，微服务模块开发。</li><li>遵循公司技术标准、规范，高质量完成设计、开发任务。</li><li>负责公司软件产品的改进、完善，性能优化。</li><li>参与公司产品基础框架的设计讨论、研发和具体应用。</li></ol><p><strong>任职要求</strong></p><ol><li>计算机、通信等相关专业本科学历及以上，具有3年以上Java开发经验。</li><li>Java基础扎实，熟悉JVM、多线程、集合等基础，熟悉Spring、Spring Cloud、Spring Boot、MyBatis等开源框架，对微服务架构有⼀定理解。</li><li>熟悉MySQL、Oracle、ElasticSearch、Clickhouse等数据库，精通SQL语法，熟悉Redis缓存数据库。</li><li>熟悉Git，Maven，Idea等⼯具。</li><li>有ERP, CRM类软件有开发经验者优先。</li><li>逻辑思维清晰，有良好的团队合作精神；较强的执⾏力和责任感，能承受压力，能够很好完成沟通上下游对接⼯作。</li></ol>', '1-3年', 'bfe84997ec74cb250nFz09-0E1dQ', '深圳', '8-13K', 'Java, C++, Python, PHP, C#, Spring, SpringCloud, MyBatis, MySQL, Oracle, ERP开发经验, 分布式经验, 微服务经验, 架构设计经验, 云计算经验', '后端开发工程师+急招+双休', 'https://www.zhipin.com/job_detail/bfe84997ec74cb250nFz09-0E1dQ.html', '带薪年假, 节日福利, 工龄奖, 员工旅游, 夜班补助, 年终奖, 全勤奖, 绩效奖金, 通讯补贴, 加班补助, 餐补, 五险一金, 零食下午茶');
INSERT INTO `jobs` VALUES (116, '森云智能', '汽车零部件', '100-499人', 'B轮', '本科', '<p><strong>主要职责</strong></p><ol><li>负责 EasyMes 系统基础业务模块的后端开发与接口编写；</li><li>按设计文档完成数据库的增删改查、业务逻辑实现及自测；</li><li>协助修复系统测试和生产环境中的代码缺陷；</li><li>编写清晰的技术注释和简单的接口说明文档；</li><li>参与代码⾛读，学习并遵循团队的技术规范。</li></ol><p><strong>岗位要求</strong></p><ol><li>本科及以上学历，计算机科学、软件⼯程、信息技术等相关专业；</li><li>掌握 Java（Spring Boot）或 C#（.NET Core）基础，能独⽴完成简单的 CRUD 功能3、熟悉 SQL 语法，了解 MySQL 或 SQL Server 的基本操作4、了解 Git、Maven/Gradle 等常用开发工具5、对制造业务（⽣产工单、物料、工艺）感兴趣，愿意深入业务6、逻辑清晰、有自驱力，遇到问题能先尝试排查再求助加分项：有校内项目或实习经验，写过完整的小型管理系统。</li></ol>', '1-3年', '9e34ac13763877960nF83ti-ElpS', '深圳 · 龙岗区 · 南联', '10-15K', 'Java, C#, Spring, MySQL, SQL Server, MES开发经验', '软件工程师（MES）', 'https://www.zhipin.com/job_detail/9e34ac13763877960nF83ti-ElpS.html', '零食下午茶, 意外险, 餐补, 交通补助, 绩效奖金, 五险一金, 团建聚餐, 节日福利, 年终奖, 带薪年假');
INSERT INTO `jobs` VALUES (117, '云智达创', '社交网络与媒体', '100-499人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>参与后端系统的设计与开发，保证系统的高性能、可扩展与稳定性；</li><li>负责数据抓取、处理与存储，包括国内主流社交媒体平台（抖音、小红书等）的数据接口与爬取工具开发；</li><li>配合AI产品开发，参与AI Agent应⽤的设计与落地；</li><li>参与前端功能开发与优化，提供接口⽀持，能够快速验证产品功能原型；</li><li>与产品经理、数据团队协作，具备良好的产品思维，能够独⽴分析需求并提出技术解决方案；</li><li>持续优化系统架构，提升代码质量和系统可靠性，积极参与技术创新和新技术探索。</li></ol><p><strong>任职要求</strong></p><ol><li>精通至少⼀种编程语言（如Python、Java、Golang、Nodejs等），具备良好的编码规范与工程意识，熟悉多种语言者优先；</li><li>熟悉国内主流社交平台（抖音、小红书等）的数据结构、API接口和抓取方法，具备相关项目经验者优先；</li><li>熟悉AI大模型、自然语言处理或机器学习应用开发,具备AI相关开发经验者优先；</li><li>有个人项目经验优先，如 GitHub 开源项目、个人博客或其他技术成果；</li><li>具备一定前端开发能力，能够协助前端实现功能或快速验证产品原型（如 React、Vue、HTML/CSS/JS 等）；</li><li>拥有良好的产品思维与沟通能力，能够理解业务需求并提出优化方案；</li><li>具备快速学习能力，乐于研究新技术，并能够在团队中推动技术落地。</li></ol>', '1-3年', '05f89697ede61dd9031-2d6-FVNQ', '深圳 · 南山区 · 科技园', '11-18K', 'Golang, Java, Docker, Zookeeper, MySQL, Redis, 搜索/推荐/广告经验, Dubbo', '后端开发工程师 (Java)', 'https://www.zhipin.com/job_detail/05f89697ede61dd9031-2d6-FVNQ.html', '节日福利, 五险一金, 带薪年假, 加班补助, 定期体检, 年终奖, 通讯补贴');
INSERT INTO `jobs` VALUES (118, '瑞维控股', '物业管理', '100-499人', '不需要融资', '本科', '<p>【Java后端开发经验2年左右，愿意转产品方向的工程师】</p><p><strong>岗位职责</strong></p><ol><li>参与公司产品规划，结合公司发展战略，策划及统筹产品的发展规划，明晰定位、目标、策略并落实、实施；</li><li>负责需求研究、产品调研；编写客户需求文档；</li><li>负责市场洞察、需求分析、产品设计、产品验收等；参与行业竞品分析、产品商业业务计划制定，提出产品改善计划；</li><li>研究行业最新产品的技术发展方向及趋势，参与制定公司产品发展策略；</li><li>规划设计产品并撰写产品需求说明文档与产品原型设计，设定产品路线图，制定产品上线和改版计划，推动开发团队高质量完成产品开发与迭代；</li><li>负责在项目推进过程中的协调沟通工作，与开发、业务等团队配合，协调各方资源进行产品全生命周期管理，不断改进和提升产品的质量；</li><li>撰写产品相关资料与产品解决方案，承担产品培训、宣传、技术交流等支持工作。</li></ol><p><strong>任职要求</strong></p><p><strong>任职要求</strong></p><ol><li>全日制统招本科及以上学历，计算机、软件工程等相关专业，2年以上开发或者测试经验。</li><li>有Java开发经验，做过Java项目开发，熟练掌握Java基础知识。</li><li>熟悉 SpringBoot/SpringCloud/Dubbo/MyBatis/Redis 等框架和技术，熟悉多线程编程，深入理解 Spring 底层原理及运行机制。</li><li>熟悉python脚本编写，熟悉至少一种自动化测试工具，例如 Selenium、JUnit、TestNG等；</li><li>熟练掌握 SQL 基础知识，熟悉 MySQL、Oracle、SQL Server 等一种或多种常用数据库，能够进行数据库脚本的编写、应用开发及相关脚本优化。</li><li>熟悉 Linux 常用命令，能够在 Linux 环境下进行开发和部署。</li><li>能熟练使用浏览器开发者工具分析bug，熟悉html、 javascript等前端开发脚本优先。</li><li>熟悉常用的测试工具jmeter，postman等。</li><li>具备较强的学习能力和技术钻研精神，有良好的服务意识和较强的沟通能力，能够独立处理开发过程中遇到的问题。</li></ol>', '1-3年', '36316ddd3208c5ff03F83tq_E1tS', '深圳 · 南山区 · 科技园', '7-12K·13薪', 'Java, Python, SpringCloud, Dubbo, MySQL, 大数据经验, 微服务经验, 不接受居家办公, 产品', '产品助理/专员（Java方向）', 'https://www.zhipin.com/job_detail/36316ddd3208c5ff03F83tq_E1tS.html', '定期体检, 餐补, 带薪年假, 全勤奖, 年终奖, 五险一金, 团建聚餐');
INSERT INTO `jobs` VALUES (119, '深圳友康达药业', '电子商务', '100-499人', '未融资', '大专', '<ol><li>有在轻流合作的公司⼯作过的相关经验及运营过清流系统的相关⼯作者优先。</li><li>搭建过多个轻流系统的相关工作经验。以及手写过轻流系统的经验者优先4、依据业务场景配置表单、设计审批流程（下单审批、发货审批等），实现物流⾃动下单、物流进度跟进等自动化场景，搭建多维度报表及数据看板，配置机器人消息推送，完成全流程业务数字化；</li><li>持续优化低代码平台上的业务流程，解决表单、流程配置中的卡点问题，提升业务操作效率。</li><li>有符合以上条件的求职者欢迎提供相关作品！！！二、技术开发与系统对接1、使用 Java/Python 编写脚本或后端代码，开发并对接IPO 接口，解决低代码平台无法覆盖的复杂业务需求；</li><li>管理 MySQL/Oracle 等数据库，编写并优化 SQL 查询语句，提升数据交互效率；</li><li>负责多系统间的数据交互与对接，实现不同系统间的数据联动、核对与同步，保障跨系统数据准确性。三、业务需求对接与方案输出1、主动收集各部门信息化需求，结合低代码平台特性及后端开发能力，输出低代码或 “低代码 + 定制开发” 的混合解决方案；</li><li>向业务方讲解技术方案，推动数字化转型落地，跟进上线后效果反馈，持续迭代优化系统；</li><li>沉淀低代码平台搭建经验，形成标准化的配置模板或解决方案，提升团队整体交付效率。四、系统运维1、负责公司低代码系统及关联 IT 系统的日常监控、维护，及时排查并处理系统故障、数据异常等问题，确保系统稳定运行和高可用性；</li><li>梳理系统运维手册，记录常见问题及解决方案，提升系统运维效率。</li></ol>', '1-3年', '424130f085636a120nV539-6FFVV', '深圳 · 龙岗区 · 南联', '10-15K', '', 'IT 系统开发工程师（低代码 + 后端）', 'https://www.zhipin.com/job_detail/424130f085636a120nV539-6FFVV.html', '零食下午茶, 底薪加提成, 全勤奖, 加班补助, 带薪年假, 定期体检, 绩效奖金, 补充医疗保险');
INSERT INTO `jobs` VALUES (120, '深圳市欢喜堂健康咨询', '电子商务', '100-499人', '', '大专', '<p>岗位名称轻流低代码开boss发实施工程师</p><p><strong>岗位职责</strong></p><ol><li>根据业务场景配置表单、设计多级复杂审批流（下单、发货、对账、退换货等），⽀持分⽀流转、加签、抄送、驳回回流等全场景配置。</li><li>搭建业务自动化场景，实现物流自动下单、进度跟进、数据回写、库存联动等功能，打通业务闭环；配置机器⼈完成消息推送、定时数据同步等自动化操作。</li><li>制作订单、物流、对账等多维度数据报表与可视化看板，输出经营分析数据，支撑企业管理决策。</li><li>持续排查并解决表单、流程、自动化运行卡点与问题，优化业务流程，提升整体工作效率。二、代码开发与系统接口对接1、使用Java/Python编写脚本及后端代码，开发低代码平台无法实现的复杂个性化业务功能。</li><li>负责IPO及第三方接口开发、适配与联调，做好数据校验、异常处理，保障接口稳定运行。</li><li>打通多系统数据壁垒，实现跨系统数据联动、核对与同步，确保数据准确、实时。</li><li>负责对接后系统运维、问题排查和功能迭代，持续优化接口性能与数据交互逻辑。</li></ol><p><strong>任职要求</strong></p><ol><li>核心必备经验：具备轻流系统从零搭建、落地、运营优化的完整项目经验，有轻流合作服务商从业经历者优先。</li><li>精通轻流全套核心功能，可独立完成表单、审批流、自动化规则、数据看板、机器人的配置与落地。</li><li>掌握Java或Python开发能力，可独立编写脚本、开发对接接口，解决复杂业务需求。</li><li>熟悉物流、供应链、订单类业务流程，能精准拆解需求并落地数字化解决方案。</li><li>逻辑清晰，具备独立问题排查、项目交付能力，执行力与自主优化意识强。优先录用1、有轻流服务商驻场实施、整套企业低代码平台搭建落地经验；</li><li>有物流自动化、供应链数字化、多系统接口联动实战经验；</li><li>有IPO系统对接、跨平台数据打通项目经验。</li></ol>', '1-3年', '44ca77d4ab2960fb0nJ629y1FFpX', '深圳 · 龙岗区 · 龙岗中心城', '15-20K', 'Java', 'IT系统开发工程师（必须搭建过轻流系统！）', 'https://www.zhipin.com/job_detail/44ca77d4ab2960fb0nJ629y1FFpX.html', '');
INSERT INTO `jobs` VALUES (121, '彬彬美文化', '互联网', '0-20人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责公司出海短剧业务全系列后端系统的开发与日常维护，涵盖H5后台、APP服务端、运营管理后台、数据统计后台等核心业务系统，保障系统稳定运行。</li><li>独立完成后端接口开发、数据库表结构设计、核⼼业务逻辑开发，同步规范编写接口⽂档，保证代码及⽂档标准化、可维护。</li><li>配合前端完成接口联调对接，快速响应运营、产品的业务需求，高效完成功能迭代，支撑业务快速落地。</li><li>深度参与核⼼业务模块开发，包含用户体系、订单充值、广告投放数据、ROI统计、素材数据统计等关键业务功能搭建与优化。</li><li>负责线上日常问题排查与修复，快速处理接口异常、慢SQL卡顿、服务器运行异常等线上故障，保障业务平稳运转。</li><li>持续跟进业务发展需求，针对性优化系统性能，提升系统稳定性、接口响应速度及业务数据统计准确性。</li></ol><p><strong>任职要求</strong></p><ol><li>具备2年以上后端开发经验，有泛娱乐、短视频或内容付费类App开发经验者优先考虑2、熟练 Java/PHP/Go/Node.js 任一后端语言，有完整项目经验，可独立开发落地需求；</li><li>精通 MySQL，能自建表结构、编写 SQL，会 SQL 优化与数据问题排查；</li><li>熟悉 Redis 使用，精通接口开发，有后台管理系统开发实战经验；</li><li>掌握 Linux 常用命令，可完成服务部署、环境调试及线上问题排查；</li><li>代码规范，沟通协作良好，能独立负责中小型模块全流程开发；</li><li>责任心强，善于拆解业务需求，高效推进版本迭代落地。加分项1、拥有短剧、小说、视频、直播、游戏、出海APP相关项目后端开发经验。</li><li>熟练使用 AI开发工具，能够借助工具提升开发效率。岗位</li></ol><p><strong>福利</strong></p><p>入职即缴五险一金，按法定节假日休假。日常下午茶，舒适工作氛围，明确晋升路径。工作时间：9:30-12：00 13:30-19:00 大小周制度。</p>', '1-3年', '9d599a72243fa1bf0nJ43Ni9F1JV', '深圳 · 南山区 · 科技园', '10-15K', 'Java, Spring, MySQL, Redis, 游戏后端经验, 音视频经验', '后端开发工程师', 'https://www.zhipin.com/job_detail/9d599a72243fa1bf0nJ43Ni9F1JV.html', '绩效奖金, 零食下午茶, 团建聚餐, 年终奖, 五险一金, 底薪加提成');
INSERT INTO `jobs` VALUES (122, '星浩美邦', '进出口贸易', '100-499人', '不需要融资', '本科', '<p>一、 职位概述我们正在寻找一位经验丰富、充满热情的 Shopify 程序员。您将是我们团队的核心成员，负责设计、开发、优化和维护我们的 Shopify 商店，确保其在前端用户体验和后端功能上都达到⼀流⽔平。理想的候选⼈不仅是一名开发者，更是一名问题解决者。您需要对 Shopify 平台有深⼊的理解，精通 Liquid 模板语言，具备坚实的 Java 后端开发能力，并且对 UI/UX 设计有敏锐的洞察力，能够将创意转化为美观、流畅且高效的在线商店。</p><p><strong>二、 核心职责</strong></p><ol><li>Shopify 主题开发与定制 (前端 & Liquid)· 使用 Liquid 编程语言，深度定制和开发响应式、高性能的 Shopify 主题。· 根据 UI/UX 设计稿，精准实现网页布局、交互元素和动画效果，确保跨浏览器和设备兼容。· 优化前端性能，包括页面加载速度、图片懒加载、代码压缩等，以提升用户体验和搜索引擎排名。</li><li>应用开发与后端集成 (Java)· 设计、开发并维护与 Shopify API（REST Admin API, GraphQL）集成的自定义应用或后端服务。· 使用 Java 及相关技术栈（如 Spring Boot）构建稳定、可扩展的后端系统，用于处理订单、库存、客户数据等。· 集成第三方系统（如 ERP, CRM, PIM, 支付网关、物流系统）。</li><li>UI/UX 实现与优化· 与设计团队紧密合作，理解设计意图并提供技术可行性建议。· 将设计原型（Figma, Adobe XD, Sketch 等）转化为高质量的代码，注重细节和像素级完美。· 持续进行 A/B 测试和用户体验优化，以提高转化率。</li><li>商店管理与技术支持· 负责 Shopify 商店的日常管理、配置和更新。· 快速诊断并解决网站出现的技术问题，确保线上商店的稳定运行。· 管理并安装必要的 Shopify 应用，并评估其性能和对网站速度的影响。</li><li>代码质量与团队协作· 编写整洁、可维护、可复用的代码，并进行代码审查。· 使用 Git 等版本控制工具进行协作开发。· 撰写清晰的技术文档。</li></ol><p><strong>三、 任职要求</strong></p><p>必备技能与经验：· 工作经验： 拥有 2 年以上 Shopify 开发经验，并至少完整参与过 2 个以上的 Shopify 项目。· Shopify & Liquid： · 精通 Shopify 平台架构、主题结构、区块和模块。 · 深入掌握 Liquid 模板语言，能进行复杂逻辑处理和自定义模块开发。· Java 后端开发： · 熟练掌握 Java 及主流框架（如 Spring, Spring Boot）。 · 有使用 Java 与 Shopify API 或其他 RESTful/GraphQL API 进行集成的实际经验。 · 了解数据库设计（MySQL, PostgreSQL 等）和 SQL 优化。· 前端技术 (UI)： · 精通 HTML5, CSS3, JavaScript (ES6+)。 · 熟悉至少一种现代 CSS 框架（如 Tailwind CSS）和 CSS 预处理器（如 SASS/SCSS）。 · 具备响应式网页设计和移动端优先的开发理念。· 版本控制： 熟练使用 Git。优先考虑条件：· 有开发并发布 Shopify 公共/私有应用的经验。· 熟悉 Shopify 的元字段（Metafields）和自定义功能实现。· 了解前端框架（如 Vue.js, React）在 Shopify 主题中的应用。· 具备性能优化、SEO 最佳实践的实战经验。· 拥有良好的审美和 UI/UX 设计感。个人素质：· 出色的解决问题能力： 能够独立分析并解决复杂的技术挑战。· 强烈的责任心： 对代码质量和项目成果负责。· 良好的沟通能力： 能够与非技术团队成员（如设计师、营销人员）有效协作。· 积极主动： 持续关注 Shopify 及 Web 开发领域的最新技术和趋势。</p>', '1-3年', 'b6bc6fe183e9632703x50t61F1tT', '深圳 · 龙岗区 · 坂田', '15-20K', 'Java, 物联网经验, SpringCloud, Oracle', 'Shopify 程序员', 'https://www.zhipin.com/job_detail/b6bc6fe183e9632703x50t61F1tT.html', '节日福利, 绩效奖金, 五险一金, 年终奖, 全勤奖, 零食下午茶, 保底工资, 有无线网, 工龄奖, 团建聚餐');
INSERT INTO `jobs` VALUES (123, '日志易', '计算机软件', '100-499人', 'C轮', '本科', '<p>-</p><p><strong>岗位职责</strong></p><p>负责⼤数据系统的研发和维护-</p><p><strong>任职条件</strong></p><ol><li>计算机及相关专业，本科及以上学历，具有良好的计算机相关知识 2、互联⽹公司2年以上研发经验。</li><li>熟练掌握linux下多线程编程；</li><li>熟练使⽤java，python语言编程 5、参与过分布式高性能服务的设计开发，有⼤规模分布式系统的实践经验者优先 6、熟悉Elasticsearch相关知识的优先</li></ol>', '1-3年', 'e3214f2e28ca34c80nF42tm6FVFW', '深圳 · 南山区 · 南头', '14-17K·13薪', 'Java, 不接受居家办公, 分布式经验, Elasticsearch, 微服务经验, SpringCloud, MySQL, MyBatis, Redis, Spring', 'java开发-2年以上经验-深圳', 'https://www.zhipin.com/job_detail/e3214f2e28ca34c80nF42tm6FVFW.html', '五险一金, 年终奖, 带薪年假, 加班补助, 生日福利, 股票期权, 意外险, 定期体检, 绩效奖金, 通讯补贴, 零食下午茶');
INSERT INTO `jobs` VALUES (124, '三基同创', '智能硬件', '100-499人', '未融资', '本科', '<ol><li>一年以上服务器端开发经验2. 全日制大专以上学历，电子、计算机软件、通信类相关专业；</li><li>熟悉JAVASCRIPT,NODEJS，JAVA4 熟悉MYSQL 数据库开发5. 有JAVA语言项目开发经验，调试经验丰富，有NODEJS开发经验优先考虑；</li><li>工作主动积极，团结协作，责任感强，能吃苦，并乐于接受挑战;</li><li>良好的表达和沟通能力，工作态度好，性格开朗。</li></ol><p><strong>福利待遇</strong></p><ol><li>成绩优异者可获得公司的技术股份分红；</li><li>缴纳社保与养老的五险一金；</li><li>法定节假日正常放假，工作满1年享受年假；</li><li>定期安排公司活动和免费旅游；</li><li>绩效奖励、年终奖金、加班补贴。</li></ol>', '1-3年', '4592f288f6c98a661HZ_3tq5FlZV', '深圳 · 宝安区 · 西乡', '9-14K', 'Java, Nginx, 不接受居家办公, MySQL', '服务器开发工程师', 'https://www.zhipin.com/job_detail/4592f288f6c98a661HZ_3tq5FlZV.html', '节日福利, 加班补助, 员工旅游, 年终奖, 带薪年假, 全勤奖, 五险一金');
INSERT INTO `jobs` VALUES (125, '柏悦', '跨境物流', '0-20人', '未融资', '大专', '<p><strong>岗位职责</strong></p><ol><li>主导后端核心模boss块、公共服务的架构设计与开发，负责技术难点攻坚、系统性能优化与架构演进；</li><li>熟练运用 CodeBuddy、Cursor、Kiro 等 AI 编程工具完成复杂业务编码、逻辑调试、代码重构，输出标准化代码注释与技术文档；</li><li>探索 AI 赋能研发的最佳实践，梳理标准化使⽤流程，带动团队落地 AI 提效⽅案，统⼀开发规范；</li><li>主导代码评审、技术方案评审，把控项目技术质量，配合团队完成版本迭代、线上故障处理；</li><li>沉淀技术经验，完善项⽬知识库、开发规范，提升整体研发交付能力。</li></ol><p><strong>任职要求</strong></p><ol><li>3 年及以上后端开发经验，具备独立负责模块 / 项目的能力，精通后端技术体系；</li><li>深度使用各类 AI 编程工具，熟练通过提示词优化、工具配置提升编码、调试、文档效率；</li><li>具备架构思维，熟悉微服务、分布式、高可用设计，有复杂业务系统搭建经验；</li><li>乐于分享，擅长总结方法论，能够借助 AI 工具优化团队工作流程、降低重复工作量；</li><li>学习能力强，拥抱新技术，沟通协调能力优秀，具备较强的问题复盘与风险预判能力；</li><li>掌握 MySQL / Redis 基础操作，理解缓存与持久化基本设计；</li><li>具备基本的 Git 使用习惯，理解分支管理与 Code Review 流程。</li></ol>', '1-3年', '002d54c28add91ae0nB-39y5EVdR', '深圳 · 龙岗区 · 坂田', '10-15K', '', '后端开发', 'https://www.zhipin.com/job_detail/002d54c28add91ae0nB-39y5EVdR.html', '交通补助, 五险, 通讯补贴, 节日福利, 团建聚餐, 零食下午茶');
INSERT INTO `jobs` VALUES (126, '名通科技', '计算机软件', '100-499人', '不需要融资', '本科', '<p>【</p><p><strong>岗位职责</strong></p><p>】1、需求分析与设计：深度理解项目需求，和项目经理、产品经理以及客户沟通，分析需求文档，确保对业务流程和</p><p><strong>技术要求</strong></p><ol><li>编码实现：根据需求文档或者需求说明，使用Java、SQL语言进行编码，遵循编码规范和最佳实践，确保代码的可读性、可维护性和扩展性。利用Spring Boot、Spring Cloud、Nacos、Redis、RocketMQ等流行框架提高开发效率。编写单元测试，确保代码质量。</li><li>代码调试与优化：对代码进行调试，解决开发过程中出现的问题。性能调优，包括数据库查询优化、算法优化等。代码审查，和其他开发者一起保证代码质量。</li><li>文档编写：编写技术文档，如设计文档、接口文档、用户手册、工作量评估文档(如COSMIC、NESMA、FPA)等。更新维护文档，保持文档与实际代码的一致性。</li><li>测试与部署：配合测试团队进行集成测试、系统测试。协助解决测试阶段发现的问题。参与软件的部署工作(包括CI/CD流水线)，有时需要进行现场技术支持。【</li></ol><p><strong>岗位要求</strong></p><ol><li>有一年以上java开发工作经验；一年以上需求分析或项目管理经验，有微服务和DOCKER实际开发经验优先；</li><li>掌握项目管理流程、具备较强的需求分析能力；</li><li>具有较强的协调能力、沟通能力和统筹管理能力；</li><li>具有较强的责任心和工作热情，能在高压下工作；</li><li>能接受短期其他省份出差，有DEVOPS认证优先；</li><li>具备统计学、数据分析相关背景优先。</li></ol>', '1-3年', '75b7dbd0f57778481H1-2Nu7FltT', '深圳 · 南山区 · 科技园', '9-14K·13薪', 'Java, Docker, 微服务经验, SpringCloud, Redis, Spring', 'java开发工程师（双休/年终奖）', 'https://www.zhipin.com/job_detail/75b7dbd0f57778481H1-2Nu7FltT.html', '节日福利, 团建聚餐, 补充医疗保险, 五险一金, 股票期权, 带薪年假, 定期体检, 年终奖, 结婚礼金, 加班补助, 员工旅游, 零食下午茶, 生育礼金, 意外险');
INSERT INTO `jobs` VALUES (127, '育昇', '半导体/芯片', '20-99人', '', '本科', '<p>Responsibilities(负责):•Participate in vhome project on research & development. 参与香港养老院项目的研发.•Participate in ERP/CRM/others project on in-house applications. 参与公司内部产品的研发，包括ERP/CRM以及其它应用平台。•Develop, design & enhance applications to continuously perform stably & reliably.负责设计、研发、测试以及优化现有产品。•Gather user requirements and perform basic analysis.收集和整理客户需求，并做需求分析。•Conduct UAT/SIT to ensure the application is ready to roll out.负责测试环境和研发环境的产品发布和迭代。Requirements（能⼒）:• Strong Java skills and Spring framework (Spring Boot, Spring MVC, Spring Security，Spring Cloud). 2+ years of working experience in software development, Candidate with more experience would be considered as Senior Java Developer。较强的Java编写能⼒，特别是在SpringBoot3+和微服务⽅面，至少具备2年的编程经验。•Strong SQL operation abilities and performance optimization, include stored procedures programs, create indexes to speed up. MySQL and PostgreSQL for more than 1 years ‘experience.较强的数据库操作能⼒，包括SQL编写，以及建立表索引、编写存储过程等。有1年以上MySQL、PostgreSQL编程经验。•API Design sides, good at Rest API program and make secure of interface, Used Redis、Kafka、MQ would be plus.较强的API编写能力，特别是Rest API以及确保接口安全。•Good at MyBatis or Hibernate skills, known XML coding is plus.拥有MyBatis 或者Hibernate方面的工作经验，熟悉XML更好。•具備PHP編碼的能力，會被優先考慮，可以完善現有PHP產品主要是舊係統維護和升級•具備Android編碼的能力，將被優先考慮，可以完善現有客戶端產品舊係統的維護和升級•Good interpersonal communication skills and able to work independently较好的人际关系，善于沟通，能够承受压力，具备独立完成任务的能力。•Experience in integrating AI modules is plus, such as GCP Vertex AI, OpenAI. Ability to build enterprise AI mode is plus.使用过Google的Vertex AI, OpenAI,有能力构建企业自己的AI模型者优先。•Bachelor’s degree holder in Information Technology, Computer Science or related discipline.计算机相关专业毕业，其它专业的优秀者也会考虑。•Working in Shenzhen Office, but Task and team manager from Hong Kong Office.香港公司，但是工作在深圳，但是大部分任务和管理来自于香港。• 公司实行5天8小时工作制，按国家法定假期休假</p>', '1-3年', 'f25c6852b20b4a82031_2dq5E1VX', '深圳', '13-18K·13薪', 'Java, Nginx, 微服务经验, PostgreSQL, SpringCloud, MySQL, MyBatis, Spring, ERP开发经验', 'Java高级工程师', 'https://www.zhipin.com/job_detail/f25c6852b20b4a82031_2dq5E1VX.html', '年终奖, 带薪年假, 五险一金');
INSERT INTO `jobs` VALUES (128, '知律科技', '企业服务', '20-99人', '天使轮', '本科', '<p><strong>一、岗位职责</strong></p><ol><li>负责公司SaaS平台（基于SaaS的行业级一体化管理软件，融合了OA、CRM、HRM、项目管理、财务、团队协作、电商等功能）的开发与优化；</li><li>根据产品及项目的开发进度和任务分配，按时按量保质完成项目编码，并根据需要及时修改、完善模块功能。</li></ol><p><strong>二、职位要求</strong></p><ol><li>全日制本科及以上学历，计算机或其它相关专业，1年及以上开发经验；</li><li>扎实的JAVA编程基础， 熟悉各种开源的框架如SSM、Spring Cloud、Spring Boot等；</li><li>熟练使用MySQL数据库， 掌握基本的SQL优化技巧；</li><li>参与过中型/大型工作流平台或引擎或者CRM、OA等企业管理系统相关项目者优先；</li><li>强烈的责任心和团队合作能力，善于沟通，良好的学习能力，逻辑思维能力强、条理性好。</li></ol><p><strong>三、薪资福利</strong></p><p>1、薪资待遇：面议，优秀者薪资不受此招聘启事限制；2、</p><p><strong>福利待遇</strong></p><ol><li>培训体系：新员工入职培训+行业知识培训等；</li><li>晋升空间：优秀者随时晋升，上升空间无限；</li><li>符合条件的员工，可享受公司面对骨干成员的股权激励计划。四、工作环境公司位于创维半导体设计大厦西座，这里地处深圳高新科技园核心区，地铁1号线高新园站直达，毗邻深南大道与万象天地商圈。大厦采用5A智能化办公系统与高速电梯，室内环境干净优雅、宽敞通透，中央空调、舒适座椅、绿植景观一应俱全，更贴心配备午休睡床。楼下步行即达万象天地、大沙河生态长廊，周边汇聚腾讯、大疆、TCL等顶尖科技企业，形成强大的产业生态与人才磁场，将便捷交通、高品质办公、购物餐饮与自然休闲完美融于一体。在这里，城市繁华与自然河畔兼得，高效工作与品质生活相融，诚挚期待志在科技前沿的你加入！五、公司网站公司官网：www.kinglex.cn</li></ol>', '1-3年', 'f8c3ead09e51539c1nJ63d67FVJU', '深圳 · 南山区 · 科技园', '11-20K', 'Java, 企业级应用开发, SpringCloud, 分布式技术, SpringBoot, Spring, SSM, ERP开发经验, java, 微服务经验, MySQL, MyBatis, 后端开发', 'Java软件工程师', 'https://www.zhipin.com/job_detail/f8c3ead09e51539c1nJ63d67FVJU.html', '带薪年假, 节日福利, 员工旅游, 股票期权, 五险一金');
INSERT INTO `jobs` VALUES (129, '拜特科技', '计算机软件', '100-499人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责承接需求分析人员规格，根据需求规格进行方案设计；</li><li>负责系统的整体架构设计及数据库结构设计；</li><li>参与系统设计，以确保设计与代码质量；</li></ol><p><strong>任职要求</strong></p><p>1、统招本科以上学历学信网可查（硬性条件，不符合请不要投递），计算机相关专业，2-3年以上开发经验2、具有良好的技术⽅案设计能⼒和设计⽅案文档编写能力，具有⼀定的培训能力及培训辅导经验3、工作细致，具有良好的团队使用精神，高度的责任感，较强的适用，沟通，表达能力4、精通J2EE技术，深入理解JVM基础概念，熟练掌握I/O多线程，API编程及熔断处理机制5、熟悉Spring、Spring Boot和Spring Cloud体系(阅读过源码及扩展过源码或编写过框架者优先)6、具备良好的编程习惯，熟悉mock技术，并能编写单元测试7、熟悉tomcat、undertow、nginx等开源中间件8、至少熟悉一种消息中间件，如RabbitMQ、RocketMQ、Kafka9、熟悉Redis、ES、ELK，并具备相关实战经验10、熟悉Mysql、Oracle关系型数据库13、有AI相关项目经验、大型微服务架构成功搭建经验者优先</p>', '1-3年', '2d03692dee8966c20nJ72d-_EFtS', '深圳 · 南山区 · 蛇口', '14-17K·13薪', 'Java, 不接受居家办公, Docker, 微服务经验, SpringCloud, MySQL, MyBatis, Redis, SQL Server, 架构设计经验, Spring, Oracle', '中级java开发工程师', 'https://www.zhipin.com/job_detail/2d03692dee8966c20nJ72d-_EFtS.html', '零食下午茶, 绩效奖金, 补充医疗保险, 年终奖, 团建聚餐, 住房补贴, 员工旅游, 节日福利, 股票期权, 带薪年假, 定期体检, 底薪加提成, 五险一金');
INSERT INTO `jobs` VALUES (130, '深圳智链云桥互联科技', '互联网', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责系统核心模块的设计与开发，保障代码质量与系统稳定性</li><li>参与技术难题攻关，完成关键功能的实现与性能优化</li><li>配合产品与业务团队推进项目落地，确保开发进度与交付质量</li><li>编写高质量代码，参与代码评审，推动团队技术规范落地</li><li>协同团队成员完成系统架构优化与技术迭代</li></ol><p><strong>任职要求</strong></p><ol><li>具备扎实的编程基础，熟悉常用数据结构与算法，掌握⾯向对象设计原则</li><li>熟悉主流开发框架，能够熟练运⽤相关技术完成业务开发任务</li><li>具备良好的问题分析与解决能⼒，能独立承担开发任务并推动问题闭环</li><li>具有良好的沟通协作能力，能够⾼效配合团队完成项目目标</li><li>具备持续学习意识，能够快速掌握新技术并应用于实际工作</li></ol>', '1-3年', 'f3f748df10929ac50nd839y9F1dY', '深圳 · 南山区 · 后海', '12-22K', '', 'Java', 'https://www.zhipin.com/job_detail/f3f748df10929ac50nd839y9F1dY.html', '五险一金, 零食下午茶, 节日福利, 全勤奖');
INSERT INTO `jobs` VALUES (131, '私募排排网', '互联网金融', '100-499人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>参与项目需求评审、工作量评估、功能开发；</li><li>支撑下游应用数据需求（包括基础数据、衍⽣数据、计算指标等）；</li><li>发现和解决业务系统技术问题，保证系统质量、性能和稳定性。</li></ol><p><strong>任职要求</strong></p><ol><li>全⽇制统招本科以上学历，2年以上Java开发经验；</li><li>精通Java语⾔，熟悉Spring Boot/Spring Cloud等主流框架。</li><li>深入理解面向对象设计原则，熟悉常⽤的设计模式。</li><li>熟悉MySQL/Oracle等关系型数据库，了解NoSQL数据库如MongoDB、Redis等。</li><li>熟悉Linux操作系统，能熟练使用Git等版本控制工具。</li><li>了解性能调优、安全防护等相关知识。</li><li>有算法开发经验优先。</li><li>有金融行业项目开发经验优先。</li><li>有数据管理系统项目开发经验优先。</li><li>熟悉AI编程优先。</li></ol>', '1-3年', 'a1e08f1f558053850nB43tm4ElRW', '深圳 · 福田区 · 上沙', '13-25K', 'Java, SpringCloud, MySQL, Spring', 'java开发工程师', 'https://www.zhipin.com/job_detail/a1e08f1f558053850nB43tm4ElRW.html', '年终奖, 节日福利, 定期体检, 五险一金, 员工旅游, 带薪年假');
INSERT INTO `jobs` VALUES (132, '深圳库里斯机器人', '电子/硬件开发', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><p>云端业务平台开发：负责设计、开发和维护机器人云端业务中台，包括任务调度、车队管理、状态监控、数据报表、用户与权限管理等系统。云边端通信与协同：构建高可用、⾼并发、低延迟的云-边-端通信框架，确保云端指令可可靠下发⾄机器⼈，并稳定接收机器人的状态、数据上报。实时数据处理：负责机器人海量实时数据（位置、状态、传感器数据、⽇志等）的采集、处理、存储与可视化，为运营、算法和决策提供支持。核心服务开发：参与或主导关键服务开发，如高精度地图管理、任务编排与派发、远程遥操作（Remote Operation）、仿真测试平台等。性能与稳定性保障：持续优化系统架构，保证云端服务的高可用性、可扩展性和安全性，处理线上故障。跨团队协作：与前端、机器人本体软件（ROS2）、算法（导航、视觉）、硬件（嵌入式）、产品等团队紧密协作，共同完成产品功能的交付与落地。</p><p><strong>任职要求</strong></p><ol><li>本科及以上学历，2年以上后端相关经验。</li><li>精通Java，熟练掌握脚本语言（如Shell/Python）。</li><li>熟练掌握主流微服务框架（如Spring Cloud,Dubbo,GoMicro,Kratos等。</li><li>精通MySQL、PostgreSQL等关系型数据库，具备优秀的数据库设计和高性能查询优化能力。</li><li>熟悉Docker、Kubernetes(K8s），有在容器化环境中开发部署的经验。</li><li>深刻理解TCP/IP、HTTP/HTTPS、WebSocket、gRPC 等网络协议和通信框架，有物联网（10T）通信协议（如MQTT)开发经验者优先。</li><li>有机器人、物联网（1oT）、车联网、自动驾驶等相关领域后台开发经验，熟悉机器人相关概念和架构，了解ROS/ROS2基础通信机制。</li></ol>', '1-3年', '9e72ca396acd372d0nBy29u0EVJX', '深圳', '12-15K·13薪', 'Java, 不接受居家办公, C++, 机器狗  无人机, 无人车, MySQL', '机器狗后端开发工程师', 'https://www.zhipin.com/job_detail/9e72ca396acd372d0nBy29u0EVJX.html', '全勤奖, 绩效奖金, 工龄奖, 年终奖, 团建聚餐, 底薪加提成, 住房补贴, 加班补助, 节日福利, 有无线网, 补充医疗保险, 意外险, 五险一金, 带薪年假, 包吃, 保底工资, 免费工装');
INSERT INTO `jobs` VALUES (133, '锐莱科技', '电子商务', '100-499人', '不需要融资', '本科', '<p>备注：1.本岗位需要线下面试和做测试，介意者请勿扰，谢谢！2.本岗位硬性要求有Python经验，跨境经验优先！</p><p><strong>岗位职责</strong></p><ol><li>AI工具场景开发：基于Claude、ChatGPT等AI模型，深耕跨境电商业务场景，独立开发实用AI⼯具，涵盖商品⽂案批量⽣成、多语言客服自动回复、竞品数据分析报告、智能选品助⼿等核心功能，落地解决跨境运营实际问题；</li><li>Prompt设计与调优：针对跨境业务需求精准设计、迭代优化Prompt指令，打磨模型输出效果，确保AI生成内容贴合业务标准、可直接落地使用，杜绝无效、表层化输出内容；</li><li>AI服务开发对接：使用Python/Java语言对接现有跨境业务系统，完成AI接口调用、数据处理、结果存储与页面展示等全流程开发，搭建稳定可用的AI业务服务工具；</li><li>模型输出优化：结合亚马逊、Shopify、速卖通等跨境平台真实业务数据，优化AI模型上下文输入逻辑，持续提升模型输出精准度、实用性，赋能跨境运营提效。</li></ol><p><strong>任职要求</strong></p><ol><li>AI模型实操能力（核心优先）：熟练使用Claude，有Claude API实际项目开发经验（非网页聊天使用），可清晰阐述Prompt设计思路、上下文处理方案及项目落地问题与解决方案；熟悉Claude Tool Use、Streaming、长上下文等基础API用法，了解Sonnet、Opus模型差异，可根据业务场景精准匹配模型与参数；</li><li>代码开发能力：精通Python、Java任意一门编程语言，可独立完成AI接口调用、数据处理、结果存储与展示的完整开发流程；无需深耕算法，能够编写稳定、规范、可读性强的落地代码即可；</li><li>行业经验（优先加分）：有跨境电商行业从业或项目经验，熟悉亚马逊、速卖通等主流跨境平台业务逻辑，了解跨境选品、运营、数据分析、客服售后等核心业务场景；</li><li>核心能力要求：聚焦业务落地，具备较强的问题解决能力，善于借助AI工具拆解、解决跨境电商实际运营痛点，追求工具实用性与业务提效成果。</li></ol>', '1-3年', 'b60358597679ea0c0nJ72tS_F1RQ', '深圳', '10-13K', 'Java, 不接受居家办公, SpringCloud, MySQL, 亚马逊经验, AI, Python', 'AI应用工程师', 'https://www.zhipin.com/job_detail/b60358597679ea0c0nJ72tS_F1RQ.html', '员工旅游, 零食下午茶, 餐补, 带薪年假, 五险一金, 节日福利, 俱乐部活动, 生日福利, 年终奖, 团建聚餐');
INSERT INTO `jobs` VALUES (134, '深圳慧力创新科技', '人工智能', '0-20人', '', '本科', '<p><strong>岗位职责</strong></p><ol><li>独立负责AI应用前后端功能开发（React/Vue + Node/Go/Py）；</li><li>负责AI Agent的任务编排、记忆管理、技能管理等落地；</li><li>负责APP开发以及AI能力集成到Android/iOS应用；</li></ol><p><strong>任职要求</strong></p><ol><li>熟练掌握 Java/Kotlin/Swift ⾄少⼀种以及Python/Go/Node.js ⾄少一种;</li><li>对大模型以及Agent、知识库等具有较好的认知，拥有业务实战经验更佳；</li><li>熟练使⽤ React/Vue 框架;</li><li>熟悉 MySQL/PostgreSQL 和 Redis，具备扎实的数据库设计能力;</li><li>熟练使用 Git/Gerrit、Linux 常用命令；</li><li>我们希望你是热爱技术、对AI充满热情，具有团队作战精神，勇于担当的；经验要求：以下至少满足两条▸ 有互联网应用开发经验，不是个人Demo；▸ 同时写过前端+后端，能独立闭环一个功能模块；▸ 写过Tool Call/Function Calling，调过Prompt；▸ 有移动端开发经验（原生/跨平台均可）；【加分项】有AI应用项目（带作品/链接/Demo也行）；写在最后;我们是AI应用初创公司，为节省彼此宝贵时间，如果介意勿投！岗位</li></ol><p><strong>福利</strong></p><ol><li>五险一金；</li><li>年假、双休、调休；</li></ol>', '1-3年', '1b33661df2d0f8b80nd43du5GVNY', '深圳', '7-12K·13薪', 'Java, Golang, Python, JVM, Docker, Nginx, Spring, Dubbo, MySQL, Redis, Hadoop, PostgreSQL, MongoDB', 'AI应用开发工程师', 'https://www.zhipin.com/job_detail/1b33661df2d0f8b80nd43du5GVNY.html', '');
INSERT INTO `jobs` VALUES (135, '深圳奈森拓科技', '互联网', '100-499人', '', '本科', '<p>项目跨境客服系统背景及挑战：1. 服务稳定性：全球各地客服7*24小时强依赖系统办公，超高在线率及在线时长，2.海量数据处理： 面向的客户主要是跨境电商头部卖家，3. 通⽤化设计：⼤客户需求场景复杂及多样性做功能抽象</p><p><strong>任职要求</strong></p><ol><li>逻辑能⼒强，善于抽象复杂业务场景；</li><li>表达清晰，对业务理解有自己的见解3、了解数据库原理，具备SQL优化和数据处理能⼒；</li><li>具备扎实的Java编程能力，熟悉主流开发框架与工具；</li></ol><p><strong>岗位职责</strong></p><ol><li>负责公司核心系统的Java开发与维护，保障系统稳定运行；</li><li>参与需求分析与系统设计，完成模块功能的开发与集成；</li><li>编写高质量、可维护的技术文档，确保开发过程规范可控。岗位优势：</li><li>有完备的技术框架及基础设施2、由阿里资深架构师直接指导3、项目范围足够大，业务场景足够多</li></ol>', '1-3年', '7c4bca55d27bb8690nV_2t2-EFBR', '深圳 · 南山区 · 科技园', '12-18K', 'Java, Spring, MySQL, Redis', '中级java开发工程师', 'https://www.zhipin.com/job_detail/7c4bca55d27bb8690nV_2t2-EFBR.html', '');
INSERT INTO `jobs` VALUES (136, '中科云遥', '计算机软件', '20-99人', '天使轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>核心后端开发：负责服务器端Java组件的设计、开发和维护，使用Java、Spring Boot等框架构建高并发、高可用的Web服务及RESTful API 。</li><li>GIS功能实现：基于ArcGIS Enterprise（Server/Portal/Data Store）进行二次开发和功能扩展；利用ArcObjects或ArcGIS Maps SDK for Java/JavaScript开发定制化GIS工具和业务模块 。</li><li>空间数据管理：设计并优化空间数据库结构，处理复杂的空间查询、空间分析及数据可视化业务逻辑；熟悉ArcSDE版本管理机制 。</li><li>系统集成与优化：负责GIS系统与其他企业业务系统（如OA、ERP）的API对接；排查系统性能瓶颈，优化代码及数据库查询 。</li><li>文档编写：撰写软件设计文档、数据库设计文档及系统部署手册 。</li></ol><p><strong>任职要求</strong></p><ol><li>学历专业：本科及以上学历，地理信息系统（GIS）、遥感、测绘、计算机科学与技术、软件工程等相关专业 。</li><li>经验要求：具有2年以上Java开发经验，并有实际的GIS项目开发经历（优秀硕士毕业生可放宽年限要求）。</li><li>编程语言：精通Java，熟悉IO、多线程、集合框架，熟悉JVM调优；掌握Spring、Spring Boot、MyBatis等主流框架 。ArcGIS技术栈：</li><li>熟练使用ArcGIS Desktop（ArcMap/ArcGIS Pro） 进行数据处理、制图及符号化配置 。</li><li>熟悉ArcGIS Server的安装、服务发布（MapService, GPService, FeatureService）及管理 。</li><li>熟悉ArcSDE空间数据引擎，了解地理数据库（Geodatabase）的版本管理和多用户编辑机制 。</li><li>熟悉ArcGIS API for Java（或JavaScript）者优先；有ArcObjects二次开发经验者优先 。数据库与工具：</li><li>数据库：熟练掌握PostgreSQL/PostGIS、Oracle或SQL Server等数据库，熟练编写SQL语句，掌握空间查询语言（如ST_Geometry）。</li><li>版本控制：熟练使用Git进行协作开发 。</li></ol><p><strong>综合素质</strong></p><ol><li>具备极强的责任心和团队协作精神，工作踏实、勤恳 。</li><li>具有较强的自学能力和沟通能力，能够快速理解业务需求并转化为技术实现 。加分项（符合任意一条优先考虑）：有ArcGIS Enterprise（Portal/GeoEvent/Data Store） 实际部署和运维经验 。熟悉三维GIS开发，如ArcGIS Pro SDK、CityEngine或Cesium与ArcGIS集成 。熟悉GDAL、GeoServer、GeoTools等开源GIS库，有影像数据处理（Raster/Imagery）经验 。有Docker、Kubernetes容器化部署经验，或熟悉云计算平台（AWS/Azure/阿里云）。</li></ol>', '1-3年', 'db7b410469dfb4331Hx73d2_FlBV', '深圳 · 福田区 · 梅林', '12-17K', 'Java, Tomcat, 分布式经验, Elasticsearch, 微服务经验, SpringCloud, MySQL, Redis, Spring, Oracle', 'java开发工程师', 'https://www.zhipin.com/job_detail/db7b410469dfb4331Hx73d2_FlBV.html', '带薪年假, 节日福利, 交通补助, 住房补贴, 股票期权, 绩效奖金, 通讯补贴, 补充医疗保险, 五险一金');
INSERT INTO `jobs` VALUES (137, '深圳盼贤科技有限公司', '进出口贸易', '100-499人', '不需要融资', '本科', '<p>一、本岗位需在长沙总部办公！！！能接受的再投递简历噢！二、本岗位硬性要求是具备跨境电商erp项目开发经验，没有跨境电商ERP开发经验的勿投哦！</p><p><strong>岗位职责</strong></p><ol><li>负责跨境电商 ERP 系统全栈开发与迭代，完成 亚马逊 / Temu / Shein / 沃尔玛 等平台对接、多仓库 / 多币种、订单 / 库存 / 物流 / 财务 等核心模块开发，独⽴完成后端开发到前端页⾯实现、开发与部署、数据库设计优化及部署上线。</li><li>跟踪⾏业技术趋势，推进 AI、自动化等新技术在 ERP 业务落地。</li><li>参与需求分析、方案设计、接口联调、问题排查全流程，协同跨团队保障项⽬交付。</li><li>遵循开发规范，编写代码与技术文档，主导代码评审、性能优化与技术沉淀。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上计算机相关专业，2 年及以上 Java 全栈开发经验，有跨境电商 ERP 开发经验优先。</li><li>具备 ERP 系统 0-1 搭建或深度二次开发经验，熟悉订单、库存、物流、财务、平台同步、客户管理等核心模块开发，能独立主导或核心参与ERP系统的架构设计、模块开发、上线迭代全流程。</li><li>后端：精通 Java（JDK8+），熟练掌握 Spring Boot、Spring Cloud、MyBatis-Plus，理解Spring Cloud微服务架构。</li><li>数据库与中间件：熟练使用 MySQL/Oracle/PostgreSQL，具备数据库设计、SQL / 索引优化、分库分表经验。</li><li>前端：熟练掌握 Vue3、ES6+、Node.js，精通 Element Plus、uni-app，具备响应式开发、移动端适配、前端性能优化能力。</li><li>熟悉亚马逊 / Temu/Shein/ 沃尔玛等 1-2 个跨境电商平台 API 对接流程，理解跨境电商业务。</li><li>具备独立需求分析、方案设计、问题排查能力；熟悉敏捷开发，有良好代码规范、协作、执行与抗压能力，学习与推进能力强。</li></ol><p><strong>薪资福利</strong></p><ol><li>工作时间上午9：00-12：00，下午；13：30--18：15，实行大小周，法定节假日正常休息。</li><li>薪资待遇月薪8K–12K，能力优秀者可面议谈薪。</li><li>员工</li></ol><p><strong>福利</strong></p><p>提供五险一金</p><p><strong>福利</strong></p><p>，基础保障及时到位。依法享有带薪年假，法定节假日正常休息，工作生活平衡。提供年度定期体检，关注员工身体健康与长期发展。配备节日</p><p><strong>福利</strong></p><p>、日常下午茶，定期组织团建活动，氛围轻松。</p>', '1-3年', 'b2827a3fbae893bc0nFy2tq4GVJX', '深圳 · 龙岗区 · 坂田', '10-12K', 'Java, PostgreSQL, SpringCloud, MySQL, Spring, Oracle', '资深java开发工程师（跨境电商-ERP）', 'https://www.zhipin.com/job_detail/b2827a3fbae893bc0nFy2tq4GVJX.html', '节日福利, 带薪年假, 零食下午茶, 五险一金, 团建聚餐, 全勤奖, 定期体检, 底薪加提成');
INSERT INTO `jobs` VALUES (138, '携银信息', '计算机软件', '100-499人', '未融资', '本科', '<ol><li>全日制本科计算机或相关专业学历，2年及以上企业级应用系统开发经验。</li><li>JAVA基础扎实，理解IO、多线程、集合等JavaSE知识，熟悉HTTP基本工作原理。</li><li>具备较丰富的Spring框架开发经验，熟悉Spring Boot等微服务框架。</li><li>熟悉JVM原理，具备一定的性能调优和问题排查能⼒。</li><li>熟悉⾯向对象开发⽅式，对微服务架构理念有一定认识。</li><li>熟练使用MyBatis和Oracle数据库，熟悉Redis、MongoDB等⾮关系型数据库者优先。</li><li>熟悉Linux常用命令，掌握前后端对接及生产问题排查的基本方法。</li><li>掌握Maven、Git等常用开发辅助工具。</li><li>熟悉Tomcat的配置与管理。</li><li>了解高可用架构、分布式部署、多活部署、容灾切换、灰度发布等相关实践者优先。</li><li>有金融行业、TA系统、资金清算、登记过户、基金交易系统开发经验者优先。</li></ol>', '1-3年', '6fd500fb4dc94c2c0nJ43Nu6FFZX', '深圳 · 福田区 · 上步', '10-12K', 'Java, Spring, MyBatis, Tomcat, JVM, Oracle, Redis, MongoDB, 不接受居家办公', '初级java开发工程师', 'https://www.zhipin.com/job_detail/6fd500fb4dc94c2c0nJ43Nu6FFZX.html', '餐补, 绩效奖金, 带薪年假, 五险一金, 加班补助, 生日福利, 补充医疗保险, 零食下午茶, 定期体检, 团建聚餐, 员工旅游, 节日福利, 年终奖');
INSERT INTO `jobs` VALUES (139, '车易新能源', '新能源', '100-499人', '未融资', '本科', '<p><strong>一、岗位职责</strong></p><ol><li>负责公司内部管理系统的整体搭建、开发与功能优化，涵盖财务、人事、行政、售前与售后部门的业务流程、数据统计等内部信息化系统，根据公司业务及管理需求完成系统架构设计与代码开发。</li><li>深度对接公司各部门需求，梳理业务流程，精准拆解开发任务，独立完成系统模块的设计、开发、测试与上线落地⼯作，保障系统稳定⾼效运⾏。</li><li>负责现有内部管理系统的日常运维、bug修复、性能优化，解决系统使用过程中出现的各类技术问题，持续提升系统运⾏效率与使用体验。</li><li>参与数字化管理方案的调研与规划，结合行业主流技术和公司发展需求，优化系统架构，推进内部管理体系数字化升级。</li><li>整理完善系统开发文档、技术手册、使用说明，配合各部门完成系统培训、落地推广及使用指导工作。</li></ol><p><strong>二、任职要求</strong></p><ol><li>学历背景：2025-2026届应届本科及以上学历计算机科学与技术、软件工程、信息技术、人工智能、数据科学与大数据技术等相关专业。</li><li>专业能力：掌握Java、Python、PHP等至少一门主流开发语言，熟悉前后端开发基础框架，了解数据库原理及MySQL、SQL Server等常用数据库的使用与优化。</li><li>技能素养：具备基础的系统架构思维和独立开发能力，能够清晰梳理业务逻辑，高效完成开发任务；熟悉软件开发流程、测试流程，具备良好的代码编写规范。4.</li></ol><p><strong>综合素质</strong></p><p>学习能力强，对企业数字化、内部系统开发有浓厚兴趣，愿意深耕企业信息化建设领域；具备良好的沟通协调能力、团队协作意识和责任心，工作严谨细致，能够抗压落地各项工作。5. 无不良在校记录，品行端正，积极上进，愿意长期稳定发展。</p>', '1-3年', '18a134259a7f6cdd0nF-3t-9E1FS', '深圳 · 南山区 · 科技园', '9-14K', 'Java, Nginx, MySQL, SQL Server, 架构设计经验, Spring, Python', '内部管理系统开发工程师', 'https://www.zhipin.com/job_detail/18a134259a7f6cdd0nF-3t-9E1FS.html', '节日福利, 五险一金, 员工旅游, 带薪年假, 团建聚餐, 意外险');
INSERT INTO `jobs` VALUES (140, '深圳市华馥科技', '光伏', '0-20人', '未融资', '大专', '<p><strong>岗位要求</strong></p><p>1)有HIS数据库相关经验的优先2）有医疗相关（糖尿病，慢性病，高血压等）开发经验优先，Java编程基础。应聘者需要具备扎实的Java编程基础，包括熟悉IO、多线程、分布式、集合等基础API，对JVM原理有一定的了解。框架和技术栈。应熟悉并掌握主流的Java后端开发框架和技术栈，如Spring, Spring Boot, Spring Cloud, MyBatis等，了解并能够根据业务特性进行技术选型。数据库技能。应聘者需要熟练掌握至少一种关系型数据库（如MySQL, Oracle, PostgreSQL等），能够编写高效SQL并具备SQL调优能力，同时了解数据库连接池、事务管理等相关技术。开发工具和环境。熟悉并熟练使用常用的Java开发工具和环境，如Eclipse、IntelliJ IDEA、Maven、Git等，能够进行代码管理、构建和调试。问题解决和逻辑思维能力。具备良好的逻辑思维能力和问题解决能力，能够针对不同的问题进行分析和处理，找到最优解决方案。团队协作能力。具备强烈的责任心和进取心，良好的沟通能力和团队协作能力，能够和其他团队成员合作开发项目，协调各种工作。学习和自我提升能力。具备不断学习和自我提升的能力，对新技术保持好奇心和研究动力。大专及以上学历，学信网可查。1年以上后端开发经验，有新能源平台或者医疗系统开发经验优先。</p>', '1-3年', '0aae7ee57f957f921HF82NW-GVZU', '深圳 · 宝安区 · 西乡', '6-11K', 'Java, 物联网经验, SpringCloud, MySQL, Redis, Spring', 'java后台开发工程师', 'https://www.zhipin.com/job_detail/0aae7ee57f957f921HF82NW-GVZU.html', '员工旅游, 带薪年假, 绩效奖金, 五险一金, 保底工资');
INSERT INTO `jobs` VALUES (141, '深圳市恒星智科技', '智能硬件/消费电子', '20-99人', '未融资', '大专', '<p>【</p><p><strong>职位描述</strong></p><ol><li>参与需求讨论、对技术文档的整理。【技能要求】1、学历专科以上⾄少三年的java开发经验；</li><li>熟悉主流的互联⽹架构框架spring cloud；</li><li>熟悉mysql等关系型数据库，缓存数据库redis、消息中间件rabbittmq、代理服务器Nginx。</li><li>熟悉或使⽤过vue者优先；</li><li>有较强的自学能力和良好的语⾔表达能力，具备良好的团队协作精神；</li><li>热爱技术工作，愿意在技术领域长期发展。</li></ol>', '1-3年', 'f6c610cdc9246dd80ndy0ty-FVZV', '深圳', '13-25K', '', 'java开发工程师', 'https://www.zhipin.com/job_detail/f6c610cdc9246dd80ndy0ty-FVZV.html', '团建聚餐, 法定节假日三薪, 生日福利, 年终奖, 工龄奖, 全勤奖, 员工旅游, 节日福利, 餐补, 五险一金');
INSERT INTO `jobs` VALUES (142, '陕西海饼干科技', '计算机软件', '20-99人', '不需要融资', '本科', '<p><strong>任职要求</strong></p><ol><li>统招本科以上学历，1年以上相关工作经验；</li><li>JAVA基础扎实，充分理解面向对象，熟悉io、nio、多线程、设计模式、通信协议等基础技术；熟悉JVM 工作原理并掌握常见性能调优方法；</li><li>熟悉Spring、Springmvc、Mybatis、Hibernate等常⽤开发框架及特征，熟悉常⽤中间件Tomcat、Mq、Kafka等；</li><li>熟悉单元测试⽤例开发；熟悉软件技术文档的编写；</li><li>具备良好的文档编制习惯和代码书写规范。</li></ol><p><strong>岗位要求</strong></p><ol><li>本科及以上学历，1年以上Java开发相关⼯作经验。</li><li>扎实的Java基础，深入理解面向对象、IO/NIO、多线程、设计模式及通信协议，熟悉JVM原理与性能调优。</li><li>熟练使用Spring系列框架（如Spring MVC）、MyBatis/Hibernate等ORM框架，熟悉Tomcat配置及MQ/Kafka等中间件。</li><li>具备单元测试开发能力，能规范编写技术文档和开发文档。</li><li>代码书写规范严格，遵循主流开发标准，文档编制习惯良好。（工作经验最少1-3年，应届生无工作经验要求硕士）所属行业:企业级软件</li></ol><p><strong>一、岗位职责</strong></p><ol><li>负责SaaS软件等产品特性的系统设计、核心开发与交付及运维，构建软件工程能力。</li><li>主导或参与客户原始需求分析、系统设计等，能够与团队融洽协作，高质量完成核心交付。</li><li>主导或参与系统核心模块的技术竞争力构建，跟踪分析业界发展趋势并完成竞争力分析。</li><li>负责相关子系统及业务流程的优化，研发过程持续改进。</li></ol>', '1-3年', '385a481e82266a260nF_3d66GFNX', '深圳 · 南山区 · 科技园', '17-30K·14薪', 'Java, Spring, SpringCloud, MyBatis, Hibernate, Kafka, MySQL, Redis, Oracle, 架构设计经验, 分布式经验, 微服务经验, 不接受居家办公', 'java开发工程师', 'https://www.zhipin.com/job_detail/385a481e82266a260nF_3d66GFNX.html', '年终奖, 保底工资, 生日福利, 补充医疗保险, 有无线网, 五险一金, 绩效奖金, 高温补贴, 定期体检, 加班补助, 节假日加班费, 法定节假日三薪');
INSERT INTO `jobs` VALUES (143, '冠英股份', '计算机软件', '100-499人', '不需要融资', '本科', '<p><strong>一、岗位职责</strong></p><ol><li>负责把前沿的大模型技术（LLM、Agent、RAG）落地到具体的业务场景中，与前后端工程师、产品经理、设计师等团队成员协作，完成AI Agents产品新功能的开发和上线。</li><li>负责AI Agent整体架构设计与技术选型，用Java+Python搭建企业级AI⼤脑，打通电商平台的全链路数据。</li><li>开发基于LangChain/LlamaIndex的智能体（Agent），结合RAG技术，构建能解决复杂问题的⾏业专家助⼿。</li><li>解决大模型在企业内网的私有化部署、微调及性能优化问题，确保系统在⾼并发下的稳定性。</li><li>开发Agent可调用工具，对接内外部系统，将AI能力无缝嵌入现有的ERP、MES及电商系统；</li><li>设计实现多Agent编排框架；建立Agent行为评估与监控体系；推动Agent系统工程化落地，把控生产环境核心指标。</li></ol><p><strong>二、任职要求</strong></p><ol><li>本科及以上学历，计算机软件/人工智能相关专业；2至3年开发经验。</li><li>精通Java，熟悉Spring Boot/Spring cloud等主流框架，有高并发分布式系统经验。</li><li>具备极强的 AI-Native 编程思维，熟练使用 Cursor、Claude Code、Codex 等 AI 辅助编程工具进行敏捷开发。精通大模型 API 调用及提示词工程4、熟练掌握Python，了解PyTorch/TensorFlow。</li><li>有RAG、向量数据库（Milvus/Weaviate）或Agent项目落地经验。</li><li>熟悉Docker、Linux，有模型服务化部署经验。</li></ol>', '1-3年', 'dfc605232a42683b0nBz2N20FVNZ', '深圳 · 龙华区 · 民治', '9-12K', 'Java, Python, Spring, SpringCloud, Docker', 'AI开发应用工程师', 'https://www.zhipin.com/job_detail/dfc605232a42683b0nBz2N20FVNZ.html', '定期体检, 生日福利, 节日福利, 年终奖, 绩效奖金, 补充医疗保险, 交通补助, 股票期权, 带薪年假, 通讯补贴, 包吃, 五险一金, 餐补, 加班补助, 团建聚餐');
INSERT INTO `jobs` VALUES (144, '深圳市乐邦咨询管...', '咨询', '0-20人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>设计、开发、测试和维护软件应用。</li><li>与团队合作，确保软件项目的顺利进行。</li><li>优化现有软件的性能，提升用户体验。</li><li>解决软件开发过程中的技术问题。</li></ol><p><strong>任职要求</strong></p><ol><li>具备良好的逻辑思维能力和问题解决能力。</li><li>熟悉软件开发生命周期，有相关开发经验者优先。</li><li>能够独立工作同时也能良好地与团队合作。</li><li>对软件开发技术有持续的学习和探索。</li></ol>', '1-3年', 'cbfdf7ed0e1c05be03B83d61F1VU', '深圳 · 福田区 · 车公庙', '15-16K', '不接受居家办公, Java, Spring, MySQL', '软件开发工程师', 'https://www.zhipin.com/job_detail/cbfdf7ed0e1c05be03B83d61F1VU.html', '五险一金');
INSERT INTO `jobs` VALUES (145, '西安英沃诺克信息技术', '计算机软件', '100-499人', '未融资', '本科', '<p>java开发工程师</p><p><strong>岗位职责</strong></p><ol><li>负责SaaS软件等产品特性的系统设计、核心开发与交付及运维，构建软件工程能力。</li><li>主导或参与客户原始需求分析、系统设计等，能够与团队融洽协作，高质量完成核心交付。</li><li>主导或参与系统核心模块的技术竞争力构建，跟踪分析业界发展趋势并完成竞争力分析。</li><li>负责相关子系统及业务流程的优化，研发过程持续改进。</li></ol><p><strong>任职要求</strong></p><ol><li>统招本科以上学历，1年以上相关工作经验；</li><li>JAVA基础扎实，充分理解面向对象，熟悉io、nio、多线程、设计模式、通信协议等基础技术；熟悉JVM 工作原理并掌握常见性能调优方法；</li><li>熟悉Spring、Springmvc、Mybatis、Hibernate等常用开发框架及特征，熟悉常用中间件Tomcat、Mq、Kafka等；</li><li>熟悉单元测试用例开发；熟悉软件技术文档的编写；</li><li>具备良好的文档编制习惯和代码书写规范。</li></ol>', '1-3年', 'f000cfe99fe582bc03N629q_EFNV', '深圳 · 南山区 · 科技园', '13-26K·14薪', 'Java, Python, SpringCloud, Tomcat, MyBatis, Spring, Redis, MySQL, MongoDB, 分布式经验, 架构设计经验, 微服务经验, 不接受居家办公', 'java开发工程师', 'https://www.zhipin.com/job_detail/f000cfe99fe582bc03N629q_EFNV.html', '生日福利, 节日福利, 团建聚餐, 零食下午茶, 全勤奖, 法定节假日三薪, 节假日加班费, 底薪加提成, 五险一金');
INSERT INTO `jobs` VALUES (146, '唛壳', '电子商务', '100-499人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责AI应用相关业务模块的设计、开发与迭代，基于Java技术栈完成核心功能实现；</li><li>参与需求评审和技术方案设计，能够清晰理解业务需求并转化为可落地的技术实现；</li><li>与产品、运营及算法团队紧密协作，保障项目按时⾼质量交付；</li><li>负责系统⽇常维护、性能优化及线上问题排查，确保系统稳定运⾏；</li><li>后续根据公司规划，逐步参与前端（Vue/React）及全栈相关开发工作，公司提供系统性培训支持。</li></ol><p><strong>任职要求</strong></p><ol><li>基本条件·学历：全⽇制本科及以上（一本院校及以上优先）；·经验：1-2年Java开发经验，有亚马逊erp开发经验。</li><li>专业技能·Java基础扎实，熟悉Spring Boot/Spring Cloud框架体系；·了解MySQL、Redis等主流数据库及缓存中间件的使用；·对Linux基本操作有一定了解，能完成日常部署及日志排查；·不强制要求当前具备前端或全栈能力，但需具备学习意愿，公司提供培训，后续向全栈方向培养。3、</li></ol><p><strong>综合素质</strong></p><p>·沟通表达能力良好，能够主动与团队成员进行信息同步和问题澄清；·逻辑思维清晰，具备一定的分析问题和解决问题的能力；·自驱力强，愿意持续学习新技术，能快速适应业务变化。加分项·了解Python，对AI/机器学习领域有浓厚兴趣；·有实际项目交付经验，能独立完成小型模块开发；·对前端技术（Vue/React）有一定了解或实践经历。</p>', '1-3年', '04db91f7a409d4a50nFy0tu0ElJT', '深圳 · 龙华区 · 龙华', '8-13K', 'Java, Spring, SpringCloud, MySQL, Redis, ERP开发经验, 不接受居家办公', 'AI应用开发工程师', 'https://www.zhipin.com/job_detail/04db91f7a409d4a50nFy0tu0ElJT.html', '生日福利, 带薪年假, 节日福利, 年终奖, 零食下午茶, 团建聚餐, 节假日加班费, 夜班补助, 员工旅游, 五险一金, 工作时间学习');
INSERT INTO `jobs` VALUES (147, '上海三高计算机', '计算机软件', '100-499人', '已上市', '本科', '<ol><li>负责部门相关项boss目的JAVA开发工作；</li><li>负责编写核心模块概要设计、详细设计等技术文档；</li><li>参与项⽬中业务功能接口协议和核⼼模块的设计，解决项⽬中的关键问题和技术难题；</li><li>能够与团队进行良好的沟通合作，按时保质保量完成开发任务。</li></ol><p><strong>岗位要求</strong></p><p>1. 熟练掌握Java语言2. 熟悉使⽤MySQL、Oracle、Sqlserver、GaussDB等关系型数据库，熟练使用Redis、MQ、Nacos等中间件3. 熟悉Spring、Spring Boot、Spring Cloud等常用开发框架4. 熟悉Linux平台及基本操作命令5. 良好的沟通能力和团队精神，有出差项目现场能力6. 英语阅读良好7. 会听说粤语加分（需要出差香港）8. 深圳户口或深圳居住证</p>', '1-3年', '9f1b8d67f5697ca80nF439W8F1pU', '深圳 · 罗湖区 · 东门', '6-11K', 'C#, Java, C++, C, SpringCloud, MySQL, SQL Server, Spring, Oracle, Python', 'java开发工程师（深圳）', 'https://www.zhipin.com/job_detail/9f1b8d67f5697ca80nF439W8F1pU.html', '五险一金, 交通补助, 餐补, 有无线网, 节日福利, 带薪年假, 生日福利, 零食下午茶, 员工旅游, 年终奖, 团建聚餐, 定期体检');
INSERT INTO `jobs` VALUES (148, '甄才智能', '人工智能', '0-20人', '', '本科', '<p><strong>岗位职责</strong></p><p>1. 负责Java相关系统的开发与维护 2. 参与项⽬需求分析及技术⽅案设计</p><p><strong>任职要求</strong></p><ol><li>善于沟通、按时完成上级交给的⼯作</li><li>拥有良好的团队合作精神，能迅速融入团队</li><li>具备良好的学习能力，能够不断改进⼯作方法</li></ol>', '1-3年', '20d40cde97dcd0cf0nF70tm4FlZU', '深圳 · 南山区 · 科技园', '15-20K·14薪', '', 'Java', 'https://www.zhipin.com/job_detail/20d40cde97dcd0cf0nF70tm4FlZU.html', '五险一金');
INSERT INTO `jobs` VALUES (149, '加木创新', '通信/网络设备', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责跨境电商中台、高并发交易引擎及供应链系统的架构设计、核心代码编写与系统重构；</li><li>负责多阶段、多模式交易链路下的分布式业务状态机及状态驱动引擎的研发；</li><li>负责核心资源独占锁机制、高并发竞态条件控制流及多渠道库存同步模块的编写；</li><li>负责海外第三⽅聚合⽀付接口、跨境物流 API 以及多国税率计算引擎的通⽤抽象与对接；</li><li>负责全链路性能调优、自动化对账系统、异常熔断降级机制及数据加密合规模块的开发。</li><li>负责 AI 图像识别、计算机视觉（CV）评估模型在工程端的接⼊与调度，主导图片/视频流的异步传输、高吞吐处理及 AI 识别结果的结构化解析。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机相关专业，5 年以上 Java 核心开发经验，有大型电商、供应链或 WMS 仓储系统背景；</li><li>扎实的 Java 基础，精通 Spring Boot、Spring Cloud 分布式架构，深入理解 JVM 内存模型与性能调优；</li><li>精通 Redis 缓存，具备熟练运用 Redis 分布式锁、Lua 脚本进行高并发资源锁定的底层开发能力；</li><li>熟练掌握 MQ（RocketMQ 或 RabbitMQ）消息队列，具备处理异步解耦、分布式事务最终一致性及死信队列的实战经验；</li><li>熟练掌握 MySQL（具备索引调优及分库分表经验），熟悉常见加密算法（AES、RSA），具备接口幂等性设计与数据落盘加密开发能力；</li><li>具备敏锐的异常边界处理能力，有海外三方支付对账、国际化多语言多税率系统开发经验者优先；</li><li>熟悉常用 AI 模型，有使用 Java 对接 OpenCV、TensorFlow Serving、ONNX Runtime 或主流云端 AI 视觉 API 经验者优先。</li><li>具备强烈的技术好奇心与钻研精神，热衷于跟踪与研究前沿技术及 AI 领域；能够主动将结合 AI 工具（如 Cursor、Claude Code 等）深度融入日常研发流。</li></ol>', '1-3年', '0c62d1b29d2469240nB82d28FlNY', '深圳 · 南山区 · 科技园', '15-25K', '', '高级 Java 开发工程师', 'https://www.zhipin.com/job_detail/0c62d1b29d2469240nB82d28FlNY.html', '加班补助, 带薪年假, 五险一金, 保底工资, 员工旅游, 团建聚餐, 零食下午茶, 生日福利, 年终奖, 节日福利');
INSERT INTO `jobs` VALUES (150, '上海华为', '半导体/芯片', '0-20人', '', '本科', '<p>boss基于Spring Boot构建高性能AI推理微服务，封装RESTful/gRPC API供业务调用。使用Java实现Prompt模板引擎、多轮对话管理及RAG流程编排（基于LangChain4j或Spring AI）。集成向量数据库（Milvus/Pinecone）Java SDK，实现向量检索；对接Qwen、GLM等大模型API。负责AI服务的⾼并发限流、熔断降级及异步任务处理，保障系统稳定性。进⾏JVM调优，优化模型推理延迟与内存占⽤；维护模型版本管理与A/B测试。</p><p><strong>任职要求</strong></p><p>Java功底扎实：2年以上Java开发经验，精通多线程、IO、JVM内存模型，熟悉Spring Cloud微服务生态。AI技术栈：熟悉LangChain4j或Spring AI框架，有Prompt工程及RAG实际项⽬经验。算法基础：了解Transformer架构及Embedding原理，能看懂论文并做工程转化。工具链：熟练使用Redis、Kafka、Docker/K8s，至少熟悉一种向量数据库。加分项：有Python算法调研能力、大模型微调经验或AIGC应用落地案例。</p>', '1-3年', 'beb7aff77fb006420nF52dS1GVpX', '深圳 · 龙岗区 · 平湖', '15-20K·13薪', '', 'Java', 'https://www.zhipin.com/job_detail/beb7aff77fb006420nF52dS1GVpX.html', '');
INSERT INTO `jobs` VALUES (151, '兆日科技', '计算机服务', '100-499人', '已上市', '本科', '<p>学历要求：本科及以上；专业范围：计算机科学与技术、软件工程、网络工程、人⼯智能等计算机相关专业；⼯作地点：福建厦门银⾏专业</p><p><strong>技术要求</strong></p><p>【</p><p><strong>岗位职责</strong></p><p>】负责银行供应链金融系统开发，参与反向保理、授信优化、供应链系统改造，承接信贷业务需求，完成功能开发与迭代交付，配合⾏方推进项目落地。【</p><p><strong>任职要求</strong></p><ol><li>SpringBoot、MyBatis、Dubbo、Zookeeper、MySQL、Redis、Shiro、XXL-Job 等技术栈；</li><li>有供应链金融、保理、信贷系统开发经验，熟悉反向保理业务优先；</li><li>有金融 / 银行项目经验优先，能够独立开发模块，沟通协作良好。招聘聘背景：入职深圳兆日科技，五险一金足额缴纳在深圳，外派厦门银行，视工作情况后续有机会转为银行员工。面试流程：候选人在深圳可现场面试，如在外地，可安排视频面试。</li></ol>', '1-3年', '10b950fa9ceb3f650nJ739S-GFBS', '深圳 · 福田区 · 车公庙', '12-24K', 'Java, Spring, SpringCloud, MySQL, Oracle, 分布式经验, 微服务经验, 不接受居家办公', 'Java开发工程师（供应链方向）', 'https://www.zhipin.com/job_detail/10b950fa9ceb3f650nJ739S-GFBS.html', '人才住房, 节日福利, 年终奖, 员工旅游, 五险一金, 零食下午茶, 深户调入, 带薪年假, 补充医疗保险, 定期体检');
INSERT INTO `jobs` VALUES (152, '鹰才信息', '互联网', '0-20人', '未融资', '大专', '<p><strong>岗位职责</strong></p><ol><li>负责公司后端系统的设计、开发和维护工作；</li><li>参与需求分析、技术方案设计及接口文档编写；</li><li>完成核心代码编写，解决开发过程中的技术难题；</li><li>配合前端开发⼈员完成系统集成与联调；</li><li>保障系统的⾼性能、⾼可用性及安全性。</li></ol><p><strong>任职要求</strong></p><ol><li>熟悉主流后端开发语言（如Java、Python等）；</li><li>熟悉常⽤数据库（如MySQL、Redis、postgresql、rag）及SQL优化；</li><li>了解微服务架构及相关技术组件（如Spring boot等）；</li><li>具备良好的沟通能力和团队协作意识；</li><li>有后端开发项目经验者优先。</li></ol>', '1-3年', '7585f1d2c5cebfde0nZ53tq0F1VW', '深圳 · 龙华区 · 观澜', '11-17K', 'Java, Nginx, 分布式经验, spring cloud Alibaba, PostgreSQL, SpringCloud, K8S, Redis, spring AI, Spring, 微服务经验, Netty, Python', '后端开发工程师', 'https://www.zhipin.com/job_detail/7585f1d2c5cebfde0nZ53tq0F1VW.html', '加班补助, 节日福利, 五险一金, 绩效奖金');
INSERT INTO `jobs` VALUES (153, '正大康地', '农/林/牧/渔', '100-499人', '', '本科', '<ol><li>计算机/数学相关专业本科及以上学历，3年以上数据仓库项目经验;</li><li>从事数据仓库领域工作至少2年以上，熟悉数据仓库模型设计方法论，并有实际模型设计及ETL开发经验;</li><li>熟悉数据治理相关流程，包括数据接入、数据处理数据治理、数据组织、数据服务等;</li><li>具备用户问题的定位及解决能力，善于归纳总结对数据敏感;</li><li>至少掌握 Java、Python、C# 编程语言其中一种；</li><li>熟悉FineReport报表开发及运维，负责过销售、财务等部门报表需求落地6、熟悉SAP SD\\PP相关模块业务，具备SAP Business One开发能力8、优秀的数据分析能力、需求理解能力，能较好的理清业务流程;</li><li>精通或熟悉常见RDBMS(Oracle/SQL Server/MySql)的使用及开发，熟练使用SQL语句，了解各数据库优缺点，熟悉与架构设计相关的数据存储、性能调优等相关领域知识，有相关项目经验尤佳。</li><li>熟悉饲料行业销售、采购、生产、财务业务流程，熟悉财务及财务合并基础知识，具有数字化管理业务项目背景，能独立管理项目，能针对业务部门用户给予指导和培训，有独立完成饲料行业信息化运维方面的工作经验。</li></ol>', '1-3年', 'c50a9a3e8dd189bb1H1z2di0GFBZ', '深圳 · 南山区 · 科技园', '12-24K·13薪', 'Java, MySQL, ERP开发经验', '软件工程师', 'https://www.zhipin.com/job_detail/c50a9a3e8dd189bb1H1z2di0GFBZ.html', '');
INSERT INTO `jobs` VALUES (154, '深圳市上为信息技术', '互联网', '100-499人', '未融资', '本科', '<p>岗位boss</p><p><strong>职责</strong></p><ul><li>参与公司软件产品的需求分析、技术方案讨论，协助完成模块开发、调试与测试，支撑软件产品迭代升级。</li><li>按照开发规范编写高质量代码，修复软件bug，优化代码性能，提升软件产品的稳定性和用户体验。</li><li>负责软件开发相关⽂档的编写、整理与归档，配合测试团队完成集成测试，保障产品质量。</li><li>配合团队完成软件产品的迭代升级，跟进⾏业软件开发技术动态，助⼒团队技术提升。</li></ul><p><strong>岗位要求</strong></p><ul><li>本科及以上学历，计算机科学与技术、软件工程等相关专业，应届生可投，接受⽆相关工作经验者。</li><li>掌握Java、Python、JavaScript等至少一种编程语言，熟悉常用开发框架，能独立完成基础模块开发。</li><li>了解MySQL等数据库基本操作，具备基础的代码编写和调试能力，能排查简单的代码bug。</li><li>工作认真负责，具备良好的学习能力和团队协作精神，能快速适应开发节奏，主动学习新技术。</li></ul><p><strong>福利待遇</strong></p><p>- 薪资：8300-11700元/月- 基础</p><p><strong>福利</strong></p><p>五险一金、法定节假日全休、节日</p><p><strong>福利</strong></p><p>（春节、端午、中秋等），全面保障员工权益。- 日常</p><p><strong>福利</strong></p><p>月度下午茶、每月1次部门团建，弹性工作时间（9:00~9:30--18:00~18:30），营造高效的工作氛围。</p>', '1-3年', '5f4cae5da2f9c99d0nFz2ti-EVJU', '深圳', '8-11K', 'Java, Spring, MySQL, 云计算经验, 不接受居家办公', '软件开发工程师（初级）', 'https://www.zhipin.com/job_detail/5f4cae5da2f9c99d0nFz2ti-EVJU.html', '零食下午茶, 意外险, 生日福利, 定期体检, 补充医疗保险, 五险一金, 节假日加班费, 保底工资, 绩效奖金, 加班补助, 节日福利');
INSERT INTO `jobs` VALUES (155, '深圳天财税务咨询', '财务/审计/税务', '0-20人', '未融资', '大专', '<p><strong>岗位职责</strong></p><ol><li>负责公司内部私有CRM系统从零自研、迭代与整体落地，搭建适配公司业务的客户线索、商机跟进、订单合同、工单流程、业绩统计、客户回访、续费预警等全套业务模块，不依赖开源模板套改。</li><li>负责公司全业务数据整合与数据中台搭建，打通广告投放线索、企业微信、业务订单、财务收款、员工绩效、历史客户台账等多渠道数据，解决数据孤岛问题，实现数据统⼀归集、⾃动同步、去重清洗、异常修正。</li><li>独⽴完成前后端开发、数据库设计、接口开发、第三方系统对接，搭建可视化数据看板，包含获客数据、转化数据、成交数据、成本利润、团队业绩、客户流失分析等核心业务报表。</li><li>负责系统权限体系搭建与数据安全管理，实现⽼板、主管、销售、财务分级权限、数据隔离、客户敏感信息脱敏，管控数据导出与查询权限，保障客户隐私数据安全。</li><li>负责服务器部署、系统运维、日常巡检、数据库备份、故障排查、性能优化，保障系统长期稳定运行。</li><li>对接各部门业务需求，主动梳理业务流程，将口头需求转化为标准化开发功能，负责员工系统使用培训、问题答疑、功能迭代优化。</li><li>负责存量历史数据迁移、整理、入库，持续优化业务流程与数据逻辑，后期支撑系统向SaaS多租户模式迭代升级。</li></ol><p><strong>任职要求</strong></p><ol><li>大专及以上计算机、软件工程、大数据、信息管理等相关专业，2年及以上企业后台系统独立开发经验，必须有自主开发CRM/业务管理系统落地案例。</li><li>技术栈扎实：熟练Vue3/ElementUI前端开发；熟练PHP/Java/Python任一后端框架；精通MySQL数据库设计、复杂查询、索引优化、批量数据处理。</li><li>具备成熟的接口开发与第三方对接能力，能独立完成企微、表单、投放、财务等系统的数据同步、定时任务、数据校验，可独立处理数据错乱、重复、缺失等问题。</li><li>具备业务数据化能力，懂销售业务、订单、业绩、成本统计逻辑，能自主设计业务报表、数据大屏，不需要业务方提供详细需求文档。</li><li>熟悉Linux基础操作、项目部署、日志排查、数据备份，可独立完成系统上线、运维、故障修复。</li><li>具备极强的独立工作能力，可单人完成需求梳理—开发—测试—上线—运维—培训全流程，不依赖团队协作。</li><li>做事严谨、责任心强、数据敏感度高，具备极强的客户隐私保密意识，能严格管控公司核心客户数据。优先录用条件1、有咨询行业、企业服务、财税、商务中介行业CRM开发经验者优先；</li><li>有数据中台、多系统数据整合、数据看板开发经验者优先；</li><li>有SaaS系统、多租户权限体系搭建经验者优先；</li><li>可独立从零搭建整套后台系统，而非只会修改开源源码者优先。</li></ol>', '1-3年', '07f44c57f64748640nFz29m5E1JU', '深圳 · 福田区 · 车公庙', '14-20K', 'Java, C, MyBatis, JVM, MySQL, SQL Server, 架构设计经验, 不接受居家办公', '企业数字化系统开发（香港秘书CRM系统）', 'https://www.zhipin.com/job_detail/07f44c57f64748640nFz29m5E1JU.html', '全勤奖, 五险, 员工旅游, 零食下午茶, 节日福利, 年终奖, 工龄奖, 补充医疗保险, 生日福利, 餐补, 底薪加提成, 绩效奖金, 保底工资, 团建聚餐, 带薪年假, 五险一金');
INSERT INTO `jobs` VALUES (156, '开普莱科技有限公司', '计算机软件', '0-20人', '', '本科', '<ol><li>参与业务需求分析，进行系统架构设计、模块划分和数据库设计。</li><li>负责核心业务功能的后端代码开发、单元测试和代码重构，确保代码质量和系统稳定性。</li><li>负责系统性能优化，解决高并发、数据一致性等核⼼技术挑战。</li><li>编写清晰的技术⽂档，包括设计⽂档、接口文档等。</li><li>参与线上系统部署、监控和维护，快速定位并解决线上故障。</li><li>跟踪和学习业界最新的技术，并将其应用于实际⼯作中以提升产品竞争力。必备要求**1. **学历与经验：** * 计算机科学或相关专业，本科及以上学历。 * **2年及以上** Java后端开发经验。</li><li>**技术基础：** * **Java基础扎实：** 深刻理解面向对象编程、集合、流Stream、多线程并发、JVM内存模型、垃圾回收机制等。* **主流框架精通：** 熟练掌握 Spring、Spring MVC、**Spring Boot**、‌Spring WebFlux‌、MyBatis/Hibernate 等主流开发框架。 * **数据库知识：** * 熟练掌握 MySQL 或 PostgreSQL 等关系型数据库，MongoDB 非关系型数据库，具备优秀的SQL编写和优化能力。 * 了解 Redis、Memcached 等至少一种NoSQL数据库及其应用场景。 * **中间件与微服务：** * 熟悉消息中间件，如 RabbitMQ、Kafka、RocketMQ 中的至少一种。 * 具备微服务架构实战经验，熟悉 **Spring Cloud (Eureka/Nacos, Feign, Hystrix, Gateway)** 或 Dubbo 等微服务框架。 * **工具与平台：** * 熟练使用 Git、Maven/Gradle 等版本控制和构建工具。 * 熟悉 Linux 操作系统常用命令，具备基本的运维能力。</li><li>**综合能力：** * 具备良好的系统设计能力，理解常用设计模式和软件设计原则。 * 具备较强的逻辑思维能力、分析问题和解决问题的能力。 * 具有良好的团队合作精神和沟通能力，工作积极主动，责任心强。优先考虑条件**1. 有分布式、高并发、高可用系统设计和开发经验者优先。</li><li>熟悉 Docker、Kubernetes 等容器化技术，有云平台（AWS, Azure, 阿里云，腾讯云）使用经验者优先。</li><li>熟悉 Elasticsearch、MongoDB 等非关系型数据库，并有实际项目经验者优先。</li><li>了解 DevOps 流程，有 CI/CD（如 Jenkins, GitLab CI）实践经验者优先。</li><li>有性能调优、全链路压测经验者优先。</li><li>在开源社区有贡献或有技术博客/GitHub项目者优先。</li></ol>', '1-3年', 'de780969caa81bdd031-3dm6GVdS', '深圳 · 南山区 · 蛇口', '8-12K', 'Java, Hibernate, 团队管理经验, 分布式经验, SpringCloud, Redis, SQL Server, Spring, 大数据经验, Docker, 微服务经验, MySQL, MyBatis, MongoDB, 架构设计经验, Oracle', 'java软件工程师 （后端）', 'https://www.zhipin.com/job_detail/de780969caa81bdd031-3dm6GVdS.html', '');
INSERT INTO `jobs` VALUES (157, '深圳市在川智能信...', '大数据', '20-99人', '', '大专', '<ol><li>产品研发总负责 主导聚合平台的整体技术架构和产品设计，包括统一API接入、多模型路由、Token计费引擎、开发者门户等模块，确保架构能扛住商业量级的调用。 （核心要求：能画架构图、能写核心代码、能定迭代节奏）2. 平台运维兜底人 负责平台上线后的稳定性、性能优化、故障响应。你需要建立监控告警体系，制定应急预案，保证SLA达到商业可用标准。 （核心要求：线上问题能顶上，不甩锅、不拖延）3. 模型接入与选型 对接模型厂商技术接口，制定标准接入流程，评估模型效果和成本，给出接入优先级建议。</li><li>支持销售与客户 为前端销售和客户提供技术答疑、Demo环境、POC测试支持，把一线反馈转化成产品需求。 我们希望你有这些底色：能写代码、能搭系统：熟悉至少一门后端语言（Go/Java/Python），有过高并发服务或API平台开发经验，能独立设计中等复杂度的后端架构。能搞定线上问题：熟悉Linux、容器化部署、监控日志那一套，出过生产事故不慌，能快速定位和恢复。深度AI辅助编程习惯：日常使用Cursor、Copilot、Windsurf等工具进行vibe coding，相信“AI是第一生产力”，能用AI大幅压缩重复劳动，把时间花在架构思考和难点攻关上。我们不太看重，但会加分的东西学历不限，统招本科加分，优秀大专也欢迎。工作年限不卡死，2年以上后端开发经验，有独立负责过模块或小项目的就行。有云服务、API网关、计费系统相关经验更好，没有的话，愿意快速学习也行。我们特别欣赏的特质自驱闭环：交代一件事，你不仅做完，还能多想一步，主动同步进度。务实坦诚：知道早期资源有限，能接受“先跑通再优化”，不追求过度设计。沟通舒服：能和销售、客户用白话讲技术，也能和技术伙伴深入抠细节。AI原生思维：遇到问题先想“能不能用AI解决”，善于用Prompt和工具链提升个人与团队能效。 为什么考虑加入我们？真·从0到1的操盘机会：聚合平台是公司战略重心，希望将来它也就是你的名片。商业化闭环已打通：我们有现成的云代理客户和行业解决方案，平台上线就有付费流量，不是做内部玩具。成长无上限：平台一旦验证，你就是这条产品线的负责人，短期和长期回报同步升级。</li></ol>', '1-3年', '2e5c9540b6439aaf0nF90tq7GVJX', '深圳 · 南山区 · 前海', '15-20K', 'Golang, MES开发经验, Java, 团队管理经验, 不接受居家办公, SpringCloud, Redis, ERP开发经验, Elasticsearch, MySQL, MongoDB, Oracle, 游戏后端经验, Python', '大模型聚合平台·产品技术负责人', 'https://www.zhipin.com/job_detail/2e5c9540b6439aaf0nF90tq7GVJX.html', '');
INSERT INTO `jobs` VALUES (158, '悦跃科技', '计算机软件', '20-99人', '', '本科', '<p>boss负责服务开发、部署、上线、API输出、产品上架，是知识课堂产品的技术中枢，保障APP各项功能的稳定运⾏。设计与实现 ⽤户体系、学习记录、课程内容管理、测评系统、错题本、跟读评分 等核⼼业务API，支撑前端的动态交互。对接第三方服务，丰富产品功能。负责产品上架流程，确保知识课堂能顺利发布并持续更新。通过后端架构优化，保证⾼并发场景下的回应速度与系统稳定性。</p>', '1-3年', '48f52a3bfa0096b20nF_0t69GFJR', '深圳 · 宝安区 · 西乡', '12-20K', '不接受居家办公, 架构设计经验', '业务后端开发工程师', 'https://www.zhipin.com/job_detail/48f52a3bfa0096b20nF_0t69GFJR.html', '');
INSERT INTO `jobs` VALUES (159, '武汉达明乐科技', '互联网', '0-20人', '', '本科', '<p><strong>岗位职责</strong></p><ol><li>参与系统架构boss设计及核心模块开发，确保项目高质量交付</li><li>编写可维护、高性能的Java代码，持续优化系统性能</li><li>配合产品和测试团队，完成需求分析与功能实现</li></ol><p><strong>任职要求</strong></p><ol><li>熟练掌握Java语⾔及主流开发框架，具备扎实的编程能⼒</li><li>熟悉数据库设计与优化，有MySQL等关系型数据库使⽤经验</li><li>具备良好的逻辑思维能力与问题解决能力，责任⼼强</li></ol>', '1-3年', '1cfbf4ad66200d570nZ83NW4EFFZ', '深圳 · 龙岗区 · 坂田', '12-20K·15薪', '', 'java 开发工程师', 'https://www.zhipin.com/job_detail/1cfbf4ad66200d570nZ83NW4EFFZ.html', '');
INSERT INTO `jobs` VALUES (160, '观麦', '互联网', '100-499人', 'C轮', '本科', '<p>boss</p><p><strong>岗位职责</strong></p><ol><li>负责系统的技术方案设计、开发和维护工作等；</li><li>深入思考研发过程中的各项问题，共同促进团队工作效率和研发质量的提升；</li><li>充分理解业务诉求，通过技术手段助力增长业务实现高速增长。</li></ol><p><strong>任职要求</strong></p><ol><li>本科以上学历计算机相关专业、3年及以上 Java 开发经验；</li><li>Java 基础扎实，熟练掌握数据结构、多线程编程、JVM 优化并能在业务中灵活应用；</li><li>熟练掌握 SpringBoot、ORM 等主流开源框架及原理；</li><li>熟悉分布式、缓存、消息、搜索等机制，能对分布式常用技术进行合理应用，解决各种疑难问题；</li><li>熟悉 Linux 操作系统，常用命令和shell脚本；</li><li>熟悉 MySQL、MongoDB 等大型数据库，并对数据库查询优化有丰富经验；</li><li>有 ERP/SCM 系统开发经验者优先；</li></ol>', '1-3年', '03c6c8e9161d1cc403Bz2tq_FFZZ', '深圳 · 南山区 · 科技园', '10-15K', 'JVM, Java, 不接受居家办公, MySQL, MongoDB, ERP开发经验', 'java初级开发工程师', 'https://www.zhipin.com/job_detail/03c6c8e9161d1cc403Bz2tq_FFZZ.html', '弹性工作, 年终奖, 通讯补贴, 定期体检, 股票期权, 带薪年假, 餐补, 五险一金, 加班补助, 交通补助, 员工旅游, 零食下午茶, 节日福利, 社团活动');
INSERT INTO `jobs` VALUES (161, '西点信息', '计算机软件', '100-499人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责基于公司产品二开项目的开发及交付工作；</li><li>严格执行软件项目开发规范，各阶段按规定输出对应的文档及代码；</li><li>严格执行公司质量管理方针；</li><li>在项目的调研、开发及验收过程中，及时与用户及其他相关部门沟通工作；</li><li>为业务部及相关项目提供技术支持；</li><li>为公司业务部门的项目开发工程师进行技术培训，包括系统功能逻辑、数据结构等。</li></ol><p><strong>任职资格</strong></p><ol><li>统招本科及以上学历，计算机相关专业；</li><li>1-3年以上java开发经验，扎实的JAVA基础，掌握JVM、多线程、并发编程；</li><li>熟悉Spring, SpringMVC, SpringBoot, SpringCloud, Mybatis框架，对框架原理有深入的理解；</li><li>熟练MySQL, Oracle数据库，且对SQL优化及数据库性能优化有一定经验；</li><li>熟悉Redis、Mongodb等NoSQL数据库；</li><li>熟悉中间件kafka、zookeeper、Elasticsearch；</li><li>有扎实的javascript编程功底，熟悉Vue、React中一种框架；</li><li>熟悉linux系统部署基本（基于docker、k8s）操作，有集群、高可用、容灾思想;</li><li>有OA、CRM、工作流开发经验者优先。</li></ol>', '1-3年', '3937e80b013b50d71HJz3N69GFJY', '深圳 · 南山区 · 科技园', '9-13K', 'Java, 团队管理经验, 微服务经验, SpringCloud, MySQL, Spring', 'java开发工程师', 'https://www.zhipin.com/job_detail/3937e80b013b50d71HJz3N69GFJY.html', '加班补助, 零食下午茶, 通讯补贴, 有无线网, 交通补助, 宿舍有空调, 住房补贴, 定期体检, 带薪年假, 包住, 团建聚餐, 五险一金, 员工旅游, 底薪加提成, 节日福利, 补充医疗保险, 年终奖, 股票期权, 保底工资, 绩效奖金');
INSERT INTO `jobs` VALUES (162, '科成智造', '计算机软件', '0-20人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>有独立完成项目所有模块的开发的能力；</li><li>负责公司工业软件系统的开发、测试、上线；</li><li>参与系统的需求调研和需求分析、系统解决⽅案设计等⼯作，满⾜业务部门对系统的合理需求；</li><li>根据项目经理调研需求文档进⾏系统软件的开发、测试、并辅助上线等工作。</li><li>其他相关系统的接口和数据异常处理，结合实际业务需要，提出改善方案；</li><li>负责系统的测试、操作手册的编写和客户端上线培训，以及在上线后的优化迭代；</li></ol><p><strong>任职条件</strong></p><ol><li>本科以上学历，计算机相关专业。3年以上工作经验，条件优秀者可放宽学历和工作年限;</li><li>具有良好的编程习惯和优秀的编程实现能力；</li><li>二次开发过若依、JeecgBoot优先考虑；</li><li>熟练使用Spring、SpringMVC、SpringBoot等主流框架;</li><li>熟练使用Mybatis、Mybatis-plus和hibernate；</li><li>掌握至少一种(Mysql、PostgreSQL 等）主流关系型数据库开发，熟练掌握SQL语句的编写;</li><li>熟悉vue3、TypeScript、Es6、Ant-Design-Vue或element-plus、vben-admin优先考虑；</li><li>掌握Linux操作系统及常用命令,以及使用Tomcat应用服务器的配置、部署；</li><li>适应外地出差；</li><li>有MES、WMS、ERP系统开发经验者优先考虑；</li><li>有1年以上电子SMT组装行业MES开发经验者优先考虑；备注：有项目奖金、有出差补贴、差旅费报销。</li></ol>', '1-3年', '8608043329911b6f0nFz0t65ElJZ', '深圳 · 光明区 · 光明', '8-13K', 'MES开发经验, Java, 物联网经验, PostgreSQL, MySQL, SQL Server, Spring, ERP开发经验', 'mes高级开发工程师', 'https://www.zhipin.com/job_detail/8608043329911b6f0nFz0t65ElJZ.html', '');
INSERT INTO `jobs` VALUES (163, '研科', '计算机软件', '20-99人', '不需要融资', '本科', '<p><strong>工作职责</strong></p><ol><li>boss参与软件开发项目的具体实施。</li><li>负责项目的需求分析、设计工作，按要求编写详细设计说明书等。</li><li>负责核⼼模块程序编码开发⼯作。</li><li>负责系统上线后升级维护需求的实施。招聘条件：</li><li>具有国家教育部认可的⼀本或以上学历（计算机科学/软件工程/信息技术/信息管理等相关专业）2、熟练掌握Java语言、熟悉LINUX操作系统，掌握MySQL、 Oracle或其他数据库；掌握Redis、Kafka等常⽤组件。</li><li>JAVA技术：需熟练掌握Java语言及Spring boot等开源框架，熟悉http、socket等通讯协议，了解 Restful，在底层技术平台、中间件等领域具有开发经验者优先。</li><li>前端技术：熟练Vue.js 框架，具备基于 Vue.js 框架开发大型项目的经验和精通 HTML5 和 CSS3,熟练 W3C 标准与 ES 规范、MVC、MVVM、Web语义化。</li><li>有银行项目实施经验者优先，懂VUE优先。</li><li>具备较强的工作责任心和团队合作意识，抗压能力强，具有较强分析问题和解决问题的能力，具备良好的协调沟通能力。</li><li>会 说/听 粤语者优先。</li></ol>', '1-3年', '2658659692d75aaa0nF-2NW1EVBV', '深圳 · 罗湖区 · 笋岗', '7-12K', 'Java, MySQL, Spring', 'Java', 'https://www.zhipin.com/job_detail/2658659692d75aaa0nF-2NW1EVBV.html', '节假日加班费, 定期体检, 员工旅游, 带薪年假, 法定节假日三薪, 团建聚餐, 年终奖, 保底工资, 节日福利, 餐补, 生日福利, 五险一金, 绩效奖金');
INSERT INTO `jobs` VALUES (164, '鼎森电子科技', '半导体/芯片', '100-499人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责公司业务系统后端功能模块的开发、维护与优化；</li><li>配合产品、前端、测试完成需求分析、接口设计和功能交付；</li><li>负责数据库表结构设计、SQL 编写及基础性能优化；</li><li>协助排查并解决线上常见问题，保障系统稳定运行；</li><li>参与项目规范建设，持续提升代码质量和开发效率。</li></ol><p><strong>岗位要求</strong></p><ol><li>本科学历，计算机相关专业优先，1 年及以上后端开发经验，优秀应届生也可考虑；</li><li>熟悉 Java 或 Go 中至少一种开发语言，有对应框架使用经验；</li><li>熟悉 MySQL，了解 Redis 的基本使用场景；</li><li>了解 HTTP、TCP/IP 等基础网络知识，能进行基本问题排查；</li><li>熟悉 Git 等版本管理工具；</li><li>了解 Linux 常用命令，具备基础的服务部署和日志排查能力；</li><li>有良好的沟通能力、责任心和团队协作意识；</li><li>本岗位主要用到技术有Nodejs、Nest、Mysql、Redis；</li><li>优先“nodejs ”，目前后端主要是Node.js / NestJS技术栈。待遇</li></ol><p><strong>福利</strong></p><ol><li>法定节假日、工作一年以上不低于五天的带薪年假等；</li><li>根据规定购买五险一金【一档社保】;</li><li>节假日红包、生日会、丰盛的下午茶、每年为员工购买商业保险。</li><li>公司每年不定期组织旅游，各部门根据情况组织团队建设活动；</li><li>公司为员工提供升职调薪的机会。工作时间：【大小周】9：00-12：00，13：30-18：00</li></ol>', '1-3年', 'e5e392397ed399dc03J72tq1EVtQ', '深圳 · 福田区 · 华强南', '10-13K', 'Java, 分布式经验, MySQL, Redis, 架构设计经验, nodejs, ERP开发经验, NestJS', '后端开发工程师', 'https://www.zhipin.com/job_detail/e5e392397ed399dc03J72tq1EVtQ.html', '节日福利, 交通补助, 团建聚餐, 五险一金, CBD办公, 年终奖, 绩效奖金, 零食下午茶, 带薪年假');
INSERT INTO `jobs` VALUES (165, '深圳右脑人工智能', '人工智能', '20-99人', '天使轮', '本科', '<p>熟悉至少一种主流前端框架，例如 React、Vue、Next.js 等。熟悉至少一种后端开发语⾔或框架，例如 Python/FastAPI、Node.js、Go、Java/Spring Boot 等。熟悉数据库设计与使⽤，例如 MySQL、PostgreSQL、MongoDB、Redis、Elasticsearch 等。能够独⽴完成从前端页面、后端接口、数据库到部署上线的完整开发流程。熟悉 Linux、Git、Docker、Nginx、基本 CI/CD 或服务器部署流程。有较好的工程习惯，能够写出结构清晰、可维护、可扩展的代码。能理解复杂业务逻辑，并将算法、数据和⽤户操作流程转化为产品功能。对 AI 应用、大模型、Agent、网络安全产品或企业级 SaaS 有兴趣。加分项有 B 端系统、SaaS 平台、数据平台、运维平台、安全产品或中后台系统开发经验。了解 SOC、SIEM、日志分析、告警平台、工单系统、资产管理、安全运营等业务。有大模型应用开发经验，例如 RAG、Agent、工具调用、提示词工程、模型接口封装等。熟悉可视化组件和图谱展示，例如 ECharts、AntV、D3.js、关系图、攻击链展示等。有云服务器部署、Kubernetes、微服务、消息队列、异步任务、权限系统设计经验。有从 0 到 1 搭建产品原型或创业团队工程经验。</p>', '1-3年', '3d4cfdd380b29d3d0nF82dS8FlpW', '深圳', '9-11K', 'Java, Python, MySQL, MongoDB, PostgreSQL, 团队管理经验, 架构设计经验', '智能体开发工程师', 'https://www.zhipin.com/job_detail/3d4cfdd380b29d3d0nF82dS8FlpW.html', '五险一金');
INSERT INTO `jobs` VALUES (166, '深圳市小荔枝科技', '互联网', '0-20人', '', '大专', '<p><strong>职位描述</strong></p><p>PHP\nRedis\nMongoDB\nSpring\n1-3年经验，有成熟项目开发经验\n江先生\n3日内活跃\n深圳市小荔枝科技\n·\n技术总监\n竞争力分析\n查看完整个人竞争力\n个人综合排名：在人中排名第\n你在？位置\n一般 良好 优秀 极好\nBOSS 安全提示\n严禁用人单位和招聘者用户做出任何损害求职者合法权益的违法违规行为，包括但不限于扣押求职者证件、收取求职者财物、向求职者集资、让求职者入股、诱导求职者异地入职、异地参加培训、违法违规使用求职者简历等，您一旦发现此类行为， 请立即举报\n工商信息\n公司名称\n深圳市小荔枝科技有限公司\n法定代表人\n江建涛\n成立日期\n2021-06-21\n企业类型\n有限责任公司\n经营状态\n存续\n注册资金\n10万人民币\n查看全部\n工作地址\n深圳龙岗区创信时代大厦1单元808\n点击查看地图\n更多职位\n看过该职位的人还看了\nJava开发工程师\n9-13K\n天阳科技\n深圳\n高级Java全栈开发工程师\n9-11K\n芯科华高\n深圳\njava开发工程师\n7-10K\n阳光云救\n深圳\njava全栈开发工程师\n9-14K\n深圳市大强未来科技\n深圳\nJava开发初级工程师\n8-12K·13薪\n可为信息\n深圳\nJava开发工程师-银行\n9-14K\n中电金信\n深圳\n精选职位\nJava\n10-14K\n致远创想\n深圳\njava开发\n10-15K\n美琦国际货运代理\n深圳\n初级开发工程师（双休不加班）\n7-9K·13薪\n雪雀科技\n深圳\nJava 开发工程师(初中级 · 3-5 年)\n7-9K\nmongoso\n深圳\n后端开发工程师JAVA\n8-13K\n鸢飞科技\n深圳\n后端开发工程师\n9-11K\n深圳来造科技有限公司\n深圳\n深圳\n搜索\n城市招聘 热门职位 推荐公司 热门企业\n临夏回族自治州招聘\n阳泉招聘\n呼伦贝尔招聘\n镇江招聘\n宝鸡招聘\n景德镇招聘\n鄂州招聘\n甘孜藏族自治州招聘\n武汉招聘\n株洲招聘\n首页深圳招聘·Java招聘深圳Java招聘深圳市小荔枝科技Java招聘\n页面更新时间：2026-08-03\n企业服务热线和算法/未成年人等举报渠道 400 065 5799\n老年人直连热线400 661 6030\n工作日 8:00 - 22:00\n休息日 8:00 - 22:00\n企业服务\n职位搜索\nAPP\n投资者关系 Investor Relations\n直品公益基金会\n求职技巧\n使用与帮助\n协议与规则\n隐私政策\n防骗指南\n使用帮助\n联系\n北京华品博睿网络技术有限公司\n公司地址 北京市朝阳区太阳宫中路16号院1号楼18层1801内09\n违法和不良信息举报邮箱/未成年人举报渠道 jubao@.com\nCopyright © 2026 京ICP备14013441号-5京ICP证150923号 电子营业执照 京公网安备11010502032801 朝阳网警 人力资源服务许可证 网上有害信息举报专区 朝阳区人社局监督电话 算法备案信息</p>', '1-3年', '42653cf4ad6fae881HB62N69EFVS', '深圳 · 龙岗区 · 坂田', '8-12K', 'PHP, Spring, Redis, MongoDB', 'JavaScript', 'https://www.zhipin.com/job_detail/42653cf4ad6fae881HB62N69EFVS.html', '');
INSERT INTO `jobs` VALUES (167, '新源润', '互联网', '20-99人', '未融资', '本科', '<ol><li>本科及以上学历，boss计算机科学与技术、软件工程、电子信息工程等相关专业，优秀专科毕业生可酌情考虑（需具备对应项⽬经验）。</li><li>具备扎实的计算机基础知识，掌握数据结构、算法、计算机⽹络、操作系统、数据库原理等核⼼理论。核心</li></ol><p><strong>技术要求</strong></p><ol><li>熟练掌握Java语言基础，包括JDK核⼼API（集合、IO、多线程、反射、注解等），理解JVM工作原理（内存模型、垃圾回收机制、类加载机制），能进行JVM性能调优。</li><li>熟练使用Spring、SpringBoot、SpringMVC框架，理解Spring IoC、AOP核心原理，能独立搭建SpringBoot项目，配置核心参数。</li><li>熟悉MyBatis、MyBatis-Plus等持久层框架，能熟练编写SQL语句、 mapper映射文件，掌握分页、动态SQL、关联查询等技巧。</li><li>了解微服务相关技术（SpringCloud、SpringCloudAlibaba），如Nacos、Eureka、Feign、Gateway、Sentinel等，有微服务项目开发经验者优先。</li><li>熟悉消息队列（RabbitMQ、Kafka等），理解消息队列的应用场景（解耦、削峰、异步通信），能独立实现消息的发送、接收、重试、死信队列处理。</li><li>掌握Redis等缓存技术，理解缓存原理、缓存穿透、缓存击穿、缓存雪崩的解决方案，能熟练使用Redis进行数据缓存、分布式锁实现。</li><li>了解Docker容器技术，能使用Docker打包、部署项目，有Docker Compose、K8s使用经验者优先。</li><li>熟悉TCP/IP协议栈，深入理解TCP协议核心机制（三次握手、四次挥手、滑动窗口、拥塞控制、重传机制等），能排查网络通讯相关问题（如连接超时、数据丢包、粘包拆包等）。</li><li>了解Java网络编程基础，熟悉Socket、NIO、Netty等网络通讯相关技术，能使用Netty等框架进行高性能网络通讯开发者优先。</li></ol>', '1-3年', '6310728ef29f13050nd_2di6F1tV', '深圳 · 宝安区 · 西乡', '8-13K·13薪', 'Java, Spring, MyBatis, Hibernate, SpringCloud, MySQL, Redis, Oracle', 'java工程师', 'https://www.zhipin.com/job_detail/6310728ef29f13050nd_2di6F1tV.html', '五险一金, 年终奖, 员工旅游, 节日福利');
INSERT INTO `jobs` VALUES (168, '渴望科技', '计算机软件', '0-20人', '', '大专', '<p><strong>岗位职责</strong></p><ol><li>参与公司Java项目的开发与维护工作；</li><li>根据需求文档进行系统设计、编码实现，确保代码质量；</li><li>参与代码审查，协助解决技术难题，提升系统性能；</li><li>编写相关技术文档，参与项目的版本控制和部署流程。</li></ol><p><strong>任职要求</strong></p><ol><li>对Java语言有扎实的理解，熟悉面向对象编程；</li><li>了解常用的开发框架，如Spring Boot、Hibernate等；</li><li>具备良好的数据库知识，熟悉SQL及常见关系型数据库；</li><li>具有较强的学习能力和团队协作精神，能够适应快速变化的工作环境。</li></ol>', '1-3年', '2443c91a02fb37a403J-3d6-EVtR', '深圳 · 坪山区 · 坪山', '7-12K', 'Java, 不接受居家办公, Kafka, Tomcat, Nginx, Docker, JVM, MySQL, PostgreSQL, Redis, Spark, Hive, 架构设计经验, 分布式经验, 大数据经验, 物联网经验, 微服务经验', '医疗java开发工程师', 'https://www.zhipin.com/job_detail/2443c91a02fb37a403J-3d6-EVtR.html', '');
INSERT INTO `jobs` VALUES (169, '快瞳科技', '计算机软件', '0-20人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>boss负责AI产品B端系统的服务端设计和研发；</li><li>负责AI数据管理，包括分类、存储、读取等 3、负责AI系统统一对外接口，编写技术文档，实现接口封装，解答客户问题；</li><li>完成领导安排的其他相关任务</li></ol><p><strong>任职要求</strong></p><ol><li>本科以上学历，2年以上java开发和后台开发的项目经验；</li><li>熟练掌握 Java 及面向对象设计开发，熟悉常⽤框架；</li><li>熟练掌握 MySQL 应⽤开发、数据库原理和常⽤性能优化和扩展技术；</li><li>熟悉http 协议、缓存、jvm 调优、序列化、Docker等；</li><li>熟悉python/shell等脚本语言；熟悉Linux环境及操作，熟悉系统、应用部署和调优 6、具备较强的主动承担意识和⾃我驱动力，良好的客户服务意识；具备较强的主动学习意识和学习能力</li></ol>', '1-3年', 'b0334291ec0899e30nd-3960EVVX', '深圳 · 南山区 · 科技园', '10-12K', '', 'Java开发工程师', 'https://www.zhipin.com/job_detail/b0334291ec0899e30nd-3960EVVX.html', '全勤奖, 五险一金, 底薪加提成, 团建聚餐, 保底工资, 带薪年假, 绩效奖金');
INSERT INTO `jobs` VALUES (170, '深圳万顺项目策划', '其他专业服务', '0-20人', '', '本科', '<p><strong>岗位职责</strong></p><ol><li>独立完成公司软件系统的功能开发与维护；</li><li>根据技术方案生成网页或者App3、协助进⾏系统性能优化和技术问题排查； 4 Ps:开发⾹港公司需要的软件或前端，供⾹港公司使用。</li></ol><p><strong>任职要求</strong></p><ol><li>具备扎实的编程基础和良好的代码规范；</li><li>熟练掌握至少⼀门主流编程语言，能够独立完成功能模块开发；</li><li>熟悉常用数据结构与算法，理解操作系统及网络基础知识；</li><li>由0-1独立开发5 、要求会粤语。</li></ol>', '1-3年', 'f43daa82d6b369b90ndz39S1E1RX', '深圳 · 罗湖区 · 东门', '8-12K', 'Java, 不接受居家办公, C++, Hibernate, C, SpringCloud, Kafka, Redis, Spring, HBase, 大数据经验, 微服务经验, MySQL, PHP, MyBatis, MongoDB, 架构设计经验, Oracle, Python', '开发工程师', 'https://www.zhipin.com/job_detail/f43daa82d6b369b90ndz39S1E1RX.html', '');
INSERT INTO `jobs` VALUES (171, '松果金融', '广告营销', '20-99人', '', '本科', '<p><strong>工作职责</strong></p><ol><li>负责公司自研系统平台和软件的研发和维护；</li><li>对业务需求进行技术方案设计、实现以及优化，持续提升服务性能和稳定性；</li><li>改进和优化开发流程、技术框架、服务设施性能；</li><li>跟踪新技术发展并运用到实际项目中。</li><li>负责高质量编码设计，承担业务重点技术攻坚，保证高可靠，高性能，高可扩展的业务支撑；</li></ol><p><strong>任职资格</strong></p><ol><li>本科以上学历，计算机科学、电子工程、信息工程或其它相关理工科专业学士以上学位，有2年以上互联网服务端开发经验；</li><li>熟练掌握一门以上主流程序设计语言（C/C++、Java、Python等），具备扎实的编程功底；</li><li>熟悉 Python，REST API设计规范；</li><li>掌握MySQL等关系型数据库的使用，熟悉Redis/MongoDB等NoSQL技术；</li><li>熟悉Linux基本知识，熟悉Git团队开发与版本管理；</li><li>熟悉网络爬虫、app, node.js开发可视为加分项；</li><li>优秀的分析问题和解决问题的能力，对解决挑战性问题充满激情；</li><li>善于沟通，工作积极主动，责任心强，具备良好的团队协作能力；岗位</li></ol><p><strong>福利</strong></p><p>1、入职购买五险一金 2、年终奖</p>', '1-3年', '95d08e3755960e9d1HFz2du-GVBW', '深圳 · 南山区 · 科技园', '9-14K', 'Java, 不接受居家办公, SpringCloud, MySQL, Spring, Oracle', 'java开发工程师', 'https://www.zhipin.com/job_detail/95d08e3755960e9d1HFz2du-GVBW.html', '');
INSERT INTO `jobs` VALUES (172, '汇巨信息', '计算机服务', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>参与基boss于Java技术的企业级应用开发，参与软件系统的需求、分析与设计、审核，并负责完成核心代码；</li><li>根据开发进度和任务分配，独立完成相应模块的软件设计、编程、开发、测试以及相关文档。</li></ol><p><strong>岗位要求</strong></p><ol><li>计算机技术等相关专业本科以上学历，有扎实的软件基础知识；</li><li>精通Java，有1年以上Java应用开发经验；</li><li>精通面向对象设计，有大型关系型数据库的开发设计经验优先；</li><li>熟悉Oracle等常规数据库，精通SQL语句编写5、熟悉主流框架，如Spring等开源框架，6、熟练使用Tomcat等中间件；</li><li>需要能够使用Eclipse，Idea，Git，SVN等8、为人诚实，思维严谨，学习能力和独立工作能力强，能承受一定的工作压力；工作勤奋，责任心强，具体良好的沟通能力和团队合作意识；</li><li>有数据仓库开发经验的优先，做过广电、电信业务系统者优先</li></ol>', '1-3年', '65d1dce7ca0dfcfb1nR-2ty-EFtV', '深圳 · 南山区 · 科技园', '8-12K', 'Java', 'JAVA开发工程师', 'https://www.zhipin.com/job_detail/65d1dce7ca0dfcfb1nR-2ty-EFtV.html', '五险一金, 零食下午茶, 加班补助, 定期体检, 周末双休, 带薪年假, 员工旅游, 意外险, 节日福利, 年终奖');
INSERT INTO `jobs` VALUES (173, '广东国科城市大脑科技', '计算机软件', '20-99人', '', '本科', '<p>【</p><p><strong>岗位职责</strong></p><p>】1、参与项目前期需求调研分析与设计工作2、按计划独立完成开发、编程任务3、完成接口文档、数据库设计、测试⽂档、使⽤⼿册等文档编制工作4、参与相关的系统测试及部署⼯作5、维护软件使之保持可用性和稳定性6、负责公司产品的维护和更新工作7、完成项目经理交办的其他工作【</p><p><strong>任职要求</strong></p><ol><li>掌握SpringBoot、MyBatis或其他开发框架。</li><li>熟练至少一种IDE，如Eclipse或IntelliJ IDEA。</li><li>掌握SQL语法，掌握至少一种关系型数据库，如MySQL或 SQL Server、Oracle数据库。</li><li>掌握至少一种代码版本控制工具，如Git或SVN。</li><li>全日制本科及以上学历，计算机相关专业优先。</li></ol>', '1-3年', 'db25a9342db813810nF93dW6FlBV', '深圳 · 龙华区 · 民治', '8-13K', 'Java, Spring, SpringCloud, MyBatis, MySQL, Redis, 微服务经验, 物联网经验, 不接受居家办公', 'Java', 'https://www.zhipin.com/job_detail/db25a9342db813810nF93dW6FlBV.html', '绩效奖金, 节日福利, 团建聚餐, 生日福利, 带薪年假, 加班补助, 五险一金, 节假日加班费');
INSERT INTO `jobs` VALUES (174, '新信路科技', '互联网', '0-20人', '天使轮', '本科', '<p>岗boss位</p><p><strong>职责</strong></p><ul><li>​​技术攻坚​​：主导通信系统与AI服务的集成开发，优化系统性能与稳定性，解决分布式场景下的技术难点。</li><li>​​架构迭代​​：参与MySQL主从架构、Redis缓存策略的设计优化，实现数据冷热分离与毫秒级响应；参与搭建AI服务平台，参与AI+通信的业务场景研究。</li><li>​​跨团队协作​​：与通信系统团队、前端团队紧密配合，推动产品功能落地，确保技术⽅案与业务需求对齐。</li></ul><p><strong>任职要求</strong></p><ul><li>掌握Redis集群、MySQL主从架构设计，具备SQL优化与分布式事务实战经验；</li><li>熟悉Spring Security权限框架、Jackson序列化，了解容器化部署（Docker/K8s）者加分。​​软性素质​​- ​​学习能力​​：能快速消化通信协议与AI集成技术，主动研究开源方案源码；</li><li>​​问题解决​​：独立定位线上故障，设计过百万级并发系统的容灾方案者优先；</li><li>​​协作意识​​：清晰表达技术方案，适应敏捷开发节奏，推动跨团队目标达成。</li></ul>', '1-3年', 'f349a2a3d42a3e690nd70tW1FVdR', '深圳 · 南山区 · 科技园', '10-15K', 'Java, 不接受居家办公, SpringCloud, MySQL, Spring', 'Java', 'https://www.zhipin.com/job_detail/f349a2a3d42a3e690nd70tW1FVdR.html', '');
INSERT INTO `jobs` VALUES (175, '美琦国际货运代理', '物流/仓储', '100-499人', '未融资', '本科', '<p>1.本科boss及以上，计算机相关专业，3年以上Java开发经验2. 核心背景：有跨境物流系统（WMS/OMS/TMS/尾程打单）开发经验3. 必备技能：熟练掌握Java、Spring Boot/Cloud、MySQL、Redis，会用Maven/Git4. 核心工作：负责系统开发、架构优化、线上问题排查与维护</p>', '1-3年', 'eac2a3165d97b73b0nB429S9F1JW', '深圳 · 龙岗区 · 坂田', '10-15K', 'Java, OMS, SpringCloud, MySQL, Redis, SQL Server, TMS, Spring, WMS, 跨境物流系统', '高级java开发', 'https://www.zhipin.com/job_detail/eac2a3165d97b73b0nB429S9F1JW.html', '零食下午茶, 带薪年假, 节日福利, 有无线网, 团建聚餐, 定期体检, 员工旅游, 五险一金, 底薪加提成, 生日福利, 补充医疗保险, 交通补助, 年终奖');
INSERT INTO `jobs` VALUES (176, '核芯智联', '电子/半导体/集成电路', '0-20人', '', '本科', '<p><strong>工作内容</strong></p><ol><li>负责Java相关的高级研发工作，确保代码质量和模块功能的实现。</li><li>参与系统设计，包括功能设计和数据库结构设计，确保系统的稳定性和高效性。</li><li>与团队合作，快速定位并解决技术问题，提升系统的性能和用户体验。</li></ol><p><strong>任职要求</strong></p><ol><li>精通Java编程语言，具备扎实的Java开发能力。</li><li>熟悉Springboot、SpringCloud、MyBatis等主流Java框架和技术栈。</li><li>具备良好的逻辑思维能力，能够理解复杂的业务需求并转化为技术实现。</li></ol>', '1-3年', '3ea64a9fcdafc9be03Z92tq4E1BR', '深圳 · 龙华区 · 龙华', '15-20K', 'Java, SpringCloud, MyBatis, Redis, MySQL, 架构设计经验, 微服务经验, 分布式经验, 物联网经验', 'java高级研发工程师', 'https://www.zhipin.com/job_detail/3ea64a9fcdafc9be03Z92tq4E1BR.html', '');
INSERT INTO `jobs` VALUES (177, '古法', '电子商务', '20-99人', '', '本科', '<p>1.主要负责本公司的日常工作处理2.完成上级安排的一些其他事务性工作公司免费提高住宿4.有意向者请直接在BOSS与我沟通</p>', '1-3年', '1bd3143558d3cecd1HR92Ny8FFNW', '深圳 · 宝安区 · 西乡', '15-16K', 'PHP, Shell', 'Java', 'https://www.zhipin.com/job_detail/1bd3143558d3cecd1HR92Ny8FFNW.html', '');
INSERT INTO `jobs` VALUES (178, '畅飞扬CFY', '计算机软件', '0-20人', '未融资', '本科', '<p>招聘｜Java后端开发工程师深圳龙岗</p><p><strong>一、岗位职责</strong></p><p>1、 负责公司产品后端业务开发、接口联调、问题修复2、AI智能体完成基础CRUD、代码生成，你专注需求整合、测试上线3、对接算法工程师，完成AI模型接口调用与本地化部署适配4、维护MySQL、Redis，保障系统稳定运行</p><p><strong>二、任职要求</strong></p><ol><li>1年左右Java后端经验，能快速接手工作2、熟练精通：Spring Boot MyBatis、MySQL、Redis3、懂接口开发、自测、联调，能独立负责模块4、踏实靠谱并有敬业精神、执行力强，自律性良好并能高效高质交付 三、加分项 - 会使用AI开发工具（Cursor/通义/豆包等）提升编码效率、 熟练使用及了解各主流Al平台的应用调用- 有大模型接口调用、RAG、智能体相关开发经验- 了解Docker、千问、豆包和通义等模型本地化部署及调用、服务对接流程- 有政务/档案/政企项目、高并发产品开发经验- 熟悉国产信创环境（麒麟、统信UOS）优先- 能快速接手现有代码，独立排查问题和开发工作四、有以下技能基础优先录取且根据实际调高待遇：</li><li>在图文声像智能识别语言处理领域或自然语言研发经验者优先考虑。</li><li>做过手机端开发，小程序、App的，熟悉了解C++的。</li></ol><p><strong>二、任职资格</strong></p><ol><li>计算机、人工智能、软件工程等相关专业，全日制统招本科以上学历。</li><li>至少1年以上实际开发经验；（注：有参与过多个项目开发或独立主导承担过开发项目的优先）。</li><li>具备创新意识，性格开朗，具有良好的表达沟通能力，思路清晰，吃苦耐劳与敬业精神以及较强的责任心与团队精神。欢迎优秀实习生投简历，择优录用注明：</li><li>目前以线下面试为主，待遇以综合能力面试评估而定。前来面试者自备自带简历。</li><li>思想，心态成熟稳重者优。思想心态漂浮不稳者请谨重应聘。</li><li>不接受成考，拒绝假学历，假履历（面试时和入职时核查）。薪酬待遇：</li><li>5k～12k之间，具体根据个人综合能力而定。</li><li>带薪享国家假期，生日礼，旅游团建等。</li><li>不定期举行活动及学习成长。</li><li>工作奖励，项目奖等。大小周，八小时制。面试地址：深圳市龙岗区大运软件小镇74栋一楼（导航该地址）。</li></ol>', '1-3年', '4cc5c94c957d1d041Hx539i5GFtR', '深圳 · 龙岗区 · 横岗', '7-12K', 'Java, 大数据经验, 音视频经验, 不接受居家办公, Tomcat, 分布式经验, MySQL, Spring', 'java开发工程师', 'https://www.zhipin.com/job_detail/4cc5c94c957d1d041Hx539i5GFtR.html', '');
INSERT INTO `jobs` VALUES (179, '深圳市飞录科技', '电子/硬件开发', '0-20人', '未融资', '本科', '<ol><li>参与系统架构设计，优化系统性能，提升用户体验。</li><li>与团队合作，完成模块测试，并协助解决项目中的技术难题。</li></ol><p><strong>任职要求</strong></p><ol><li>熟练运用Java语言，具备扎实的编程能力和良好的代码习惯。</li><li>熟悉常用的软件开发框架和技术栈，能够高效进行软件开发。</li><li>具备良好的团队合作精神，能够有效沟通，协同解决开发中的问题。</li></ol>', '1-3年', '634be49d76dfbc0a03V82tS1GVpQ', '深圳 · 龙岗区 · 横岗', '15-16K', '', '软件工程师', 'https://www.zhipin.com/job_detail/634be49d76dfbc0a03V82tS1GVpQ.html', '股票期权, 全勤奖, 五险一金, 工龄奖, 年终奖');
INSERT INTO `jobs` VALUES (180, '深圳市凝光世纪科技', '人工智能', '20-99人', '未融资', '本科', '<p>##</p><p><strong>岗位描述</strong></p><p>我们正在招聘一名后端工程师，负责 AI 皮肤检测应用的后端系统设计、开发与维护。该岗位主要⽀持移动端、后台管理端和 AI 服务之间的数据流转，参与 API 设计、核⼼数据模型建设、第三⽅服务集成、系统部署与稳定性保障。我们希望候选人具备扎实的通用后端⼯程能力，能够独立完成从需求理解、接口设计、数据库设计、开发测试到上线维护的完整开发流程。如果候选人有【 WebSocket、实时语音服务、流式通信或设备长连接】相关经验，将会是重要【加分项】。##</p><p><strong>岗位职责</strong></p><ol><li>负责应用后端系统的设计、开发与维护，支持移动端、后台管理端和 AI 服务的业务需求。</li><li>设计并实现稳定、清晰、可复用的 API，定义服务之间的数据流和接口规范。</li><li>负责用户、检测记录、图片、报告等核心数据模型设计，保障数据结构清晰、可扩展。</li><li>对接第三方 AI 服务、云存储、认证、通知等外部系统。</li><li>负责后端服务的部署、日志、监控、错误排查和性能优化。</li><li>根据产品需要，参与实时通信、设备接入、语音服务等后端能力的集成与改造。##</li></ol><p><strong>岗位要求</strong></p><ol><li>3 年以上后端开发经验，有独立负责模块或服务的经验。</li><li>熟悉至少一种主流后端语言，例如 Java、Go、Python、Node.js。</li><li>熟悉 RESTful API 设计，能够与移动端或前端清晰定义接口。</li><li>熟悉 PostgreSQL / MySQL 等关系型数据库，能够进行表结构设计和常见查询优化。</li><li>熟悉 Redis、对象存储、消息队列等常见后端组件。</li><li>熟悉云服务部署和基础运维，例如 AWS、GCP、Azure、阿里云等。</li><li>理解异步任务、缓存、限流、重试、幂等、服务拆分等后端设计概念。</li><li>具备线上问题排查、日志分析和性能优化经验。</li><li>能够独立完成从需求理解、接口设计、数据库设计、开发测试到上线维护的完整后端开发流程。</li><li>具备良好的代码质量意识，能编写可维护、可测试的代码。</li><li>能够与移动端、AI 工程师、产品人员清晰沟通需求、接口和数据流程。## 加分项1. 有 WebSocket、流式通信、实时语音服务、设备长连接或低延迟后端服务开发经验。</li><li>有语音相关后端经验，例如 ASR / TTS 服务接入、音频流转发、会话状态管理、打断处理、实时语音交互链路等。</li><li>有图片、文件、异步任务、结构化数据生成或结果处理相关系统经验。</li><li>有 AI 应用后端开发经验，熟悉 LLM、Agent、Memory、上下文管理、工具调用或状态管理等相关系统的设计与集成。</li><li>有向量数据库、RAG、embedding、语义检索等 AI 应用基础设施经验。我们提供什么？薪资面谈 | 线上办公无坐班无打卡 | 偶尔线下会议 | 初创公司充分尊重和爱惜人才，能让你的才华落地开花 | 扁平化管理沟通效率高</li></ol>', '1-3年', 'b41b9025f03b17bb0nFz2NW9FlpY', '深圳 · 南山区 · 科技园', '15-25K', 'Java, Python, Golang, MySQL, Redis, PostgreSQL, 架构设计经验, 接受居家办公', '后端工程师', 'https://www.zhipin.com/job_detail/b41b9025f03b17bb0nFz2NW9FlpY.html', '团建聚餐, 员工旅游, 绩效奖金, 五险一金');
INSERT INTO `jobs` VALUES (181, '鼎新软件', '计算机软件', '20-99人', '不需要融资', '本科', '<p>【</p><p><strong>岗位职责</strong></p><ol><li>参与公司核心产品的设计及研发；</li><li>参与产品评审，能提出可行的技术方案4. 参与日常产品维护，bug修复，性能调优等工作。【</li></ol><p><strong>职位要求</strong></p><ol><li>熟悉TCP/IP、websocket、http等常用通讯协议；</li><li>JAVA开发基础扎实，熟悉设计模式，具备常规数据结构和算法基础；</li><li>熟悉互联网开发基本框架，例如Spring，MyBatis，Spring Boot等；</li><li>熟悉数据库相关知识，例如MySQL，了解NoSQL, key-value存储原理；</li><li>对于Restful API设计有良好的基础，熟练掌握api接口开发工作;</li><li>具有良好的沟通协调能力及进取精神，思维条理清晰，学习能力强；</li><li>抗压能力强，有篮球、羽毛球等特长者优先；</li></ol>', '1-3年', '8e008484de6b71841XZ529u7FFdX', '深圳', '8-13K', 'Socket技术, 网络协议, 数据结构, 后端开发, Spring, NoSQL, SpringBoot, Oracle', '后端开发工程师（java方向）', 'https://www.zhipin.com/job_detail/8e008484de6b71841XZ529u7FFdX.html', '员工旅游, 定期体检, 节日福利, 零食下午茶, 餐补, 年终奖, 带薪年假, 五险一金');
INSERT INTO `jobs` VALUES (182, '飞创协作', '互联网', '100-499人', 'A轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责飞书集成平台的技术应用和落地，满足对飞书套件内多个场景的集成需求。</li><li>负责飞书集成和相关接口开发，为运维系统及其他业务系统拓展功能。</li><li>根据客户需求，参与相关系统的架构设计、调研、文档撰写、技术评审等工作。</li><li>设计、开发和测试飞书与其他应用程序的集成方案，确保其稳定性和可靠性。</li><li>优化集成系统的引擎与调度，使其与公司业务或项目相匹配。</li><li>参与飞书相关平台系统的日常管理和运维工作。</li></ol><p><strong>任职要求</strong></p><ol><li>统招本科以上学历，2年以上SaaS软件开发经验。</li><li>熟悉全栈、AI、JS、JavaScript、Java、Python、接口对接、集成开发、接口开发、海外。</li><li>有将不同系统进行集成的实际经验。</li><li>能够与业务部门进行有效的沟通，准确分析业务需求并转化为技术需求。</li><li>具有IT和企业信息化方面的知识基础，理解数据库原理。</li><li>具备良好的沟通能力、需求理解能力和团队合作意识。另：如果有以下类似实践经历的话，可以直接获得面试机会：对 AI 有自己的认知、实践对海外平台有实际的实践（例如 GitHub、Hugging Face等）</li></ol>', '1-3年', '303da0ac02cc25b303Zz3Nm6EFpZ', '深圳 · 南山区 · 科技园', '10-15K', 'Java, AI, 全栈, 接口开发, 集成开发, Python', '项目集成实施工程师', 'https://www.zhipin.com/job_detail/303da0ac02cc25b303Zz3Nm6EFpZ.html', '团建聚餐, 五险一金, 底薪加提成, 零食下午茶, 定期体检, 股票期权, 年终奖, 绩效奖金, 带薪年假, 节日福利, 员工旅游');
INSERT INTO `jobs` VALUES (183, '中兴耀维', '互联网', '20-99人', 'A轮', '本科', '<ol><li>有扎实的Java基础，Java多线程、并发以及网络通信有深厚的经验；</li><li>精通java开源框架：springboot技术栈，mybatis，Maven等开发技术；</li><li>了解微服务原理与开发规范，熟悉dubbo，zookeeper；</li><li>熟悉Spring Cloud技术栈，具有很强的复杂问题分析能力和解决问题能力；</li><li>熟悉主流数据库的使用和优化，如：MySQL及NoSQL等；</li><li>有强烈的责任心和良好的沟通能力，良好的代码设计能力、code style及编程习惯；</li><li>性格开朗，具有团队合作精神，学习能力强，能承受较大的工作压力。</li><li>了解分布式系统架构，有分布式系统开发经验，或k8s相关经验者优先；</li><li>有WCS\\WMS\\APS\\MES\\RCS\\FMS开发经验，或工厂经营分析开发经验者优先；</li></ol>', '1-3年', '084ef61e5fcb54371HV92t-5EFRT', '深圳 · 宝安区 · 西乡', '8-13K', 'Java, MyBatis, MySQL, 微服务经验, MES开发经验, 不接受居家办公', '后端开发工程师', 'https://www.zhipin.com/job_detail/084ef61e5fcb54371HV92t-5EFRT.html', '年终奖, 定期体检, 带薪年假, 五险一金, 员工旅游, 股票期权');
INSERT INTO `jobs` VALUES (184, '开源中国', '互联网', '100-499人', 'C轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>参与公司 AI 相关产品和平台的后端研发与迭代</li><li>参与核心模块的设计、开发、测试、上线及持续优化</li><li>参与服务接口、业务流程及系统集成能力建设</li><li>协助处理系统在性能、稳定性、安全和可维护性方面的问题</li><li>与产品、算法、前端、测试、运维等团队协作，推动项⽬落地</li></ol><p><strong>任职要求</strong></p><ol><li>计算机相关专业本科及以上学历，1-3 年后端开发经验；优秀应届⽣或项⽬经历突出者亦可</li><li>具备良好的编程基础、数据结构与算法基础，有较好的工程实现能力</li><li>有 Rust 开发经验优先；有其他主流后端语⾔经验并愿意转 Rust 方向也欢迎</li><li>熟悉常见后端开发相关知识，包括网络通信、数据库、并发编程、服务开发与问题排查等</li><li>对 AI 应用方向有兴趣，有相关项目经验者优先</li><li>具备良好的学习能力、沟通协作能力和责任心加分项!!!</li><li>有平台型产品或中后台系统研发经验</li><li>有 AI 应用、智能化产品或相关项目经验</li><li>有开源项目、个人作品或完整项目落地经验</li></ol>', '1-3年', '20f77a368cf249dd0nd82t6-F1JQ', '深圳 · 南山区 · 科技园', '12-20K·14薪', '云计算经验', 'Rust 后端开发工程师（AI 方向）', 'https://www.zhipin.com/job_detail/20f77a368cf249dd0nd82t6-F1JQ.html', '餐补, 股票期权, 加班补助, 带薪年假, 丰富员工活动, 14薪, 员工旅游, 节日福利, 零食下午茶, 年终奖, 五险一金, 餐补');
INSERT INTO `jobs` VALUES (185, '中保车服', '互联网金融', '100-499人', 'B轮', '本科', '<p><strong>工作职责</strong></p><ol><li>负责业务方向AI智能体和AI应用能力的设计、开发和交付，重点解决业务流程和业务系统中的实际问题。</li><li>负责将⼤模型、RAG、Agent、知识库、⼯作流、⼯具调用等能力封装为标准化接口、服务组件和可复⽤业务能力。</li><li>负责AI能力与公司现有业务系统的集成对接，包括业务数据库、CRM、ERP、OA、工单系统、流程系统、钉钉/企业微信等。</li><li>负责业务智能体的后端接口、工具调用、权限控制、日志审计、配置管理和监控告警等功能开发。</li><li>参与业务场景中的RAG检索、Agent编排、提示词模板、工具调用、业务规则注入和工作流编排等工程实现。</li><li>配合AI架构师和AI研发工程师，将底层AI能力封装为业务系统可调用、可治理、可复用的标准化服务。</li><li>负责AI应用与企业现有业务系统的数据交互、接口联调、权限对接和上线交付。</li><li>支持业务智能体的PoC、试点上线、问题修复和版本迭代，推动应用从Demo走向生产使用。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机、软件工程、人工智能等相关专业优先。</li><li>熟悉Java/Python/Node.js/Go中至少一种主流开发语言。</li><li>熟悉RESTful API、数据库、缓存、消息队列、权限体系、日志监控等常见工程能力。</li><li>了解大模型应用开发，有LangChain、LlamaIndex、Dify、FastGPT、OpenAI API、本地大模型调用等经验者优先。</li><li>熟悉RAG、向量数据库、Embedding、Prompt Engineering、Agent工具调用等基础概念者优先。</li><li>有业务系统、CRM、ERP、工单系统、数据平台集成经验者优先。</li><li>具备较强的问题拆解能力和工程落地能力，能独立完成从需求到上线的开发工作。</li></ol>', '1-3年', 'f653a46ef5c975050nF_2tS-GFdR', '深圳 · 福田区 · 华强北', '10-15K·15薪', 'Java, Golang, Python, 不接受居家办公', 'ai应用开发工程师', 'https://www.zhipin.com/job_detail/f653a46ef5c975050nF_2tS-GFdR.html', '定期体检, 意外险, 年终奖, 五险一金, 零食下午茶, 带薪年假, 餐补, 团建聚餐, 股票期权, 员工旅游, 补充医疗保险, 节日福利');
INSERT INTO `jobs` VALUES (186, '深圳中地', '计算机软件', '100-499人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>独立完成功能模块代码编写，调试，测试和维护；</li><li>参与产品和项目需求分析，进行系统的功能定义，程序设计；</li><li>负责编写各阶段的产品和项目的技术设计文档。</li><li>领导交办的其他工作。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机相关专业，2年以上工作经验，有GIS行业开发背景者优先考虑；</li><li>精通JAVA、WEB编程，熟悉J2EE技术架构；</li><li>熟悉Spring Cloud、Spring Cloud Alibaba、Spring Boot等主流Java服务架构；</li><li>熟悉RaabbitMQ，Kafka等消息队列中间件，熟悉Elasticsearch分布式搜索引擎；</li><li>具备一定的前端能力，了解主流的jquery、vue、react等前端框架，并具备基本代码的修改能力；</li><li>熟悉ORACLE/MySQL/PostgreSQL数据库以及数据库开发机制；</li><li>熟悉Liunx系统操作，精通Docker，K8S服务集群部署8、熟悉政府项目开发，对各类云上环境（华为云、腾讯云等）有深入的了解。</li><li>踏实稳重、团队合作、良好的沟通能力，学习能力。</li></ol>', '1-3年', '7d6d48944969aebe0HZz2di7F1M~', '深圳 · 南山区 · 科技园', '12-18K', 'Java, Elasticsearch, SpringCloud, Kafka, MySQL, PostgreSQL, Oracle, GIS, k8s', 'Java开发工程师', 'https://www.zhipin.com/job_detail/7d6d48944969aebe0HZz2di7F1M~.html', '补充医疗保险, 五险一金, 年终奖, 定期体检, 带薪年假, 员工旅游, 通讯补贴, 节日福利');
INSERT INTO `jobs` VALUES (187, '酷博咨询', '计算机服务', '0-20人', '', '本科', '<p><strong>职位描述</strong></p><p>Java\nJAVA基础扎实，理解io、多线程、集合等基础框架，对JVM原理有一定的了解\n刘女士\n今日活跃\n酷博咨询\n·\n招聘者\n竞争力分析\n查看完整个人竞争力\n个人综合排名：在人中排名第\n你在？位置\n一般 良好 优秀 极好\nBOSS 安全提示\n严禁用人单位和招聘者用户做出任何损害求职者合法权益的违法违规行为，包括但不限于扣押求职者证件、收取求职者财物、向求职者集资、让求职者入股、诱导求职者异地入职、异地参加培训、违法违规使用求职者简历等，您一旦发现此类行为， 请立即举报\n工商信息\n公司名称\n珠海市酷博咨询服务有限公司\n法定代表人\n刘丽芳\n成立日期\n2021-07-30\n企业类型\n有限责任公司（自然人独资）\n经营状态\n在营\n注册资金\n5万\n查看全部\n工作地址\n深圳宝安区中粮锦云2903\n点击查看地图\n更多职位\n看过该职位的人还看了\njava开发（半导体大厂）\n15-25K\n某知名半导体/芯片公司\n深圳\nweb3后端开发工程师\n15-20K\n深圳通盛源科技\n深圳\nJava工程师\n15-30K·15薪\n某知名公司\n深圳\nJAVA（双倍工资+六险一金）\n15-30K\n华为\n深圳\njava开发（半导体大厂\\国企\\六险一金）\n15-25K·13薪\n某大型公司\n深圳\nFDE工程师（跨境电商+AI）\n15-20K\n增量科技\n深圳\n精选职位\nJava开发（大厂，六险一金）\n15-25K·13薪\n某大型公司\n深圳\nFDE工程师（跨境电商+AI员工方向）\n15-18K·13薪\n增量科技\n深圳\nJava\n15-16K\n同和信息技术有限公司\n深圳\n高级java开发工程师\n15-30K\n嘉立创\n深圳\n中级java开发工程师\n15-18K\n众投互联\n深圳\nJava\n15-30K·14薪\n艾麦物流\n深圳\n深圳\n搜索\n城市招聘 热门职位 推荐公司 热门企业\n百色招聘\n铁岭招聘\n兰州招聘\n银川招聘\n漯河招聘\n天门招聘\n长治招聘\n巴音郭楞蒙古自治州招聘\n池州招聘\n延边朝鲜族自治州招聘\n首页深圳招聘·Java招聘深圳Java招聘酷博咨询Java招聘\n页面更新时间：2026-08-04\n企业服务热线和算法/未成年人等举报渠道 400 065 5799\n老年人直连热线400 661 6030\n工作日 8:00 - 22:00\n休息日 8:00 - 22:00\n企业服务\n职位搜索\nAPP\n投资者关系 Investor Relations\n直品公益基金会\n求职技巧\n使用与帮助\n协议与规则\n隐私政策\n防骗指南\n使用帮助\n联系\n北京华品博睿网络技术有限公司\n公司地址 北京市朝阳区太阳宫中路16号院1号楼18层1801内09\n违法和不良信息举报邮箱/未成年人举报渠道 jubao@.com\nCopyright © 2026 京ICP备14013441号-5京ICP证150923号 电子营业执照 京公网安备11010502032801 朝阳网警 人力资源服务许可证 网上有害信息举报专区 朝阳区人社局监督电话 算法备案信息</p>', '1-3年', '9d55c911eb70a2d11XB_2d28EVZV', '深圳 · 宝安区 · 西乡', '15-16K', 'Java', 'Java', 'https://www.zhipin.com/job_detail/9d55c911eb70a2d11XB_2d28EVZV.html', '');
INSERT INTO `jobs` VALUES (188, '深圳市维特利医疗科技', '医疗器械', '0-20人', '', '本科', '<p><strong>岗位职责</strong></p><ol><li>参与医疗科技系统后端功能的设计与开发，完成核⼼代码编写；</li><li>配合产品与前端团队，实现业务需求，保障系统稳定性与可扩展性；</li><li>参与系统架构优化和技术⽅案设计，提升服务性能与数据处理能⼒；</li><li>负责接口设计与维护，支持多终端数据交互与集成；</li><li>根据业务发展需要，持续迭代和优化现有系统模块。</li></ol><p><strong>任职要求</strong></p><ol><li>具备扎实的Java编程基础，熟悉常用设计模式与开发框架；</li><li>熟悉分布式系统设计，了解微服务架构及相关技术组件；</li><li>掌握数据库设计原理，具备良好的SQL编写与调优能⼒；</li><li>具备良好的沟通能力和团队协作意识，能高效推进项目落地。</li></ol>', '1-3年', 'fd89e96ea82dcadc0nJ72dS0ElRS', '深圳 · 龙岗区 · 横岗', '15-16K', '', 'Java', 'https://www.zhipin.com/job_detail/fd89e96ea82dcadc0nJ72dS0ElRS.html', '');
INSERT INTO `jobs` VALUES (189, '创欧供应链', '跨境物流', '100-499人', 'D轮及以上', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责公司核心业务系统后端服务的架构设计、开发、调试与优化，确保系统具备高性能和高稳定性；</li><li>根据产品需求，参与业务模块的详细设计与开发，实现高质量、易维护的代码交付；</li><li>持续优化现有系统，定位并解决性能瓶颈，快速响应并处理线上故障；</li><li>深耕跨境物流 / 国际货代自研系统，熟悉海运空运专线业务、运价计费、报关清关、物流轨迹、跨境结算模块开发，熟练对接各类物流第三方接口，参与过 TMS / 货代物流系统全流程开发，懂跨境行业业务优先。</li></ol><p><strong>任职要求</strong></p><ol><li>全日制本科及以上学历，计算机科学、软件工程或相关专业，具备扎实的计算机及网络基础；</li><li>3年以上Java开发经验，精通Java语言，熟悉JVM内存管理、垃圾回收机制，具备成熟的项目实战经验；</li><li>编程基础扎实，熟练掌握数据结构和算法，深入理解IO、多线程、并发、集合等基础框架；</li><li>精通MySQL、Redis、MongoDB等数据库技术，深入理解数据库原理及性能优化，能够编写高性能代码，有大表处理经验者优先；</li><li>具备优秀的编码习惯和问题解决能力，能够独立分析和解决复杂技术问题；</li><li>具备良好的团队合作精神和沟通能力，责任心强，适应快速变化的工作环境。</li><li>熟悉跨境全链路业务：国际海运 / 空运 / 专线、头程尾程、订舱、清关、报关、仓配、集运、海外仓流程。公司</li></ol><p><strong>福利</strong></p><ol><li>购买五险一金；</li><li>每年两次调薪机会；</li><li>员工生日红包；</li><li>入职享有5天年假，按照工作年限每年递增1天，7天封顶；</li><li>周末双休；</li><li>弹性上班时间（早上8点30—下午6点或早上9点—下午6点30以此类推），中午休息一个半小时。</li></ol>', '1-3年', 'e559904c68d8b52403F509m5FFtV', '深圳 · 南山区 · 科技园', '12-20K·13薪', 'JVM, Java, Tomcat, 分布式经验, Redis, SQL Server, Spring, 有前端经验/技能, 大数据经验, Docker, 微服务经验, MySQL, MyBatis, MongoDB, 架构设计经验, Oracle', 'java开发工程师', 'https://www.zhipin.com/job_detail/e559904c68d8b52403F509m5FFtV.html', '定期体检, 保底工资, 意外险, 底薪加提成, 绩效奖金, 年终奖, 五险一金');
INSERT INTO `jobs` VALUES (190, '社区云科技', '生活服务(O2O)', '20-99人', '未融资', '本科', '<p><strong>工作职责</strong></p><ol><li>负责基础应用（包括但不限于自研物业工单系统、收费系统）的研发与维护；</li><li>发现并解决研发过程中的各项问题，融入和促进团队工作效率和开发质量的提升，包括但不限于引入新技术，研发新组件等；</li><li>分析和深入发掘现有系统的不足，定位系统瓶颈，提高系统性能和稳定性；</li></ol><p><strong>任职要求</strong></p><ol><li>3年以上Java开发经验，扎实的Java编程基础，JVM调优经验，熟悉各种设计模式；</li><li>熟练掌握Spring boot、Spring cloud、Mybatis等主流开发框架；</li><li>熟悉MySQL、Elasticsearch、Redis、MongoDB、Clickhouse；</li><li>熟悉RabbitMQ、Kafka等常用消息中间件；</li><li>良好的组件级建模能力，能够设计复杂业务、高并发、大数据量的系统；</li><li>熟悉整个软件过程，能够沟通需求、控制项目进度，有良好的文档能力；加分项：</li><li>拥有良好的大局观，独立思考，拥有自己的判断力；</li><li>对一个或多个开源项目有深入理解；</li><li>有工单、计费相关经验。</li></ol>', '1-3年', '12582502e82e6e1b1nB83N68EVdW', '深圳', '7-12K', 'Maven, GIT, Linux, SpringCloud, MySQL, 分布式技术, 微服务架构, Redis', 'Java工程师', 'https://www.zhipin.com/job_detail/12582502e82e6e1b1nB83N68EVdW.html', '');
INSERT INTO `jobs` VALUES (191, '华深云博科技', '计算机软件', '20-99人', '', '本科', '<p>岗位boss</p><p><strong>职责</strong></p><ol><li>负责参与新项目的开发及计划；</li><li>负责项目系统构架设计及系统接口设计；</li><li>可以熟练运用html、JSP、Servlet等进行编程；</li><li>熟悉多种java工具，精通spingmvc、mybatis；</li><li>可以精确地分析市场需求完成系统设计及开发；</li><li>负责根据用户及市场需求设计文档及开发，不断改善。</li></ol><p><strong>任职要求</strong></p><ol><li>拥有2年以上Java项目开发经验；</li><li>拥有扎实的Java编程基础，熟练掌握CVS/SVN等；</li><li>具有良好的创新思维、有团队合作精神及沟通能力；</li><li>为人谦虚好学、具有较强的学习能力，肯钻研，能够踏实工作，责任心强。</li><li>研究生及以上学历。</li></ol>', '1-3年', '9f389182b3a9b1bf03Vz3ty4EFBV', '深圳 · 福田区 · 车公庙', '8-11K·13薪', 'Java, C++, 不接受居家办公, SpringCloud, MySQL, Spring, ERP开发经验', 'JAVA开发工程师', 'https://www.zhipin.com/job_detail/9f389182b3a9b1bf03Vz3ty4EFBV.html', '');
INSERT INTO `jobs` VALUES (192, '观讯信息(深圳)...', '计算机软件', '0-20人', '', '本科', '<ol><li>参与产品的需求分析、功能设计、数据库设计、接口设计等相关工作；</li><li>和团队成员保持良好沟通，对产品需求提出合理化建议，按计划确保开发工作顺利进行；</li><li>参与公司技术标准规范的建设，对技术规范相关工作提出合理化建议；</li><li>参与公司内部的技术分享与交流等相关工作。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机、地理信息、通信等相关专业；</li><li>1-3年工作经验，实际参与项目的研发经验至少1年以上；</li><li>能熟练运用后端开发的常用技术工具，如Git、SVN、Docker、Jenkins、IntelliJ IDEA等；</li><li>熟悉常用数据库，如MySQL、PostgreSQL，能熟练使用SQL语句，对数据库事务、锁、索引有一定的了解；</li><li>熟悉常用的编程语言，如Java、C++、C#、go、Python等，至少熟悉其中1种编程语言；</li><li>对分布式系统有一定了解，能熟练使用Spring MVC、Spring Boot、Spring Cloud、Spring Cloud Alibaba等开源框架进行开发；</li><li>具备系统分析设计能力者优先，熟悉大数据、云计算、人工智能等相关技术栈的优先；</li><li>有智慧城市、智慧交通、视频监控、智慧园区等项目开发经验者优先；</li><li>有创业激情，有主人翁意识，抗压能力强，积极主动。</li></ol>', '1-3年', '3f3ce4f5c712ae401XVy2ty5FltZ', '深圳 · 南山区 · 南头', '8-12K·13薪', 'Java, C/C++, Python, 企业级应用开发, 全栈开发, Netty, SQL Server, 后端开发, Spring, SSM, 客户端开发', '软件后端开发工程师', 'https://www.zhipin.com/job_detail/3f3ce4f5c712ae401XVy2ty5FltZ.html', '五险一金, 年终奖, 定期体检, 股票期权, 住房补贴, 员工旅游, 带薪年假, 零食下午茶');
INSERT INTO `jobs` VALUES (193, '深圳顺天创科技', '互联网', '20-99人', 'A轮', '本科', '<p>后端开发工程师（AI 应用方向）</p><p><strong>岗位职责</strong></p><ol><li>负责公司官网、AI 产品及业务系统的后端研发⼯作，参与服务端架构设计、开发与维护；</li><li>参与 ToC 端 AI 产品的后端建设，包括⽤户体系、业务逻辑、数据管理、接口服务等核⼼模块开发；</li><li>配合前端、UI、产品团队完成产品从需求设计、技术方案制定到上线交付的完整流程；</li><li>负责公司 AI 平台及相关服务的后端开发，包括模型接口调用、业务服务封装、数据处理及系统能⼒建设；</li><li>根据业务发展需求，参与 SaaS 平台、管理后台、会员体系、支付系统、数据统计等相关业务模块开发；</li><li>负责系统性能优化、安全性建设以及服务稳定性保障，持续提升产品体验；</li><li>参与技术方案设计和架构演进，推动公司技术体系持续完善。---</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机相关专业优先，具备 2 年以上后端开发经验；</li><li>熟练掌握至少一种主流后端开发语言： - Go / Java / Python / Node.js 等；</li><li>熟悉 Web 服务开发流程，具备 RESTful API 设计和接口开发经验；</li><li>熟悉 MySQL、PostgreSQL 等关系型数据库，有数据库设计和性能优化经验；</li><li>熟悉 Redis、消息队列等常用中间件，有高并发业务处理经验优先；</li><li>熟悉 Linux 环境及常见服务部署流程，具备 Docker、Nginx 等相关使用经验；</li><li>具备良好的代码规范意识，能够独立完成模块设计、开发和维护；</li><li>具备较强的问题分析能力和学习能力，能够快速适应新业务和新技术。---AI 方向能力要求1. 对人工智能、大语言模型（LLM）、AIGC 等方向有兴趣并具备一定了解；</li><li>了解DeepSeek、通义千问等大模型 API 调用方式及应用场景；</li><li>了解 Agent、MCP、RAG 等 AI 应用相关技术概念，有实际开发经验者优先；</li><li>有 AI 产品后端服务开发、模型调用平台、智能应用开发经验优先。---加分项- 有 AI 应用、智能助手、Agent 平台开发经验；- 有 SaaS 产品、ToC 产品后端开发经验；- 有用户体系、权限系统、订单支付、会员订阅等业务开发经验；- 熟悉微服务架构、云服务部署及系统监控；- 有从 0 到 1 搭建后端服务经验；- 熟悉 Go 语言生态或 Python AI 开发生态。</li></ol>', '1-3年', '8a5ac9f20dcbe52c0nJ42t-5ElFX', '深圳 · 南山区 · 科技园', '10-15K', 'Golang, Java, Nginx, 不接受居家办公, 分布式经验, PostgreSQL, SpringCloud, Kafka, Redis, Spring, Docker, 微服务经验, MySQL, 云计算经验, 架构设计经验, Python', '后端开发工程师', 'https://www.zhipin.com/job_detail/8a5ac9f20dcbe52c0nJ42t-5ElFX.html', '五险一金, 生日福利, 团建聚餐, 法定节假日三薪, 加班补助, 节假日加班费, 住房补贴, 股票期权, 零食下午茶, 带薪年假, 底薪加提成, 保底工资');
INSERT INTO `jobs` VALUES (194, '拾里郎', '计算机软件', '0-20人', '天使轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>配合开发团队，保障平台迭代优化；</li><li>业务技术方案设计与核心开发；</li><li>建立技术规范与质量体系，提升团队开发效率；</li><li>协同产品、运维等部门推进项目交付，培养团队技术人才。</li></ol><p><strong>任职要求</strong></p><ol><li>本科以上学历，计算机相关专业，3年以上Java开发经验；</li><li>有运维基础，熟练使用linux，会配置应用自启动、备份调优数据库、离线安装软件解决安全问题等；</li><li>熟悉分布式、微服务架构，具备系统性能优化能力；</li><li>熟悉腾讯云、阿里云等主流云平台，熟练使用服务器管理、负载均衡、CDN、对象存储等服务；</li><li>优秀的沟通协调与项目管理能力，抗压性强</li></ol>', '1-3年', '579bfcccffa97b6403J70t-1E1RT', '深圳 · 龙华区 · 民治', '10-15K', 'Java, SpringCloud, MySQL, Python', '中级java开发工程师', 'https://www.zhipin.com/job_detail/579bfcccffa97b6403J70t-1E1RT.html', '五险一金, 加班补助, 员工旅游, 股票期权, 带薪年假, 年终奖, 全勤奖');
INSERT INTO `jobs` VALUES (195, '深圳灵动', '互联网金融', '100-499人', '不需要融资', '本科', '<p>核心定位：寻找能独立承接BIPO系统深度开发任务的“熟手”。既能写代码，又能懂业务（懂薪酬、考勤计算逻辑），最好有从BIPO（必博）出来的背景。关键要求：系统经验： 熟悉BIPO云原⽣微服务架构，曾经参与过BIPO系统的实施上线或版本升级项⽬。业务理解： 能看懂复杂的⼈力资源规则，并能将其转化为技术语言（例如：将不同国家的法定假期规则通过代码实现）。集成能⼒： 主导过至少2个以上第三方系统（如OA、财务金蝶/用友）与BIPO的API集成项目。语言能力： 具备英语读写能力，能阅读英文技术文档（BIPO涉及跨国业务，系统文档可能涉及英文）。</p>', '1-3年', 'f3fee8b2b62d7cd00nZ70tm9F1pQ', '深圳 · 南山区 · 后海', '15-20K·14薪', '', '资深HRIS开发（BIPO专家）', 'https://www.zhipin.com/job_detail/f3fee8b2b62d7cd00nZ70tm9F1pQ.html', '餐补, 带薪病假, 年终奖, 有无线网, 定期体检, 五险一金, 地铁直达, 零食下午茶, 节日福利, 带薪年假, 加班补助, 法定节假日三薪, 员工旅游, 交通补助, 节假日加班费, 团建聚餐, 生日福利');
INSERT INTO `jobs` VALUES (196, '深圳中科软', '计算机服务', '20-99人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ul><li>负责高校信息化系统（如教务管理、学生管理、人事管理、智慧校园、迎新系统、离校系统等）的前后端全栈开发、测试、部署及迭代优化，贴合高校业务场景，满⾜师⽣及⾏政人员使用需求。</li><li>参与需求调研与分析，对接⾼校各部门（教务处、学生处、人事处等），梳理业务逻辑，输出技术方案、接口文档及数据库设计文档，确保开发内容贴合业务实际。</li><li>使用Java技术栈完成后端接口开发、业务逻辑实现，同时负责前端页面开发与交互优化，保障系统的易用性、稳定性和安全性，适配高校多角色（学生、老师、行政人员）使用场景。</li><li>负责数据库设计、SQL优化、缓存配置，解决系统开发及线上运行中的技术问题，排查bug、优化系统性能，保障系统7×24小时稳定运行。</li><li>配合团队完成代码评审、版本管理、项目部署，参与技术选型和技术创新，推动高校信息化系统的迭代升级，提升系统智能化、便捷化水平。</li><li>对接高校信息化相关对接工作，配合完成系统对接、数据同步，协助解决师生使用过程中的技术咨询与问题反馈。</li></ul><p><strong>任职要求</strong></p><ol><li>学历与经验- 本科及以上学历，计算机相关专业（计算机科学与技术、软件工程、信息工程等），1-3年及以上Java全栈开发经验，有高校信息化系统、政企事业单位信息化项目开发经验者优先。- 应届生优秀者可放宽经验要求，需具备扎实的技术基础和较强的学习能力，有相关课程设计、实习项目经验（前后端结合）者优先。</li><li>技术能力（前后端必备）- 后端技术：熟练掌握Java基础（语法、面向对象、集合、多线程、IO等），熟练使用Spring Boot、Spring MVC、MyBatis/MyBatis-Plus等主流框架；熟悉MySQL数据库，具备扎实的SQL编写、索引优化、事务处理能力；了解Redis缓存、RabbitMQ等中间件者优先。- 前端技术：熟练掌握HTML、CSS、JavaScript，熟悉Vue、Element UI等主流前端框架，能够独立完成页面开发、表单交互、数据渲染，具备前端性能优化意识。- 工具与运维：熟练使用Git版本控制、Maven构建工具；了解Linux常用命令，具备基础的项目部署、日志排查能力；熟悉接口调试工具（Postman、Swagger）。- 加分项：了解高校业务流程（教务、学工、人事等）、有微服务、分布式系统开发经验、熟悉国产化数据库/中间件者优先。3.</li></ol><p><strong>综合素质</strong></p><ul><li>具备良好的沟通协调能力，能高效对接高校各部门，准确理解业务需求并转化为技术实现。</li><li>具备较强的问题解决能力、逻辑思维能力，工作认真负责，有责任心和团队协作精神，能独立完成分配的开发任务。</li><li>愿意深入了解高校信息化行业，主动学习新技术、新业务，适应项目迭代节奏，能承受一定的工作压力。</li><li>具备良好的代码规范和文档编写习惯，注重代码质量和系统安全性。</li></ul>', '1-3年', '481b645091fd3c150nd-2N69GVpQ', '深圳 · 龙岗区 · 横岗', '8-12K', 'Java, Docker, SpringCloud, MySQL, MyBatis, Redis, Spring', 'java软件开发工程师', 'https://www.zhipin.com/job_detail/481b645091fd3c150nd-2N69GVpQ.html', '年终奖, 五险一金, 带薪年假, 团建聚餐');
INSERT INTO `jobs` VALUES (197, '河南猎上', '互联网', '0-20人', '', '本科', '<p><strong>岗位职责</strong></p><ol><li>支持生态创新中⼼测试认证⼯作及场景调优（全栈国产化、基础软件栈组合等）。</li><li>⽀持评审ISV提交的适配认证软件技术材料，协助ISV梳理软件技术栈，制定软件迁移适配的部署方案、测试方案，适配资源及配置，并⽀撑ISV完成环境的搭建。问题分析和解决：</li><li>支持协助生态伙伴软件的迁移部署、性能调优、认证；提供基础使用和技术支持，拉通相关产品部、资源池，解决技术难题。</li><li>支持向ISV宣讲解决方案及案例，推动方案的复制、落地；不断的技术赋能、布道；结合相关产品竞争力，推动实现各行业应用场景与ISV的联合解决方案孵化；对开源社区和论坛，持续的优秀技术实践输出，案例总结分享。知识管理与能力建设：</li><li>从日常问题处理，问题分析，和知识打标分析中发现缺失知识，自行输出，或拉通其他领域提供素材或输出知识。</li><li>基于日常问题处理和定期的问题分析发现产品缺陷，输出FAQ，公告或培训课件。</li></ol><p><strong>任职要求</strong></p><ol><li>了解计算、服务器、PC等相关产品硬件知识，有一定云、服务器、存储等领域研发和技术支持经验。技能：</li><li>熟悉Python/C/C++/Java等软件编程语言，在指导下可以进行相关代码的编写与仿真。</li><li>了解ARM/Nvidia/X86相关的一种或多种软硬件体系结构。</li><li>了解硬盘、内存、网卡等关键器件工作原理和PCIE、SAS、I2C等通用接口协议。能力：</li><li>项目管理能力：具备较好的执行力。</li><li>学习能力：热衷新技术学习，善于总结和分享，喜欢动手实践。</li><li>知识管理能力：拥有知识分类整理意识，能够输出相关FAQ或培训课件。</li><li>沟通能力：能按照指导与上下游接口部门建立例行沟通渠道，并例行审视进展。资格要求：学历要求：本科及以上或同等学历（计算机、软件、硬件工程等相关专业）工作经验：IT/CT行业相关从业经验2年及以上，至少熟悉一种主流编程语言要求1.需要有java语言的工作经验(硬性要求）2.需要有基于云平台开发的经验，使用过常用的开源组件（硬性要求）3.如果同时有C/C++的经验则更佳（加分项）。</li></ol>', '1-3年', '51ba3d876d2b093e0nB-29y8EVJT', '深圳 · 南山区 · 科技园', '15-20K', 'Java, C++, Spring, MySQL, 云计算经验', '鲲鹏FAE（有云平台开发经验）', 'https://www.zhipin.com/job_detail/51ba3d876d2b093e0nB-29y8EVJT.html', '');
INSERT INTO `jobs` VALUES (198, '莱动科技', '新能源', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><p>负责公司物联网产品后端服务的设计、开发、维护与优化，涵盖微服务架构搭建、接口开发及核心业务逻辑实现。独立完成后端功能模块的设计、编码与测试，保障代码质量、系统性能及稳定性。参与后端技术选型、架构设计、数据库建模与优化，以及中间件的选型与配置。负责 MQTT、OCPP 等物联网协议的服务端集成与对接，实现设备通信、数据解析、指令下发及状态管理。负责基于 RabbitMQ 的消息队列架构设计、消息收发、异步处理及可靠性保障，解决消息积压、重复消费、消息丢失等问题。负责后端服务的部署、监控、运维及性能调优，保障系统⾼可⽤与⾼并发处理能力。与前端、产品、硬件团队紧密协作，确保物联网项⽬端到端的高质量交付。</p><p><strong>任职要求</strong></p><ol><li>精通 Java ，深刻理解面向对象编程、设计模式、多线程及 JVM 核心特性。</li><li>熟练掌握 Spring Boot、Spring Cloud（Alibaba）等微服务框架，熟悉 MyBatis/MyBatis-Plus、Spring Data JPA 等 ORM 框架的使用与优化。</li><li>熟悉关系型数据库（MySQL）的设计、索引优化及事务管理；掌握 Redis 缓存的使用、集群配置及性能调优。</li><li>精通 RabbitMQ 消息队列的原理、核心特性及实战应用，熟练配置交换机、队列、绑定关系，能灵活运用死信队列、延迟队列、优先级队列等高级特性解决业务问题，具备消息可靠性投递、幂等性处理及性能调优经验。</li><li>精通 MQTT 协议，具备 EMQX 或其他 MQTT Broker 的服务端集成、运维及问题排查经验；熟悉 OCPP 协议（1.6/2.0 版本），有充电桩 / 物联网设备通信对接经验者优先。</li><li>具备独立开发后端项目的能力，熟悉后端工程化流程（Maven/Gradle 构建、Git 版本控制、JUnit/TestNG 单元测试、Sonar 代码质量检测）。</li><li>熟悉 Linux 系统基础操作，掌握 Docker、K8s 等容器化部署技术，了解 Nginx 配置与反向代理优化。</li><li>具备物联网（IoT）相关项目开发经验，有设备接入、数据中台、充电桩管理平台或智能硬件后端开发经验者优先。软技能：具备良好的需求拆解能力、跨团队沟通协调能力和团队协作精神；有较强的问题排查能力、责任心和抗压能力。</li></ol>', '1-3年', 'e46dae644c7d86390nR63ti6ElpS', '深圳 · 宝安区 · 沙井', '10-15K', 'Java, MySQL, 物联网经验, 大数据经验, ocpp协议, 新能源, 充电桩', 'APP后端开发工程师', 'https://www.zhipin.com/job_detail/e46dae644c7d86390nR63ti6ElpS.html', '带薪年假, 员工旅游, 团建聚餐, 零食下午茶, 绩效奖金, 节日福利, 五险一金');
INSERT INTO `jobs` VALUES (199, '快数', '计算机软件', '20-99人', '', '本科', '<p>1．熟悉金蝶苍穹开发，有实际金蝶苍穹项目开发经验，具备中级证书更佳2．具备金蝶云产品的生产制造、供应链、存货成本、财务领域基本知识3．有Spring、Mybatis、SpringBoot、SpringCloud等框架的相关开发经验4．熟练使用MySQL、Oracle等关系数据库，具备sql优化经验，熟悉Redis使用5. 熟练使用消息队列，主要是RocketMQ6．良好的java语言功底，熟悉常用的一些设计模式7．较强的学习意识和快速学习能力，能编写相关的设计文档、开发文档，具备良好的代码开发规范，8．清晰的表达能力和流畅的沟通能力，有良好的客户服务精神及团队合作能力</p>', '1-3年', '4e29b2a897a66da203By3t-8ElZT', '深圳 · 龙岗区 · 坂田', '6-11K', 'JVM, Java, 不接受居家办公, Elasticsearch, Docker, PostgreSQL, MySQL, Kafka, Redis, Dubbo, ERP开发经验', '苍穹开发', 'https://www.zhipin.com/job_detail/4e29b2a897a66da203By3t-8ElZT.html', '');
INSERT INTO `jobs` VALUES (200, '海拓时代', '游戏', '100-499人', 'A轮', '大专', '<p>1、3boss年以上的Java开发经验，1年及以上Java游戏服务端开发经验，精通JavaSE，集合等基础2、熟悉Java多线程、队列、反射及网络开发，熟悉面向对象编程思想和常用的设计模式3、对新兴技术有强烈的追求欲望，学习能力强(如NIO框架、RPC框架、微服务、分布式等)4、熟悉常用的linux系统命令及操作，有线上问题排查、JVM调优、内存调优经验者优先5、善于沟通，能很好的融入团队，有一定协调管理能力6、对于所使用的框架和技术，知其然并知其所以然者优先7、有Java游戏服务端开发经验者优先</p><p><strong>岗位职责</strong></p><p>(主程方向)：1、参与底层框架的讨论、优化、以及编写2、根据策划需求，独立完成相应的游戏玩法模块开发2．研究和探索创新的开发思路和前沿的技术，应用到团队与产品中3、喜欢网络游戏，有良好的团队意识，善于与他人沟通合作</p>', '1-3年', '94789086b73b501e1nZ_2Nm4ElpU', '深圳 · 宝安区 · 西乡', '18-30K', 'php, 游戏', 'JAVA开发工程师', 'https://www.zhipin.com/job_detail/94789086b73b501e1nZ_2Nm4ElpU.html', '节日福利, 全勤奖, 员工旅游, 节庆礼品, 五险一金, 零食下午茶, 绩效奖金, 夜间免费打车, 带薪年假, 星巴克驻场, 下午茶, 年终奖, 团建聚餐');
INSERT INTO `jobs` VALUES (201, '龙名集团', '互联网', '20-99人', '不需要融资', '大专', '<p><strong>岗位职责</strong></p><ol><li>独立负责模块研发（编码/自测等），输出高质量代码、自测和功能交付；</li><li>平台功能迭代：参与公司核⼼平台/系统的⽇常开发、功能迭代与技术优化，快速响应业务需求；</li><li>不断优化重构，持续提升代码质量和⽤户体验，主动参与代码审查，持续重构优化代码，提升系统可维护性与扩展性；</li><li>技术实践：关注并探索新技术在业务中的合理应用，解决技术难题。任职需求1.经验与背景：3-5年以上Java后端开发经验，计算机相关专业全日制本科及以上学历。</li><li>核⼼技术栈：精通java、spring、springBoot、mybatis-plus等框架。熟练掌握SpringBoot,SpringCloud,MyBatis/MyBatis-Plus等主流开发框架。有互联网Web项目开发工作经验；有DNS系统开发经验者优先熟悉Linux常用命令及基本运维操作。</li><li>协作能力：熟悉Javascript、vue等部分前端技术，具备良好的前后端协作能力。优秀的沟通能力和规范的文档习惯。</li><li>优先条件：有大型互联网平台、高并发系统开发经验者优先。有开源项目贡献、技术博客分享或可公开访问的优秀项目经验者优先。岗位</li></ol><p><strong>福利</strong></p><p>1.有市场竞争力的薪资 + 年终分红2.五险一金3.带薪年假 + 法定节假日 4.节日</p><p><strong>福利</strong></p><p>5.免费午餐</p>', '1-3年', '7f6afbdd85bfa7090nd409y7ElVX', '深圳 · 南山区 · 科技园', '10-15K', 'Java, Tomcat, 不接受居家办公, PostgreSQL, MySQL, MyBatis, 架构设计经验, Spring, 区块链经验', 'java工程师', 'https://www.zhipin.com/job_detail/7f6afbdd85bfa7090nd409y7ElVX.html', '团建聚餐, 餐补, 五险一金, 孝心津贴, 节假日加班费, 夜班补助, 零食下午茶, 带薪年假, 生日福利, 保底工资, 底薪加提成, 节日福利, 加班补助, 股票期权, 年终奖');
INSERT INTO `jobs` VALUES (202, '君璟科技', '计算机服务', '20-99人', '未融资', '本科', '<ol><li>负责跨境收单系统的开发与维护，参与系boss统架构设计、模块划分和业务需求分析；</li><li>实现高性能低延迟收单交易处理；</li><li>与产品经理、前端工程师和测试工程师紧密协作，确保开发进度和产品质量；</li><li>设计资金核对与自动对账系统，保障商户结算准确性；</li><li>对现有系统进行性能调优、故障排查，保障收单系统的安全性和稳定性6.编写高质量的代码，撰写相关技术文档和设计文档，进行代码审查和技术分享；</li><li>熟练阅读并对接主流支付渠道的API与技术文档，具备落地对接经验；</li></ol><p><strong>任职要求</strong></p><ol><li>计算机科学或相关专业本科及以上学历，2. 1-3年以上支付系统开发经验，其中2年专注收单/支付网关方向，；</li><li>熟练掌握Java编程语言，深入理解Spring、Spring Boot、MyBatis等主流框架的使用；</li><li>熟悉跨境收单行业相关业务流程，有与第三方支付、银行渠道对接的经验；</li><li>对分布式系统、微服务架构有深入理解，熟悉常用的缓存、消息队列、中间件（如Redis、Kafka等）；</li><li>熟悉数据库设计与开发，能进行MySQL或其他主流数据库的优化；</li><li>具备良好的问题分析和解决能力，能独立完成系统模块的开发和优化；</li><li>精通收单清分、拒付（Chargeback）处理、跨境资金归集逻辑，</li></ol>', '1-3年', '6665da3d1bfd354c03F73t25FFpY', '深圳 · 南山区 · 科技园', '10-15K', 'Java, Spring, MyBatis, Kafka, Redis, MySQL', 'Java开发工程师（跨境收单方向）', 'https://www.zhipin.com/job_detail/6665da3d1bfd354c03F73t25FFpY.html', '加班补助, 带薪年假, 法定节假日三薪, 五险一金, 零食下午茶');
INSERT INTO `jobs` VALUES (203, '巨迈科技', '智能硬件', '0-20人', 'A轮', '大专', '<p><strong>岗位职责</strong></p><p>负责JAVA服务器后端开发,负责公司产品HTML5页面的迭代工作. 能力要求:要求熟悉 JAVA, HTML5等开发工具 并且有1-2年相关工作经验要求思维灵活, 有效沟通(不招应届毕业生和实习 ).公司介绍:本公司主要做机器视觉方面的方案和产品研发主要产品有 网络摄像机, 婴儿看护器, 3d打印服务器, 运营商ip音箱 等待遇是1. 基本工资2. 根据公司利润情况发放额外年终奖金，3. 部分项目按产品销售，按件提奖金，按月结算有人带，快速成长</p>', '1-3年', '3dca090cf4383c091nx42d25GFtV', '深圳 · 龙华区 · 民治', '10-15K', '服务器端开发, 网络协议, Android', 'JAVA工程师', 'https://www.zhipin.com/job_detail/3dca090cf4383c091nx42d25GFtV.html', '五险一金, 年终奖, 节日福利, 零食下午茶');
INSERT INTO `jobs` VALUES (204, 'iTran', '计算机软件', '20-99人', '不需要融资', '本科', '<ol><li>负责软件后端开发，以及项目的管理及实施；</li><li>协助商务部门进行软件产品售前的系统演示、现场沟通交流；</li><li>协助技术团队进行项目实施阶段的开发工作；</li><li>英文可作为工作语言，可以海内外出差；</li><li>二年以上软件开发工作经验优先；</li><li>领导交办的其他工作事项；</li><li>海外留学/双一流大学优先。</li></ol>', '1-3年', 'd044fc5b6cf3e30c03V72tq8EFdR', '深圳 · 罗湖区 · 万象城', '10-15K', 'Java, 不接受居家办公, 团队管理经验, MySQL, Spring, Oracle', '中级java开发工程师', 'https://www.zhipin.com/job_detail/d044fc5b6cf3e30c03V72tq8EFdR.html', '定期体检, 绩效奖金, 员工旅游, 带薪年假, 生日福利, 五险一金, 团建聚餐, 年终奖, 节日福利, 交通补助, 零食下午茶, 每周零食柜, 意外险');
INSERT INTO `jobs` VALUES (205, '深圳市盼歌游戏', '互联网', '0-20人', '', '大专', '<p><strong>岗位职责</strong></p><ol><li>负责盼歌游戏Java相关项目的开发与维护工作。</li><li>参与系统设计，确保代码质量，与团队协作完成模块测试。</li><li>根据项目需求，进行功能设计和数据库优化。</li></ol><p><strong>任职要求</strong></p><ol><li>熟练运用Java语言，具备扎实的编程能力和良好的代码习惯。</li><li>熟悉常用的Java开发框架和技术栈。</li><li>具备良好的团队合作精神，能够高效沟通和解决技术问题。</li></ol>', '1-3年', '5399076541b42bce0nR82Nm-EldX', '深圳 · 龙华区 · 龙华', '15-16K', '不接受居家办公, Java, Spring, Netty, MySQL, Redis, 微服务经验', '中级java开发工程师', 'https://www.zhipin.com/job_detail/5399076541b42bce0nR82Nm-EldX.html', '');
INSERT INTO `jobs` VALUES (206, '宇威科技', '互联网', '100-499人', '未融资', '大专', '<p><strong>岗位职责</strong></p><ol><li>独立完成项目的系统分析、架构设计，负责核心模块开发，确保技术方案能够按计划要求，⾼质量的完成；</li><li>具有⼀定的技术架构思维，确保设计的技术⽅案、开发的代码有较高性能、质量保障、扩展性，前瞻性；</li><li>负责新产品的开发和迭代优化，进行软件设计和编码实现以及编码测试，确保安全、质量和性能。</li><li>可以进⾏项目的运维5.有一定的客户交流经验</li></ol><p><strong>任职资格</strong></p><ol><li>本科及以上学历，计算机及相关专业；</li><li>3年及以上JAVA开发的经验，熟悉spring等框架，熟悉各种设计模式；</li><li>熟练使用MySQL、mongodb等主流数据库，熟悉Redis、FastDFS、ES等常用技术；</li><li>熟练使用Apache/Nginx/Tomcat/Zookeeper/Kafka等应用服务器的配置和使用；</li><li>熟悉Linux开发环境、常用版本管理工具（SVN/Git等）,有shell开发能力者优先；</li><li>熟悉分布式系统的设计和应用，参与过电商平台、社交、大型分布式互联网产品、熟悉SOA架构的开发者优先</li></ol>', '1-3年', '56f68d007bd526fd0nF53t20F1tU', '深圳 · 龙岗区 · 大运', '10-15K', 'Java, 系统架构, Spring', 'Java高级开发工程师', 'https://www.zhipin.com/job_detail/56f68d007bd526fd0nF53t20F1tU.html', '员工旅游, 包吃, 每年团建, 节日福利, 带薪年假, 五险一金, 年终奖, 免费咖啡, 定期体检, 餐补, 技术分享, 零食下午茶');
INSERT INTO `jobs` VALUES (207, '指南针医疗', '医疗健康', '100-499人', '天使轮', '本科', '<p><strong>一、岗位职责</strong></p><p>​​​​核心开发​​负责企业级应用的后端架构设计与功能模块开发，使用Java语言实现高可用、可扩展的业务系统参与需求分析、数据库设计及接口开发，完成Spring Boot/Spring Cloud等框架的配置与优化编写单元测试，保障代码质量，参与系统部署、监控及性能调优（如高并发场景下的负载均衡设计）​​技术协作​​与前端团队协作完成全栈功能开发，确保接口规范（RESTful API）与数据交互效率配合运维团队实现容器化部署（Docker/Kubernetes），参与服务器维护及日志分析​​文档与创新​​撰写技术文档（设计文档、接口文档），推动团队知识沉淀跟踪前沿技术（如微服务、分布式存储），参与技术预研与创新方案落地​​</p><p><strong>二、任职要求</strong></p><p>​​​​基础能力​​本科及以上学历，计算机科学、软件工程或相关专业2年以上Java开发经验，熟悉JVM原理、多线程编程及常用设计模式​​技术栈要求​​​​核心框架​​：精通Spring Boot/Spring Cloud，熟练使用MyBatis/Hibernate​​数据库​​：关系型：MySQL/Oracle，掌握SQL优化、索引设计及事务管理NoSQL：熟悉Redis缓存机制、MongoDB文档存储​​中间件​​：熟悉消息队列（Kafka/RabbitMQ）、分布式锁（ZooKeeper）​​工具链​​：熟练使用Git/Maven，了解Linux系统操作及Shell脚本​​进阶能力（加分项）​​有高并发系统开发经验（如电商平台、金融系统）熟悉微服务架构（Dubbo/Spring Cloud Alibaba）及服务治理了解低代码平台（如JeecgBoot）、工作流引擎（Activiti/Flowable）具备容器化运维经验或Python脚本开发能力​​三、素质要求​​逻辑清晰，具备独立解决问题能力，能快速定位系统瓶颈良好的团队协作意识，适应敏捷开发流程，抗压能力强持续学习意愿，关注技术动态（如大模型集成、云原生架构）​​</p><p><strong>四、薪资福利</strong></p><p>​​五险一金、带薪年假、技术培训及晋升通道参与创新型项目机会（如区块链、智能物联网系统）</p>', '1-3年', 'bedd858f8c54649703d_29S6FVNY', '深圳 · 南山区 · 科技园', '8-12K', 'Java, 不接受居家办公, SpringCloud, Hadoop, Redis, SQL Server, Spring, ERP开发经验, 大数据经验, 微服务经验, MySQL, 架构设计经验, Oracle, Python', 'Java', 'https://www.zhipin.com/job_detail/bedd858f8c54649703d_29S6FVNY.html', '零食下午茶, 五险一金, 餐补, 股票期权, 年终奖, 加班补助, 员工旅游, 带薪年假');
INSERT INTO `jobs` VALUES (208, '玲琅科技', '电子商务', '100-499人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>参与项目需求分析与讨论，理解功能需求，设计系统架构，确保技术实现方案合理可行。</li><li>负责后台服务开发，主导或参与Java后台服务的开发工作，编写⾼质量的核⼼代码，确保功能按时交付。</li><li>与前端开发团队紧密配合，共同完成接口对接、功能联调，确保前后端功能⽆缝衔接。</li><li>编写符合规范的Java代码，注重代码的可读性和可维护性，同时进行代码优化，提升运行效率。</li><li>维护和优化现有系统，并对现有系统进⾏性能优化和稳定性维护，及时排查并解决技术问题，确保系统高效运行。</li><li>关注新技术动态，学习和了解Java及相关领域的最新技术动态，尤其是AI技术在开发中的应用，探索如何提升开发效率和产品质量。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历,计算机、软件工程或相关专业；</li><li>2-3 年 Java 开发经验，有电商行业、数据分析相关经验优先；</li><li>JAVA基础扎实，理解 IO、多线程、集合等基础及底层框架实现，并了解设计模式；</li><li>熟悉 Spring, Spring Boot 等主流框架；</li><li>熟悉 RESTful API 设计和实现；</li><li>熟练使用关系型数据库（如 MySQL等）和 NoSQL 数据库（如 Redis,MongoDB等）；</li><li>了解消息中间件（如 Kafka, RocketMQ, RabbitMQ）的使用。</li><li>有严密的逻辑思维能力，善于思考，具备良好的分析问题和解决问题的能力,良好的编码习惯；</li><li>有分布式系统、微服务架构相关项目经验者优先；</li><li>熟悉 Docker 和 Kubernetes 容器化技术；</li><li>具有良好的沟通能力，良好的团队合作精神，责任心强、勤奋敬业，执行力强。</li></ol>', '1-3年', 'ca5787520ad7dce50nFy2tq0EFtU', '深圳 · 龙岗区 · 坂田', '10-15K', 'Java, Docker, MySQL, Spring', 'Java后端开发工程师', 'https://www.zhipin.com/job_detail/ca5787520ad7dce50nFy2tq0EFtU.html', '交通补助, 团建聚餐, 节日福利, 底薪加提成, 五险一金, 带薪年假, 零食下午茶, 生日福利, 保底工资, 绩效奖金, 全勤奖');
INSERT INTO `jobs` VALUES (209, '深圳京科精密模型', '电子/半导体/集成电路', '20-99人', '未融资', '高中', '<ol><li>对手板3D图纸有良好的分析能力，能拆图纸，同时能够对机台操作熟悉。</li><li>懂精雕软件编程，从事手板编程两年以上经验。</li><li>年龄******，高中及以上学历4、能独立完成工作，速度快效率高，有足够的行业经验，了解相关产品工艺，刀路合理，有责任心，服从公司安排。</li></ol>', '1-3年', '2cf2cc83758810881nBz29q_FVdR', '深圳 · 宝安区 · 固戍', '8-13K', '手板, 数码编程, 编程, 手板编程, 数码, CNC数控', '手板编程', 'https://www.zhipin.com/job_detail/2cf2cc83758810881nBz29q_FVdR.html', '定期体检, 包吃, 员工旅游, 包住, 社保, 年终奖, 全勤奖');
INSERT INTO `jobs` VALUES (210, '瀚知智能', '互联网', '0-20人', '天使轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>参与Java相关系统的开发与维护，保障系统稳定运行；</li><li>根据项目需求完成模块设计、编码及测试任务；</li><li>配合团队完成技术方案讨论与实现，推动项目进度；</li></ol><p><strong>任职要求</strong></p><ol><li>熟悉Java语⾔及常⽤开发框架，具备良好的编码习惯；</li><li>了解软件开发流程，具备独⽴解决问题的能力；</li><li>具备良好的沟通能力与团队协作意识；</li><li>对技术有热情，有责任⼼，能适应一定强度的工作节奏。</li></ol>', '1-3年', 'cc4216e2a8096a720nV_3ty7GFFT', '深圳 · 南山区 · 科技园', '8-12K', 'Java, SpringCloud, MySQL, Spring', 'java开发工程师', 'https://www.zhipin.com/job_detail/cc4216e2a8096a720nV_3ty7GFFT.html', '交通补助, 团建聚餐, 节假日加班费, 股票期权, 补充医疗保险, 员工旅游, 带薪年假, 五险一金, 全勤奖, 节日福利, 绩效奖金');
INSERT INTO `jobs` VALUES (211, '华正联实业有限公司', '专用设备', '100-499人', '', '本科', '<p><strong>一、岗位职责</strong></p><ol><li>参与项目的需求分析，根据需求文档进行系统设计，确保设计满⾜业务需求和技术标准；</li><li>负责核⼼代码的编写，包括但不限于后端接口、业务逻辑、数据库操作等，确保代码质量⾼、可维护性好；</li><li>编写技术文档，如设计文档、接口⽂档、用户手册等；</li><li>负责核心代码的单元测试，确保代码的正确性和稳定性；</li><li>与团队成员紧密合作，共同完成项目开发和维护工作；</li><li>熟悉国产化平台、AI编程优先。</li></ol><p><strong>二、任职要求</strong></p><ol><li>至少3年以上的Java开发经验，具有扎实的Java编程基础，熟悉JVM原理、内存模型、垃圾回收等·熟悉常用的设计模式并对设计模式有一定见解；</li><li>熟练掌握springboot、springcloud全家桶，深入理解spring原理(包括但不限于IOC、DI、AOP)；</li><li>熟悉常用中间件并有一定的实战经验，如redis、rabbitmq、kafka、mongoDB，对原理有一定认识；</li><li>熟悉Docker+Kubernetes(K8s)项目部署，有一定实战经验；</li><li>有微服务架构经验，并对微服务有一定的理解。(包括但不限于服务网关、服务注册发现、服务负载、降级熔断等)·具备优秀的逻辑思维能力和问题解决能力，持续学习能力和技术钻研精神；</li><li>有良好的英语阅读能力。良好的沟通能力和团队合作精神，能适应快节奏的工作环境，自我驱动力强。</li></ol>', '3-5年', '5151338a0fc091520nBz2du9FlpR', '深圳 · 龙岗区 · 布吉', '12-20K', 'Java, SpringCloud, Spring, Kafka, JVM, MongoDB, MySQL, 架构设计经验, 微服务经验, 不接受居家办公', 'java开发工程师', 'https://www.zhipin.com/job_detail/5151338a0fc091520nBz2du9FlpR.html', '宿舍有空调, 法定节假日三薪, 免费工装, 带薪年假, 定期体检, 意外险, 高温补贴, 交通补助, 节日福利, 生日福利, 六险一金, 餐补, 补充医疗保险, 员工旅游');
INSERT INTO `jobs` VALUES (212, '深圳市领宽科技', '互联网', '20-99人', '', '本科', '<p>我们正在建设一套交易相关的业务管理与执行系统，涉及数据管理、交易控制、任务执行、权限审计、服务器资源调度等模块。现招聘一名全栈⼯程师，参与系统架构设计、Java 后端开发、Vue 前端开发、数据库设计、接口联调、性能优化和⼯程交付。该岗位不是单纯的页⾯或接口开发。我们希望你以后端能力为基础，具备独立完成前端页⾯开发的能力，并能使用 AI 编程工具提升效率，通过测试、调试和代码审查保障交付质量。</p><p><strong>岗位职责</strong></p><ol><li>负责 Java 后端服务开发、接口设计、业务实现、性能优化与问题排查。</li><li>负责 Vue 前端页面开发、交互实现、前后端联调与体验优化。</li><li>参与系统架构设计，包括模块划分、接口规范、数据库模型和可扩展性设计。</li><li>使用 AI 编程工具辅助完成代码生成、重构、调试、文档和单元测试。</li><li>参与需求评审、技术评审、代码评审，保障系统稳定性和可维护性。</li><li>配合产品、测试、运维完成版本交付、线上问题定位与修复。</li></ol><p><strong>岗位要求</strong></p><ol><li>具备 3年Java 后端和2年前端开发经验。</li><li>精通 Java 后端开发，熟悉 JDK21+特性、Spring Boot，有 Spring Cloud 或微服务经验优先。</li><li>熟悉 Vue 3、TypeScript，能够独立完成中后台页面开发、接口联调和基础部署。</li><li>熟悉 MySQL、Redis，具备基础表结构设计、SQL 编写、索引使用和事务处理能力。</li><li>了解消息队列、搜索服务、容器化、CI/CD、日志监控等，有实际经验优先。</li><li>具备一定系统设计能力，能够参与模块拆解、接口设计、数据库建模和技术方案讨论。</li><li>有 AI 编程工具使用经验，能对 AI 生成内容进行基本判断，代码审查保障代码质量。</li><li>熟悉单元测试、接口调试、SQL 优化和常见问题排查。</li><li>具备良好的业务理解、逻辑分析、沟通协作和自驱力。加分项1. 有高并发、高可用系统开发经验。</li><li>有金融、交易、量化、风控、订单系统、任务调度系统或复杂中后台系统经验。</li><li>有从 0 到 1 参与业务系统、技术架构或工程规范建设的经验。</li><li>有核心模块开发、技术方案设计或小团队协作经验。</li><li>有复杂系统性能优化、稳定性治理或线上问题排查经验。我们看重1. 后端能力扎实，前端能够独立落地。</li><li>有架构意识，能参与系统设计，而不是只完成单点功能。</li><li>能熟练使用 AI 工具，但不盲目信任 AI 输出。</li><li>能把需求拆成清晰、稳定、可维护的系统实现。</li><li>有自驱力，能在业务变化中持续提升工程质量。</li></ol>', '3-5年', '279d45363053b5ef0nF_0tm-EVZX', '深圳 · 南山区 · 深圳湾', '15-20K', 'Java, Spring, Kafka, Docker, MySQL, Spark, 架构设计经验, 区块链经验, 不接受居家办公', 'Java全栈工程师', 'https://www.zhipin.com/job_detail/279d45363053b5ef0nF_0tm-EVZX.html', '股票期权, 团建聚餐, 节日福利, 带薪年假, 补充医疗保险, 定期体检, 生日福利, 全勤奖, 保底工资, 零食下午茶, 法定节假日三薪, 员工旅游, 工龄奖, 五险一金, 意外险, 年终奖');
INSERT INTO `jobs` VALUES (213, '深圳招商永隆信息技术', '计算机软件', '100-499人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>根据项目要求，承担相关功能的开发工作并按计划完成任务目标。</li><li>配合系统分析人员相关的需求调研及分析工作。</li><li>完成项目相关功能程序设计及代码的编写。</li><li>完成对应功能模块的单元测试，联调等工作。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历；计算机、软件工程等相关专业，英语四级及以上。</li><li>熟练使用Java编程语言；掌握SpringCloud/SpringBoot等框架的使用。</li><li>熟悉MySQL、ORACLE、SQL Server等主流数据库；熟悉Linux命令和shell脚本的编写。</li><li>了解Docker等容器化平台的部署和维护，对Vue/JavaScript/HTML5/CSS3等Web前端技术有初步了解。</li><li>有银行软件开发项目经验优先</li></ol>', '3-5年', 'fdded309305f69ea03Bz3Nq1FlpQ', '深圳 · 龙岗区 · 平湖', '15-30K', 'Java, SpringCloud, Redis, Spring, Oracle', 'java开发工程师', 'https://www.zhipin.com/job_detail/fdded309305f69ea03Bz3Nq1FlpQ.html', '餐补, 节日福利, 交通补助, 年终奖, 定期体检, 生日福利, 通讯补贴, 节假日加班费, 绩效奖金, 五险一金, 带薪年假, 高温补贴, 补充医疗保险');
INSERT INTO `jobs` VALUES (214, '广州九雏科技有限公司', '计算机软件', '20-99人', '', '大专', '<p><strong>岗位职责</strong></p><ol><li>负责业务平台技术⽅案设计，代码编写和系统优化；</li><li>了解熟悉包括但不限于分布式架构、⾼并发处理、存储性能优化、⼀致性保障、租户隔离等相关技术；</li><li>解决平台中遇到的各种技术问题，打造安全、可靠、稳定、高效的平台。</li></ol><p><strong>岗位要求</strong></p><ol><li>Java基础扎实，熟悉主流框架和技术，如Spring、SpringBoot、Spring Cloud，Dubbo、CQRS等，有微服务架构设计经验；</li><li>熟悉分布式缓存、消息中间件、RPC框架、负载均衡、JVM原理等技术，掌握各类中间件使用，包括consul、mysql、redis、nginx、elasticsearch等；</li><li>掌握数据库优化技巧，常⽤数据结构、设计模式；</li><li>过往项目有做过智慧工程类的可以优先选择。</li></ol>', '3-5年', '108da81d518e4b000nJ739q7EFJY', '深圳 · 南山区 · 科技园', '11-16K', 'Java, SpringCloud, MyBatis, Spring, MySQL, Redis, 分布式经验, 微服务经验', 'Java开发工程师', 'https://www.zhipin.com/job_detail/108da81d518e4b000nJ739q7EFJY.html', '');
INSERT INTO `jobs` VALUES (215, '广州九霄云外文旅发展', '电子商务', '0-20人', '不需要融资', '本科', '<p>哨兵平台：工业监控告警、异常检测、设备安防、数据采集预警平台</p><p><strong>工作职责</strong></p><ol><li>负责仓储机器人调度平台开发⼯作，根据业务规格说明书，能够快速进⾏代码实现；</li><li>主动按时⾼质量完成需求开发和自测；</li><li>配合PM高质量完成各项开发任务，包括不限于需求评审，系统测试⽤例编写，代码评审与问题或工单定位修改等。</li><li>熟练运用各种问题排查方法，快速定位系统问题根因并修复；</li><li>输出并分享高质量的交付文档进行知识沉淀。</li></ol><p><strong>任职资格</strong></p><ol><li>全日制本科学历，计算机相关专业，3年及以上Java开发经验，JAVA基础扎实，熟练掌握io、多线程、集合等基础框架，熟悉JVM原理；</li><li>良好的团队合作能力，流畅的口头和书面表达能力，严谨的工作态度，有极客意识，求知欲强 ，思路活跃。</li><li>熟悉常用开源框架的原理和内部机制，如Spring Cloud等，能够熟练并合理使用；</li><li>熟悉数据库，redis、RPC等中间件，有良好的设计模式及实际落地能力；</li><li>自驱力强且有强烈的技术热情和钻研精神，热爱新技术；</li></ol>', '3-5年', 'd02e799608226df90nF829m_FlBV', '深圳 · 宝安区 · 西乡', '12-16K', 'Java, SpringCloud, MySQL, Redis, 微服务经验, 不接受居家办公, 数据采集预警, 工业监控告警, 哨兵平台', 'JAVA', 'https://www.zhipin.com/job_detail/d02e799608226df90nF829m_FlBV.html', '五险一金, 定期体检, 绩效奖金, 保底工资, 底薪加提成');
INSERT INTO `jobs` VALUES (216, '费滋', '互联网', '100-499人', '未融资', '本科', '<p><strong>岗位职责</strong></p><p>参与即时通讯平台核心模块的开发与维护负责功能模块的代码编写、单元测试与问题排查参与技术方案评审，学习并实践分布式系统设计配合团队完成需求开发与线上问题处理持续学习，逐步承担核心模块的设计与优化工作</p><p><strong>任职要求</strong></p><p>985/211 院校本科及以上学历，计算机相关专业毕业 3 年以内，有扎实的计算机基础熟悉 Java 核⼼，了解多线程、集合、IO 等基础知识熟悉 Spring Boot / MyBatis 等主流框架，有实际项⽬经验了解 MySQL、Redis 等常⽤存储系统熟练使用 AI 工具辅助开发，包括 AI 编码（如 Cursor、Claude Code）、AI 测试、AI 辅助调试等具备良好的编码习惯和代码规范意识对技术有热情，具备较强的学习能⼒与自驱力加分项：有即时通讯/消息系统相关项目经验优先有 Netty、NIO 网络编程经验优先有分布式系统相关课程或实践项目优先有开源项目贡献或技术博客优先ACM/ICPC 等算法竞赛获奖优先培养方向导师制： 资深架构师一对一指导AI 辅助开发： 团队全面拥抱 AI 工具，提升研发效能核心业务： 参与 IM 核心模块开发，快速成长技术视野： 接触高并发、大规模分布式系统实战晋升通道： 明确的技术晋升路径，表现优秀可快速晋升</p>', '3-5年', 'b001e07bab153b460nFz09u1EFdY', '深圳 · 南山区 · 科技园', '10-15K', 'Java', 'java工程师', 'https://www.zhipin.com/job_detail/b001e07bab153b460nFz09u1EFdY.html', '带薪年假, 生日福利, 零食下午茶, 节日福利, 绩效奖金, 定期体检, 五险一金');
INSERT INTO `jobs` VALUES (217, '零坐标', '互联网', '20-99人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>根据业务需求负责后端服务的需求分析、功能设计与业务编码开发，保障项目进度与交付质量。</li><li>熟练使用AI参与代码 Review，保障代码规范性、运行稳定性及性能合规。</li><li>负责自⾝开发模块的⾃测，配合测试完成联调测试，保障交付质量。</li><li>负责现有系统功能迭代、⽇常维护，快速定位并修复线上问题及缺陷。</li><li>熟练使用 AI 工具辅助⽇常开发，对接大模型接口，参与业务知识库搭建、简易 AI 工作流梳理与业务场景落地。</li></ol><p><strong>岗位要求</strong></p><ol><li>本科及以上学历，有金融支付、信贷业务背景优先；</li><li>5年以上java开发经验，Java 基础扎实，掌握 IO、多线程、集合等基础框架，了解 Java 虚拟机、缓存、消息等基础原理；</li><li>熟练掌握 Java /python编程及 IDEA 开发工具使用，熟悉 Linux 常用命令及项目部署流程；</li><li>能熟练使用 Claude、OpenAI Codex 等 AI 工具辅助代码编写、重构及问题排查；了解大模型基础对接，有业务知识库、AI 工作流相关实践经验优先；</li><li>具备良好的沟通协作能力，文档编写能力良好，勤奋好学，主动性强。没有AI实际项目开发经验，且对前沿AI没有深入研究深入接触的同学不用投递哈，以免浪费双方时间！</li></ol>', '3-5年', '1be191ffd4bc44180nB82t21ElZW', '深圳 · 南山区 · 科技园', '18-28K·13薪', 'Java, 不接受居家办公, 分布式经验, SpringCloud, MySQL, 后端开发, AI应用开发, 关注AI技术前沿', 'Java/AI应用开发工程师', 'https://www.zhipin.com/job_detail/1be191ffd4bc44180nB82t21ElZW.html', '零食下午茶, 保底工资, 交通补助, 节日福利, 带薪年假, 加班补助, 团建聚餐, 绩效奖金, 年终奖, 五险一金');
INSERT INTO `jobs` VALUES (218, '裕宁科技', '计算机软件', '100-499人', '未融资', '本科', '<ol><li>4年以上后端开发经验，熟练掌握 Java/Go/Python/Node.js 之一，本科及以上学历。</li><li>能独立完成服务部署：熟练使用 Docker、Docker Compose，了解 Kubernetes 基础操作，熟悉 Linux 及 CI/CD 自动化部署流程。</li><li>深入实践非对称加密传输：掌握 RSA/ECC 原理，有数字信封、JWT 签名、mTLS 等实际应用经验，能设计防窃听、防伪造的安全通信方案。</li><li>熟悉加密库与证书管理：能处理密钥轮换、私钥安全存储，防范中间人攻击、重放攻击，理解 HTTPS 与证书链验证。</li><li>熟练使用关系数据库（MySQL/PostgreSQL） 及至少一种 NoSQL 或消息队列，具备 SQL 调优能力。</li><li>具备系统集成与问题排查能力：能独立设计安全接口、编写技术文档，并排查线上性能/网络/内存等故障</li></ol>', '3-5年', '9760ba03184584fb03Z92Ny_GVBU', '深圳 · 福田区 · 车公庙', '11-14K', 'Java, 不接受居家办公, 微服务经验, MySQL, Spring, Oracle', 'java开发工程师', 'https://www.zhipin.com/job_detail/9760ba03184584fb03Z92Ny_GVBU.html', '节日福利, 加班补助, 带薪年假, 年终奖, 股票期权, 定期体检, 五险一金, 员工旅游, 零食下午茶');
INSERT INTO `jobs` VALUES (219, '沣利供应链有限公司', '电子商务', '100-499人', '未融资', '大专', '<p><strong>岗位职责</strong></p><ol><li>基于织信 Informat 平台，协助织信开发团队完成一期项目的开发与实施与运维，确保项目按时高质量落地。</li><li>深度对接各部门，精准拆解需求并转化为织信平台可落地的开发⽅案，独⽴完成表单设计、流程建模、数据关联、API 接口调⽤及第三方系统（飞书、企业微信、领星、亚马逊）集成。</li><li>运用⾼阶JavaScript编写自定义脚本、拓展组件与集成逻辑，突破平台原生能力限制，解决个性化复杂业务痛点、线上性能瓶颈与疑难BUG，保障系统高可用、高稳定运行。</li><li>负责项目全流程文档编制（需求文档、设计文档、测试报告、操作手册），完成内部知识沉淀与共享。</li><li>跟踪织信 Informat 平台迭代与 AI 低代码技术趋势，探索及实施 AI Agent 在业务中的落地场景，跟进低代码与AI技术趋势，基于MCP协议落地AI Agent多智能体协作场景，运用平台AI组件实现智能表单、智能审批、自动化业务分析等功能，优化现有系统与开发流程。</li><li>为内部用户提供织信 Informat 平台操作培训与技术支持，协助解决系统上线后的运维与迭代优化问题。</li><li>有使用JAVA语言开发大型ERP系统的全流程落地经验，熟悉了解spring全家桶。</li><li>熟悉服务器运维技术。</li></ol><p><strong>四、任职要求</strong></p><ol><li>技术能力： 精通高阶JavaScript开发，可独立编写复杂异步逻辑、自定义拓展组件、接口集成脚本；熟练掌握MySQL、SQL Server，具备数据表设计、索引优化、复杂SQL编写及大数据量性能调优能力；精通企业级API系统集成，熟悉第三方系统双向对接、异常重试、数据一致性处理。</li><li>项目经验：拥有 1-3 年低代码开发平台实操经验，至少成功交付过 1 个完整的中大型企业级低代码项目，具备项目全流程落地能力，有织信 Informat 平台开发项目经验者优先。</li><li>AI 基础：了解 AI Agent、大模型应用基础原理，熟悉MCP协议，能独立完成多智能体协作场景开发；有使用织信平台 AI 组件实现智能表单、智能审批等功能的经验者优先。</li><li>具备扎实的Java高级开发功底，熟练掌握SpringBoot、Spring MVC等主流框架，精通后端业务逻辑开发、接口开发、服务封装与代码优化，可独立完成低代码平台配套后端定制开发、复杂业务逻辑拓展及第三方服务对接（三）加分项 会Python代码，有Python开发经验 、熟悉xxx业务流程 、具备敏捷开发、DevOps 实施经验。</li></ol>', '3-5年', 'fdfb7bb8d3e58a820nFy2ty9FVVZ', '深圳 · 龙岗区 · 坂田', '15-20K·13薪', 'Java, C, C++, Python, C#, 不接受居家办公, ERP开发经验, 织信低代码全栈开发, 织信, 企业级低代码平台开发, 低代码开发工程师, 跨境电商低代码开发', '低代码开发工程师（织信 Informat+AI ）', 'https://www.zhipin.com/job_detail/fdfb7bb8d3e58a820nFy2ty9FVVZ.html', '零食下午茶, 有无线网, 团建聚餐, 年终奖, 节假日加班费, 节日福利, 全勤奖, 带薪年假, 五险一金, 保底工资, 绩效奖金, 员工旅游');
INSERT INTO `jobs` VALUES (220, '深圳市静格创新科技', '智能硬件/消费电子', '0-20人', '天使轮', '本科', '<ol><li>负责IoT云服务平台的设计、开发与维护；</li><li>实现设备接⼊、消息中间件、数据存储、权限管控等核⼼功能；</li><li>确保系统的⾼并发、高可用与⾼扩展性，支持大规模设备接入；</li><li>负责云服务架构优化与性能调优.</li></ol>', '3-5年', '580f7cae78920cda0nJ52d-0EFBX', '深圳 · 南山区 · 科技园', '10-15K', 'C++, Python, Spring, MySQL, 架构设计经验, 分布式经验, 微服务经验, 云计算经验, 大数据经验', '云服务平台工程师 / 主管', 'https://www.zhipin.com/job_detail/580f7cae78920cda0nJ52d-0EFBX.html', '');
INSERT INTO `jobs` VALUES (221, '乐事立信信息科技', '计算机硬件', '20-99人', '未融资', '本科', '<p>工作任务: 1 开发我们自己的智慧工地云平台; 提供给直接客户，代理商，政府方便查询了解设备的运行状况。2 做好与各个客户，政府平台的服务器对接。3 在设备运行基础上，根据客户要求，提供各项智能化报表和运用。技能要求:1 有独立开发物联网云平台经验。2 熟悉服务器的前后端开发。</p>', '3-5年', 'b9a56f9c482f60231HF53t-0E1JQ', '深圳 · 龙华区 · 龙华', '15-30K', 'Java, 不接受居家办公, SpringCloud, MySQL, PHP', '物联网平台开发工程师', 'https://www.zhipin.com/job_detail/b9a56f9c482f60231HF53t-0E1JQ.html', '');
INSERT INTO `jobs` VALUES (222, '深圳市铭盛缘互联...', '计算机软件', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责开发公司的制造业MES、WMS、QMS、APS、TPM、CRM、SRM、财务、供应链、HR等软件系统；</li><li>负责后端Spring Cloud微服务+VUE3，TypeScript前端.3 熟练应用用AI开发代码。有开发效率考核。</li><li>优化现有系统的性能，提高系统的稳定性和扩展性；</li><li>完善改进低代码平台的功能、性能问题；</li><li>解决产品开发中遇到的技术难点问题；</li><li>负责系统部署、发布上线工作；</li></ol><p><strong>任职要求</strong></p><ol><li>本产品属于制造企业⼤型智能制造相关产品，需要对业务有深⼊了解，主动学习能⼒、理解能力比较强。</li><li>主⼒开发过MES、WMS、QMS、PLM、APS，以及ERP财务、供应链等系统的优先。有金蝶或用友研发项目经验的优先考虑。</li><li>熟练掌握Spring Cloud、MyBatis等开发框架， 并要求有前端VUE3，TypeScript实际开发经验。能独立完成全栈开发工作。</li><li>有良好的团队合作精神，沟通良好。能独立解决问题，有创新精神。对产品项目有责任心，能承担较高的压力,可接受项目忙时加班。</li><li>部分项目需要到客户现场出差。岗位</li></ol><p><strong>福利</strong></p><ol><li>公司正处于业务快速增长的突破期，急需立志于打造中国更先进的MES系统的有志之士加入；</li><li>有能力、负责任者，有更好的晋升机会；</li><li>有突出贡献者，可以获得丰厚年底奖金，以及股权激励；</li></ol>', '3-5年', '2d0a6d3f9de406010nR_0ti7FVdT', '深圳 · 龙华区 · 民治', '10-15K', 'MES开发经验, Java, SpringCloud, MySQL, MyBatis, Dubbo', 'JAVA中级全栈开发工程师', 'https://www.zhipin.com/job_detail/2d0a6d3f9de406010nR_0ti7FVdT.html', '节日福利, 团建聚餐, 零食下午茶, 五险一金');
INSERT INTO `jobs` VALUES (223, '小蓝快充', '储能', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责光储充一体化SaaS平台核心模块开发，包括能源管理EMS、设备监控、充电运营、计费分账、运维工单、数据大屏、⽤户管理等功能设计与实现。</li><li>负责光伏、储能PCS/BMS、充电桩、智能电表等设备接⼊，基于MQTT、Modbus、OCPP、IEC61850、DL/T645等协议完成数据⾤集、远程控制与协议适配。</li><li>负责高并发、高可⽤分布式系统架构设计与优化，保障平台稳定运行与海量设备数据实时处理。</li><li>负责时序数据库、关系型数据库、消息队列、缓存等技术方案设计与落地，支撑削峰填谷、负荷预测、智能调度、电力交易、对账结算等核心业务。</li><li>参与第三方系统对接，包括电网调度、支付、发票、企业能源管理、虚拟电厂平台等系统集成。</li><li>负责代码质量管控、技术文档编写、性能优化、线上问题排查与系统迭代升级。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机、软件工程、自动化、电气工程、新能源等相关专业，3年及以上后端开发经验。</li><li>精通 Java/Python/Go 至少一门主流语言，熟练使用 Spring Boot/Spring Cloud、Django、Gin 等开发框架。</li><li>熟悉微服务、分布式系统设计，掌握 MySQL、Redis、Kafka、RabbitMQ、Elasticsearch，有TDengine/InfluxDB/TimescaleDB时序数据库使用经验优先。</li><li>熟悉光储充行业基础知识，了解光伏、储能、充电桩、EMS能源管理系统原理，有能源物联网、充电桩平台、储能云平台开发经验优先。</li><li>熟悉工业通信协议，具备设备接入、数据采集、远程控制开发经验，能够独立完成设备协议对接与调试。</li><li>具备良好的代码习惯、架构思维与问题排查能力，能够独立承担模块设计与开发工作。</li><li>工作积极主动，责任心强，具备良好的沟通协作能力与抗压能力，热爱新能源行业。加分项1. 有虚拟电厂、需求响应、AI负荷预测、光储充协同调度项目经验。</li><li>熟悉 Docker/K8s 云原生部署、CI/CD、DevOps 流程。</li><li>掌握 Vue/React 前端技术，可独立完成全栈开发。</li><li>熟悉电力行业标准、网络安全等保2.0要求。</li><li>有大型SaaS平台、高并发工业物联网平台架构设计经验。</li></ol>', '3-5年', 'ef7682e86ed900340nV90tu6GFtT', '深圳 · 光明区 · 光明', '15-22K·13薪', 'Java, C++, Python, Spring, SpringCloud, MySQL, Redis, SQL Server', '光储充SaaS平台开发工程师', 'https://www.zhipin.com/job_detail/ef7682e86ed900340nV90tu6GFtT.html', '带薪年假, 年终奖, 节日福利, 员工旅游, 定期体检, 全勤奖, 五险一金, 股票期权, 加班补助, 交通补助, 通讯补贴');
INSERT INTO `jobs` VALUES (224, '深圳磅旗', '自动化设备', '100-499人', 'B轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责 lds 调度系统的开发，模板规划、任务调度、交通管制、硬件交互，系统仿真、监控报警等模块，并持续对调度系统进⾏优化；</li><li>负责调度系统与上下层系统的接口定义和实现；</li><li>负责调度系统与外围设备对接，如卷帘门、电梯、提升机，输送线，按钮，呼叫器等；</li><li>负责调度系统需求分析、设计说明等⽂档撰写。</li></ol><p><strong>任职要求</strong></p><ol><li>统招本科及以上学历，计算机、数学、⾃动化、通信工程等相关专业；</li><li>具有 3 年以上 java 系统开发经验,wms wcs 智能工⼚自动化系统,开发经验优先；</li><li>熟练掌握主流SSM框架,Springboot,restful风格webservice接口开发 4. 熟悉Modbus、TCP/IP，SOCKET 等常用通讯协议；</li></ol>', '3-5年', 'c506a09afb8ab1390nB92d25F1RY', '深圳 · 罗湖区 · 水贝', '17-23K', 'Java, Spring, SpringCloud, MySQL, 智能机器人, WMS系统, WCS系统', '资深java开发工程师（调度系统开发经验）', 'https://www.zhipin.com/job_detail/c506a09afb8ab1390nB92d25F1RY.html', '生日福利, 保底工资, 底薪加提成, 员工旅游, 节日福利, 团建聚餐, 股票期权, 带薪年假, 五险一金, 绩效奖金, 年终奖, 定期体检, 零食下午茶');
INSERT INTO `jobs` VALUES (225, '深圳市五虫科技', '计算机软件', '20-99人', '天使轮', '本科', '<p><strong>岗位职责</strong></p><p>1、主要负责公boss司相关业务系统功能模块的开发工作2、参与需求分析、系统设计、集成测试以及运维工作3、基于Spring、SpringBoot完成后端服务开发工作，编写高质量的代码，确保系统的稳定性和可扩展⾏4、参与解决项⽬开发过程中的技术难点,持续优化代码质量；</p><p><strong>岗位要求</strong></p><ol><li>本科及以上学历，计算机，软件⼯程等相关专业。</li><li>3年以上Java后端开发经验，熟练掌握Java基础、集合、多线程、10、反射等核心知识。</li><li>熟练使用SpringBoot框架进⾏项目开发，理解 Spring、SpringMVC核心原理，熟悉常用starter 与自动配置。</li><li>熟悉Maven项目构建、Git版本控制制，具备良好的编码规范与工程化意识。</li><li>熟练掌握MySQL常用SQL编写，存储过程，触发器，事务与锁机制。</li><li>熟悉Redis缓存、RabbitlMQ/Kafka消息队列等中间件7、了解Linux常用命令、Docker容器化部署8、良好的问题排查能力、沟通能力与团队协作意识，能独立承担模块开发。</li><li>工作严谨负责，具备良好的业务理解能力与需求拆解能力，能独立完成需求到代码的实现。</li><li>熟悉Golang语言及有相关开发经验的优先考虑。</li></ol>', '3-5年', '1a1495be4d4171fe0nJ62tq9FVNS', '深圳 · 龙华区 · 民治', '11-15K', 'Java, Spring, MySQL, 不接受居家办公', 'java中级开发工程师', 'https://www.zhipin.com/job_detail/1a1495be4d4171fe0nJ62tq9FVNS.html', '五险一金');
INSERT INTO `jobs` VALUES (226, '领锋创智', '云计算', '0-20人', '不需要融资', '大专', '<p><strong>一、岗位职责</strong></p><ol><li>设计和开发高质量的Java应用程序，确保系统的高可⽤性和可扩展性。</li><li>领导技术⽅案设计，进⾏关键技术决策和架构优化。</li><li>解决复杂技术问题，提升团队整体技术水平。</li><li>负责新技术研究和技术预研，推动技术创新和工程效率提升。</li><li>参与项⽬规划和需求分析，与产品经理和项目经理紧密合作，确保系统迭代目标的实现。</li></ol><p><strong>二、任职要求</strong></p><ol><li>技术能力：5年+ Java开发经验，精通JVM调优、多线程、网络编程及分布式系统设计；深度掌握Spring生态（Spring Boot/Cloud/MyBatis），熟悉RPC框架（Dubbo/gRPC）；熟练使用MySQL（分库分表/性能优化）、Redis（高可用集群）、RocketMQ等中间件；具备大型电商系统（交易/仓储/物流模块）或供应链中台项目实战经验。</li><li>架构能力：有主导过至少1个复杂系统架构设计经验，熟悉DDD与微服务拆分；熟悉容器化技术（Docker/K8s）及CI/CD流水线设计。3.</li></ol><p><strong>综合素质</strong></p><p>大专及以上学历，代码规范严格（冗余率低/可维护性强），技术文档撰写能力优秀；具备技术领导力，抗压能力强，对技术有极致追求。4.优先条件有跨境电商系统开发经验，熟悉亚马逊/Shopify API集成或国内电商SaaS ERP对接（如领星/易仓）；有高并发场景实战经验；熟悉前端技术栈（React/Vue），可独立完成全栈模块开发。</p>', '3-5年', '9b62e3a30b0bf89c0nV_3Ny0ElJU', '深圳 · 宝安区 · 西乡', '15-24K·13薪', 'JVM, Java, 团队管理经验, 分布式经验, PostgreSQL, SpringCloud, Kafka, Redis, 接受居家办公, Spring, ERP开发经验, 微服务经验, MySQL, MyBatis, 架构设计经验, Oracle', '中/高级Java开发工程师', 'https://www.zhipin.com/job_detail/9b62e3a30b0bf89c0nV_3Ny0ElJU.html', '团建聚餐, 年终奖, 五险一金, 餐补, 交通补助, 带薪年假');
INSERT INTO `jobs` VALUES (227, '谷从', '计算机软件', '20-99人', '不需要融资', '大专', '<p>负责公司iaa业务线公司做iaa工具app业务，必须有相关业务经验；技术栈要求：spring全家桶；有ai开发经验</p>', '3-5年', '8be26dd8c2c075e00nF609m8FlVR', '深圳 · 南山区 · 科技园', '15-30K', 'Java, Spring, SpringCloud, MySQL, 搜索/推荐/广告经验', 'Java开发-iaa工具', 'https://www.zhipin.com/job_detail/8be26dd8c2c075e00nF609m8FlVR.html', '团建聚餐, 员工旅游, 生日福利, 五险一金, 绩效奖金, 零食下午茶, 带薪年假, 餐补, 补充医疗保险, 定期体检, 节日福利, 意外险');
INSERT INTO `jobs` VALUES (228, '广州三辰', '互联网', '20-99人', '', '大专', '<ol><li>3年以上经验，大专学历及以上；</li><li>熟练掌握Spring、SpringBoot、SpringCloud等常用开发框架，熟悉常用的设计模式；</li><li>熟练使用MySQL或Oracle数据库，能够进⾏SQL优化和性能分析；</li><li>熟悉Linux系统，掌握Shell脚本开发，了解CSS相关知识，熟悉常⽤中间件如Redis、Kafka等；</li><li>有良好沟通理解能⼒，有团队协作精神，能承受一定工作压⼒。</li></ol>', '3-5年', 'b32a64855ed7c5df0nZ72N27E1JS', '深圳 · 龙岗区 · 大运', '9-13K', 'Java, SpringCloud, MySQL', 'Java工程师', 'https://www.zhipin.com/job_detail/b32a64855ed7c5df0nZ72N27E1JS.html', '');
INSERT INTO `jobs` VALUES (229, '合肥零次方机器人', '人工智能', '100-499人', '天使轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责前置仓具身智能平台后端架构设计与研发，支撑具身智能在智慧零售场景的落地</li><li>设计并实现SaaS多租户架构，包括租户隔离、权限管理等通用平台能⼒，⽀撑不同客户的个性化配置需求</li><li>对接WES系统及第三⽅仓储服务，设计标准化接口协议，保障库存数据一致性与业务指令可靠触达</li><li>构建订单履约状态机，管理订单生命周期（待分配、拣货中、待出库、已完成、异常），实现异常订单⾃动重试与人工介入机制</li><li>保障代码质量与系统稳定性，协助排查线上性能瓶颈</li><li>紧密协同项目交付，与产品、测试及架构师配合，确保版本按期闭环</li></ol><p><strong>任职要求</strong></p><ol><li>基础背景 - 本科及以上学历，计算机相关专业 - 3年以上后端开发经验 - 具备SaaS平台开发经验，熟悉多租户架构、租户隔离、权限体系设计 - 了解WES/WMS系统业务逻辑</li><li>Java深度 - 扎实的Java基础，深入理解IO模型（BIO/NIO/AIO）、多线程并发编程、JVM调优 - 熟练掌握Spring Boot、Spring Cloud微服务组件，对其核心原理有一定了解 - 熟悉分布式,微服务架构并具备相关实际项目经验</li><li>通信与协议 - 熟悉TCP/IP、HTTP、WebSocket、gRPC - 对Netty有深入理解及实战经验者优先</li><li>存储与中间件 - 熟练使用MySQL、Redis，具备优秀的数据库建模与SQL调优能力 - 熟悉消息中间件（Kafka/RocketMQ），对其持久化机制和可靠性传输有实战经验 - 熟悉对象存储S3协议，有MinIO或国产分布式存储集成经验者优先</li></ol><p><strong>综合素质</strong></p><p>- 具备极强的逻辑思维与业务抽象能力，能从仓储复杂场景中提炼通用平台能力 - 团队协作精神强，对具身智能、仓储自动化等前沿技术有探索欲</p>', '3-5年', '57b4b1bd4fa63b2e0nd_3t61FlJZ', '深圳 · 南山区 · 科技园', '15-30K·14薪', 'Java, 大数据经验, 不接受居家办公, Docker, 微服务经验, SpringCloud, MySQL, Redis, 云计算经验, SQL Server, 架构设计经验, Spring', '后端开发工程师', 'https://www.zhipin.com/job_detail/57b4b1bd4fa63b2e0nd_3t61FlJZ.html', '员工旅游, 股票期权, 加班补助, 团建聚餐, 节假日加班费, 节日福利, 工龄奖, 高温补贴, 定期体检, 年终奖, 生日福利, 带薪年假, 零食下午茶, 夜班补助, 免费工装, 五险一金');
INSERT INTO `jobs` VALUES (230, '一道', '计算机软件', '20-99人', '不需要融资', '大专', '<p>岗位boss</p><p><strong>职责</strong></p><p>一、 负责产品后端的部分工程设计，部分架构设计以及开发工作；二、 研究业界新技术及其应⽤，解决创新研发过程中的关键问题和技术难点；三、 根据项⽬任务计划按时完成软件编码和单元测试⼯作，按照开发流程编写相应模块的设计文档；四、 与产品经理、测试工程师、其他团队沟通合作，确保产品研发⼯作的质量和进度；协调或指导团队里其他开发人员工作，负责项目开发组的日常管理工作；五、 熟悉设计模式，熟练掌握面向对象编程和事件驱动编程风格；六、 有热情，酷爱技术，有良好的计划、沟通组织协调能力、语言表达能力；较强的逻辑分析能力和应变能力；良好的团队合作精神。七、 领导安排的其它事务。</p><p><strong>任职要求</strong></p><p>一、 全日制大专以上学历，计算机相关专业；二、 3年以上开发工作经验；三、 做事积极主动、认真负责，有良好的沟通能力。自学能力强，有团队精神；四、 扎实的JAVA基础，清晰的面向对象的编程思想；五、 熟练掌握常用的数据结构/算法；六、 掌握常用的JAVA开源框架，Spring boot,,MyBatis,Netty,Spring cloud等；七、 掌握使用PostgreSql,熟悉SQL优化方法,熟悉redis、mongodb;八、 能独立开发web页面,熟练使用html,javascript,vue.js;九、 具备技术文档编写能力;十、 具备需求分析能力,能独立完成需求功能设计工作；十一、 具备独立分析解决问题的能力。</p><p><strong>福利</strong></p><p>及其他：1.成长支持：定制化培训计划（内部技术分享会、外部培训报销）；双通道晋升机制（管理岗 / 技术专家岗），优秀员工可获得期权激励；2.</p><p><strong>福利</strong></p><p>保障：六险一金（补充商业保险）、带薪年假、出差补贴、年度体检；节日</p><p><strong>福利</strong></p><p>、生日会、团队旅游、下午茶等；工作环境：开放式办公空间、扁平化管理文化。</p>', '3-5年', '85231e24c039e07c031-3ti-FFNQ', '深圳 · 龙岗区 · 坂田', '12-18K', 'MES开发经验, Java, PostgreSQL, SpringCloud, MySQL, MongoDB, Spring', '中高级Java工程师', 'https://www.zhipin.com/job_detail/85231e24c039e07c031-3ti-FFNQ.html', '带薪年假, 生日福利, 年终奖, 员工旅游, 团建聚餐, 定期体检, 五险一金, 绩效奖金, 交通补助, 节日福利, 零食下午茶, 通讯补贴, 加班补助, 股票期权');
INSERT INTO `jobs` VALUES (231, '深圳爱真牛人工智...', '培训/辅导机构', '20-99人', '未融资', '本科', '<p><strong>一、岗位职责</strong></p><ol><li>架构治理与标准化建设主导技术规范制定与落地，包括微服务开发标准（代码规范、API设计、日志采集）、环境管控策略（开发/测试/生产分级隔离）、CI/CD流程（⾃动化构建+镜像管理+灰度发布）；建⽴技术债务台账，制定遗留系统重构路线，定期评审核⼼模块性能（响应时长、SQL执行效率、缓存命中率等）；推动工具链建设（如⾃动化测试覆盖率统计、Sonar质量卡点），减少低级缺陷，保障代码质量。</li><li>核心系统技术攻坚核心技术代码开发，负责高可用架构设计，主导关键模块的技术选型、容量规划（全链路压测、弹性扩缩容机制）、灾备方案（熔断降级、限流预案）；解决海量请求下的性能瓶颈（如分布式锁优化、慢查询治理、JVM参数调优），保障核心服务SLA（可用性≥99.95%）；制定紧急Hotfix处理流程，平衡线上问题修复与常规迭代进度，确保关键问题MTTR<1小时。</li><li>研发过程管理把控版本全生命周期（需求评审→工时评估→开发→测试→上线），设计风险预警模型（基于复杂度/历史缺陷率评估延期概率）；建立技术债务台账，制定遗留系统重构路线，定期评审核心模块性能指标。</li><li>团队技术赋能与管理建立技术内训机制（Code Review双周会、故障复盘会），提升团队代码质量意识与问题排查能力；负责5人以上团队日常监督、项目进展跟进及问题处理，具备多项目资源协调能力（同时推进≥2个中型及以上项目）；高效执行领导任务：制定详细工作计划与执行方案，明确任务目标、关键节点及责任人，保持密切沟通与及时反馈，确保任务高质量完成。</li></ol><p><strong>二、招聘要求</strong></p><ol><li>学历要求985/211/双一流院校统招本科及以上（能力突出者可放宽），计算机相关专业。</li><li>技能要求3年以上Java核心技术代码开发经验，2年以上Spring Cloud微服务架构设计经验；熟练掌握Java语言，熟悉JVM原理、并发编程、集合框架。熟悉敏捷开发（Scrum/Kanban），熟悉Nacos/Sentinel/Gateway等组件，主导过复杂系统性能调优（如日均百万订单系统）；熟练使用Spring Boot、Spring Cloud或Spring Cloud Alibaba微服务框架。熟悉MySQL高可用架构（主从同步、读写分离、分库分表方案）、CI/CD工具链（Jenkins/K8s/ArgoCD）；熟悉Redis（缓存、分布式锁、消息队列等场景）。熟悉RESTful API设计规范，了解API安全（JWT/OAuth2、防重放、限流）。主导过多个小程序项目并完成核心代码开发者优先。</li><li>管理能力2年以上技术团队管理经验，成功带过3人及以上技术小组，具备从0到1搭建项目、搭建团队的实战经验；掌握研发效能优化方法（如通过自动化提升测试覆盖率至70%+，降低重复缺陷率）；具备创业风险精神，能有效调动团队成员的积极性与凝聚力。</li><li>结果导向在有限资源下优先解决A类问题（如线上故障导致营收损失）；擅长利用有限资源将每项任务产生与预期相符的结果；具备系统性思维，能将零散问题抽象为标准流程。三、加分项熟悉小程序生态及微信支付接入全流程；有技术团队从0到1搭建经验。</li></ol>', '3-5年', '5c8ec47e09d2acaf0nJ739u0FVVT', '深圳 · 南山区 · 科技园', '9-12K', 'Java, Spring, SpringCloud, Kafka, Nginx, Elasticsearch, MySQL, Redis, MongoDB, PostgreSQL, 团队管理经验, 架构设计经验, 分布式经验, 微服务经验, 云计算经验, 不接受居家办公', 'Java技术经理', 'https://www.zhipin.com/job_detail/5c8ec47e09d2acaf0nJ739u0FVVT.html', '生日福利, 交通补助, 通讯补贴, 带薪年假, 底薪加提成, 年终奖, 绩效奖金, 餐补, 全勤奖, 有无线网, 保底工资, 节日福利, 股票期权, 五险一金');
INSERT INTO `jobs` VALUES (232, '港大前海智交研究院', '非营利组织', '20-99人', '未融资', '本科', '<p>‌</p><p><strong>岗位职责</strong></p><ol><li>负责公司核心业务boss产品的技术路线设计和系统研发工作；</li><li>负责交付项目的系统研发和技术支持⼯作；</li><li>维护和升级现有软件产品，快速定位并修复现有软件缺陷；</li><li>配合项⽬经理完成相关任务⽬标。新技术攻坚、引进与架构设计；</li></ol><p><strong>任职要求</strong></p><ol><li>统招本科及以上学历，计算机相关专业，3-5年以上Java开发经验；</li><li>有智慧园区、智慧仓储、智慧停车系统相关工作经验优先；有GIS/BIM开发经验优先；</li><li>精通JAVA语言，良好的OOD、OOP基本功和代码洁癖，有⼀定的前端基础：Vue；</li><li>JAVA开发基础扎实：掌握常用的设计模式；精通JVM，包括内存模型、类加载机制以及性能优化；</li><li>精通运用JAVA核心编程技术，熟悉多线程，网络，接口编程， 网络编程或数据库编程；</li><li>熟悉SpringCloud、Mybatis等主流框架，对分布式系统、微服务架构微、容器化技术、大数据处理等相关技术有深入了解；</li><li>熟悉掌握RabbitMQ、Zookeeper、Kafka、Netty、Docker等流行开源产品；</li><li>熟悉关系型数据库使用和设计，MySQL优先；</li><li>思路清晰，乐观皮实，有团队合作精神，善于总结和分享。</li></ol>', '3-5年', 'dcf8d7b7c95127960nR92Ni7GVJS', '深圳 · 南山区 · 前海', '15-25K', '', '后台开发工程师', 'https://www.zhipin.com/job_detail/dcf8d7b7c95127960nR92Ni7GVJS.html', '团建聚餐, 餐补, 定期体检, 绩效奖金, 五险一金, 带薪年假, 补充医疗保险, 年终奖');
INSERT INTO `jobs` VALUES (233, '知律科技', '企业服务', '20-99人', '天使轮', '本科', '<p><strong>一、岗位职责</strong></p><ol><li>负责公司SaaS平台（基于SaaS的行业级一体化管理软件，融合了OA、CRM、HRM、项目管理、财务、团队协作、电商等功能）的开发与优化；</li><li>根据产品及项目的开发进度和任务，按时按量保质完成项目编码，并根据需要及时修改、完善模块功能；</li><li>基于高并发、高可用对软件平台进行架构升级优化。</li></ol><p><strong>二、职位要求</strong></p><ol><li>全日制重点大学（985、211）本科毕业，计算机或其它相关专业；</li><li>扎实的JAVA编程基础， 熟悉各种开源的框架如SSM、Spring Cloud、Spring Boot等；</li><li>熟练使用MySQL数据库， 掌握基本的SQL优化技巧；</li><li>有系统高并发、高可用的架构设计及实战经验，熟悉分步式、微服务架构；</li><li>参与过大中型工作流平台或引擎或者CRM、OA等企业管理系统相关项目者优先；</li><li>强烈的责任心和使命感，能吃苦，善于沟通，学习能力和逻辑思维能力强，能承受较大的压力和挑战。</li></ol><p><strong>三、薪资福利</strong></p><p>1、薪资待遇：面议，优秀者薪资不受此招聘启事限制；2、</p><p><strong>福利待遇</strong></p><ol><li>培训体系：新员工入职培训+行业知识培训等；</li><li>晋升空间：优秀者随时晋升，上升空间无限；</li><li>符合条件的员工，可享受公司面对骨干成员的股权激励计划。四、工作环境公司位于南山科技园“创维半导体设计大厦 西座”，新址紧邻地铁1号线高新园站（370米距离）和9号线高新南站（495米），为员工和访客提供了便捷的公共交通选择。自驾方面，只需10分钟即可直达深南大道，30分钟即可通达宝安机场，出行非常方便。五、公司网站公司官网：www.kinglex.cn</li></ol>', '3-5年', '5aea28cdd1d26dea1H1z3d29Flo~', '深圳 · 南山区 · 科技园', '15-22K', '企业软件', '高级Java软件工程师', 'https://www.zhipin.com/job_detail/5aea28cdd1d26dea1H1z3d29Flo~.html', '五险一金, 员工旅游, 带薪年假, 节日福利, 股票期权');
INSERT INTO `jobs` VALUES (234, '渊联技术', '计算机服务', '100-499人', 'A轮', '本科', '<p>此岗位上班地址在湖南永州办事处，介意勿投！！！</p><p><strong>岗位职责</strong></p><ol><li>负责公司AI代码产线的建设与应用程序的开发调试；</li><li>参与公司产品的功能规划、需求分析、模块设计、技术实现和用户体验；</li><li>根据项目进度要求，完成所负责模块的设计、编码、单元测试/系统联调，及问题解决；</li><li>根据开发规范与流程独立完成模块的设计、编码、测试以及相关⽂档；</li><li>参与公司产品的架构优化，性能优化，并辅助其他模块进⾏技术实现；</li><li>协助并完成其他各类技术开发任务。</li></ol><p><strong>职位要求</strong></p><ol><li>全⽇制统招本科以上学历，计算机相关专业；</li><li>3年+ Java开发经验，精通Spring Boot/Spring MVC/Spring Security框架；</li><li>深入理解微服务架构，熟悉Spring Cloud/Nacos/Gateway等组件；</li><li>熟练掌握MySQL设计与优化，熟悉Mybatis/Mybatis plus框架使用；</li><li>熟练使⽤Redis实现分布式缓存及锁机制；</li><li>熟练掌握至少一种数据库Oracle、MySQL,有数据库优化经历者优先；</li><li>有容器化部署经验（Docker/K8s）；</li><li>熟悉Docker应用，有Marathon+Mesos或Kubernetes等容器管理工具经验。- 软性素质： - 具备复杂业务抽象能力，能独立完成架构设计文档； - 重视代码质量（Sonar规范），熟悉常见设计模式； - 强责任心和团队协作精神，适应敏捷开发；</li><li>熟悉主流AI设计工具，具有大模型使用经验。- 加分项目： - 有MES、ERP等制造行业相关软件开发经验优先考虑； - 能够使用AI编程工具进行原型开发优先考虑。</li></ol>', '3-5年', 'e1fdb8cc9ec2ed6e0nBy2di7GFpW', '深圳 · 南山区 · 科技园', '8-13K', 'Java, Spring, SpringCloud, Docker, MySQL, Redis, Oracle, ERP开发经验, MES开发经验', 'Java开发工程师（AI编程方向）', 'https://www.zhipin.com/job_detail/e1fdb8cc9ec2ed6e0nBy2di7GFpW.html', '带薪年假, 团建聚餐, 股票期权, 五险一金, 保底工资, 绩效奖金, 年终奖, 底薪加提成');
INSERT INTO `jobs` VALUES (235, '康索特软件', '计算机软件', '20-99人', '未融资', '本科', '<p>【</p><p><strong>岗位职责</strong></p><ol><li>能深度理解产品需求，开发高质量的应用模块；</li><li>能使⽤AI独⽴完成模块开发，包括前后端代码编写，联调和问题排查；【</li></ol><p><strong>任职要求</strong></p><ol><li>熟悉Java，Springboot，SpringCloud微服务等后端技术，熟悉Redis缓存，熟悉MySQL；</li><li>了解CSS，HTML，JS，TS，使用 Vue.js ，Element等框架开发 Web 应用；</li><li>熟悉linux系统和相关指令，熟悉Docker；</li><li>认真细⼼，良好的沟通协作能力，遇事积极主动；</li><li>拥抱AI，熟悉AI工具，使用AI提高工作效率；</li></ol>', '3-5年', 'fcaa111a238b6bf00nF_39i7E1dW', '深圳 · 南山区 · 科技园', '11-16K', 'Java, 物联网经验, SpringCloud, MySQL, Spring', '全栈工程师（侧重后端）', 'https://www.zhipin.com/job_detail/fcaa111a238b6bf00nF_39i7E1dW.html', '节日福利, 年终奖, 意外险, 补充医疗保险, 带薪年假, 绩效奖金, 通讯补贴, 定期体检, 双休, 员工旅游, 保底工资, 生日福利, 底薪加提成, 零食下午茶, 五险一金, 团建聚餐, 加班补助');
INSERT INTO `jobs` VALUES (236, '深圳市科南数字信...', '计算机软件', '0-20人', '', '大专', '<p><strong>任职要求</strong></p><ol><li>基础条件与经验（1）工作年限：3年及以上全栈或后端/前端开发工作经验。</li><li>项目经验：具有完整参与 0 到 1 项目 的开发经验，具备独⽴按时完成模块研发的能⼒。</li><li>后端技术（主）（1）扎实的 Java*基础，熟悉⾯向对象设计原则与常用设计模式。</li><li>熟练掌握 Spring / Spring Boot / Spring Cloud等主流开发框架。</li><li>熟悉关系型数据库（如 MySQL、PostgreSQL），具备良好的数据库设计与 SQL 优化能力；了解 Redis 等缓存中间件。</li><li>具备良好的 RESTful API 接口设计与规范化⽂档编写能力。</li><li>前端技术（1）熟练掌握 HTML5、CSS3、JavaScript / TypeScript，熟悉响应式布局与跨浏览器兼容性。</li><li>具有实际 Vue (Vue 2 / Vue 3) 或 React 项目开发经验，了解相关生态（如 Router、Pinia/Redux、Axios）。</li><li>AI 编程与工程能力（重要）（1）熟练使用 AI 辅助编程：能有效利用 codex/opencode/workbuddy 等工具进行代码生成、重构、Debug 及单元测试编写，具备提炼高效 Prompt 的能力。</li><li>熟练使用 Git 进行代码版本控制与团队协作。了解基本 DevOps 流程，熟悉 Linux 基础命令及 Docker 容器化部署。</li><li>软实力（1）具备良好的业务理解能力、逻辑思维能力与沟通协调能力。</li><li>有强烈的主动性与责任心，具备良好的工程质量意识（注重代码规范与安全性）。</li><li>加分项（优先考虑）（1）熟悉微服务架构、消息队列（如 RabbitMQ/Kafka）或高并发优化经验。</li><li>具备 Node.js、Next.js 或 Nuxt.js 等全栈/SSR 框架开发经验。</li><li>有自己的开源项目、技术博客，或在开源社区有贡献者优先。</li><li>在实际项目中成功构建或搭建过基于 AI 的 Workflow / Agent 自动化流程。</li></ol>', '3-5年', 'f7ccc319a3dcf6fa0nJ709q4EldT', '深圳 · 龙岗区 · 大运', '13-17K', 'Router/Pinia/Redux, Java, 不接受居家办公, SpringCloud, VUE, react, SQL Server, Spring, AI编程, MySQL, MyBatis, 云计算经验, AI/AI使用', 'Java/全栈开发', 'https://www.zhipin.com/job_detail/f7ccc319a3dcf6fa0nJ709q4EldT.html', '');
INSERT INTO `jobs` VALUES (237, '深圳常宏智慧', '其他专业服务', '0-20人', '未融资', '本科', '<p>岗位职boss责：1.后端系统开发：负责系统设计开发维护、参与需求分析 / 技术方案 / 架构设计、编写高质量代码、参与技术评审2.Java 核心功能开发：使用 Java 及框架（Spring Boot/Spring Cloud 等）开发业务功能、设计实现 RESTful API、编写业务逻辑代码、优化代码结构3.数据库设计与优化：设计数据库表结构、编写 SQL 语句、优化查询性能、设计数据缓存⽅案（Redis 等）、管理数据库版本4.系统集成与对接：与前端协作完成接口对接、与第三⽅系统集成、设计实现消息队列⽅案、处理数据同步和一致性5.单元测试与代码审查：编写单元测试、参与代码审查、编写技术文档、遵循开发规范6.问题排查与性能优化：排查修复⽣产问题 Bug、分析性能瓶颈、优化 JVM 参数、处理高并发问题</p><p><strong>任职要求</strong></p><ol><li>本科及以上学历（计算机 / 软件工程 / 信息技术相关），3 年以上 Java 后端开发经验，有互联网公司开发经验、完整项目经验优先2.核心技术能力：熟练掌握 Java 语言及核心原理、精通 Spring/Spring Boot/Spring Cloud 等框架、熟悉 MyBatis/Hibernate 等 ORM 框架、熟悉 JVM 原理 / 垃圾回收 / JVM 调优 / Java 并发编程；熟练掌握 MySQL/PostgreSQL 等关系型数据库、熟悉数据库设计原则 / SQL 优化、了解 NoSQL 数据库（MongoDB/Redis 等）；熟悉 Redis 缓存、了解消息队列（RabbitMQ/Kafka 等）/ 分布式协调服务（ZooKeeper/Nacos 等）；熟悉微服务架构设计理念、了解服务注册发现 / 配置中心 / 负载均衡 / 分布式事务3.软技能：良好沟通能力、问题分析解决能力、学习能力、创新意识、文档编写能力、团队协作精神，有技术论文发表经历优先加分项：</li><li>熟悉 Git 版本控制 / Git Flow 工作流、熟悉 Maven/Gradle 构建工具、熟悉 CI/CD 流程（Jenkins/GitLab CI 等）2.熟悉 Docker 容器技术 / 容器化部署、了解 K8s 容器编排、熟悉阿里云 / 腾讯云等云平台、了解 Serverless / 云原生技术3.具备良好系统设计能力、了解分布式系统设计原理 / 高并发高可用架构 / 系统安全数据安全4.了解前端技术（Vue/React/Angular 等）、能与前端高效协作、了解前后端分离架构5.系统运维与保障：负责后端服务日常运维、监控核心组件、制定备份恢复策略、参与架构设计并提优化建议</li></ol>', '3-5年', 'ba50be52c8d3bbb40nV53Nq8GVBT', '深圳 · 坪山区 · 坪山', '11-15K', '', '后端开发工程师', 'https://www.zhipin.com/job_detail/ba50be52c8d3bbb40nV53Nq8GVBT.html', '保底工资, 带薪年假, 定期体检, 节日福利, 五险一金, 绩效奖金');
INSERT INTO `jobs` VALUES (238, '深圳鱼溪堂', '游戏', '100-499人', '天使轮', '本科', '<p><strong>一、岗位职责</strong></p><ol><li>对接媒体渠道及游戏SDK，完成数据的采集、清洗与入库。</li><li>参与数据分析平台/报表系统建设。</li><li>⽀撑⽇常数据核对分析需求。（⼆）SDK后端1、负责SDK后端服务开发和维护功能。</li><li>接入必要的第三方SDK，如⼴告，数据采集等。</li><li>对接游戏联运硬核渠道及其他主流渠道。</li><li>对接游戏研发，配合其完成SDK接入。</li><li>处理线上问题并持续优化。（三）AI应用与提效1、使用AI开发内部提效工具，或搭建工作流，替代重复性人工操作。</li><li>适当辅助非技术同学使用AI工具。</li></ol><p><strong>二、任职要求</strong></p><ol><li>精通Spring Boot、MyBatis等主流开发框架，熟悉微服务架构与常用设计模式。</li><li>熟练使用Kafka、MQ等消息中间件，了解Flink/Spark等大数据计算框架。</li><li>熟悉MySQL，redis,ClickHouse等数据库、缓存、数仓等使用与接入。</li><li>熟练使用Linux常用命令，熟悉服务器环境下的应用部署与排障。（二）AI能力1、熟练运用AI编程，提升效率，对各主流大模型有较深入理解。</li><li>了解 Agent、RAG、SKILL、MCP等AI应用核心概念。</li><li>具备使用AI落地提效的实际经验，有可量化的提效成果者优先。</li></ol>', '3-5年', '680cc5093cb6a90a0nF42d-9GFZX', '深圳 · 南山区 · 科技园', '15-30K', 'Java, Spring, MyBatis, Kafka, SpringCloud, Nginx, 不接受居家办公, MySQL, Redis, 微服务经验, 架构设计经验, 大数据经验, 游戏行业, 游戏发行', '游戏JAVA后端开发工程师', 'https://www.zhipin.com/job_detail/680cc5093cb6a90a0nF42d-9GFZX.html', '五险一金, 底薪加提成, 保底工资, 带薪年假, 绩效奖金, 员工旅游, 生娃礼金, 年终奖, 节日福利, 全勤奖, 团建聚餐, 结婚礼金, 零食下午茶, 定期体检, 有无线网');
INSERT INTO `jobs` VALUES (239, '深圳某中型机电工程公司', '机电工程', '100-499人', '', '本科', '<p>boss</p><p><strong>岗位职责</strong></p><ol><li>针对新型的空间体验创意，基于算法或业务逻辑，快速进行原型产品开发并进行功能效果验证；</li><li>新产品及新商业模式的策划、技术选型、技术方案制定，并推进包括软硬件在内的原型产品的开发；</li><li>配合团队编写规范且可维护的代码，参加代码评审、产品测试、部署、运维等开发流程，制作并整理技术文档；</li><li>管理委外的开发项⽬，并积极推进现有产品的软硬件设计优化，促进专利申请。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，控制⼯程、嵌⼊式、计算机或其他理工科相关专业，3年或以上开发经验；</li><li>熟练掌握例如Java、Python、C/C++、Swift/Objective-C 等一门以上的编程语⾔，熟悉该语言生态的主流框架和常用技术栈，习惯敏捷开发节奏；</li><li>可灵活应用各类AI工具、熟悉3D建模、电机控制、无线通讯技术者优先；</li><li>良好的沟通能力和团队合作能力、做事主动、日语或英语流畅者优先；</li><li>热爱生活、对新事物有强烈的好奇心与探索欲者优先</li></ol>', '3-5年', 'b4a0178090112c290nJ40tS8FldU', '深圳', '15-25K', 'Java, Python, C++, C, 架构设计经验, 不接受居家办公', '创新产品开发工程师（五险一金，周末双休）', 'https://www.zhipin.com/job_detail/b4a0178090112c290nJ40tS8FldU.html', '');
INSERT INTO `jobs` VALUES (240, '大展科技', '计算机软件', '100-499人', '未融资', '大专', '<p><strong>岗位要求</strong></p><ol><li>学信网统招大专及以上学历2. 具备扎实的编程功底，熟练掌握Java语言，深入理解JVM原理，熟练使⽤Spring、Spring MVC、SpringBoot、Spring Cloud、 Mybatis等主流开发框架，具备扎实的编程基础和良好的编程习惯；对常⽤的设计模式、设计原则、数据结构等有⼀定的理解和掌握，对面向对象思想有深入的理解；</li><li>熟悉Nginx、Redis、Kafka, MQ，对象存储等中间件的使⽤及部署；熟练使用Linux命令；</li><li>熟练掌握Oracle/PostgreSQL/MySQL等数据库，具备数据分析+设计+开发的能力，有数据库能调优经验；</li><li>熟悉敏捷开发模式及DevOps管理方法体系。</li><li>有金融/保险公司/信托/财务相关数据系统研发经验。</li></ol>', '3-5年', '9ede3fe909e95a060nFz09S7FFNR', '深圳 · 福田区 · 车公庙', '11-13K', 'Java, 不接受居家办公, DevOps, 分布式经验, 微服务经验, 保险, SpringCloud, MySQL, Redis, Spring, Oracle, 金融', 'java开发 （双休大厂现场面试）', 'https://www.zhipin.com/job_detail/9ede3fe909e95a060nFz09S7FFNR.html', '定期体检, 免费班车, 带薪年假, 节日福利, 年终奖, 五险一金, 零食下午茶, 员工旅游');
INSERT INTO `jobs` VALUES (241, '渴创技术', '消费电子', '100-499人', 'A轮', '本科', '<p><strong>工作内容</strong></p><ol><li>负责Netsuite ERP系统的二次开发、维护及优化，确保日常业务运营的有效运行（包括与第三方平台实现订单、费用数据同步、开发第三方系统的接口实现自研系统之间的数据交换等）；</li><li>协助财务信息化，满足审计及内部运营管理需求。</li><li>根据业务需求，设计和实施高效的解决方案以优化系统性能和用户体验，了解业务团队需求并提供技术支持和指导；</li><li>解决Netsuite平台相关的技术难题，提供高效、可靠的解决方案；</li><li>参与项目规划和评估，包括需求分析、开发估时和风险评估等。</li></ol><p><strong>岗位要求</strong></p><ol><li>学历要求：本科及以上学历，计算机科学、信息技术或相关专业。</li><li>专业技能:- 3年及以上Netsuite开发经验- 熟悉NetSuite中的主数据、应收应付，存货、总账，资产等模块的配置和功能设计，可独立完成相关操作。- 熟练掌握Netsuite平台，包括SuiteScript 1.0/2.x的编写和应用开发。- 理解和使用Netsuite SuiteCloud开发工具集，如SuiteBuilder, SuiteFlow,SuiteAnalytics, SuiteTalk等工具。- 熟悉 Netsuite 系统工作流、SuiteScript 脚本开发、自定义记录、事务处理记录、系统搜索功能等。- 熟悉Web技术，包括HTML,CSS, JavaScript, XML,和Web Services (SOAP, REST)。- 拥有数据库相关技能，了解SQL查询语言和数据库设计。- 具备对接第三方服务的开发经验，比如对接Shopify、Amazon、Walmart、万邑通等，熟悉 Amazon、Shopify 等电商平台，物流海外仓系统对接方式。- 有跨境电商、供应链管理项目经验。 - 具有良好的沟通能力和团队合作精神，能够独立解决问题。</li></ol><p><strong>福利待遇</strong></p><ol><li>入职购买五险一金（一档），让你没有后顾之忧；</li><li>年底双薪、年假、带薪病假；</li><li>朝九晚六不加班（加班可调休），节假日按法定放；</li><li>公司氛围好，扁平化管理，没有那么多勾心斗角；</li><li>每个季度有团建经费，每天免费咖啡提供，</li></ol><p><strong>福利</strong></p><p>多多；6、定期培训等</p>', '3-5年', '883b5212b76fbdb003F929i_FlJZ', '深圳 · 龙岗区 · 坂田', '15-30K·13薪', 'Java, 不接受居家办公, NS开发, MySQL, Javascript, Oracle, SuiteCloud, ERP开发经验, netsuite', 'Oracle Netsuite开发工程师', 'https://www.zhipin.com/job_detail/883b5212b76fbdb003F929i_FlJZ.html', '全勤奖, 五险一金, 五险一金, 年终奖');
INSERT INTO `jobs` VALUES (242, '悦策科技', '大数据', '20-99人', '未融资', '本科', '<p>【</p><p><strong>岗位职责</strong></p><ol><li>技术攻坚与规范建设：带领研发组研究AI前沿技术；建立高标准的代码规范与测试流程，保障产品按时、高质量交付。</li><li>项⽬运维与客户⽀撑：统筹客户项⽬的落地实施与后期运维，快速解决生产环境复杂问题。</li><li>售前技术支持：配合业务部门进⾏技术方案输出、技术宣讲，将客户需求转化为可落地的解决方案。【</li></ol><p><strong>任职要求</strong></p><ol><li>Python与AI工程化经验：熟悉Python生态；具备大模型应用开发经验，熟悉Harness等AI框架，有智能体开发者优先。</li><li>大数据与数据库优化：熟练使用Oracle、MySQL等数据库，了解数据分析开发者优先。</li><li>熟练运用AI辅助编程：必须熟练掌握AI辅助编程工具，善于利用AI生成代码、编写单元测试及排查Bug，显著提升团队整体研发效率。</li><li>良好的管理与协作能力：具备较强的小组管理能力，能有效拆解任务并指导团队成员成长；沟通协调能力出色，能顺畅衔接各业务部门。</li><li>责任心与抗压能力：具备强烈的产品化和质量意识；工作积极主动，乐观皮实，能在快节奏的项目压力下保持高效产出。</li></ol>', '3-5年', 'fd8d2c673d5b33070nB82N67ElJZ', '深圳 · 南山区 · 科技园', '13-18K', 'Java, Nginx, 团队管理经验, 不接受居家办公, 分布式经验, SpringCloud, SQL Server, Spring, Docker, 微服务经验, MySQL, MyBatis, Python', '智能体开发工程师', 'https://www.zhipin.com/job_detail/fd8d2c673d5b33070nB82N67ElJZ.html', '节日福利, 零食下午茶, 年终奖, 餐补, 五险一金, 员工旅游, 股票期权, 带薪年假, 定期体检');
INSERT INTO `jobs` VALUES (243, '北京汉正天成', '电子商务', '100-499人', '不需要融资', '本科', '<ol><li>计算boss机相关专业，3年以boss上的Java开发经验；</li><li>熟悉SpringMVC、SpringBoot、SpringCloud、myBytis、k8s、tsf微服务平台等开源框架。</li><li>熟悉MySQL、达梦、oracle、PostgreSQL等数据库使用，并有相关优化SQL优化经验；</li><li>熟悉存储过程的使用及编写，并有实际开发经验；</li><li>熟悉Redis等缓存数据使用，并有实际项目使⽤；</li><li>熟悉Nginx部署配置，并理解其原理，熟悉git⼯具使⽤；</li><li>良好的沟通意识和服务态度，团队意识强；</li><li>熟悉并使用过etl、数据工⼚等经验优先；</li><li>熟悉并使用过xxljob、Kafka、rabbitmq等经验优先；</li><li>具备电网营销、营配业务或南网项目的系统开发经验者优先；</li><li>具有一定的抗压能力。</li></ol>', '3-5年', '90cf428729cef18c0nF53dy9F1pY', '深圳 · 宝安区 · 西乡', '10-15K', 'Java, Nginx, xxljob, Kafka、rabbitmq, PostgreSQL, SpringCloud, MySQL, MyBatis, Redis, Oracle', 'Java开发工程师', 'https://www.zhipin.com/job_detail/90cf428729cef18c0nF53dy9F1pY.html', '');
INSERT INTO `jobs` VALUES (244, '星创', '计算机软件', '100-499人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>能独立负责业务需求，完成从 0 到 1 的开发任务，按时高质量完成项目交付；</li><li>有良好的编码基础和编码习惯，负责基础组件的开发，并能对团队其它人进⾏ Code Review；</li><li>有丰富的性能优化经验，负责团队的技术攻坚和复杂功能的优化；</li></ol><p><strong>岗位要求</strong></p><ol><li>计算机相关专业本科及以上学历，3年以上后端开发经验；</li><li>有扎实的 JAVA 基础，了解 JVM 原理，有 JVM 调优经验；</li><li>熟练掌握⾄少⼀款数据库，如 MySQL，Oracle、SQLServer、StarRocks 等，良好的数据库设计和丰富的优化经验；</li><li>熟悉分布式系统的设计，熟悉分布式缓存和消息队列， 熟练掌握并发编程；</li><li>掌握设计模式和设计原则，能独立完成系统模块的划分和开发，注重程序的性能和扩展性，有良好的编码习惯，有 Python 开发经验加分；</li><li>具有良好的沟通能力和团队合作精神，热爱技术，积极主动，有团队合作精神；</li><li>有数据中台、⼴告系统开发经验人员优先。</li></ol>', '3-5年', '37f0df50d75a2b7a0nJ609m1GVRT', '深圳 · 福田区 · 车公庙', '18-27K', 'Java, Spring, MySQL', 'Java后端开发工程师', 'https://www.zhipin.com/job_detail/37f0df50d75a2b7a0nJ609m1GVRT.html', '团建聚餐, 五险一金, 年终奖, 带薪年假, 零食下午茶, 定期体检, 加班补助, 节日福利, 绩效奖金, 生日福利, 全勤奖, 企业年金');
INSERT INTO `jobs` VALUES (245, '河北源海鸿锦', '互联网', '100-499人', '', '本科', '<p><strong>工作职责</strong></p><ol><li>负责仓储机器人调度平台开发工作，根据业务规格说明书，能够快速进行代码实现；</li><li>主动按时⾼质量完成需求开发和⾃测；</li><li>配合PM⾼质量完成各项开发任务，包括不限于需求评审，系统测试用例编写，代码评审与问题或工单定位修改等。</li><li>熟练运⽤各种问题排查方法，快速定位系统问题根因并修复；</li><li>输出并分享高质量的交付文档进行知识沉淀。</li></ol><p><strong>任职资格</strong></p><ol><li>全日制本科学历，计算机相关专业，3年及以上Java开发经验，JAVA基础扎实，熟练掌握io、多线程、集合等基础框架，熟悉JVM原理；</li><li>良好的团队合作能力，流畅的口头和书面表达能力，严谨的工作态度，有极客意识，求知欲强 ，思路活跃。</li><li>熟悉常用开源框架的原理和内部机制，如Spring Cloud等，能够熟练并合理使用；</li><li>熟悉数据库，redis、RPC等中间件，有良好的设计模式及实际落地能力；</li><li>自驱力强且有强烈的技术热情和钻研精神，热爱新技术；</li></ol>', '3-5年', '2dbcd7b2eb1c5b060nFz39S7E1RY', '深圳 · 宝安区 · 西乡', '15-16K', 'Java, SpringCloud, JVM, Redis, 架构设计经验, 不接受居家办公', 'Java', 'https://www.zhipin.com/job_detail/2dbcd7b2eb1c5b060nFz39S7E1RY.html', '');
INSERT INTO `jobs` VALUES (246, '遇创科技', '游戏', '20-99人', '未融资', '大专', '<p>职位概要： 负责手机游戏项目后端开发工作。</p><p><strong>岗位职责</strong></p><ol><li>负责游戏服务器业务开发与维护，保证服务端的性能，稳定性；</li><li>游戏服务器数据配置和数据分析工具的开发和维护；</li><li>与前端，策划等人员密切协作完成开发和部署。</li></ol><p><strong>任职资格</strong></p><ol><li>计算机专业，四年以上java游戏服务器开发工作经验；至少参与过一款完整游戏项目；</li><li>能独立负责游戏服务端业务模块与核心功能开发3.扎实java基础，有多线程开发及NIO开发工作经验；</li><li>熟练使用spring框架以及相关组件，有过微服务开发经验；</li><li>有丰富的MySQL数据库查询和调优经验。</li><li>熟练使用git，maven，gradle等各种开发工具。</li><li>有高并发程序设计经验，对jvm工作原理和内存分析有一定的工作经验。</li><li>有jQuery，vue2/3的网页开发经验。</li><li>有海外项目经验，有亚马逊云服务经验优先；</li><li>热爱游戏行业，有电玩城手游服务端开发经验更佳熟练操作linux常用的各种命令和工具软件。</li></ol>', '3-5年', '111522c4d10e8d9803B-3t25GVVY', '深圳 · 南山区 · 科技园', '14-18K·13薪', 'Java, MySQL, Spring', 'java游戏开发工程师', 'https://www.zhipin.com/job_detail/111522c4d10e8d9803B-3t25GVVY.html', '绩效奖金, 零食下午茶, 员工旅游, 定期体检, 年终奖, 通讯补贴, 带薪年假, 交通补助, 五险一金, 节日福利, 餐补');
INSERT INTO `jobs` VALUES (247, '达芬奇新能源', '计算机软件', '0-20人', '未融资', '本科', '<p><strong>一、岗位职责</strong></p><ol><li>负责公司智慧停车后端平台的设计、开发、迭代及维护，核心支撑车位管理、预约调度、无感⽀付、设备管控、数据统计分析等核⼼业务模块，保障平台⾼可用、高并发、⾼安全。</li><li>负责后端服务架构设计与优化，梳理业务逻辑，设计合理的数据模型、接口规范及业务流程，提升系统性能、可扩展性与可维护性，支撑业务快速迭代。</li><li>对接物联网设备，负责设备数据采集、解析、存储与同步，实现设备状态监控、远程控制等功能，保障设备与平台的数据联动稳定。</li><li>与前端开发、测试、产品等团队紧密协作，完成接口设计、开发与联调，处理前后端数据交互、异常排查等问题，配合完成产品功能落地与上线。</li><li>负责后端平台线上问题排查、bug修复、性能优化，监控系统运行状态，及时处理突发故障，保障平台7×24小时稳定运行，降低系统故障率。</li><li>参与智慧停车业务需求分析与技术方案讨论，结合后端技术特点，为产品优化、功能迭代提供合理建议，沉淀技术文档、开发规范及通用组件，提升团队开发效率。</li><li>负责数据库设计、优化与维护，处理数据备份、恢复及性能调优，保障数据安全与数据一致性；关注行业技术动态，将合适的新技术、新框架应用到项目中，推动技术升级。</li></ol><p><strong>二、任职要求</strong></p><ol><li>学历：本科及以上，计算机、电子通信、软件工程、物联网工程等相关专业优先，3~5年及以上后端开发经验，有物联网、智慧停车、智慧城市、平台开发相关项目经验者优先。</li><li>了解物联网基础原理、常见物联网协议，熟悉智慧停车业务流程者优先，能快速理解业务逻辑并转化为后端实现方案。</li><li>熟练掌握Java语言的核心特性、开发框架及生态体系。</li><li>熟练掌握关系型数据库，精通SQL语句编写、数据库设计、索引优化及性能调优；了解非关系型数据库，能熟练运用其解决业务场景问题。</li><li>了解物联网协议，能完成物联网设备数据对接、解析与同步，熟悉设备管理相关开发逻辑，有设备接入平台开发经验者优先。</li><li>熟悉后端工程化、微服务架构，了解服务注册与发现、负载均衡、熔断降级等机制，能参与架构设计与优化，提升系统可扩展性与稳定性。</li><li>熟悉Linux系统操作，能熟练使用命令行进行服务器部署、日志排查、服务监控；掌握Git版本控制工具，能规范进行代码提交、分支管理与协作开发。</li><li>了解分布式系统、高并发处理、数据加密等相关技术，能应对智慧停车高峰期的系统压力，保障平台稳定运行；有支付接口集成经验者优先。</li></ol>', '3-5年', 'fff6d2e4734efc1c0nBy0tW4F1dW', '深圳 · 宝安区 · 石岩', '10-15K', 'Java, SpringCloud, MySQL, 智慧停车, 停车系统, 道闸系统', '停车系统平台Java开发中级工程师', 'https://www.zhipin.com/job_detail/fff6d2e4734efc1c0nBy0tW4F1dW.html', '绩效奖金, 年终奖, 五险一金');
INSERT INTO `jobs` VALUES (248, '光胜科技', '智能硬件/消费电子', '100-499人', 'A轮', '本科', '<p>AI二次元潮玩社交业务扩招中公司亮点（风口赛道，难得机遇，邀你同行！）产品：AI 二次元潮玩社交作息：双休 9:00–18:30位置：深圳·南山（毗邻腾讯滨海⼤厦）</p><p><strong>福利</strong></p><p>五险⼀⾦/下午茶/生日会/团建/激励奖⾦/年终奖等</p><p><strong>岗位职责</strong></p><ol><li>负责 C 端 APP 后端核心架构设计与开发，支撑软硬件连接、数据采集、设备控制指令下发，保障服务低延迟、高可用。</li><li>主导社区互动、会员订阅、聚合支付等核心业务模块从 0 到 1 搭建，覆盖 Feed 流、评论点赞、即时消息、周期计费、多渠道支付、对账与风控。</li><li>针对海量用户高并发场景，负责数据库分库分表、Redis 缓存、消息队列等方案设计与深度优化，解决性能瓶颈。</li><li>负责MQTT/CoAP/TCP 等物联网协议网关开发与维护，处理设备心跳、状态同步、固件升级（OTA）等服务。</li></ol><p><strong>任职要求</strong></p><ol><li>计算机相关专业本科及以上，5 年及以上后端开发经验。</li><li>精通 Java/Go/Node.js 至少一门，深入理解底层原理与多线程 / 协程模型。</li><li>熟练掌握 MySQL 设计与调优，具备大规模数据分库分表实战经验；精通 Redis 缓存、分布式锁及常见缓存问题解决方案。</li><li>熟练使用 Kafka/RocketMQ 等消息中间件，有削峰填谷、异步解耦实战经验。</li><li>有支付对接、对账、退款、订阅制开发经验；具备社区 Feed 流、IM 或社交关系链开发经验优先。</li><li>熟悉 Netty/Vert.x 等网络框架，有MQTT 网关、IoT 设备接入经验优先。</li><li>熟悉微服务架构、Docker/K8s 等，具备复杂系统拆分与重构能力。</li><li>业务敏感度强，抗压、沟通协作良好，具备强责任心与安全意识。</li></ol>', '3-5年', '7d773c71d65c9d820nVz29-0E1pT', '深圳 · 南山区 · 科技园', '12-18K·13薪', 'Golang, Java, C++, Java开发, PostgreSQL, Python开发, 架构设计经验, 后端开发, 后端工程师, Python', '后端开发工程师', 'https://www.zhipin.com/job_detail/7d773c71d65c9d820nVz29-0E1pT.html', '加班补助, 生日福利, 法定节假日三薪, 股票期权, 年终分红, 有无线网, 保底工资, 员工旅游, 绩效奖金, 餐补, 年终奖, 团建聚餐, 零食下午茶, 节假日加班费, 节日福利, 底薪加提成, 全勤奖, 五险一金, 免费工装, 带薪年假');
INSERT INTO `jobs` VALUES (249, '南京海钰通科技', '半导体/芯片', '0-20人', '', '本科', '<p><strong>工作职责</strong></p><ol><li>负责仓储机器人调度平台开发工作，根据业务规格说明书，能够快速进行代码实现；</li><li>主动按时⾼质量完成需求开发和⾃测；</li><li>配合PM⾼质量完成各项开发任务，包括不限于需求评审，系统测试用例编写，代码评审与问题或工单定位修改等。</li><li>熟练运⽤各种问题排查方法，快速定位系统问题根因并修复；</li><li>输出并分享高质量的交付文档进行知识沉淀。</li></ol><p><strong>任职资格</strong></p><ol><li>全日制本科学历，计算机相关专业，3年及以上Java开发经验，JAVA基础扎实，熟练掌握io、多线程、集合等基础框架，熟悉JVM原理；</li><li>良好的团队合作能力，流畅的口头和书面表达能力，严谨的工作态度，有极客意识，求知欲强 ，思路活跃。</li><li>熟悉常用开源框架的原理和内部机制，如Spring Cloud等，能够熟练并合理使用；</li><li>熟悉数据库，redis、RPC等中间件，有良好的设计模式及实际落地能力；</li><li>自驱力强且有强烈的技术热情和钻研精神，热爱新技术；</li></ol>', '3-5年', 'c9f39c019e7855670nF82t65FVNU', '深圳 · 宝安区 · 西乡', '14-17K', 'Java, JVM, MySQL, 云计算经验, 不接受居家办公', 'Java开发工程师   双休   六险一金', 'https://www.zhipin.com/job_detail/c9f39c019e7855670nF82t65FVNU.html', '');
INSERT INTO `jobs` VALUES (250, '数盾股份', '信息安全', '100-499人', 'D轮及以上', '本科', '<p>项目制，项目制，项目制，能接受在投递简历</p><p><strong>职位描述</strong></p><ol><li>参与项目的需求分析、系统设计与技术选型，提供专业的技术建议与解决方案。</li><li>负责核心代码的编写与系统模块的开发，遵循代码规范与最佳实践，确保代码的可读性、可维护性与可扩展性。</li><li>对现有系统进行优化与维护，及时发现并解决系统中存在的性能瓶颈、安全漏洞等问题。</li><li>配合测试团队完成软件的测试工作，对测试中发现的问题进行快速定位与修复，保障软件质量。</li><li>参与技术攻关与难题解决，在遇到复杂技术问题时，能够深入研究并提出有效的解决方案，推动项目顺利进行</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机科学、软件工程等相关专业，3年以上 Java 开发经验。</li><li>精通 Java 核心库与常用设计模式，熟悉 Spring、Spring Boot、MyBatis、Mybatis-Flex、Fluent-Mybatis等主流框架。</li><li>熟练掌握数据库设计与开发，有 MySQL、PostgreSql、Oracle 等关系型数据库应用经验，熟悉 SQL 调优。</li><li>深入理解并熟悉使用 MySQL、PostgreSql、Oracle 等关系型数据库，能够进行高效的数据库设计、优化及复杂查询编写。</li><li>对 Redis、Mongodb、Hive 等非关系型数据库有扎实的掌握，熟悉其应用场景及数据处理方式。</li><li>具备良好的问题解决能力，能够独立分析并解决复杂的技术问题，有较强的学习能力与自我提升意识。</li><li>责任心强，对工作任务有高度的责任感和敬业精神，确保交付的代码质量可靠、稳定高效。</li><li>学习能力强，能够快速掌握新技术并应用于实际工作中，主动跟进行业技术发展趋势，不断提升自我技术水平。</li><li>抗压能力强，在项目周期紧张、任务繁重的情况下，依然能够保持冷静，有条不紊地推进工作，确保项目按时交付。</li><li>能够适应出差（驻场）及短时高强度加班，根据项目需求及时前往不同地区开展工作，积极配合团队完成异地项目任务。（重要，如不能接受请不要投递）</li></ol>', '3-5年', 'bc9c7729ba66f50e03J_0t64FFFR', '深圳 · 南山区 · 科技园', '12-16K', 'Java, 物联网经验, 不接受居家办公, PostgreSQL, SpringCloud, MySQL, SQL Server, Spring', '中级java开发工程师', 'https://www.zhipin.com/job_detail/bc9c7729ba66f50e03J_0t64FFFR.html', '工龄奖, 五险一金, 餐补, 生日福利, 节假日加班费, 有无线网, 节日福利, 加班补助, 团建聚餐, 底薪加提成, 法定节假日三薪, 保底工资, 带薪年假');
INSERT INTO `jobs` VALUES (251, '全运汇物流科技', '跨境物流', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>参与公司核心业务系统的需求分析、架构设计及代码开发，确保高性能、高可用性；</li><li>负责Java后端服务开发，包括但不限于分布式系统、微服务、数据中间件等模块；</li><li>优化现有系统架构，解决⾼并发、⼤数据量场景下的技术难题；</li><li>编写⾼质量技术文档，推动代码审查、单元测试和持续集成；</li><li>跟踪前沿技术，推动技术创新与团队技术能力提升。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机/软件⼯程相关专业，3年及以上（可调整年限）Java开发经验；</li><li>扎实的Java基础，熟悉多线程、集合、JVM原理及调优；</li><li>精通主流开发框架：Spring/Spring Boot/Spring Cloud、MyBatis等；</li><li>熟悉MySQL、Redis、oracle等数据库，具备SQL优化及分库分表经验；</li><li>熟悉分布式系统设计，熟悉Dubbo、Zookeeper、RocketMQ/Kafka等中间件；</li><li>熟练使用Git、Maven/Gradle，熟悉Linux开发环境及Shell脚本；</li><li>良好的编码习惯，理解设计模式，能独立完成模块设计与开发。加分项1.有国际物流系统的项目经验2.熟悉前端技术（Vue/React）或有全栈开发能力；工作时间：5天半工作制，每周休息1.5天周一至周五，早上9点至下午6点半，午休1个半小时周六早上9点至中午12点半</li></ol>', '3-5年', 'cb88aeb0684eeea10nF_396-EFBW', '深圳 · 宝安区 · 福永', '10-13K·13薪', 'Java, SpringCloud, MySQL, Redis', 'java软件开发工程师', 'https://www.zhipin.com/job_detail/cb88aeb0684eeea10nF_396-EFBW.html', '绩效奖金, 节日福利, 团建聚餐, 零食下午茶, 年终奖, 带薪年假, 员工旅游, 生日福利, 底薪加提成, 保底工资, 五险一金, 加班补助');
INSERT INTO `jobs` VALUES (252, '深圳科皓', '计算机软件', '100-499人', '未融资', '大专', '<p><strong>岗位职责</strong></p><ol><li>参与公司核心业务系统的设计、开发与维护，确保代码质量、性能及可扩展性。</li><li>参与技术方案评审，完成数据库设计、接口定义及核心功能编码。</li><li>解决后端系统的高并发、⾼可⽤问题，进⾏JVM调优、SQL优化及中间件故障排查。</li><li>在必要时协助前端页面开发或接口联调，保障前后端顺畅协作。</li><li>撰写技术文档，参与代码评审。</li></ol><p><strong>任职要求</strong></p><ol><li>3-5年Java开发经验，深⼊理解JVM原理（内存模型、GC机制）、并发编程、IO模型及常用数据结构，具备实际调优经验。</li><li>熟练掌握Spring生态系统（Spring Boot/Spring Cloud/Spring MVC），深入理解MyBatis或MyBatis Plus持久层框架，有微服务架构项目经验者优先。</li><li>熟练使用常用中间件，如Redis（缓存）、RocketMQ/Kafka（消息队列），理解其底层机制及常见问题处理（如缓存穿透、消息积压）。</li><li>至少掌握SQLServer，Mysql，Oracle主流数据库中的一种，具备复杂SQL编写、索引优化、分库分表设计能力。</li><li>了解HTML/CSS/JavaScript基础，熟悉Vue或React的基本使用，能够看懂前端代码并进行简单的页面调整；熟悉RESTful API设计规范，能与前端工程师高效联调。</li><li>具备钻研精神和较强的学习能力，热爱技术研究与实践；工作认真负责，逻辑清晰，具备良好的沟通能力和抗压能力。</li></ol>', '3-5年', 'ae88b42e995aa0e20nJ729-5FlNW', '深圳 · 福田区 · 梅林', '10-15K', 'Java, Spring, SpringCloud, MyBatis, MySQL, Oracle, Redis, 微服务经验, 不接受居家办公', '中级java开发工程师', 'https://www.zhipin.com/job_detail/ae88b42e995aa0e20nJ729-5FlNW.html', '带薪年假, 五险一金, 节日福利, 定期体检, 交通补助, 宿舍有空调, 股票期权');
INSERT INTO `jobs` VALUES (253, '宙一物流', '跨境物流', '20-99人', '不需要融资', '本科', '<p>**【公司业务】**国内仓储 + 海外仓 + 专线小包 + FBA大货头程物流（海运/空运直达亚马逊FBA仓库）；自研ERP+OMS系统，支撑跨境物流全链路数字化运营。**【</p><p><strong>岗位亮点</strong></p><ul><li>同时驾驭Spring MVC + Spring Boot双技术体系；</li><li>涉及多线程异步处理、高并发系统优化、物流轨迹追踪等核⼼技术场景；</li><li>后端前端自己写自己调，完整闭环开发，成长空间大；</li><li>公司自研系统，技术自主权大，非外包，长期稳定投入；</li><li>团队氛围好，鼓励使用AI工具提效。**【</li></ul><p><strong>岗位职责</strong></p><ol><li>使用Java Spring Boot及Spring MVC构建稳定、可扩展的微服务架构后端，保障系统高可用性；</li><li>承担物流全链路追踪、运费/关税试算与计费、多仓库存同步等复杂业务逻辑的代码实现；</li><li>设计并优化MySQL数据库结构及复杂SQL，实现高效数据存储与访问，保障数据一致性与完整性；</li><li>结合MySQL处理海量时序数据（物流轨迹、订单入库出库等），支持物流订单实时数据采集、存储与分析场景；</li><li>利用Redis实现缓存、分布式锁等应用，提升系统吞吐量及并发处理能力；</li><li>使用RocketMQ进行分布式消息通信与异步处理，确保高可用消息传递与系统解耦；</li><li>基于JSP/Thymeleaf模板引擎及Layui/jQuery进行前后端全链路开发与自测，确保数据闭环；</li><li>参与架构设计、技术选型、系统性能优化及技术难题攻关，推动技术栈的持续演进；</li><li>跨部门协作，与产品、测试、运维团队紧密配合，保障项目按时交付与持续迭代。**【产品相关要求】**1. 理解AI产品的业务场景及用户需求，能将技术方案有效转化为落地产品功能；</li><li>具备从需求分析、功能设计到上线运营的完整产品开发生命周期经验；</li><li>关注用户体验，能与产品经理、设计师密切合作，推动产品交互与功能完善；</li><li>熟悉数据驱动的产品迭代流程，能够结合数据反馈不断优化产品性能和用户体验；</li><li>具备快速响应业务变更能力和多任务协同执行能力，保障项目高效推进；</li><li>能够设计和实现AI能力模块与业务系统的灵活集成，满足多样化场景需求；</li><li>了解行业AI发展趋势，具备创新意识，推动产品不断升级迭代。**【</li></ol><p><strong>岗位要求</strong></p><ol><li>精通Java 8，熟悉集合、IO、多线程、并发编程；</li><li>同时驾驭Spring MVC + Spring Boot双技术体系；</li><li>熟悉MySQL数据库设计及优化，有实际复杂业务数据库设计和调优经验；</li><li>熟悉复杂SQL统计查询，对SQL优化有丰富的经验；</li><li>熟悉Redis缓存架构和分布式缓存机制，具备实际项目应用经验；</li><li>熟悉多线程异步处理，有高并发场景下的实际应用经验；</li><li>熟悉前端开发，有JSP/Thymeleaf模板引擎或Layui/jQuery使用经验；</li><li>熟练使用Maven、Git等开发工具；</li><li>熟练使用Cursor、Claude Code等AI辅助开发工具，能够借助AI工具提升编码效率和代码质量，具备AI时代的开发思维；</li><li>具备良好的沟通协作能力，责任心强，具备快速学习和解决问题能力。**【加分项】**1. 熟练运用Claude Code、Cursor等工具优化开发流程，对AI辅助编程模式有深入实践；</li><li>参与过大型分布式系统设计与开发，具备高并发、高可用系统实战经验；</li><li>有国际物流/跨境电商/海外仓/FBA头程/TMS/WMS/轨迹追踪系统开发经验；</li><li>有AI开源项目贡献经验或技术博客沉淀者优先；</li><li>具备物流系统全栈技术能力，理解从开发到线上的完整数据链路。**【</li></ol><p><strong>福利待遇</strong></p><ol><li>上班时间：9:00-12:00 13:30-18:30，大小休息；</li><li>每月为员工举办生日会、团队聚餐、不定期全体团建；</li></ol>', '3-5年', '2138ae594da5f3890nFy3NS-ElVY', '深圳 · 龙岗区 · 坂田', '13-17K', 'Java, 不接受居家办公, MySQL, 架构设计经验, Spring', 'Java全栈开发工程师（国际物流/FBA/海外仓', 'https://www.zhipin.com/job_detail/2138ae594da5f3890nFy3NS-ElVY.html', '带薪年假, 员工旅游, 全勤奖, 保底工资, 生日福利, 工龄奖, 五险一金, 绩效奖金, 年终奖, 底薪加提成, 团建聚餐, 零食下午茶');
INSERT INTO `jobs` VALUES (254, '志拓电源', '电子/硬件开发', '100-499人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>参与系统需求分析与技术方案设计，完成核心代码编写和模块开发；</li><li>负责后端服务的开发与维护，保障系统稳定性与可扩展性；</li><li>配合前端及测试团队完成接口联调，推动项目高效交付；</li><li>编写相关技术⽂档，持续优化代码质量与系统性能；</li><li>参与技术难题攻关，提供有效的解决⽅案。</li></ol><p><strong>任职要求</strong></p><ol><li>统招本科、计算机相关专业；</li><li>具备3年及以上JAVA开发经验；</li><li>Java基础扎实，精通SpringBoot，SpringMVC，SpringCloud，Mybatis等常⽤开源框架；</li><li>精通数据库MySQL、缓存技术云Redis，了解常用NOSQL存储；</li><li>了解Tomact，Nginx等应用服务器的使⽤，了解HTML5，JavaScript，CSS，jQuery等前段开发语言；</li><li>熟悉centos，Linux/Unix操作系统；</li><li>熟悉分布式系统相关技术，具有云计算与大数据开发经验优先；</li></ol>', '3-5年', '6dc3dcd21ac483900nB439u7FlpY', '深圳 · 宝安区 · 沙井', '10-15K', 'Java, SpringCloud, MyBatis, MySQL, Redis', 'java后端开发工程师', 'https://www.zhipin.com/job_detail/6dc3dcd21ac483900nB439u7FlpY.html', '全勤奖, 年终奖, 包吃, 节日福利, 住房补贴');
INSERT INTO `jobs` VALUES (255, '深圳灵动', '互联网金融', '100-499人', '不需要融资', '本科', '<p><strong>职位描述</strong></p><p>作为MOKA系统管理专员，你将全面负责MOKA招聘系统的日常运营、优化与系统管理，为招聘团队提供高效的系统支持与精准的数据洞察，通过技术赋能提升全球招聘效率与决策质量。核⼼</p><p><strong>职责</strong></p><p>负责MOKA系统的⽇常流程优化与⾃定义二次开发。作为内部专家，为用户（HM、HRBP、Recruiter）等提供系统操作培训、即问即答与疑难故障排查。根据业务发展，不断完善业务流程，直到磨合到最佳的业务流转链路。深⼊理解招聘业务流程，主动识别系统痛点，主导或参与系统功能优化、模块上线及迭代项目。协同IT、人力资源信息化团队，推动招聘系统与其他系统的数据集成与流程打通。开发报表（如渠道效果、招聘周期、团队效率、招聘成本等），支持月度/季度业务复盘等。</p><p><strong>任职要求</strong></p><p>3-5年人力资源相关系统工作经验，如（Moka、北森、SuccessFactors）实战经验。有Moka、飞书等HR系统集成经验，熟悉开放API对接及数据同步机制。参与过积分商城或绩效开发，熟悉用户成长、权益发放等业务。拥有良好的系统思维与流程优化意识，能够将业务需求转化为系统解决方案。较强的沟通与服务意识，能够高效支持业务需求。技术能力：具备SaaS化产品开发经验，支持多租户、可配置化业务模块。熟悉resultful接口风格，了解云服务（AWS/Aliyun/Tencent Cloud）相关组件使用。精通Java及主流开源框架（Spring Boot/Spring Cloud），具备高并发、分布式系统开发经验。熟悉微服务架构，掌握服务治理、API设计及性能优化。加分项：长期从事HR相关系统开发与实施。熟悉HR的员工入转调离整体业务。具备日常英文沟通能力，能够阅读英文文档、进行基础英文沟通。</p>', '3-5年', '4b0c59ad1af830080nV-29m7GFtT', '深圳 · 南山区 · 后海', '15-20K·14薪', 'Java, 大数据经验, Hibernate, SpringCloud, MySQL, MyBatis, Spring', 'MOKA开发工程师', 'https://www.zhipin.com/job_detail/4b0c59ad1af830080nV-29m7GFtT.html', '带薪年假, 地铁直达, 有无线网, 年终奖, 餐补, 五险一金, 交通补助, 节日福利, 带薪病假, 团建聚餐, 法定节假日三薪, 节假日加班费, 生日福利, 员工旅游, 加班补助, 定期体检, 零食下午茶');
INSERT INTO `jobs` VALUES (256, '北京君宏科技', '互联网', '100-499人', '不需要融资', '本科', '<p>暂定一年的项目，干得好后期大概率会延期，项⽬地址在海南海口，海口环境好，⾐⾷住行都很便宜，很适合生活哟，愿意来海口的⼩伙伴们抓紧联系了哈岗位主要</p><p><strong>工作内容</strong></p><ol><li>负责后端接口开发、接口对接调试及代码实现 2.按照产品需求文档完成开发、数据治理、系统搭建、框架初始化等工作;</li><li>完成自己负责开发功能模块的自测，以及测试人员发现问题的修复。技术经验和素质：</li><li>有扎实的JAVA开发基础，3年以上JavaWeb开发经验。</li><li>熟悉SpringBoot、SpringCloud、Mybatis、Redis、Mysal、MQ组件、Maven、Vue、Boot strap、Layui等主流技术。</li><li>熟练掌握Linux、Nginx、Tomcat等服务器端技术和命令。</li><li>熟悉 Doris、StarRocks、ClickHouse、Hive、Neo4j、Elasticsearch、向量数据库5、本科及以上学历，计算机、软件工程、信息管理、数据科学、统计学、公共管理等相关专业优先6、具备较强的业务理解能力，能够从客户业务目标出发，抽象业务流程、数据关系、权限规则和系统功能7、具有较好的学习能力、沟通能力，能承受较强的工作压力与出差。</li><li>具备良好的团队合作精神，热爱专研技术，善于思考，能独立分析和解决问题。加分：有审计、财政、农业、住建、国资、医保、社保等政务行业项目经验。</li></ol>', '3-5年', '38e1225ce9a141800nJ429u4F1BV', '深圳 · 福田区 · 上步', '10-12K', 'Java, Spring, MySQL', 'java', 'https://www.zhipin.com/job_detail/38e1225ce9a141800nJ429u4F1BV.html', '交通补助, 节日福利');
INSERT INTO `jobs` VALUES (257, '奥哲', '互联网', '100-499人', 'C轮', '本科', '<p><strong>工作职责</strong></p><p>1. 负责低代码产品功能设计以及开发工作2. 有ERP相关开发经验并能够指导新人3. 熟悉敏捷开发模式，具备快速的学习能力</p><p><strong>任职资格</strong></p><ol><li>本科及以上学历，3年及以上⼯作经验；具备良好的 Java 基础，熟练掌握 Java 集合、并发类库的使⽤以及底层原理；</li><li>熟悉 MySQL 索引，⽇志，事务，MVCC 机制，分库分表原理，实现过 SQL 调优及分表3. 熟悉Redis缓存机制、具有实战经验4. 熟悉springboot技术栈，并具备实战经验；</li><li>熟悉常用设计模式，代码整洁。</li><li>有良好的团队沟通能力，学习能⼒，工作积极主动、拥有一定的自我驱动能力。</li></ol>', '3-5年', 'd6864deef10b8d230nV82Nq6GFNS', '深圳 · 南山区 · 科技园', '15-25K·15薪', 'MES开发经验, Java, 分布式经验, SpringCloud, Redis, Dubbo, SQL Server, Spring, ERP开发经验, 微服务经验, Zookeeper, MySQL, MyBatis, 云计算经验, Oracle', '后端工程师(J11244)', 'https://www.zhipin.com/job_detail/d6864deef10b8d230nV82Nq6GFNS.html', '定期体检, 节日福利, 团建聚餐, 年终奖, 健身房, 绩效奖金, 五险一金, 股票期权, 带薪年假, 补充医疗保险');
INSERT INTO `jobs` VALUES (258, '飞速创软', '计算机软件', '20-99人', 'B轮', '本科', '<p>​</p><p><strong>核心职责</strong></p><ol><li>负责低代码产品、OA系统或审批流程（如请假、报销）的后台设计与开发；</li><li>进行流程定义（BPMN 2.</li><li>的建模、部署、测试与维护；</li><li>管理流程实例的整个生命周期（启动、暂停、跳转、终止）；</li><li>通过Flowable提供的API（如RuntimeService, TaskService）与业务系统集成；技术栈要求​​：</li><li>语⾔基础​​：精通Java，熟悉集合、多线程等核⼼技术；</li><li>主流框架​​：熟练使⽤Spring、SpringBoot、SpringCloud、MyBatis等；</li><li>​​数据库​​：熟悉MySQL等数据库操作，了解Flowable的数据库表结构；</li><li>​​引擎技能​​：精通Flowable或Activiti等工作流引擎，并有实际项目经验；​​业务与软技能​​：</li><li>具备良好的沟通能⼒和团队协作精神；</li><li>拥有业务抽象能力，能将复杂的业务流程转化为清晰的流程模型。</li></ol>', '3-5年', 'd570d26c885b823503x42Ni_GVVT', '深圳 · 宝安区 · 新安', '8-13K', 'Java, 物联网经验, 大数据经验, 不接受居家办公, 微服务经验, SpringCloud, MySQL, MyBatis, 云计算经验, Spring, ERP开发经验', 'Flowable流程开发工程师', 'https://www.zhipin.com/job_detail/d570d26c885b823503x42Ni_GVVT.html', '五险一金, 股票期权, 带薪年假, 保底工资');
INSERT INTO `jobs` VALUES (259, '广州挚禾科技有限公司', '互联网金融', '20-99人', '', '大专', '<ol><li>⼤专及以上学历；</li><li>具备扎实的Java编程基础，深⼊理解IO、多线程、集合等基础框架；熟练掌握常⽤设计模式；</li><li>精通Spring全家桶（Spring Boot, Spring MVC, Spring Cloud, MyBatis/Hibernate），并有丰富的实战经验；</li><li>熟练使用MySQL，具备良好的数据库设计能力，熟悉索引优化、SQL调优；了解Redis等NoSQL数据库的使⽤场景</li></ol>', '3-5年', '8032689c11ca558a0nJ72NW7GVNQ', '深圳 · 南山区 · 科技园', '8-11K', 'Java, Spring, MySQL, 微服务经验, 不接受居家办公', 'Java', 'https://www.zhipin.com/job_detail/8032689c11ca558a0nJ72NW7GVNQ.html', '');
INSERT INTO `jobs` VALUES (260, '小多头', '互联网', '20-99人', 'A轮', '本科', '<p>【</p><p><strong>岗位职责</strong></p><ol><li>基于SpringBoot/SpringCloud微服务架构进行业务迭代，保障系统高可⽤、稳定性、性能；</li><li>负责数据库设计、SQL优化、慢查询治理，缓存、消息队列等中间件落地；</li><li>参与线上问题排查、性能调优、故障复盘，持续优化系统架构；</li><li>和产品、前端、测试协作，推动需求落地，输出接口⽂档、技术⽅案；</li><li>参与代码评审，沉淀开发规范，协助初级工程师成长。【</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机相关专业，3~5年Java后端开发经验；</li><li>扎实Java基础，熟练掌握集合、多线程、JVM原理、GC调优、IO、反射等；</li><li>熟练使用 Spring Boot、Spring Cloud、Spring MVC、MyBatis/MyBatis-Plus；</li><li>熟练MySQL，懂得索引优化、事务机制；熟练使⽤Redis，理解缓存策略、缓存击穿/雪崩解决方案；</li><li>至少掌握一款消息中间件（RocketMQ/Kafka），了解消息可靠性、幂等、顺序消息处理；</li><li>熟悉Git、Maven/Gradle，具备Linux服务器基础操作能力；# 加分项：</li><li>有广告平台、广告联盟业务开发经验，具备广告SDK对接、第三方广告渠道（穿山甲、优量汇、快手广告等）对接经验优先；熟悉广告归因、曝光/点击数据上报、广告计费逻辑者优先；</li><li>有金融、资管、基金、量化交易、行情系统相关开发经验优先；</li><li>了解数据治理相关体系，有数据清洗、指标口径管理、数据埋点、数据仓库对接经验；了解推荐系统、内容推荐算法基础，参与过推荐服务开发落地优先；</li><li>了解容器技术 Docker、K8s，熟悉JVM参数调优、链路追踪（OpenTelemetry）；</li><li>接触过分库分表、分布式锁、分布式事务、限流熔断(Sentinel/Resilience4j)；</li><li>掌握MongoDB、Elasticsearch等NoSQL；</li><li>具备高并发系统实战经验，有性能优化、线上故障排查经验；</li><li>了解OpenAPI接口规范、Prometheus/Grafana监控体系。【岗位</li></ol><p><strong>福利</strong></p><ol><li>，周末双休，法定节假日带薪休假；</li><li>惬意舒适的办公环境，高大上的办公设备，温馨的办公氛围；</li><li>五花八门的节日</li></ol><p><strong>福利</strong></p><ol><li>全勤奖、年终奖金、带薪年假的激励等；</li><li>设置人性化的员工休息室，有带饭习惯的宝宝冰箱、微波炉随便用；</li><li>购买五险一金，为你解决后顾之忧；</li><li>交通便利，周围商业配套设施完善，午休时间休闲逛街分分钟实现；</li><li>全体员工海内外旅游，已组织去了三亚&泰国，今年哪里呢？9、互补型团队，简单的人际关系，闪光点的碰撞和磨合。</li></ol>', '3-5年', 'ee7411a4b21f724c0nJ63dq4E1dV', '深圳 · 福田区 · 会展中心', '13-22K', 'Java, 大数据经验, 广告系统开发经验, 微服务经验, SpringCloud, MySQL, Kafka, Redis, MongoDB, SpringBoot, Spring, 广告SDK', 'Java后端开发工程师', 'https://www.zhipin.com/job_detail/ee7411a4b21f724c0nJ63dq4E1dV.html', '带薪年假, 加班补助, 零食下午茶, 定期体检, 团建聚餐, 五险一金, 节假日加班费, 节日福利, 补充医疗保险, 员工旅游, 年终奖, 股票期权');
INSERT INTO `jobs` VALUES (261, '合数教育', '在线教育', '100-499人', '未融资', '本科', '<p><strong>岗位职责</strong></p><p>负责公司业务系统的全栈开发工作，包括后端服务开发、前端页面实现及前后端联调优化</p><p><strong>任职要求</strong></p><ol><li>本科以上，3~5年工作经验，计算机相关专业;</li><li>具备2年以上全栈开发相关工作经验，有完整全栈项⽬落地经验优先。</li><li>精通微服务，熟练掌握Spring Cloud、 Spring Cloud Alibaba、 Dubbo，具备扎实的后端开发基础。</li><li>熟练掌握前端开发技术栈，包括Vue、 React、 Element-plus、 TypeSctipt、Tailwind CSS、uni-app等。</li><li>熟悉数据库设计与优化，熟悉主流数据库Mysql、 PostgreSQL。</li><li>具备良好的沟通能⼒和团队协作精神，责任⼼强，工作认真负责，具备较强的学习能力和问题解决能⼒;</li><li>有教育行业在线教育平台、直播平台建设、电商系统建设经验优先8、有基于新媒体(抖音/视频号/小红书/百家号等)电商或SaaS服务商(有赞/微盟)等开放平台集成研发经验优先\"</li></ol>', '3-5年', '658a30969344b6c90nJ62tu6FFBY', '深圳 · 福田区 · 石厦', '12-24K', 'Java, SpringCloud, Spring, Dubbo, MySQL, PostgreSQL', 'Java全栈开发工程师', 'https://www.zhipin.com/job_detail/658a30969344b6c90nJ62tu6FFBY.html', '员工旅游, 零食下午茶, 团建聚餐, 底薪加提成, 夜班补助, 绩效奖金, 生日福利, 节日福利, 保底工资, 意外险, 年终奖, 带薪年假, 五险一金');
INSERT INTO `jobs` VALUES (262, '学友科技', '计算机软件', '100-499人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>根据公司软件开发管理规范等要求，完成相关子系统/模块的编码，调试工作并确保安全、质量和性能；</li><li>维护和升级现有产品，快速定位并修复现有软件缺陷；</li><li>参与软件系统的方案讨论、技术调研、系统分析、重构、优化；</li><li>编写相关技术类文档；</li><li>编写系统功能代码。</li><li>与外部客户或内部团队保持有效沟通，确保需求理解准确，促进跨部门协作，推动项目顺利进行</li></ol><p><strong>任职要求</strong></p><ol><li>熟悉分布式系统的设计和应用，熟悉分布式、缓存、消息等机制;能对分布式常用技术进行合理应用，解决问题;</li><li>精通Java编码，多线程机制、IO机制、集合框架等;</li><li>熟悉Linux/Unix平台，熟悉关系型数据库 Mysql、Oracle的SQL脚本编写;</li><li>具备出色的沟通技巧，能够与外部客户及内部团队有效沟通，确保需求理解准确。</li><li>对技术研发极具热爱、钻研精神。重点∶1、开发能力强，基本功扎实;</li><li>做事态度端正，认真负责，热爱钻研技术，优秀沟通的能力!</li></ol><p><strong>福利待遇</strong></p><ol><li>五险一金：（养老、医疗、生育、工伤、失业保险）入职当月购买五险一金；</li><li>节日慰问：中秋节、端午节发放节日慰问品；</li><li>假期规定：公司提供按国家标准的有薪假期；</li><li>员工活动：不定期组织各项文娱活动，员工生日会，下午茶；</li><li>办公环境设施：全绿化、宽敞明亮的办公环境，配备冰箱、微波炉、饮水机7、上班时间：9:00-12:30 13:30-18:00 双休8、近上水径、下水径地铁站，治安稳定，经济交通便利，同时，房租便宜生活成本低。年轻团队、良好的办公氛围，舒适的办公环境，期待您的加入。</li></ol>', '3-5年', '464a7c4c458582e103d_2ty1GVVT', '深圳 · 龙岗区 · 布吉', '17-18K', 'MySQL, 分布式技术, 多线程, 微服务架构, Spring, Oracle, 后端开发, SQL', 'java开发软件工程师', 'https://www.zhipin.com/job_detail/464a7c4c458582e103d_2ty1GVVT.html', '年终奖, 零食下午茶, 底薪加提成, 生日福利, 夜班补助, 保底工资, 节日福利, 五险一金, 全勤奖, 绩效奖金, 带薪年假, 交通补助');
INSERT INTO `jobs` VALUES (263, '上海恒格信息', '互联网金融', '100-499人', '不需要融资', '本科', '<ol><li>本科2年以上或专科3年以上计算机、信息管理相关专业优先。</li><li>具备分布式系统开发和设计经验，熟悉缓存，消息、服务治理、容灾、分布式一致性等机制；</li><li>有扎实的 JAVA 基础，熟悉IO、多线程、集合，熟练使用 spring 框架进行編程；</li><li>熟悉dubbo 、redis、mongo 使用⽅法5、熟悉mysql、oracle、tdsal数据库使⽤，并能熟练进⾏表设计和SQL 优化；</li><li>熟悉常用的开源框架．对开源框架源码有研究，熟练运用 git7.具有较强的学可能⼒，沟通协调能力，强烈的责住心、工作踏实，善开总结以及交档編写能力；</li><li>具备良好的分析解决向题能力，具有业务需求分析能力，责任感强、爱思考、沟通能力和抗压能力．能与各种背景人员合作；</li></ol>', '3-5年', '33070a640bd4b8360nR529S4GFpW', '深圳 · 福田区 · 车公庙', '9-12K', '', 'java开发', 'https://www.zhipin.com/job_detail/33070a640bd4b8360nR529S4GFpW.html', '带薪年假, 股票期权, 节日福利, 免费班车, 定期体检, 五险一金');
INSERT INTO `jobs` VALUES (264, '绿之源能源', '电力/热力/燃气/水利', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><p>负责 Java / Spring Boot 后端服务的设计、开发与维护；负责系统接口、业务模块及数据库相关功能开发；参与 PostgreSQL、MySQL、ClickHouse、Redis 的使⽤与优化；负责 Linux、Docker、Nginx 环境下的项⽬部署与问题排查；参与系统性能优化和技术⽂档编写。</p><p><strong>任职要求</strong></p><p>计算机相关专业本科及以上学历（3年以上开发经验）熟悉 Java，掌握 Spring Boot、常用设计模式；具备良好的数据结构与算法基础；熟悉 PostgreSQL、MySQL，了解 ClickHouse、Redis；了解 Linux 常用命令、Docker 和 Nginx；具备良好的代码规范、问题分析和团队协作能⼒。</p>', '3-5年', '69984d4ecb72a38b0nJ70t27GFFY', '深圳 · 罗湖区 · 东门', '12-18K·13薪', 'Golang, Nginx, Java, Docker, PostgreSQL, MySQL, Kafka, Redis, Spring Boot, Spring, Python', '中高级java开发工程师', 'https://www.zhipin.com/job_detail/69984d4ecb72a38b0nJ70t27GFFY.html', '员工旅游, 团建聚餐, 零食下午茶, 带薪年假, 定期体检, 加班补助, 五险一金, 节假日加班费, 节日福利, 年终奖');
INSERT INTO `jobs` VALUES (265, '恒芯伟创', '电子/半导体/集成电路', '100-499人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>参与产品需求分析，负责核心功能模块的设计与开发，确保系统稳定、高效。</li><li>负责后端服务的架构优化与代码重构，编写高质量、可维护的Java代码。</li><li>负责前端页面与交互的开发，与UI/UX团队配合，实现良好的⽤户体验。</li><li>独⽴完成模块的数据库设计、接口定义及⽂档编写。</li><li>参与技术难点攻关，持续优化系统性能，提升系统安全性。</li><li>协助测试人员完成功能测试，修复线上问题，保障系统平稳运行。</li><li>参与团队技术分享，推动技术规范与流程的改进。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机相关专业，3年以上开发经验（优秀者可放宽）。</li><li>具备良好的编码习惯，注重代码可读性和可维护性。</li><li>有较强的逻辑思维能⼒和问题分析能力，能够独立解决复杂问题。</li><li>良好的团队协作精神，善于沟通，积极主动，有责任心。</li><li>对新技术有好奇心，能够快速学习和应用。</li></ol>', '3-5年', 'afe5c69af40e71310nV_09W_EFJX', '深圳', '18-23K', '', '高级全栈开发工程师', 'https://www.zhipin.com/job_detail/afe5c69af40e71310nV_09W_EFJX.html', '生日福利, 五险一金, 节日福利, 交通补助, 团建聚餐, 零食下午茶, 包吃, 全勤奖, 带薪年假, 定期体检, 餐补, 工龄奖, 住房补贴, 员工旅游');
INSERT INTO `jobs` VALUES (266, '拜特科技', '计算机软件', '100-499人', '未融资', '本科', '<p>一、 岗位定位我们负责建设全司统一的银企直连平台，是司库系统资金流转的“核心枢纽”。你将直⾯⾦融级⾼并发、数据强一致性和异构系统适配三大挑战，负责对接国内外银⾏的支付、外汇、票据等核心接口，并赋能司库系统</p><p><strong>二、 岗位职责</strong></p><p>1、银企产品核心开发 负责公司银企平台的需求分析、概要设计及核心代码编写，主导复杂业务场景的技术方案设计，确保系统的高可用、高性能及可扩展性 核心银行渠道（银企直连）的对接开发，包括但不限于账户余额、交易明细、批量/单笔支付、电子回单、外汇兑换、票据承兑/贴现等接口的封装与落地，统一报文网关层设计2、系统性能与数据一致性保障 负责批量付款任务调度优化，利用Java多线程（JUC、线程池）与异步编排技术提升系统吞吐量，解决银行限流与业务并发之间的矛盾 严格保障资金交易的幂等性3、存量系统维护与迭代 负责存量银企产品的日常维护、生产问题排查及迭代升级</p><p><strong>三、 任职要求</strong></p><p>1、第一学历是统招本科以上学历，学信网可查（硬性条件，不符合请不要投递），计算机相关专业，3年以上开发经验2、Java基础：扎实的Java编程基础，深入理解IO多路复用、并发编程（JUC包源码、锁机制）、JVM内存模型及类加载机制，具备实际调优经验3、设计能力：熟悉常用设计模式（工厂、策略、责任链等）并在项目中有实际落地4、技术框架：精通Spring Framework（IOC、AOP、事务传播）、Spring Boot5、安全加密：熟悉常见的加解密算法（RSA/AES/SM2/SM4）及签名验签机制，有SSL/TLS双向认证配置经验6、数据库与中间件：精通MySQL、Oracle（索引优化、事务隔离、行锁）、Redis（分布式锁），熟练使用至少一种MQ（RocketMQ/RabbitMQ）</p>', '3-5年', '8eae810a3f27afdb0nJ73t66E1JQ', '深圳 · 南山区 · 蛇口', '15-23K·13薪', 'Java, Spring, SpringCloud, MyBatis, JVM, MySQL, Redis, Oracle, 微服务经验, 分布式经验, 架构设计经验', 'Java软件工程师（银企）', 'https://www.zhipin.com/job_detail/8eae810a3f27afdb0nJ73t66E1JQ.html', '绩效奖金, 带薪年假, 节日福利, 零食下午茶, 五险一金, 团建聚餐, 住房补贴, 年终奖, 底薪加提成, 补充医疗保险, 定期体检, 员工旅游, 股票期权');
INSERT INTO `jobs` VALUES (267, '某大型储能公司', '储能', '100-499人', '不需要融资', '本科', '<ol><li>设备数据处理，对接收的设备数据进⾏清洗、解析、规则处理及落库，⽀持设备监控、数据 分析与AI模型训练。</li><li>MQTT/WebSocket 通信服务，搭建设备与云端的实时双向通信服务，保证消息传输的稳定性 与低延迟。 消费类业务支持 4. 搭建对接服务器，接入蚂蚁集团后台数据，包括订单、交易、⽤户等业务数据的实时同步与 处理。</li><li>数据整理与加工，对消费类数据进行清洗、转换、聚合，建立数据模型，支持业务分析与决 策。</li><li>负责后台API开发，包括支付、订单、会员、设备管理等核心模块的接口设计与实现。</li><li>对接第三方平台（支付宝、微信、AI服务商等），处理回调、通知、数据同步等逻辑。 运维与部署 8. 负责服务器的日常运维，日志、监控、部署相关管理。</li><li>使用 GitLab CI / Jenkins / Docker 等工具完善 CI/CD 流水线。</li></ol><p><strong>任职要求</strong></p><p>必备要求 熟练掌握 Java 后端开发，理解 Spring Boot / Spring Cloud 生态。熟悉 MQTT、WebSocket 等 IoT 通信协议，有设备接入与管理经验。 熟悉 MySQL / Redis 等常用数据存储。 熟悉 RESTful API 设计及 HTTP/HTTPS 协议。 了解 IoT 设备认证、安全等基础知识。 了解第三方平台对接流程（如支付宝开放平台、微信开放平台等）。 熟悉 Linux 基础操作，能进行常规运维和排错。 熟悉 Git、Maven/Gradle、Docker 等工具链。 加分项 有AI玩具、智能硬件、儿童玩具等领域的后端开发经验。 有大规模IoT设备接入与管理经验，熟悉设备影子、OTA升级等功能。 熟悉 CoAP、LwM2M 等轻量级IoT协议。 有AI服务对接经验（如语音识别、图像识别、对话机器人等）。 有电商/消费类/支付/订单系统开发经验。 有蚂蚁集团（支付宝）、微信支付等第三方平台对接经验。 熟悉 Go 语言开发，有高性能服务开发经验。 熟悉 Kafka、RocketMQ、EMQX 等消息中间件的使用与调优。 有时序数据库（InfluxDB、TDengine）使用经验。 有多租户系统设计经验。 有大规模数据接入、ETL、流处理经验。 熟悉数据建模、数据仓库相关知识。 具备一定架构能力，能推动项目研发效率优化。</p>', '3-5年', '8922badb8dcdf4180nF_3t--EFFV', '深圳', '15-25K', 'Java, 物联网经验, MQTT, WebSocket, 智能语音', 'java后端开发', 'https://www.zhipin.com/job_detail/8922badb8dcdf4180nF_3t--EFFV.html', '团建聚餐, 绩效奖金, 五险一金, 带薪年假, 零食下午茶, 定期体检, 股票期权, 员工旅游, 补充医疗保险, 年终奖');
INSERT INTO `jobs` VALUES (268, '某中型智能硬件公司', '智能硬件', '100-499人', '', '大专', '<p><strong>工作职责</strong></p><ol><li>负责仓储机器人调度平台开发工作，根据业务规格说明书，能够快速进行代码实现；</li><li>主动按时⾼质量完成需求开发和⾃测；</li><li>配合PM⾼质量完成各项开发任务，包括不限于需求评审，系统测试用例编写，代码评审与问题或工单定位修改等。</li><li>熟练运⽤各种问题排查方法，快速定位系统问题根因并修复；</li><li>输出并分享高质量的交付文档进行知识沉淀。</li></ol><p><strong>任职资格</strong></p><ol><li>全日制本科学历，计算机相关专业，3年及以上Java开发经验，JAVA基础扎实，熟练掌握io、多线程、集合等基础框架，熟悉JVM原理；</li><li>良好的团队合作能力，流畅的口头和书面表达能力，严谨的工作态度，有极客意识，求知欲强 ，思路活跃。</li><li>熟悉常用开源框架的原理和内部机制，如Spring Cloud等，能够熟练并合理使用；</li><li>熟悉数据库，redis、RPC等中间件，有良好的设计模式及实际落地能力；</li><li>自驱力强且有强烈的技术热情和钻研精神，热爱新技术；</li></ol>', '3-5年', '8bd3ce90ab889b470nF82N26FFRR', '深圳', '17-25K', '', 'java后端开发岗', 'https://www.zhipin.com/job_detail/8bd3ce90ab889b470nF82N26FFRR.html', '');
INSERT INTO `jobs` VALUES (269, '鸿嘉利新能源有限公司', '新能源', '100-499人', '未融资', '本科', '<p><strong>岗位职责</strong></p><p>1. 负责公司软件产品的服务端研发工作2. 参与需求讨论和分析，能够分解任务，提出合理的设计方案3. 能够高质量的完成所负责模块的编码工作，并指导和Review其他同事的编码4. 对现有技术架构进行优化改进</p><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机相关专业，3年以上Java开发经验；</li><li>掌握TCP/IP协议：MQTT协议或OCPP协议，有新能源充电或物联网平台开发经验；</li><li>具备扎实的JAVA知识储备（JVM、集合数据结构、面向对象，多线程、NIO）及掌握HTTP协议，有良好的编码习惯，有较强的代码质量控制意识和良好的技术文档能力；</li><li>熟练运用Java，熟悉SpringCloud、SpringBoot、Spring、Mybatis等框架，能对主流框架源码有一定了解，能快速掌握主流开发框架；</li><li>熟悉Mysql、PostgreSql并能根据业务需求进行数据库设计与优化； 熟悉Elasticsearch搜索引擎；熟悉分布式架构、Redis缓存、MongoDB、消息队列等更佳；</li><li>熟悉git、svn、Maven原理及日常使用；</li><li>熟悉常用的Linux命令，熟悉服务器应用部署；</li><li>了解微服务架构并有项目经验者优先考虑；</li><li>具备良好的设计模式理解能力，具备较好的算法基础，有团队管理经验者优先10. 良好沟通能力和团队协作能力，具有较强的工作责任心，快速学习能力，乐观积极进取11、有物联网平台开发经验优先，有高并发处理经验优先；</li></ol>', '3-5年', 'd559c0e8851c57da03Z-3dm7F1RV', '深圳 · 光明区 · 光明', '9-14K', 'JVM, Java, Nginx, 不接受居家办公, 微服务经验, PostgreSQL, SpringCloud, MySQL, Netty, Redis, MongoDB', 'Java', 'https://www.zhipin.com/job_detail/d559c0e8851c57da03Z-3dm7F1RV.html', '带薪年假, 加班补助, 节日福利, 包吃, 团建聚餐, 全勤奖, 包住, 年终奖, 宿舍有空调, 工龄奖, 五险一金, 绩效奖金, 包住');
INSERT INTO `jobs` VALUES (270, '广志信息', '互联网', '100-499人', 'A轮', '本科', '<p>外包岗位，介意勿投。工期3-6个月必要岗位：主要是英语要好，技术栈不限，python, java, .net都可以，但是要愿意跨技术栈学习</p><p><strong>岗位职责</strong></p><p>负责后端服务的设计、开发与维护，参与系统架构演进。根据项目需要，灵活使用多种技术栈完成开发任务，不限于 Java/Go/Python/C#/Net 等。参与数据平台或业务系统的后端开发，包括 API 设计、性能优化与问题排查。借助 AI 辅助编程⼯具，⾼效完成跨技术栈的代码编写、重构与调试。与海外团队或客户进⾏技术沟通与协作（英语工作环境）。编写必要的技术文档，参与代码审查与团队技术分享。</p><p><strong>任职要求</strong></p><p>本科及以上学历，计算机相关专业。3 年以上后端开发经验，不限定特定技术栈，具备快速学习新语⾔/框架的能力。熟悉至少一种主流后端语言及其生态（如 Java/Spring、Go/Gin、Python/Django、C#/.NET 等）。了解常见数据库、缓存、消息队列及 RESTful API 设计。乐于使用 AI 工具（如 Copilot、ChatGPT 等）辅助编程，愿意尝试新技术栈。具备良好的跨文化沟通与协作能力。英语要求：口语流利，能进行日常技术沟通与技术方案讨论。优先条件：有海外工作/学习经历，或有外企工作背景。有跨技术栈项目经验（如从一种语言迁移到另一种，或同时维护多种语言）。</p>', '3-5年', 'b970705307e76f5b0nF80tu7F1BX', '深圳 · 龙岗区 · 坂田', '14-15K', 'Java, Python, C#', '后端开发工程师（英语流利）', 'https://www.zhipin.com/job_detail/b970705307e76f5b0nF80tu7F1BX.html', '股票期权, 加班补助, 五险一金, 节日福利, 带薪年假, 员工旅游, 零食下午茶, 年终奖');
INSERT INTO `jobs` VALUES (271, 'firstsing', '电子商务', '0-20人', '未融资', '大专', '<p>【高级/中级】全栈 APP 开发工程师（Java + Python AI + 爬虫） 薪资待遇8K - 20K（根据能力可⾯议） | 13薪 / 绩效奖⾦ ⼯作地点深圳</p><p><strong>岗位职责</strong></p><p>APP & Web 端全栈开发： 负责公司核心产品（firstsing.com 及 guiyuan 系列）的前后端架构设计、核心功能研发与性能优化。微服务与即时通讯开发： 基于 Java (Spring Cloud) 维护与重构后端系统，优化即时通讯（WebSocket / 离线消息 / 游标分页）、消息可靠性及接口安全凭证（HMAC）。AI 微服务与⾳视频处理： 负责 Python AI 节点（FastAPI）的构建与维护，集成 OCR 识别（PaddleOCR）、音视频处理（FFmpeg/OpenCV 帧采样与质量分析算法）及 AI Gateway 跨服务调用。数据采集与爬虫引擎： 负责多源媒体资源（图片/视频/网页数据）的高效抓取、解析、反爬突破、防盗链处理及数据清洗入库。</p><p><strong>任职要求</strong></p><ol><li>Python AI & 多媒体工程化（加分与必备）熟练掌握 Python (FastAPI / Django)，具备将 AI 模型/算法工程化落地为生产级 API 的能力。熟练使用 FFmpeg 与 OpenCV，有音视频处理、多帧采样、图像质量评估（如 Laplacian 梯度方差/信息熵/亮度检测）经验者优先。熟悉或使用过 PaddleOCR / EasyOCR 等 OCR 工具，能独立维护图像/文本识别微服务（ocr-service）。</li><li>爬虫与数据采集精通 Python 爬虫（Scrapy / Selenium / Playwright），具备处理 HTTP/HTTPS 多源提取、限流、代理池搭建、随机 UA 及编码识别（chardet）的实战经验。熟悉常见的反爬策略与验证码识别方案，能应对复杂的图片/视频防盗链与解析抓取。</li><li>前端与跨端能力熟练掌握 Vue3 / TypeScript / UniApp，熟悉 Pinia / Vuex 状态管理及 RESTful API 契约式联调。具备富文本/动态组件开发能力，了解 Viewer.js、Cropper.js 等媒体处理库的使用。加分项具备 LLM / Agent / RAG 落地实践经验，了解 Model Gateway 或 LangChain/LlamaIndex 框架者优先。有独立独立开发并上架过 iOS/Android/小程序 APP 全栈项目经验者优先。熟练使用 Claude Code、Cursor、GitHub Copilot 等 AI 编程工具进行高效 Debug 和重构。我们能提供核心业务主导权： 直接参与出海平台与 AI 前沿产品的架构升级，技术自主度高。极客氛围： 拥抱最新 AI 辅助开发工具，鼓励使用 AI 赋能日常写码与效率提升。扁平化管理： 结果导向，沟通高效，无无意义加班与内耗。</li></ol>', '3-5年', '5afd18e8e7cfb3770nJ43NS7ElNQ', '深圳 · 宝安区 · 福永', '8-13K·13薪', 'Java, Python, Spring, SpringCloud, MyBatis, Nginx, Docker, MySQL, Redis, 架构设计经验, 微服务经验, 分布式经验, 音视频经验, 不接受居家办公', '全栈 APP 开发工程师Java  Python AI 爬虫', 'https://www.zhipin.com/job_detail/5afd18e8e7cfb3770nJ43NS7ElNQ.html', '带薪年假, 节日福利, 员工旅游, 五险一金, 包吃, 包住, 年终奖');
INSERT INTO `jobs` VALUES (272, '得理科技', '计算机软件', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>boss负责搜索，资讯类app后台开发工作；</li><li>负责SAAS类平台产品后台开发工作。</li></ol><p><strong>任职要求</strong></p><ol><li>本科以上学历，3年以上工作经验；</li><li>精通java语言，对java面向对象软件结构有一定理解；</li><li>能够熟练掌握spring等主流开发框架；</li><li>熟练使用mysql数据库，对数据库表有独立设计能力；</li><li>熟悉https协议，redis相关协议，熟悉分布式、缓存、消息等机制；</li><li>良好的学习能力、沟通能力、适应能力、责任心强，能在压力下独立解决问题，具有主人翁精神。</li></ol>', '3-5年', 'a7f216f223ba32b403d-3dm0EVJZ', '深圳 · 福田区 · 上步', '10-15K', 'Java, SAAS, AI, Redis, Spring', '后台开发工程师', 'https://www.zhipin.com/job_detail/a7f216f223ba32b403d-3dm0EVJZ.html', '节日福利, 绩效奖金, 定期体检, 五险一金, 团建聚餐, 零食下午茶, 生日福利, 带薪年假, 股票期权');
INSERT INTO `jobs` VALUES (273, '上海博达瑞科技', '互联网', '100-499人', '未融资', '本科', '<p>【岗位概述】1. 计算机以及相关专业，3年以上JAVA核心开发经验2. 扎实的 Java 基础，熟悉 JVM 原理以及调优，熟悉 JavalO 、多线程、网络等方面编程和底层逻辑3. 精通常⽤设计模式，熟练使⽤ Spring 、 SpringBoot 、 MyBatis 等常⽤的 Java 框架，并有深入理解4. 熟悉 Mysql，熟练使用 SQL 查询语⾔，了解事务、索引等技术的机制和原理5. 熟练使用互联网项目常用的中间件，如 Redis 、 Kafka 、 Nacos 等，至少对其中一种掌握实现原理6. 具备Linux系统环境软件开发技能，了解Docker、Kubernetes等容器编排相关技术7. 熟练使用开发、代码管理及打包工具；8. 有良好的技术文档编写能力；</p><p><strong>任职资格</strong></p><ol><li>至少3年以上Java开发经验，有扎实的数据结构和算法基础；</li><li>熟悉常用的Java开发框架，例如Spring等；</li><li>熟练使用MySQL等数据库，有良好的SQL语言功底；</li><li>熟悉分布式、微服务架构，并具备相关实际项目经验；</li><li>具备良好的沟通和团队合作能力，注重代码质量和项目效率；</li><li>积极主动，具备快速学习能力和问题解决能力。其他 有AI大模型项目经验优先，抗压能力好，沟通能力好优先。</li></ol>', '3-5年', '52d9205789343bec0nVz3tu_EFtX', '深圳 · 南山区 · 科技园', '14-22K', 'Java, 不接受居家办公, SpringCloud, MySQL, Kafka, MyBatis, Redis, Oracle', 'java开发中级工程师', 'https://www.zhipin.com/job_detail/52d9205789343bec0nVz3tu_EFtX.html', '');
INSERT INTO `jobs` VALUES (274, '深圳琪乐科技有限公司', '计算机软件', '20-99人', '未融资', '本科', '<p><strong>基本要求</strong></p><ul><li>本科及以上学历，计算机、人工智能、软件工程、数学等相关专业，3-5年及以上AI相关开发经验（优秀应届生可放宽）。</li><li>具备良好的编码习惯，精通Python编程语⾔，熟悉Java/Go者优先。</li><li>具备较强的问题解决能⼒、逻辑思维能⼒，善于学习新技术，有良好的沟通协作能力和责任心。</li><li>了解⼤模型基本原理，对AI智能体、RAG、工具调用等相关技术有浓厚兴趣和探索欲</li></ul><p><strong>岗位职责</strong></p><ul><li>负责AI智能体（AI Agent）核心功能开发、调试与优化，包括自主规划、任务拆解、工具调用、记忆管理等核心模块，确保智能体具备高效的自主决策与执行能力。</li><li>基于LangChain/LangGraph等主流框架，搭建智能体开发架构，实现智能体对话交互、任务协同能力。</li><li>负责检索增强生成（RAG/GraphRAG）相关开发，包括向量数据库（Milvus/Weaviate/Pinecone）的选型、知识库构建、检索策略优化，解决大模型幻觉问题。</li><li>参与AI智能体的需求分析、技术方案设计，结合业务场景（如办公自动化、客户服务、行业辅助等），落地可复用的智能体解决方案。</li><li>负责智能体系统的工程化部署、性能优化、bug修复，保障系统稳定运行，提升用户体验。</li><li>跟踪AI智能体、大模型领域前沿技术（如多智能体协同、多模态交互），并应用到实际开发中，推动技术迭代升级。</li><li>配合产品、测试等团队，完成需求对接、功能验收、文档编写等工作。</li></ul>', '3-5年', 'fcd04bb01cee4b0e0nZ_09u6FVNR', '深圳 · 龙华区 · 民治', '12-17K', 'Java, 大数据经验, 团队管理经验, 不接受居家办公, Python', 'AI智能体开发工程师', 'https://www.zhipin.com/job_detail/fcd04bb01cee4b0e0nZ_09u6FVNR.html', '员工旅游, 节日福利, 交通补助, 五险一金, 加班补助, 零食下午茶, 带薪年假, 年终奖');
INSERT INTO `jobs` VALUES (275, '深圳华资数智科技', '计算机软件', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>主导系统架构设计与核心模块开发，完成高质量的代码编写和单元测试；</li><li>根据项目任务完成相应功能模块的设计、开发与优化工作；</li><li>带领开发团队成员进⾏技术⽅案调研与⽂档编写，推动项目顺利实施；</li><li>对现有系统进行维护和性能调优，保障系统稳定性和可扩展性；</li><li>完成上级安排的其他技术开发相关⼯作。</li></ol><p><strong>任职要求</strong></p><ol><li>具备扎实的Java编程基础，熟悉常用设计模式和开发框架；</li><li>熟悉分布式系统设计与应用，了解主流中间件技术；</li><li>具备良好的沟通能力和团队协作意识，能高效配合项目推进；</li><li>有较强的学习能力和问题解决能力，能独立承担开发任务；</li><li>能够在规定时间内保质保量完成分配的</li></ol><p><strong>工作内容</strong></p><p>。</p>', '3-5年', 'a07ef88f9749031c0nJ52964GFtS', '深圳 · 福田区 · 车公庙', '15-20K', 'Java, Spring, Redis', 'JAVA开发', 'https://www.zhipin.com/job_detail/a07ef88f9749031c0nJ52964GFtS.html', '定期体检, 员工旅游, 法定节假日三薪, 夜班补助, 五险一金, 带薪年假, 意外险, 通讯补贴, 团建聚餐, 节假日加班费, 生日福利, 零食下午茶');
INSERT INTO `jobs` VALUES (276, '爱商在线', '计算机软件', '100-499人', 'B轮', '大专', '<p><strong>任职要求</strong></p><p>1、熟悉Java语言、了解Python语言2、熟悉Spring AI、LangGraph4j 等至少一个AI开发框架3、了解开源AI应⽤与⼯作流⾃动化平台，比如Dify、N8N等AI中台架构与规划能力 4、了解AI中台的整体技术架构规划与演进，覆盖⼤模型应用、AI能力封装等5、扎实的AI核心技术与云原生工程功底 a) 熟悉掌握Python、Java语言 b) 熟悉Spring AI、LangGraph4j等至少一个AI开发框架 c) 了解开源AI应用与工作流自动化平台，比如Dify、N8N等6、业务理解与项目管理能力 a) 能深入理解业务需求，将业务痛点转化为技术架构方案，推动 AI 技术与业务的深度融合 加分项 a) 了解NLP、机器学习、深度学习原理，熟悉 TensorFlow、PyTorch 等主流框架，了解 CNN、Transformer、强化学习等常见算法 b) 了解AI模型训练、评估、部署、调优的全流程 c) 了解微服务架构与分布式系统设计，熟练掌握容器化技术（Docker、Kubernetes）、消息队列、缓存等中间件 d) 了解大模型部署优化、模型性能提升、算力资源调度及数据安全等核心难点的调研与方案论证 e) 具备优秀的团队管理能力，能统筹算法、后端、前端、运维等跨部门团队，推动复杂技术方案落地执行</p>', '3-5年', '9a9e583ce9b063cb0nF73tu8F1NW', '深圳 · 南山区 · 大学城', '15-20K', 'Java, 团队管理经验, 不接受居家办公, Spring, ERP开发经验, Python', 'java开发工程师(自研)', 'https://www.zhipin.com/job_detail/9a9e583ce9b063cb0nF73tu8F1NW.html', '带薪年假, 零食下午茶, 餐补, 节日福利, 五险一金, 员工旅游, 定期体检');
INSERT INTO `jobs` VALUES (277, '深圳市华鑫源公司', '进出口贸易', '20-99人', '未融资', '大专', '<p><strong>工作内容</strong></p><ul><li>负责公司网站及应用的后端开发服务，优化MySQL/PostgreSQL+Redis性能；</li><li>负责开发公司网站及应用的后端功能，包括API接口、数据存储等，支撑前端/移动端数据需求；</li><li>参与项目的需求分析、设计和评审工作；</li><li>负责公司网站及应用的技术选型和架构设计，主导系统升级，确保项目能够按时交付并满足客户需求；</li></ul><p><strong>主要职责</strong></p><ul><li>熟练掌握Java、Python编程语言，了解常用的Python库和框架，如Django、Flask等；</li><li>熟悉Linux系统，能够通过命令行进行服务器部署和管理；</li><li>了解常见的数据库系统，如MySQL、PostgreSQL等；</li><li>熟悉常用的代码管理工具，如Git等；</li><li>3-5年以上经验，逻辑清晰，具备团队协作能力。 加分项：物联网协议/云平台/自动化脚本经验。</li></ul>', '3-5年', '6de14996a0e875c703F-2t-6FFtZ', '深圳 · 龙岗区 · 横岗', '10-15K', 'Java, Python, Spring, MySQL, 架构设计经验', '后端开发工程师', 'https://www.zhipin.com/job_detail/6de14996a0e875c703F-2t-6FFtZ.html', '五险一金, 底薪加提成, 团建聚餐, 带薪年假, 节日福利, 绩效奖金, 零食下午茶, 年终奖, 员工旅游');
INSERT INTO `jobs` VALUES (278, '甄才智能', '人工智能', '0-20人', '', '本科', '<p>boss负责公司业务系统后端功能开发、接口设计和服务端逻辑实现。参与需求评审、技术方案设计、数据库设计和核心模块开发。持续优化系统性能、稳定性和可维护性，解决线上问题和技术难点。与产品、前端、测试等团队协作，保障项目按时高质量交付。参与代码评审、技术⽂档编写和⼯程规范建设。本科及以上学历，计算机、软件⼯程或相关专业优先。3年以上Java后端开发经验，具备良好的编码习惯和工程意识。熟悉Spring Boot、Spring Cloud、MyBatis等常用Java技术栈。熟悉MySQL、Redis、消息队列等常⽤中间件，有实际项目经验。理解常见设计模式、接口设计、数据库设计和系统性能优化方法。具备良好的沟通协作能力、问题分析能力和责任心。有高并发、分布式系统、微服务架构经验者优先。有电商、SaaS、支付、供应链或企业服务项目经验者优先。熟悉Docker、Kubernetes、CI/CD或云原生相关技术者优先。</p>', '3-5年', 'a5d8c832e41595570nF_39q9FVRX', '深圳 · 南山区 · 科技园', '15-25K', 'Java, Spring Boot, MySQL', 'Java开发工程师', 'https://www.zhipin.com/job_detail/a5d8c832e41595570nF_39q9FVRX.html', '五险一金');
INSERT INTO `jobs` VALUES (279, '同舟技术', '计算机软件', '100-499人', '未融资', '大专', '<p><strong>岗位职责</strong></p><ol><li>负责货拉拉大数boss据服务平台设计、开发、监控，保障其高效稳定运行；</li><li>结合大模型（LLM）、AI Agent等新技术，探索⼤数据平台智能化能⼒；</li><li>参与服务性能调优(资源调度、计算/查询优化)、服务稳定性保障、灾备⽅案设计和压测演练;</li></ol><p><strong>岗位要求</strong></p><ol><li>3~5年或以上的大数据开发从业经验，有大型分布式系统设计&开发经验，具有良好的Java功底，熟悉SOA开源应⽤框架，如Spring Boot，Spring Cloud，Mybatis等；</li><li>使用过LangChain、RAG、Dify等任一框架，或有Prompt工程、RAG、Agent相关实践经验者优先；</li><li>熟练掌握数据库技术(如Mysql、Redis)，熟悉数据库设计和优化知识，有实际生产项目应用经验；</li><li>对大数据基础架构和平台底层原理有深度理解和丰富开发经验, 对复杂系统的性能优化和稳定性提升有实战经验，熟悉计算引擎(Spark、Flink、Tez等)OLA、P引擎(Doris、Presto等)、linux操作系统，能够独立完成线上问题排查及解决;</li><li>具备良好编程习惯，有良好沟通协作能力，能够独立完成任务；</li><li>有AI大模型项目经验优先、有js、python、go等语言开发经验优先；</li></ol>', '3-5年', 'b8d4b2fa598713940ndy3N21F1BT', '深圳 · 福田区 · 梅林', '13-15K', '', 'JAVA开发', 'https://www.zhipin.com/job_detail/b8d4b2fa598713940ndy3N21F1BT.html', '零食下午茶, 节日福利, 员工旅游, 带薪年假, 五险一金');
INSERT INTO `jobs` VALUES (280, '深圳市赤道供应链', '跨境物流', '100-499人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>配合产品经理参与项目系统设计,依据功能设计书、数据库设计文档，编制软件详细设计书;</li><li>按照需求设计，完成代码设计、代码编写及相关的功能测试，修复代码缺陷，确保软件高质量。</li><li>分析并解决软件开发过程中的问题，持续提升系统性能和稳定性，扫除技术风险。</li><li>配合团队leader工作，为团队提供产品技术⽀持，完成软件⽣命周期中的⽂档编写。</li></ol><p><strong>任职要求</strong></p><ol><li>熟悉分布式系统的理论,有高并发系统的架构设计、开发和调试经验者优先；</li><li>有微服务架构设计或开发工作经验，理解微服务架构的基本原则与思想，熟悉Netty、SpringBoot、SpringCloud或Dubbo等相关技术；</li><li>熟练掌握mysql，memcached，redis、Mongodb等主流数据存储系统,可对系统进⾏性能调优；熟悉mqtt等消息中间件,有缓存系统、服务化管理、业务监控的经验优先;4熟悉常用开源框架的应用和原理，如：Zookeeper，Redis，Kafka/RabbitMQ, Spring, Mybatis ；</li><li>熟练使用Maven、Git、gitlab、Jkens等项目构建管理工具6、熟练掌握spark、hive、storm、flink等优先；</li><li>熟悉JVM调优，内存调优，有网络相关的基础能力，熟悉多线程编程，内存管理，设计模式；（中高级）。</li></ol>', '3-5年', '1c87c77d1151fe8e0nF82N65FlJU', '深圳 · 龙华区 · 民治', '10-15K', 'Java, 供应链开发经验, MySQL, MyBatis, Redis, MongoDB, Spark, 区块链经验, ERP开发经验', 'Java开发工程师', 'https://www.zhipin.com/job_detail/1c87c77d1151fe8e0nF82N65FlJU.html', '加班补助, 员工旅游, 五险一金, 定期体检, 意外险, 补充医疗保险, 节日福利');
INSERT INTO `jobs` VALUES (281, '大望谷', '互联网', '20-99人', '未融资', '本科', '<p>岗位boss</p><p><strong>职责</strong></p><ol><li>能独立完成系统设计、模块拆分、计划制定及开发任务；</li><li>负责核心代码的编写、系统重构以及系统的性能优化与改进；</li><li>参与项目的需求分析、系统设计、编码、项目内测试及相关文档编写工作；</li><li>指导并协调项目成员完成相关工作，并能够对项目成员进行培训工作；</li><li>参与开发过程中相关新技术的究和验证；</li></ol><p><strong>任职条件</strong></p><p>1、3-5年以上金融行业项目经验，独自负责过完整的复杂项目，有金融行业、支付平台等技术架构设计经验者优先2、java基础扎实，对集合、网络通讯、反射、异常处理、多线程等有较深入的了解，具备良好的面向对象设计技巧3、精通主流Java开发框架，如Spring Cloud、Dubbo、Spring Boot、 ElasticSearch、Zookeeper等，有大中型项目开放式API设计开发实践经验4、具有丰富的Mysql数据库设计与开发经验；Redis、Mongodb等缓存数据库技术经验5、团队协作及沟通能力强，可有效推动解决困难任务</p>', '3-5年', 'd555040cca26c12403F82dW1GVJQ', '深圳 · 福田区 · 会展中心', '11-22K', 'Java, C++, Python, SpringCloud, Redis', 'Java开发工程师（双休，金融经验）', 'https://www.zhipin.com/job_detail/d555040cca26c12403F82dW1GVJQ.html', '团建聚餐, 年终奖, 定期体检, 零食下午茶, 带薪年假, 交通补助, 节日福利, 绩效奖金, 员工旅游, 五险一金');
INSERT INTO `jobs` VALUES (282, '大胜科技', '电子商务', '20-99人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>参与公司软件系统的设计与开发，完成模块编码、测试及调试工作；</li><li>根据需求进行功能实现和技术方案落地，确保开发进度和质量；</li><li>配合团队完成系统集成、性能优化和问题排查；</li><li>编写相关技术文档，遵循开发规范和版本管理流程；</li></ol><p><strong>任职要求</strong></p><ol><li>熟悉主流编程语⾔及相关开发框架，具备良好的编码习惯；有saas⼯作经验优先 ；</li><li>掌握常⽤数据结构、算法和数据库操作，了解缓存和消息队列机制；</li><li>具备一定的系统设计能力，能够独⽴完成模块开发任务；</li><li>具有良好的沟通协作意识和较强的责任心，适应团队开发模式；</li></ol>', '3-5年', 'd8b30feac20fc6920nB52tq1GFNS', '深圳 · 南山区 · 前海', '10-15K', 'C#, Java, 不接受居家办公, C++, C, 其他, SQL Server, Spring, ERP开发经验, 大数据经验, Zookeeper, MySQL, 架构设计经验, Python', '软件开发工程师', 'https://www.zhipin.com/job_detail/d8b30feac20fc6920nB52tq1GFNS.html', '底薪加提成, 全勤奖, 员工旅游, 团建聚餐, 带薪年假, 绩效奖金, 保底工资, 节日福利, 五险一金');
INSERT INTO `jobs` VALUES (283, '深圳市优普洛', '计算机软件', '20-99人', '未融资', '本科', '<p>自研岗，</p><p><strong>岗位职责</strong></p><ol><li>负责 AI 业务相关后台服务开发，包括智能体（Agent）服务、API 接口、任务调度等系统模块；</li><li>负责服务的 Docker 容器化部署，有 Kubernetes（k8s）部署经验优先；</li><li>与算法、产品团队协作，支撑智能体交互、模型推理、数据处理等后端能力；</li><li>持续优化系统性能，参与技术调研，快速落地新技术方案5.负责客户需求沟通和梳理。</li><li>有3-5⼈团队开发管理经验。</li></ol><p><strong>岗位要求</strong></p><ol><li>本科及以上，计算机相关专业优先；</li><li>有2年以上 Java 后台开发经验，有实际项⽬落地经验；​3. 熟练 Java（Spring Boot / Spring Cloud 等），有扎实编码能⼒；</li><li>熟悉微服务架构，有相关项目经验；</li><li>熟悉 Docker 容器化部署，能独立完成服务的镜像构建与容器部署，了解 Kubernetes（k8s）部署更佳；</li><li>有​智能体（Agent）开发经验，了解智能体交互、任务编排、多轮对话后端逻辑等；</li><li>学习能⼒强，对新技术（如 AI 工程化、云原生）接受快，具备一定的跨团队沟通与协作能力8.使用过 ​Python，有 Python 与 Java 混合开发或调用 AI 模型经验。</li><li>有 ​AI / 大模型应用 / 模型服务化（如推理 API、向量检索、Prompt 工程等）相关开发经验。</li></ol>', '3-5年', '48b7cde2c2c616d60nZ_3dy6E1BQ', '深圳 · 福田区 · 市民中心', '10-15K·13薪', 'Java, Nginx, 团队管理经验, 不接受居家办公, 分布式经验, PostgreSQL, SpringCloud, Redis, Spring, Docker, Elasticsearch, 微服务经验, MySQL, Oracle, Python', '中级java开发', 'https://www.zhipin.com/job_detail/48b7cde2c2c616d60nZ_3dy6E1BQ.html', '五险一金, 定期体检, 年终奖, 带薪年假, 员工旅游, 节日福利, 股票期权');
INSERT INTO `jobs` VALUES (284, '海星文化艺术有限公司', '职业培训', '0-20人', '', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责学习平台、SCRM、OA等系统维护和部署，根据需求进行产品需求，接口设计等；</li><li>根据需求，完成产品业务模块开发的代码编写、自测，并对代码质量负责；</li><li>参与公司产品的架构优化，性能优化并辅助其他模块进行技术实现；</li><li>根据需求编写开发文档，对接前端开发人员，根据项目具体要求，按计划完成任务目标；</li><li>负责生产环境的运维，并为数据安全性负责；</li><li>完成领导交代的其他事项。</li><li>有AI项目经验优先；</li></ol><p><strong>岗位要求</strong></p><ol><li>5年以上Java开发经验，Java基础扎实，熟悉集合、多线程、IO等基础知识，有架构设计经验；</li><li>熟悉主流开源框架的设计和原理，如Spring MVC、Spring boot、SpringCloud、mybatis等，熟悉redis缓存机制，有从0-1项目经验优先；</li><li>熟练掌握常用数据库，有数据库设计、调优经验，熟悉MYSQL、ORACLE，对Nosql技术有一定了解；</li><li>掌握linux常见命令和定位问题方法，有较强的的定位问题能力；</li><li>对信息安全和常见的方案有一定的了解，有较强的逻辑分析能力和解决问题的能力；</li><li>有一定的程序性能分析和性能优化能力；</li><li>良好的沟通表达能力和解决问题能力，具有主观能动性；</li></ol>', '3-5年', 'fa1015c2a28645d41H180924EVVY', '深圳 · 龙华区 · 民治', '15-22K', 'Java, 大数据经验, 不接受居家办公, SpringCloud, MyBatis, Spark, 架构设计经验, Spring', 'Java 开发工程师', 'https://www.zhipin.com/job_detail/fa1015c2a28645d41H180924EVVY.html', '');
INSERT INTO `jobs` VALUES (285, '锐莱科技', '电子商务', '100-499人', '不需要融资', '本科', '<p>【</p><p><strong>岗位职责</strong></p><ol><li>作为业务与IT团队之间的桥梁，将业务痛点转化为技术需求，协同完成系统改造或AI能力接⼊，包括与各⼤跨境电商平台（如亚马逊、Shopee等）的API对接，实现⾃动上架、库存同步、发货等功能。</li><li>熟练运用主流AI编程工具（如Claude Code、Gemini、Cursor、Coze等），独⽴完成轻量级业务工具、自动化脚本、数据分析应用、AI Agent的设计与交付（如自动化报表、邮件助手、数据清洗、智能客服等），并利用AI工具进行自动化编程，提升开发效率。</li><li>对接公司内部AI平台、MCP生态及各业务系统（ERP/WMS/财务/平台API等），打通数据链路，推动业务流程的AI化重构；参与系统架构设计，优化现有系统的性能和可扩展性，解决技术难题。</li><li>跟踪业务效果，持续迭代优化已上线的AI解决方案，量化产出价值（节省工时、提升转化、降低成本等）；在团队内布道AI工具使用方法，培训业务同事掌握基础AI编程与工具应用，提升组织整体AI素养。【</li></ol><p><strong>任职要求</strong></p><ol><li>2年以上跨境电商行业经验（亚马逊、Flipkart、Shopee、Lazada、TikTok Shop、独立站等任一平台均可），熟悉电商业务全链路（运营/供应链/财务/客服至少深度了解一个领域）。</li><li>具备扎实的编程功底，熟练使用Python或JavaScript处理数据、调用API、编写自动化脚本；Java方向需精通SpringBoot/SpringCloud等框架，3年以上Java开发经验，能结合AI工具适配Java场景。</li><li>精通至少2款主流AI编程工具（Claude Code、Cursor、Gemini CLI、Qoder、Windsurf等），实战中AI代码生成占比≥50%，能独立完成从需求到上线的小型项目。</li><li>了解LLM基础原理（Prompt工程、RAG、Function Calling、MCP协议等），能根据业务场景选择合适的AI技术路径；具备优秀的问题排查能力，能结合AI提效并保障代码质量。</li><li>优秀的沟通与跨部门协作能力：能与业务、运营、财务、IT团队高效对话，准确理解业务诉求并转化为技术语言；能用业务听得懂的方式讲清楚技术方案。</li><li>强问题拆解与自驱能力，面对模糊需求能主动调研、快速试错、持续交付；热衷AI新技术，有研发提效或自动化编程经验优先。</li><li>有以下经验者优先：跨境电商平台API（SP-API、Flipkart Seller API等）对接经验；内部工具/Agent开发经验（Dify、n8n、Coze、LangChain等）；数据分析背景（SQL熟练，会用Pandas/BI工具）；英文读写流畅，可与海外团队协作；有\"业务+技术\"双重身份的项目经历（如运营转技术、产品经理转开发等）。</li></ol>', '3-5年', '5224f3ecb15a2fc40nF629q8EVVV', '深圳 · 龙岗区 · 坂田', '13-23K', 'Java, Python, SpringCloud, MySQL, 不接受居家办公, 跨境电商', 'Java/AI 工程师（初级~资深）', 'https://www.zhipin.com/job_detail/5224f3ecb15a2fc40nF629q8EVVV.html', '俱乐部活动, 带薪年假, 年终奖, 团建聚餐, 零食下午茶, 节日福利, 生日福利, 员工旅游, 餐补, 五险一金');
INSERT INTO `jobs` VALUES (286, '红茶移动', '互联网', '100-499人', 'C轮', '本科', '<p>【</p><p><strong>岗位职责</strong></p><ol><li>根据产品需求，完成接口设计、开发及文档编写；</li><li>参与数据库设计、优化，提高数据查询和存储的效率；</li><li>配合前端工程师，提供稳定可靠的API接口；</li><li>参与代码评审，优化代码质量，提⾼团队的开发效率；</li><li>处理线上问题，参与系统故障排查和性能优化。【</li></ol><p><strong>任职要求</strong></p><ol><li>熟悉 Java 基础（如多线程、集合、IO等），了解 JVM 运⾏机制；</li><li>熟悉 Spring Boot 或 Spring Cloud 框架，了解微服务架构；</li><li>熟悉 MySQL 或其他关系型数据库，掌握基本SQL优化技巧；</li><li>了解 Docker、Kubernetes 等容器化技术；</li><li>了解 Redis等常见中间件的使⽤场景；</li><li>具备良好的编程习惯，熟悉 Git 版本控制工具；</li><li>具有较强的学习能力、团队合作精神和良好的沟通能⼒。加分项：</li><li>做过SAAS服务；</li><li>有通信相关行业背景或经验。</li></ol>', '3-5年', '3a6e5da9600d0b190nF-2t25F1RV', '深圳', '18-25K', 'Java, Spring, SpringCloud, MongoDB, Redis, 物联网经验', '资深java开发工程师', 'https://www.zhipin.com/job_detail/3a6e5da9600d0b190nF-2t25F1RV.html', '入职周年礼物, 交通补助, 零食下午茶, 餐补, 通讯补贴, 免费咖啡, 年终奖, 带薪年假, 住房补贴, 股票期权, 员工旅游, 定期体检, 补充医疗保险, 五险一金, 培训进修补贴, 新婚生育红包, 企业滴滴, 节日福利');
INSERT INTO `jobs` VALUES (287, '鼎合丰', '计算机硬件', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>完成产品需求分析及功能设计；</li><li>辅助进行产品相关模块的功能定义,程序设计；</li><li>根据设计文档或需求说明完成重难点模块代码编写，调试，测试和维护；</li><li>分析并解决软件开发过程中的问题；</li><li>协助测试工程师制定测试计划，定位发现的问题；</li><li>配合项目经理完成相关任务目标。</li></ol><p><strong>岗位要求</strong></p><ol><li>本科及以上学历，三年以上java相关应用开发经验；</li><li>精通java编程语言，深入理解Spring、SpringCloud、Mybatis等框架的设计架构思想和实现方式；</li><li>具备MySQL、redis、mongoDB等主流数据库的开发能力；</li><li>具备需求分析和系统设计能力，以及较强的逻辑分析和独立解决问题能力；</li><li>熟悉软件开发流程，能够独立完成设计、编码、单元测试；</li><li>熟练掌握JEECMS框架，能基于JEECMS框架独立完成设计和编码；</li><li>有强烈的责任心和团队精神，善于沟通和合作，能独立完成设计和编码。</li></ol>', '3-5年', 'c4f0b8f773c25d191XZz0929GVpU', '深圳 · 龙岗区 · 横岗', '12-18K', 'Spring, JAVA, 中级软件工程师', 'Java中级开发工程师', 'https://www.zhipin.com/job_detail/c4f0b8f773c25d191XZz0929GVpU.html', '绩效奖金, 年终奖, 餐补, 带薪年假');
INSERT INTO `jobs` VALUES (288, '博鹏智能科技有限公司', '电气机械/器材', '20-99人', '未融资', '大专', '<p><strong>主要职责</strong></p><ol><li>系统设计与开发 ：根据客户需求或项目要求，设计和开发物联网系统，包括选择合适的传感器、设备和通信协议，并编写程序代码。</li><li>传感器与设备集成 ：集成各种传感器和设备，确保它们能够相互通信和协同工作，可能涉及网络配置、数据格式转换和安全性考虑。</li><li>数据分析与处理 ：处理从物联网设备收集的数据，并进行分析，提取有价值的信息，帮助企业做出智能决策。</li><li>安全性保障 ：确保物联网系统的安全性，包括数据加密、访问控制和认证等措施。</li><li>系统集成与测试 ：整合物联网系统的各个组件，并进行全面的测试和验证，确保系统的稳定性和可靠性。</li><li>故障排除与维护 ：监测和管理物联网系统的运行状态，及时处理故障，并进行需求变更或系统优化。</li></ol><p><strong>任职要求</strong></p><ol><li>全日制大专及以上学历，电子、电气、自动控制、计算机及相关专业。技术知识 。</li><li>熟悉物联网技术和相关的通信协议（如蓝牙、Wi-Fi、Zigbee、LoRa等），深入了解网络协议（如TCP/IP、MQTT、HTTP等），能够有效实现设备之间的通信。</li><li>编程能力 ：熟练掌握至少一种编程语言，如C/C++、Python、Java等。数据分析 ：具备数据挖掘、数据仓库、数据结构等相关知识。</li><li>云计算 ：熟悉云计算平台（如AWS、Azure等）和边缘计算的架构设计与实现。</li><li>网络安全 ：具备良好的网络安全知识，了解数据加密、认证和授权等技术。</li><li>工作经验 ：有物联网平台实施经验，至少有三项相关项目成功案例。</li><li>沟通和协作 ：具备良好的沟通能力和团队协作精神，能够推动项目的顺利进展。</li><li>具有良好的团队合作精神，能够有效沟通，解决开发中的问题。</li></ol>', '3-5年', '81a2c41f09d934fe03R43t2-FVFX', '深圳 · 龙华区 · 龙华', '8-13K', 'Java, 物联网经验, MySQL, Spring', '物联网 Iot 工程师', 'https://www.zhipin.com/job_detail/81a2c41f09d934fe03R43t2-FVFX.html', '');
INSERT INTO `jobs` VALUES (289, '云创数安', '计算机软件', '0-20人', '', '本科', '<p><strong>岗位职责</strong></p><ol><li>项目跟踪与管理；</li><li>产品部署与交付；</li><li>AI与产业结合研究</li></ol><p><strong>岗位要求</strong></p><ol><li>全日制本科计算机相关专业，具有Java开发设计架构经验；</li><li>Java基础扎实，熟悉JVM原理并有JVM调优实战经验，JDK源码 有一定了解；</li><li>熟悉Spring等至少3种主流框架原理和机制；</li><li>精通⾯向对象思想，熟悉设计原则、设计模式和领域建模；</li><li>掌握数据库原理，精通MySQL、Oracle并有优化实战经验；</li><li>熟悉分布式、⾼并发、⾼性能架构，并有性能优化实战经验；</li><li>工作态度认真，责任心强，具有良好的沟通协调、团队合作及抗 压能⼒，能自主驱动，执行能力强；</li><li>有数据安全产品或网络安全产品开发经验者优先；</li><li>有源代码分析产品开发经验者或有源代码分析工作经验者优先；</li><li>能独立承担产品POC测试与交付部署，编制部署文档，与客户进行沟通，项目进展跟进能力；</li><li>具备应用独立部署与交付能力:熟悉 Docker/容器化、CI/CD,能独立完成从开发到生产的多环境部署与运维(Go/Python 技术栈优先)；</li><li>具备 AI 应用工程化能力:有 LLM/Agent 项目落地经验,熟悉 vLLM/Ollama 本地推理、prompt 工程、工具调用(tool calling)者优先；</li></ol>', '3-5年', '177cd5f0098dbd6a0nJ709q0GFBY', '深圳 · 福田区 · 车公庙', '12-20K', 'Java, Python, Spring, Docker, JVM, MySQL, Hive, 架构设计经验', 'AI全栈研发工程师', 'https://www.zhipin.com/job_detail/177cd5f0098dbd6a0nJ709q0GFBY.html', '');
INSERT INTO `jobs` VALUES (290, '飞流无线', '物联网', '20-99人', '未融资', '本科', '<ol><li>扎实的JAVA基础，掌握JVM、并发编程、网络编程等基础知识3、有良好的编码规范，程序设计能力，了解常用的设计模式；</li><li>熟练使用关系型数据库，包括oracle、mysql等，具备数据库设计能力，数据库调优能力；</li><li>熟悉spring boot、mybatis、spring cloud开源微服务框架；</li><li>掌握redis缓存、mq消息队列、Nginx等中间件使用；</li><li>熟练掌握maven骨架项目，能够规划管理项目maven依赖；熟悉linux常用命令；</li><li>具备良好的沟通能力和受压能力，接受加班</li></ol>', '3-5年', 'b8b074ef28702bb11X1809W8GVdX', '深圳 · 南山区 · 科技园', '11-15K·13薪', 'Java, 物联网经验, 分布式经验, 微服务经验, SpringCloud, MySQL, 接受无前端经验/技能, Redis', 'Java', 'https://www.zhipin.com/job_detail/b8b074ef28702bb11X1809W8GVdX.html', '带薪年假, 年终奖, 有无线网, 团建聚餐, 绩效奖金, 节日福利, 生日福利, 员工旅游, 加班补助, 五险一金, 餐补, 定期体检, 零食下午茶');
INSERT INTO `jobs` VALUES (291, '上海嘉驰信息技术咨询', '计算机软件', '100-499人', 'C轮', '本科', '<p><strong>工作职责</strong></p><ol><li>负责货运核心业务系统后端开发。</li><li>深度参与项目需求分析与系统架构设计,确保系统具备高可扩展展性、⾼可维护性及⾼并发处理能⼒。</li><li>负责解决系统中的关键问题和技术难题,负责服务端代码的迭代更新和维护,快速定位并修复缺陷。</li></ol><p><strong>职位要求</strong></p><ol><li>计算机相关专业本科及以上学历,3年及以上开发经验,熟悉Java 编程语言和 Java生态主流开发框架、微服务架构。</li><li>熟练掌握MySQL、Redis、Kafka 等常⽤中间件及其原理。</li><li>具备较强的理解和解决问题的能力。</li><li>具备良好的团队协作能力和沟通能力,能够跨部门协作,具备良好的工作态度和责任心。</li></ol>', '3-5年', 'aee805c70ab025e60nJ73N6-GVpR', '深圳 · 福田区 · 梅林', '14-15K', 'Java, Spring, SpringCloud, MySQL', 'Java开发工程师-用户平台', 'https://www.zhipin.com/job_detail/aee805c70ab025e60nJ73N6-GVpR.html', '绩效奖金, 团建聚餐, 节日福利, 生日福利, 带薪年假, 五险一金, 年终奖');
INSERT INTO `jobs` VALUES (292, '逆创实业', '互联网', '100-499人', '不需要融资', '本科', '<p>1.平安银行知识工程项目适配改造 2.知识工程产品完善及优化【</p><p><strong>岗位职责</strong></p><p>】1.完成项⽬组相关的服务端开发⼯作 2.能接受产研其他产品安排【</p><p><strong>任职要求</strong></p><ol><li>Java基础扎实，熟悉多线程，集合等基础框架,理解ivm相关知识</li><li>熟练掌握java相关⽣态框架如springboot，spring cloud</li><li>熟悉分布式系统设计，有微服务架构开发经验</li><li>熟悉nacos,mysgl，redis，elasticsearch等中间件的使用</li><li>熟悉linux环境，能掌握常见的命令对服务进行只常维护和问题排査 7,了解⼤数据hadoop生态框架，如hadoop，spark，hbase，hive等</li><li>了解容器化技术如docker和kubemnetes</li><li>有银行交付项目经验优先</li><li>有图谱项目经验优化</li></ol>', '3-5年', 'ee147d976b62a9aa0nB-29u6EVpQ', '深圳 · 罗湖区 · 东门', '13-16K', 'Java, 不接受居家办公, Elasticsearch, 微服务经验, SpringCloud, MySQL, Hadoop, Redis, Spark, Spring', 'Java', 'https://www.zhipin.com/job_detail/ee147d976b62a9aa0nB-29u6EVpQ.html', '法定节假日三薪, 全勤奖, 餐补, 员工旅游, 带薪年假, 节假日加班费, 五险一金, 加班补助, 通讯补贴, 年终奖, 节日福利, 补充医疗保险, 定期体检');
INSERT INTO `jobs` VALUES (293, '品阔', '互联网', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责银行应用系统的开发，包括核心银行业务、总账、支付、数字开户以及其他支持功能；</li><li>参与整体IT基础设施和网络安全的开发；</li><li>参与第三方应用程序的评估，以及针对正在进行的银行业务的新IT举措；</li><li>参与由IT团队和相关部门制定的银行灾难恢复战略的演练和执行；</li><li>处理与IT相关的计划外停机、故障和提供的IT服务质量下降等事件；</li><li>参与变更管理和发布管理流程。考虑代码的可扩展性并提交高质量的代码；</li></ol><p><strong>任职要求</strong></p><ol><li>计算机科学、信息系统或相关的本科学历，3年以上经验；</li><li>在Java、并发编程和关系数据库管理系统方面具有扎实的技术知识；</li><li>熟悉Unix/Linux操作系统、云计算、消息队列和分布式存储；</li><li>对包括核心银行业务、支付、eKYC、AML和外汇在内的金融领域有浓厚兴趣者优先考虑；加分项：</li><li>服务过做过金融类特别是银行的；</li><li>重点本科或者以上学历或者大厂经历；</li><li>对任何主流云计算基础设施具有扎实的理解和实践；</li><li>具备额外的脚本编写和自动化专业知识将是额外的优势</li></ol><p><strong>福利待遇</strong></p><p>五险一金，社保足额缴纳，双休。</p>', '3-5年', 'aceb828a7e32321b03R52t67FVZV', '深圳 · 南山区 · 科技园', '15-30K', 'Java, Hibernate, 银行, SpringCloud, Redis, Spring, Oracle, 金融', '高级研发工程师', 'https://www.zhipin.com/job_detail/aceb828a7e32321b03R52t67FVZV.html', '股票期权, 企业年金, 餐补, 全勤奖, 五险一金, 交通补助, 夜班补助, 绩效奖金, 通讯补贴, 法定节假日三薪, 补充医疗保险, 加班补助, 节假日加班费, 保底工资, 年终奖, 带薪年假');
INSERT INTO `jobs` VALUES (294, '深圳御水飞行科技', '电子/硬件开发', '20-99人', '天使轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责后端系统的设计、开发和维护，保障服务的高性能与稳定性；</li><li>参与业务需求分析，完成接口设计与数据结构规划；</li><li>编写高质量、可维护的代码，持续优化系统架构；</li><li>配合前端及协作团队推进项目进度，确保系统高效集成；</li><li>参与技术难题攻关，提升系统在⾼并发、⾼可⽤场景下的表现；</li></ol><p><strong>任职要求</strong></p><ol><li>具备扎实的编程基础，熟练掌握至少一种主流后端开发语⾔；</li><li>熟悉常用数据结构与算法，了解操作系统和网络通信原理；</li><li>具备良好的系统设计能力，能对复杂业务进行合理抽象与分层；</li><li>具备较强的逻辑思维和问题解决能力，能独立完成模块开发；</li><li>具备良好的沟通协作意识，对技术有热情，持续学习能力强；</li></ol>', '3-5年', '3940664bf219cc290nd839y-F1pR', '深圳', '10-12K', 'Java, C++', '后端开发工程师', 'https://www.zhipin.com/job_detail/3940664bf219cc290nd839y-F1pR.html', '住房补贴, 绩效奖金, 零食下午茶, 节日福利, 五险一金, 员工旅游, 团建聚餐, 股票期权');
INSERT INTO `jobs` VALUES (295, '深圳德奥', '人工智能', '20-99人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责版本需求分析；</li><li>负责编写相关模块概要设计、详细设计等技术文档；</li><li>负责业务功能接口协议和基础类库的设计4、解决项目中的技术难题，指导初级工程师开发；</li><li>参与改进架构、提升性能，提升用户体验，对服务和产品持续优化。</li></ol><p><strong>任职要求</strong></p><ol><li>一本统招本科及以上学历，3年及以上linux服务端开发经验；</li><li>扎实的Java基础，熟悉NIO、多线程、集合等技术，熟悉主流java开源框架，如dubbo、mybatis、redis、zookeeper；</li><li>较为全面的软件知识结构，包括计算机网络、操作系统、软件工程、设计模式、数据结构、数据库系统；</li><li>掌握高并发、高负载、分布式系统相关技术，并具有实际开发经验优先；</li><li>对技术有浓厚兴趣，学习能力强，适应能力好，抗压能力强；</li><li>有大数据产品开发经验优先。</li></ol>', '3-5年', 'b4488c80f0b5101803N52d25ElRQ', '深圳 · 南山区 · 科技园', '15-25K·14薪', 'Java, 不接受居家办公, SpringCloud, 分布式技术, Redis, Dubbo, 数据结构, 音视频经验, Docker, 微服务经验, Linux, 负载均衡技术, 多线程', 'Java中级开发工程师', 'https://www.zhipin.com/job_detail/b4488c80f0b5101803N52d25ElRQ.html', '定期体检, 交通补助, 住房补贴, 绩效奖金, 员工旅游, 团建聚餐, 五险一金, 意外险, 带薪年假, 年终奖, 生日福利, 通讯补贴, 零食下午茶, 节日福利');
INSERT INTO `jobs` VALUES (296, '北京元蔓科技有限公司', '计算机软件', '20-99人', '', '大专', '<ol><li>计算机相关专业，3年以上的Java开发经验；</li><li>熟悉SpringMVC、SpringBoot、SpringCloud、myBytis、k8s等开源框架。</li><li>熟悉MySQL、达梦、PostgreSQL等数据库使用，并有相关优化SQL优化经验；</li><li>熟悉存储过程的使用及编写，并有实际开发经验；</li><li>熟悉Redis等缓存数据使用，并有实际项目使⽤；</li><li>熟悉Nginx部署配置，并理解其原理，熟悉git⼯具使⽤；</li><li>良好的沟通意识和服务态度，团队意识强；</li><li>熟悉并使用过etl、数据工⼚等经验优先；</li><li>具备电网营销、营配业务或南网项目的系统开发经验者优先；</li><li>具有一定的抗压能力。</li></ol>', '3-5年', 'c0025be09bf44f8f0nZ739i5E1ZV', '深圳 · 南山区 · 科技园', '8-13K', 'Java, SpringCloud, MyBatis, Nginx, PostgreSQL, MySQL, 南网, 电网, 数据开发, etl', 'java开发工程师', 'https://www.zhipin.com/job_detail/c0025be09bf44f8f0nZ739i5E1ZV.html', '');
INSERT INTO `jobs` VALUES (297, '钜弘技术', '计算机/通信/其他电子设备', '100-499人', '未融资', '本科', '<p>boss</p><p><strong>一、岗位职责</strong></p><ol><li>负责移动应用服务端、Web端的开发和维护；</li><li>参与系统的需求分析，完成对产品的接口、数据库结构以及业务逻辑设计；</li><li>编写技术文档，记录系统架构、设计和实现细节；二、职能要求：</li><li>本科以上学历，计算机相关专业，3年以上后端开发经验；</li><li>熟练掌握Java语⾔，熟悉Spring,SpringMVC,Springboot, SpringCloud等流⾏开源框架；</li><li>具备Java分布式软件开发经验，有⾼并发、高负载、高可⽤性系统设计和稳定性经验；</li><li>熟悉Web前端技术，包括HTML/XML/CSS/Javascript等；</li><li>对微服务架构、高性能低成本的后台架构有深入了解，有较强的技术规划和实现能力；</li><li>有Mysql/Redis/DynamoDB等数据库开发经验；</li></ol><p><strong>三、福利待遇</strong></p><ol><li>薪资结构：基本工资+岗位津贴+全勤奖+年底奖金；</li><li>调薪制度：年度调薪；</li><li>社会保险：入职即缴五险；</li><li>假期规定：带薪年假+春节提前放假+享受完整的法定节假日；</li><li>单/双/休，八小时工作制；9:00-12:00，13：30-18:30；</li><li>其它</li></ol><p><strong>福利</strong></p><p>①每年免费为员工组织旅游；②节假日关怀</p><p><strong>福利</strong></p><p>，每季度举办员工生日会等；③定期组织各项文娱活动，每年至少1-2次大型团建；期待优秀的您加入，共同进步！</p>', '3-5年', '4c60dc0692783a1703x70968FlJQ', '深圳 · 宝安区 · 松岗', '15-20K', 'Java, 不接受居家办公, SpringCloud, MySQL, 架构设计经验, Spring, Oracle', 'java后端开发工程师', 'https://www.zhipin.com/job_detail/4c60dc0692783a1703x70968FlJQ.html', '底薪加提成, 节日福利, 带薪年假, 包住, 包吃, 年终奖, 生日福利, 团建聚餐, 宿舍有空调, 全勤奖');
INSERT INTO `jobs` VALUES (298, '浙江徽创信息技术有限', '计算机软件', '100-499人', '未融资', '本科', '<p>【</p><p><strong>岗位职责</strong></p><ol><li>负责核心业务模块设计及数据库设计等；</li><li>参与产品的系统分析与设计、编码实现等工作，确保业务系统的质量、安全和性能；</li><li>保证系统可重用、扩展性、高性 能和伸缩性，对代码质量、系统性持续做优化迭代。</li><li>解决产品研发过程中碰到的各种技术难题；【</li></ol><p><strong>任职要求</strong></p><ol><li>全⽇制本科及以上学历，计算机，软件⼯程及相关专业；</li><li>3-5年以上JAVA语⾔开发经验，3.精通Spring, SpringMVC，Spring Boot, dubbo 等开源框架4.基础知识扎实，例如：数据结构、网络编程、多线程、分布式架构，以及JVM原理和性能调优;</li><li>熟悉MySQL/Oracle数据库，熟悉Redis,熟悉NoSQL存储,熟悉关系数据库应用设计开发；</li><li>熟悉常见的中间件、分布式解决⽅案及其原理：分布式缓存、SOA、消息中间件，连接池等；</li><li>熟悉Tomcat、Jetty等Web服务器。</li><li>有较强的逻辑思维能力，数据分析能力、问题排查能力,主动积极有责任感，能够承担工作压力9.有大型分布式、高并发、高负载、高可用系统设计、开发和调优经验优先。</li></ol>', '3-5年', '68481add465c19130nJ73NS0EVBV', '深圳 · 南山区 · 蛇口', '10-14K', 'JVM, Java, 不接受居家办公, 分布式经验, SpringCloud, Redis, Dubbo, Spring, 微服务经验, MySQL, MyBatis, MongoDB, Oracle', '中级Java', 'https://www.zhipin.com/job_detail/68481add465c19130nJ73NS0EVBV.html', '五险一金');
INSERT INTO `jobs` VALUES (299, '深圳市中创智宇科技', '互联网', '20-99人', '', '本科', '<p><strong>职位描述</strong></p><p>Java\n微服务经验\nSpringCloud\nMySQL\n熟练掌握常见开源框架和技术，熟悉微服务，具备前端技能，会基础开发和联调，需要写设计文档\n孙莎莎\n今日活跃\n深圳市中创智宇科技\n·\n招聘者\n竞争力分析\n查看完整个人竞争力\n个人综合排名：在人中排名第\n你在？位置\n一般 良好 优秀 极好\nBOSS 安全提示\n严禁用人单位和招聘者用户做出任何损害求职者合法权益的违法违规行为，包括但不限于扣押求职者证件、收取求职者财物、向求职者集资、让求职者入股、诱导求职者异地入职、异地参加培训、违法违规使用求职者简历等，您一旦发现此类行为， 请立即举报\n工商信息\n公司名称\n深圳市中创智宇科技有限公司\n法定代表人\n江锦宇\n成立日期\n2018-04-18\n企业类型\n有限责任公司\n经营状态\n存续\n注册资金\n100万人民币\n查看全部\n工作地址\n深圳福田区八卦岭工业区-五区\n点击查看地图\n更多职位\n看过该职位的人还看了\nJava开发工程师（珠海项目，线上面试）\n10-14K\n长亮科技\n深圳\njava开发工程师\n10-15K\n软通动力\n深圳\njava开发工程师\n10-15K\n中航信息\n深圳\n中级JAVA开发工程师\n10-15K\n超光速国际物流\n深圳\n金融项目Java开发\n11-16K\n中电金信\n深圳\nJava/Python开发工程师（AI方向）\n10-15K\n云仓库\n深圳\n精选职位\nrpa工程师亚马逊\n10-15K\n佳翔\n深圳\nJava开发（驻场银行+双休）\n11-17K\n长亮科技\n深圳\nJava\n10-15K\n峰峻智能\n深圳\nJAVA开发工程师（驻场某券商）\n11-14K\n新华三技术有限公司\n深圳\n中级java开发工程师\n10-15K\n智慧林网络\n深圳\njava开发工程师\n11-16K·13薪\n汇合发展\n深圳\n深圳\n搜索\n城市招聘 热门职位 推荐公司 热门企业\n安康招聘\n莆田招聘\n泸州招聘\n白山招聘\n黄山招聘\n定西招聘\n吕梁招聘\n钦州招聘\n嘉兴招聘\n遂宁招聘\n首页深圳招聘·Java招聘深圳Java招聘深圳市中创智宇科技Java招聘\n页面更新时间：2026-08-04\n企业服务热线和算法/未成年人等举报渠道 400 065 5799\n老年人直连热线400 661 6030\n工作日 8:00 - 22:00\n休息日 8:00 - 22:00\n企业服务\n职位搜索\nAPP\n投资者关系 Investor Relations\n直品公益基金会\n求职技巧\n使用与帮助\n协议与规则\n隐私政策\n防骗指南\n使用帮助\n联系\n北京华品博睿网络技术有限公司\n公司地址 北京市朝阳区太阳宫中路16号院1号楼18层1801内09\n违法和不良信息举报邮箱/未成年人举报渠道 jubao@.com\nCopyright © 2026 京ICP备14013441号-5京ICP证150923号 电子营业执照 京公网安备11010502032801 朝阳网警 人力资源服务许可证 网上有害信息举报专区 朝阳区人社局监督电话 算法备案信息</p>', '3-5年', 'e3a851b92d2236c10nF-2N--F1pT', '深圳 · 福田区 · 上步', '10-11K', 'Java, SpringCloud, MySQL, 微服务经验', 'java开发', 'https://www.zhipin.com/job_detail/e3a851b92d2236c10nF-2N--F1pT.html', '');
INSERT INTO `jobs` VALUES (300, '研谱科技', '计算机软件', '0-20人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责公司核心业务系统的全栈开发与迭代，主导后端业务逻辑开发、接口设计及前端页面开发落地，独立完成从需求拆解、方案设计到代码开发、测试上线的全流程⼯作，保障业务系统稳定运⾏与功能迭代。</li><li>基于Spring Boot框架进⾏后端架构搭建、功能开发、接口封装与优化，结合业务场景完成系统架构设计、模块拆分、技术方案落地，保障系统架构的合理性、可扩展性与可维护性。</li><li>使用Vue框架完成前端页⾯开发、组件封装、页面适配、交互优化，配合后端接口完成前后端联调，解决前端兼容性、页面卡顿、交互异常等问题，提升用户使用体验。</li><li>负责数据库设计与优化，熟练运用MySQL、MongoDB数据库，完成数据表结构设计、索引优化、数据查询优化、数据迁移、数据备份等工作，解决数据库慢查询、数据冗余、并发访问等问题，保障数据存储高效、稳定、安全。</li><li>主导系统性能优化工作，针对系统接口响应慢、并发瓶颈、资源占用过高等问题进行专项排查与优化，完成代码重构、架构升级、缓存优化、并发优化等工作，提升系统吞吐量、稳定性与承载能力。</li><li>参与Linux环境下的项目开发、部署、调试与运维工作，熟练完成服务器环境配置、项目打包部署、日志排查、问题定位等日常开发运维工作，保障线上项目稳定运行。</li><li>根据业务技术需求，使用Node.js、C++完成配套工具、底层功能、辅助服务的开发与迭代，适配核心业务的拓展需求，补齐系统功能短板。</li><li>参与技术评审、代码评审，梳理技术难点并输出解决方案，沉淀技术文档、开发规范，带动团队技术优化，配合团队完成技术攻坚与项目落地。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机、软件工程等相关专业，2年及以上Java全栈开发经验，具备完整的全栈项目落地经验，熟悉互联网业务开发流程。</li><li>精通Java后端开发，熟练掌握Spring Boot核心框架及相关生态技术，熟悉Spring MVC、MyBatis等主流框架，具备扎实的Java基础、多线程、并发编程、IO操作、网络 socket 编程等底层知识。</li><li>精通Vue前端开发，熟练使用Vue2/Vue3、Vue Router、Vuex、Axios等主流技术栈，熟练掌握前端工程化开发，能够独立完成复杂页面及交互功能开发。</li><li>熟练掌握MySQL、MongoDB两大数据库，精通SQL语句编写、索引设计、事务机制、数据库调优，熟悉非关系型数据库存储逻辑，具备海量数据处理与优化经验。</li><li>具备优秀的系统架构设计能力，能够根据业务场景设计合理的系统架构、模块拆分、接口规范，具备微服务、分布式架构基础认知与落地经验，擅长解决各类架构痛点。</li><li>具备专业的系统性能优化能力，熟悉接口优化、代码优化、并发优化、缓存优化、数据库优化等主流性能调优手段，能够独立完成系统性能排查与专项优化。</li><li>熟练掌握Linux操作系统，精通Linux环境下的代码开发、编译调试、项目部署、日志分析、权限配置、进程管理等操作，能够独立解决服务器端各类开发运维问题。</li><li>掌握Node.js开发技术，能够独立开发后端辅助服务、接口工具、自动化脚本；熟悉C++开发，具备底层功能、工具模块开发能力，可适配多语言协同开发场景。</li><li>熟悉前后端协同开发流程，具备良好的代码规范、编程思维和问题排查能力，能够快速定位并解决项目中的各类技术bug和疑难问题。</li></ol>', '3-5年', 'ed4d9d90bd676b600nB73tW8EldY', '深圳 · 南山区 · 科技园', '12-15K', 'Java, node, 不接受居家办公, C++, 微服务经验, MySQL, Netty, MongoDB, 架构设计经验, Spring, leaflet', '中级java开发工程师', 'https://www.zhipin.com/job_detail/ed4d9d90bd676b600nB73tW8EldY.html', '五险一金, 定期体检, 带薪年假, 聚餐, 节日福利, 年终奖');
INSERT INTO `jobs` VALUES (301, '嘉方传媒', '广告营销', '20-99人', '天使轮', '本科', '<p>关于我们我们是一家有真实高频业务场景的整合营销公司，长期服务于效果投放与素材生产场景，当前正在推进公司核心项⽬“效果投放 AI 升级”。这个项⽬不是 AI 平台，也不是单纯做⼏个工具，而是围绕真实业务，逐步搭建⼀套营销智能工作系统。当前第一阶段，我们聚焦解决一个非常具体、也非常关键的问题：把优质素材与投放结果真正挂接起来，让素材能够被拆解、复盘、形成判断，并进一步衍化和验证。你加入后，不是去做一个孤立的技术模块，而是会和 AI 产品经理、投手、剪辑等角色一起，参与这套系统的从 0 到 1 搭建。长期来看，项目会继续向 AIGC、全链路协同、更智能的营销工作流演进，但当前阶段我们更强调：先把最真实、最有价值的业务闭环贯通。你将参与什么你将和 AI 产品经理一起，参与搭建一套面向真实营销业务的后端系统。这个系统不是做单点工具，而是围绕“素材理解、结果追踪、经验沉淀、智能辅助”逐步建立一条可持续运转的业务闭环。第一阶段重点是把业务中最关键的对象关系和数据流打通，让内容资产、投放表现、复盘结论能够被统一管理、查询和回溯，并逐步支持 AI 能力介入业务流程。•业务数据底座：内容资产、投放结果、版本关系、复盘记录、实验记录等核心业务对象的后端服务与数据模型。•数据接入与清洗：搭建数据接入、清洗、标准化和挂接流程，处理真实业务中的脏数据、命名不统一、对象关系复杂等问题。•复盘与验证支撑：复盘卡片、实验记录、衍生方案、验证结果回写等功能的数据流转与状态管理。•AI 能力接入：接入合适的 AI / LLM / 多模态能力，用于内容理解、信息整理、建议生成、复盘辅助等场景。•可扩展架构：从轻量级出发，支撑第一阶段业务闭环，为后续 AIGC、全链路协同、营销智能化产品化预留系统能力。你将负责的具体工作•参与营销智能一期项目的后端架构设计与核心服务开发。•设计并实现核心业务对象模型，支持内容资产、投放结果、版本关系、复盘记录、实验记录等业务数据的统一管理。•搭建数据接入、清洗、标准化和挂接流程，处理真实业务中的脏数据、命名不统一、对象关系复杂等问题。•实现业务后台与服务接口，支撑项目第一阶段的最小闭环跑通。•支持复盘、验证、衍生方案记录等功能的数据流转与状态管理。•接入合适的 AI / LLM / 多模态能力，用于内容理解、信息整理、建议生成、复盘辅助等场景。•与项目 Owner 持续协作，推动系统不断迭代，逐步提升可用性、可维护性和扩展性。•为后续的知识沉淀、模板复用、内容规范化与智能化扩展预留系统能力。必须具备•精通至少一门后端语言：Python / Go / Java / Node.js 之一。•有扎实的后端开发能力，能够独立完成核心业务服务开发。•有真实的数据处理 / ETL / 数据建模经验。•熟悉常见数据源、接口设计、服务部署和基础工程规范。•能面对复杂、杂乱、变化快的业务需求，而不是只适应边界清晰的纯技术任务。•有良好的代码组织能力、版本控制习惯和问题排查能力。•能与非技术角色协作，理解业务目标，并把需求翻译成可落地的系统实现。•有产品交付意识，接受先做最小闭环、再逐个扩展，而不是一上来追求大而全。优先考虑•做过内部工具系统、流程系统、审核系统、实验系统、数据中后台等项目。•有广告、内容、推荐、媒体、营销相关行业经验。•有 LLM / 多模态 / AI 应用接入经验。•熟悉 Docker、CI/CD、基础容器化部署。•做过脏数据治理、对象建模、流程抽象类项目。•有一定前端阅读和简单调整能力，能和前端或 AI Coding 协同完成界面级需求。加分项•有 RAG、向量库、知识检索实战经验。•熟悉 LangChain / LlamaIndex / Spring AI 中的任意一种。•有 AIGC 平台对接经验（文生图、图生视频、文生视频等）。•有 Ollama / vLLM / 主流模型 API 接入与调优经验。•对素材理解、内容理解、多模态分析方向有兴趣或实践。我们更看重你什么除了技术能力，我们更看重你是否适合我们现在这个阶段。我们希望你：•不是只会“接需求写代码”，而是真正愿意参与从 0 到 1 搭系统。•不是只会憋概念，而是能把复杂问题拆解成阶段并落实到代码和系统里。•不是只会做 AI Demo，而是能把 AI 能力推进真实业务流程。•不害怕杂乱和变化，因为真实业务的第一阶段一定不会很整齐。•能接受先把数据层和闭环跑通，再逐步扩展更复杂的 AI 能力。一句话来说，我们要找的不是“只会做技术”的人，而是能配合 Owner，把业务问题真正做成系统的人。你将获得什么•直接参与公司核心 AI 升级项目从 0 到 1 建设。•与业务一线深度协作，快速积累真实的 AI 应用落地经验。•有机会参与从数据底座、后端系统到 AI 能力接入的完整建设过程。•团队扁平，决策链短，方案可以快速进入业务验证。•我们这个项目不是纸上谈兵，而是有真实用户、真实素材、真实投放反馈。•长期有机会继续参与后续 AIGC、全链路协同、营销智能化产品化建设。适合这份岗位的人如果你符合下面这些特征，这个岗位很适合你：•后端基础扎实，但不想一直做纯通用业务 CRUD。•对 AI 应用场景有兴趣，但不希望停留在 Demo 和概念层。•愿意进入真实业务现场，和产品、业务一起把闭环跑出来。•能接受项目早期的不完美，并愿意一起搭底座、跑样板、逐步升级。•希望未来积累的不只是“写代码”，而是“搭系统 + 懂业务 + 接 AI”的综合能力。说在最后我们不是在招聘一个“万能型 AI 超人”，也不是要你一来就独自揽下整个平台。我们更希望你能和 AI 产品经理一起，把当前最关键的第一阶段做扎实：先把素材 → 结果 → 复盘 → 衍生 → 验证这条闭环搭起来，再一步步把 AI 的能力真正接进业务。如果你有扎实的后端工程能力，愿意面对真实业务中的复杂性，又对 AI 应用落地有兴趣，我们很期待和你聊聊。</p>', '3-5年', 'd8752f9654fa15500nB43tm-ElBV', '深圳 · 南山区 · 蛇口', '10-15K', 'Java, Python, Spring, SpringCloud, MyBatis, Hibernate, Tomcat, MySQL, Redis, Oracle, MongoDB, SQL Server, 微服务经验, 大数据经验, 不接受居家办公, AI, AI后端', 'AI后端工程师', 'https://www.zhipin.com/job_detail/d8752f9654fa15500nB43tm-ElBV.html', '年终奖, 带薪年假, 交通补助, 全勤奖, 五险一金, 生日福利, 节日福利, 零食下午茶, 定期体检, 员工旅游');
INSERT INTO `jobs` VALUES (302, '山东浪潮数字服务', '互联网', '100-499人', '', '本科', '<ol><li>负责Java后端项目的需求分析、技术方案设计与落地，能独立完成核心模块开发、编码、测试及上线全流程⼯作，确保项⽬交付质量与效率。</li><li>参与AI相关功能的开发与集成⼯作（如AI接口调用、算法落地、数据处理等），结合业务场景实现AI相关需求，积累AI编程实践经验。</li><li>负责项目⽇常代码优化、bug修复、性能调优，提升系统稳定性、可扩展性和可维护性，遵循规范的编码标准与开发流程。</li><li>熟练运用Java核心技术及主流框架（Spring Boot、Spring Cloud等），结合数据库、缓存、消息中间件等技术，搭建高效、可靠的后端服务。</li><li>参与需求评审、技术研讨会议，主动沟通需求细节，协调跨团队（产品、测试、前端等）协作，推动项目顺利推进。</li><li>梳理开发过程中遇到的技术问题，总结解决方案，提出系统优化建议，协助完善技术开发规范与流程。</li><li>关注行业新技术、新框架，主动学习并应用到实际工作中，提升团队技术能力；完成领导交办的其他临时性技术相关工作。</li></ol><p><strong>任职资格要求</strong></p><ol><li>熟练掌握 Java 基础、多线程、集合、IO 等核心技术；</li><li>精通 Spring Boot、Spring Cloud 等主流开发框架，熟悉微服务架构；</li><li>熟练使用 MySQL、Redis 等数据库及缓存中间件；</li><li>能独立完成需求分析、接口开发、技术方案设计与代码实现；</li><li>熟悉Git、Maven 等开发工具，具备良好的编码规范与工程化能力。</li></ol><p><strong>四、综合素质</strong></p><p>具备良好的沟通协调能力；具有较强的团队合作精神、责任意识与自主解决问题能力。</p>', '3-5年', '79c5c98d4879c45a0nBy2N28FFRY', '深圳 · 南山区 · 科技园', '10-15K', 'Java, 团队管理经验, 不接受居家办公, SpringCloud, MySQL, 架构设计经验, Spring', 'Java-深圳', 'https://www.zhipin.com/job_detail/79c5c98d4879c45a0nBy2N28FFRY.html', '五险一金, 补充医疗保险, 定期体检, 带薪年假, 有无线网');
INSERT INTO `jobs` VALUES (303, '瑞克斯安捷', '互联网', '20-99人', '天使轮', '大专', '<p><strong>岗位职责</strong></p><ol><li>负责跨境物流业务系统整体研发与迭代，独立完成核心模块的架构设计、编码开发、测试落地、性能优化及上线运维，涵盖核心业务场景。</li><li>主导中大型技术项⽬从0到1的全流程落地，参与项⽬需求调研、⽅案评审、技术选型、进度把控，独立攻克项目核⼼难点，推动项目高效交付、落地迭代。</li><li>负责AI应用及智能Agent开发，结合跨境物流业务场景，落地智能调度、智能对账、异常预警、智能客服、自动化单据处理、物流路径智能优化等AI赋能功能，实现业务流程自动化、智能化升级。</li><li>基于Java+Vue3技术栈进行前后端全栈开发，搭建稳定、高效、可扩展的系统架构，优化代码逻辑、系统性能及交互体验，保障高并发、高可用的业务系统稳定运行。</li><li>主动挖掘业务痛点，具备独立创新思考能力，从技术视角提出优化方案，通过技术创新赋能业务提效降本，持续推进产品和技术体系迭代升级。</li><li>高效对接业务、运营团队，精准拆解业务需求，同步技术方案，及时解决项目开发及落地过程中的各类问题，主动推进项目进度，具备极强的项目推动力。</li><li>梳理技术规范、沉淀项目文档，优化研发流程，协助团队提升整体研发效率。</li></ol><p><strong>任职要求</strong></p><ol><li>技术能力硬性要求（1）4年及以上互联网/企业级系统全栈开发经验，主导过中大型项目完整开发落地，具备独立负责核心业务系统的能力，有跨境物流、供应链、仓储货代、跨境电商行业项目经验者优先。</li><li>后端精通Java，熟练掌握SpringBoot、SpringCloud等主流微服务框架，熟悉MySQL、Redis、MQ等中间件，精通接口开发、数据处理、事务优化、高并发场景解决方案。</li><li>前端熟练掌握Vue3、Vite、Pinia、Element Plus等主流技术栈，能够独立完成前端页面开发、组件封装、交互优化，熟练掌握TS、Ajax、前端工程化开发。</li><li>具备扎实的AI开发能力，拥有完整的Agent开发落地经验，熟悉大模型应用开发、智能体编排、Prompt工程、RAG知识库、自动化任务流程搭建，有业务AI智能化项目落地案例者优先。</li><li>具备完整全栈思维，熟悉前后端协同开发、接口联调、部署上线全流程，能够独立完成全功能模块从0到1搭建。</li><li>项目与创新能力（1）具备极强的独立思考能力和创新意识，不局限于现有业务模式，能够主动通过技术创新解决业务痛点、优化业务流程。</li><li>拥有中大型项目主导经验，具备需求拆解、技术方案设计、风险预判、进度管控能力，可独立推动项目落地交付。3、</li></ol><p><strong>综合素质</strong></p><ol><li>自驱力强、精力充沛、执行力强，具备主动推进项目前进的主人翁意识，不被动等待任务。</li><li>抗压能力强、有拼劲，能够适应项目攻坚阶段的工作节奏，敢于承接复杂、高难度开发任务。</li><li>逻辑清晰、责任心强，具备良好的代码规范和技术沉淀意识。加分项1、有跨境物流、国际货代、供应链管理、WMS/TMS系统开发经验者优先；</li><li>有AI Agent、智能自动化平台、大模型业务落地项目经验者优先；</li><li>具备从0到1搭建业务系统、技术平台的实战经验者优先；</li><li>熟悉物流轨迹、报关、订舱、费用结算等跨境物流核心业务流程者优先。</li></ol><p><strong>岗位亮点</strong></p><ol><li>核心技术岗，全权负责公司物流核心系统研发与AI智能化升级，自主权高、成长空间大；</li><li>主打技术创新+业务赋能，支持从0到1创新项目落地，充分发挥个人技术能力和创新思维；</li><li>团队氛围高效务实，无冗余流程，鼓励技术突破，高执行力、高回报；</li><li>深耕跨境物流赛道，业务场景成熟，AI赋能落地场景丰富，技术价值可快速落地体现。</li></ol>', '3-5年', '71ffd229d77d46860nJ52t24FFBV', '深圳 · 龙华区 · 民治', '18-25K·13薪', 'Java, Spring, MySQL', '全栈工程师', 'https://www.zhipin.com/job_detail/71ffd229d77d46860nJ52t24FFBV.html', '交通补助, 健身房, 股票期权, 生日福利, 五险一金, 团建聚餐, 节日福利, 员工旅游, 法定节假日三薪, 零食下午茶, 加班补助, 底薪加提成, 零食, 节假日加班费, 绩效奖金, 年终奖, 带薪年假');
INSERT INTO `jobs` VALUES (304, '浩翰星河', '计算机软件', '20-99人', '不需要融资', '大专', '<p><strong>岗位职责</strong></p><ol><li>负责云苍穹现有功能扩展调整及新模块开发；</li><li>负责云苍穹系统上的二次开发以及维护工作；</li><li>负责云苍穹数据报表及新模块的开发。</li><li>3年以上苍穹开发经验负责金蝶苍穹平台（PaaS）的二次开发与定制化实施，包括但不限于：基于苍穹低代码平台（如星瀚、星瀚财务）开发业务模块（财务、供应链、HR等）；使用​​苍穹开发框架（KDDI）​​构建前端页面、后端逻辑、API接口及数据模型；集成第三方系统（如OA、CRM、银企直连） via RESTful API 或消息队列。根据客户需求设计技术方案，解决复杂业务问题（如多组织权限、跨系统数据同步、高性能报表开发）。优化系统性能，排查并修复代码缺陷，确保系统稳定性与安全性（如数据加密、权限控制）。</li></ol>', '3-5年', '239b7d1a3400bb471Xx_39u_E1RQ', '深圳 · 南山区 · 科技园', '10-15K', '星瀚, 金蝶, 苍穹', '苍穹开发', 'https://www.zhipin.com/job_detail/239b7d1a3400bb471Xx_39u_E1RQ.html', '零食下午茶, 团建聚餐, 节日福利, 带薪年假, 有无线网, 五险一金, 员工旅游');
INSERT INTO `jobs` VALUES (305, '深圳市生行科技', '计算机软件', '0-20人', '', '大专', '<p><strong>职位描述</strong></p><p>Java\nMySQL\nSpring\n熟悉JAVA、SpringMVC、SpringBoot、MyBatis\n林女士\n在线\n深圳市生行科技\n·\n招聘经理\n竞争力分析\n查看完整个人竞争力\n个人综合排名：在人中排名第\n你在？位置\n一般 良好 优秀 极好\nBOSS 安全提示\n严禁用人单位和招聘者用户做出任何损害求职者合法权益的违法违规行为，包括但不限于扣押求职者证件、收取求职者财物、向求职者集资、让求职者入股、诱导求职者异地入职、异地参加培训、违法违规使用求职者简历等，您一旦发现此类行为， 请立即举报\n工商信息\n公司名称\n深圳市生行科技有限公司\n法定代表人\n袁润巧\n成立日期\n2023-06-27\n企业类型\n有限责任公司（自然人独资）\n经营状态\n存续\n注册资金\n100万人民币\n查看全部\n工作地址\n深圳南山区南山科技园102\n点击查看地图\n更多职位\n看过该职位的人还看了\njava开发工程师\n10-15K\n软通动力\n深圳\njava开发工程师\n10-15K\n中航信息\n深圳\nJava\n10-15K\n峰峻智能\n深圳\nJava（平安银行）\n10-12K\n上海恒格信息\n深圳\n金融项目Java开发\n11-16K\n中电金信\n深圳\nJava/Python开发工程师（AI方向）\n10-15K\n云仓库\n深圳\n精选职位\njava开发工程师\n11-16K·13薪\n汇合发展\n深圳\n后端软件工程师（Java方向）\n10-15K\nCARVOO凯沃智能\n深圳\nJAVA开发工程师（驻场某券商）\n11-14K\n新华三技术有限公司\n深圳\nrpa工程师亚马逊\n10-15K\n佳翔\n深圳\n中级java开发工程师\n10-15K\n智慧林网络\n深圳\n高级Java全栈开发工程师\n9-11K\n芯科华高\n深圳\n深圳\n搜索\n城市招聘 热门职位 推荐公司 热门企业\n海北藏族自治州招聘\n鹰潭招聘\n大兴安岭地区招聘\n石家庄招聘\n萍乡招聘\n白沙黎族自治县招聘\n南平招聘\n阿勒泰地区招聘\n邢台招聘\n河池招聘\n首页深圳招聘·Java招聘深圳Java招聘深圳市生行科技Java招聘\n页面更新时间：2026-08-05\n企业服务热线和算法/未成年人等举报渠道 400 065 5799\n老年人直连热线400 661 6030\n工作日 8:00 - 22:00\n休息日 8:00 - 22:00\n企业服务\n职位搜索\nAPP\n投资者关系 Investor Relations\n直品公益基金会\n求职技巧\n使用与帮助\n协议与规则\n隐私政策\n防骗指南\n使用帮助\n联系\n北京华品博睿网络技术有限公司\n公司地址 北京市朝阳区太阳宫中路16号院1号楼18层1801内09\n违法和不良信息举报邮箱/未成年人举报渠道 jubao@.com\nCopyright © 2026 京ICP备14013441号-5京ICP证150923号 电子营业执照 京公网安备11010502032801 朝阳网警 人力资源服务许可证 网上有害信息举报专区 朝阳区人社局监督电话 算法备案信息</p>', '3-5年', 'dadb5a02439e98760nZ-2d65FVtY', '深圳 · 南山区 · 科技园', '10-15K', 'Java, 不接受居家办公, MySQL, Spring', 'java开发工程师', 'https://www.zhipin.com/job_detail/dadb5a02439e98760nZ-2d65FVtY.html', '');
INSERT INTO `jobs` VALUES (306, '亿安云', '计算机软件', '0-20人', '', '本科', '<p>我们需要的不只是执行者，而是能深度理解G端业务逻辑、主动利用智能工具解决复杂业务与技术融合问题的技术合伙人。您将负责数字政务、智慧园区等核心产品的前端架构与开发，并需要充分理解后端逻辑，与团队高效协同，利用AI编程工具大幅提升在复杂项目环境下的交付质量与速度。您的</p><p><strong>主要职责</strong></p><ol><li>核心开发： 负责公司数字城市、一网统管、智慧园区、物联网管理平台、数据可视化大屏等核心G端/B端产品的前端架构设计、开发与优化。</li><li>全栈协同： 深度参与产品前后端接口设计，能独立完成后端（Node.js/Python/Java等）基础功能的实现与联调，对后端技术有40%-50%的实践理解和调试能力。</li><li>AI提效先锋： 将AI编程助手深度融入日常工作流，熟练使用 Cursor、Codex、GitHub Copilot、通义灵码 等工具进行代码生成、重构、调试和文档编写，显著提升开发效率与代码质量。</li><li>技术驱动： 探索和实践前沿技术（如低代码、WebGL、微前端、大屏可视化）在数字政府和智慧城市项目中的创新应用。</li></ol><p><strong>职位要求</strong></p><ol><li>技术基础： ◦ 精通 Vue3/React/Angular 等至少一种主流前端框架及相关生态，有复杂中后台单页应用开发经验。 ◦ 扎实的JavaScript/TypeScript、HTML5、CSS3基础，熟悉ES6+新特性。 ◦ 熟悉前端工程化工具（Webpack/Vite等），具备性能优化和工程架构能力。</li><li>全栈能力： ◦ 熟悉后端开发语言（如Node.js、Python、Java之一），能阅读、理解和编写基本的后端业务逻辑与API接口。 ◦ 熟悉RESTful API设计规范，精通HTTP协议，能与后端工程师进行高效的技术对话。 ◦ 熟悉至少一种数据库（如MySQL、PostgreSQL、MongoDB）的基本操作和设计理念。</li><li>AI工具精通（核心要求）： ◦ 必须熟练使用 Cursor 或同级别以代码为核心的AI IDE。 请在简历中说明您使用AI编程助手的具体场景和心得。 ◦ 熟练运用GitHub Copilot等AI辅助工具进行日常编码。 ◦ 具备优秀的提示词工程能力，能精准地向AI描述需求，并评估、优化其生成的代码。 ◦ 有利用AI工具进行代码重构、生成单元测试、编写技术文档的实践经验。优先考虑（具备以下经验者将获得极大优势）：</li><li>有政务、数字城市、智慧园区、物联网等G端/B端复杂项目经验，理解其业务流程、用户特点（如多级审核、工作流、复杂表单、大屏指挥）。</li><li>有大型数据可视化、WebGL/Three.js 3D可视化（如数字孪生园区、城市CIM）开发经验。</li><li>了解微前端架构（qiankun等）在大型政务平台中的应用，或低代码平台的开发与集成经验。</li><li>对智慧城市相关技术（如物联网协议、GIS地图应用、视频融合）有基本了解或浓厚兴趣。</li><li>对技术有强烈热情，有自己的技术博客、开源项目或积极参与技术社区。我们提供• 有竞争力的薪酬： 薪资+项目奖金+年终奖。• 关键的项目角色： 参与决定城市未来面貌的数字政府、智慧城市核心项目，技术成果具有重大社会价值。• 成长型技术环境： 与顶尖技术团队共事，鼓励探索AI赋能开发等前沿实践，提供充足的培训和会议资源。• 完善的</li></ol><p><strong>福利</strong></p><p>体系： 五险一金、带薪年假、团建活动、节日</p><p><strong>福利</strong></p><ol><li>您最熟悉的AI编程工具（如Cursor）及一个具体的使用案例。</li><li>一个能体现您全栈理解能力，特别是涉及复杂业务逻辑（如政务、物联网） 的项目经历。我们需要的不仅是一位Java专家，更是一位具备深厚后端功底、同时拥有50%-60%前端实战能力的“全栈型后端工程师”。您将是连接业务逻辑与用户体验的关键桥梁，并能熟练运用AI编程工具，大幅提升复杂政务与物联网系统的交付效率。您的</li></ol><p><strong>主要职责</strong></p><ol><li>核心后端开发： 负责公司数字政府、智慧园区、物联网平台、业务中台等核心产品的Java后端架构设计、微服务开发、高并发与高可用保障。</li><li>前后端高效协同： 深度参与前端技术方案评审，能独立阅读、理解和修改前端代码（Vue3/React等），甚至能独立完成简单模块的全栈开发。您需要懂前端状态管理、组件化思想，能与前端团队无缝对接。</li><li>AI驱动研发： 将AI编程助手深度融入工作流，熟练使用 Cursor、Codex、GitHub Copilot、通义灵码 等工具进行Java代码生成、SQL优化、接口文档编写，以及辅助进行前端代码的理解与调试。</li><li>技术攻坚： 解决G端/B端项目中复杂的业务逻辑（如多级审批流、复杂报表、权限体系）和物联网数据处理挑战。</li></ol><p><strong>职位要求</strong></p><ol><li>Java 专家： ◦ 扎实的Java基础，深入理解JVM、多线程、集合框架、IO/NIO等。 ◦ 精通 Spring Boot, Spring Cloud, MyBatis Plus 等主流微服务与ORM框架。 ◦ 熟悉分布式系统设计与常用中间件（Redis, Kafka/RabbitMQ, Elasticsearch, Nginx等）。</li><li>前端实战能力（核心差异点）： ◦ 必须具备50%-60%的前端开发能力，而非仅仅“了解”。 这意味着您能看懂并修改现代前端框架（Vue3/React）的代码。 ◦ 熟悉 JavaScript/TypeScript, HTML, CSS，能独立实现简单的页面交互和接口联调。 ◦ 理解前端工程化（npm/yarn, webpack/vite）和基本的状态管理（Pinia/Vuex/Redux）概念。</li><li>AI工具精通（必备技能）： ◦ 必须熟练使用 Cursor 或同级别AI IDE。 请在简历中展示您如何利用AI提升Java或全栈开发效率。 ◦ 熟练运用AI进行代码补全、重构、生成单元测试用例、编写技术文档。 ◦ 具备优秀的提示词工程能力，能利用AI辅助理解复杂的前端代码或生成前端Mock数据。优先考虑（具备以下经验者将获得极大优势）：</li><li>有政务、数字城市、智慧园区、物联网等G端/B端复杂项目经验，深刻理解其业务流程（如办文办会、网格化管理、物联感知）。</li><li>有 Node.js 或 Java + Kotlin/Scala 等混合技术栈 的全栈项目开发经验。</li><li>有 WebGL/Three.js 可视化 或 大屏数据展示 相关的前后端开发经验。</li><li>熟悉信创环境（国产化数据库、操作系统、中间件）下的开发与适配。</li><li>有低代码/无代码平台开发经验，或自己的全栈开源项目。我们提供• 有竞争力的薪酬： 薪资+项目奖金+年终奖。• 关键的项目角色： 参与决定城市未来面貌的数字政府、智慧城市核心项目，技术成果具有重大社会价值。• 全栈成长空间： 在G端复杂业务场景中，充分发挥您的全栈技术优势，向Tech Lead或架构师方向发展。• 完善的</li></ol><p><strong>福利</strong></p><p>体系： 五险一金、带薪年假、定期体检、团建活动、节日</p><p><strong>福利</strong></p><ol><li>您最熟悉的AI编程工具（如Cursor）及一个在Java或全栈开发中的具体使用案例。</li><li>一个能体现您“50%-60%前端能力” 的项目经历（例如：您独立用Vue/React实现了一个什么功能）。</li></ol>', '3-5年', '82178f3a0bc319e61H1_3dq_EVpY', '深圳 · 南山区 · 大学城', '12-18K', 'Java, 物联网经验, 不接受居家办公, SpringCloud, Hadoop, Kafka, Redis, Spring, 大数据经验, Elasticsearch, 微服务经验, MySQL, MyBatis, MongoDB, 架构设计经验', 'java开发工程师', 'https://www.zhipin.com/job_detail/82178f3a0bc319e61H1_3dq_EVpY.html', '');
INSERT INTO `jobs` VALUES (307, '深圳市云晓智联科技', '通信/网络设备', '0-20人', '未融资', '本科', '<p>【</p><p><strong>职位描述</strong></p><ol><li>开发和维护物联⽹、管理相关系统；</li><li>负责对业务需求进⾏评审，开发实施，迭代优化；</li><li>按要求提交软件开发和测试过程中的标准化⽂档和操作手册。 【</li></ol><p><strong>职位要求</strong></p><ol><li>有苍穹开发且3年以上Java开发⼯作经验；</li><li>熟悉Java领域常用的开源框架，如Spring, Struts,Ibatis,Hibernate等；</li><li>熟悉多线程编程，熟悉socket编程，WebService接口技术；</li><li>熟悉Oracle,MySql等数据库，并有开发经验；</li><li>熟悉linux/UNIX等操作系统，了解Shell;</li><li>有较强的表达和沟通能力，善于团队合作；【</li></ol><p><strong>福利待遇</strong></p><p>】作息友好：9:00-18:00（双休不内卷）+社保团队氛围：90/95后高知伙伴，可安心深耕后端技术、专注开发、做系统优化。如果你是踏实做事的技术伙伴，欢迎你。</p>', '3-5年', '1b32b7e1f6b8eaad0nd929W6E1FQ', '深圳', '12-20K', 'Java, Spring, Hibernate, 不接受居家办公, Oracle, MySQL, 架构设计经验, WebService, 多线程编程, socket, 苍穹开发', '后端开发工程师-双休-急聘', 'https://www.zhipin.com/job_detail/1b32b7e1f6b8eaad0nd929W6E1FQ.html', '带薪年假, 保底工资, 绩效奖金, 五险一金');
INSERT INTO `jobs` VALUES (308, '卫健智能', '计算机软件', '20-99人', '天使轮', '大专', '<p><strong>岗位职责</strong></p><ol><li>负责公司相关产品的后端开发、迭代升级及代码优化，确保系统稳定、高效运行。</li><li>参与需求分析、技术方案设计、数据库设计，配合产品、测试等团队完成产品落地。</li><li>具备较强的问题分析和解决能力，逻辑思维清晰，能快速定位并解决开发过程中的技术问题。</li></ol><p><strong>岗位要求</strong></p><ol><li>有AI代码开发实战经验，并有3-5 年 Java 后端开发经验。</li><li>熟练掌握 JDK 核⼼ API，熟悉 Spring Boot、Spring Cloud、MyBatis 等主流开源框架，具备分布式系统开发经验。</li><li>熟练掌握关系型数据库（MySQL、Oracle）的设计与优化，熟悉⾮关系型数据库（Redis、MongoDB）的使⽤场景，具备复杂 SQL 编写、索引优化及数据库性能调优能力。</li><li>了解微服务架构设计理念，熟悉服务注册与发现（Nacos、Eureka）、配置中心、消息队列（RabbitMQ、Kafka）等技术。</li><li>责任⼼强，工作严谨细致，有良好的抗压能力，能按时按质完成各项开发任务7、计算机及IT相关专业背景，大专及以上学历； 优先条件 1、从事公共卫生信息化系统开发相关工作；</li><li>有AI编程经验</li></ol>', '3-5年', 'a5dba42c94d2c6830nF83NS_FVJW', '深圳 · 南山区 · 西丽', '13-15K', 'Java, Nginx, SpringCloud, Oracle, PostgreSQL, MongoDB', 'Java开发工程师', 'https://www.zhipin.com/job_detail/a5dba42c94d2c6830nF83NS_FVJW.html', '员工旅游, 节假日加班费, 通讯补贴, 带薪年假, 零食下午茶, 生日福利, 餐补, 绩效奖金, 五险一金, 加班补助, 团建聚餐, 节日福利');
INSERT INTO `jobs` VALUES (309, '诺博医疗', '医疗健康', '100-499人', 'C轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责产品需求评审和业务系统开发，深入理解业务场景和产品架构，形成软件设计方案，并参与设计评审；负责模块设计、编码、联调，负责相关开发文档的编写，负责bug修复、系统维护和优化;</li><li>负责软件架构的持续改进和重构，参与分析并解决开发中遇到的代码质量问题、性能问题、稳定性问题、资源使用效率问题等;？3. 与嵌⼊式开发⼈员协作，通过硬件接口或⽹络通信技术，实现中台与各种设备的对接，开发协议适配器，开发和维护稳定、高效、易扩展、高度智能化的设备管理系统；</li><li>与上层业务系统开发⼈员协作，基于对底层硬件业务的合理抽象，向上层提供优质的API，帮助上层应用快速实现新业务；</li><li>参与技术中台、业务中台建设，开发公司级的可复用组件，输出***实践，参与框架底层优化等；</li><li>积极进行个人技术提升和技术分享，培养和带领初级、中级开发者，推动团队效能化。</li></ol><p><strong>任职要求</strong></p><ol><li>全日制本科计算机、软件工程、通信等相关专业，3-5年以上Java服务端开发经验，有优秀的学习能力和团队合作精神，有较强的责任心和团队精神，能够承受较强的工作压力；优秀的分析问题、解决问题能力，乐于主动钻研技术、解决具有挑战性的复杂业务问题；</li><li>精通面向对象分析与设计(OOA/OOD)、SOLID原则、设计模式等; 能够熟练地运用UML进行建模；熟悉领域驱动设计（DDD）、响应式架构、CQRS\\ES优先；</li><li>扎实的Java基础知识功底，熟练掌握JDK（8+）的各种API、JVM的原理与调优，熟悉常用的数据结构和算法, 有优秀的编程素养和良好的代码习惯；</li><li>精通JavaEE技术，熟练掌握AOP技术，对Spring？MVC，Spring Boot、Mybatis等的源码有深入研究和理解；有Spring-data-jpa, Mybatis-plus、Sharding-Sphere实战经验者优先；</li><li>精通Redis、Kafka、Zookeeper/etcd/Consul、ElasticSearch、ELK、RocketMQ、InfluxDB等至少五种常用中间件；</li><li>精通数据库MySQL使用，OLTP数据库设计，SQL调优等；</li><li>精通网络编程，对TCP/IP、HTTP、HTTP2协议有深刻理解；对Netty原理，gRPC有深入研究者优先；</li><li>精通高性能Java编程，对java collections、 java concurrent、java nio包有深入研究；熟悉Akka且有CQRS/ES实战经验者优先；</li><li>精通Spring Web和Tomcat调优；熟悉Spring Webflux、reactor者优先；</li><li>精通Linux操作命令及Shell脚本编写，能熟练进行服务器负载的查看与分析，能熟练对java程序的问题进行现场排查和堆栈分析；出差巴西、摩洛哥、马来西亚、西班牙英语作为工作语言出差时长偶尔出差</li></ol>', '3-5年', 'f689564846e5d0750nZ93d64FVRS', '深圳 · 南山区 · 科技园', '14-25K', 'Java, 全英环境, SpringCloud, MySQL, SQL Server, 英语口语, Spring', 'java中高级（全英环境+口语流利）', 'https://www.zhipin.com/job_detail/f689564846e5d0750nZ93d64FVRS.html', '生日福利, 节日福利, 零食下午茶, 年终奖, 股票期权, 餐补, 带薪年假, 团建聚餐, 五险一金');
INSERT INTO `jobs` VALUES (310, '技威时代', '通信/网络设备', '100-499人', '未融资', '本科', '<p><strong>岗位职责</strong></p><p>1、负责云平台迭代需求的分析和详细设计的讨论及评审工作2、根据开发计划，负责接口设计、功能开发及功能模块单元测试等3、完成相关技术文档的编写</p><p><strong>任职要求</strong></p><ol><li>具有扎实的基础和编程能力，理解io、反射、多线程、集合等，清楚JVM的原理：</li><li>熟练运用SpringMVC、springboot、springcloud、MyBatis框架体系，掌握多个spring功能模块；</li><li>熟悉常⽤Linux命令，熟悉服务器应⽤部署；</li><li>掌握常⽤数据库的使用，如：MySQL、Redis、mongodb；</li><li>熟悉分布式系统的设计和应用，熟练掌握分布式、缓存、消息等机制：</li><li>具有较强的责任⼼和自学能力，具有良好的对外沟通和团队协作能力，具备良好的分析解决问题能力，能独立承担工作任务及把控任务进度。满足以下条件优先：</li><li>具备分布式、大数据量、高并发、高负载、高可用性系统设计开发经验优先；</li><li>有支付业务的开发经验优先3、有Golang开发经验优先</li></ol>', '3-5年', 'b36e38695e39f3b50nBz2du5F1NS', '深圳 · 龙华区 · 民治', '11-20K', 'Golang, 高负载, Java, 不接受居家办公, 高并发, 分布式经验, 支付, SpringCloud, Spring, 微服务经验, MySQL, MyBatis, 高可用性', '服务器开发（双休）', 'https://www.zhipin.com/job_detail/b36e38695e39f3b50nBz2du5F1NS.html', '餐补, 团建聚餐, 零食下午茶, 年终奖, 定期体检, 五险一金, 员工旅游, 绩效奖金, 带薪年假, 交通补助, 节日福利');
INSERT INTO `jobs` VALUES (311, 'Testin 云测', '互联网', '100-499人', 'D轮及以上', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责公司AI测试产品的开发，主要做业务系统的架构设计与代码开发，承担核心功能模块的研发及技术难点攻关。</li><li>负责整体技术架构的规划与演进，包括业务模型抽象、系统架构设计、技术选型及难点攻关，确保系统的高可用、高扩展性及安全性。</li><li>主导完成系统性能优化，解决开发过程中的⾼并发、数据⼀致性等复杂技术问题；负责系统设计评审及代码审查，确保代码质量。</li><li>负责核⼼模块的技术方案设计文档编写，参与制定团队编码规范、接口规范及数据库设计规范，并推动执⾏。</li><li>具备良好的跨部门沟通能力，能够指导初中级开发人员，协助团队整体技术提升，保证项目按时、高质量交付。</li></ol><p><strong>任职要求</strong></p><ol><li>统招本科及以上学历， 计算机相关专业，2、 3年以上Java开发经验，有做过AI项目优先，Java基础扎实，对JVM原理（内存模型、垃圾回收、类加载机制）及性能调优有深入理解；精通并发编程，能熟练处理线程安全问题。</li><li>熟练掌握MySQL或Oracle，具备优秀的SQL调优经验（Explain分析、慢SQL优化、索引优化），了解数据库中间件（如ShardingSphere）或分库分表设计者优先。</li><li>深入理解Spring Boot/Cloud、MyBatis等框架的底层原理和实现机制；熟悉分布式系统的设计和应用，熟悉分布式缓存（Redis）、消息中间件（RocketMQ/Kafka）的原理及应用场景，能解决常见的分布式问题（如分布式锁、事务消息）。</li><li>熟悉常用的设计模式，具备一定的系统设计能力（如微服务拆分、缓存策略、数据一致性方案）。</li><li>熟练使用Idea、Maven、Git；熟悉Linux环境，具备线上问题排查（日志分析、Arthas使用）和JVM性能调优经验。</li></ol>', '3-5年', 'eaf65d21947d2b8c0nF62di7GFdZ', '深圳 · 南山区 · 科技园', '16-18K', 'Java, SpringCloud, MySQL, Redis, Spring, Python', 'Java开发', 'https://www.zhipin.com/job_detail/eaf65d21947d2b8c0nF62di7GFdZ.html', '补充医疗保险, 五险一金, 节日福利, 带薪年假');
INSERT INTO `jobs` VALUES (312, '健三实业', '半导体/芯片', '100-499人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责公司产品的服务端核心代码开发；</li><li>参与产品架构设计、优化及技术方案实施；</li><li>解决产品研发过程中碰到的各种技术难题，突破性能瓶颈；</li><li>深度参与业务规划，讨论并提出有建设性的意见。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机相关专业，3年以上服务端核心开发、架构经验，有AI项目经验者优先；</li><li>JAVA基础扎实，熟练掌握IO、多线程、集合等基础类库，熟悉分布式缓存、消息机制、搜索引擎等技术；</li><li>熟悉J2EE规范，掌握常用的设计模式；熟悉高并发、高性能的分布式系统的设计及应用、调优；</li><li>熟悉SQL，了解Mysql及相关分布式存储技术；</li><li>深入了解互联网常用技术栈，zk、springBoot、dubbo、redis、spring、mybatis等开源组件和技术；</li><li>专注于技术，精益求精，并对业界的最新技术发展动态有比较密切的关注；</li><li>新的思维，并能从技术趋势和思路上能影响技术团队；</li><li>有激情、愿意分享，自驱能力强，良好的结果导向和抗压能力。</li></ol>', '3-5年', '9dc61a3b8f0895121X1_2ti-F1BU', '深圳 · 宝安区 · 新安', '12-24K', 'Java, 不接受居家办公, MySQL, MyBatis, Dubbo, 架构设计经验', '中级后端开发工程师', 'https://www.zhipin.com/job_detail/9dc61a3b8f0895121X1_2ti-F1BU.html', '');
INSERT INTO `jobs` VALUES (313, '顶尖传诚科技有限公司', '互联网', '100-499人', '未融资', '大专', '<p>岗位概述 1. 计算机相关专业，5 年以上 Java 核心开发经验，具备 Python 项目开发实操经验2. 扎实 Java、Python 基础；精通 JVM 调优、Java IO、多线程、网络编程；熟悉 Python 协程、GIL 及性能优化3. 熟用各类设计模式，深⼊掌握 Spring、SpringBoot、MyBatis；会 FastAPI/Flask 等 Python 常⽤开发框架4. 精通 MySQL，熟练编写优化 SQL，理解索引、事务、锁底层机制，可通过 Python 实现数据读写处理5. 熟练使⽤ Redis、Kafka、Nacos 等中间件，至少精通一种底层原理，可使⽤ Java/Python 对接开发6. 熟练 Linux 开发运维，了解 Docker、K8s，能编写 Shell、Python 自动化脚本7. 熟练 Git、Maven 等研发工具，可使用 Python 编写自动化测试、数据处理脚本8. 具备规范的技术方案、接口文档编写能力</p><p><strong>任职资格</strong></p><p>教育背景要求：专科以上学历工作经验：5年以上知识与技能 1. 计算机相关专业，5 年以上 Java 核心开发经验，具备 Python 项目开发实操经验2. 扎实 Java、Python 基础；精通 JVM 调优、Java IO、多线程、网络编程；熟悉 Python 协程、GIL 及性能优化3. 熟用各类设计模式，深入掌握 Spring、SpringBoot、MyBatis；会 FastAPI/Flask 等 Python 常用开发框架4. 精通 MySQL，熟练编写优化 SQL，理解索引、事务、锁底层机制，可通过 Python 实现数据读写处理5. 熟练使用 Redis、Kafka、Nacos 等中间件，至少精通一种底层原理，可使用 Java/Python 对接开发6. 熟练 Linux 开发运维，了解 Docker、K8s，能编写 Shell、Python 自动化脚本7. 熟练 Git、Maven 等研发工具，可使用 Python 编写自动化测试、数据处理脚本8. 具备规范的技术方案、接口文档编写能力其他 有AI大模型项目经验优先，抗压能力好，沟通能力好优先</p>', '3-5年', 'b023a140009967fd0nJ52tu5GFJS', '深圳 · 南山区 · 科技园', '18-25K', 'Python, Spring, MySQL', 'JAVA开发（Python+AI经验）', 'https://www.zhipin.com/job_detail/b023a140009967fd0nJ52tu5GFJS.html', '团建聚餐, 带薪年假, 加班补助, 节日福利, 生日福利, 绩效奖金, 年终奖, 五险一金, 底薪加提成, 保底工资, 零食下午茶');
INSERT INTO `jobs` VALUES (314, '道致科技', '互联网', '100-499人', '', '大专', '<ol><li>至少3-5年Java后端开发经验，有大型互联网项目经验者优先。</li><li>具备计算机科学、软件⼯程或相关领域的学⼠学位。</li><li>精通Java编程语⾔和相关框架（如Spring Boot、Spring Cloud更偏向于微服务框架）。</li><li>熟悉关系型数据库（如MySQL、PostgreSQL）和NoSQL数据库（如MongoDB、Redis）。</li><li>具有RESTful API设计和开发经验。</li><li>熟悉分布式系统架构和微服务架构。</li><li>了解消息队列系统（如RabbitMQ、Kafka）。</li><li>熟悉版本控制工具（如Git）。</li><li>具有良好的问题解决能力和代码优化能⼒。</li><li>了解基本的安全实践和数据保护措施。</li></ol>', '3-5年', 'e0dc129caa3c5e7e0nF92N-0EVpW', '深圳 · 宝安区 · 西乡', '15-30K', 'Java, 不接受居家办公, 分布式经验, 微服务经验, SpringCloud, MySQL, Kafka, Redis, Spring', '高级java开发工程师', 'https://www.zhipin.com/job_detail/e0dc129caa3c5e7e0nF92N-0EVpW.html', '');
INSERT INTO `jobs` VALUES (315, '深圳企蜂科技有限公司', '企业服务', '20-99人', '未融资', '大专', '<p><strong>一、岗位职责</strong></p><ol><li>负责公司AI产品及数字化平台研发，包括：AI销售助手、企业知识库、AI客服、AI营销自动化工具、⼩程序及管理后台等；</li><li>负责⼤模型能⼒接入与应用开发，包括：OpenAI、DeepSeek、通义千问、Claude、Gemini等模型能⼒集成；</li><li>负责AI Agent工作流设计与开发，包括：Prompt设计、Function Calling、Workflow编排、多Agent协作；</li><li>负责企业知识库（RAG）建设，包括：文档解析、向量数据库、检索增强、知识管理；</li><li>负责后端系统开发与维护：Java、SpringBoot、MySQL、Redis6、参与前端及全栈能力建设：Vue、UniApp、微信小程序等7、参与产品设计与业务场景分析，推动AI能力在真实业务中的落地。</li></ol><p><strong>二、任职要求</strong></p><p>1、必须具备3年以上开发经验熟悉Java生态（SpringBoot、MyBatis）熟悉MySQL、Redis具备完整项目开发经验熟悉API设计与系统架构设计具备良好的问题分析与解决能力加分项2、AI能力要求（重点）至少具备以下其中两项以上实践经验：大模型API接入经验Prompt工程实践经验RAG知识库搭建经验AI Agent开发经验LangChain/LangGraph实践经验Dify、Coze等AI平台开发经验MCP协议使用经验Function Calling实践经验3、优先考虑有以下经验优先：AI产品开发经验SaaS产品经验CRM系统经验商城系统经验支付系统经验企业数字化项目经验独立负责过0-1产品开发4、我们希望你：不只是程序员，而是产品共创者；能理解业务，而不仅仅理解代码；对AI技术充满兴趣，并愿意持续学习；能利用AI快速解决实际问题；愿意参与从0到1的产品建设；愿意与业务团队共同推动产品成长。</p><p><strong>三、岗位亮点</strong></p><p>深度参与公司AI战略项目建设 参与AI销售助手产品研发 有机会主导Agent工作流设计 接触企业级知识库与大模型应用场景 可从开发工程师成长为AI产品技术负责人 创业型团队，技术决策链路短 真实业务场景，项目落地速度快</p><p><strong>四、福利待遇</strong></p><p>五险一金 · 法定节假日 · 带薪年假 · 年度体检交通补贴 · 考证补贴 · 基础培训计划年度团队旅游下午茶 · 免费零食饮品 · 生日礼 · 节日礼年轻团队，氛围轻松，不PUA、不内卷五、工作时间周一至周五 9:00-18:00，午休2小时，双休工作地点：深圳·南山·深圳湾科技生态园2栋A座（双线地铁，交通便利）</p>', '3-5年', '09c6d16f82a1b54a0nF42t24EVdY', '深圳 · 南山区 · 科技园', '10-15K', 'Java, Spring, SpringCloud, MyBatis, MySQL, Redis, 沟通表达能力强, 团队协作意识强, 乐于技术分享, 愿意跟进新技术', 'AI应用开发工程师（Java）', 'https://www.zhipin.com/job_detail/09c6d16f82a1b54a0nF42t24EVdY.html', '带薪年假, 餐补, 免费工装, 五险一金, 员工旅游, 节假日加班费, 绩效奖金, 通讯补贴, 生日福利, 团建聚餐, 交通补助, 零食下午茶, 有无线网, 医药福利, 股票期权, 底薪加提成, 法定节假日三薪, 节日福利, 年终奖, 保底工资');
INSERT INTO `jobs` VALUES (316, '海外商旅', '生活服务(O2O)', '20-99人', '不需要融资', '本科', '<p>岗位boss</p><p><strong>职责</strong></p><ol><li>参与酒店业务中台的核心系统(搜索、预订、订单、库存)的设计、开发与重构，2、负责与国内外酒店集团及第三方供应商的系统对接，设计高可用、可扩展的技术⽅案。</li><li>攻克⾼并发、分布式事务、数据⼀致性、系统性能优化等技术难题，编写高质量、可维护的代码，并参与技术文档的写与维护。</li><li>根据业务规划制定相应技术规划、系统技术架构，推动系统演进，参与需求分析、架构设计、技术决策以及详细设计，对产品的系统安全性设计负责；</li><li>对产品的系统安全性设计负责；</li><li>跟踪项⽬的进度，执行任务管理，协调项目组成员之间的合作；解决生产问题出现的各种问题，做好快速响应和长期方案推进。</li></ol><p><strong>任职要求</strong></p><ol><li>统招本科及以上学历，计算机及其相关专业；</li><li>具有3年以上Java开发经验，有互联网差旅系统工作经验的优先，熟悉机票、酒店、商旅的相关业务开发；</li><li>精通Java语言，对相关技术领域的开源产品有深入的理解；</li><li>精通领域建模，熟悉主流技术架构体系，熟悉敏捷开发等理念；</li><li>熟练Linux 系统，掌握shell 。</li><li>精通NOSQL、系统高并发、微服务组件，熟悉MQ（rabbitmq、kafka、rocketmq等），熟悉Docker、Kubernetes者优先；精通数据结构，多线程编程和常用的设计模式，熟悉并理解常见分布式系统框架及解决方案（如ElasticSearch，消息中间件，Dubbo 服务化框架等），熟练使用MySQL等主流数据库；</li><li>精通SpringMVC、Dubbo、Zookeeper、Mybatis、MySQL、rabbitmq、Maven、Hbase；</li><li>具有有大规模高并发访问的Web应用架构设计及基于SOA架构的复杂业务系统开发经验；</li><li>具有一定的项目规划和决策能力，善于捕捉业务需求、架构设计中存在的问题，并给出有效的解决措施和方法，具有很强的抗压能力；</li><li>具有很强的较强的逻辑思维、管理协调能力，学习能力，分析能力和沟通能力，工作细致，性格稳定，有贡献精神，责任心强。</li><li>有差旅行业开发经验的优先考虑上班时间：09:00-18:00 ；中午12：00-13:00休息；双休</li></ol>', '3-5年', '1fa20e2f63576990031z3t-5FVBQ', '深圳 · 龙岗区 · 大运', '15-20K', 'GIT, MySQL, 消息队列, SpringBoot, Spring, Oracle', '高级java后端开发工程师', 'https://www.zhipin.com/job_detail/1fa20e2f63576990031z3t-5FVBQ.html', '生日福利, 法定节假日三薪, 补充医疗保险, 零食下午茶, 团建聚餐, 保底工资, 通讯补贴, 年终奖, 员工旅游');
INSERT INTO `jobs` VALUES (317, '云享', '计算机软件', '20-99人', '', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责金融类业务系统及相关产品的功能开发。</li><li>参与分布式系统开发、采用微服务架构、容器云平台等技术方案。</li><li>与业务团队紧密协作，参与客户侧需求分析，解决系统实施中的技术问题。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机相关专业。</li><li>3年以上Java开发经验，具有银⾏业务系统、⾦融业务平台开发经验者优先。</li><li>精通Java语⾔及Spring Cloud、SpringBoot、MyBatis等主流框架，熟悉分布式中间件（Dubbo/ZooKeeper）、缓存（Redis）、消息队列（Kafka/RabbitMQ）等。</li><li>熟练掌握Linux、Docker、Kubernetes等容器化技术，具备平台化构建和运维经验。</li><li>熟悉MySQL、Oracle等数据库设计与优化，具备高并发系统架构设计能力。</li><li>具备较强的技术规划能⼒、沟通协调能力，能承受压力并主动推动项目进展。</li></ol>', '3-5年', '21751204278bb02d0nR73NS6FlBX', '深圳 · 龙岗区 · 坂田', '12-18K', 'Java, SpringCloud, MySQL, 微服务经验, 四方, 雁联, 长亮', 'java开发工程师', 'https://www.zhipin.com/job_detail/21751204278bb02d0nR73NS6FlBX.html', '');
INSERT INTO `jobs` VALUES (318, '中航信息', '智能硬件', '100-499人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责公司软件系统的架构设计、业务规划演进、功能设计及实现。</li><li>跟踪业界最新技术的发展（物联网、AI等方向），提供竞争分析和业务规划建议。</li><li>负责技术方案的研究、方案评估和技术规范制定。对系统的稳定性、先进性负责，提升系统容错能⼒、规避潜在问题。</li><li>负责技术难点的分析、定位，提供可⾏的解决⽅案。</li><li>融入团队，提升团队的技术能力、开发效率，带领团队共同成长。</li></ol><p><strong>任职要求</strong></p><ol><li>计算机相关专业统招本科以上学历，有扎实的计算机基础知识和编程功底。五年以上JAVA开发⼯作经验，含两年以上中大型系统架构设计经验。具备金融、医疗行业经验优先。</li><li>主导过1个以上行业应用软件系统从0到1的研发、交付工作，具备优秀的架构能力和成功经验。</li><li>熟悉Spring Boot、Spring Cloud等主流框架，熟悉Redis,MyBatis,MQ等常见中间件。</li><li>熟悉MySQL，具备对数据库系统进行规划、设计及调优的能力。</li><li>精通计算机网络，熟悉HTTP，TCP/IP协议。</li><li>对技术趋势敏感，对AI大模型有深刻理解，能将前沿AI技术融入系统设计，拥有技术判断力与决策力，能在业务需求与技术成本间取得平衡。</li><li>极强的技术领导力，能驱动团队达成技术目标，具备优秀的沟通与跨部门协调能力。</li><li>要有为项目成功、业务成功而艰苦奋斗的意愿。具备优秀的再学习能力、自我驱动力和自我修复力，能独立思考解决问题，工作认真、灵活、高效、自律。</li></ol>', '3-5年', 'de5d0a09036705570nB839u4GFRW', '深圳 · 福田区 · 车公庙', '10-15K', '', 'java开发工程师', 'https://www.zhipin.com/job_detail/de5d0a09036705570nB839u4GFRW.html', '工龄奖, 五险一金, 团建聚餐, 意外险, 节日福利, 带薪年假, 有无线网, 生日福利');
INSERT INTO `jobs` VALUES (319, '理想科技', '计算机软件', '20-99人', '未融资', '大专', '<ol><li>有银行/互联⽹金融工作经验，熟悉支付结算类业务场景优先。</li><li>熟练掌握SpringBoot、SpringCloud、Eureka、Redis、RocketMQ等技术，熟悉并发编程，有分布式应用系统开发经验； 4，熟悉Oracle/MySQL数据库，要求有数据分析能力，会用大数据工具。掌握数据库索引，有sql调优能力；</li></ol>', '3-5年', '5d2b3a34e83357d80nJ52d28GFVQ', '深圳 · 罗湖区 · 东门', '14-16K', 'Java, Spring, MySQL, Redis', 'Java/全栈--平安银行', 'https://www.zhipin.com/job_detail/5d2b3a34e83357d80nJ52d28GFVQ.html', '五险一金');
INSERT INTO `jobs` VALUES (320, '星火燎原传媒', '互联网', '100-499人', '不需要融资', '本科', '<p>【</p><p><strong>岗位职责</strong></p><ol><li>参与实时竞价（RTB）链路的开发，实现 OpenRTB 协议的请求解析、竞价逻辑、响应封装及 win notice 处理。</li><li>配合⾼级⼯程师完成系统架构的落地，编写⾼质量、可扩展、可测试的代码，保障广告系统在高并发场景下的稳定与低延迟。</li><li>承接⼴告投放策略的工程实现，包括流量切分、A/B 实验、频次控制、预算 pacing 等，并完成相关文档与单元测试。</li><li>负责线上问题的定位与修复（性能瓶颈、数据不一致、异常流量等），持续优化系统可观测性与容错能力。</li><li>与运营业务团队协作，理解广告业务需求（如 ECPM 优化、投放效果提升），并转化为技术方案。【</li></ol><p><strong>任职要求</strong></p><ol><li>广告知识要求：理解 RTB 实时竞价流程，熟悉 OpenRTB 协议至少 2.x 版本的关键字段（imp、bidrequest、bidresponse、winnotice 等）。熟悉至少一类广告投放策略（预算控制、频次控制、人群定向、流量打底）的实现方式。熟悉广告常用指标（展示、点击、消耗、CTR、ECPM、填充率）及其在系统中的计算链路。有 DSP / SSP / ADX / 广告监测 / 转化归因 任一系统的开发经验。</li><li>加分项：有广告反作弊、动态创意、素材优选相关开发经验。使用过 Flink / Spark 进行实时数据流处理，或了解广告归因模型。熟悉 Docker / Kubernetes，有云原生环境下广告服务部署与调优经验。</li></ol>', '3-5年', '426002910bf364cf0ndz3dq7EFRQ', '深圳 · 南山区 · 科技园', '18-23K', 'Java, Golang, Spring, MySQL, Redis, adx, 程序化广告', '中级程序化广告开发工程师', 'https://www.zhipin.com/job_detail/426002910bf364cf0ndz3dq7EFRQ.html', '员工旅游, 带薪年假, 年终奖, 五险一金');
INSERT INTO `jobs` VALUES (321, '深度数据', '互联网', '20-99人', '天使轮', '本科', '<p><strong>岗位职责</strong></p><p>深入业务一线或客户现场，通过对话、观察和数据分析识别真正的工程问题在需求不明确、信息不完整的情况下，结构化框定问题边界、成功标准和交付优先级将模糊业务诉求转化为清晰技术方案，并能向⾮技术背景⼲系⼈说明方案逻辑与取舍独立完成从⽅案设计、编码实现到部署上线的完整闭环，交付可被实际使用的工程产物根据场景灵活选择技术手段，主要涉及 Node.js/Java/Python等后端技术以及前端工程、Electron 桌面端、AI Agent 编排、API 集成和自动化脚本基于生产环境真实反馈持续优化方案，并将前线问题、产品缺口和最佳实践回流团队</p><p><strong>任职要求</strong></p><p>有 2-5 年软件开发或工程交付经验，经验更丰富但思维开放者也欢迎精通 Java/Nodejs/Python/Go 等其中一个或多个技术栈，具备独立完成中小型系统设计与实现的能力熟悉现代前端工程，能完成复杂页面开发、状态管理、接口联调和工程化配置了解 Electron 或类似桌面端开发框架，理解主进程、渲染进程、IPC、本地存储和跨平台打包发布等常见问题有在缺少完整技术规格或需求文档的情况下，自主定义问题并推进交付的经历熟练使用 Codex/Claude Code/Cursor 等 AI 辅助开发工具，或有自己动手搭建 Agent、自动化工作流、Skill 等实践具备良好的逻辑思维、结构化表达和沟通能力，能将复杂技术问题向非技术人员清晰阐述结果导向、闭环意识强，关注方案是否在生产环境稳定运行并被实际使用学习能力强，能在陌生技术栈或业务领域中快速建立理解并动手解决问题全日制本科及以上学历，专业不限；计算机科学、软件工程、数据科学、数学、物理等理工类专业优先加分项有客户现场交付、业务方技术服务或复杂项目跨团队推进经验QS 前 50 院校背景优先；非理工类专业但具备优秀工程实践和问题解决能力者也欢迎有 Electron、桌面端、CLI、开发者工具、IDE 插件或本地 Agent 产品经验熟悉数据库、云服务、运维、代理、日志、权限或安全存储等工程问题，能根据场景快速上手有从零到一搭建个人项目、开源项目、Agent 或自动化工作流的经历英文技术文档阅读无障碍，能进行基本英文技术文档写作与口头沟通有 AWS / Azure / GCP 认证、软考、PMP 等相关资质证书</p>', '3-5年', '9ec80b33314c5c830nF92d64FlRQ', '深圳 · 南山区 · 科技园', '15-25K', 'Java, Python, Nginx, 大数据经验, 云计算经验, ERP开发经验, MES开发经验, 不接受居家办公', 'FDE 前沿部署工程师', 'https://www.zhipin.com/job_detail/9ec80b33314c5c830nF92d64FlRQ.html', '保底工资, 零食下午茶, 带薪年假, 五险一金, 年终奖, 股票期权, 团建聚餐, 绩效奖金');
INSERT INTO `jobs` VALUES (322, '金信云服', '计算机软件', '100-499人', '不需要融资', '本科', '<p><strong>职责描述</strong></p><ol><li>负责公司系统的开发，独立完成需求研发</li><li>参与日常与业务，BA进行需求沟通</li><li>完成日常版本⾃测、构建、发版等⼯作</li><li>完成相关安全整改、⽣产问题处理</li></ol><p><strong>任职要求</strong></p><ol><li>统招本科及以上学历，计算机相关专业，3年以上Java项目经验；</li><li>Java基础扎实，熟悉常用开源框架（Spring/Mybatis）；</li><li>对微服务框架有⼀定了解，熟悉SpringCloud开发；</li><li>熟悉oracle等数据库经验，对数据库原理有较深入理解，能够定位和解决数据库性能问题；</li><li>有一定海量数据处理经验，了解Hadoop、HBase、Kafka、Hive、Spark/Flink等框架的工作原理；</li><li>具有良好的沟通能力，团队合作精神，工作积极主动，具备良好的学习能力；</li></ol>', '3-5年', '74e2152c0086e5ea0nJ52t2-EFBV', '深圳 · 福田区 · 车公庙', '10-11K', 'Java, MySQL, Spring', 'Java', 'https://www.zhipin.com/job_detail/74e2152c0086e5ea0nJ52t2-EFBV.html', '年终奖, 节日福利, 员工旅游, 五险一金, 零食下午茶');
INSERT INTO `jobs` VALUES (323, '欢喜互娱', '游戏', '100-499人', '天使轮', '本科', '<p><strong>岗位职责</strong></p><p>1、根据策划或产品的要求进行游戏逻辑的开发2、游戏研发相关工具的开发3、游戏后台开发4、游戏服务器相关优化工作</p><p><strong>岗位要求</strong></p><ol><li>计算机相关专业，本科以上学历,有java或scala服务器研发经验；</li><li>精通nio、网络、多线程编程；</li><li>熟悉Netty，Jetty等网络开源框架的使用；</li><li>熟悉Linux平台及基本操作指令；</li><li>熟悉mysql数据库；</li><li>学习能力强，责任心强；</li><li>有3DMMORPG开发经验者优先考虑。</li></ol>', '3-5年', 'b42b05f15abf4e4303V-3d-9E1JZ', '深圳 · 南山区 · 科技园', '11-20K', 'Java, Linux, .NET', 'Java服务器开发工程师', 'https://www.zhipin.com/job_detail/b42b05f15abf4e4303V-3d-9E1JZ.html', '加班补助, 节日福利, 交通补助, 节假日加班费, 带薪年假, 法定节假日三薪, 生日福利, 员工旅游, 有无线网, 绩效奖金, 年终奖, 五险一金');
INSERT INTO `jobs` VALUES (324, '墨影科技', '智能硬件', '100-499人', 'A轮', '大专', '<ol><li>通过API与其他系统或服务进行对接，或其它较简单的⼆次开发。</li><li>⽤户现场技术⽀持及日常维护,向用户提供咨询、指导，收集⽤户反馈信息；</li><li>按照客户要求协助进行现场培训和指导，进行相关文档的编写，完成使用手册、测试文档、验收文档等；</li><li>与客户方保持良好的合作，确保项目进度与质量。【</li></ol><p><strong>岗位要求</strong></p><ol><li>熟练使用SpringBoot、SpringCloud等主流开源框架；</li><li>熟练使用RustfulAPI、MQTT、WebSocket进行数据交换，熟练使用JS、TS及React框架；</li><li>精通主流数据库使用，了解PostgresQL、MongoDB以及其它非关系型数据库；</li><li>能够胜任项目实施方案的撰写、需求分析和建议书的编写；</li><li>具备项目部署经验，了解企业级服务器常用软件环境的基本操作，能熟练在Linux下进行软件项目部署；</li><li>有学习能力、理解力，具备良好自信心、责任心，有较强的口头表达及沟通能力和团队意识。加分项：了解工业或机器人行业优先</li></ol>', '3-5年', 'a4d9311db6437c820nV93t24F1ZQ', '深圳 · 南山区 · 科技园', '11-14K', '', '软件开发工程师', 'https://www.zhipin.com/job_detail/a4d9311db6437c820nV93t24F1ZQ.html', '意外险, 团建聚餐, 生日福利, 零食下午茶, 股票期权, 法定节假日三薪, 五险一金, 年终奖, 节日福利, 带薪年假, 绩效奖金, 免费工装, 交通补助, 定期体检, 高温补贴');
INSERT INTO `jobs` VALUES (325, '纽曼海德智能', '智能硬件', '100-499人', '未融资', '本科', '<p>Knowledge /Additional IT technology background：Mobil Swift, JavaScript, Typescript, Node, Vue, React, AngularJava, Python, C,C++, C#.netREST, Linux, PostgreSQL, Docker, K8s, MicroserviceAzure,AWS, OpenAl, WastonX, ROSA Development tools：Agile/Scrum, BAVS, Lean, OKRs, Gantt, VSM, KanbanJira/confluence, Trello, Mural, Webex, slackGit, Jenkins, ClcD-pipelineSketch,Figma, draw.io 要在电商公司已经做过的中级软件程序员</p>', '3-5年', 'd749f7018f5f605e03J92Nm1E1JQ', '深圳 · 龙华区 · 观澜', '12-20K', 'Golang, Java, 物联网经验, C++, Hibernate, 团队管理经验, SpringCloud, Redis, SQL Server, Spring, ERP开发经验, HBase, Hive, Docker, PHP, MyBatis, MongoDB, Python', '软件工程师', 'https://www.zhipin.com/job_detail/d749f7018f5f605e03J92Nm1E1JQ.html', '定期体检, 节日福利, 通讯补贴, 带薪年假, 年终奖, 员工旅游, 五险一金');
INSERT INTO `jobs` VALUES (326, '合肥景彦科技有限公司', '环保', '100-499人', '', '大专', '<ol><li>具备良好的用户沟通能⼒;</li><li>精通java语⾔，熟悉Java 8新特性;</li><li>熟练掌握springboot等开发框架;</li><li>数据库技术，如Mysql，了解数据库设计原则；</li><li>熟悉分布式技术；</li><li>熟悉缓存技术及消息队列技术;</li><li>具备良好的逻辑思维能⼒8、具备一定抗压能力，可以应对复杂或紧急的问题。太平财险车险互联⽹H5移动出单系统维护项目:</li><li>Java基础扎实，理解IO、多线程、集合等基础知识，对JVM有一定了解。</li><li>熟练使用eclipse、IDEA等开发工具，熟悉JSP、Servlet等开发技术。</li><li>熟练使用struts、SpringCloud、Springboot、Mybatis等常用开发框架；熟悉主流应用中间件如Weblogic、Tomcat中至少一种。</li><li>熟悉主流数据库（如Oracle、Mysql、PostgreSQL等），熟练使用SQL语言。</li><li>熟练掌握软件设计理论，能独立完成相关需求或项目设计。</li><li>高度的责任心、活泼开朗，有较强的学习能力；良好的表达和交流能力，富有进取心。</li><li>有从事保险相关系统开发经验优先。太平财险车险出单系统维护项目:java基础：熟练spring相关框架：熟练springcloud：熟练关系型数据库：熟练中间件（redis\\MQ）：熟练前端技术（js、html、css\\vue）:了解太平财险网电销系统维护项目:有JS经验的后端都可以 不用全栈现场面试面试地址：深圳粤海城T2 8楼（广东省深圳市罗湖区太白路53号）</li></ol>', '3-5年', 'd180b06baef6ebdb0nFy2NS7EldT', '深圳 · 罗湖区 · 东湖', '10-13K', 'Java, 缓存技术, MySQL, 分布式技术, Spring, 数据库, Java 8, springboot', '中级Java开发', 'https://www.zhipin.com/job_detail/d180b06baef6ebdb0nFy2NS7EldT.html', '');
INSERT INTO `jobs` VALUES (327, '嘉成数智', '自动化设备', '100-499人', '天使轮', '本科', '<p>有过制造业 MES 开发或二次开发经验，开发项目经理经验 1 年以上；熟练掌握一种开发语言，Java / C# / Python 等 、精通sqlserver；了解上位机程序，有开发经验优先；会前端 vue3、vite、typescript 经验优先；全日制本科及以上学历。</p>', '3-5年', '890792147054e9770nV409S1GFJV', '深圳 · 坪山区 · 坪山', '15-25K', 'C#, MES开发经验, Java, 不接受居家办公, MySQL, SQL Server, Oracle, Python', 'mes工程师', 'https://www.zhipin.com/job_detail/890792147054e9770nV409S1GFJV.html', '年终奖, 工龄奖, 免费工装, 高温补贴, 宿舍有空调, 五险一金, 节假日加班费, 餐补, 夜班补助, 节日福利, 加班补助, 包住, 包吃, 全勤奖, 住房补贴, 带薪年假');
INSERT INTO `jobs` VALUES (328, '万漉金科技', '互联网', '20-99人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责公司系统核心代码的架构设计，开发与维护，撰写相关文档，参与需求分析；</li><li>对研发中疑难技术问题提供有效解决方法并主导实施改进和优化；</li><li>对现有产品的性能和架构进行改性；</li></ol><p><strong>任职要求</strong></p><ol><li>学历不限，计算机相关专业，3-5年以上⼯作经验；</li><li>精通Java编程，能够熟练应⽤SpringMVC，Spring，MyBatis，Redis等主流开发技术；</li><li>熟练使⽤ LINUX4、熟悉 MySQL，对 SQL 性能调优有一定的经验；</li><li>了解 MogoDB 以及 Redis 等，有分布式系统开发经验以及对服务器性能优化有深刻了解，有高并发项⽬经验；</li><li>有中大型互联网系统产品的研发，上线，维护经验；</li><li>责任心强，有团队合作能力和承受压力的能力。沟通能力佳，思路清晰，业务理解能力强，执行能力强，有持续自我学习的能力和意愿，较强的工作责任心和优秀的沟通协调能力；</li><li>有支付，金融，巨量快手投放数据处理相关经验优先考虑。</li></ol>', '3-5年', '4b90796e4cbf5d230nV82d-_EFtX', '深圳 · 南山区 · 科技园', '12-18K', 'Java, 分布式经验, Docker, 微服务经验, SpringCloud, MySQL, Kafka, Redis, MyBatis, Spring', '中级java开发工程师', 'https://www.zhipin.com/job_detail/4b90796e4cbf5d230nV82d-_EFtX.html', '交通补助, 保底工资, 节日福利, 零食下午茶, 年终奖, 团建聚餐, 加班补助, 员工旅游, 五险一金, 带薪年假');
INSERT INTO `jobs` VALUES (329, '安卫普科技', '智能硬件', '100-499人', 'B轮', '本科', '<p>岗boss位</p><p><strong>职责</strong></p><ol><li>负责反无设备、无线管控设备配套后台系统、设备运维管理平台、态势感知系统、数据服务中台的后端开发、功能迭代与架构优化，支撑设备管控、数据采集、态势分析全业务流程。</li><li>对接前端页⾯与底层硬件设备，负责设备通信协议对接、实现射频设备参数配置、状态监测、故障告警、⽇志⾤集、权限管控、设备运维等核心后端业务逻辑开发。</li><li>搭建并维护设备数据采集、清洗、存储与统计分析体系，处理射频频谱数据、设备运⾏数据、告警事件数据、运维操作数据，保障海量设备数据传输的准确性、实时性与完整性。</li><li>设计和优化数据库结构、接口逻辑与服务架构，封装通用业务接口、工具服务，解决高并发数据上报、高频数据渲染、设备批量管控等场景的性能瓶颈，保障系统7*24小时稳定运行。</li><li>开发实时告警、数据联动、态势统计、报表生成等核心功能，支撑前端可视化大屏、设备运维终端、后台管理系统的业务落地，适配政企、工业级设备管控使用场景。</li><li>配合产品、前端、硬件、测试团队完成需求评审、方案设计、接口联调、版本测试与上线部署，负责线上问题排查、bug修复、性能调优，持续迭代优化系统功能与稳定性。</li><li>梳理业务流程，沉淀通用技术组件与业务模型，规范接口文档与开发规范，持续优化项目架构，提升团队开发效率与项目可维护性。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机、软件工程、电子信息、通信工程、自动化等相关专业，3年以上后端开发经验，有物联网、工业设备、射频无线、安防管控、政企系统相关项目经验者优先。</li><li>扎实掌握后端开发基础，熟练掌握 Java 主流技术栈（SpringBoot、Spring MVC、MyBatis/MyBatis-Plus），熟悉后端开发流程、代码规范与项目部署流程。</li><li>熟练掌握 MySQL 数据库，精通数据表设计、索引优化、SQL编写与性能调优，熟悉数据分库分表、数据冗余处理，适配海量设备数据存储场景。</li><li>熟悉网络通信机制，熟练对接 RESTful 接口，掌握 WebSocket 实时通信技术，能够实现设备实时数据推送、状态同步、实时告警等功能。</li><li>了解物联网设备通信逻辑，熟悉设备数据上报、指令交互、数据解析流程，能够独立完成设备对接相关后端业务开发。</li><li>具备独立需求拆解、技术方案设计、功能开发、问题排查能力，逻辑思维清晰，能快速理解反无设备管控、射频监测类业务需求，高效完成功能落地。</li><li>熟悉 Git 版本管理、Maven/Gradle 项目构建和持续集成，具备规范的开发习惯和团队协作能力。【加分项】1、有反无设备、无线射频监测、信号干扰管控、物联网设备平台开发经验者优先。</li><li>熟悉 Redis、MQ 等中间件，掌握缓存、消息队列的使用场景，能解决高并发、高实时性数据处理问题。</li><li>熟悉 TCP/UDP等常用设备通信协议，有硬件设备对接、工控系统开发经验。</li><li>具备系统架构优化、接口性能调优、海量数据处理、分布式服务开发经验。</li><li>熟悉 Linux 基础命令、服务器部署、日志排查，具备独立部署与运维项目的能力。</li></ol>', '3-5年', '2def28ec44d4eba00nJ40ti9ElBW', '深圳 · 南山区 · 科技园', '12-16K·14薪', 'Java, MyBatis, Spring, MySQL', 'Java', 'https://www.zhipin.com/job_detail/2def28ec44d4eba00nJ40ti9ElBW.html', '保底工资, 带薪年假, 零食下午茶, 绩效奖金, 法定节假日三薪, 团建聚餐, 拼车补贴, 五险一金, 高温补贴, 节假日加班费, 有无线网, 生日福利, 年终奖, 定期体检, 节日福利, 员工旅游, 集体公寓');
INSERT INTO `jobs` VALUES (330, '上海舟恩信息', '计算机软件', '100-499人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责公司内部经营相关系统的架构设计、核心模块开发和优化工作，确保系统稳定、安全、高效运行；</li><li>能快速熟悉陌⽣业务场景，快速上⼿，独⽴解决开发过程中的技术难题，对系统功能迭代有自己的解决⽅案，并且能拉通各模块人员将方案落地实施；</li><li>协同团队完成软件开发生命周期的各个环节，包括需求分析、概要设计、详细设计、编码、单元测试、系统集成测试等；</li><li>认真完成上级指派的各项工作。技能要求：</li><li>具备扎实的编程功底，熟练掌握 Java 语言，深入理解 JVM 原理，熟练使用 Spring、Spring MVC、SpringBoot、Spring Cloud、 Mybatis 等主流开发框架，具备扎实的编程基础和良好的编程习惯；对常用的设计模式、设计原则、数据结构等有一定的理解和掌握，对面向对象思想有深入的理解；</li><li>熟悉 Nginx、Redis、Kafka, MQ，对象存储等中间件的使用及部署；熟练使用 Linux 命令；</li><li>熟练掌握 Oracle/PostgreSQL/MySQL 等数据库，具备数据分析 + 设计 + 开发的能力，有数据库能调优经验；</li></ol>', '3-5年', 'c29993a9bc06c45f0nJ5296-EFRW', '深圳 · 福田区 · 石厦', '12-13K', 'Java, Spring, MySQL, 不接受居家办公, 保险, 金融', 'Java-外包-线下面试（全额公积金社保双休）', 'https://www.zhipin.com/job_detail/c29993a9bc06c45f0nJ5296-EFRW.html', '零食下午茶, 五险一金, 带薪年假, 意外险, 节日福利');
INSERT INTO `jobs` VALUES (331, '博安云科技', '计算机软件', '100-499人', '未融资', '本科', '<p>需要有信贷项目的经验1、近3年内至少有2个或以上信贷系统实施经验，包括对公信贷、综合信贷、普惠小微信贷等。2、</p><p><strong>岗位要求</strong></p><p><strong>岗位职责</strong></p><p><strong>技术要求</strong></p><ol><li>前端交互:了解前后端分离的开发模式，能够使用HTTP2、参与项⽬的架构设计和技术选型，确保协议进行前后端数据交互(如使用Axios、Fetch等)近3年内至少有2个或以上信贷系|统的高性能、高可用性和可扩展性。</li><li>开发框架:熟练掌握SpringBoot、SpringCloud等开源统实施经验，包括对公信贷、综3、与产品经理、设计师、测试人员等密切微服务框架，并深入理解其原理和机制合信贷、普惠小微信贷等。作，确保项目按时交付并满足业务需求。</li><li>其他技术:熟悉Docker/K8S等容器化系统，分布式、缓4、解决开发过程中遇到的技术问题，持续近5年内至少有3个或以上信贷系存、消息队列等技术，如Kafka、Memcached、Redis等化系统性能和技术文档编写及分享。</li><li>数据库:熟练应用性能优化，能够进行数据库性能优化合信贷、普惠小微信贷等。(如索引优化、查询优化、分库分表等)和数据建模</li></ol>', '3-5年', '5b726cb5b5d5c8e40nJ52tW1E1NR', '深圳 · 罗湖区 · 东门', '13-14K', 'Java, Nginx, 不接受居家办公, SpringCloud, MySQL, Redis, Spring', '信贷java开发工程师', 'https://www.zhipin.com/job_detail/5b726cb5b5d5c8e40nJ52tW1E1NR.html', '节日福利, 零食下午茶, 餐补, 全勤奖, 加班补助, 生日福利, 五险一金');
INSERT INTO `jobs` VALUES (332, '上海大崃', '计算机软件', '100-499人', '不需要融资', '大专', '<p><strong>岗位职责</strong></p><ol><li>负责POS收单（磁条卡/IC卡/NFC闪付）、CPM被扫/MPM主扫扫码支付全链路系统设计与开发，基于ISO8583协议对接Visa、Mastercard等国际卡组织通道；</li><li>主导清结算批量作业、账务核心模块开发，实现手续费自动计提、商户分润、第三⽅渠道对账、差错调账、拒付处理等核⼼能⼒；</li><li>参与支付微服务架构迭代与性能调优，保障系统平稳承载百万级日交易量；</li><li>牵头技术⽅案评审，输出标准化设计文档，统一团队代码规范，持续提升系统稳定性与工程交付质量。</li></ol><p><strong>任职要求</strong></p><ol><li>3年及以上Java后端开发经验，至少2年金融支付、线下收单相关项目实战经验；</li><li>熟练使用Spring Boot、Spring Cloud微服务体系，熟悉Nacos、Sentinel、Gateway等服务治理组件；</li><li>精通MySQL分库分表，熟练使用Redis、Kafka/RocketMQ，拥有高并发交易系统性能优化实战经验；</li><li>熟悉ISO8583报文标准，有Visa、Mastercard境外卡组通道对接落地经验；</li><li>熟悉支付核心业务：交易授权、清算、结算、对账、拒付全流程逻辑。加分项1、有清结算核心系统、账务引擎独立设计与落地经验；</li><li>了解EMV芯片卡规范、3DS 2.0跨境安全认证流程。</li></ol>', '3-5年', '9b70b40d33ddab100nJ52dy-EFtU', '深圳 · 南山区 · 科技园', '15-25K', '不接受居家办公, Java, Spring, SpringCloud, Kafka, MySQL, Redis, 支付, Visa, 收单、支付, 发卡, 跨境支付', 'Java后端工程师（支付收单）', 'https://www.zhipin.com/job_detail/9b70b40d33ddab100nJ52dy-EFtU.html', '带薪年假, 员工旅游, 零食下午茶, 补充医疗保险, 意外险, 加班补助, 节日福利, 五险一金, 定期体检, 生日福利, 团建聚餐');
INSERT INTO `jobs` VALUES (333, '超级视觉', '智能硬件', '20-99人', '天使轮', '大专', '<p>一、系统开发与维护参与需求分析、系统设计，完成核心功能模块的代码编写；负责Java后端服务开发，确保高性能、高可⽤性和可扩展性；维护和优化现有系统，解决线上故障及性能瓶颈。⼆、技术⽅案落地根据业务需求设计技术方案，输出设计文档；遵循代码规范，进⾏代码审查，确保代码质量。三、协作与沟通与前端、测试、产品等团队协作，推动项目按时交付；参与技术攻关，解决开发中的难点问题。四、新技术探索跟踪行业技术动态，将新技术应用于实际项目（如微服务、云原生等）。五、公司安排的其他工作任务</p><p><strong>任职要求</strong></p><p><strong>任职要求</strong></p><ol><li>大专及以上学历，计算机、软件工程等相关专业优先。</li><li>具备三年以上开发经验，精通Java语言，熟悉JVM原理、多线程、集合框架等；</li><li>熟练使用Spring Boot、Spring Cloud、MyBatis等主流框架，熟悉MySQL/Oracle等数据库，掌握SQL优化及索引设计；</li><li>熟悉Redis、RabbitMQ/Kafka等中间件；</li><li>了解分布式系统设计（如Dubbo、Zookeeper）。</li><li>熟练使用Git、Maven/Gradle、Jenkins等开发运维工具；</li><li>熟悉Linux基础命令及Shell脚本。</li></ol><p><strong>综合素质</strong></p><ol><li>逻辑严谨，能快速定位后端问题并提出解决方案；</li><li>具备跨部门沟通能力，适应阶段性高强度工作。</li></ol>', '3-5年', 'd549de16801c342b0nd42du5E1pR', '深圳 · 龙华区 · 民治', '15-23K', 'Java, 音视频经验, 不接受居家办公, SpringCloud, MySQL, 搜索/推荐/广告经验, Spring', '中级java开发工程师', 'https://www.zhipin.com/job_detail/d549de16801c342b0nd42du5E1pR.html', '带薪年假, 团建聚餐, 底薪加提成, 意外险, 股票期权, 绩效奖金, 保底工资, 免费工装, 五险一金, 员工旅游');
INSERT INTO `jobs` VALUES (334, '深圳爱普', '汽车零部件', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责软件代码生成、编写、开发、测试等工作；</li><li>负责软件的开发和集成，承担系统引导程序的开发和调试3、负责汽车电动中门PSD、电动尾门ECU等控制器应用程序的设计开发及测工作；</li><li>对所开发的软件进行仿真和真实系统测试，设计和实施测试方案5.、负责对整个系统产品故障分析和解决异常问题的处理；?6、完成领导交办的其它临时工作；</li></ol><p><strong>任职要求</strong></p><ol><li>全日制本科以上学历，3年以上工作经验2.熟悉C++语言、Java、INCA、Autosar、CANape等任何一种开发工具；</li><li>有电机驱动、电动尾门、电动中门软件控制开发原理工作经历者优先；</li><li>具有较强的沟通协调能力、逻辑思维能力、抗压能力，较强的团队协作能力，为人正直有理想、工作认真负责；</li><li>遵守国家法律、法规和公司规章制度；</li></ol>', '3-5年', '5f1e707be403930a0HR43tS-FlM~', '深圳 · 光明区 · 光明', '8-12K', 'Java', '软件工程师  汽车电子软件工程师', 'https://www.zhipin.com/job_detail/5f1e707be403930a0HR43tS-FlM~.html', '员工旅游, 包住, 五险一金, 零食下午茶, 节日福利, 年终奖');
INSERT INTO `jobs` VALUES (335, '深圳市北科检测', '检测/认证', '20-99人', '未融资', '本科', '<p>注：做过合同管理项目经验优先面试：1轮视频+1轮现场面试上班时间：9:30-19:00 双休【</p><p><strong>岗位职责</strong></p><ol><li>AI 研发效能 & AI 落地 * 熟练使⽤ AI Coding ⼯具（Claude Code、CodeX、Cursor 等）提升编码效率。 * 结合 AI Agent 技术（AgentScope、LangChain、LangGraph 等）开发智能体应用。</li><li>质量与稳定性编写高可靠、易维护的代码，严格执⾏单元测试与代码审查；运用混沌工程等理念提升系统韧性，快速定位并修复线上故障。</li><li>技术演进持续引入 最新分布式中间件与框架（Spring Cloud、ShardingSphere、Seata、RocketMQ 5.</li><li>Redis 等），优化系统性能、成本与可扩展性。【</li></ol><p><strong>岗位要求</strong></p><ol><li>Java 核心能力扎实的 Java 基础，深入理解 JVM、多线程并发、网络编程。</li><li>主流框架精通 Spring Boot 与 Spring Cloud 微服务体系，熟练使用 MyBatis-Plus。</li><li>AI 经验 * AI Coding：熟练使用至少一种 AI 编程助手（Claude Code、CodeX、Cursor 等），并有实际提效经验。 * AI Agent：了解 Agent 基础架构（ReAct、Plan-Execute 等），使用过 AgentScope、LangChain、LangGraph 开发过 Agent 应用。 * 对 LLM 应用有实践热情，能结合业务设计轻量级 AI 能力。</li><li>分布式中间件与组件 * 微服务治理：Nacos、Sentinel（熟悉 Spring Cloud Alibaba）。 * 数据分片与分布式事务：Apache ShardingSphere（分库分表、读写分离）、Seata（AT/TCC 模式）。 * 消息与缓存：RocketMQ 5.0 / Kafka、Redis 7.0+（数据结构、集群方案、Redisson 客户端）。</li><li>数据库与性能精通 MySQL，熟悉 Redis 高可用方案；对分布式数据库（TiDB、OceanBase）有了解者加分。</li><li>分布式系统经验具备高并发、高可用系统实战经验，掌握常见分布式模式（幂等、防重、分布式 ID、最终一致性）。熟悉容器化与编排（Docker、Kubernetes）及 DevOps 流程。</li></ol>', '3-5年', 'eab5e3c54fcfdd910nJ709m9FVNS', '深圳 · 南山区 · 科技园', '12-17K', 'Java, 合同管理项目经验, SpringCloud, MySQL, Redis, Spark, AI经验, Spring', 'JAVA开发（短期项目6个月）', 'https://www.zhipin.com/job_detail/eab5e3c54fcfdd910nJ709m9FVNS.html', '交通补助, 五险一金, 年终奖, 带薪年假, 节日福利, 全勤奖, 零食下午茶, 员工旅游');
INSERT INTO `jobs` VALUES (336, '微克科技', '计算机软件', '100-499人', '不需要融资', '本科', '<ol><li>负责核心业务系统及 AI 智能化应用的后端架构设计、开发与维护。</li><li>将大语言模型（LLM）能⼒与 Java 微服务体系深度集成，构建⾼性能、低延迟的 AI 推理服务与 API。</li><li>攻克 AI 应⽤落地中的核心技术难题，持续优化 RAG 检索精度、Prompt 提示词策略及系统的并发稳定性。</li><li>编写⾼质量代码并制定研发规范，灵活使用 AI 辅助开发（如使用 Cursor/Copilot）的效率。</li><li>与算法、产品及前端团队紧密协作，推动 AI 技术在具体业务场景中的创新落地与迭代。</li></ol><p><strong>任职资格</strong></p><p>基础素质： 统招本科及以上学历，计算机相关专业，3年以上 Java 后端开发经验，具备扎实的 JVM、多线程及分布式系统设计功底。核心技术： 精通 Spring Boot、Spring Cloud 等微服务框架，熟练掌握 MySQL、Redis、Kafka/RocketMQ 等主流存储与中间件技术。云原生能力： 熟悉 Docker、Kubernetes (K8s) 容器化编排及 CI/CD 自动化部署流程。AI 技能（核心加分项）：有真实的大模型应用（LLM Application）落地经验。熟练掌握 Prompt Engineering，了解 RAG、Vector DB（向量数据库）及 Agent 智能体的开发范式。习惯使用 AI 编程工具（Cursor/Copilot）辅助日常开发，具备良好的 Python 读写能力者优先。软技能： 具备极强的自驱力和技术好奇心，对 AI 前沿技术保持高度敏感，有良好的跨团队沟通与技术文档撰写能力。</p>', '3-5年', 'e5b78d3ca5daceda0nB52921GVNQ', '深圳 · 龙华区 · 民治', '15-25K', 'Java, Spring, SpringCloud, Redis, 分布式经验, asr, tts', 'Java开发工程师', 'https://www.zhipin.com/job_detail/e5b78d3ca5daceda0nB52921GVNQ.html', '带薪年假, 绩效奖金, 五险一金, 股票期权, 节日福利');
INSERT INTO `jobs` VALUES (337, '深圳太可褶商贸', '批发/零售', '20-99人', '', '本科', '<p>核心</p><p><strong>岗位职责</strong></p><ol><li>核心业务研发：负责公司APP（iOS/Android）及小程序等前端应用的后端接口设计与开发，确保各端业务需求⾼质量落地。</li><li>系统架构与优化：参与后端微服务架构的设计与演进，针对APP与⼩程序的⾼并发、高可用场景，进⾏接口性能调优与数据库优化。多端交付与技术支持：深度参与多端产品的技术评审，协助解决复杂的端云交互问题、网络请求异常及数据同步等技术难题。</li><li>质量与稳定性保障：主导或参与后端自动化测试与接口测试体系建设，制定严格的发版准入标准；负责线上突发故障的应急响应与排查，保障系统SLA达标。</li><li>技术沉淀与规范：负责编写核心模块的技术文档与API接口规范，推动团队技术氛围建设，提升整体研发效能。</li></ol><p><strong>任职资格要求</strong></p><ol><li>学历与经验：计算机或相关专业本科及以上学历，3-5年以上Java后端开发经验，具备扎实的底层技术功底。</li><li>Java核心基础：精通Java核心技术，熟练掌握Spring Boot、Spring Cloud、MyBatis等主流开源框架，深刻理解其底层运行原理。</li><li>多端业务理解：熟悉APP与小程序的底层运行机制、接口交互规范及发版审核规则，具备独立排查复杂端云交互问题的能力。</li><li>数据库与中间件：精通MySQL数据库设计与SQL调优；熟练掌握Redis、RabbitMQ/Kafka等常用中间件，有高并发场景下的缓存设计与消息队列实战经验。</li><li>运维与测试能力：熟练掌握Linux操作系统，熟悉Docker/K8s等容器化技术及CI/CD流水线建设；熟悉主流自动化测试框架（如JMeter、Postman等），具备编写高质量接口测试用例的能力。6、</li></ol><p><strong>综合素质</strong></p><p>具备极强的责任心、抗压能力和跨部门沟通协调能力；拥有优秀的逻辑思维与问题分析能力，能以业务价值为导向推动技术落地。7、熟悉前端技术栈（Vue/React/Uni-app/Flutter等），能阅读并排查前端代码问题者优先。</p>', '3-5年', 'dafd359de1474ce00nF92Nu7FlJZ', '深圳 · 南山区 · 科技园', '8-12K', 'Java, 游戏后端经验', 'java开发工程师', 'https://www.zhipin.com/job_detail/dafd359de1474ce00nF92Nu7FlJZ.html', '');
INSERT INTO `jobs` VALUES (338, '喀斯特网络', '互联网', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责用户体系模块重构，涵盖用户信息管理、账户权限、KYC关联等核心能力建设，梳理现有痛点并独⽴设计落地新⽅案；</li><li>负责开卡（发卡）模块重构，优化开卡流程、提升系统稳定性与安全性；</li><li>负责返佣模块的设计与开发，包括返佣规则配置、佣⾦计算与结算流程等；</li><li>参与支付/收单核心链路开发：交易处理、清算对账、账户余额与冻结体系的设计与实现；</li><li>参与钱包（法币+虚拟货币）充提币等核⼼业务模块的开发与维护，保障多渠道对接（第三方风控、支付通道等）的稳定性；</li><li>配合技术方案评审与代码质量把控，推动重构类项目按期交付。 ---</li></ol><p><strong>岗位要求</strong></p><ol><li>3-5年以上软件开发经验，其中3年以上用户体系相关模块开发经验（有海外支付/跨境收单/合规金融项目背景者优先）；</li><li>有过用户体系、开卡或返佣类模块的重构/开发实战经验，能独立完成从方案设计到落地上线的全流程；</li><li>精通Java（基础扎实，熟悉高并发、多线程），熟悉微服务架构；</li><li>具备分布式系统（高可用、流量控制）设计经验，熟悉分布式事务原理及处理方案；</li><li>熟悉Redis、Kafka/RocketMQ等缓存与消息中间件，熟悉Docker/K8s容器化部署；</li><li>熟悉MySQL/Oracle等数据库设计与调优，具备数据库集群构建能力；</li><li>熟悉AI智能体（AI Agent）开发，有Claude Code、Codex等AI编程工具实战经验，能借助AI提升研发效率者优先；</li><li>动手能力强，能独立承担模块从0到1或存量重构的完整开发工作，而非仅停留在方案设计层面；</li><li>技术思路清晰，善于解决复杂问题，较强的逻辑思维能力及抗压能力，能在高并发、多渠道对接等复杂环境下推进工作。</li></ol>', '3-5年', '600a7fd9eff092270nJ63Nm_FlNV', '深圳 · 龙华区 · 民治', '17-22K', 'Java, Spring, SpringCloud, Kafka, Docker, JVM, MySQL, Oracle, 架构设计经验, 分布式经验, 微服务经验, 不接受居家办公', 'Java开发工程师（支付方向）', 'https://www.zhipin.com/job_detail/600a7fd9eff092270nJ63Nm_FlNV.html', '交通补助, 零食下午茶, 节日福利, 补充医疗保险, 加班补助, 带薪年假, 五险一金, 生日福利, 餐补, 夜班补助, 团建聚餐, 有无线网, 法定节假日三薪');
INSERT INTO `jobs` VALUES (339, '中赫慧能', '企业服务', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>有政务项目开发部署经验，负责大数据治理产品与项目的功能需求开发；</li><li>负责重点功能模块的设计，完成数据库设计 ；</li><li>持续迭代优化数据治理产品，以系统化、智能化能力高效支撑数据业务快速发展；</li><li>编写开发文档，编写相关技术方案文档；</li><li>能够独立完成项目相关系统分析、设计，技术文档、代码编写，确保编写的技术方案能够按计划要求高质量完成；</li><li>具备审核及评估相关方案与设计的能力，以确保其符合架构规划，满足业务需求；</li><li>能够独立及带领团队解决开发中遇到的难点问题；</li><li>较强的技术架构思维，确保设计的技术方案、开发的代码有较高性能、扩展性及前瞻性；</li><li>具备良好的抗压性、良好的学习能力及团队协作能力；</li><li>负责对突发事件快速响应、判断故障并有效解决；</li><li>熟悉高并发、高性能的分布式系统的设计、开发、问题解决以及调优相关知识；</li><li>能够完整理解产品的交互体验需求，并根据需求按时完成软件测试、开发任务,具备全栈开发能力；</li><li>精通架构设计方法、技术、过程及工具，熟悉主流的架构设计方法论和框架。</li></ol><p><strong>任职要求</strong></p><ol><li>计算机相关专业，全日制本科及以上学历，5年以上Java开发经验；带领过团队完成至少2个以上项目的全生命周期开发；</li><li>熟练掌握Linux系统日常操作，具备快速定位问题的能力，熟悉ELK、监控系统等技术；</li><li>精通JAVA、主流数据库、服务器；</li><li>熟练使用Dubbo、Spring、Spring Boot、Spring Cloud、Spring Cloud Alibaba、SpringMVC、MyBatis等主流开源框架，有实际项目应用经验；</li><li>熟练使用Idea、Git、Maven等工具，有消息中间件(RabbitMQ、RocketMQ、Kafka)使用经验，精通数据库MySql或Oracle，熟练使用NoSQL(Redis、Mongodb等)；</li><li>能比较熟练使用相关Web 开发技术，熟悉Jsp、Ajax、Javascript、HTML、XML、VUE等；</li><li>理解能力强，沟通思维清晰，勇于担当，甘于奉献，善于学习，交流分享；</li><li>对数据治理有一定的实践经验，熟悉数据治理领域知识和技能，对数据业务场景敏感优先；</li><li>具有较强的技术规划能力和组织协调能力，有大型系统架构设计的成品优先；具备良好的沟通能力，优秀的独立分析、解决问题能力；有技术材料输出经验，有汇报经验优先。</li></ol>', '3-5年', '6c4e261bbb0c402d1HN73Ny1F1JX', '深圳 · 南山区 · 科技园', '10-14K', 'Golang, Java, 团队管理经验, SpringCloud, Redis, Spring, ERP开发经验, 大数据经验, MySQL, PHP, MyBatis, 架构设计经验, Oracle', '后端开发工程师', 'https://www.zhipin.com/job_detail/6c4e261bbb0c402d1HN73Ny1F1JX.html', '五险一金, 带薪年假, 节日福利, 年终奖, 零食下午茶');
INSERT INTO `jobs` VALUES (340, '申创衡金', '计算机软件', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>核心开发：独立负责车险业务系统（如承保、批改等）功能模块的设计、开发与维护，高质量交付代码。</li><li>系统集成：负责与第三方渠道、合作平台、内部系统的接口设计与开发，确保系统间数据流畅交互。</li><li>质量保障：配合测试团队完成测试与缺陷修复，参与代码评审，确保系统稳定性和交付质量。</li><li>⽣产运维：能快速定位、分析与解决线上系统故障及性能问题，保障⽣产环境稳定。</li><li>团队协作：积极响应业务需求，主动与业务、测试、运维团队沟通协作，⾼效推动任务闭环。</li></ol><p><strong>岗位要求</strong></p><ol><li>全日制本科及以上学历，计算机相关专业，毕业满三年，具备2年以上Java开发经验。有保险、金融⾏业系统（特别是车险领域）开发经验者优先。</li><li>精通Java核心、多线程、集合框架，深入理解JVM原理（内存模型、GC机制）。熟练掌握Spring Boot、Spring Cloud Alibaba、MyBatis等主流框架及原理。</li><li>熟练掌握HTML5、CSS3、JavaScript（ES6+）核心，至少能熟练使用一门主流前端框架（Vue2/3或React），并有实际项目应用经验。</li><li>熟悉常用中间件，如消息队列（RabbitMQ/Kafka）、RPC框架（Dubbo/gRPC）。熟练使用IDEA、Maven、Git等开发与协作工具。</li><li>具备良好的SQL编写与优化能力，熟悉MySQL等数据库。掌握基本的Linux操作命令，能进行日常的部署、日志查看与问题排查。</li><li>具备优秀的沟通表达能力和团队协作精神，责任心强，能主动推动和解决问题。对新技术保持好奇心和学习热情，能快速适应业务与技术变化。</li></ol>', '3-5年', '91bf3e89924d2db10nZ-2t64FldR', '深圳 · 龙岗区 · 南联', '13-16K', 'Java, 不接受居家办公, SpringCloud, MySQL, MyBatis, Redis, Spring, Oracle', '中级java开发工程师', 'https://www.zhipin.com/job_detail/91bf3e89924d2db10nZ-2t64FldR.html', '节日福利, 通讯补贴, 员工旅游, 带薪年假, 股票期权, 年终奖, 补充医疗保险');
INSERT INTO `jobs` VALUES (341, '重庆零一数维人工...', '互联网', '20-99人', 'A轮', '本科', '<ol><li>负责公司业务系统后端开发及相关技术支持工作，以 Java 后端开发为主，同时参与 Python 服务开发和 AI 应用能⼒建设。</li><li>接受有培训经历的候选⼈，但需具备真实项⽬经验和独立开发能力；仅培训结业、缺乏实际项⽬经验者暂不匹配。</li><li>团队鼓励并要求拥抱 AI 编程工具，不严格区分前后端工程师，希望候选人具备一定全栈协作意识。</li><li>面试过程需本人独立完成，禁止代面、AI 代答或高度依赖 AI 生成回答。我们更关注候选人真实技术理解、实际项目经验和独立解决问题能力。</li><li>能接受根据项目需要进行短期或阶段性出差。</li></ol><p><strong>工作职责</strong></p><ol><li>负责业务系统后端开发，参与需求分析、接口设计、功能开发、测试联调及上线维护。</li><li>主要使用 Java 进行业务模块开发，包括接口开发、业务逻辑实现、系统优化及问题排查。</li><li>使用 Python 参与部分服务开发，包括 AI 应用接口、数据处理、工具服务等相关功能。</li><li>参与大模型相关应用开发，包括模型接口调用、知识库问答、智能助手、Agent 等业务场景落地。</li><li>负责系统与数据库、中间件、第三方服务等进行集成开发。</li><li>配合完成系统部署、日志分析、线上问题定位及故障处理。</li><li>参与代码评审、技术文档编写和团队协作，持续优化研发效率。</li><li>能够熟练使用 AI 编程工具辅助开发，提高编码、调试、测试和文档整理效率。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机、软件工程、人工智能等相关专业优先。</li><li>3 年以上后端开发经验，有独立负责业务模块开发经验。</li><li>熟悉 Java 开发，掌握 Java 基础语法、集合、多线程、异常处理等常用能力。</li><li>熟悉 SpringBoot、SpringCloud 开发，有实际项目开发经验。</li><li>具备 Python 开发能力，熟悉 FastAPI 或类似 Web 框架，能够完成服务接口和业务功能开发。</li><li>熟悉 HTTP 接口开发，了解接口鉴权、参数校验、异常处理等常见开发规范。</li><li>熟悉 MySQL、PostgreSQL 等数据库使用，能够完成表设计、SQL 编写和基础优化。</li><li>了解 Redis、消息队列等常见中间件，有实际使用经验优先。</li><li>熟悉 Linux 常用操作，能够进行服务部署、日志查看和问题排查。</li><li>熟悉 Git、Maven 等研发工具，具备团队协作开发经验。</li><li>了解大模型应用开发流程，了解 Prompt、RAG、知识库、工具调用等基本概念。</li><li>有 LangChain、LlamaIndex 等 AI 应用框架使用经验优先。</li><li>能够使用 Cursor、GitHub Copilot、ChatGPT 等 AI 工具辅助日常开发，并具备基本代码判断能力。</li><li>具备良好的代码习惯，能够编写结构清晰、易维护的代码。加分项1、有智能客服、知识库问答、企业搜索、流程自动化等 AI 应用项目经验。</li><li>有 RAG、Agent、大模型应用平台相关开发经验。</li><li>有企业级项目、ToB 项目或复杂业务系统开发经验。</li><li>有微服务、系统优化、高并发处理经验。</li><li>了解 Vue 等前端技术，能够配合完成接口联调和简单页面调整。</li><li>有使用 AI 工具提升研发效率、优化代码或辅助项目交付经验。</li></ol>', '3-5年', '3fcc19209cc62b0f0nF_09u9EFpR', '深圳 · 南山区 · 科技园', '13-16K·13薪', 'Java, AI后端应用开发, SpringCloud, MySQL, AI 编程, Redis, FastAPI, Spring, Python', 'AI 应用后端工程师', 'https://www.zhipin.com/job_detail/3fcc19209cc62b0f0nF_09u9EFpR.html', '绩效奖金, 定期体检, 加班补助, 年终奖, 有无线网, 五险一金, 团建聚餐');
INSERT INTO `jobs` VALUES (342, '运动帝图', '互联网', '20-99人', '不需要融资', '本科', '<p>职位名称：Java工程师</p><p><strong>岗位职责</strong></p><ol><li>参与后端架构和产品的研发，根据需求开发相关高性能、靠性的后台服务；</li><li>根据项目任务计划按时完成软件编码和单元测试工作；</li></ol><p><strong>任职要求</strong></p><ol><li>有扎实的Java基础，有钻研新技术的热情；</li><li>有创业者基因，有开发高品质产品、编写高质量代码的自我要求；</li><li>爱运动，有一项深度的体育运动爱好者优先；</li></ol>', '3-5年', '77744d6027ee56bd0XF_3tg~', '深圳 · 福田区 · 皇岗', '7-14K', 'Java', 'Java工程师', 'https://www.zhipin.com/job_detail/77744d6027ee56bd0XF_3tg~.html', '五险一金, 带薪年假');
INSERT INTO `jobs` VALUES (343, '云晓智联', '大数据', '0-20人', '未融资', '本科', '<p><strong>一、职位描述</strong></p><ol><li>项目总控：全面负责公司的项目需求理解、技术⽅案设计、⼯程量评估、排期制定及任务分解。主导项⽬开发过程，协调前后端、测试、运维等资源，确保项目按计划高质量交付；开发和维护物联⽹、养殖管理相关系统；</li><li>架构决策：负责系统架构设计、核心模块技术选型及难点攻关，对业务需求进行评审、开发实施、迭代优化；</li><li>团队管理：带领研发团队完成项目目标，提高技术水平及工程效率。</li></ol><p><strong>二、职位要求</strong></p><ol><li>计算机相关专业本科及以上学历，5年以上Java开发工作经验，2年以上技术团队管理经验；</li><li>精通Java/JVM、Spring Boot/Cloud、主流中间件（Redis, MQ, ES等）精通MySQL等数据库设计与优化。能深入理解分布式技术（事务、缓存、服务治理等）；</li><li>精通YOLO、OpenCV库，Python语言，TensorFlow或PyTorch深度学习框架；</li><li>具备优秀的项目管理能力，出色的团队领导力、沟通协调能力与技术影响力，卓越的分析与解决问题能力；</li></ol>', '3-5年', 'e328d5f67fbb06020nB92N24EFZY', '深圳 · 南山区 · 科技园', '12-18K', 'YOLO, Java, OpenCV, Redis, Spring', 'Java 后端开发工程师', 'https://www.zhipin.com/job_detail/e328d5f67fbb06020nB92N24EFZY.html', '股票期权, 保底工资, 年终奖, 五险一金, 绩效奖金, 团建聚餐, 零食下午茶');
INSERT INTO `jobs` VALUES (344, '熵基律动', '互联网', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><p>1:负责公司自研 SaaS 产品的Java 后端服务开发，参与系统架构设计及核心模块的技术方案制定。2:独立完成复杂业务功能的需求分析、设计、编码、测试与部署，保障代码质量与系统性能。3:对线上系统进⾏持续优化与重构，解决⾼并发、分布式环境下的技术难题，提升系统稳定性和可扩展性。4:与产品、前端、测试等团队⾼效协作，推动项目顺利迭代。跟踪并研究前沿技术，将其合理应用于项⽬，以改进系统架构和开发流程。</p><p><strong>任职要求</strong></p><p>1:统招本科及以上学历，计算机相关专业，拥有3 年及以上 Java 后端开发经验。2:精通 Java 语言，深入理解 JVM 内存模型、并发编程、集合框架等核心特性和运行机制。3:熟练掌握Spring Boot、Spring Cloud等至少一种主流 Web 框架及微服务生态，并了解其设计原理。4:精通 MySQL 数据库应用，具备优秀的索引优化、SQL 调优能力；熟悉 Redis 及其常用数据结构与应用场景。5:具备分布式系统开发经验，熟悉微服务架构，并有 gRPC、Kafka/RabbitMQ、ETCD/Consul 等技术的实际使用经验。6:具备高并发、大数据量系统的设计与性能调优实战经验。7:掌握 Linux 开发环境，熟练使用 Git，拥有良好的工程化实践，熟悉 Docker 及 CI/CD 流程。8:具备优秀的问题分析、逻辑思维能力和强烈的技术责任心，良好的团队沟通与协作精神。优先考虑（加分项）1:有基于 Kubernetes 的云原生项目开发或运维经验。2:熟悉 Prometheus、Grafana、ELK 等可观测性技术栈。3:有 AI 工程化或算法模型部署相关经验，或熟悉向量数据库、RAG 应用开发。</p>', '3-5年', 'ac7b6fc990db95550nB40t21FVZW', '深圳 · 南山区 · 科技园', '11-22K·14薪', 'Java, 不接受居家办公, 分布式经验, 微服务经验, SpringCloud, MySQL, 人工智能, Redis, 云计算经验, 架构设计经验, Spring, AI Agent', 'JAVA后端开发工程师(AI Agent)', 'https://www.zhipin.com/job_detail/ac7b6fc990db95550nB40t21FVZW.html', '节日福利, 团建聚餐, 绩效奖金, 零食下午茶, 餐补, 带薪年假, 五险一金, 股票期权, 年终奖, 有无线网');
INSERT INTO `jobs` VALUES (345, '辰宇', '咨询', '0-20人', 'A轮', '本科', '<p><strong>一、岗位描述</strong></p><ol><li>参与企业内部ERP的平台研发，包括HR、OA、CRM、财务、培训/学院、工单/任务等，打造企业级的saas开发生态；</li><li>参与系统的架构设计与底层能力集成，配合团队完成系统架构优化、技术难点攻关及代码重构；</li><li>⽂档的撰写、维护，以及团队知识与技术体系搭建。⼆、</li></ol><p><strong>任职要求</strong></p><ol><li>本科学历，计算机、软件、数学相关专业优先；</li><li>3-5年⼯作经验，具有一定的架构能力，有良好的团队合作及抗压能⼒，有强烈的主人翁意识推进事务进展；</li><li>Java基础扎实，熟悉面向对象编程，理解IO、多线程、集合等基础概念；</li><li>能熟练使用MYSQL与MongoDB数据库；</li><li>熟悉Spring、Spring Cloud、Spring Data、Spring Security等开源框架；</li><li>了解RabbitMQ等消息中间件；</li><li>理解微服务架构与分布式系统；</li><li>熟悉常用Linux命令，了解服务器应用的部署；</li><li>善于沟通及主动思考总结，倡导创新与持续优化，思路周密，代码严谨，对技术有强烈兴趣。三、加分项：</li><li>有运维开发经验；</li><li>有数据整理清洗经验；</li><li>有AI的模型、agent对接或自研经验；</li><li>有跨团队协调资源或主导过技术选型/推广的经验。四、团队氛围：我们采用敏捷开发模式，团队扁平化，没有繁琐的流程与会议，专注于技术视角。</li></ol>', '3-5年', '9303c9d178ee666c0nFz2t-0FVVY', '深圳', '10-15K', 'Java, Spring, SpringCloud, MySQL, MongoDB, 架构设计经验', 'java开发工程师', 'https://www.zhipin.com/job_detail/9303c9d178ee666c0nFz2t-0FVVY.html', '节日福利, 团建聚餐, 零食下午茶, 带薪年假, 股票期权, 绩效奖金');
INSERT INTO `jobs` VALUES (346, '万游商务旅游有限公司', '酒店/民宿', '20-99人', '未融资', '本科', '<p><strong>一、岗位职责</strong></p><ol><li>系统架构与核心开发：参与系统架构设计与技术选型，负责订单、定价、库存、结算对账等核心模块开发；对接OTA、PMS、GDS多渠道第三方接口，实现异常重试、熔断降级；搭建订单状态机、动态定价及库存管控逻辑，保障业务准确稳定。</li><li>接口开发与系统集成：负责内外系统接口及运营后台开发；对接微信、⽀付宝、银⾏⽀付渠道，实现分账、预授权、延迟结算等能力；完成短信、消息推送等基础服务集成。</li><li>性能优化与稳定保障：通过缓存、并行调⽤、线程池优化系统并发性能；采用异步机制处理耗时业务；搭建监控告警体系，配合自动化测试，保障系统高可用、高稳定性。</li><li>团队协作：输出架构、数据库、接口等技术文档；参与代码评审，规范开发标准；配合产品评估方案可行性，协同推进业务落地。</li></ol><p><strong>二、任职要求</strong></p><ol><li>3年以上Java开发经验，熟练掌握Spring Boot/Cloud、MyBatis；</li><li>精通JVM、多线程并发；熟练MySQL，具备复杂SQL编写、库表设计及慢调优能力；熟练Redis、消息队列，掌握API设计、鉴权、限流降级；</li><li>了解分布式事务，可解决跨服务数据一致性问题。</li><li>有OTA/酒店/旅游行业、高并发报价系统、订单状态机、结算对账系统开发经验者优先，熟悉缓存常见问题解决方案者加分。</li></ol><p><strong>三、薪资福利</strong></p><p>薪资：综合10000-15000元/月（底薪+绩效+提成）作息：早九晚六、双休，不强制加班</p><p><strong>福利</strong></p><p>五险、法定节假日、节日</p><p><strong>福利</strong></p><p>、定期团建、系统化培训团队：氛围轻松、激励完善、成长空间充足</p>', '3-5年', '2c46f7cbead7e93e0nF-2969F1NZ', '深圳 · 龙岗区 · 横岗', '10-15K', 'Java, Spring, SpringCloud, Kafka, JVM, MyBatis, MySQL, Redis, 架构设计经验, 微服务经验, ERP开发经验, 不接受居家办公', 'Java 开发工程师（OTA 酒店供应链中台）', 'https://www.zhipin.com/job_detail/2c46f7cbead7e93e0nF-2969F1NZ.html', '保底工资, 有无线网, 员工旅游, 绩效奖金, 底薪加提成');
INSERT INTO `jobs` VALUES (347, '美创商管', '物业管理', '20-99人', '', '本科', '<p><strong>岗位职责</strong></p><ol><li>后端核心开发：基于 SpringCloud/SpringBoot 搭建微服务，完成高并发业务模块、数据存储、中间件调优、接口设计、性能优化。</li><li>AI 工程落地：负责 Java 服务对接大模型 API（OpenAI、通义千问、⽂⼼⼀言、本地 LLaMA/Qwen 等开源大模型），封装统⼀ AI 调用 SDK、会话管理、提示词工程管理模块。</li><li>RAG 知识库开发：使用 Java 对接向量数据库（Milvus、Chroma、FAISS、PGVector），实现文档切片、向量化存储、相似度检索、知识库问答链路完整开发。</li><li>AI Agent、智能工作流开发：基于 Java 编排 Agent 任务、工具调用、多轮对话上下文管理，搭建智能客服、数据分析助手、代码助手、企业知识库系统。</li><li>推理服务集成：对接本地私有化大模型推理服务（Ollama、vLLM、TensorRT），实现 Java 侧负载均衡、限流、重试、异步推理、流式输出处理。</li><li>系统架构优化：解决 AI 场景下高并发问答、长文本处理、Token 计数、请求超时、向量检索慢、批量向量化等性能问题；做缓存、异步队列、分片优化。</li><li>数据与算法配合：配合算法工程师完成数据集处理、微调任务的调度管理，开发 AI 任务后台管理平台，监控模型调用成本、响应耗时、准确率。</li><li>技术沉淀：输出 AI+Java 后端技术规范、组件封装、通用中间件；参与技术方案评审，主导老旧系统 AI 化改造。</li></ol><p><strong>任职要求</strong></p><ol><li>Java 后端基础能力，本科及以上计算机相关专业。</li><li>精通 SpringBoot、SpringCloud、SpringCloudAlibaba 微服务体系，熟练使用 Nacos、Sentinel、Gateway、Feign 等组件。</li><li>精通 MySQL 索引优化、分库分表；熟练 Redis、RabbitMQ/Kafka、Elasticsearch 等中间件。</li><li>熟悉 JVM 调优、并发编程、线程池、分布式锁、分布式事务、高可用架构设计。</li><li>熟练 Docker、K8s 基础部署，能独立打包 Java 服务、配置 AI 服务容器编排。硬性 AI 相关能力（必备，缺一不可）--有大模型落地实战经验，独立用 Java 开发过大模型问答、RAG 知识库、智能对话类线上项目；不只是调用第三方 API 玩具项目。--熟悉主流大模型：开源 LLM（Qwen、Llama、GLM）、商用 API（通义、文心、GPT 系列），掌握流式返回 SSE 处理、Token 统计、上下文窗口管理。--精通 RAG 全链路 Java 开发：文本分割、Embedding 向量生成、向量库 Milvus/PGVector 增删改查、相似度召回、重排逻辑实现。--掌握提示词工程、多轮对话状态管理、会话记忆持久化；了解 Agent 工具调用、Function Call 开发。--熟悉 AI 推理服务对接：Ollama、vLLM、Triton，能通过 Java TTP/gRPC 调用本地私有化模型，处理批量推理、异步任务。--了解 AI 场景性能痛点：大请求限流、模型调用成本管控、缓存策略、长文本分片、并发问答资源隔离方案。</li></ol>', '3-5年', 'e238abb776add5910nFz2NS_E1tU', '深圳', '15-23K', 'Java, 分布式经验, 微服务经验, SpringCloud, MySQL, Hadoop, MyBatis', 'Java工程师', 'https://www.zhipin.com/job_detail/e238abb776add5910nFz2NS_E1tU.html', '');
INSERT INTO `jobs` VALUES (348, '深圳沃浦思必特信...', '计算机软件', '0-20人', '不需要融资', '大专', '<p><strong>职位描述</strong></p><ol><li>参与系统的开发、优化与维护，确保系统在高并发、高负载的环境下稳定高效运行；</li><li>关键技术研究和攻关，提供技术指导和⽀持；</li><li>参与技术⽅案设计，主导关键技术难题的攻关与技术创新，与产品、前端、测试等紧密合作，确保系统的开发与上线顺利进⾏。</li><li>系统架构的持续优化和重构，提高系统的容错能力和可维护性，确保系统在复杂环境下的稳定运⾏；</li><li>参与分析性能瓶颈，定位系统问题，并通过代码优化、并发控制、数据库优化等手段，提升系统性能；</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机、软件工程、电子信息等相关专业；</li><li>5年以上后端开发经验；</li><li>有高并发、低延迟系统设计和开发经验，熟悉系统的业务流程和核心技术；</li><li>熟悉分布式系统设计，掌握消息队列、数据库（如MySQL、Redis，mongodb，PostgreSQL等）及缓存技术，能够设计和优化大数据量高并发系统；</li><li>熟悉高性能计算、内存管理、并发编程，有独立解决问题的能力；</li><li>有java大数据查询、高并发优化及jvm性能调优的经验，能够有效解决系统瓶颈；</li><li>基础扎实，精通Java并发编程、JVM，理解网络通信、多线程等基础框架，对各种开源开发框架如Spring boot、mybatis，springcloud，zk，kafka等开发体系有深入的应用和优化经验，掌握它的原理和机制；</li></ol>', '3-5年', 'c27208f86fb9e1840nF609i_GVdT', '深圳 · 福田区 · 会展中心', '17-22K', 'Java, SpringCloud, Kafka, Dubbo, Elasticsearch, MySQL, Redis, Hive, 分布式经验, 大数据经验, 架构设计经验', '高级java开发工程师', 'https://www.zhipin.com/job_detail/c27208f86fb9e1840nF609i_GVdT.html', '绩效奖金, 五险一金, 法定节假日三薪, 全勤奖, 节假日加班费, 年终奖, 保底工资, 定期体检');
INSERT INTO `jobs` VALUES (349, '深电科', '通信/网络设备', '100-499人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>熟悉敏捷开发模式，根据设计文档和开发规范，独立编写高质量代码；</li><li>参与需求分析，进行功能设计并根据需求搭建开发环境；</li><li>发现并修复BUG，不断优化现有产品，提⾼产品稳定性、可扩展性及⽤户体验；</li><li>参与开发成果评审，关注前沿技术研究，并应⽤于项目开发中。</li></ol><p><strong>岗位要求</strong></p><ol><li>JAVA基础知识扎实、熟悉jvm原理、多线程、面向对象设计思想、熟悉spring、spring mvc、mybatis、hibernate、fastjson/jackjson等主流开源框架；</li><li>掌握微服务架构，⾄少参与一个微服务项目开发，熟练运用spring boot、ZooKeeper、eureka/Consul、dubbo、redis、zuul、Spring-Cloud-Config等技术及nginx、gradle、maven、gitlab、nexus、swagger等工具；</li><li>熟练运用JavaScript等前端脚本语言，如：jquery、vue等JS框架；</li><li>熟练运用Oracle、MySQL等主流数据库技术，有SQL性能调优经验；</li><li>熟练掌握TOMCAT，nginx 必要配置。</li><li>了解智能体开发过程及工具，有智能体开发经验者优先。</li></ol>', '3-5年', '8b316c80db3d44540nR40tm4E1ZU', '深圳 · 福田区 · 景田', '10-15K', '', 'java开发工程师', 'https://www.zhipin.com/job_detail/8b316c80db3d44540nR40tm4E1ZU.html', '');
INSERT INTO `jobs` VALUES (350, '盛迪嘉支付', '互联网', '100-499人', '不需要融资', '本科', '<p><strong>一、岗位职责</strong></p><ol><li>有跨境收款、付款、结售汇、渠道网关、清算对账、风控平台核心模块设计开发；</li><li>搭建过分布式金融系统，处理过多币种资⾦流转、外管局国际收⽀申报、外贸单证关联；</li><li>对接海内外银⾏、支付渠道，实现通道接入、路由、⾃动重试、跨境交易状态机；</li><li>系统性能优化、线上故障排查、数据库分库分表、保证资金数据一致性。</li></ol><p><strong>二、任职要求</strong></p><ol><li>参与架构评审、输出技术方案、代码评审，沉淀金融组件；</li><li>扎实 Java 基础，熟悉 JVM、多线程、SpringBoot/SpringCloud 微服务；</li><li>精通 MySQL 索引、事务、锁机制；熟练 Redis、消息队列；</li><li>熟悉国际支付、外汇交易、多币种账务账户；</li><li>熟悉金融审计、交易可追溯体系；理解资金系统对账、账务、交易链路；了解AML、KYC、外贸 B2B 业务加分；</li><li>良好文档能力，能承受金融系统线上应急压力。</li></ol>', '3-5年', '99b1ea33de9cd5080nJ739--FFBW', '深圳 · 宝安区 · 西乡', '15-30K', 'Java, Spring, SpringCloud, MyBatis, MySQL', '跨境后台开发', 'https://www.zhipin.com/job_detail/99b1ea33de9cd5080nJ739--FFBW.html', '双休, 节日福利, 零食下午茶, 朝九晚六, 年终奖');
INSERT INTO `jobs` VALUES (351, '九天创新(广东)智能', '人工智能', '20-99人', 'A轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责商用服务机器人PaaS、SaaS云平台需求分析、架构设计、技术选型及长期技术规划；</li><li>负责机器人云端业务架构、数据架构、应用架构等⽅案的选型、搭建与优化；</li><li>主导云平台相关业务性能、稳定性优化、技术难题攻关、发现并解决各类潜在技术风险；</li><li>研究探索机器⼈云平台前沿技术，改进⼯具链，提高软件可用性及开发效率，降低维护成本。</li></ol><p><strong>任职要求</strong></p><ol><li>⼤学本科以上学历，计算机、网络通信、信息相关专业，又从0到1搭建大型云平台PaaS系统建设经验；</li><li>精通java、python、golang、nodejs等至少一种开发语言、云原生开源技术，有智能硬件相关云平台搭建经验者优先；</li><li>基本掌握业界主流云厂商AWS、Azure、腾讯云等云服务架构设计原理，并有大型云平台 建设成功项目经验；</li><li>熟悉分布式系统的设计和应用，了解Kubernetes、Openstack、Docker等云计算技术。</li><li>了解Netflix、EDAS等业界微服务架构，有相关架构设计经验者优先。</li><li>关注云计算技术发展，能够掌握技术发展趋势与业务发展动向，对关键技术有自己独特见解；</li><li>有优秀的数据分析能力和需求分析能力，很强的AI编程能力，能够独立开展业务调研、数据分析、报告编写工作。</li></ol>', '3-5年', '9215fc742a8dfb480nFz2dS9FVpV', '深圳 · 南山区 · 科技园', '15-30K', 'Java, Python, Golang, SpringCloud, Dubbo, Elasticsearch, Spring, Kafka, MySQL, Redis, 架构设计经验, 分布式经验, 微服务经验, 云计算经验, 不接受居家办公', '云平台后端工程师', 'https://www.zhipin.com/job_detail/9215fc742a8dfb480nFz2dS9FVpV.html', '带薪年假, 五险一金, 餐补, 全勤奖, 股票期权, 员工旅游, 生日福利, 年终奖, 法定节假日三薪');
INSERT INTO `jobs` VALUES (352, '携银信息', '计算机软件', '100-499人', '未融资', '本科', '<p>岗位缺：初级--中级--高级 java开发工程师</p><p><strong>任职要求</strong></p><ol><li>计算机相关专业，3年及以上Java后端开发经验，有数据类平台开发经验优先。</li><li>熟练掌握Java基础及Spring、SpringBoot、SpringCloud等主流微服务框架。</li><li>熟悉MQ、Redis等中间件，具备良好的SQL编写、性能优化及数据处理能力。</li><li>具备独立需求拆解、⽅案设计、开发落地与问题排查能⼒。</li><li>代码规范良好，沟通协作能⼒强，责任心强，可高效完成项⽬节点任务。加分项：</li><li>有AI应用开发实战经验，参与过智能数据平台、AI业务系统开发优先2、熟练使用Python，可独立完成数据处理、脚本开发等工作优先;</li><li>熟悉Docker容器部署、环境搭建与服务运维优先;</li><li>具备大型平台项目架构设计、核心模块主导开发经验优先。</li></ol>', '3-5年', '941ae92492195f8c0nF52du5GFpT', '深圳 · 福田区 · 上步', '11-20K', 'Java, MySQL, Redis, 架构设计经验, Spring', 'java开发工程师', 'https://www.zhipin.com/job_detail/941ae92492195f8c0nF52du5GFpT.html', '餐补, 补充医疗保险, 年终奖, 定期体检, 节日福利, 五险一金, 生日福利, 员工旅游, 团建聚餐, 绩效奖金, 带薪年假, 零食下午茶, 加班补助');
INSERT INTO `jobs` VALUES (353, '信运派', '跨境物流', '100-499人', '不需要融资', '大专', '<p><strong>一、岗位职责</strong></p><ol><li>基于业务需求，设计、开发和维护稳定、高效、可扩展的服务端业务逻辑和API接口，为前端和移动端提供坚实的数据支撑。</li><li>深入理解业务流程和数据模型，设计⾼效、可维护的数据库表结构，并编写优化后的SQL语句，确保数据存储和查询的性能满⾜业务⾼峰期的需求。</li><li>保障系统的稳定性、安全性和可扩展性，能够预见并解决潜在的业务增长带来的技术挑战，为业务的持续发展提供技术保障。</li><li>积极参与技术方案的评审和代码审查，从业务价值和技术可行性角度提出建设性意见，确保技术⽅案能够更好地服务于业务目标。</li><li>关注系统性能瓶颈，通过技术手段优化接口响应速度、资源利用率，直接提升业务处理效率和用户体验。</li><li>参与技术选型和架构设计，为业务的快速迭代和创新提供技术基础。</li></ol><p><strong>二、任职要求</strong></p><ol><li>专科及以上学历；3年以上JAVA开发经验。</li><li>精通 Java 编程，深入理解 Spring Boot/Spring Cloud 微服务框架；</li><li>具备扎实的数据库设计和SQL优化能力，熟悉MySQL, PostgreSQL等关系型数据库，能够处理大规模数据和高并发请求。</li><li>对分布式系统、微服务架构有深入理解和实践经验，能够构建高可用、可伸缩的业务系统。</li><li>具备良好的系统设计能力，能够从业务需求出发，考虑系统的可扩展性、稳定性、安全性以及成本效益。</li><li>有参与技术方案评审和代码审查的经验，能够从业务和技术双重角度评估方案。</li><li>具备优秀的分析问题和解决问题的能力，能够快速定位并解决线上业务问题。</li><li>对数据安全和隐私保护有高度重视。</li></ol>', '3-5年', 'f0acf633988889db0nJ529S7FlRV', '深圳 · 龙岗区 · 坂田', '12-18K', 'Java, Spring, MySQL, ERP开发经验', 'JAVA后端开发', 'https://www.zhipin.com/job_detail/f0acf633988889db0nJ529S7FlRV.html', '团建聚餐, 底薪加提成, 员工旅游, 夜班补贴, 节假日加班费, 年终奖, 零食下午茶, 免费工装, 带薪年假, 生日福利, 定期体检, 五险一金, 节日福利, 绩效奖金, 保底工资, 有无线网, 夜班补助');
INSERT INTO `jobs` VALUES (354, '彬彬美文化', '互联网', '0-20人', '未融资', '本科', '<ol><li>负责公司出海短剧业务全系列后端系统的开发与日常维护，涵盖H5后台、APP服务端、运营管理后台、数据统计后台等核心业务系统，保障系统稳定运行。</li><li>独立完成后端接口开发、数据库表结构设计、核⼼业务逻辑开发，同步规范编写接口⽂档，保证代码及⽂档标准化、可维护。</li><li>配合前端完成接口联调对接，快速响应运营、产品的业务需求，高效完成功能迭代，支撑业务快速落地。</li><li>深度参与核⼼业务模块开发，包含用户体系、订单充值、广告投放数据、ROI统计、素材数据统计等关键业务功能搭建与优化。</li><li>负责线上日常问题排查与修复，快速处理接口异常、慢SQL卡顿、服务器运行异常等线上故障，保障业务平稳运转。</li><li>持续跟进业务发展需求，针对性优化系统性能，提升系统稳定性、接口响应速度及业务数据统计准确性。</li></ol><p><strong>任职要求</strong></p><ol><li>全日制本科学历（学信网可查）2、熟练 Java/PHP/Go/Node.js 任一后端语言，有完整项目经验，可独立开发落地需求；</li><li>精通 MySQL，能自建表结构、编写 SQL，会 SQL 优化与数据问题排查；熟悉 Redis 使用，精通接口开发，有后台管理系统开发实战经验；</li><li>代码规范，沟通协作良好，能独立负责中小型模块全流程开发；</li><li>责任心强，善于拆解业务需求，高效推进版本迭代落地。加分项1、拥有短剧、小说、视频、直播、游戏、出海APP相关项目后端开发经验。</li><li>熟练使用 AI开发工具，能够借助工具提升开发效率。岗位</li></ol><p><strong>福利</strong></p><p>入职即缴五险一金，按法定节假日休假。日常下午茶，舒适工作氛围，明确晋升路径。工作时间：9:30-12：00 13:30-19:00 大小周制度。</p>', '3-5年', '12a9f40ee71bc1a20nJ63Ny0ElpR', '深圳 · 南山区 · 科技园', '10-15K', 'Java, PHP, Spring, MySQL, Redis', '短剧后端开发', 'https://www.zhipin.com/job_detail/12a9f40ee71bc1a20nJ63Ny0ElpR.html', '五险一金, 零食下午茶, 年终奖, 绩效奖金, 底薪加提成, 团建聚餐');
INSERT INTO `jobs` VALUES (355, '数鑫科技', '计算机软件', '20-99人', 'A轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>在高级工程师的带领下，参与软件模块层面的设计工作、以及设计⽂档输出⼯作；</li><li>参与软件模块内部的结构设计；</li><li>负责软件模块的代码编写、单元测试⼯作，确保代码与架构设计、软件模块规格的一致性，确保代码质量；</li><li>参与核心框架、核⼼组件的技术积累工作；</li><li>参与对服务端工程师之间的交叉代码REVIEW；</li><li>负责现网问题的定位和解决；</li></ol><p><strong>岗位要求</strong></p><ol><li>良好的团队沟通协作能力；</li><li>有互联网＋或者移动互联网平台的项目开发经验；</li><li>熟悉面向对象程序设计，熟悉各种主流的设计模式；</li><li>熟悉微服务架构技术，精通SpringBoot、SpringCloud等技术框架的编程；</li><li>熟悉nginx的部署和配置；</li><li>熟悉Lua、OpenResty的编程；</li><li>熟悉Redis集群、ElastichSearch集群的部署和编程；</li><li>熟悉MySQL集群的部署、以及MySQL编程；</li><li>熟悉Linux环境；熟悉SVN、GIT、禅道等工具的部署和使用；</li><li>了解OpenAPI规范体系，熟悉RESTFull规范体系；熟悉Swagger技术体系；</li><li>熟悉docker、K8S者优先；</li></ol>', '3-5年', '59138cb17472c6260nB70t20FlZU', '深圳 · 南山区 · 蛇口', '12-20K', 'Java, Spring, Kafka, Nginx, SpringCloud, MySQL, Oracle, Redis, Spark', '服务端工程师', 'https://www.zhipin.com/job_detail/59138cb17472c6260nB70t20FlZU.html', '零食下午茶, 带薪年假, 节日福利, 员工旅游, 生日福利, 团建聚餐, 股票期权, 五险一金');
INSERT INTO `jobs` VALUES (356, '爱生生命', '医疗健康', '20-99人', 'A轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责参与公司项目业务相关模块的设计和研发。</li><li>参与需求分析、需求评审、撰写相关软件开发文档；</li><li>负责各业务模块功能实现与单元测试，保证项目进度和质量。</li><li>完成公司项目中基于脚本⽂件的体检报告检测流程或qiime-2检测流程的修改；</li><li>完成公司业务相关的Web端/⼩程序功能实现。以上4，5选⼀</li></ol><p><strong>任职要求</strong></p><ol><li>2年以上实际Java、python类软件项目开发工作经验，注：同时招收⼤学实习生；</li><li>扎实的Java基础知识，熟练使用spring、springcloud、springboot、mybatis或SSH等框架，熟悉后台技术开发；</li><li>熟练掌握BS相关的开发技术，熟悉前端相关技术（如HTML5、AJAX、AngularJS和vue等），熟悉redis、memcached等缓存技术；</li><li>熟悉微信小程序开发，有至少两年的工作经验；</li><li>熟练使用MySQL、Oracle、mongodb等数据库，熟悉Linux或windows平台；</li><li>具有良好的编码习惯和较强的文档编写能力；</li><li>工作严谨、认真负责、积极主动，有较强的责任心和事业心、有良好的沟通能力和理解能力，有良好的团队合作精神;</li><li>2，3或5至少熟悉一项。</li></ol>', '3-5年', 'd27b33eb58c99b6f0nF53d--FFFS', '深圳 · 福田区 · 上步', '7-12K', 'Java, Spring, MySQL', '软件开发工程师', 'https://www.zhipin.com/job_detail/d27b33eb58c99b6f0nF53d--FFFS.html', '带薪年假, 五险一金, 节日福利, 年终奖, 股票期权, 团建聚餐, 零食下午茶, 绩效奖金, 员工旅游, 法定节假日三薪, 通讯补贴, 意外险');
INSERT INTO `jobs` VALUES (357, '中控美芯', '电子商务', '0-20人', '不需要融资', '本科', '<p>【</p><p><strong>岗位要求</strong></p><ol><li>有自己的一套解决问题方法，能够独自完成线上问题排查与调优工作；</li><li>具有扎实的Java编程基础，对IO、多线程、JVM原理有一定的了解；</li><li>乐于在复杂系统中定位关键性能问题，强烈的求知欲、能够主动优化系统性能瓶颈；</li><li>熟悉缓存技术(redis)、搜索技术(ES)、异步框架、集群与负载均衡、消息中间件等领域；</li><li>参与或主导高并发项目研发、有大型分布式、高并发、高性能、高可用系统的设计开发经验；</li><li>对技术有热情，勤奋、乐于学习，有技术驱动业务的冲劲；</li><li>有很好的分析问题和解决问题的能力，责任心强，善于学习，善于沟通和表达，有良好的团队合作意识。</li></ol>', '3-5年', 'f11372a8199fc68f1nx70t6_FlVW', '深圳 · 龙岗区 · 大运', '15-30K', 'Linux, 架构师, 软件工程师, Windows, 高级软件工程师, 中级软件工程师, Android', '软件工程师', 'https://www.zhipin.com/job_detail/f11372a8199fc68f1nx70t6_FlVW.html', '五险一金');
INSERT INTO `jobs` VALUES (358, '全民互动 互联网', '游戏', '100-499人', 'A轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>聚焦游戏中台核心业务，负责核心模块的编码实现，迭代。保障系统在用户高频请求场景下的稳定运⾏。</li><li>及时响应并处理线上问题，快速定位并解决，保障系统可⽤性。</li><li>参与技术⽅案评审，攻克技术难点，持续优化系统性能4. 深度理解游戏发行、广告投放、数据中台等业务场景，将业务战略转化为合理技术⽅案，平衡业务迭代速度与技术架构健康度。</li><li>调研行业前沿技术，引入合适的技术框架与工具，推动团队工程化、自动化能力升级。</li></ol><p><strong>岗位要求</strong></p><p>● 计算机相关专业，本科及以上学历，3 年及以上 Java 后端开发经验。● 熟练使用 Spring Boot + Spring Cloud 微服务架构，熟悉Gateway、Nacos、Feign、Sentinel。● 熟练使用 MySQL，具备SQL优化、索引设计、分库分表实战经验。● 熟练使用 Redis 缓存技术，熟悉分布式锁、缓存穿透/击穿/雪崩解决方案。● 熟练使用 RabbitMQ/Kafka 消息队列，掌握消息可靠性保障机制。● 掌握Vue前端开发技能，具备全站开发经验。【加分项】● 具备大规模高并发、高吞吐、高可用系统设计与实战经验。● 熟悉ClickHouse、Doris列式数据库以及海量数据实时查询与分析优化，适配游戏发行数据统计场景。● 有数据中台、广告投放系统、游戏发行相关平台开发经验。</p>', '3-5年', '9316ae0de6307ae80nd_0t-6ElBS', '深圳 · 龙岗区 · 坂田', '12-16K', 'Java, 大数据经验, 不接受居家办公, MySQL, Redis, Spring', '中级java开发工程师', 'https://www.zhipin.com/job_detail/9316ae0de6307ae80nd_0t-6ElBS.html', '员工旅游, 零食下午茶, 生日福利, 节日福利, 餐补, 带薪年假, 五险一金, 文娱活动, 全勤奖, 加班补助');
INSERT INTO `jobs` VALUES (359, '励科智慧楼宇', '物联网', '20-99人', '不需要融资', '本科', '<p><strong>一、 岗位职责</strong></p><ol><li>参与物业管理与智慧楼宇领域AI应用场景的研究与落地，包括但不限于：AI客服、AI工单助手、AI巡检与设备故障诊断、AI知识库与智能问答、AI能耗分析与技能优化、AI安防预警、AI管理决策⽀持；</li><li>基于开源⼤模型开展AI应⽤研发与落地，围绕Qwen、DeepSeek、GLM等国产及国际开源模型进行部署、调优与业务应用；</li><li>负责⼤模型（LLM）在物业及楼宇管理场景中的应用开发与优化；</li><li>负责AI智能体（Agent）设计、工具调用与业务流程自动化；</li><li>基于物联网平台数据，开展设备运行分析、预测模型及AI算法应用；</li><li>配合公司现有智慧楼宇平台进行AI模块开发、接口对接与系统集成；</li><li>参与视频AI、语音AI、设备AI等方向的技术研究与测试；</li><li>跟踪国内外AI技术与开源生态发展，探索适用于物业行业的AI产品与解决方案；</li><li>编写技术文档、方案材料及演示Demo。</li><li>薪资待遇：15K–30K/月（根据能力与经验面议）二、 素质要求：（一）基础要求1. 本科及以上学历，计算机、人工智能、软件工程、自动化、电子信息、物联网等相关专业；</li><li>对AI、大模型、智能体等方向有较强兴趣，关注行业发展；</li><li>具备良好的逻辑思维能力、学习能力与问题分析能力；</li><li>责任心强，具备良好的沟通协作能力；</li><li>愿意深入物业、楼宇、设备运维等实际业务场景；</li><li>具备较强的动手能力与技术钻研精神，能够快速学习新技术并推动落地；</li><li>年龄28岁以内。</li><li>可接受相关专业优秀应届毕业生；（二）</li></ol><p><strong>技术要求</strong></p><p>（满足部分即可）1. 具备以下一种或多种相关开发能力：Python开发；Java / Go / Node.js 后端开发；Web前端开发；数据处理与分析；AI应用开发；API接口开发与系统集成。2. 了解或接触过以下技术优先：大模型应用：OpenAI、DeepSeek、Qwen、GLM 等；AI应用框架：LangChain、LlamaIndex、Dify、Coze；RAG知识库；AI Agent智能体；MCP、Function Call 等工具调用；向量数据库；AI工作流编排。（三）优先条件：具备以下任一经验优先： ◦ 有AI项目实践经验； ◦ 有智能体（Agent）开发经验； ◦ 有RAG知识库项目经验； ◦ 有物联网平台开发经验； ◦ 有视频识别/视觉AI经验； ◦ 有物业、楼宇、机电行业相关经验； ◦ 有开源项目或个人作品； ◦ 有参加AI竞赛、创新创业项目经历。</p>', '3-5年', '651a6220c62a4d970nB52tu5GFpU', '深圳 · 福田区 · 岗厦', '15-30K', 'Java, 物联网经验, 大数据经验, 团队管理经验, 不接受居家办公', 'AI应用研发工程师（物业与智慧楼宇方向）', 'https://www.zhipin.com/job_detail/651a6220c62a4d970nB52tu5GFpU.html', '包住, 餐补, 带薪年假, 免费工装, 宿舍有空调, 加班补助, 意外险, 生日福利, 法定节假日三薪, 零食下午茶, 定期体检, 团建聚餐, 年终奖, 工龄奖, 高温补贴, 补充医疗保险, 夜班补助, 五险一金, 节假日加班费, 节日福利');
INSERT INTO `jobs` VALUES (360, '深圳财阜教育有限公司', '咨询', '20-99人', '未融资', '本科', '<p>boss</p><p><strong>岗位职责</strong></p><ol><li>参与软件产品的需求分析、技术方案设计，负责后端核心业务模块的代码开发、单元测试及集成测试。</li><li>严格遵循开发规范与流程，保障代码质量与开发效率，及时修复开发过程中出现的BUG，确保项目按时交付。</li><li>配合前端开发团队完成接口联调工作，提供稳定、⾼效的后端接口⽀持，协助解决前后端交互过程中的技术问题。</li><li>参与系统的⽇常维护与优化，包括性能优化、功能迭代等，提升系统的稳定性与用户体验。</li><li>积极参与技术分享与团队讨论，主动学习新技术、新框架，持续提升自⾝技术能力。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机相关专业，3年以上JAVA开发经验，有相关项目开发经验者优先。</li><li>精通 PHP（Hyperf/Laravel/ThinkPHP）、JAVA基础语法，熟练掌握PHP+‌HTML‌+CSS‌+JavaScrip+mysql+redis+hyperf等主流开发框架，了解微服务相关技术者优先。</li><li>熟悉MySQL、达梦等关系型数据库的使用与基本优化，具备一定的SQL编写与调优能力。</li><li>了解分布式系统、消息队列、缓存等技术的基本原理与应用场景，有相关实践经验者优先。</li><li>具备良好的编码习惯、逻辑思维能力及问题排查能力，具有较强的责任心与团队协作精神。</li></ol>', '3-5年', '7644e9829159d2a00nd-2tW9F1JS', '深圳 · 福田区 · 购物公园', '13-20K', 'Java, 不接受居家办公, 分布式经验, MySQL, PHP', '后端工程师', 'https://www.zhipin.com/job_detail/7644e9829159d2a00nd-2tW9F1JS.html', '团建聚餐, 工龄奖, 员工旅游, 零食下午茶, 全勤奖, 加班补助, 五险一金, 绩效奖金, 年终奖, 定期体检, 带薪年假');
INSERT INTO `jobs` VALUES (361, '青牛智胜科技有限公司', '计算机软件', '20-99人', 'B轮', '本科', '<p><strong>职位描述</strong></p><p>微服务架构\n测试测试测试测试测试\n方巨英\n今日活跃\n青牛智胜科技有限公司\n·\n招聘者\n竞争力分析\n查看完整个人竞争力\n个人综合排名：在人中排名第\n你在？位置\n一般 良好 优秀 极好\nBOSS 安全提示\n严禁用人单位和招聘者用户做出任何损害求职者合法权益的违法违规行为，包括但不限于扣押求职者证件、收取求职者财物、向求职者集资、让求职者入股、诱导求职者异地入职、异地参加培训、违法违规使用求职者简历等，您一旦发现此类行为， 请立即举报\n公司介绍\n青牛智胜（深圳）科技有限公司成立于2018年5月，总部位于深圳市南山区，是国内领先的对话式AI国家高新企业，2023年被认证为深圳市专精特新中小企业。\n公司核心产研团队来自于原腾讯TEG智能客服团队，专注于生成式AI，自然语言理解、对话处理、融合网络、深度学习、知识工程、文本处理等技术研究，已构建AICC智能客服平台，AICP智能培训平台， AIDH互动数智人，AISG 智慧文旅平台等产品矩阵。\n公司已为文旅、金融、运营商、政务、物流等行业的多家标杆企业提供服务，每日在公司产品运营平台上发生数亿级次对话，不断提升沟通效率及用户体验，为企业及用户带来超预期的使用价值。\n查看全部\n工商信息\n公司名称\n青牛智胜（深圳）科技有限公司\n法定代表人\n沈洪波\n成立日期\n2018-05-23\n企业类型\n有限责任公司\n经营状态\n存续\n注册资金\n4396.2783万人民币\n查看全部\n工作地址\n深圳南山区深圳湾科技生态园5楼\n点击查看地图\n更多职位\n看过该职位的人还看了\njava开发（半导体大厂）\n15-25K\n某知名半导体/芯片公司\n深圳\nweb3后端开发工程师\n15-20K\n深圳通盛源科技\n深圳\nJava工程师\n15-30K·15薪\n某知名公司\n深圳\njava开发（半导体大厂\\国企\\六险一金）\n15-25K·13薪\n某大型公司\n深圳\nFDE工程师（跨境电商+AI）\n15-20K\n增量科技\n深圳\nJava开发（大厂，六险一金）\n15-25K·13薪\n某大型公司\n深圳\n精选职位\nJAVA（双倍工资+六险一金）\n15-30K\n华为\n深圳\n高级java开发工程师\n15-30K\n嘉立创\n深圳\nFDE工程师（跨境电商+AI员工方向）\n15-18K·13薪\n增量科技\n深圳\nJava\n15-16K\n同和信息技术有限公司\n深圳\n中级java开发工程师\n15-18K\n众投互联\n深圳\nJava\n15-30K·14薪\n艾麦物流\n深圳\n深圳\n搜索\n城市招聘 热门职位 推荐公司 热门企业\n昆明招聘\n牡丹江招聘\n宜宾招聘\n乌鲁木齐招聘\n衡阳招聘\n深圳招聘\n四平招聘\n平顶山招聘\n沈阳招聘\n海北藏族自治州招聘\n首页深圳招聘·Java招聘深圳Java招聘青牛智胜科技有限公司Java招聘\n页面更新时间：2026-08-04\n企业服务热线和算法/未成年人等举报渠道 400 065 5799\n老年人直连热线400 661 6030\n工作日 8:00 - 22:00\n休息日 8:00 - 22:00\n企业服务\n职位搜索\nAPP\n投资者关系 Investor Relations\n直品公益基金会\n求职技巧\n使用与帮助\n协议与规则\n隐私政策\n防骗指南\n使用帮助\n联系\n北京华品博睿网络技术有限公司\n公司地址 北京市朝阳区太阳宫中路16号院1号楼18层1801内09\n违法和不良信息举报邮箱/未成年人举报渠道 jubao@.com\nCopyright © 2026 京ICP备14013441号-5京ICP证150923号 电子营业执照 京公网安备11010502032801 朝阳网警 人力资源服务许可证 网上有害信息举报专区 朝阳区人社局监督电话 算法备案信息</p>', '3-5年', 'a7524d4901f18d5c1Xd73Nq5F1BQ', '深圳 · 南山区 · 科技园', '15-16K', '微服务架构', 'Java', 'https://www.zhipin.com/job_detail/a7524d4901f18d5c1Xd73Nq5F1BQ.html', '员工旅游, 薪资普调, 定期体检, 周末双休, 团建聚餐, 通讯补贴, 带薪年假, 绩效奖金, 餐补, 节日福利, 加班补助');
INSERT INTO `jobs` VALUES (362, '越航物流', '跨境物流', '100-499人', '未融资', '大专', '<p>我们是一家创立于2002年的国际物流企业，是国家AAAAA级重点物流企业。也是阿里巴巴国际站最早一批线上国际物流服务商企业。⼆⼗三年资深国际物流集货庄家。在招岗位：中级JAVA开发要求TO B项⽬经验</p><p><strong>薪资福利</strong></p><p>薪资10-15K，月休6天，入职缴纳社保，提供免费住宿-⽣日节日礼物，入职满一年有年终奖，带薪年休假。</p><p><strong>岗位职责</strong></p><p>及</p><p><strong>任职资格</strong></p><ol><li>3年以上JAVA开发经验，具备良好的编程习惯2、具备跨境物流行业经验，有WMS,OMS,TMS项目开发经历3、精通Spring、MyBatis、SpringMVC等应用框架并熟悉实现鳛啥铎原理;</li><li>精通JVM,GC,I0,多线程等原理，具备线上问题排查解决与调优能力;</li><li>熟练使用SpringBoot，SpringCloud Alibaba进行服务化的开发与监测6、精通各类中间件设计原理如Redis、MQElasticSearch，Mongodb等，并能熟练使用;</li><li>熟悉主流数据库Mysql/Oracle，具备数据建模和分库分表设计与及慢SQL分析和优化能力;</li><li>有中大型分布式、高并发、高负载、高可用系统架构设计和实施经验;</li><li>责任心强，具备良好的问题分析能力、外部沟通和团队协作能力，能独立完成系统调优设计，解决复杂应用问题;</li><li>优先考虑熟悉跨境物流、国际货代业务运作模式，对关务、仓储、干线、尾程等环节有了解者;.对哲盟V5, 易宇通K5, 易抵达等系统有开发经验者优先;具备基础的技术理解能力，能与开发人员讨论技术实现方案。</li></ol>', '3-5年', 'a83f250c7c805c0703N82dW4FlRQ', '深圳 · 宝安区 · 福永', '10-15K', 'Java, 不接受居家办公, 分布式经验, SpringCloud, MySQL, Spring', '包住宿-java 开发（中级）-国际物流行业', 'https://www.zhipin.com/job_detail/a83f250c7c805c0703N82dW4FlRQ.html', '生日福利, 绩效奖金, 提供住宿, 全勤奖, 保底工资, 节日福利, 团建聚餐, 包住, 年终奖, 购买五险, 员工旅游, 定期体检, 底薪加提成, 宿舍有空调, 带薪年假, 五险一金, 零食下午茶');
INSERT INTO `jobs` VALUES (363, '招商永隆银行深圳分行', '计算机服务', '100-499人', '', '本科', '<p>该岗位为招商永隆银行子公司-招商永隆信息技术（深圳）有限公司正式编制，工作地点平湖，需参加线下面试，英语需过4级。⼯作</p><p><strong>职责</strong></p><ol><li>根据项⽬具体要求，负责项⽬的需求文档编写、设计、开发及投产；</li><li>持续提升系统性能和稳定性，扫除技术风险；</li><li>维护现有系统，快速定位并修复现有软件缺陷。</li></ol><p><strong>任职资格</strong></p><ol><li>本科及以上学历，计算机相关专业，2年以上工作经验，有银⾏从业经验者优先；</li><li>扎实的编程能力，熟练掌握Java编程语言，精通熟悉Spring Boot/Spring Batch/Mybatis等开源框架，kafka、redis等中间件，熟悉SpringCould生态，在GitHub有开源项目者优先；</li><li>精通数据库原理，精通MySQL、Oracle实践并熟悉其规范要求，对于Hadoop, Hive, Spark, Flink, Hbase有实践并熟悉者优先；</li><li>熟悉分布式系统设计与开发、负载均衡技术、系统容灾设计、高可用系统等相关知识者优先；</li><li>熟悉软件测试基本理论和方法，掌握任意一种主流开源测试软件框架/工具者优先。</li></ol>', '3-5年', 'df0e4ad5c8dc2d9203N82dq1ElJZ', '深圳 · 龙岗区 · 平湖', '15-30K', 'Java, Kafka, Redis', 'java开发工程师', 'https://www.zhipin.com/job_detail/df0e4ad5c8dc2d9203N82dq1ElJZ.html', '');
INSERT INTO `jobs` VALUES (364, '咯拉树', '互联网', '100-499人', '', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责公司项目的后端开发工作，参与需求分析、系统设计、编码实现、测试及维护等环节；</li><li>根据项目需求，参与制定技术方案，负责完成系统模块的设计与开发；</li><li>参与编写项⽬相关技术⽂档，确保项⽬质量；</li><li>协同前端开发工程师完成系统功能调试与优化；</li><li>跟进新技术动态，根据项目需求引⼊新技术，提高系统性能和开发效率；</li><li>遵循公司开发规范，确保代码质量，参与代码审查；</li><li>完成上级领导交办的其他工作。</li></ol><p><strong>任职要求</strong></p><ol><li>计算机相关专业，全日制本科及以上学历；</li><li>良好的沟通、团队协作能力；</li><li>有良好的责任心4、3年以上相关开发经验；</li><li>熟悉javase，熟悉servlet原理6、熟悉springboot、mybatis等框架7、熟悉mysql数据库</li></ol>', '3-5年', '9a659708f789f8aa0nB729m9GVdQ', '深圳 · 福田区 · 梅林', '13-18K', 'Java, 分布式经验, MySQL, 财务业财一体化系统, Spring, 银行财务资金系统, 金融/信贷/资金管理', 'Java开发(深圳岗位- 银行/财务资金系统)', 'https://www.zhipin.com/job_detail/9a659708f789f8aa0nB729m9GVdQ.html', '');
INSERT INTO `jobs` VALUES (365, '深圳市云港科技', '互联网金融', '100-499人', '', '本科', '<p>与第三方公司签署劳动合同-短期合同</p><p><strong>岗位职责</strong></p><ol><li>负责金融交易后台结算系统相关外围接口开发；</li><li>负责金融交易相关报表需求开发；</li><li>内部一般问题分析排查，⽇常缺陷修改。</li></ol><p><strong>任职要求</strong></p><ol><li>计算机或者相关专业本科及以上学历，具有3年或以上Java项⽬开发经验，熟悉⾦融业务优先;</li><li>熟悉微服务架构，掌握Springboot相关技术栈，对Dubbo、SpringCloud分布式框架有较深了解和经验;</li><li>掌握数据库相关知识，熟悉Oracle、MySq|等常规数据库，熟悉Linux系统操作; .</li><li>掌握java多线程技术，熟练RabbitMQ、Redis等常用中间件；</li><li>熟悉Vue/React/Angular等主流框架，有H5/小程序开发经验，有过⼤型系统开发经验者优先；</li><li>思路清晰，有良好的需求理解、分析、抽象能力和系统设计能力;</li><li>责任心强，有良好的沟通协调能力和团队合作意识。</li></ol>', '3-5年', 'd72a07ee80336d180nJ73du-FlVR', '深圳 · 福田区 · 会展中心', '15-20K', 'Java, Spring, SpringCloud, MySQL, Oracle, SQL Server', 'Java开发工程师（第三方短期合同）', 'https://www.zhipin.com/job_detail/d72a07ee80336d180nJ73du-FlVR.html', '员工旅游, 零食下午茶, 法定节假日三薪, 夜班补助, 年终奖, 交通补助, 五险一金, 生日福利, 加班补助, 定期体检, 有无线网, 股票期权, 定期体检, 团建聚餐, 节日福利, 餐补, 带薪年假');
INSERT INTO `jobs` VALUES (366, '意如图真科技有限公司', '人工智能', '20-99人', 'B轮', '本科', '<p>注：我们不做外包，不卖人头。但是因为银行的监管要求，数据不可以带出机房，所以暂时是驻在客户那边做研发。</p><p><strong>核心职责</strong></p><p>- 负责银行项⽬的驻场研发，完成现场业务需求对接和相关服务的研发⼯作（Java为主、少量Python服务）- 负责 Linux 环境下的服务部署与线上问题排查- 参与技术评审，对接业务⽅数据、算法团队，推动 AI 能力在银行业务场景的技术落地与迭代优化</p><p><strong>职位要求</strong></p><p>- 本科及以上学历，计算机、软件⼯程等相关专业，3年左右 Java 后端开发经验- 熟练使用 Java 核心技术，熟练使用 Spring Boot、Spring Cloud 等微服务框架，具备分布式系统开发经验- 熟练使用 MySQL、Redis、ES、Kafka 等常用存储技术- 熟练使用 Python，可独立完成数据处理脚本、服务对接工具、自动化脚本的开发- 熟悉 Linux 操作系统，熟练掌握系统调优、日志分析、故障排查等能力，有线上系统运维经验优先- 有银行、金融行业研发经验者优先，熟悉对公信贷、零售信贷、私人理财等业务系统者优先</p>', '3-5年', '5571b9437bfe59c00nFy0921FVVY', '深圳 · 罗湖区 · 东门', '15-25K', 'Java, 银行, MySQL, Spring', 'java开发工程师（非外包）', 'https://www.zhipin.com/job_detail/5571b9437bfe59c00nFy0921FVVY.html', '员工旅游, 年终奖, 带薪年假, 定期体检, 股票期权, 五险一金, 绩效奖金');
INSERT INTO `jobs` VALUES (367, '北半球网络科技', '电子商务', '100-499人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>Java后端开发：负责基于Java语言的后台业务系统、API接口、微服务的设计、开发、测试、部署、运维与持续优化，保障系统稳定性和性能。</li><li>Web前端开发与维护：负责公司Web应用的前端页面开发（HTML, CSS, JavaScript/Vue）及交互实现，确保良好的用户体验和兼容性。</li><li>RPA流程设计与开发：分析业务部门⾃动化需求，设计、开发、测试、部署基于影⼑RPA平台的机器⼈流程，并负责已部署流程的监控、运行维护与优化升级。</li><li>维护系统稳定性，助力于系统功能优化。</li></ol><p><strong>任职要求</strong></p><ol><li>计算机相关专业本科以上学历，3-5年以上Java开发⼯作经验；具有3年以上的Java开发经验，熟悉Java RESTful API，熟悉Spring Boot/MyBatis等开发框架。</li><li>熟悉数据库系统，如MySQL、Oracle等，熟悉SQL语言；熟悉常用的前端技术，如HTML/JavaScript/CSS/Vue等。</li><li>悉Linux系统，了解Linux的命令和操作；具有Python经验优先，了解AI行业发展，有AI编程经验。</li><li>独立完成所有需求功能，并且具有优化系统前后端性能独特见解和实践。</li><li>熟悉财务、金蝶云星空丶AWS等系统对接开发经验优先。</li><li>对前端性能优化，兼容性方面有独特研究，熟悉数据结构算法，docker，服务器运维等优先。【薪酬</li></ol><p><strong>福利</strong></p><ol><li>【上班时间】9:00-12:30，14:00-18:00（全年双休，月底最后一个周六学习日）；</li><li>【薪酬】业界有竞争力和较完善的薪酬待遇，保障小伙伴的付出与收获成正比；</li><li>【发薪资日】每月5日发放上月薪资；</li><li>【社保公积金】入职即购买六险一金（社保+公积金+人身意外险）;</li><li>【每日零食】每日有办公零食自由享用（咖啡、零食等）；</li><li>【下午茶】每隔一周周四下午茶</li></ol><p><strong>福利</strong></p><ol><li>【团建】每季度部门聚餐团建等活动自由安排；每季度或每年外出旅游等团建，各种丰富的团队活动；</li><li>【全勤奖】每月全勤奖励100元；</li><li>【带薪年假】入职满三个月员工享有5天及以上带薪年假；</li><li>【礼金】入职满一年享有喜事礼金（生育、结婚等）；</li><li>【法定假期】国家法定节假日、春节假期、婚假、病假、产假等；</li><li>【读书资金】每月10000元读书资金（鼓励内部技能输出培训奖励、外部技能提升培训报名等）；</li><li>【励体系】业务团队有合理化建议奖励、项目奖励、新品奖励、奖车激励、年度分红激励等。</li></ol>', '3-5年', '5dc4c83296d8eaac0nF_2Nm0FFFY', '深圳', '13-16K·14薪', 'Java, 不接受居家办公, MySQL, MyBatis, Oracle', '中/高级全栈开发工程师', 'https://www.zhipin.com/job_detail/5dc4c83296d8eaac0nF_2Nm0FFFY.html', '补充医疗保险, 有无线网, 绩效奖金, 餐补, 五险一金, 定期体检, 员工旅游, 零食下午茶, 团建聚餐, 加班补助, 节日福利, 全勤奖, 交通补助, 股票期权, 年终奖, 企业年金, 意外险, 底薪加提成, 带薪年假, 读书资金');
INSERT INTO `jobs` VALUES (368, '深圳美天折网络', '互联网', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>参与公司核心业务系统的需求分析、机构设计和代码开发，保障系统高性能、高可用性；</li><li>前期主要负责Java 后端服务开发，包括但不限于业务逻辑实现、接口设计、数据库优化等；后期⼯作会涉及到⾦蝶系统、供应链系统、收银系统等多平台的信息流通设计。</li><li>编写⾼质量、可维护的代码，参与代码审查和技术文档编写；</li><li>持续优化系统性能，解决线上问题，保障系统稳定性和安全性；</li></ol><p><strong>任职要求</strong></p><ol><li>扎实的Java基础，熟悉JVM、多线程、集合、IO核心机制；</li><li>熟练使⽤SpringBoot、SpringCloud、Mybatis等主流框架；</li><li>熟练使用Mysql、Orcale等关系型数据库，具备数据库建模设计、SQL优化能力；</li><li>熟练使用Redis、MongoDb、RabbitMQ/RocketMQ、Nginx等中间件；</li><li>熟练使用Maven/Gradle、Git等开发工具；</li><li>熟练使用云服务（AWS、Aliyun），熟悉操作Linux系统、完成独立部署流程；加分项：</li><li>有高并发、分布式系统开发经验（如分库分表、熔断降级等）；</li><li>有线上数据清洗经验者优先；</li><li>有开源项目贡献者优先；</li></ol>', '3-5年', 'acca35f86e1a68820nJ52tS-FFJX', '深圳 · 福田区 · 车公庙', '10-15K', 'Java, SpringCloud, Spring, MySQL, Oracle, 架构设计经验, ERP开发经验, 进销存系统, CRM', 'java后端开发（餐饮CRM供应链ERP）', 'https://www.zhipin.com/job_detail/acca35f86e1a68820nJ52tS-FFJX.html', '五险一金');
INSERT INTO `jobs` VALUES (369, '中网讯通', '运营商/增值服务', '100-499人', '未融资', '本科', '<p>boss</p><p><strong>岗位职责</strong></p><ol><li>负责公司核心业务平台全栈开发与架构落地，主导需求评审、技术选型、开发迭代、上线运维全流程，保障高并发业务系统稳定运行。</li><li>基于Java微服务体系完成后端开发、核心业务逻辑封装，负责系统架构优化，保障服务⾼可⽤、⾼扩展、数据一致性。</li><li>独立完成前端复杂页⾯、数据可视化大屏及多端适配开发，搭建通用组件库，提升团队开发效率。</li><li>负责数据库、缓存、消息队列、分布式架构全链路优化，排查并解决线上性能瓶颈与复杂技术问题。</li><li>制定团队代码与技术规范，沉淀技术文档，赋能初级开发，推动团队技术迭代与架构升级。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上计算机相关专业，3年以上Java全栈开发经验，主导/核心参与过2个及以上中大型项目完整开发周期。</li><li>扎实的Java基础，熟练JVM调优、多线程高并发、JDK8+特性及常用设计模式，具备扎实算法与数据结构功底，可独立完成中等难度算法开发优化。</li><li>精通SpringBoot、Spring Cloud Alibaba、Dubbo等微服务框架，熟练ORM框架及Nacos、Sentinel、Seata、Gateway等微服务组件，掌握权限体系搭建。</li><li>熟悉TCP/HTTP网络协议、Netty框架；熟练Kafka/RocketMQ等消息队列，掌握消息幂等、积压、死信等问题优化方案，熟悉ES、MinIO等主流中间件。</li><li>精通MySQL索引优化、SQL调优、分库分表、事务管理；熟练Redis各类场景及缓存常见问题解决方案，了解主流NoSQL数据库使用。</li><li>熟练ES6+、HTML5/CSS3，精通Vue/React任一前端框架及配套生态，掌握前端工程化、组件封装与多端适配、性能优化。</li><li>熟练Git、Maven/Gradle，了解Docker、K8s容器部署及Nginx调优，可独立完成Linux环境下项目部署、问题排查与性能监控。</li><li>精通分布式事务、分布式锁、限流熔断等高并发核心技术，具备分布式系统架构设计与线上问题排查能力。优先加分项1、拥有百万级日活高并发系统开发、微服务架构拆分落地经验；</li><li>熟悉RESTful API规范、JWT/OAuth2.</li><li>GraphQL技术；</li><li>有AI业务落地经验，熟练Spring AI、LangChain4j等Java大模型开发框架；</li><li>有开源项目贡献、技术文章沉淀者优先。</li></ol>', '3-5年', '1b81fa7e073692bd0nFz09y-GFBQ', '深圳 · 南山区 · 科技园', '12-15K', 'Java, JVM, MySQL, 不接受居家办公', 'java全栈开发工程师', 'https://www.zhipin.com/job_detail/1b81fa7e073692bd0nFz09y-GFBQ.html', '员工旅游, 带薪年假, 零食下午茶, 年终奖, 定期体检, 节日福利, 免费班车, 全勤奖, 五险一金, 加班补助, 补充医疗保险');
INSERT INTO `jobs` VALUES (370, '深圳晨昏线科技', '人工智能', '100-499人', '天使轮', '本科', '<p>一，</p><p><strong>岗位职责</strong></p><p>1，负责核心业务系统及后端服务的架构设计、开发与迭代优化，保障系统高性能、高可⽤。2，参与技术⽅案设计与评审，主导关键技术难题攻关，持续提升系统稳定性和可扩展性。3，深⼊理解业务需求，独立完成模块设计与开发，编写高质量、可维护的代码。4，指导中级及初级⼯程师，进行代码审查与技术分享，提升团队整体技术水平。5，关注线上系统运行状态，主导性能调优、故障排查与解决，保障系统稳定运行。二，</p><p><strong>任职要求</strong></p><p>1，基础要求:本科及以上学历，计算机相关专业，3年以上Java后端开发经验。扎实的计算机基础，熟悉数据结构、算法、多线程、网络编程等核心知识。2，技术能力:精通Java，深入理解JVM原理、内存模型、性能调优。熟练掌握Spring Boot、Spring（IOC、AOP、事务等）生态，了解Spring Cloud微服务组件。熟练掌握MyBatis/MyBatis Plus。熟练掌握Redis，了解底层数据结构与应用场景，具备高并发缓存设计经验。熟练掌握RocketMQ、Kafka、MQTT等消息中间件，具备分布式消息系统设计与实践。掌握PostgreSQL、MySQL、Oracle、MongoDB等主流数据库，具备SQL优化与数据库调优能力。了解Elasticsearch原理，具备搜索场景开发或优化经验者优先。深入了解HTTP/HTTPS协议，熟悉网络通信与安全机制。掌握Java线程池原理及使用，理解核心参数配置与调优策略。熟悉分布式系统开发，具备高并发、高可用系统设计经验。熟练掌握Git及常用Linux命令，具备脚本编写与服务器问题排查能力。</p>', '3-5年', '48563d5dab32079d0ndy0tW9EVpW', '深圳', '18-25K·13薪', 'Java, MySQL, AI, Spring, Python', 'Java', 'https://www.zhipin.com/job_detail/48563d5dab32079d0ndy0tW9EVpW.html', '节日福利, 年终奖, 有无线网, 零食下午茶, 定期体检, 五险一金, 绩效奖金, 股票期权, 带薪年假, 保底工资, 生日福利, 加班补助, 节假日加班费, 员工旅游, 团建聚餐, 底薪加提成');
INSERT INTO `jobs` VALUES (371, '华盟财税科技', '计算机软件', '100-499人', 'B轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责公司产品的开发和维护，参与项目的需求分析和设计；</li><li>根据项目需求，完成模块的设计、编码、测试和文档编写；</li><li>参与项目的技术难题攻关，协助团队解决技术问题；</li><li>参与代码审查，确保代码质量和项目进度；</li><li>协助高级工程师进行技术方案的设计和实施。</li></ol><p><strong>任职要求</strong></p><ol><li>计算机相关专业，本科及以上学历，英语4级及以上，5年Java开发经验；</li><li>熟练掌握Java基础知识，理解面向对象编程思想，具备良好的编程习惯；</li><li>熟悉Java常用开发框架，如Spring、SpringMVC、MyBatis等；</li><li>熟悉常用的设计模式，能够在项目中合理运用；</li><li>熟悉关系型数据库（如MySQL、Vastbase）的使用，具备一定的数据库设计能力；</li><li>熟悉Linux操作系统，能够熟练使用基本的Shell命令；</li><li>熟悉常用的版本控制工具，如Git；</li><li>具备良好的问题分析和解决能力，能够独立解决开发过程中遇到的技术问题；</li><li>具备良好的学习能力、沟通能力和团队合作精神；</li><li>具有分布式系统开发、微服务架构实践经验、有税务系统相关工作经验优先。</li></ol>', '3-5年', '588e9b6e96eeee951H163tW8FFdY', '深圳 · 南山区 · 科技园', '14-20K·13薪', 'Java, 分布式经验, 微服务经验, MySQL, MyBatis, Spring, ERP开发经验', 'Java开发工程师', 'https://www.zhipin.com/job_detail/588e9b6e96eeee951H163tW8FFdY.html', '五险一金, 零食下午茶, 定期体检, 节日福利, 补充医疗保险, 年终奖, 员工旅游, 带薪年假');
INSERT INTO `jobs` VALUES (372, '瀚墨文化', '电子商务', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责项目boss迭代，系统优化以及系统重构等具体任务的开发；</li><li>能独立承担重要任务，并对结果负责；</li></ol><p><strong>岗位要求</strong></p><ol><li>全日制本科以上学历，3年及以上使用JAVA开发的经验；</li><li>精通Java基础(常⽤类库，深⼊源代码的优先考虑)，良好的编码规范；</li><li>熟练掌握Spring/Spring Boot/Spring Cloud全家桶；</li><li>熟练掌握MySQL和MongDB数据库的开发和性能优化，熟练掌握Redis等分布式缓存的开发和性能优化；</li><li>有Elasticsearch，RabbitMQ，分布式定时任务等使⽤经验的优先考虑；</li><li>具备良好的逻辑思维，思路清晰，善于思考，能独立分析和解决问题；</li><li>参与过中大型项⽬的优先考虑；</li><li>注重团队协作，具备良好的沟通协调能力和过人的抗压能力；加分项:</li><li>有批发零售、电商、ERP系统经验者优先；</li><li>有系统架构能力，有电商平台性能瓶颈优化经验（如商品检索、订单处理、实时库存同步等核心场景）；</li></ol>', '3-5年', '58c19eb56172cebf03172tm4GVZZ', '深圳 · 罗湖区 · 水贝', '17-25K', '', 'Java开发工程师', 'https://www.zhipin.com/job_detail/58c19eb56172cebf03172tm4GVZZ.html', '餐补, 交通补助, 员工旅游, 带薪年假, 岗位技能培训, 零食下午茶, 全勤奖, 五险一金, 年终奖, 定期体检, 每月聚餐, 节日福利');
INSERT INTO `jobs` VALUES (373, '视壮科技', '互联网', '100-499人', '未融资', '本科', '<p>1.</p><p><strong>岗位职责</strong></p><p>1.核心业务开发：参与产品需求评审与任务拆解，负责核心业务模块的后端开发工作，并承担部分技术管理与任务统筹</p><p><strong>职责</strong></p><ol><li>宠物业务支撑：负责宠物智能产品线（如陪伴机器⼈等）的⽇常需求对接、业务逻辑迭代与后端接口开发，保障相关系统的⾼效交付与稳定运行。</li><li>架构演进与攻关：参与系统服务端技术架构的规划、设计与实现，负责核心技术难题的攻关（如⾼并发处理、数据容灾、微服务治理等）。</li><li>系统维护与调优：负责维护和升级现有平台服务，快速定位并修复线上缺陷，持续推进系统级性能优化与底层中间件的改造。</li><li>算法工程化落地：跨部门协同 AI 算法团队，协助完成相关智能化算法与模型在后端的工程化对接、接口封装及容器化部署保障。</li><li>团队效能提升：培养团队成员，组织技术分享；引入并推行 AI 辅助编程（AI Vibe Coding）最佳实践，提升研发团队的整体编码效能与技术品位。2.</li></ol><p><strong>任职条件</strong></p><ol><li>基础要求：本科及以上学历，计算机相关专业，具备 5 年以上 Java 后端研发经验。</li><li>核心技术：精通 Java 核心编程，具备良好的编码规范。深入理解 Spring Framework，熟练落地 Spring Boot、Spring Cloud 等微服务架构。</li><li>数据库与容灾：深入理解 PostgreSQL、MySQL 等关系型数据库及复杂 SQL 调优；熟悉数据库架构与容灾技术，能独立设计并实施主从复制、读写分离及高可用数据灾备方案。</li><li>缓存与性能：熟练掌握 Redis 缓存技术（熟悉 Redis Cluster 集群最佳），能根据不同业务场景设计合理的缓存策略与数据结构，解决高并发下的性能瓶颈。</li><li>IoT与中间件：熟悉 MQTT 等物联网通信协议，具备物联网场景下设备与服务端消息交互开发经验。有 EMQX、Kafka 等消息引擎及 TDengine 等时序数据库实际落地经验者优先。</li><li>底层调优：具备丰富的线上系统性能诊断与排障经验，熟练掌握 JVM 调优（包括内存管理、垃圾回收策略及多线程并发优化）。</li><li>云原生生态：熟悉 Docker 容器化技术及应用部署，掌握 Docker Compose 工具；熟悉 Kubernetes (K8s) 或 Helm 等容器编排及自动化部署工具，有实际的微服务集群管理经验者优先。</li><li>排障监控：熟悉微服务链路追踪与日志分析工具体系，能够针对系统级故障进行快速定位、闭环处理及问题修复。</li><li>AI 效能创新：拥抱 AI 研发新范式，熟悉 AI Vibe Coding 工作流。熟练使用本地 AI 编码环境及终端工具（如Codex、Claude Code、OpenCode等）实战经验，能利用 AI 显著提升代码编写、重构与测试效能者优先。</li></ol>', '3-5年', '2a467e2e3c277e4c0nJ62tu9ElVW', '深圳 · 宝安区 · 新安', '16-25K·13薪', 'Java, Spring, MySQL, 云计算经验, 架构设计经验, 物联网经验, 不接受居家办公', 'java开发工程师', 'https://www.zhipin.com/job_detail/2a467e2e3c277e4c0nJ62tu9ElVW.html', '节日福利, 每周运动日, 零食下午茶, 餐补, 员工旅游, 带薪年假, 年终奖, 六险一金');
INSERT INTO `jobs` VALUES (374, '道一技术', '计算机软件', '0-20人', '不需要融资', '本科', '<p>1.业务管理平台后台开发2.熟悉springboot开发框架，熟悉mysql数据库3.具有一定的设计能力，文档表达能力强4.具备前端开发技能优先5.懂流媒体技术，熟悉VUE优先</p>', '3-5年', '5d5057556fbc70df0nR52N21GVtS', '深圳 · 南山区 · 科技园', '9-13K', 'Java, Nginx, 物联网经验, 不接受居家办公, MySQL, Redis, Spring, 后端开发', 'Java', 'https://www.zhipin.com/job_detail/5d5057556fbc70df0nR52N21GVtS.html', '');
INSERT INTO `jobs` VALUES (375, '深圳市奕罗思科技', '电子商务', '20-99人', '', '本科', '<ol><li>岗位基本信息级别要求：P6及以上工作地点：远程核心要求：golang 方向 短视频 社交类 app项目，有2年以上的管理经验 Java技术深耕、团队管理、后端架构设计、项⽬统筹。</li><li>岗位核⼼</li></ol><p><strong>职责</strong></p><p>团队管理：负责10⼈左右的Java后端团队管理，涵盖人员招聘、培养及绩效考核，打造高效能研发团队。架构设计：主导后端Java技术架构设计与技术选型，优化系统性能、安全性与可扩展性，攻克核⼼技术难题。项目统筹：统筹后端项目研发全流程，制定研发计划，严格把控项目进度、质量与最终交付，协调各方资源推进项目落地。规范与协同：规范后端研发流程，推行代码评审与技术复盘，提升团队整体研发效率与代码质量；高效对接前端、测试等部门，实现跨部门顺畅协作。3.</p><p><strong>任职要求</strong></p><p>本科及以上学历，计算机相关专业，具备5年以上Java后端研发经验，以及2年以上团队管理经验（带队规模10人以上者优先）。精通Java基础、Spring Boot、Spring Cloud等主流框架；熟悉微服务、分布式、高并发架构设计；熟练掌握MySQL、Redis、ES、Kafka等主流中间件。具备优秀的团队管理与跨部门沟通能力，拥有清晰的技术规划思路与出色的问题解决能力，能胜任高压工作环境。具有互联网行业后端研发管理经验及复杂系统架构设计经验者优先。对系统性能优化有深刻理解，能够迅速识别并有效处理性能瓶颈问题。能够与产品、测试、运维团队通力合作，共同驱动产品整体质量升级\"</p>', '3-5年', 'b21c7146302d3e120nFy09q-GVtW', '深圳 · 宝安区 · 西乡', '15-25K·14薪', 'Java, MySQL, MyBatis, 云计算经验, 接受居家办公, Spring', 'java开发（远程办公）', 'https://www.zhipin.com/job_detail/b21c7146302d3e120nFy09q-GVtW.html', '');
INSERT INTO `jobs` VALUES (376, '苏杭科技', '互联网', '0-20人', '天使轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责公司安排的研发任务，解决项目上遇到的技术难题；</li><li>参与项目现场系统调试工作，配合完成项目上线工作；</li><li>能够接受每年三个月左右的出差（根据项目的数量安排，可能会超过）；</li><li>以系统部署到现场调试、小批量研发为主，主要方向是研发实施；</li></ol><p><strong>岗位要求</strong></p><ol><li>负责JAVA版本的WMS、WCS系统及其他定制项目需求开发；</li><li>对接MES、ERP等上游系统，对接AGV、堆垛机、电子标签、料箱机器人等自动化设备；</li><li>参与现场系统联调，能独立完成服务器相关的环境搭建；</li><li>具有良好的沟通与业务理解能力，能独立解决技术性问题;</li><li>了解打印机、PDA、电子秤、输送线等设备对接优先；</li><li>熟悉生产制造、有仓储物流行业经验优先。</li></ol>', '3-5年', '0db78a4496f4984f1XF42N26EVpR', '深圳 · 龙华区 · 民治', '11-15K', '', '高级java开发工程师', 'https://www.zhipin.com/job_detail/0db78a4496f4984f1XF42N26EVpR.html', '五险一金, 工龄奖, 包住, 绩效奖金, 定期体检, 股票期权, 年终奖');
INSERT INTO `jobs` VALUES (377, '晧辰仪联网', '仪器仪表', '20-99人', '不需要融资', '本科', '<p><strong>一、岗位职责</strong></p><ol><li>参与公司 ERP 4.0 及相关企业服务系统（OA / CRM / CMS）的后端架构设计与核心模块开发；</li><li>负责业务需求分析、技术方案设计、数据库设计，产出规范的技术文档；</li><li>编写⾼质量、可维护、可扩展的 Java 代码，参与 Code Review，保障代码质量与系统稳定性；</li><li>参与系统性能优化、⾼并发场景下的架构改进与问题排查；</li><li>与前端、测试团队紧密协作，推动需求落地与版本迭代交付；</li><li>探索并落地 AI 能⼒ 与企业系统的结合（如智能报表、自动化流程、数据分析等），参与自有产品线的技术创新；</li><li>指导初级开发⼈员，分享技术经验，促进团队整体技术能力提升。</li></ol><p><strong>二、任职要求</strong></p><ol><li>学历专业：计算机科学、软件工程或相关专业本科及以上学历；</li><li>开发经验：3 年以上 Java 后端开发经验，有完整项目从设计到上线的经历；</li><li>语言基础：Java 基础扎实，熟悉面向对象设计、集合框架、并发编程、JVM 原理及调优；</li><li>框架技术：熟练掌握 Spring Boot / Spring Cloud / MyBatis / MyBatis-Plus 等主流框架，理解其核心原理；</li><li>数据库：熟练使用 MySQL，具备 SQL 优化能力；了解 Redis、MongoDB 等 NoSQL 数据库；</li><li>中间件：熟悉 RabbitMQ / Kafka 等消息队列，ElasticSearch 等搜索中间件者优先；</li><li>工程化：熟练使用 Git、Maven / Gradle，了解 Docker、CI/CD 流程；</li><li>系统设计：具备良好的系统设计能力，熟悉微服务架构、分布式系统、RESTful API 设计规范；</li><li>软素质：责任心强，具备良好的沟通协作能力和问题解决能力，有较强的自驱学习意识。三、加分项：●有 ERP / OA / CRM 等企业级系统开发经验；●熟悉 AI / 大模型应用开发（LangChain、RAG、Prompt Engineering 等）；●有高并发、高可用系统架构设计经验；●有开源项目贡献或技术博客输出习惯；●了解前端技术（Vue / React），能进行全栈协作；●有带团队或技术指导经验者优先。</li></ol><p><strong>四、福利待遇</strong></p><p>●有竞争力的薪资：根据能力面议，年终奖金 + 项目奖金；●成长空间：核心项目主导机会，AI 方向技术探索，清晰的晋升通道；●社会保障：五险一金齐全，法定节假日正常休息；●团队氛围：扁平管理，技术导向，拒绝无效内卷；●其他</p><p><strong>福利</strong></p><p>定期团建、下午茶、节日</p><p><strong>福利</strong></p><p>。</p>', '3-5年', 'b161b16255b1aed30nJ72920E1FY', '深圳 · 南山区 · 科技园', '11-18K', 'Java, 不接受居家办公, MySQL, Spring, ERP开发经验', 'Java开发工程师', 'https://www.zhipin.com/job_detail/b161b16255b1aed30nJ72920E1FY.html', '带薪年假, 团建聚餐, 员工旅游, 零食下午茶, 五险一金, 全勤奖, 加班补助');
INSERT INTO `jobs` VALUES (378, '港交所科技', '计算机服务', '100-499人', '不需要融资', '本科', '<p>Job Summary:This role is a critical part of the Enterprise data team involved in the replacement of legacy ETL tool by providing key data engineering activities including pipeline management, analysis & visualisation engineering. The role will be working closely alongside ETL developers and wider technology teams to engineer solutions supporting their strategic roadmap.This is a high-impact role for a candidate who is passionate about engineering excellence, have a strong technical background and excellent IT skills paired with excellent team working and communication skills. This role is a data engineering role (covering backend, data, infrastructure) and collaborates on solution design, implementation, deployment, testing and support.Job Duties:Responsibilities:Design, implement, and maintain robust data pipelines and infrastructure to support LME integration across data warehouses or critical to ensure reliability and scalability.Ensure the robustness and quality of data workloads using Python/Java/Scala and modern data engineering practices, including automated validation, monitoring, and comprehensive testing.Ensure all technical documentation is accurate, up-to-date, and accessible to relevant stakeholders.Provide internal data analysis and reporting to support business and technology objectives.Act as a liaison between technical teams and non-technical stakeholders, ensuring clear and effective communication of project status, risks, and requirements.Develop and maintain database architectures, including data lakes and data warehouses.Ensure data quality and consistency through data cleaning, transformation, and validation processes.Lead incident analysis and root cause investigations for data-related issues, implementing improvements to enhance system stability and performance.Evaluate possible solutions and designs to establish best approach in terms of customer outcome, architecture and cost. Including prototyping, technical spikes and proofs of concept.Design, implement and support scalable and robust data pipelines to support analytics and data processing needs.Implement test or process automation, Test Driven Development, Continuous Integration and Continuous Delivery as required and support the team in implementing best practices.Requirements:Experience: Minimum 3 years in software engineering, with demonstrable involvement in at least one production-grade data system within financial services or a similarly regulated industry.Data Quality: Proven ability to validate and govern data pipelines, ensuring data integrity, correctness, and compliance.Full-Stack Engineering: Hands-on experience with Java (Spring Boot), React (optional), and Python, covering backend, frontend, and data engineering.Data Engineering Tools: Proficient with modern data engineering and analytics platforms (e.g., Apache Airflow, Spark, Kafka, dbt, Snowflake, or similar).DevOps & Cloud: Experience with containerisation (Docker, Kubernetes), CI/CD pipelines, and cloud platforms (e.g., AWS, Azure, GCP) is highly desirable and increasingly standard in the industry.Bonus for knowledge of:Scripting languages, preferably Python.RDBMS systems, PostgresSQL, SQL server or similar.NoSQL or distributed databases (MongoDB etc)Experience with working on streaming pipelines.</p>', '3-5年', '4fdea9e85578bf2c0nF-3tu9EVFU', '深圳', '18-30K', 'Java, Spring, MySQL', 'Systems Engineer - Java - Data Platform', 'https://www.zhipin.com/job_detail/4fdea9e85578bf2c0nF-3tu9EVFU.html', '补充医疗保险, 团建聚餐, 五险一金, 年终奖, 带薪年假, 定期体检, 节日福利');
INSERT INTO `jobs` VALUES (379, '泰比特', '智能硬件/消费电子', '100-499人', '未融资', '本科', '<ol><li>完成功能模块的需求调研、概要设计、详细设计、代码编写、单元测试、系统联调和集成测试；</li><li>核心代码与组件编写，共享重用代码库开发；</li><li>解决开发中所遇到的技术难题4、学习和研究新技术以满足产品的需求，根据开发过程中的体验对产品提出改进建议5、3-5年相关工作经验</li></ol>', '3-5年', 'f9d31e0eaa1e9a0d0nF639u_ElJT', '深圳 · 光明区 · 光明', '9-14K', '不接受居家办公, Java, Spring, SpringCloud, MyBatis, Tomcat, Nginx, Redis, MongoDB, HBase, PostgreSQL, Spark, 团队管理经验, 物联网经验, ERP开发经验', '中/高级java开发工程师', 'https://www.zhipin.com/job_detail/f9d31e0eaa1e9a0d0nF639u_ElJT.html', '年终奖, 加班补助, 定期体检, 餐补, 意外险, 员工旅游, 节假日加班费, 工龄奖, 零食下午茶, 补充医疗保险, 团建聚餐, 夜班补助, 绩效奖金, 保底工资, 节日福利, 全勤奖, 带薪年假, 底薪加提成, 五险一金, 有无线网');
INSERT INTO `jobs` VALUES (380, '摩赞智能', '批发/零售', '20-99人', '不需要融资', '本科', '<p><strong>工作职责</strong></p><ol><li>基于公司web产品平台进行项目定制开发和实施；</li><li>负责解决项目实施过程中技术疑难问题处理；</li><li>服从项目工作安排，参与项目功能开发和实施；</li><li>对项目技术内容负责，包括系统架构设计、功能开发和测试、以及系统交付质量。</li></ol><p><strong>任职资格</strong></p><ol><li>必备电商或社交行业项目经验，熟悉该领域的核心业务模式和技术特点；</li><li>计算应用及相关专业统招本科毕业；</li><li>能熟练使用Java语言体系的主流开发框架（如Spring boot等），3年以上开发经验；</li><li>了解UML规范，有软件设计开发编码经验，善于解决开发过程中遇到的问题，且在团队中担任核心主力开发工作1年以上；</li><li>熟悉SQL语言，能熟练使用MySQL等主流数据库进行开发，能对数据库进行部署和优化，且有数据库优化经验的优先；</li><li>了解不少于10种设计模式，能熟练使用不少于5种设计模式，在实际工作中应用不少于3种的优先；</li><li>了解并熟悉VUE前端开发框架，有1年以上工作经验的优先；</li><li>良好的沟通表达能力、良好设计文档编写能力，有开发设计文档编写经验的优先；</li><li>具有较强的抗压能力及责任心；</li><li>熟练Linux系统部署与维护。</li></ol>', '3-5年', '407ebe654f88626a03R63dW7GVNZ', '深圳 · 南山区 · 科技园', '10-14K', 'JVM, Java, APP, MySQL, Vue, Kafka, 社交, Dubbo, Spring boot, C端', 'JAVA开发工程师', 'https://www.zhipin.com/job_detail/407ebe654f88626a03R63dW7GVNZ.html', '加班补助, 年终奖, 保底工资, 夜班补助, 有无线网, 五险一金, 节假日加班费, 团建聚餐, 股票期权, 底薪加提成, 意外险, 带薪年假, 法定节假日三薪, 零食下午茶, 绩效奖金');
INSERT INTO `jobs` VALUES (381, '诺达通信', '智能硬件', '100-499人', '未融资', '本科', '<p>【通勤便利】紧邻地铁 雪象站 A 出口，实测步行仅 10分钟；注意常规导航会自动规划绕远路线，走我们的专属近道能少走⼀半路，上下班更省⼼省时。https://surl.amap.com/18UadmS86jB公司</p><p><strong>福利待遇</strong></p><p>节假⽇</p><p><strong>福利</strong></p><ol><li>负责公司物联网设备接入、数据采集、指令下发等核心业务的后端架构设计与开发。</li><li>了解 AWS IoT Core 架构（设备认证、Topic 权限、规则引擎、设备影子）,熟练使用 AWS SDK for Java 进行服务调用。</li><li>熟悉AWS 通用服务：Lambda、Kinesis、MSK(Kafka)、DynamoDB、S3、Timestream、API Gateway、IAM/KMS 等。</li><li>熟悉通信协议：MQTT 3.</li><li>1/5.0（核心要求）、CoAP、AMQP、WebSocket。定义并优化MQTT/CoAP通信协议及物模型标准。</li><li>参与系统稳定性建设，包括限流降级、链路追踪、日志监控（CloudWatch）。</li><li>熟练使用 Redis 进行缓存与分布式锁设计。有扎实的SQL调优经验。</li></ol>', '3-5年', '3f81d5b57949466e0nJ62t2_E1RT', '深圳 · 龙岗区 · 坂田', '10-15K', 'JVM, MES开发经验, Java, 物联网经验, 不接受居家办公, SpringCloud, 架构设计经验, Spring, ERP开发经验', 'JAVA 后端开发', 'https://www.zhipin.com/job_detail/3f81d5b57949466e0nJ62t2_E1RT.html', '全勤奖, 五险一金');
INSERT INTO `jobs` VALUES (382, '里德云', '互联网', '20-99人', '不需要融资', '大专', '<ol><li>AI Agent 应⽤与工程化落地对AI技术保持敏锐度，深入理解⼤语言模型（LLM）基本原理；熟悉Agent（智能体）应用范式，掌握Tool Use / Function Calling机制、Prompt Engineering及Context Engineering（上下文工程）；理解主流AI客户端（如Hermes、Codex等）的底层交互原理与执行机制；有实际的LLM API对接、提示词上下文组装及Agent工作流编排经验者优先。</li><li>沟通与理解力具备出色的跨部门沟通与协作能力，能够准确理解产品意图与业务痛点；具备英文文档阅读能力，能高效获取前沿技术资讯。【技术栈要求】1. 编程语言精通 Java 或 Rust 其中一门语言。若为Java方向，需深入理解JVM原理、多线程、集合框架及性能调优；若为Rust方向，需熟悉其所有权机制、生命周期、内存安全模型及异步编程（Tokio生态），了解主流Web框架（如Axum、Actix-web）及高性能并发原理，具备优秀的编码风格与代码质量意识。</li><li>框架与架构熟练掌握主流后端开发框架（如Spring Boot、MyBatis等）；熟悉服务化/微服务架构设计，掌握Spring Cloud、Dubbo、gRPC等RPC框架；具备分布式系统开发经验。</li><li>数据库与中间件熟练使用关系型数据库（MySQL、PostgreSQL）及NoSQL（Redis、MongoDB），具备复杂的SQL优化及缓存设计能力。</li><li>全栈/前端能力（加分项）熟悉React/Vue/Flutter/Android/iOS等其中一项技术栈，理解前端交互与布局，能独立完成部分功能的前后端联调。【基础门槛】</li></ol><p><strong>综合素质</strong></p><p>认真负责、积极主动，具备较强的自我驱动力与学习能力，能够承受一定程度的工作压力。【为什么选择我们】国际化视野：加入一线国际化团队，你的代码将与世界接轨。成长加速通道：资深导师一对一“传帮带”，为你提供实现自我、成就梦想的加速通道。舒适办公环境：轻松舒适的工作氛围，注重员工体验与身心健康。</p>', '3-5年', 'b04cf26235810c840nF73tW7FlVT', '深圳 · 宝安区 · 宝安中心区', '7-12K', 'Java, 物联网经验, 团队管理经验, 不接受居家办公, 分布式经验, PostgreSQL, SpringCloud, ai, SQL Server, Spring, ERP开发经验, MySQL, 架构设计经验, Python, AI Agent', 'AI Agent 应用工程师 (Java/Rust)', 'https://www.zhipin.com/job_detail/b04cf26235810c840nF73tW7FlVT.html', '保底工资, 有无线网, 带薪年假, 底薪加提成, 餐补, 零食下午茶, 五险一金, 住房补贴');
INSERT INTO `jobs` VALUES (383, '安庆英禾网络', '计算机软件', '0-20人', '', '本科', '<p><strong>工作内容</strong></p><p>熟悉后台常用技术框架，熟悉基本的算法和数据结构加分项有良好的沟通表达能力</p>', '3-5年', '42d0b90203237fe71HN-2dW-FFJY', '深圳 · 南山区 · 科技园', '15-20K·13薪', 'Java, Docker, SpringCloud, MySQL, Spring', 'Java', 'https://www.zhipin.com/job_detail/42d0b90203237fe71HN-2dW-FFJY.html', '');
INSERT INTO `jobs` VALUES (384, '瑞维控股', '物业管理', '100-499人', '不需要融资', '本科', '<ol><li>业务价值清晰：不做纯技术Demo，所有开发成果直接服务集团真实业务，落地效果可量化，个人工作价值直观可见；</li><li>完整成长路径：深度参与企业内部AI体系搭建，全程主导智能体、RAG平台从0到1落地，积累企业级AI工程化实战经验，区别于仅做浅层开源项目的基础开发；</li><li>技术视野⼴阔：持续跟进⼤模型、多智能体等前沿技术，⿎励自主技术调研与创新试点，拥有充足空间实践新技术落地；</li><li>团队务实落地导向：团队聚焦解决真实业务痛点，重视实战调优与⼯程能力，能够充分发挥有落地经验人才的技术优势，避免纯理论、浅层次开发工作。</li></ol><p><strong>岗位职责</strong></p><ol><li>负责集团各业务域AI工具、业务智能体、场景化AI技能的设计、开发、配置、部署与持续迭代优化，独立跟进需求调研、方案设计、开发实现、测试上线、运维调优全流程交付，支撑各业务线数字化提效。</li><li>深度拆解业务流程，挖掘真实可落地的AI赋能场景，结合业务痛点输出完整AI解决方案；独立完成业务数据清洗结构化、知识库搭建、模型选型、Prompt体系设计、检索调优、效果评测，持续优化智能体输出准确率，降低模型幻觉，打造适配业务的实用AI能力。</li><li>协同产品、后端研发、业务运营团队，将智能体、RAG、专项AI技能封装为标准化可复用模块与服务接口，搭建企业内部AI资产库；快速响应业务使用反馈，迭代优化功能与使用体验，保障线上应用稳定可用。</li><li>跟踪大模型、Agent、多模态等前沿AI技术，完成新技术、新框架可行性验证与试点落地，结合公司业务探索创新应用模式，沉淀标准化开发规范、落地文档与问题解决方案。</li><li>负责已上线AI应用日常监控、线上故障排查、性能迭代优化，完成技术复盘、资产归档，高效完成上级交办的其他AI相关工作。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机、人工智能、软件工程、大数据等相关专业优先，优秀复合型人才可放宽专业限制。</li><li>具备扎实的AI应用落地实战经验，社招需1年及以上AI应用/智能体开发工作经验；优秀应届生可放宽工作年限，但需拥有完整可演示、具备真实业务场景的个人项目。要求拥有至少1个独立主导0-1搭建完成的业务智能体完整项目，熟悉从需求到上线全链路操作。</li><li>熟练使用Python进行开发，熟练运用numpy、pandas完成业务数据处理；熟练掌握LangChain、LlamaIndex任意一类LLM应用开发框架，了解PyTorch/TensorFlow其中一种主流AI框架。</li><li>精通RAG、Agent落地全流程，掌握文本分段、向量召回、重排、上下文约束、幻觉抑制等实操调优方法；熟练使用Milvus、Chroma等向量数据库，熟悉主流大模型API对接、封装，具备成熟Prompt工程实战经验。</li><li>具备独立排查线上问题的能力，可自主解决知识库召回偏差、智能体工具调用异常、输出不稳定、上下文超限等常见落地问题。</li><li>具备优秀逻辑思维与沟通表达能力，能精准理解业务需求，主动推进项目落地；学习能力强，愿意持续跟进前沿AI技术，团队协作意识良好，交付责任心强。</li></ol>', '3-5年', '0f8c2251ec45ba7d0nF50tS6GVZU', '深圳 · 南山区 · 科技园', '8-12K', 'Golang, Java, 大数据经验, 不接受居家办公, MySQL, Redis, Spring, Python', 'AI应用开发工程师', 'https://www.zhipin.com/job_detail/0f8c2251ec45ba7d0nF50tS6GVZU.html', '团建聚餐, 餐补, 带薪年假, 全勤奖, 年终奖, 定期体检, 五险一金');
INSERT INTO `jobs` VALUES (385, '鹏业软件', '计算机软件', '100-499人', '不需要融资', '本科', '<p>boss</p><p><strong>岗位职责</strong></p><ol><li>熟悉业务，深度参与业务模块的代码设计与编写，确保逻辑准确，满足需求，代码易读、易维护、易扩展。</li><li>负责现有系统的升级和维护工作，确保系统稳定运行。</li><li>高效定位与处理问题，主动优化系统性能，持续提升系统质量、运行效率与用户体验。</li><li>编写并及时更新相关技术文档，确保文档内容准确清晰、易于理解且符合实际需要。</li><li>按时按质完成领导交办的其他工作任务。</li></ol><p><strong>任职要求</strong></p><ol><li>大学统招本科及以上学历，计算机相关专业，扎实的计算机基础，良好的学习能力，喜欢探索新技术。</li><li>具备3年及以上后端服务器开发经验，有国产化项目经验的优先。</li><li>熟练掌握 SpringBoot/SpringCloud/Mybatis/Dubbo等核心开发框架, 深入理解其内部原理和工作机制。要求有多个相关项目落地经验。</li><li>熟悉MQ，Redis，Kafka，Zookeeper，Nginx，Tomcat，weblogci等中间件的部署与应用开发。</li><li>熟悉Jenkins，docker等持续集成和发布工具。</li><li>熟悉Oracle、MySQL、SQLServer、达梦等数据库，熟练掌握SQL语句，熟悉常用SQL性能优化方法。</li><li>熟悉linux系统基本命令。熟悉Svn、Git版本管理工具。</li><li>了解前端页面开发技术，具备一定的前端技术技能，有 Vue 或anjurlar实际开发经验更佳。</li><li>具备代码规范意识，注重代码的整洁、可维护性。</li><li>强烈的责任心与主动性，对所负责工作有owner意识，并能自我驱动成长。</li></ol>', '3-5年', '2ab817d9a503d7a01Xxz2t25EFBS', '深圳 · 福田区 · 园岭', '11-21K', 'JVM, Java, PostgreSQL, SpringCloud, MySQL, MyBatis, Redis, Dubbo, MongoDB, Spring, Oracle', 'Java开发工程师', 'https://www.zhipin.com/job_detail/2ab817d9a503d7a01Xxz2t25EFBS.html', '生日福利, 五险一金, 节日福利, 意外险, 餐补, 带薪年假, 年终奖, 团建聚餐, 定期体检, 补充医疗保险, 高温补贴');
INSERT INTO `jobs` VALUES (386, '高竞文化', '互联网', '100-499人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责社交直播 App 的 C 端后台服务及 B 端运营系统的设计、开发与维护；</li><li>独立完成需求分析、技术方案设计、编码实现及上线支持，保障系统稳定运行；</li><li>参与代码 Review，持续优化代码质量、系统性能与架构可扩展性；</li><li>与产品、客户端、测试等团队协作，推动业务需求⾼质量落地；</li><li>在项⽬推进过程中沉淀技术⽂档、设计文档和业务知识，形成规范化、可复用的研发资产；</li><li>关注 AI 技术在研发场景中的应⽤，能够借助 AI 工具提升需求开发效率与交付质量。</li></ol><p><strong>岗位要求</strong></p><ol><li>本科及以上学历，5-8 年 Java 开发经验；</li><li>扎实的 Java 基础，熟悉 IO、多线程、集合等核心知识，理解常见设计模式并能灵活应用；</li><li>熟悉 Spring Boot、Spring Cloud Alibaba、Dubbo 等主流框架，了解其原理和机制；</li><li>熟悉分布式系统、缓存、消息队列等技术体系，具备高并发、高可用系统开发经验；</li><li>熟悉 JVM、Web、Redis、Kafka、RabbitMQ 等中间件及相关原理；</li><li>熟悉 MySQL、MongoDB，具备 SQL 优化经验，能结合业务场景合理设计数据存储方案；</li><li>有良好的开发规范意识，工作细致严谨，具备较强的文档编写、总结沉淀和知识传递能力；</li><li>能清晰输出技术设计思路、业务流程和功能使用说明，便于团队协作与后续维护；</li><li>具备较强的学习能力、沟通能力和团队合作精神，积极主动，执行力强；</li><li>能够使用 AI 工具辅助需求分析、开发实现和效率提升，对 AI 前沿技术有浓厚兴趣；</li><li>具备产品设计思维者优先，能够从技术视角对产品方案提出建设性建议；</li><li>有社交、直播相关产品开发经验者优先，包括但不限于社交类 App、音视频直播类 App、大型直播间业务及营收活动平台等；</li><li>有 K8s 容器化部署经验者优先。</li></ol>', '3-5年', '9a761eb5c762bdd40nBz3dW_EFVU', '深圳 · 南山区 · 科技园', '15-25K', 'Java, 音视频经验, 不接受居家办公, SpringCloud, MySQL, 语音社交, MongoDB, 游戏, 架构设计经验, AI辅助', '高级JAVA开发工程师（语音社交类）', 'https://www.zhipin.com/job_detail/9a761eb5c762bdd40nBz3dW_EFVU.html', '五险一金, 节日福利, 团建聚餐, 生日福利, 零食下午茶, 定期体检, 法定节假日三薪, 夜班补助, 股票期权, 绩效奖金, 年终奖, 社团活动, 补充医疗保险, 带薪年假, 员工旅游');
INSERT INTO `jobs` VALUES (387, '哩呐呐', '人工智能', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责 AI 社交 App 后端系统的设计、开发与维护；</li><li>参与用户系统、关系链、聊天消息、内容推荐、AI 对话、虚拟角色等核心模块建设；</li><li>负责接口设计、性能优化、稳定性保障和线上问题排查；</li><li>配合产品、算法、前端、客户端团队，推动 AI 社交相关功能落地；</li><li>参与技术方案设计，持续优化系统架构、代码质量和开发效率；</li><li>能够结合 Codex、Claude Code 等 AI 编程⼯具提升研发效率。</li></ol><p><strong>岗位要求</strong></p><ol><li>3年以上 Java 后端开发经验，计算机相关专业优先；</li><li>熟悉 Java 基础、集合、多线程、JVM、常见设计模式；</li><li>熟悉 Spring Boot、Spring Cloud、MyBatis/MyBatis-Plus 等主流 Java 技术栈；</li><li>熟悉 MySQL、Redis、消息队列等常⽤中间件，有实际项⽬经验；</li><li>熟悉 RESTful API 设计，有良好的接口设计和代码规范意识；</li><li>具备一定的系统设计能力，能独⽴负责模块开发和问题排查；</li><li>有较强的学习能力和责任心，能适应创业团队快速迭代节奏；</li><li>会使用 Codex、Claude Code、Cursor 等 AI 辅助开发工具，并能将其融入日常开发流程。加分项：</li><li>有 AI 社交、AI 陪伴、虚拟角色、聊天机器人、社区、IM、语音/视频社交等相关项目经验；</li><li>对 AI 社交产品有理解，关注 AI Agent、LLM、数字人、情绪陪护等方向；</li><li>有大模型 API 接入经验，如 OpenAI、Claude、通义千问、DeepSeek、豆包等；</li><li>有高并发 IM、推荐系统、内容安全、用户增长相关经验；</li><li>有创业公司或从 0 到 1 产品开发经验优先。我们希望你1. 不只是写接口，而是能理解产品和业务；</li><li>对 AI 社交有兴趣，愿意探索新的交互方式；</li><li>能主动使用 AI 工具提高开发效率；</li><li>代码质量好，沟通直接，执行力强。</li><li>全日制统招本科及以上。薪资待遇：薪资面议，根据能力和经验匹配。优秀者可谈期权/项目激励。</li></ol>', '3-5年', '226fc9cc77473c100nB509S4GVRW', '深圳', '15-25K', 'JVM, Java, SpringCloud, MySQL', 'Java后端开发工程师（AI社交方向）', 'https://www.zhipin.com/job_detail/226fc9cc77473c100nB509S4GVRW.html', '带薪年假, 有无线网, 包吃, 节日福利, 免费停车, 全勤奖, 五险一金, 工龄奖');
INSERT INTO `jobs` VALUES (388, '重力星球', '智能硬件/消费电子', '100-499人', 'A轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>全端后台研发落地：负责公司键鼠、耳机、手柄、音响、桌⾯屏幕等全品类外设对应的Web端、Windows客户端、IOS客户端、移动端APP、设备云平台后端接口开发与业务迭代，⽀撑多端设备的数据交互、功能联动与业务落地。</li><li>设备云平台体系搭建与迭代：主导设备管理后台核⼼开发，实现设备固件OTA升级、设备在线监测、用户设备绑定、配置云端同步、设备日志收集、远程运维等核⼼能力，搭建稳定高效的外设设备云服务体系。</li><li>业务后台系统开发：负责品牌官网、用户支持平台、产品商城、售后体系后端开发，完成用户体系、订单体系、权限体系、产品资源、售后工单等业务模块的设计与迭代，保障业务高效运转。</li><li>跨团队协同开发：深度协同前端、上位机开发、嵌入式工程师、UIUX、产品团队，对接多端业务需求与设备通信需求，梳理业务逻辑与接口规范，完成软硬件联调、多端接口适配、功能闭环落地。</li><li>性能优化与风险管控：负责后端服务性能调优、接口稳定性优化、高并发适配、数据安全校验，解决多设备、多端并发请求异常、数据同步错乱、接口响应慢等问题，保障服务7*24小时稳定运行；沉淀后端开发规范、接口文档与技术组件。</li></ol><p><strong>任职要求</strong></p><ol><li>学历专业：本科及以上学历，计算机、软件工程、电子信息、网络工程等相关专业，能力优秀者可放宽学历。</li><li>工作年限：3年及以上后端开发相关工作经验，有智能硬件、电竞外设、多端设备云平台研发经验者优先。</li><li>项目背景：完整参与或主导过APP、客户端、Web平台、设备云平台任意多端后台项目开发与上线落地，有硬件设备配套后端服务量产落地经验优先。</li><li>核心技术栈：熟练掌握Java/Go任一主流后端开发语言，熟悉SpringBoot、微服务架构；熟练掌握MySQL、Redis、消息队列等中间件；熟悉接口开发、数据交互、设备对接逻辑，具备多端统一后台开发实战经验。</li><li>职业素养：具备独立业务模块设计、开发、排查问题能力，理解软硬件协同业务逻辑，代码规范良好，具备量产级项目交付思维与团队协作能力。\"</li></ol>', '3-5年', '6848b9b74805637f0nJ709q5ElBY', '深圳 · 南山区 · 科技园', '15-20K', 'Java, 微服务经验, SpringCloud, MySQL, Redis, Spring', 'JAVA开发工程师', 'https://www.zhipin.com/job_detail/6848b9b74805637f0nJ709q5ElBY.html', '夜班补助, 团建聚餐, 绩效奖金, 零食下午茶, 节日福利, 带薪年假, 员工旅游, 年终奖, 底薪加提成, 有无线网, 加班补助, 五险一金, 股票期权, 保底工资, 交通补助');
INSERT INTO `jobs` VALUES (389, '深圳思格矿业有限公司', '投资/融资', '100-499人', '不需要融资', '本科', '<p>两个岗位（后端/前端）</p><p><strong>岗位职责</strong></p><p>1、独立完成小程序前后端开发（页面+接口+数据库）2、负责预约、订单、支付、⽤户、排班等核⼼业务模块3、项⽬部署、联调、性能优化、迭代维护、后期运维4、无设计稿时能独立完成基础 UI 和交互设计</p><p><strong>任职要求</strong></p><ol><li>熟练掌握⼩程序开发（WXML/WXSS/JS），有实战、上线项目2、Java 后端扎实（Spring Boot、MySQL、Redis）4、能独立推进需求→开发→上线全流程5、自驱力强，适应快节奏加分项· 有多端框架经验（uni-app/Taro/Flutter 等）· 有小程序迁移 App 经验温馨提示，面试会看会问：</li><li>过往作品集/体验码2、你对我司小程序前期落地部署规划（简易）薪资待遇与工作时间1、10-20K+绩效+奖金分红+五险+每天餐补50（优秀者面议）2、周末双休，早上 9:00-晚上 18:</li><li>老板nice，团队文化包容务实，每周固定零食水果日</li></ol>', '3-5年', '2d925fc52c81ef4f0nJ72Ny7F1dS', '深圳 · 南山区 · 科技园', '10-15K', 'Java, 不接受居家办公, Hive, SpringCloud, MySQL, Redis, Spring Boot, 架构设计经验, Spring, MyBatis-Plus, Python', '微信小程序开发工程师（后端/前端）', 'https://www.zhipin.com/job_detail/2d925fc52c81ef4f0nJ72Ny7F1dS.html', '零食下午茶, 绩效奖金, 年终奖, 生日福利, 工龄奖, 节日福利, 员工旅游, 有无线网, 餐补, 全勤奖, 底薪加提成, 股票期权, 团建聚餐');
INSERT INTO `jobs` VALUES (390, '智保惠众', '通信/网络设备', '100-499人', '不需要融资', '本科', '<p>划重点：请勿虚假毕业年限，请勿虚假毕业年限，请勿虚假毕业年限，人需在深圳本地。</p><p><strong>岗位职责</strong></p><ol><li>2024届（含）之前毕业且四年制统招全日制大学本科及以上学历，需要人在深圳本地，或能到线下复试2.外包富德⽣命⼈寿长期稳定项⽬，做过AI项目经验的优先3.能独立完成功能模块开发，并具有复杂需求的独⽴分析和设计能力，参与过2个或以上新建项目优先；</li><li>熟练掌握Java编程语言，并具备扎实的编程基础，熟悉VUE等前端主流技术。</li><li>熟悉并熟练使用Spring、Springboot、SpringCloud、MyBatis等主流开发框架和工具；</li><li>具备良好的数据库设计和开发能力，有至少2个以上基于Oracle数据库相关的应用开发经验，熟练掌握MySQL、Oracle等数据库语言；</li><li>熟悉基本编码规范，能高效完成编码工作；</li></ol>', '3-5年', 'b75ec3dcd8ff6fa80nFz2ty1EFtX', '深圳 · 龙岗区 · 南联', '10-13K', 'ai开发, Java, 分布式经验, 微服务经验, MySQL, Spring', 'Java开发 深圳现场面试（人在本地）', 'https://www.zhipin.com/job_detail/b75ec3dcd8ff6fa80nFz2ty1EFtX.html', '定期体检, 带薪年假, 五险一金, 零食下午茶, 节日福利, 年终奖');
INSERT INTO `jobs` VALUES (391, '深圳品简科技', '智能硬件', '100-499人', '', '本科', '<p><strong>任职要求</strong></p><ol><li>全日制统招本科，计算机相关专业，1年以上Java工作经验；</li><li>Java基础扎实、熟悉多线程、集合等基础知识；</li><li>熟悉Spring Boot 、Vertx(基于异步处理)等开源组件的使用4. 熟悉掌握linux命令和使用、熟悉常用Mysql、PostgreSQL语法或SpringBoot JPA规范5. 有分布式、高并发系统开发设计经验，熟悉Netty、Redis、Kafka、ElasticSearch、ZooKeeper等中间件:</li><li>熟悉各种通讯网络的传输协议如TCP/UDP/HTTPWebSocket/MQTT/COAP等:；</li><li>精通SpringBoot、SpringCloud等主流框架熟悉K8S、Docker、DevOps等容器云及软件工程技术;</li><li>有运维平台、分布式系统分析、设计和开发经验者优先；</li><li>有物联网平台架构设计经验优先;有Netty使用经验优先;有vertx使用经验优先;有大数据开发经验优先。。</li></ol>', '3-5年', 'ed31f0c4b337d6b31Hx93NS8FlNT', '深圳 · 宝安区 · 石岩', '10-15K·13薪', 'Golang, Java, C++, SpringCloud, MySQL, SQL Server, Spring', '后台开发工程师', 'https://www.zhipin.com/job_detail/ed31f0c4b337d6b31Hx93NS8FlNT.html', '五险一金, 年终奖, 绩效奖金, 团建聚餐');
INSERT INTO `jobs` VALUES (392, '小野和子', '电子商务', '100-499人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责公司外采系统的激活、迭代与性能优化，深挖并修复系统底层逻辑短板，盘活现有系统核心能力，持续提升系统运行效能与稳定性，保障业务⾼效落地运⾏。</li><li>主导公司BI平台与各业务端口的对接与适配⼯作，结合实际业务逻辑完成数据打通，确保业务数据精准、完整、实时输出，为业务复盘、公司经营决策提供可靠的数据支撑。</li><li>统筹数据开发与数据治理全流程工作，负责数据底层架构的搭建、优化与迭代，保障数据库平稳4、依托公司底层数据资源与现有系统能⼒，承接AI功能开发与场景落地工作，推进AI产品迭代优化，落地各类业务智能化场景，助力业务降本提效。</li><li>立足业务思维开展技术工作，快速理解核心业务逻辑，联动业务部门排查、解决数据异常、系统适配等各类问题，确保技术方案贴合业务实际需求，主动推进各项工作落地闭环。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，3年以上前端开发经验，具备电商行业项目经验者优先2.具备专业的数据体系搭建能力：熟悉数据仓库建模理论、数据治理方法论，拥有数据质量、数据血缘、BI 看板等数据平台的搭建、开发及优化经验，可独立完成数据底层架构搭建与迭代升级——扎实的底层技术功底：精通 Python、Java 编程语言及对应技术生态，深入理解 JVM 原理、多线程、并发编程、网络 IO 等底层核心机制；熟练掌握 Linux 操作系统及常用命令，可独立完成系统问题排查、性能分析与优化工作。——熟练掌握主流开发框架与分布式技术：熟悉 Flask、Spring Boot、Spring Cloud 等微服务框架，具备大型分布式系统的设计、开发与优化实战经验。——精通数据库与缓存技术：熟练运用 MySQL、SqlServer、PostgreSQL 等关系型数据库及 Redis 缓存技术，具备优秀的 SQL 编写、调优及数据库运维能力。——掌握大数据核心技术栈：熟悉 Hadoop、Spark、Flink、Kafka、Starrocks 等主流大数据组件的运行原理与应用场景，具备成熟的大数据开发落地经验。</li><li>具备AI落地开发基础，掌握智能化开发工具，有 Vibe Coding 开发经验，能够熟练使用 Codex、Cursor 完成软件前后端整体设计与开发工作，高效推进项目落地。</li><li>具备优秀的业务理解能力、沟通协作能力及抗压能力，拥有极强的自驱力和主观能动性，能够结合业务需求主动推进技术迭代、问题优化，适配业务长期发展。</li></ol>', '3-5年', '456bda82660577870nFz2NW8F1dQ', '深圳 · 宝安区 · 西乡', '18-24K·13薪', 'Java, Python, Spring, SpringCloud, MySQL, Hive, Spark, SQL Server, Hadoop, 分布式经验, 大数据经验, 架构设计经验, 不接受居家办公', '软件开发工程师', 'https://www.zhipin.com/job_detail/456bda82660577870nFz2NW8F1dQ.html', '带薪年假, 底薪加提成, 定期体检, 零食下午茶, 企业年金, 节日福利, 年终奖, 高温补贴, 员工旅游, 生日福利, 节假日加班费, 女性关怀, 五险一金, 意外险, 绩效奖金, 保底工资, 弹性工作休息, 团建聚餐, 法定节假日三薪');
INSERT INTO `jobs` VALUES (393, '慧卡科技', '互联网金融', '20-99人', '未融资', '本科', '<p>职位</p><p><strong>职责</strong></p><ol><li>使用SpringBoot开发微服务;</li><li>实现业务需求，优化及完善基础组件和功能;</li><li>沟通推进业务需求验收;</li><li>重点、难点的技术攻坚。</li></ol><p><strong>职位要求</strong></p><ol><li>本科及以上学历，计算机相关专业，有银行系统开发经验者优先;</li><li>精通Java语言，具有良好的编码习惯;</li><li>熟练掌握SpringBoot和SpringCloud等框架，了解 Dubbo;</li><li>熟练掌握Oracle、MySQL等主流数据库的应用与配置;</li><li>熟练掌握IDEA、Eclipse等JavaIDE开发工具;</li><li>熟悉Tomcat、Nginx等配置;</li><li>熟悉Vue.js等前端框架;</li><li>有责任心，有良好的工作态度，具有较强的团队协作精神;</li><li>熟练的专业英语阅读能力，良好的表达能力和沟通技巧，能清晰准确的阐述问题;</li><li>具备良好的自学能力和独立解决问题的能力，能承受一定的工作压力自主研发 周末双休</li></ol>', '3-5年', '3e7eae20b78d70511Xx53dW8EFtY', '深圳 · 南山区 · 科技园', '15-20K', 'Java, SpringCloud, MySQL, Redis, Spring', 'Java开发工程师', 'https://www.zhipin.com/job_detail/3e7eae20b78d70511Xx53dW8EFtY.html', '节日福利, 带薪年假, 补充医疗保险, 五险一金, 年终奖, 加班补助, 员工旅游');
INSERT INTO `jobs` VALUES (394, '立能派', '储能', '20-99人', '不需要融资', '本科', '<ol><li>计算机相关专业本科及以上学历，3年以上Java开发经验，必须具备新能源系统（光伏/储能/充电桩运维管理）项⽬经验，熟悉新能源业务场景。</li><li>精通Java核⼼语法、多线程编程及JVM原理，熟练掌握Spring Boot、Spring MVC、MyBatis等主流框架，具备分布式系统开发经验（微服务架构、RPC调⽤）。</li><li>掌握前端技术栈（HTML5/CSS3/JavaScript），熟练使用Vue/React框架及ECharts数据可视化组件，能独立完成前端页⾯开发与状态管理。</li><li>熟悉MySQL、Redis等数据库及缓存技术，具备数据库设计与优化能力，了解分布式事务、消息队列（Kafka/RocketMQ）等解决方案。</li><li>熟悉Linux环境，能独立搭建部署系统。</li></ol>', '3-5年', 'd16a38f11e2216fc0nB709u5EFpX', '深圳', '8-12K', 'Java, C, Spring, SpringCloud, MyBatis, 不接受居家办公, MySQL, Redis, Oracle, 物联网经验', 'Java开发工程师', 'https://www.zhipin.com/job_detail/d16a38f11e2216fc0nB709u5EFpX.html', '全勤奖, 五险一金, 工龄奖, 带薪年假, 年终奖, 意外险');
INSERT INTO `jobs` VALUES (395, '迈戈科技', '电子商务', '100-499人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>核心系统研发：参与公司核心业务系统开发，保障系统的高可用、⾼并发与可扩展性，独⽴完成复杂模块的编码实现与性能优化；</li><li>AI辅助开发实践：深度使⽤AI编程助手（如Cursor、Claude Code、Codex、GitHub Copilot等）作为主要开发方式，⾼效完成代码生成、重构、单元测试与文档编写；</li><li>代码质量把控：对AI生成的代码进行专业审查与重构，具备底层技术直觉，能够手动纠错并解决，确保最终交付代码的规范性与安全性；</li><li>行业经验：具有SAAS电商行业工作经历优先，特别是对用户、订单、商品模块有开发经验的，另外对SAAS模式和应用场景有深入了解。</li><li>抗压能力：能在多线程任务和紧迫的交付节点下，保持高效沟通与协作，以结果为导向推动项目顺利落地。</li></ol><p><strong>任职要求</strong></p><ol><li>基础技能： 统招全日制本科及以上学历，计算机相关专业，5年以上Java后端开发经验；Java基础扎实，精通Java 21+、Spring Boot、Spring Cloud、MyBatis-Plus等主流框架，深刻理解微服务架构及底层运行机制；</li><li>数据库与中间件：熟练掌握MySQL/ORACLE等关系型数据库，具备优秀的SQL编写与索引调优能力；熟悉Redis、Kafka/RabbitMQ等中间件，有分布式事务与高并发处理经验；</li><li>AI Coding经验：具备AI Native思维，是Cursor、Claude Code等AI Coding工具的重度使用者；能清晰描述个人使用AI工具的实际经验，能通过Prompt/Workflow高效驱动AI完成复杂开发任务；</li><li>工程化素养：了解Docker/Kubernetes容器化部署，具备良好的代码习惯及快速学习能力；</li><li>综合能力：具备优秀的系统设计能力与问题排查能力，逻辑清晰；对AI技术抱有强烈热情，不被单一技术栈限制，能通过AI快速学习并上手新技术。</li></ol><p><strong>任职要求</strong></p>', '3-5年', 'bcf7450f4132cfc20nF_39y8GFBU', '深圳 · 福田区 · 梅林', '16-20K', 'Java, 不接受居家办公, 分布式经验, 微服务经验, SpringCloud, MySQL, 云计算经验, SQL Server, 架构设计经验, Oracle, 区块链经验', 'Java后端开发工程师', 'https://www.zhipin.com/job_detail/bcf7450f4132cfc20nF_39y8GFBU.html', '全勤奖, 团建聚餐, 生日福利, 股票期权, 交通补助, 年终奖, 员工旅游, 节日福利, 五险一金, 带薪年假, 住房补贴, 底薪加提成');
INSERT INTO `jobs` VALUES (396, '德沃', '咨询', '20-99人', '天使轮', '本科', '<p><strong>工作职责</strong></p><ol><li>参与公司计算机视觉信息化系统、业务后台、数据接口与前端页面开发，完成系统搭建、模块开发、联调、测试和上线支持。</li><li>参与java/Spring Boot、Vue/React 或 Python 脚本等项目开发，配合算法、前端、测试⼈员完成接口联调和功能交付。</li><li>配合完成硬件设备数据接⼊与接口联调，包括摄像机、光学设备、边缘计算盒⼦等设备的 SDK、API 或通信接口对接。</li><li>配合完成视觉算法、检测算法、推理服务的系统集成与适配，支持算法在边缘计算盒子上的部署、调⽤、测试和问题排查。</li><li>参与算法商城相关功能建设，包括算法能力展示、算法服务接入、接口调用、配置管理、版本迭代和使用数据记录等。</li><li>负责系统日常维护、线上问题跟进、数据处理、简单运维和版本迭代支持，保障系统稳定运行。</li><li>熟悉 Codex、Claude Code、Trae、Cursor 等 AI 编程工具，或熟悉 Vibe Coding 等 AI 辅助开发方式者优先。其它：</li><li>具备扎实的软件开发基础，代码规范、注释清晰、逻辑严谨，理解模块化、复用性和基本工程质量。</li><li>掌握java基础及 Spring Boot 开发优先，了解 Spring Cloud、异步任务、多线程、接口封装等能力者优先。</li><li>熟悉 MySQL 基本使用、SQL 编写、事务概念和常见性能问题；了解 MongoDB 等非关系型数据库者优先。</li><li>了解 RESTful 接口、WebSocket、前后端联调流程，可配合 Vue/React 页面、实时通信、设备长连接等场景。</li><li>熟悉 Python 基础，能用于数据处理、接口联调、自动化脚本、日志分析等辅助工作。</li><li>具备系统搭建、上线支持、日常运维、故障排查和版本迭代意识，能按要求完成初级开发与维护任务。</li><li>接触过硬件设备接口、SDK、API 或通信协议者优先；了解摄像机、光学设备、工业检测设备、边缘计算盒子者优先。</li><li>了解视觉算法、检测算法、推理服务、模型部署或边缘计算适配流程者优先。</li><li>了解算法商城、算法服务管理、模型版本管理、算法能力展示或接口调用平台者优先。</li><li>使用过 Codex、Claude Code、Trae、Cursor 等 AI 编程工具，或了解 Vibe Coding、提示词、AI 搜索等效率方法者优先。</li><li>了解大模型、智能体、RAG、工作流自动化、AI 视觉、图像识别或风电巡检相关项目者优先。</li><li>沟通协作能力好，能主动反馈进度、说明问题，配合产品、算法、前端、测试和项目人员推进交付；学习能力强、执行稳定、责任心强。</li></ol>', '3-5年', '002546fc3045b7730nJ60967FFVZ', '深圳 · 南山区 · 科技园', '10-14K', 'Java, Spring, SpringCloud, MyBatis, Hibernate, Kafka, MySQL, Redis, Oracle, 大数据经验, 架构设计经验, 不接受居家办公', '后端工程师', 'https://www.zhipin.com/job_detail/002546fc3045b7730nJ60967FFVZ.html', '保底工资, 周末双休, 绩效奖金, 五险一金, 带薪年假');
INSERT INTO `jobs` VALUES (397, '某大型银行公司', '银行', '100-499人', '', '本科', '<p>【</p><p><strong>岗位职责</strong></p><ol><li>负责微服务接口设计与实现，设计并优化数据库模型，编写高效SQL，参与代码审查，保证代码质量符合团队规范，提供测试支持，确保产品质量；</li><li>持续优化系统监控体系，及时响应⽣产告警和业务反馈，处理线上问题，优化系统性能，保障系统稳定运⾏；</li><li>使⽤大模型工具辅助代码编写、架构设计、⽂档生成和问题排查，提升开发效率和代码质量，持续学习新技术，通过技术分享等方式互相促进提升。【</li></ol><p><strong>任职要求</strong></p><p>】本科及以上学历，计算机相关专业，3年Java后端开发经验;熟练掌握ava8，熟悉JVM原理、多线程编程，有扎实的编程基础;熟悉SpringBoot、Dubbo微服务架构，有微服务拆分与治理经验;熟练使用MySQL、MyBatis-Plus，具备数据库设计和SQL优化能力;熟悉Redis缓存技术和RabbitMQ/Kafka消息队列，有异步消息处理经验;熟悉配置中心、Docker容器化部署和Git版本控制；具备使用常用AI编码助手辅助开发的经验，能够利用大模型进行开发工作和技术文档生成；良好的沟通能力和团队协作精神，较强的问题分析和解决能力，具备TDD意识。了解金融贷款业务基本知识流程，有相关经验者优先；</p>', '3-5年', '6899469ecf7ae8310nF92Ny7FldS', '深圳', '15-20K·14薪', '', 'java开发-前台业务--深圳某知名银行', 'https://www.zhipin.com/job_detail/6899469ecf7ae8310nF92Ny7FldS.html', '');
INSERT INTO `jobs` VALUES (398, '亿幸健康科技有限公司', '互联网', '20-99人', 'A轮', '本科', '<p>后端开发工程师</p><p><strong>岗位职责</strong></p><ol><li>负责企业级的系统设计和研发工作2. 负责相关产品的功能模块的设计和开发，包括需求分析，详细设计，开发上线等3. 参与系统架构设计，优化，系统瓶颈问题的专项治理，解决系统稳定性，大数据等问题，提高系统稳定。</li><li>具有⼀定的数据分析和逻辑判断能⼒，思路清理，缜密；具备较强的问题解决能⼒5. 具备出色的沟通能力，有团队合作精神，协作精神</li></ol><p><strong>任职要求</strong></p><ol><li>计算机相关专业，本科及以上学历。</li><li>三年及以上后端开发经验, ⼀年以上独立项目经验，能够独立完成项目及当前项目二次开发能力。 His，医保对接，统筹支付经验优先；</li><li>具备服务器部署与维护经验，熟悉 Linux/Windows 操作系统、Nginx、服务器环境配置、日志排查、服务上线等实际运维能力，熟悉 Docker/CI/CD、云服务部署；</li><li>扎实的 Java/Python/Go 及常用框架 经验，Go语言优先；</li><li>精通使用 MySQL/Redis 设计和调优，熟悉 SQL 优化、索引设计、缓存机制；</li><li>熟练接口开发、Git、接口文档（Swagger/OpenAPI）；</li><li>具备模块或子系统的开发设计能力，掌握常见的设计方法和模式，保证系统的高可用性（性能，安全，容量），稳定性和可扩展性。</li><li>对技术和业务有激情，喜欢钻研，主动性高，具有较强的独立工作能力和解决问题的能力加分项有微服务、消息队列、分布式经验</li></ol>', '3-5年', 'e2abc9395d4a58c30nB_39m8GVpW', '深圳 · 南山区 · 西丽', '15-18K·13薪', '不接受居家办公, Java, Spring, SpringCloud, MyBatis, Hibernate, Nginx, MySQL, Redis, Oracle, MongoDB, HBase, 架构设计经验, 分布式经验, 微服务经验, 云计算经验, 大数据经验, 具备惠民保、商业保险的开发经验', '资深后端工程师', 'https://www.zhipin.com/job_detail/e2abc9395d4a58c30nB_39m8GVpW.html', '五险一金, 年终奖, 带薪年假, 节日福利');
INSERT INTO `jobs` VALUES (399, '深圳计算科学研究...', '互联网', '100-499人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责数据库产品的生态体系建设，聚焦多语言（Python/Java/Go）生态适配、开源组件兼容、驱动开发及应用落地。</li><li>适配多种编程语⾔的驱动、主流框架、⽣态应⽤的适配研发，打造稳定、高效、易用的数据库⽣态环境，保障兼容性、性能与稳定性，降低业务接入成本。</li><li>编写技术文档、适配手册，配合其他团队，完成生态落地、问题修复及技术迭代，保障数据库生态稳定运行。</li><li>跟踪行业技术趋势，引入先进理念，优化数据库生态体系，推动开源组件适配与合作，扩大数据库生态覆盖范围。</li></ol><p><strong>岗位要求</strong></p><ol><li>统招本科及以上学历，三年及以上数据库或开源生态开发经验。</li><li>熟练掌握Python、Java、Go中的两种及以上语言，至少精通其中一种。</li><li>熟练使用Linux操作系统，熟练使用git，遵守研发流程，服从岗位工作安排。</li><li>熟悉数据库原理、SQL语法，了解数据库基础原理和相关知识，熟练掌握数据库的使用。</li><li>具备良好的技术钻研能力、问题排查能力与沟通协作能力，自驱力强，对新技术有好奇心，学习主动性强，有钻研精神，乐于接受技术挑战。加分项:</li><li>有数据库内核开发、数据库生态建设。</li><li>多语言驱动开发、开源组件适配经验。</li></ol>', '3-5年', '33687820c556ebaa0nd50t-8ElJT', '深圳 · 龙华区 · 民治', '15-25K·14薪', 'Java, Golang, Python, MySQL', '数据库生态研发工程师', 'https://www.zhipin.com/job_detail/33687820c556ebaa0nd50t-8ElJT.html', '生日福利, 餐补, 节日福利, 定期体检, 通讯补贴, 锻炼身体, 定期团建, 零食下午茶, 交通补助, 绩效奖金, 住房补贴, 高温补贴, 团建聚餐, 带薪年假, 年终奖, 五险一金');
INSERT INTO `jobs` VALUES (400, '华正商旅', '电子商务', '100-499人', '不需要融资', '大专', '<p><strong>职位描述</strong></p><ol><li>参与产品需求的讨论和评审，能与团队共同进步，攻克难关，承受压力与责任；</li><li>根据产品进行相关系统的设计和需求开发，编写高质量代码；</li><li>负责维护系统服务正常运行，及时排查、追踪、解决线上问题；</li></ol><p><strong>任职要求</strong></p><ol><li>编程思想有清晰的认识，深⼊理解OO、AOP思想。</li><li>熟悉java反射机制、集合、I/O、多线程，了解JVM原理。</li><li>精通⽬前流⾏的开源框架：springMVC、springboot、springCloud、dubbo、zookeeper、mybatis等。</li><li>熟悉常用的前端js框架：jquery、easyui、vue.js、bootstrap。</li><li>有过jmap、jstat、javaVisualVM等性能分析工具使⽤经验。</li><li>有大型分布式、高并发、高负载（大数据量）、高可用性系统设计开发经验优先考虑。</li><li>大专及以上学历，3-5年工作经验，做过国际境外航司压位和一降的优先考虑。岗位</li></ol><p><strong>福利</strong></p><ol><li>按国家法定节假日休假，每年带薪年休假；</li><li>每年 1次团建旅游，及1次全身体检；</li><li>入职即购买五险一金、每季度评优奖励；</li><li>提供具有竟争力薪酬，外加丰厚年终股权金；</li></ol>', '3-5年', 'c669be0e33125c2d0nJ62tm-EFBS', '深圳 · 福田区 · 上步', '15-20K', 'Java, C, C++, Spring, SpringCloud, MySQL, Redis, MES开发经验, 不接受居家办公', '中高级爬虫工程师', 'https://www.zhipin.com/job_detail/c669be0e33125c2d0nJ62tm-EFBS.html', '生日福利, 绩效奖金, 宿舍有空调, 补充医疗保险, 包住, 工龄奖, 法定节假日三薪, 员工旅游, 底薪加提成, 节日福利, 定期体检, 保底工资, 夜班补助, 五险一金');
INSERT INTO `jobs` VALUES (401, '深圳英弗拉斯科技', '大数据', '20-99人', 'A轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责公司体育数据及交易相关业务系统的设计、开发与持续优化，重点建设赛事、盘口、赔率、订单及经营数据的实时计算与聚合查询能力。</li><li>基于 Java、Spring Boot 开发高并发、低延迟的业务服务，为管理后台、OpenAPI、BI 看板及其他业务系统提供稳定的数据查询与计算能力。</li><li>负责多来源体育数据的业务聚合与计算，包括赛事数据聚合、盘口归一化、多源赔率融合、赔率版本管理及实时赔率调整等功能。</li><li>基于 Kafka、Flink 建设实时数据处理链路，完成实时数据清洗、关联、聚合、状态计算及结果输出。</li><li>负责实时赔率调整相关业务能⼒建设，根据订单、风险暴露、赔率变化、商户配置等因素，计算赔率调整结果并⽀持动态策略⽣效。</li><li>负责赛事、盘口、选项等维度的实时风险暴露、责任金、投注量、盈亏及异常指标计算，为风控决策和运营管理提供实时数据支持。</li><li>基于 Apache Doris 设计和建设实时分析模型，⽀撑商户经营分析、赛事分析、赔率分析、风险分析、订单分析及多维下钻查询。</li><li>参与实时计算任务的稳定性和性能治理，包括 Flink State、Watermark、Checkpoint、Savepoint、反压、数据倾斜及任务恢复等问题的处理。</li><li>参与 Kafka Topic、事件模型、Schema 版本及数据口径的设计，保证上下游系统之间的数据一致性、可追溯性和可回放性。</li><li>与业务服务、数据底座、API、产品及测试团队协作，推动业务需求落地，并持续优化系统性能、数据准确性和工程质量。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机、软件工程、数学或相关专业，具备 3 年以上 Java 开发经验。</li><li>Java 基础扎实，熟悉集合、并发编程、JVM、网络通信及常见设计模式。</li><li>熟悉 Spring Boot、Spring Cloud、MyBatis 或其他主流 Java 开发框架，具备独立完成业务系统设计和开发的能力。</li><li>熟悉 Kafka 的核心机制，包括 Topic、Partition、Consumer Group、Offset、消息顺序、重复消费及消息积压处理。</li><li>具备 Flink 实际项目经验，熟悉 Flink SQL 或 DataStream API，并掌握以下能力中的大部分：oWindow、Watermark 和乱序数据处理；oState、Checkpoint 和 Savepoint；oExactly-once 或 At-least-once 语义；o多流关联、维表关联及实时聚合；o反压、数据倾斜和任务性能优化；oFlink 任务部署、监控及故障恢复。</li><li>熟悉 Apache Doris，具备表模型设计、分区分桶、物化视图、实时写入及查询性能优化经验。</li><li>熟练掌握 SQL，能够独立完成复杂聚合、关联查询、窗口函数及查询优化。</li><li>熟悉 MySQL、Redis 等常用存储组件，能够根据业务场景进行合理的数据模型和缓存设计。</li><li>具备良好的业务理解和抽象能力，能够将赔率、风险暴露、订单统计等业务规则转化为可维护的实时计算模型。</li><li>具备较强的问题定位能力，能够通过日志、监控、链路追踪等方式排查实时任务和在线服务问题。加分项1.具有体育数据、体育交易、赔率系统、风控系统、金融交易、支付或广告实时计算相关项目经验。</li><li>熟悉体育业务中的赛事、盘口、选项、赔率、概率、风险暴露、责任金、结算等概念。</li><li>具有多数据源聚合、实时价格计算、动态定价或规则引擎相关开发经验。</li><li>熟悉 ClickHouse、Paimon、Iceberg、Delta Lake、Debezium、Flink CDC 等技术。</li><li>具有高并发、低延迟系统设计和性能优化经验。</li><li>熟悉 Docker、Kubernetes，具备微服务容器化部署及线上运维经验。</li><li>熟悉 Prometheus、Grafana、SkyWalking、OpenTelemetry 等可观测性工具。</li><li>具备英文技术文档阅读能力，能够与海外供应商或客户进行基础技术沟通。核心技术栈Java、Spring Boot、Kafka、Flink、Apache Doris、MySQL、Redis、SQL、Docker、Kubernetes。岗位特点该岗位不是传统离线数仓或报表开发岗位，而是以 Java 业务开发和实时计算 为核心。你将直接参与以下核心能力建设：体育数据实时聚合；多源赔率融合与实时赔率调整；赛事及盘口风险暴露计算；商户经营与风险指标实时查询；BI、CRM 和运营系统的数据服务；Kafka、Flink、Doris 实时数据链路。我们希望候选人既具备扎实的 Java 工程能力，也能够使用 Flink、Doris 等技术解决复杂的实时业务问题。</li></ol>', '3-5年', '18166835b7365ea10nJ729u4GVpR', '深圳 · 南山区 · 科技园', '18-35K', 'Java, Spring, Kafka, MySQL, SQL Server, 大数据经验, 微服务经验, 分布式经验, 架构设计经验', 'java大数据开发工程师', 'https://www.zhipin.com/job_detail/18166835b7365ea10nJ729u4GVpR.html', '工龄奖, 夜班补助, 保底工资, 绩效奖金, 节假日加班费, 年终奖, 加班补助, 全勤奖, 股票期权, 五险一金, 法定节假日三薪');
INSERT INTO `jobs` VALUES (402, '未来脑律', '智能硬件/消费电子', '20-99人', 'B轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责公司核心业务系统的后boss端服务设计、开发、测试、上线及维护工作；基于 Java / Spring Boot / Spring Cloud 技术栈进行分布式微服务系统开发；</li><li>参与系统架构设计、接口设计、数据库设计及技术方案评审；</li><li>负责业务模块的需求分析、功能开发、接口联调和性能优化；</li><li>负责⾼并发场景下系统性能优化、SQL 优化、缓存设计和接口响应优化；</li><li>参与分布式系统相关问题解决，如分布式事务、消息⼀致性、接口幂等、服务容错等；</li><li>配合前端、测试、产品、运维等团队完成项⽬交付；</li><li>编写并维护相关技术文档、接口文档和开发规范；</li><li>持续关注后端技术发展，推动系统架构优化和⼯程效率提升。</li></ol><p><strong>任职要求</strong></p><ol><li>全日制本科可查，及以上学历，计算机、软件工程、信息技术等相关专业优先；</li><li>具备扎实的 Java 基础，熟悉集合、多线程、IO、反射、异常处理、JVM 等核心知识；</li><li>熟悉 Spring Boot、Spring MVC、Spring Cloud 等主流后端开发框架；</li><li>熟悉微服务架构、常用数据库，具备良好的 SQL 编写和优化能力；</li><li>熟悉常用缓存和中间件，如 Redis、RabbitMQ / Kafka / RocketMQ 等；</li><li>熟悉 RESTful API 设计规范，具备良好的接口设计和文档编写能力；</li><li>熟悉 Maven、Git、Docker、Linux 常用命令等开发和部署工具；</li><li>具备良好的代码规范意识、问题分析能力和团队协作能力。</li></ol>', '3-5年', '6bb77992fadee8010nF43tq4FlpW', '深圳 · 宝安区 · 沙井', '18-23K', 'Java, SpringCloud, MySQL, Cloud, Spring Boot, Spring Boo, Spring', 'java后台开发', 'https://www.zhipin.com/job_detail/6bb77992fadee8010nF43tq4FlpW.html', '补充医疗保险, 年终奖, 股票期权, 节日福利, 底薪加提成, 广泛医生联系, 带薪年假, 团建聚餐, 企业年金, 加班补助, 绩效奖金, 定期体检, 五险一金, 宠物友好, 员工旅游, 上班撸狗, 意外险, 保底工资, 生日福利, 零食下午茶');
INSERT INTO `jobs` VALUES (403, '乘乘智数', '大数据', '100-499人', 'A轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责公司 AI 应用与 Agent 系统的设计、开发和落地，包括智能客服、知识库问答、文档生成、数据分析自动化、业务流程⾃动化等场景。</li><li>根据公司各部门业务需求，拆解⼈⼯操作流程，设计 AI 自动化解决方案，实现“⽤户指令输入 → AI 理解任务 → 调用工具/系统 → 输出结果”的完整闭环。</li><li>负责企业内部知识库的搭建与优化，包括文档解析、内容切分、向量化、检索召回、重排序、上下文拼接等 RAG 流程，提高 AI 回答准确性和可用性。</li><li>负责开发和维护 Agent Tool / MCP / Function Calling 等工具调用能力，使 AI Agent 能够对接企业内部系统、数据库、表格、API、企业微信等业务工具。</li><li>部完成各部门 AI需求方案评估、试点开发、测试迭代和正式上线，推动 AI 从工具使用进入实际业务流程。</li><li>负责 AI 应用的测试、监控、异常处理和效果评估，持续优化模型调用成本、响应速度、输出质量和用户体验。</li><li>与技术团队协作，参与私有化部署、权限控制、数据安全、接口对接等工作，保障企业数据安全和系统稳定运行。</li><li>跟踪主流 AI 技术和工具发展，如 ChatGPT、Claude Code、Dify、Coze、LangChain、MCP 等，并结合公司业务探索可落地场景。</li></ol><p><strong>岗位要求</strong></p><ol><li>本科及以上学历，计算机、软件工程、人工智能、数据科学等相关专业优先。</li><li>具备 2 年以上后端开发、AI 应用开发或企业系统开发经验，熟悉 Java / Python / Node.js 至少一种开发语言。</li><li>熟悉主流大模型 API 调用方式，了解 Prompt Engineering、Function Calling、Agent、RAG、Embedding、向量数据库等基本原理和应用方式。</li><li>有 RAG 知识库项目经验，了解文档解析、文本切分、向量检索、重排序、上下文构造等关键环节。</li><li>有 Tool / MCP / API 对接经验，能够将 AI 能力接入企业微信、数据库、表格、业务系统或第三方平台。</li><li>有较强的工程落地能力，能独立完成从需求分析、方案设计、原型开发、测试优化到上线维护的完整流程。</li><li>具备良好的业务理解能力和沟通能力，能将业务人员的模糊需求转化为可执行的技术方案。</li><li>对 AI 应用落地有兴趣，愿意研究新工具、新框架，并能判断哪些适合公司真实业务场景。加分项1. 有 LangChain / LangGraph / LlamaIndex / AutoGen / CrewAI 等 Agent 框架实际项目经验。</li><li>有 MCP Server、Function Calling、插件系统、工具调用平台开发经验。</li><li>有企业微信机器人、智能客服、知识库问答、数据分析 Agent、自动化办公系统等项目经验。</li><li>有 Dify、Coze、FastGPT、WorkBuddy 等低代码 AI 平台使用经验，能够用其快速做原型验证，但同时具备代码级二次开发和工程化落地能力。</li><li>有私有化部署、企业数据安全、权限管理、日志监控、模型网关或大模型中台相关经验。</li><li>有 SaaS、供应链、运营、财务、人事、销售等企业业务系统开发经验。</li><li>有 AI Agent 产品从 0 到 1 落地经验，能提供 Demo、GitHub 项目、技术博客或线上案例优先。</li></ol>', '3-5年', '1c66577f9027fee80nF42t6-EFBS', '深圳 · 南山区 · 科技园', '15-20K', 'Java, Python', 'Agent开发工程师', 'https://www.zhipin.com/job_detail/1c66577f9027fee80nF42t6-EFBS.html', '生日福利, 节日福利, 五险一金, 通讯补贴, 年终奖, 零食下午茶, 全勤奖, 员工旅游, 免费工装, 股票期权, 保底工资, 工龄奖, 带薪年假, 绩效奖金, 底薪加提成');
INSERT INTO `jobs` VALUES (404, '悦颜云尚', '计算机软件', '20-99人', '不需要融资', '本科', '<p>【</p><p><strong>岗位职责</strong></p><ol><li>根据产品需求和业务流程，先梳理接口边界、字段定义、异常情况、状态流转，再借助 Cursor、Copilot 等 AI 工具提升开发效率。</li><li>对接口交付质量负责，减少“字段反复改、状态不清、联调阶段不断返工”的问题。</li><li>与前端、产品保持高频同步，提前确认接口契约、状态码、异常返回和交互逻辑。</li><li>参与沉淀接口模板、提示词模板、异常处理模板和基础测试用例模板。</li><li>配合版本提测、问题修复和线上问题排查。**我们希望你具备这些能力**1. 统招本科学历4 年以上 Java 后端开发经验，熟悉常见业务系统开发。</li><li>熟悉 RESTful API 设计，能清晰定义请求参数、返回结构、错误码和状态流转。</li><li>熟悉常见的业务开发场景，如用户、任务、活动、关系链、奖励流水、消息记录等。</li><li>能使用 AI 工具辅助写接口草稿、补异常分支、生成测试样例或做局部重构，但不会把结果不加判断地直接提交。</li><li>有较强的责任心和沟通能力，能接受快节奏、多版本迭代和深圳线下办公。**加分项**1. 做过任务激励、邀请裂变、积分/奖励、消息中心、资产流水等业务。</li><li>有较好的幂等、异常补偿、状态一致性意识。</li><li>做过移动端接口、H5/WebApp 接口或海外产品相关业务。</li><li>有一定 AI 提效实践，能讲出自己如何把 AI 用在开发全流程中。**不适合的人**1. 只会写 CRUD，不会梳理接口边界和业务状态。</li><li>需求理解不完整就开始开发，把问题全部留到联调阶段。</li><li>对 AI 抱有完全排斥态度，或者完全依赖 AI 不做审查。</li><li>对协作、交付和上线结果缺少责任感。**我们更看重什么**1. 不是会多少技术名词，而是能不能把一个模块稳定交出来。</li><li>不是写得多快，而是能不能减少返工。</li><li>不是“会不会架构八股”，而是能不能在中小团队里把业务做实。</li></ol>', '3-5年', '31353e39b1da9e3d0nZ82tq1F1FT', '深圳 · 南山区 · 科技园', '16-25K', 'Java, 不接受居家办公, 分布式经验, SpringCloud, Kafka, Redis, Dubbo, Spring, Elasticsearch, 微服务经验, MySQL, MongoDB, Oracle', 'Java开发工程师（AI优先）', 'https://www.zhipin.com/job_detail/31353e39b1da9e3d0nZ82tq1F1FT.html', '零食下午茶, 员工旅游, 团建聚餐, 带薪年假, 五险一金, 生日福利, 年终奖, 全勤奖, 绩效奖金, 节日福利');
INSERT INTO `jobs` VALUES (405, '中恒创科', '自动化设备', '20-99人', '', '本科', '<p>智能体软件开boss发工程师（Python 主力，需掌握 Java）</p><p><strong>岗位职责</strong></p><p>负责 AI 智能体、多智能体平台后端研发，使用 Python 开发智能体核心逻辑、任务编排、记忆管理、⼯具调⽤、Agent ⼯作流模块。对接各类大模型，完成 Prompt 工程、RAG 检索、智能决策、⾃动化任务流程开发，优化智能体响应速度与运行稳定性。搭建智能服务接口，落地智能问答、自动化调度、知识库问答等 AI 场景，持续做性能调优与功能迭代。维护迭代公司 Java 中台、存量业务系统，基于 SpringBoot 完成功能开发、bug 修复、跨系统接口联调，保障新旧业务打通兼容。参与需求拆解、技术方案设计、代码评审，线上故障排查，沉淀可复用智能体通用组件与开发工具。协同产品、算法、前端团队完成全流程开发联调，推进 AI 智能体业务场景规模化落地。</p><p><strong>任职要求</strong></p><p>3-6 年后端 / 全栈开发经验，主力开发语言为 Python，熟练异步、多线程编程，精通 FastAPI/Django/Flask 其中一种 Web 框架。熟练使用 Java 开发，掌握 SpringBoot 开发体系，能独立完成 Java 业务模块开发、服务维护。有 Agent 智能体、大模型应用、RAG 知识库落地实战经验，了解智能体上下文管理、工具调用流程优先。熟练 MySQL、Redis，掌握库表设计、SQL 慢查询优化、缓存设计，了解消息队列、微服务、分布式基础架构。熟悉 RESTful 接口规范、Git 版本管理，具备独立方案设计、线上问题定位能力，编码规范，逻辑清晰。具备基础全栈开发能力，可配合完成前后端联调，独立闭环开发任务。加分项有 LangChain、LlamaIndex 等主流智能体框架落地经验；开发过多智能体协作平台、自动化 Agent 工作流系统；熟练向量数据库、Embedding、检索优化、大模型微调相关技术。</p>', '3-5年', '226f58b17c4fdf420nF7096-EVdS', '深圳 · 福田区 · 岗厦', '18-35K·14薪', 'Java, Python, SpringCloud, MySQL, 大数据经验', '智能体软件开发工程师', 'https://www.zhipin.com/job_detail/226f58b17c4fdf420nF7096-EVdS.html', '');
INSERT INTO `jobs` VALUES (406, '肇庆维珍妮创盈科技', '服装/纺织', '20-99人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责公司制造业信息化系统（ERP、PDM、MES、WMS、SCM）的后端开发、功能迭代、bug修复及日常运维工作，根据企业生产、仓储、供应链、产品研发等实际业务需求，完成定制化功能开发，保障系统稳定支撑⼯⼚⽇常业务运转。</li><li>深度对接生产、工艺、仓储、⾤购、质检等内部业务部门，主动沟通收集业务痛点与功能需求，独立完成需求梳理、可行性评估、功能方案设计，输出规范的开发方案与接口文档，落地适配工厂实际生产流程的软件功能。</li><li>基于Java、C#等技术栈进行核心代码开发、功能自测及系统联调，负责数据库设计、语句优化、数据逻辑梳理，解决系统数据错乱、功能卡顿、流程异常、接口报错等日常问题，保障制造业系统高效、稳定运行。</li><li>负责各信息化系统之间的数据对接与集成开发，完成ERP、MES、WMS、设备系统之间的数据互通，同时对接车间PLC、传感器等工业设备，基于Modbus、OPC UA等协议实现设备数据采集、同步与联动，打通工厂数据孤岛。</li><li>配合项目实施落地、用户培训、系统上线等全流程工作，负责上线后的系统运维、问题答疑、故障排查，快速响应各部门使用问题，根据业务迭代需求持续优化系统功能，提升车间数字化办公、生产管控效率。</li><li>负责现有工业信息化系统的性能优化、架构微调与版本迭代，梳理系统老旧逻辑与漏洞，持续优化系统兼容性、稳定性与扩展性；沉淀标准化开发规范，配合团队完成项目迭代升级，助力企业生产数字化体系完善。</li></ol><p><strong>任职要求</strong></p><ol><li>工作经验：具备3-5年专职软件开发工作经验，有完整的软件项目开发、落地、迭代经验，有制造业、工业数字化、工厂系统开发经验者优先。</li><li>学历专业：本科及以上学历，计算机、软件工程、电子信息、自动化、智能制造等相关专业优先，能力优秀者可适当放宽学历要求。</li><li>技术能力：精通主流软件开发语言及框架（Java、C#至少一种），精通PgSQL、SQL Server等数据库开发与优化，精通前端开发，熟练使用VUE 3、Element Plus4. 行业能力：熟悉制造业业务流程，熟悉ERP、PDM、MES、WMS、SCM等常见系统，有嵌入式开发、PLC对接、工业协议（Modbus、OPC UA等）数据开发经验开发经验者优先。</li><li>项目能力：具备独立开发中小型系统的能量，具备良好的代码规范和技术文档撰写能力。6.</li></ol><p><strong>综合素质</strong></p><p>逻辑思维清晰，责任心强，抗压能力良好，能够快速理解制造业业务需求，善于沟通对接，具备团队协作能力，能适配项目阶段性加急工作节奏。</p>', '3-5年', '370b5f57c04b59430nF_3N-9E1BR', '深圳 · 光明区 · 光明', '12-18K', 'Java, C, Golang, Python, Spring, SpringCloud, MyBatis, MySQL, SQL Server, ERP开发经验, MES开发经验', '高级软件开发工程师', 'https://www.zhipin.com/job_detail/370b5f57c04b59430nF_3N-9E1BR.html', '五险一金, 有无线网, 高温补贴, 免费工装, 定期体检, 宿舍有空调, 节假日加班费, 保底工资, 夜班补助, 免费班车, 包住, 工龄奖, 节日福利, 绩效奖金, 包吃, 餐补, 带薪年假, 全勤奖');
INSERT INTO `jobs` VALUES (407, 'LEVE乐无', '互联网', '20-99人', 'A轮', '本科', '<ol><li>理解业务流程，确保对平台业务的整体把握；</li><li>基于模块/功能的需求设计进行开发、自测、维护，确保与需求的一致性；</li><li>根据项目需要，撰写开发过程中的各类规范文档，确保项目有序进行；</li><li>根据业务需求对编码进行单元测试及交叉测试，确保模块/功能正常运作；</li></ol><p><strong>任职资格</strong></p><ol><li>3年以上Java开发经验；</li><li>优秀的分析问题、解决问题和快速学习能力，对解决具有挑战性的问题充满激情；</li><li>对编码有激情，热衷开发简洁、高效、易维护的程序，符合行业标准；</li><li>精通java编程、设计模式和组件技术，对 GC、多线程,同步机制有深入了解 , 熟练掌握 Eclipse 等开发工具；</li><li>精通 J2EE主流框架springmvc+mybatis；熟练掌握基于Springboot的微服务开发框架；对分布式系统Dubbo+zookeeper/SpringCloud有一定了解；</li><li>熟悉和掌握至少一种源代码管理软件（SVN/CVS/GIT）；</li><li>熟练使用 Mysql/Oracle/MongoDB 等关系及非关系型数据库产品；</li><li>至少掌握redis、memcached、ehcache其中一种缓存机制；</li><li>熟悉Solr/elasticsearch 等开源搜索框架及爬虫技术优先；</li><li>善于沟通表达，具备良好的团队协作能力；性格乐观开朗，富于激情和创造力。</li></ol>', '3-5年', '58fbe1b0dc0d6cd41X1809m-EVJV', '深圳 · 南山区 · 科技园', '17-23K', 'Java', 'app后端开发工程师', 'https://www.zhipin.com/job_detail/58fbe1b0dc0d6cd41X1809m-EVJV.html', '');
INSERT INTO `jobs` VALUES (408, '优爱康', '智能硬件', '100-499人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>设计、开发和维护智能穿戴设备相关的 Java 应用程序或服务。</li><li>实现与穿戴设备的稳定通信（如蓝牙/BLE连接、数据传输）。</li><li>参与设备端（如Android/Wear OS应用）或服务端业务逻辑开发。</li><li>优化应用性能与功耗，提升用户体验。</li><li>协助测试和修复 Bug。</li></ol><p><strong>任职要求</strong></p><ol><li>计算机或相关专业本科及以上学历。</li><li>扎实的 Java 编程基础和面向对象设计能力。</li><li>熟悉 Android 开发 (Android SDK) 或 Wear OS 开发经验者优先。</li><li>有蓝牙/BLE 开发经验者优先。</li><li>了解网络通信、多线程编程。</li><li>良好的问题解决能力和团队协作精神。</li><li>（加分项）了解低功耗优化、传感器数据处理经验</li></ol>', '3-5年', '1a17a0e3fdb3a30003Jz096_GVdW', '深圳 · 宝安区 · 福永', '12-15K', 'Java, 音视频经验, 不接受居家办公', 'java开发', 'https://www.zhipin.com/job_detail/1a17a0e3fdb3a30003Jz096_GVdW.html', '加班补助, 生日福利, 意外险, 团建聚餐, 全勤奖, 企业年金, 绩效奖金, 年终奖, 五险一金, 工龄奖, 员工旅游, 带薪年假, 零食下午茶, 节日福利');
INSERT INTO `jobs` VALUES (409, '芯大通', '半导体/芯片', '100-499人', '未融资', '本科', '<ol><li>业务系统开发：参与业务系统的后端开发，包括用户管理、权限系统、数据平台、监控告警等通用业务模块的开发与维护。</li><li>架构演进：参与系统架构演进，推动微服务化和技术升级，搭建平台架构，满足多场景业务需求。</li><li>技术基础设施：参与开发通用技术基础设施，包括网关、注册中心、配置中心、日志中心等基础组件的搭建与维护。</li><li>代码质量：持续优化代码质量，推动技术标准化，沉淀可复用的后端技术组件。</li><li>团队协作：与其他后端工程师协作，确保代码规范统一、接口设计合理、服务间协作顺畅。【</li></ol><p><strong>任职要求</strong></p><ol><li>分布式系统：熟悉分布式系统原理，具备高并发、高可用系统设计能力；熟悉Redis、Kafka、MySQL、Elasticsearch等常用中间件。</li><li>工程能力：具备良好的代码习惯和设计能力，了解微服务架构和Docker/K8s容器化部署；有平台类后端开发经验者优先。补充通用后端方向特有素质：扎实的计算机基础、系统架构思维。</li></ol>', '3-5年', 'ad9bdb32ef560f830nF629S8GFNT', '深圳 · 南山区 · 科技园', '16-30K', 'Java, Golang, Python, Spring', '通用后端工程师', 'https://www.zhipin.com/job_detail/ad9bdb32ef560f830nF629S8GFNT.html', '交通补助, 绩效奖金, 带薪年假, 零食下午茶, 生日福利, 定期体检, 五险一金, 餐补, 团建聚餐, 节日福利, 节假日加班费, 年终奖, 意外险, 股票期权, 法定节假日三薪, 补充医疗保险');
INSERT INTO `jobs` VALUES (410, '江苏启檬科技有限公司', '互联网', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>根据应用需求分析，评估需求研发的可行性，拟定开发计划，保障需求研发的实施。</li><li>负责应用需求开发和交付，包括制定概要设计和详细设计，方案评审、开发编码、代码检查、单元测试、联调测试。</li><li>负责应⽤测试缺陷问题修复，保障版本交付质量。</li><li>负责应⽤⽣产问题排查和解决，问题分析和总结。</li><li>负责应用非功能性优化实施。</li><li>负责应⽤技术架构评估，跟进前沿技术，推动技术方案落地实施。</li></ol><p><strong>任职资格</strong></p><ol><li>4年以上后端工作，参与系统分析，模块设计与开发；</li><li>精通Java、Spring Boot、Spring Cloud相关技术栈，熟悉操作系统，数据库，IO、多线程编程原理、集合等基础框架；</li><li>熟练掌握主流应用服务器架构体系、数据库以及各种中间件技术，如es、redis、SqlServer、Kafka等；</li><li>熟练掌握SQL Server，有数据库设计和优化知识；</li><li>有分布式系统开发和设计经验，熟悉Spring Cloud微服务方案，熟悉docker优先；</li><li>有高可用、高并发、高扩展性系统经验或时序数据库经验者优先；</li><li>积极主动，思路清晰，有极强的软件需求理解，能独立分析和解决问题分析能力，极强的抽象和软件设计能力；</li><li>有项目管理经验的优先,有订单、供应链系统开发经验优先;</li></ol>', '3-5年', '516578c212e527850nF92ty0F1FV', '深圳 · 福田区 · 车公庙', '12-18K', '不接受居家办公, Java, Spring, MySQL, 物联网经验, ERP开发经验, 订单管理（OMS）, 商品管理（PMS）, 库存管理（WMS）', 'java 开发工程师', 'https://www.zhipin.com/job_detail/516578c212e527850nF92ty0F1FV.html', '五险一金, 节日福利, 免费班车, 生日福利, 节假日加班费, 加班补助, 带薪年假');
INSERT INTO `jobs` VALUES (411, '深圳赛托生物', '生物/制药', '20-99人', '已上市', '本科', '<p>【</p><p><strong>工作职责</strong></p><ol><li>负责解决项目实施过程中技术疑难问题处理；</li><li>服从项⽬⼯作安排，参与项⽬功能开发和实施；</li><li>对项目技术内容负责，包括系统架构设计、功能开发和测试、以及系统交付质量。【</li></ol><p><strong>任职资格</strong></p><ol><li>计算应用及相关专业统招本科毕业；</li><li>能熟练使用Java语言体系的主流开发框架（如Spring boot等），3年以上开发经验；</li><li>了解UML规范，有软件设计开发编码经验，善于解决开发过程中遇到的问题，且在团队中担任核心主力开发工作1年以上；</li><li>熟悉SQL语言，能熟练使用MySQL等主流数据库进行开发，能对数据库进行部署和优化，且有数据库优化经验的优先；</li><li>了解不少于10种设计模式，能熟练使用不少于5种设计模式，在实际工作中应用不少于3种的优先；</li><li>了解并熟悉VUE前端开发框架，有1年以上工作经验的优先；</li><li>良好的沟通表达能力、良好设计文档编写能力，有开发设计文档编写经验的优先；</li><li>具有较强的抗压能力及责任心；</li><li>熟练Linux系统部署与维护。</li></ol>', '3-5年', '94ea1f7fa964bcd60nFy29S0GFRR', '深圳 · 南山区 · 科技园', '10-14K', 'Java, Spring, ERP开发经验, 物联网, vue', 'java开发工程师', 'https://www.zhipin.com/job_detail/94ea1f7fa964bcd60nFy29S0GFRR.html', '保底工资, 有无线网, 五险一金, 团建聚餐, 补充医疗保险, 零食下午茶, 生日福利, 法定节假日三薪, 节假日加班费, 带薪年假, 节日福利, 员工旅游, 意外险, 绩效奖金');
INSERT INTO `jobs` VALUES (412, '云启时代', '计算机软件', '100-499人', '不需要融资', '本科', '<p>boss</p><p><strong>一、 工作职责</strong></p><ol><li>AI 高效开发： 熟练运用Claude Code、Codex、Cursor等⼯具，倍速完成后端代码编写、重构与 Bug 修复。</li><li>核⼼后端研发： 负责业务系统的 API 开发、数据库设计、⾼并发与分布式架构优化。</li><li>全流程提效： 利用 AI 辅助生成测试⽤例、技术文档，将精力聚焦于业务逻辑抽象和系统设计。</li><li>技术迭代： 持续探索 AIGC/Code LLMs 前沿工具，提炼 Prompt 最佳实践并赋能团队。</li></ol><p><strong>二、 任职要求</strong></p><ol><li>硬实力： 2-5年经验，计算机基础扎实。精通 Java/Go/Python/Node.js（至少一种），熟练掌握 MySQL、Redis；拥有前端开发能力作为加分项。</li><li>AI 技能： 熟悉Superpowers、OpenSpec、SDD 规格驱动开发者, 必须是 AI 编程工具的重度玩家，优先考虑能驾驭 AI 生成生产环境代码。</li><li>软实力： 极强的自我驱动力与学习速度，拥抱技术变革，年轻、脑子灵、解决问题速度快。</li></ol>', '3-5年', 'feaedad1c59449880nBz0ti1FVNY', '深圳 · 南山区 · 科技园', '12-20K', 'Java, Python, TDD, SDD, openspec', '软件开发工程师（擅长AI）', 'https://www.zhipin.com/job_detail/feaedad1c59449880nBz0ti1FVNY.html', '节日福利, 补充医疗保险, 年终奖, 团建聚餐, 零食下午茶, 股票期权, 带薪年假, 五险一金');
INSERT INTO `jobs` VALUES (413, '永映软件', '计算机软件', '100-499人', '不需要融资', '本科', '<ol><li>根boss据产品需求，完成功能的设计、开发，进行开发测试，保障交付代码质量；</li><li>负责AI Agent/SKILL的设计与开发，基于DeepAgents框架设计并实现多场景AI智能体应用；</li><li>负责CLI工具及MCP（Model Context Protocol）服务的开发、调优与联调，确保工具链稳定高效；</li><li>参与Agent编排与调度框架的搭建，支持多Agent协作场景的实现；</li><li>负责功能后端接口详细设计、代码编写以及相关代码重构工作；</li><li>分析与识别系统优化点，提出优化方案与建议，参与性能优化；</li><li>技术预研和难点攻关，提升系统可用性、稳定性和扩展性。</li><li>精通Java基础，熟悉Java技术体系（包含但不限于JVM、多线程并发）；</li><li>熟练掌握SpringBoot及SpringCloud相关框架；</li><li>掌握缓存、消息、负载均衡等实现机制，熟悉常用设计模式；</li><li>熟悉Agent开发范式，有SKILL定义与开发经验，掌握Tool/Skill的设计模式与开发规范；</li><li>深入理解DeepAgents框架架构，熟悉Agent Loop运转机制（规划→执行→观察→反思循环）；</li><li>熟悉大模型API调用（OpenAI API兼容协议），了解Prompt Engineering和Few-Shot设计；</li><li>有Python/Node.js多语言开发能力者优先，有AI平台或LLM应用开发经验者优先；</li><li>有保险类相关系统开发经验者优先。</li></ol>', '3-5年', '20752bfd883015801nJ93d29E1NQ', '深圳 · 福田区 · 福田中心', '12-16K', 'Java, 投资, SpringCloud, MySQL', 'java开发工程师', 'https://www.zhipin.com/job_detail/20752bfd883015801nJ93d29E1NQ.html', '定期体检, 五险一金, 节日福利, 员工旅游');
INSERT INTO `jobs` VALUES (414, '指尖商务', '互联网', '20-99人', '未融资', '本科', '<p>【</p><p><strong>岗位职责</strong></p><ol><li>与产品、运营及前端团队协作，完成内容管理、用户体系、⽀付订阅、数据统计等核⼼模块的开发；</li><li>结合AI能⼒，开发或集成智能内容生成、自动化标签、⽤户画像、个性化推荐等工具/服务，提升业务效率；</li><li>持续优化后端服务性能，解决高并发场景下的技术难点；</li><li>参与技术选型、代码评审及技术文档沉淀，推动团队工程能力提升。【</li></ol><p><strong>任职要求</strong></p><ol><li>熟练掌握至少一种后端语言（Go/Java/Python 优先），有良好的编码习惯；</li><li>熟悉常用数据库（MySQL/PostgreSQL）及缓存（Redis），了解消息队列（Kafka/RocketMQ）等中间件。</li><li>了解并能使用至少一种AI开发工具或框架（如Hugging Face、LangChain、OpenAI API、FastAPI + 推理服务等）；</li><li>有实际落地经验：如调用大模型生成内容、内容理解与打标、智能推荐、AIGC工具链集成等；</li><li>能独立完成AI服务的封装、部署与调优。</li><li>良好的沟通协作能力，自驱力强，能主动推动问题解决；有GitHub开源项目或技术博客者加分。【优先条件】· 有漫剧、短剧、动漫或泛娱乐内容行业开发经验者优先；· 有内容平台、会员体系、付费订阅等相关系统开发经验者优先；· 熟悉大模型微调（SFT/LoRA）、RAG、向量数据库等优先；· 有云原生（K8s/Docker）及 DevOps 经验者优先；· 对AI绘画/视频生成工具（如SD、ComfyUI、Pika等）有实际应用经验者优先。</li></ol>', '3-5年', '278547b164ddfbe50nB-2dq6FFVW', '深圳 · 福田区 · 车公庙', '10-15K', 'Java, 不接受居家办公, AI相关经验, MySQL, PHP, 云计算经验, 搜索/推荐/广告经验, Spring, Python', '后端开发工程师', 'https://www.zhipin.com/job_detail/278547b164ddfbe50nB-2dq6FFVW.html', '全勤奖, 零食下午茶, 底薪加提成, 绩效奖金, 五险一金, 节日福利, 保底工资, 意外险, 年终奖, 补充医疗保险');
INSERT INTO `jobs` VALUES (415, '深圳市云启矩阵网...', '计算机软件', '20-99人', '', '本科', '<p>职位介绍我们正在寻找一名具备扎实后端开发能力，同时能够熟练运用 AI 编程工具提升研发效率的后端⼯程师。这个岗位不要求你训练⼤模型，也不是单纯依赖 AI ⽣成代码。我们更看重的是：你能否准确理解业务需求，将复杂任务拆解为清晰的技术方案，并合理使用 AI 完成代码⽣成、问题排查、测试补充、文档整理和代码重构，最终对交付结果负责。我们希望你既具备传统工程师的技术判断力，也具备 AI 时代的研发效率。</p><p><strong>岗位职责</strong></p><ol><li>负责公司业务系统、数据平台及内部管理系统的后端设计、开发与维护；</li><li>根据业务需求完成接口设计、数据库设计、权限控制及核心业务逻辑开发；</li><li>参与系统架构优化，持续提升系统的稳定性、安全性和可扩展性；</li><li>负责第三方服务、数据接口及内部系统之间的集成与联调；</li><li>使用 ChatGPT、Claude、Codex、Cursor 等 AI 工具辅助需求分析、技术方案设计、代码开发、测试和问题排查；</li><li>对 AI 生成的代码进行审查、验证和优化，确保代码质量，而非直接复制使用；</li><li>编写必要的技术文档、接口文档、部署说明和故障处理记录；</li><li>配合前端、产品及业务人员推进项目落地，并对开发进度和交付结果负责。</li></ol><p><strong>任职要求</strong></p><ol><li>计算机、软件工程或相关专业，具备后端项目开发经验；</li><li>熟悉至少一种主流后端技术栈，如 Java、Python、Go、Node.js、TypeScript 等；</li><li>熟悉 RESTful API、数据库设计、身份认证、权限管理及常见后端架构；</li><li>熟悉 MySQL、PostgreSQL、Redis 等常用数据库或缓存组件；</li><li>熟悉 Git，具备良好的代码规范、版本管理和协作意识；</li><li>能够独立分析问题，通过日志、数据库、接口调用和代码定位系统故障；</li><li>熟练使用至少一种 AI 编程工具，能够通过清晰的上下文和任务拆解获得可靠结果；</li><li>具备 AI 输出验证意识，能够识别错误代码、逻辑漏洞、性能问题和安全风险；</li><li>具备较强的学习能力、执行能力和责任心，能够独立推进任务并按时交付。我们特别看重的 AI 能力能把模糊需求转化为清晰、可执行的开发任务；能为 AI 提供完整上下文、技术约束和验收标准；能使用 AI 快速阅读和理解陌生代码；能使用 AI 辅助排查报错、补充测试、重构代码和整理文档；能判断 AI 给出的方案是否真实可行，而不是盲目采纳；能在提升开发速度的同时，保证代码质量、系统安全和长期可维护性。我们需要的不是“会复制 AI 代码的人”，而是能够驾驭 AI、验证 AI，并利用 AI 提高工程交付质量的人。加分项1.有完整项目从需求分析、开发、测试到部署上线的经验；</li><li>熟悉 Docker、Linux、Nginx、CI/CD 或云平台部署；</li><li>使用过 Supabase、Vercel、Cloudflare、GitHub Actions 等技术或平台；</li><li>有数据采集、任务调度、消息队列、实时通信或高并发系统经验；</li><li>有 AI Agent、RAG、工作流自动化或大模型 API 接入经验；</li><li>有代码审查、技术方案设计或团队协作经验；</li><li>能够展示自己通过 AI 工具独立完成或显著提效的真实项目。面试时我们会关注你如何把一个业务需求拆解成后端开发任务；你如何使用 AI 完成开发，而不是只让 AI“直接写代码”；AI 生成错误代码时，你如何发现并修正；遇到接口报错、数据异常或部署失败时，你如何定位问题；你过去负责过哪些模块，最终产生了什么实际结果。我们提供真实、持续迭代的业务项目；充分使用 AI 工具提升研发效率的工作环境；重视结果和实际能力，不以传统开发方式限制效率；清晰的</li></ol><p><strong>职责</strong></p><ol><li>熟悉的后端技术栈；</li><li>独立负责过的项目或核心模块；</li><li>使用过的 AI 编程工具；</li><li>一个通过 AI 提升开发效率的真实案例；</li><li>GitHub、个人作品或可展示的项目地址。请不要只写“熟练使用 ChatGPT”。我们更希望看到你如何使用 AI 分析问题、完成开发、验证结果并推动项目真正落地。</li></ol>', '3-5年', 'ba02dcf0007abccb0nJ43Nu7E1NR', '深圳 · 宝安区 · 沙井', '10-15K', 'Java, Golang, Python, 其他, SpringCloud, Nginx, Docker, MySQL, Redis, Oracle, MongoDB, SQL Server, 分布式经验, 云计算经验', '后端开发工程师（AI 增强开发方向）', 'https://www.zhipin.com/job_detail/ba02dcf0007abccb0nJ43Nu7E1NR.html', '');
INSERT INTO `jobs` VALUES (416, '中汇旭博', '电子商务', '20-99人', '', '本科', '<p>项目地:深圳市宝安区西乡街道南昌第二工业区海柔创新科技产业园线上面试统招学信本划重点:哨兵/集群部署经验岗位名称:java后端开发⼯程师⼯作</p><p><strong>职责</strong></p><ol><li>负责仓储机器⼈调度平台开发工作，根据业务规格说明书，能够快速进行代码实现;</li><li>主动按时⾼质量完成需求开发和自测;</li><li>配合PM高质量完成各项开发任务，包括不限于需求评审，系统测试用例编写，代码评审与问题或工单定位修改等。</li><li>熟练运用各种问题排查方法，快速定位系统问题根因并修复;</li><li>输出并分享高质量的交付文档进行知识沉淀。</li></ol><p><strong>任职资格</strong></p><ol><li>全日制本科学历，计算机相关专业，3年及以上Java开发经验，JAVA基础扎实，熟练掌握io、多线程、集合等基础框架，熟悉JVM原理;</li><li>良好的团队合作能力，流畅的口头和书面表达能力，严谨的工作态度，有极客意识，求知欲强，思路活跃3.熟悉常用开源框架的原理和内部机制，如Spring Cloud等，能够熟练并合理使用;</li><li>熟悉数据库，redis、RPC等中间件，有良好的设计模式及实际落地能力;</li><li>自驱力强且有强烈的技术热情和钻研精神，热爱</li></ol>', '3-5年', '1d288f7c6dd817550nJ4092_E1NZ', '深圳 · 宝安区 · 西乡', '11-16K', 'Java, Spring, MySQL, 集群, 哨兵部署', '深圳 Java 统招学信本 紧急 哨兵/集群部署', 'https://www.zhipin.com/job_detail/1d288f7c6dd817550nJ4092_E1NZ.html', '五险一金');
INSERT INTO `jobs` VALUES (417, '软盟技术', '互联网', '100-499人', '未融资', '大专', '<p>注意注意：必须现场面试，不支持线上</p><p><strong>工作职责</strong></p><ol><li>负责地上铁营销领域系统的技术研发工作，能独立完成模块需求分析、设计及代码实现；</li><li>参与系统架构优化，提升系统在复杂业务场景下的稳定性和可维护性，保障系统的高可用性；</li><li>解决线上技术问题，建立监控告警体系，持续优化系统性能和用户体验；</li><li>探索 AI 编程工具在研发流程中的应用，提升开发效率。</li></ol><p><strong>任职要求</strong></p><ol><li>专科及以上学历，4年以上 Java 开发经验，有 B 端业务系统经验优先，具备良好的沟通能力；</li><li>熟练使用 Spring Cloud 技术栈，具备业务系统模块化设计能力，了解微服务架构的基本原理；</li><li>掌握 MySQL 数据库设计与性能优化，熟悉 Redis、RabbitMQ 等中间件的实际应用；</li><li>具备线上问题排查经验，熟练使用 Grafana、SkyWalking、ARMS 等监控工具者优先；</li><li>有 AI 编程工具（Claude Code/Codex/OpenCode/OpenClaw 等）使用经验者优先；</li><li>具备良好的抗压能力和自我驱动力。</li></ol>', '3-5年', 'fdb06bca739559cd03F62dW-FVdS', '深圳 · 南山区 · 科技园', '12-17K', 'Java, Spring, SpringCloud, 不接受居家办公, MySQL, B 端业务系统, TMS/OMS, ERP/WMS, AI 编程工具, 营销', 'Java开发-地上铁', 'https://www.zhipin.com/job_detail/fdb06bca739559cd03F62dW-FVdS.html', '节日福利, 团建聚餐, 带薪年假, 绩效奖金, 五险一金');
INSERT INTO `jobs` VALUES (418, '深圳市楚乐原网络', '互联网', '20-99人', '不需要融资', '本科', '<p>【</p><p><strong>岗位职责</strong></p><ol><li>基于现有 Go 遗留代码库，快速理解业务逻辑，识别可复用模块并完成 Java 重写与重构；</li><li>参与高并发比赛逻辑系统的设计与优化，保障数据⼀致性与系统稳定性；</li><li>负责数据库架构设计、SQL 性能调优及分布式事务⽅案落地；</li><li>参与游戏风控体系建设，包括反作弊、异常⾏为检测及安全策略设计与实现；</li><li>推动技术债务清偿，主导或参与大数据采集、清洗、存储及分析相关系统的搭建与优化；</li><li>参与容器化部署与 Kubernetes 集群运维⽅案的设计与实施。【</li></ol><p><strong>任职要求</strong></p><ol><li>精通 Java 语言及 JVM 原理，深入掌握 Spring 全家桶（Spring Boot / Spring Cloud / Spring MVC 等）；</li><li>扎实的微服务架构设计与落地经验，熟悉服务治理、分布式链路追踪及容错机制；</li><li>精通 Java 并发编程，深入理解锁机制、线程池、并发容器及异步编程框架（CompletableFuture / Reactor 等）；</li><li>熟练使用 MySQL / PostgreSQL 等关系型数据库，具备索引优化、SQL 调优及分库分表实战经验，掌握分布式事务解决方案；</li><li>熟悉 Docker 容器化技术及 Kubernetes 编排调度，具备生产环境运维经验；</li><li>能够阅读并理解 Go 语言代码，有 Go 项目实际开发或维护经验者优先（非必须，但需具备快速上手能力）。三、业务与软素质：</li><li>具备极强的业务理解能力，能快速吸收游戏玩法逻辑及比赛规则；</li><li>具备模块抽象与复用意识，能将复杂业务逻辑转化为高内聚、低耦合的代码实现；</li><li>沟通清晰，ownership 强，能主动识别并推动技术问题解决；</li><li>心态开放，愿意承担历史代码重构任务，适应跨语言（Java/Go）协作环境。【加分项】1、有完整上线游戏项目后端重构经验，成功完成技术栈迁移或架构升级；</li><li>具备游戏风控实战经验，如反作弊系统、异常行为检测模型或安全策略引擎设计；</li><li>有 0-1 大数据系统搭建经验，覆盖数据采集、ETL 清洗、分布式存储及实时/离线分析链路。【我们提供】1、深度参与核心竞技产品后端架构演进的技术挑战；</li><li>与顶尖技术团队协作，专注代码交付与系统设计的技术成长路径；</li><li>接触高并发、低延迟竞技场景及跨语言技术栈的实战机会。</li></ol>', '3-5年', '3cd544fc26eaa2600nF73dy1ElZT', '深圳 · 南山区 · 蛇口', '16-30K·13薪', 'Golang, Java, 不接受居家办公, 分布式经验, PostgreSQL, SpringCloud, Spring, actor架构, 大数据经验, Docker, 微服务经验, MySQL, 架构设计经验, 游戏后端经验', '游戏服务端开发工程师（86981）', 'https://www.zhipin.com/job_detail/3cd544fc26eaa2600nF73dy1ElZT.html', '带薪年假, 节日福利, 零食下午茶, 年终奖, 团建聚餐, 五险一金, 定期体检, 餐补');
INSERT INTO `jobs` VALUES (419, '硅语时代', '游戏', '20-99人', '不需要融资', '本科', '<p>Java开发岗位职boss责：负责后台系统核心功能的设计、模块开发、接口编写与优化；使用 SpringBoot + Shiro 实现权限控制、用户角色管理、数据隔离；编写标准化的 RESTful API 接口，支撑前端（jQuery/Bootstrap 及 Vue3/Ant Design）开发；参与现有系统的前后端分离改造升级，助力架构从单体向微服务演进；主导服务部署上线过程，熟练操作 CentOS，维护运行环境；管理并优化 Nginx、Redis、MySQL、MongoDB 等中间件配置与性能；精通 WebSocket / Netty，实现消息推送、实时通信等高并发场景；使用 Jenkins 完成自动化构建与部署，配合 Docker/K8s 实现持续交付与容器化部署；参与微服务架构（Spring Cloud）设计、服务注册发现、配置管理、链路追踪等；</p>', '3-5年', '939b2a231a6ef02703F92tW4FltQ', '深圳 · 南山区 · 科技园', '18-30K·13薪', 'Java, SpringCloud, MySQL, 游戏后端经验', '高级java开发', 'https://www.zhipin.com/job_detail/939b2a231a6ef02703F92tW4FltQ.html', '绩效奖金, 年终奖, 五险一金');
INSERT INTO `jobs` VALUES (420, '亿佳壹', '互联网', '20-99人', '', '大专', '<ol><li>3年以上boss开发经验；</li><li>熟悉JAVA、J2EE、SpringMVC、MyBatis3、熟悉springcloud、springboot4、可快速报道状态</li></ol>', '3-5年', '33a24c17589d8fcd0nd929y_FVFV', '深圳 · 福田区 · 上步', '9-13K', 'Java, SpringCloud, MySQL, 运输', 'java', 'https://www.zhipin.com/job_detail/33a24c17589d8fcd0nd929y_FVFV.html', '');
INSERT INTO `jobs` VALUES (421, '追一科技', '互联网', '100-499人', 'D轮及以上', '本科', '<p><strong>职责</strong></p><ol><li>与产品、客户、系统关联团队等沟通技术方案，输出相关设计文档；</li><li>对技术方案的合理性和可行性负责，带头解决项目中的技术难题，确保方案落地；</li><li>承担软件编码、文档编写、代码质量审查等工作；</li><li>不断优化系统设计和性能，保障系统可用性和稳定性；</li><li>以身作则，在团队内促成良好的技术氛围；要求：</li><li>统招本科及以上学历，计算机软件或相关专业；</li><li>5年及以上java开发经验，扎实的 java 编程基础，熟悉 SSH、spring mvc、springboot 开源框架及 MVC 模型；</li><li>熟悉分布式消息队列（Kafka、RabbitMQ等），分布式缓存（Redis、Memcached），zookeeper等；</li><li>熟悉 WebService、http，grpc等协议；</li><li>掌握Mysql的开发、配置、管理、调试等原理，熟练掌握SQL查询优化；</li><li>具有良好的沟通和协调能力，具备良好的团队精神和责任意识；</li><li>有敏捷开发经验、具备价值交付理念者优先；</li><li>能使用Python或Golang进行数据分析、脚本编写或其他辅助开发工作者优先；</li><li>有银行等金融项目或大型项目开发经验者优先；</li></ol>', '5-10年', 'f0b4a76a54b68b4f03V62tu8EFdQ', '深圳 · 南山区 · 科技园', '14-20K', 'Java, Elasticsearch, Redis, 不接受居家办公, 架构设计经验', '中高级Java开发工程师', 'https://www.zhipin.com/job_detail/f0b4a76a54b68b4f03V62tu8EFdQ.html', '年终奖, 节日福利, 带薪年假, 股票期权, 零食下午茶, 五险一金, 俱乐部文化, 带薪年假');
INSERT INTO `jobs` VALUES (422, '知律科技', '企业服务', '20-99人', '天使轮', '本科', '<p>Java高级工程师</p><p><strong>写在前面</strong></p><p>程序员如何高效的打招呼？JD我们在认真写，打招呼最好贴合JD提你的优势，⽤通⽤的招呼，没提任何技术点，不会在众多的未读消息中引起注意(虽然每个消息都会看)。⼀、</p><p><strong>岗位职责</strong></p><ol><li>负责公司SaaS平台（基于SaaS的行业级一体化管理软件，融合了OA、CRM、HRM、项⽬管理、财务、团队协作、电商等功能）的开发与优化；</li><li>根据产品及项目的开发进度和任务，按时按量保质完成项目编码，并根据需要及时修改、完善模块功能；</li><li>基于高并发、高可用对软件平台进行架构升级优化。（注：自研产品，非外包。不要问，问就是你没仔细看JD。）</li></ol><p><strong>二、职位要求</strong></p><ol><li>全日制本科及以上学历，计算机或其它相关专业；</li><li>扎实的JAVA编程基础， 熟悉各种开源的框架如SSM、Spring Cloud、Spring Boot等；</li><li>熟练使用MySQL数据库， 掌握基本的SQL优化技巧。</li><li>有系统高并发、高可用的架构设计及实战经验，熟悉分步式、微服务架构；</li><li>参与过大中型工作流平台或引擎或者CRM、OA等企业管理系统相关项目者优先；</li><li>有多租户自动化分库、分表经验者优先，有APIJson/Graphql实操经验者优先。</li><li>熟悉Claude Code/Cursor/Antigravity/CodeX者优先。</li><li>有企业知识库RAG，Langchain, Langgraph智能体产品落地经验者加分。</li><li>有Milvus, Postgresql + PGVector等向量数据处理经验者优先。</li><li>有Neo4J、Postgresql + AGE等其他图数据库量级数据处理经验者优先。</li><li>有低代码平台开发经验者优先。</li><li>强烈的责任心和使命感，能吃苦，善于沟通，学习能力和逻辑思维能力强，能承受较大的压力和挑战。</li></ol>', '5-10年', 'c37f2887b4c1cee00nV43dm-FFtS', '深圳 · 南山区 · 科技园', '12-22K', 'Nginx, Java, 分布式经验, PostgreSQL, Kafka, 搜索/推荐/广告经验, Redis, Spring, 大数据经验, 微服务经验, Elasticsearch, Docker, MySQL, MongoDB, 架构设计经验, Python', 'java高级研发工程师', 'https://www.zhipin.com/job_detail/c37f2887b4c1cee00nV43dm-FFtS.html', '五险一金, 节日福利, 带薪年假, 股票期权, 员工旅游');
INSERT INTO `jobs` VALUES (423, '深圳市中创智宇科技', '互联网', '20-99人', '', '本科', '<p>5年以上开发经验，精通java语言，熟悉 Redis、Kafka、Docker/K8s 等常用中间件（需熟悉前端，会简单操作）做过中大型企业内部系统。</p>', '5-10年', '705d449ab4a2521a0nB83d-1EFZX', '深圳 · 福田区 · 上步', '12-14K', 'Java, SpringCloud, MySQL, Spring', 'Java', 'https://www.zhipin.com/job_detail/705d449ab4a2521a0nB83d-1EFZX.html', '');
INSERT INTO `jobs` VALUES (424, '朗钧企业管理', '人力资源服务', '20-99人', '', '本科', '<p>短期4-6个⽉</p><p><strong>岗位职责</strong></p><ol><li>负责Java相关系统的开发、维护及优化⼯作；</li><li>参与银⾏类项目的需求分析、系统设计、编码实现及问题排查；</li><li>按照项目计划完成模块开发任务，确保代码质量与交付进度；</li><li>配合团队完成系统集成、测试及上线⽀持工作。</li></ol><p><strong>任职要求</strong></p><ol><li>统招本科及以上学历；</li><li>5年以上Java开发经验，具备扎实的编程基础和良好的代码规范；</li><li>具备银行类项目开发经验者优先。</li></ol>', '5-10年', '1fa7fba946a9c6330nJ52tu6EFdV', '深圳 · 罗湖区 · 东门', '15-17K', '不接受居家办公, 银行', 'Java工程师-短期-HZ', 'https://www.zhipin.com/job_detail/1fa7fba946a9c6330nJ52tu6EFdV.html', '');
INSERT INTO `jobs` VALUES (425, '博安云科技', '计算机软件', '100-499人', '未融资', '本科', '<p>近5年内至少有3个或以上信贷系统实施经验，包括对公信贷、综合信贷、普惠小微信贷等。</p><p><strong>岗位职责</strong></p><ol><li>负责公司产品的前端和后端开发工作，包括需求分析、设计、编码、测试和维护等。</li><li>参与项目的架构设计和技术选型，确保系统的⾼性能、⾼可⽤性和可扩展性。</li><li>与产品经理、设计师、测试人员等密切合作，确保项目按时交付并满⾜业务需求。</li><li>解决开发过程中遇到的技术问题，持续优化系统性能和技术文档编写及分享。</li></ol><p><strong>任职要求</strong></p><ol><li>Java基础:要求熟悉Java语言，JavaWeb、熟悉IO、多线程、网络通信等基础框架，了解JVM原理;</li><li>前端交互:了解前后端分离的开发模式，能够使用HTTP协议进行前后端数据交互(如使用Axios、Fetch等);</li><li>开发框架:熟练掌握SpringBoot、SpringCloud等开源微服务框架，并深入理解其原理和机制;</li><li>其他技术:熟悉Docker/K8S等容器化系统，分布式、缓存、消息队列等技术，如Kafka、Memcached、Redis等5、数据库:熟练应用性能优化，能够进行数据库性能优化(如索引优化、查询优化、分库分表等)和数据建模使用</li></ol>', '5-10年', 'dfada475103bac800nJ52tS8F1BZ', '深圳 · 罗湖区 · 东门', '13-18K', 'Java, SpringCloud, Redis, 分布式经验, 不接受居家办公', 'Java开发（信贷）', 'https://www.zhipin.com/job_detail/dfada475103bac800nJ52tS8F1BZ.html', '加班补助, 生日福利, 零食下午茶, 餐补, 五险一金, 节日福利, 全勤奖');
INSERT INTO `jobs` VALUES (426, '深圳怡珑科技', '计算机软件', '0-20人', '未融资', '大专', '<p><strong>岗位职责</strong></p><ol><li>全面负责项目全生命周期管理，制定项目计划、把控进度/质量/成本，识别并规避项⽬风险，确保按时按质交付;</li><li>负责开发完成核⼼模块开发、系统定制化改造，统筹数据⾤集/存储/分析、API设计、数据库优化等技术工作;</li><li>协调前端、测试、产品等跨团队资源，对接内外部客户，同步项目进展、处理需求变更，保障项⽬高效推进:</li><li>负责项目上线部署、联调优化及验收复盘，沉淀项目经验，推动团队开发规范和技术能力提升。</li></ol><p><strong>任职要求</strong></p><ol><li>统招全日制专科或以上学历，能独立带队完成项目全流程交付；有AI项目经验优先；</li><li>精通 Java 核心技术，熟练掌握Spring Cloud/ Spring Boot/MyBatis 等主流框架，熟练运用 MySQL/Redis，能解决高并发、海量设备数据处理技术问题;</li><li>熟悉项目管理方法论，具备清晰的项目规划、资源协调和问题解决能力，沟通表达高效，能推动跨部门协同;</li><li>熟悉物联网、大数据相关技术(如 MQTT 协议、流式计算等)，有能源/化工行业数字化项目经验者优先;</li></ol>', '5-10年', '634469e6a65da3440nJ73Nm7EVFU', '深圳 · 南山区 · 科技园', '13-18K', 'JAVA, Java, 项目经理, 团队管理经验, 分布式经验, SpringCloud, MySQL, AI, MongoDB, Spring', 'Java项目经理', 'https://www.zhipin.com/job_detail/634469e6a65da3440nJ73Nm7EVFU.html', '节日福利, 五险一金');
INSERT INTO `jobs` VALUES (427, '绿之源能源', '电力/热力/燃气/水利', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><p>负责 Java / Spring Boot 后端服务的设计、开发与维护；负责系统接口、业务模块及数据库相关功能开发；参与 PostgreSQL、MySQL、ClickHouse、Redis 的使⽤与优化；负责 Linux、Docker、Nginx 环境下的项⽬部署与问题排查；参与系统性能优化和技术⽂档编写。</p><p><strong>任职要求</strong></p><p>计算机相关专业本科及以上学历（3年以上开发经验）熟悉 Java，掌握 Spring Boot、常用设计模式；具备良好的数据结构与算法基础；熟悉 PostgreSQL、MySQL，了解 ClickHouse、Redis；了解 Linux 常用命令、Docker 和 Nginx；具备良好的代码规范、问题分析和团队协作能⼒。</p>', '5-10年', 'eb5635cda45a55970nF93Ny9FVdV', '深圳 · 罗湖区 · 东门', '12-18K·13薪', 'Golang, Nginx, Java, Docker, PostgreSQL, MySQL, Kafka, Redis, Spring Boot, Spring, Python', '中高级java开发工程师', 'https://www.zhipin.com/job_detail/eb5635cda45a55970nF93Ny9FVdV.html', '带薪年假, 年终奖, 零食下午茶, 员工旅游, 五险一金, 节假日加班费, 加班补助, 定期体检, 团建聚餐, 节日福利');
INSERT INTO `jobs` VALUES (428, '浮点云', '互联网', '20-99人', '不需要融资', '本科', '<p><strong>工作职责</strong></p><ol><li>负责核心业务系统的架构设计、开发及迭代优化，保障系统高性能与高可用性；</li><li>主导或参与分布式系统架构的演进，推动系统性能调优；</li><li>负责系统容量规划、高可用架构设计及关键故障排查与解决；</li><li>设计和开发大数据处理与流式计算平台，支持实时数据处理与分析需求；</li><li>指导初中级开发人员，参与代码评审、技术方案设计与团队技术成长。</li></ol><p><strong>基本要求</strong></p><ol><li>本科及以上学历，计算机、软件工程等相关专业优先；</li><li>5年以上Java开发经验，有大型分布式系统或高并发、低延迟项目实践经验；</li><li>具备优秀的逻辑思维能力、系统分析能力和复杂问题解决能力。核心</li></ol><p><strong>技术要求</strong></p><ol><li>Java基础与JVM：精通Java语言，深入理解JVM内存模型、多线程与并发编程。</li><li>微服务架构：- 熟练掌握Spring Cloud全家桶（Spring Boot/Cloud Gateway/Eureka/Nacos/Ribbon/OpenFeign/Hystrix/Sentinel/Config/Sleuth等）- 熟悉Apache Dubbo及其服务治理、负载均衡、容错机制。- 具备微服务拆分、服务边界设计和分布式系统架构经验。- 了解API网关、服务网格（Service Mesh）等演进技术。</li><li>缓存与内存数据库：熟练掌握Redis、Hazelcast、Apache Ignite、Aerospike等内存数据库的应用与优化。</li><li>流处理与高并发：具备流式数据处理经验，熟悉Apache Kafka、Apache Flink等框架。掌握高并发、低延迟场景下的技术方案，包括缓存策略、负载均衡、异步处理等。</li><li>数据库能力：熟练使用MySQL、PostgreSQL等关系型数据库，具备SQL优化、分库分表实践经验。</li><li>消息中间件：熟悉RabbitMQ、Kafka、RocketMQ等消息队列的原理与应用场景。</li><li>大数据处理： 具备数据仓库建设或实时数据处理经验者优先。</li><li>容器与运维：了解Docker、Kubernetes等容器化技术，具备云原生架构实践经验者优先。优先条件- 具备金融行业（如股票、基金、风险管理、合约、行情等）业务背景或系统开发经验者优先。- 有量化交易系统、风控系统或其他金融核心系统开发经验者优先。*符合优先条件的候选人将在面试中获得额外关注。我们提供：- 参与高并发、高可用分布式系统架构的设计与实现机会。- 深入大数据和实时计算领域的技术挑战。- 与资深技术团队共同成长，参与技术决策和系统演进。感谢您查阅我们的招聘信息，我们内部的技术成员大多已共事十余年之久。公司全员秉持技术至上的价值观，期待和更多新力量一起创造未来无限可能，如果你也对我们感兴趣，欢迎向HR投递简历~</li></ol>', '5-10年', '582635736d5ff2de03Jz3dq9FFJV', '深圳 · 南山区 · 海上世界', '18-30K', 'JVM, Java, 分布式经验, 微服务经验, PostgreSQL, SpringCloud, MySQL, Redis, Dubbo, 架构设计经验', 'java开发工程师', 'https://www.zhipin.com/job_detail/582635736d5ff2de03Jz3dq9FFJV.html', '带薪年假, 意外险, 补充医疗保险, 团建聚餐, 交通补助, 餐补, 节日福利, 五险一金, 年终奖, 定期体检, 零食下午茶');
INSERT INTO `jobs` VALUES (429, '奔云科技', '计算机软件', '100-499人', '未融资', '本科', '<p>boss一、职位名称AI全栈工程师（Cursor / Claude Code 等方向）二、⼯作地点西安</p><p><strong>三、岗位职责</strong></p><p>1、负责基于AI辅助开发⼯具（包括Cursor、Claude Code等）的全栈开发⼯作，提升编码效率与代码质量，推动智能产品落地2、使用Java Spring Boot及Spring Cloud构建稳定、可扩展的微服务架构后端，保障系统高可⽤性3、基于Vue框架开发用户交互界面，实现友好且高性能的前端体验，注重交互细节与响应速度4、设计并优化MySQL数据库结构及复杂SQL，实现高效数据存储与访问，保障数据一致性与完整性5、结合IoTDB处理海量时序数据，支持物联网实时数据采集、存储与分析场景6、利用Redis实现缓存、分布式锁等应用，提升系统吞吐量及并发处理能力7、使用RocketMQ进行分布式消息通信与异步处理，确保高可用消息传递与系统解耦8、熟悉MQTT协议，完成物联网设备的实时通讯与数据集成，保障设备与云端的稳定连接9、基于Netty框架实现高性能、低延迟的网络通信服务，满足实时性要求较高的业务场景10、参与架构设计、技术选型、系统性能优化及技术难题攻关，推动技术栈的持续演进11、跨部门协作，与产品、测试、运维团队紧密配合，保障项目按时交付与持续迭代四、产品相关要求1、理解AI产品的业务场景及用户需求，能将技术方案有效转化为落地产品功能2、具备从需求分析、功能设计到上线运营的完整产品开发生命周期经验3、关注用户体验，能与产品经理、设计师密切合作，推动产品交互与功能完善4、熟悉数据驱动的产品迭代流程，能够结合数据反馈不断优化产品性能和用户体验5、具备快速响应业务变更能力和多任务协同执行能力，保障项目高效推进6、能够设计和实现AI能力模块与业务系统的灵活集成，满足多样化场景需求7、了解行业AI发展趋势，具备创新意识，推动产品不断升级迭代</p><p><strong>五、任职要求</strong></p><p>1、计算机及相关专业本科及以上学历，3年以上Java后端开发经验2、熟练掌握Spring Boot及Spring Cloud微服务开发框架，理解微服务架构设计原则和常用模式3、熟悉Vue前端开发，具备良好的组件设计能力和前端性能调优经验4、熟悉MySQL数据库设计及优化，有实际复杂业务数据库设计和调优经验5、有IoTDB时序数据库应用经验者优先6、熟悉Redis缓存架构和分布式缓存机制，具备实际项目应用经验7、具备RocketMQ消息队列集成及运维经验，理解消息中间件在高并发场景下的应用8、熟悉MQTT协议，了解物联网设备接入流程，有实际物联网项目经验者优先9、掌握Netty网络编程，有高性能网络通信系统开发经验10、熟练使用Cursor、Claude Code等AI辅助开发工具，能够借助AI工具提升编码效率和代码质量，具备AI时代的开发思维11、具备良好的沟通协作能力，责任心强，具备快速学习和解决问题能力六、加分项1、熟练运用Claude Code、Cursor等工具优化开发流程，对AI辅助编程模式有深入实践2、参与过大型分布式系统设计与开发，具备高并发、高可用系统实战经验3、有Android应用开发经验，熟悉安卓系统架构或嵌入式通讯协议（如串口、MQTT等），能够参与移动端与硬件的联调工作4、有AI开源项目贡献经验或技术博客沉淀者优先5、具备物联网全栈技术能力，理解从设备端到云端的完整数据链路</p>', '5-10年', 'b95045fd1807a1890nF92dS9EFNQ', '深圳 · 光明区 · 光明', '18-30K', 'Java, SpringCloud, MySQL, 物联网经验, 不接受居家办公', 'AI高级全栈工程师', 'https://www.zhipin.com/job_detail/b95045fd1807a1890nF92dS9EFNQ.html', '生日福利, 节日福利, 零食下午茶, 定期体检, 年终奖, 餐补, 节假日加班费, 绩效奖金, 五险一金, 带薪年假, 股票期权, 通讯补贴, 加班补助, 团建聚餐');
INSERT INTO `jobs` VALUES (430, '德恩', '其他专业服务', '0-20人', '', '大专', '<p><strong>职位描述</strong></p><ol><li>专科以上学历，5年以上经验</li><li>5年经验以上，有过大型WMS，MES相关经验的开发，熟练使用AI。\n杜金亮\n在线\n德恩\n·\n招聘经理\n竞争力分析\n查看完整个人竞争力\n个人综合排名：在人中排名第\n你在？位置\n一般 良好 优秀 极好\nBOSS 安全提示\n严禁用人单位和招聘者用户做出任何损害求职者合法权益的违法违规行为，包括但不限于扣押求职者证件、收取求职者财物、向求职者集资、让求职者入股、诱导求职者异地入职、异地参加培训、违法违规使用求职者简历等，您一旦发现此类行为， 请立即举报\n工商信息\n公司名称\n广州市德恩信息科技有限公司\n法定代表人\n陈敏林\n成立日期\n2020-08-24\n企业类型\n有限责任公司（自然人独资）\n经营状态\n在营\n注册资金\n30万人民币元\n查看全部\n工作地址\n深圳南山区南山区科技园15号\n点击查看地图\n更多职位\n看过该职位的人还看了\njava开发\n15-25K·13薪\n某大型公司\n深圳\njava开发（半导体大厂）\n15-25K\n某知名半导体/芯片公司\n深圳\nweb3后端开发工程师\n15-20K\n深圳通盛源科技\n深圳\n高级java开发工程师\n15-30K\n嘉立创\n深圳\njava开发（半导体大厂\\国企\\六险一金）\n15-25K·13薪\n某大型公司\n深圳\nFDE工程师（跨境电商+AI）\n15-20K\n增量科技\n深圳\n精选职位\nJava开发（大厂，六险一金）\n15-25K·13薪\n某大型公司\n深圳\nFDE工程师（跨境电商+AI员工方向）\n15-18K·13薪\n增量科技\n深圳\nJava\n15-16K\n同和信息技术有限公司\n深圳\n中级java开发工程师\n15-18K\n众投互联\n深圳\nJava\n15-30K·14薪\n艾麦物流\n深圳\n软件开发岗（营销）\n15-25K·16薪\n招商基金\n深圳\n深圳\n搜索\n城市招聘 热门职位 推荐公司 热门企业\n克拉玛依招聘\n平顶山招聘\n南京招聘\n海西蒙古族藏族自治州招聘\n长春招聘\n阜新招聘\n渭南招聘\n嘉峪关招聘\n铜川招聘\n保山招聘\n首页深圳招聘·Java招聘深圳Java招聘德恩Java招聘\n页面更新时间：2026-08-05\n企业服务热线和算法/未成年人等举报渠道 400 065 5799\n老年人直连热线400 661 6030\n工作日 8:00 - 22:00\n休息日 8:00 - 22:00\n企业服务\n职位搜索\nAPP\n投资者关系 Investor Relations\n直品公益基金会\n求职技巧\n使用与帮助\n协议与规则\n隐私政策\n防骗指南\n使用帮助\n联系\n北京华品博睿网络技术有限公司\n公司地址 北京市朝阳区太阳宫中路16号院1号楼18层1801内09\n违法和不良信息举报邮箱/未成年人举报渠道 jubao@.com\nCopyright © 2026 京ICP备14013441号-5京ICP证150923号 电子营业执照 京公网安备11010502032801 朝阳网警 人力资源服务许可证 网上有害信息举报专区 朝阳区人社局监督电话 算法备案信息</li></ol>', '5-10年', '34bdf52f26a45db50nBz3tq5FFJV', '深圳 · 南山区 · 科技园', '15-20K', 'Java, 不接受居家办公, 分布式经验, 微服务经验, SpringCloud, MySQL, Oracle', 'Java开发', 'https://www.zhipin.com/job_detail/34bdf52f26a45db50nBz3tq5FFJV.html', '');
INSERT INTO `jobs` VALUES (431, '仁豪网络科技', '电子商务', '100-499人', '不需要融资', '大专', '<p>关于 Hipo 平台Hipo 是面向欧美市场的代采 SaaS 平台，已运营 1 年，累计服务 100多万+欧美用户，目前算是代⾤赛道的头部玩家了。平台覆盖⾤购、质检、仓储、物流、对账全链路，17+功能模块在线运⾏。现处于高速增长期，技术架构和产品体系需要从“能跑”升级到“跑得快跑得稳”。</p><p><strong>一、岗位职责</strong></p><p>1.负责模块级别的产品设计、开发和交付2.独⽴完成业务需求的技术方案设计与代码实现3.主导AI功能开发，与架构师协作推进AI客服工单等项目落地3.参与代码评审，保障代码质量4.借助AI工具提升开发效率</p><p><strong>二、任职要求</strong></p><p>必备项：1.VibeCoding能力有AI工具使用经验（Cursor/Copilot/DeepSeek等），能够借助AI辅助完成业务需求的设计和开发2.AI应用能力有AI大模型调用、Prompt优化或简单RAG应用经验3.资深开发级编码能力5年以上Java后端经验，对业务模块架构有清晰认知，能独立完成模块级开发任务4.跨境电商项目经验有跨境电商项目开发经验5.表达沟通能力能够清晰表达技术方案，有自驱力6.技术栈i:JAVA相关技术栈（熟练级别）ii:熟悉Vue/Python/Go任一iii:熟悉ES/MQ/Redis/Cloud Alibaba等组件iv:熟悉多种数据库（MySQL/MongoDB/PG等）三、要解决的核心问题1.0需求加速开发（从需求池中承接并交付）AI客服工单系统的开发落地2.0电商平台开发（对标阿里巴巴/淘宝/得物，8月立项）</p>', '5-10年', 'a3980a408517d2530nFz3ty6FlZS', '深圳', '17-23K', 'Golang, Java, SpringCloud, Kafka, Elasticsearch, MySQL, MongoDB, 架构设计经验, 不接受居家办公, 跨境电商, AI开发', '高级Java（电商+ai经验）', 'https://www.zhipin.com/job_detail/a3980a408517d2530nFz3ty6FlZS.html', '团建聚餐, 五险, 零食下午茶, 带薪年假, 员工旅游, 生日福利, 工龄奖, 法定节假日三薪, 绩效奖金, 底薪加提成, 节日福利, 节假日加班费');
INSERT INTO `jobs` VALUES (432, '深圳市科南数字信...', '计算机软件', '0-20人', '', '大专', '<p><strong>一、岗位职责</strong></p><p>1、协助核心业务系统（ERP、供应链、订单履约等）的开发和维护2、参与系统功能模块的设计和实现3、编写高质量代码，参与代码评审和技术文档编写4、协助解决系统运⾏中的问题，参与性能优化5、配合业务需求分析，学习参与技术⽅案讨论⼆、</p><p><strong>任职要求</strong></p><ol><li>专科及以上，5年-8年相关经验- 熟练掌握Java编程，具备良好的编程习惯2、了解面向对象编程思想和设计模式3、学习能力强，能快速掌握新技术框架4、责任⼼强，具备良好的沟通协作能力三、技能要求：</li><li>有电商或业务系统开发经验</li></ol>', '5-10年', '903462ace46164940nJ43d2-EVtY', '深圳', '12-15K', 'Java, SpringCloud, MySQL', 'Java', 'https://www.zhipin.com/job_detail/903462ace46164940nJ43d2-EVtY.html', '');
INSERT INTO `jobs` VALUES (433, '鹏友控股', '电子商务', '100-499人', '未融资', '大专', '<p><strong>岗位职责</strong></p><ol><li>参与需求分析、以及详细设计。</li><li>优化现有系统的性能，解决系统中的关键问题。</li><li>功能模块代码编写、不断进行系统优化。</li><li>对线上功能持续跟踪支持。</li><li>抗压能力强，随时支持解决线上问题。</li></ol><p><strong>任职要求</strong></p><ol><li>熟悉linux开发环境，熟练掌握JAVA语言，熟悉多线程、网络编程；</li><li>具有4年以上互联网业务开发经验或大容量网络服务相关经验者优先；</li><li>精通常用开源框架 Spring系列、MyBatis、Redis、MQ、ZK、ES、MongoDB等；</li><li>熟练掌握数据分析体系架构、方法和相关数据建模知识，有海量数据分析经验者优先；</li><li>有丰富的SpringCloud和dubbo的项目实践经验；</li><li>具有Docker、K8S、Netty、微服务前后台框架、消息中间件、容器化部署、安全开发等相关经验者优先；</li><li>具备强烈的责任心，团队配合精神，良好的文档习惯；</li><li>有电商开发经验者优先考虑。</li></ol>', '5-10年', 'f2b93298e5de0a5b1Hd-3dS9FlVT', '深圳 · 南山区 · 科技园', '15-20K·13薪', 'Java, 分布式技术, Linux, 架构师, SpringCloud, dubbo, Spring', '高级Java开发工程师', 'https://www.zhipin.com/job_detail/f2b93298e5de0a5b1Hd-3dS9FlVT.html', '员工旅游, 节日福利, 夜班补助, 生日福利, 团建聚餐, 零食下午茶, 五险一金, 带薪年假, 高温补贴');
INSERT INTO `jobs` VALUES (434, '南通盛江贸易有限公司', '食品/饮料/烟酒', '0-20人', '', '本科', '<p><strong>岗位职责</strong></p><ol><li>参与公司各业务线软件产品的全生命周期运维管理工作，负责搭建、优化软件持续集成 / 持续部署（CI/CD）流程，能够独立开发运维自动化⼯具及功能模块，保障软件系统稳定、⾼效、安全运⾏；​2、编写并维护 CI/CD 流程文档、运维自动化脚本说明⽂档、系统架构文档、故障排查手册等软件开发与运维过程中的关键文档，确保文档的规范性、时效性和可复用性；​3、负责软件系统的日常监控、性能优化、故障排查与应急响应，及时处理服务器、容器、网络等层面的问题，保障业务系统 稳定运行；主动推进运维流程标准化、自动化，降低人工运维成本，提升运维效率。</li><li>参与 AI 模型的私有化部署，参与 AI 应用平台的搭建和部署。</li></ol><p><strong>任职要求</strong></p><ol><li>学历/专业：全日制本科或以上学历，计算机科学与技术、软件工程、人工智能、自动化等相关专业；​2、工作经验：从事 5 年或以上DevOps相关工作经验，有 AI 模型大规模部署、运维或 AI 平台搭建经验者优先;</li><li>技能要求：​3.</li><li>必备技能：​（1）熟练掌握至少一种主流编程语言，如 Python、Shell，能够独立编写自动化脚本；​（2）精通 Docker 容器化技术，熟悉 Kubernetes 容器编排平台的使用与运维；​（3）掌握主流 CI/CD 工具（如 Jenkins、GitLab CI、GitHub Actions），能够搭建并优化 AI 模型的 CI/CD 流程；​（4）了解常见 AI 框架（如 TensorFlow、PyTorch），熟悉 AI 模型的部署方式（如 vllm、ollama、llama.cpp）；​3.</li><li>通用技能：​（1）熟悉 Linux 操作系统，具备良好的 Shell 脚本编写能力；​（2）了解数据库（如 MySQL、MongoDB）及缓存技术（如 Redis）的基本使用与运维；​（3）掌握监控告警工具（如 Prometheus、Grafana），能够搭建 AI 服务的监控体系；​4、工作素质：​（1）具备强烈的责任心和良好的团队合作意识，能够与研发、算法团队高效协作；​（2）有较强的逻辑分析能力、问题排查能力及文档编写能力，能够清晰记录运维过程及解决方案；​（3）具备快速学习能力，能够及时跟进 AI DevOps 领域的新技术、新工具，并应用到实际工作中；​5、语言要求：英语读写能力良好，能够阅读英文技术文档；会粤语者优先。</li></ol>', '5-10年', 'eece82736e65664103x-39i9EVNZ', '深圳 · 南山区 · 科技园', '18-23K', 'Java, Python, Spring, MySQL, MongoDB, 分布式经验, 微服务经验, 物联网经验, 不接受居家办公, DevOps, AI', 'JAVA开发工程师（偏AI方向）-中高级', 'https://www.zhipin.com/job_detail/eece82736e65664103x-39i9EVNZ.html', '');
INSERT INTO `jobs` VALUES (435, '瑞维控股', '物业管理', '100-499人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>技术方案设计与评审：基于业务需求，主导或深度参与系统级技术方案的设计与评审，包括架构规划、数据库设计等，为技术选型与系统演进提供专业建议。</li><li>技术攻坚与系统优化：负责核心模块的性能优化与架构调优，协助团队解决关键技术难题，参与系统监控与稳定性建设，保障业务高可⽤。</li><li>产品架构与模块开发：参与产品架构讨论，独⽴或带领团队完成关键⼦系统/模块的设计与开发，包括接口定义、业务逻辑实现及数据模型构建。</li><li>团队技术赋能与管理：编写核心模块技术文档，传导业务理解与技术⽅案，指导并管理后端开发团队，为项目顺利推进提供技术保障。</li><li>系统安全与规范推动：关注系统安全风险，推动实施相关安全策略与最佳实践，提升模块安全性。</li><li>协同与支持：高效完成上级交办的其他技术或管理相关任务，协同跨团队协作。</li></ol><p><strong>任职要求</strong></p><ol><li>全日制统招本科及以上学历，计算机、通信等相关专业，5年以上Java开发经验，1年以上后端团队管理或技术带队经验，具备中小型项目全流程架构经验或大型项目核心模块架构能力；</li><li>精通Java语言，深入理解JVM机制，具备线上问题排查与性能调优实战经验；</li><li>熟练掌握常用设计模式与原则，能将其灵活应用于实际项目设计中；</li><li>精通Spring Boot、Spring MVC等主流框架，熟悉Spring Cloud微服务生态及相关组件（如Nacos）；</li><li>精通MySQL数据库，熟练编写高效SQL，具备索引优化及慢查询分析能力；</li><li>熟练使用Redis、Memcached等至少一种NoSQL技术，并能结合业务场景进行合理选型与应用；</li><li>熟悉分布式系统常见理论（如CAP/BASE、分布式事务），了解分布式缓存、消息中间件（Kafka/RocketMQ/RabbitMQ）、Zookeeper等技术的应用场景与实现原理，有高并发、高可用系统经验者优先；</li><li>对技术有强烈热情，具备优秀的学习、分享和自驱力，良好的问题分析、解决与总结能力，擅长沟通协作和项目管理，能承受压力，具备多任务处理与团队领导力。</li></ol>', '5-10年', 'c3b0fb46da1f61e703x42d-1F1BX', '深圳 · 南山区 · 科技园', '18-25K·13薪', 'JVM, Java, 团队管理经验, 不接受居家办公, SpringCloud, Redis, Dubbo, Spring, 分布式, 微服务经验, Zookeeper, MySQL, 多线程, 架构设计经验', 'java开发组长', 'https://www.zhipin.com/job_detail/c3b0fb46da1f61e703x42d-1F1BX.html', '五险一金, 团建聚餐, 全勤奖, 年终奖, 带薪年假, 定期体检, 餐补');
INSERT INTO `jobs` VALUES (436, '启创数智', '大数据', '100-499人', '不需要融资', '本科', '<p>面试流程：boss一面线上+二⾯线下</p><p><strong>岗位职责</strong></p><ol><li>企业级智能体全流程落地：主导基于LangChain、OpenClaw等（掌握其⼀及以上）智能体框架AI Agent开发，负责架构设计、任务编排及⼯具集成，支撑流程自动化、数字员⼯等核心场景落地。</li><li>大模型应用优化：主导大模型API应用方案设计，搭建标准化提示词工程，优化指令拆解与对话逻辑，解决知识幻觉痛点，提升智能体执行准确率与稳定性。</li><li>RAG系统优化：主导企业级RAG系统架构设计与性能调优，基于Milvus等向量数据库，解决大规模数据检索准确率、响应速度问题，保障系统高可用。</li><li>Java微服务开发集成：负责智能体相关Java微服务设计、开发与维护，基于Spring Cloud搭建高可用后端，实现与现有业务系统无缝集成，解决分布式事务等工程难题。</li><li>工程化沉淀迭代：主导智能体生产级部署与运维，搭建可观测性体系；推动技术复用，落地前沿技术至业务场景。</li></ol><p><strong>任职要求</strong></p><ol><li>专业：本科及以上，计算机、软件工程、人工智能等相关专业；</li><li>工作经验：5年以上Java/Python后端开发经验，1年以上LLM及智能体开发经验，有企业级智能体项目主导经验优先。</li><li>Java微服务：精通Spring Boot、Spring Cloud，熟悉分布式事务、高并发处理及服务治理，有大规模Java系统开发维护经验；</li><li>智能体开发：精通Python后端，深入理解至少一种主流多智能体框架，具备框架二次开发能力；精通提示词工程，可独立完成Python项目模块化、工程化开发与优化；</li><li>RAG与向量数据库：主导过企业级RAG系统优化，熟悉Milvus等向量数据库的使用与调优；</li><li>大模型应用：熟悉主流大模型API调用，了解模型微调、上下文工程等技术，掌握大模型能力边界；</li><li>工作流：熟悉常见工作流引擎（如Flowable、Activiti、Camunda等），能结合工作流实现智能体复杂任务流编排与管控；</li><li>AI项目：主导或参与过至少2个企业级AI智能体项目上线，可独立完成全流程开发运维；能独立解决多智能体协同、工具调用等复杂问题。</li><li>工程化能力：熟悉Linux环境，精通Docker、K8s容器化部署运维；具备扎实Python工程化能力，可独立完成Python项目打包、部署与运维；了解LLMOps及LangSmith，有智能体监控调优经验；熟悉MCP协议。其他要求：</li><li>有技术沉淀意识，自驱力强，对AI智能体、大模型前沿技术敏感。</li></ol>', '5-10年', '0efca00ef95c44dc0nd83d25FVRX', '深圳 · 龙岗区 · 龙岗中心城', '18-25K', '', '智能体应用开发工程师 (MJ000151)', 'https://www.zhipin.com/job_detail/0efca00ef95c44dc0nd83d25FVRX.html', '餐补, 带薪年假, 绩效奖金, 五险一金');
INSERT INTO `jobs` VALUES (437, '深圳艾融科技有限...', '企业服务', '100-499人', '未融资', '本科', '<p><strong>岗位要求</strong></p><ol><li>有GFIX、司库业务、跨行支付开发经验优先。</li><li>理解 docker, kubernetes 基本原理，有容器下部署服务的经验3、熟悉 JAVA 语言与常用框架，如果有 python 语⾔开发经验更佳，熟悉spring cloud等框架，具备丰富的微服务开发经验4、已具备中级⼯程师实际⼯作能力，有code review的能力，熟悉缓存、消息等机制，有redis、kafka、rocketMq、ES使⽤经验5、熟悉linux操作系统、git操作，有JVM调优、SQL调优实战经验6、熟悉银行业务，熟悉银行业常用系统软件、基础架构平台、开发工具及软件工程管理工具7、深入了解银行业涉及的各项技术领域知识，在某一（银行所需）领域具有较高的技术能力，能独立主持和指导中型技术项目，或具有较强的业务需求引导、挖掘和规格化能力8、较强的沟通、协调能力，能指导中级及以下技术人员高效工作，并可有效推动解决困难任务9、能展示系统设计与开发的理念或成功案例10、有项目经理，项目管理经验优先</li></ol><p><strong>岗位职责</strong></p><ol><li>长期驻场为客户提供现场及远程的实施开发服务；</li><li>独立与业务需求方、关联系统技术人员沟通，梳理业务逻辑，编写和修订需求、设计、维护等软件过程文档；</li><li>负责系统对外数据接口的设计和开发；</li><li>参与相关应用的运维工作；</li><li>参与相关应用项目的开发，完成上级领导分配的各项工作；</li><li>能独立承担与客户沟通、内部协同工作；</li></ol>', '5-10年', '02fddda0db571d8e0nJ43d61GFdX', '深圳 · 罗湖区 · 东门', '10-15K', 'Java, 不接受居家办公, SpringCloud, MySQL, Redis, Spring, Oracle', 'Java', 'https://www.zhipin.com/job_detail/02fddda0db571d8e0nJ43d61GFdX.html', '节日福利, 五险一金, 零食下午茶, 股票期权, 团建聚餐, 补充医疗保险, 商业保险');
INSERT INTO `jobs` VALUES (438, '版石软件(上海)', '互联网', '100-499人', '未融资', '大专', '<p>Java开发工程师</p><p><strong>岗位职责</strong></p><ol><li>负责物联网平台及ToC端核心业务系统的架构设计与开发，保障高并发与⾼可⽤。</li><li>基于 JDK 21 及 Solon 框架进⾏敏捷开发，探索新技术以提升系统性能。</li><li>参与B端功能迭代，负责营销、现场运维类功能开发4、参与C端功能迭代，优化接口响应速度，保障流量高峰期的系统稳定。</li></ol><p><strong>任职要求</strong></p><ol><li>5年及以上Java开发经验，有完整的IoT或ToC应用落地经验优先。</li><li>熟练掌握Java基础、springboot、solon等开发框架3、熟练掌握 JDK 21 新特性并有实际应⽤经验。</li><li>熟练使用mysql、redis、Elasticsearch等数据库5、熟练使用rocketMQ中间件6、具备良好的代码规范和逻辑思维，沟通顺畅，能独立完成模块开发任务7、具备一定的抗压能力加分项：</li><li>参与过solon框架应用落地2、参与过物联网平台核心开发3、参与过数据平台核心开发早8点30 晚5点30双休，深圳的需要到面，实在道面不了也可以线上深圳市南山区中心路深圳湾段3331号南门，南山区中建科工大厦</li></ol>', '5-10年', '389cf8b3ad1671860nJ52tq5F1VR', '深圳 · 南山区 · 科技园', '10-13K', 'Java, Spring, MySQL, Oracle, 微服务经验, 分布式经验', 'Java-物联网平台-双休_wb9zj', 'https://www.zhipin.com/job_detail/389cf8b3ad1671860nJ52tq5F1VR.html', '带薪年假, 五险一金, 有无线网, 员工旅游');
INSERT INTO `jobs` VALUES (439, '未来海外', '互联网', '0-20人', '不需要融资', '本科', '<p>【boss职位概述】我们正在寻找一位拥有扎实Java技术功底和丰富支付系统开发经验的后端工程师加入我们。你将负责核⼼⽀付系统的架构设计与优化，保障系统的⾼可用、高性能与资⾦安全。如果你对区块链技术有深入理解或实战经验，这将是你的巨大加分项，你将有机会参与前沿的链上支付或资产托管系统的建设。【</p><p><strong>岗位职责</strong></p><p>】系统研发： 负责支付核心系统（如订单、账务、清结算、对账、渠道网关等）的设计、开发与维护。高可用保障： 确保支付系统在极端高并发场景下的数据一致性、准确性和系统稳定性，处理各种分布式事务难题。区块链探索（加分项）： 参与基于区块链技术的智能合约应用结算系统的设计与研发。技术攻关： 解决线上疑难问题，持续对系统进行性能优化和重构。【</p><p><strong>任职要求</strong></p><p>】（一）必须项（Java + 支付经验）：技术栈： 5年以上Java开发经验，对JVM原理、多线程并发、网络编程有深刻理解；熟悉Spring Boot/Cloud、Dubbo等微服务框架。支付经验： 必须具备支付或金融行业经验。数据一致性： 深刻理解分布式事务（TCC/Seata/RocketMQ事务消息），具备处理最终一致性的实战经验。数据库： 精通MySQL调优，熟悉分布式数据库（如TiDB）或NoSQL（如Redis）在金融场景下的使用。安全合规： 了解PCI-DSS或国家金融安全合规</p><p><strong>基本要求</strong></p><p>，对加签/加密、防重放、防篡改有成熟方案。（二）优先项（区块链经验）：链上交互： 熟悉至少一条主流公链（如Ethereum、TRON、BNB Chain交互原理。智能合约： 了解Solidity或Go合约开发，能够配合进行链上数据的解析与监听（Event Log）。钱包/资产托管： 有对接节点、构造/解析离线交易、管理私钥/助记词或接入主流MPC/HSM服务经验者优先。DeFi/Web3： 有深入研究者优先。（三）</p><p><strong>综合素质</strong></p><p>计算机相关专业本科及以上学历。具备极强的逻辑思维能力和对资金的敬畏心，对Bug零容忍。良好的沟通能力和跨团队协作能力，能够承受一定的工作压力。【加分亮点】熟悉区块链底层原理，有实际DApp后端开发经验熟悉Rust或Go语言，有多语言混合编程经验</p>', '5-10年', '7659da191c9adc6b0nJ52tq_F1BY', '深圳 · 南山区 · 蛇口', '18-25K', '', '资深java开发工程师', 'https://www.zhipin.com/job_detail/7659da191c9adc6b0nJ52tq_F1BY.html', '底薪加提成, 年终奖, 带薪年假, 五险一金, 绩效奖金');
INSERT INTO `jobs` VALUES (440, '天空之成', '游戏', '0-20人', '', '本科', '<p>硬性条件：有游戏开发经验，带过团队，没有的勿扰！！！Java高级工程师________________________________________</p><p><strong>一、岗位职责</strong></p><ol><li>负责核心业务系统的架构设计与开发，⽀撑⾼并发场景</li><li>参与系统架构设计，优化系统性能与稳定性</li><li>负责⾼并发场景下的技术方案设计（缓存、限流、降级等）</li><li>深入分析并解决系统瓶颈（JVM、数据库、IO等）</li><li>参与数据库设计与优化，保障数据⼀致性与高可用</li><li>负责系统安全设计（接口安全、防攻击、防刷等）</li><li>推动技术优化与规范落地，提高团队整体研发质量 ________________________________________</li></ol><p><strong>二、任职要求</strong></p><p>（重点筛选项）1. 基础要求• 5年以上 Java 开发经验 • 扎实的 Java 基础，熟悉集合、多线程、并发编程 • 熟悉主流框架：Spring Boot / Spring Cloud ________________________________________2. 高并发经验（必须）• 有实际高并发系统经验（如：支付、秒杀、游戏、交易系统） • 熟悉以下方案： o 缓存架构（Redis） o 消息队列（Kafka / RabbitMQ） o 限流、熔断、降级设计 • 能独立设计高并发解决方案（抗压、削峰填谷） ________________________________________3. 架构能力（核心）• 熟悉分布式系统架构设计 • 熟悉微服务架构拆分与治理 • 熟悉服务注册、配置中心、链路追踪等体系 • 有系统重构或架构升级经验优先 ________________________________________4. JVM（重点考察）• 熟悉 JVM 内存模型、类加载机制 • 熟悉 GC 原理（CMS / G1）及调优 • 能定位并解决： o 内存泄漏 o 频繁 GC o Full GC 问题 能用工具分析（jmap / jstack / Arthas）优先________________________________________5. 数据库能力（强要求）• 熟练使用 MySQL • 熟悉： o 索引优化 o SQL调优 o 分库分表 • 理解事务、锁机制（MVCC） • 有高并发下数据一致性处理经验 加分：• 熟悉 NoSQL（Redis / MongoDB） • 有读写分离、分布式事务经验 ________________________________________6. 安全（必须懂）• 熟悉常见安全问题： o SQL注入 o XSS / CSRF o 接口防刷 • 熟悉： o JWT / Token机制 o 权限系统设计 • 有风控 / 防攻击经验优先 ________________________________________三、加分项（优先考虑）• 有游戏 / 支付 / 金融 / 交易系统经验 • 熟悉容器化部署（Docker / Kubernetes） • 有高可用架构设计经验（多机房 / 容灾） • 有监控体系建设经验（日志 / 链路 / 指标） • 熟悉中间件源码或有深入研究 ________________________________________四、我们希望你具备• 能独立扛模块，而不是只写 CRUD • 能定位复杂问题，而不是依赖别人 • 有架构思维，而不是只关注功能实现</p>', '5-10年', 'c315d4c6f4183ef80nFz3dS1FVFY', '深圳 · 宝安区 · 西乡', '15-25K', 'Java, 团队管理经验, 不接受居家办公, SpringCloud, MySQL, Kafka, Redis, 游戏, 架构设计经验, Spring, 游戏后端经验', 'Java（游戏方向）', 'https://www.zhipin.com/job_detail/c315d4c6f4183ef80nFz3dS1FVFY.html', '零食下午茶, 餐补, 节假日加班费, 夜班补助, 定期体检, 五险一金');
INSERT INTO `jobs` VALUES (441, '易活跃', '计算机软件', '20-99人', '天使轮', '本科', '<p>精通Java restful开发精通mysql数据库精通maven业务分析能力强vue开发，熟悉elementui等前端组件小程序开发</p>', '5-10年', '637be870f48e1a871Xd72N-4GFFS', '深圳', '8-13K·13薪', 'Maven, 架构师, 高级软件工程师, Linux, GIT, JDK, MySQL', 'Java高级工程师', 'https://www.zhipin.com/job_detail/637be870f48e1a871Xd72N-4GFFS.html', '团建聚餐, 带薪年假, 节日福利, 零食下午茶, 员工旅游, 绩效奖金, 股票期权, 五险一金, 年终奖');
INSERT INTO `jobs` VALUES (442, '上海缘始科技', '互联网', '20-99人', '不需要融资', '大专', '<p><strong>岗位职责</strong></p><ol><li>基于SpringBoot框架构建微服务架构，主导技术方案落地与关键技术攻关；</li><li>负责MySQL数据库优化（索引设计、分库分表、SQL调优），Elasticsearch集群的搭建与搜索方案实现；</li><li>使⽤XXL-JOB构建分布式任务调度系统，解决定时任务幂等性、失败补偿等核⼼问题；</li><li>参与技术预研，参与代码Review，推动团队技术规范与DevOps流程落地。</li><li>推动 AI 编程⼯具在研发流程中的落地，提高研发效率；</li><li>持续关注新技术趋势，推动团队技术升级与最佳实践建设。</li></ol><p><strong>任职要求</strong></p><ol><li>技术栈要求：-精通SpringBoot架构，熟悉JVM调优及常用设计模式。-熟练掌握MySQL（事务隔离级别、锁机制、执⾏计划优化），有分库分表实战经验。-熟悉Elasticsearch底层原理，能独立完成分词器选型、DSL优化及集群运维。-有XXL-JOB/Quartz等任务调度系统二次开发经验，熟悉分布式锁（Redisson/Zookeeper）。-掌握消息中间件（Kafka/RocketMQ）、Redis缓存及分布式ID生成方案。</li><li>有实际使用 AI 编程工具辅助开发经验:-熟悉以下一种或多种工具：-Cursor-Codex-Claude Code-能利用 AI 提升开发效率、代码质量及问题排查效率。加分项：-有大规模系统性能调优经验（如：GC频繁、慢SQL治理、ES深度分页优化）。-有技术团队管理经验或开源项目贡献。</li></ol>', '5-10年', '118430c29bf470c80nF_2NS9GFJQ', '深圳 · 南山区 · 科技园', '15-25K', 'Java, MySQL, Spring', 'Java', 'https://www.zhipin.com/job_detail/118430c29bf470c80nF_2NS9GFJQ.html', '团建聚餐, 五险一金, 零食下午茶, 节日福利');
INSERT INTO `jobs` VALUES (443, '全民互动 互联网', '游戏', '100-499人', 'A轮', '本科', '<p><strong>一、岗位职责</strong></p><ol><li>负责游戏中台业务系统的架构设计，代码实现，牵头性能优化，建立代码规范与质量标准，保障系统稳定性与扩展性。</li><li>指导中级 / 初级开发工程师，参与代码评审、技术分享与培训，推动团队技术能力提升。</li><li>深度理解游戏发⾏、⼴告投放、数据中台等业务场景，将业务战略转化为合理技术⽅案，平衡业务迭代速度与技术架构健康度。</li><li>调研行业前沿技术，引入合适的技术框架与⼯具，推动团队工程化、自动化能力升级。</li></ol><p><strong>二、岗位要求</strong></p><p>● 计算机相关专业，本科及以上学历，5 年及以上 Java 后端开发经验，至少 2 年分布式系统或微服务架构设计经验。● 精通 Java 核心技术（JVM 调优、并发编程、IO/NIO），深入理解面向对象设计原则、设计模式。● 精通 Spring 全家桶（Spring Boot、Spring Cloud Alibaba/Spring Cloud）、Dubbo 等微服务框架，掌握服务治理、限流降级、分布式事务解决方案，有架构优化实战经验。。● 精通 MySQL 数据库原理，熟练掌握分库分表、SQL 极致优化、索引设计、事务隔离级别等；深入理解 Redis 缓存原理（持久化、集群方案、缓存穿透 / 击穿 / 雪崩解决方案），熟悉 MongoDB/Elasticsearch 等 NoSQL 数据库的应用场景与优化。● 精通 RabbitMQ/Kafka 消息队列的架构设计、性能调优、可靠性保障；熟悉 ElasticJob/XXL-JOB 分布式定时任务。● 熟练使用ClickHouse、Doris列式数据库，具备海量数据实时查询与分析优化能力，适配游戏发行数据统计场景。● 加分项：○ 具备大规模高并发、高吞吐、高可用系统设计与实战经验。○ 熟悉大数据组件（Hadoop/Spark/Flink）、流计算、数据湖等技术。○ 有数据中台、广告投放系统、游戏发行相关平台开发经验。○ 掌握Vue前端开发技能，具备全站开发经验。</p>', '5-10年', '1eb614fb78d371d60nd_0t-1GVVR', '深圳 · 龙岗区 · 坂田', '18-22K', 'Java, 大数据经验, 不接受居家办公, MySQL, Redis, Spring', '高级java游戏开发工程师', 'https://www.zhipin.com/job_detail/1eb614fb78d371d60nd_0t-1GVVR.html', '加班补助, 餐补, 带薪年假, 全勤奖, 员工旅游, 零食下午茶, 五险一金, 节日福利, 生日福利, 文娱活动');
INSERT INTO `jobs` VALUES (444, '企欣科技', '计算机软件', '0-20人', '未融资', '大专', '<ol><li>boss大专6年以上相关Java、.NET研发工作经验，有MES相关生产系统的开发经验为佳；</li><li>熟练掌握C#、Java等两种以上开发技术，熟悉主流开发工具；</li><li>具有Oracle或Sql server数据库开发经验，熟练掌握PL/SQL；</li><li>对技术有强烈的兴趣，喜欢钻研，具有良好的学习能⼒；</li><li>具备良好的沟通能⼒，团队合作能⼒以及推进工作执行，明确⽬标结果能力</li></ol>', '5-10年', '291ba779dd3d4d3d0nJ409y5ElFY', '深圳 · 坪山区 · 坪山', '16-19K', '', '高级java开发', 'https://www.zhipin.com/job_detail/291ba779dd3d4d3d0nJ409y5ElFY.html', '底薪加提成');
INSERT INTO `jobs` VALUES (445, '顶尖传诚科技有限公司', '互联网', '100-499人', '未融资', '大专', '<p>岗位概述 1. 计算机相关专业，5 年以上 Java 核心开发经验，具备 Python 项目开发实操经验2. 扎实 Java、Python 基础；精通 JVM 调优、Java IO、多线程、网络编程；熟悉 Python 协程、GIL 及性能优化3. 熟用各类设计模式，深⼊掌握 Spring、SpringBoot、MyBatis；会 FastAPI/Flask 等 Python 常⽤开发框架4. 精通 MySQL，熟练编写优化 SQL，理解索引、事务、锁底层机制，可通过 Python 实现数据读写处理5. 熟练使⽤ Redis、Kafka、Nacos 等中间件，至少精通一种底层原理，可使⽤ Java/Python 对接开发6. 熟练 Linux 开发运维，了解 Docker、K8s，能编写 Shell、Python 自动化脚本7. 熟练 Git、Maven 等研发工具，可使用 Python 编写自动化测试、数据处理脚本8. 具备规范的技术方案、接口文档编写能力</p><p><strong>任职资格</strong></p><p>要求项 填写说明：请填写本职位最适合的专业、教育背景，经验背景和特殊要求教育背景要求 专科以上学历工作经验 5年以上知识与技能 1. 计算机相关专业，5 年以上 Java 核心开发经验，具备 Python 项目开发实操经验2. 扎实 Java、Python 基础；精通 JVM 调优、Java IO、多线程、网络编程；熟悉 Python 协程、GIL 及性能优化3. 熟用各类设计模式，深入掌握 Spring、SpringBoot、MyBatis；会 FastAPI/Flask 等 Python 常用开发框架4. 精通 MySQL，熟练编写优化 SQL，理解索引、事务、锁底层机制，可通过 Python 实现数据读写处理5. 熟练使用 Redis、Kafka、Nacos 等中间件，至少精通一种底层原理，可使用 Java/Python 对接开发6. 熟练 Linux 开发运维，了解 Docker、K8s，能编写 Shell、Python 自动化脚本7. 熟练 Git、Maven 等研发工具，可使用 Python 编写自动化测试、数据处理脚本8. 具备规范的技术方案、接口文档编写能力其他 有AI大模型项目经验优先，抗压能力好，沟通能力好优先</p>', '5-10年', 'c4df457a43a751b70nJ52ti4EFVQ', '深圳 · 南山区 · 科技园', '18-25K', 'Java, Python, Spring, MyBatis, Kafka, Dubbo, JVM, MySQL, Redis, 分布式经验, 架构设计经验, 微服务经验, 云计算经验, AI, Nacos', 'Java开发工程师（Python/AI经验/长期TCL）', 'https://www.zhipin.com/job_detail/c4df457a43a751b70nJ52ti4EFVQ.html', '五险一金, 带薪年假, 绩效奖金, 年终奖, 加班补助, 生日福利, 保底工资, 节日福利, 底薪加提成, 团建聚餐, 零食下午茶');
INSERT INTO `jobs` VALUES (446, '悦策科技', '大数据', '20-99人', '未融资', '本科', '<p><strong>职位描述</strong></p><ol><li>负责公司数据管理平台、AI智能问数产品开发，实现系统的核心功能和模块；</li><li>负责部门工作目标的达成，组织技术团队进行技术研究与创新，确保产品按时⾼质量完成；</li><li>负责公司数据管理产品客户项⽬运营与运维服务；</li><li>参与公司数据产品售前技术⽀持。</li></ol><p><strong>任职资格</strong></p><ol><li>扎实的java编程基础。对各种开源框架（Spring、Mybatis等）有深入的运用、了解;</li><li>熟悉Redis、Redis-search向量搜索、Kafka、ElasticSearch相关中间件；</li><li>有AIGC、ChatGPT prompt，有对话、搜索等AI领域经验者，有⼤模型工程落地经验者优先或数据管理领域开发经验优先；</li><li>丰富的数据库（oracle，mysql等）使用经验，具备索引、SQL优化能力，有数据分析领域知识者优先考虑；</li><li>良好的产品化和研发质量意识，对系统质量有高要求，抗压且乐观的工作态度，有责任心和目标感；</li><li>较强的表达、沟通、协调能力和经验。</li></ol>', '5-10年', '06cecf0e8ece9cb103Nz09q9FFBV', '深圳 · 南山区 · 科技园', '13-18K', 'Java, Nginx, 大数据经验, 团队管理经验, 微服务经验, SpringCloud, MySQL, SQL Server, 架构设计经验, Spring', 'java产品研发主管', 'https://www.zhipin.com/job_detail/06cecf0e8ece9cb103Nz09q9FFBV.html', '五险一金, 定期体检, 节日福利, 股票期权, 餐补, 带薪年假, 员工旅游, 零食下午茶, 年终奖');
INSERT INTO `jobs` VALUES (447, 'mongoso', '计算机软件', '20-99人', '未融资', '本科', '<p>岗位boss</p><p><strong>职责</strong></p><ol><li>完成软件系统代码实现，编写代码注释及开发文档;</li><li>根据设计文档或需求文档完成代码编写、调试、测试和维护工作;</li><li>开发项⽬进⾏需求评审，以及相关设计;</li><li>配合项⽬经理完成相关任务目标。</li></ol><p><strong>岗位要求</strong></p><ol><li>统招本科学历，计算机等相关专业;</li><li>7年以上Java开发经验，会运用AI，使⽤Al代码编辑器;</li><li>精通Java编程，SpringBoot、Mybatis等主流框架;</li><li>熟练掌握Java、Servlet、JavaBean等开发语言和技术;</li><li>熟练掌握主流数据库MySQL、PG、Oracle等，熟悉NoSQL，具备优秀的数据建模能力和数据库分库分表设计能力，有大规模高并发环境下SQL优化经验优先;</li><li>熟练掌握分布式、缓存、消息、异步等机制，有Redis,Elasticsearch,Mq等实战经验;</li><li>有大型B端平台项目经验优先;</li><li>能够独立或协同，高质量按期完成项目;</li><li>有较强的逻辑思维能力，善于分析、归纳、解决问题，沟通能力良好。</li></ol>', '5-10年', 'f9c3abe70c7227a60nFy09i5GVJS', '深圳 · 龙华区 · 民治', '17-20K', 'Java, SpringCloud, Oracle, MongoDB, MySQL, 大数据经验', '中/高级Java开发工程师', 'https://www.zhipin.com/job_detail/f9c3abe70c7227a60nFy09i5GVJS.html', '节日福利, 生日福利, 五险一金, 保底工资, 绩效奖金, 零食下午茶, 带薪年假, 团建聚餐');
INSERT INTO `jobs` VALUES (448, '邮小哥', '即时配送', '20-99人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>参与业务需求分析，技术方案设计，技术方案开发实施；</li><li>负责基础小程序接口、后台管理系统接口、物流相关渠道服务商对接等相关系统功能的设计、代码编写、单元测试全部过程;</li><li>负责产品后端开发和维护，及相关后台管理系统开发及维护；</li><li>缺陷修复、易用性改进和性能优化，周期性完成版本发布、及时性修复Bug；</li><li>持续改进项目性能、安全性、稳定性和可扩展性；</li><li>负责新技术、新展现形式调研，解决项目开发中的技术问题；</li><li>负责保证项目进度，总结项目经验，归纳案例，实现经验共享。</li><li>负责核心业务模块的数据库设计与开发，精通MySQL数据库，具备优秀的SQL编写、性能调优及复杂问题排查能力；</li></ol><p><strong>任职要求</strong></p><ol><li>本科或以上学历，3年及以上Java开发经验；</li><li>java基础扎实、数据库基础扎实、面向对象程序设计抽象能力强；</li><li>熟练使用主流开源框架，如Struts/Spring MVC、SpringCloud、SpringBoot、Spring、MyBatis、Hibernate等主流开源框架；</li><li>熟练使用mysql/oracle等数据库技术，具备sql调优能力；</li><li>了解分布式系统的相关技术，zookeeper/redis/netty/thirft/rabbitmq/dubbo/nacos/hadoop/spark等；</li><li>熟练运用Linux操作系统，完成日常的运维支持、日志分析、脚本编写及系统环境维护；</li><li>负责线上服务的部署、监控、故障排查与性能调优，保障系统稳定运行；</li><li>深入理解MySQL，掌握索引优化、事务与锁机制、慢查询分析及高可用方案（如主从复制、读写分离）9、工作认真负责，能承受项目工作压力；较强的责任心及团队合作精神，有独立解决问题和快速学懂运用新技术的能力；</li><li>有知名互联网公司工作经验者优先,有快递物流公司工作经验者优先。薪资：10-20k</li></ol>', '5-10年', '3ee1764c19cf8f181XF-2ty8EVpW', '深圳', '11-22K', 'Java, 团队管理经验, 分布式经验, SpringCloud, Hadoop, SQL Server, Spring, 大数据经验, Zookeeper, MySQL, Spark, 架构设计经验, Oracle, 区块链经验', 'java', 'https://www.zhipin.com/job_detail/3ee1764c19cf8f181XF-2ty8EVpW.html', '带薪年假, 零食下午茶, 夜班补助, 节日福利, 年终奖, 补充医疗保险, 五险一金');
INSERT INTO `jobs` VALUES (449, '深圳市广大精微数...', '企业服务', '20-99人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>参与相关产品需求讨论,评审和软件设计；</li><li>按照项目计划，按时提交高质量代码，完成开发任务；</li><li>规范文档的编写、维护，以及其他与项目相关⼯作；</li><li>参与核⼼业务系统架构设计及优化，解决技术难题，推动技术创新。</li></ol><p><strong>任职要求</strong></p><ol><li>⼤学本科以上学历，计算机或相关专业；</li><li>3-5年以上Java实际项目开发经验；</li><li>具备扎实的Java基础技术体系，包括JVM、线程、并发、IO资源管理、网络等；</li><li>熟悉Spring Boot、Spring Cloud、myBatis、Maven等开发技术；</li><li>熟悉MySQL常⽤数据库，具备数据库设计和优化能力；</li><li>熟悉分布式系统设计和应用，包括分布式、缓存、消息、负载均衡等机制和实现；</li><li>熟悉MQ、ES、Redis等实战经验者优先；</li><li>熟悉Linux操作系统，熟练使用Tomcat、Apache，Nginx等应用和服务器配置，具备Shell脚本编写能力；</li><li>熟悉Docker、Kubernetes等容器化技术，具备DevOps相关经验；</li><li>具有完整产品生命周期开发，设计经验者优先；</li><li>具备高度的责任心和自驱力，乐于接受挑战，并在复杂环境中推动持续改进；</li><li>良好的团队协作能力和沟通能力；善于思考，能独立分析和解决问题，有持续学习和技术创新的热情，能够跟踪前沿技术发展趋势，并将其应用到产品中。</li></ol>', '5-10年', 'f909ea9e22ecbeb50nF43t6-FFZV', '深圳', '15-20K', 'Java, 不接受居家办公, SpringCloud, MySQL, MongoDB, SQL Server, Spring', 'Java', 'https://www.zhipin.com/job_detail/f909ea9e22ecbeb50nF43t6-FFZV.html', '零食下午茶, 定期体检, 保底工资, 团建聚餐, 五险一金, 绩效奖金, 节假日加班费');
INSERT INTO `jobs` VALUES (450, '心脉', '医疗健康', '0-20人', '', '本科', '<p><strong>任职资格</strong></p><ol><li>精通Java语⾔，熟练掌握Spring Boot、Spring Cloud等主流框架。</li><li>具有微服务架构设计与实践经验，熟悉服务治理、容错机制、接口管理等关键模块。</li><li>精通MySQL和SQL Server，能够优化SQL性能并进行数据建模。</li><li>熟悉ES缓存，具备大数据情况下的快速检索缓存设计和实现方案。</li><li>熟悉医疗HIS、叫号、检查检验等医疗核心业务系统。</li><li>精通Redis，了解其在缓存、分布式锁和会话管理中的应用。</li><li>具备强烈的责任感、良好的沟通能力和团队精神，具备较强的学习能力。</li></ol><p><strong>职位描述</strong></p><p>Java工程师负责业务需求分析，并设计高可扩展性和高性能的系统技术解决方案。负责核心功能模块的代码开发、单元测试和系统优化，确保代码质量和交付效率；快速定位和解决生产环境中的技术问题，确保系统的稳定性和用户体验。</p><p><strong>工作职责</strong></p><ol><li>参与公司核心业务系统的架构设计与开发，基于Spring Boot构建高性能、可扩展的后端应用。</li><li>负责微服务架构的设计、开发与优化，主导服务拆分与接口治理，确保系统的高可用性和高并发处理能力。</li><li>负责数据库建模与SQL性能优化，精通MySQL和SQL Server，能够处理复杂查询和事务控制。</li><li>使用Redis进行缓存架构设计、分布式锁实现以及系统性能提升。</li><li>与前端团队协作，基于Vue或React框架完成前后端集成调试。</li><li>编写技术文档，参与代码评审，推动开发标准与团队技术提升。</li><li>参与系统的部署与维护，识别并解决生产环境中的技术问题，确保系统稳定运行。</li><li>熟悉LINUX操作，有医院His及相关信息化、信创和国产化中间件经验优先。</li></ol>', '5-10年', 'ac37d6dc9c15a7fd03N90tS0GFNX', '深圳 · 宝安区 · 西乡', '13-15K', 'Java, SpringCloud, MySQL, SQL Server, Spring', '中级JAVA开发工程师', 'https://www.zhipin.com/job_detail/ac37d6dc9c15a7fd03N90tS0GFNX.html', '');
INSERT INTO `jobs` VALUES (451, '常达智能', '互联网', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责核心Java应用系统的详细设计、开发迭代和日常运维工作;</li><li>参与架构设计、项目架构搭建以及相关文档编写;</li><li>持续优化代码质量，保证系统稳定性和可扩展性;</li><li>参与技术难题的攻关和预研工作;</li><li>参加项目组技术研讨会，分享新技术和开发技巧，与项目组成员共同成长6、精通AI智能体在开发上的应用，有成熟的相关应用项目落地项目经历：具备丰富的项目经历，尤其是在ERP开发、物联网、SPD项目开发等领域的项目经验者优先考虑。数据库开发：熟悉数据库开发，不仅限于MySQL、SQLServer，对常用的数据库有深入理解。项目压力：能够承受项目压力，具备解决问题和应对挑战的能力。编码习惯：具有良好的编码规范和习惯，注重代码质量和可维护性。代码管理工具：熟悉常用的代码管理工具，如Git，能够熟练使用版本控制系统。研发管理流程：了解并熟悉研发管理流程，包括需求分析、设计、开发、测试、部署和维护。部署经验：熟悉代码持续构建，熟悉Docker部署，能够独立完成应用程序的部署和配置。项目配合：能够承受项目出差及加班要求，确保项目按计划交付。</li></ol>', '5-10年', '279b826bbf7443c01Hx52tu1FVNV', '深圳 · 龙岗区 · 坂田', '12-20K', 'Java, 物联网经验, 不接受居家办公, 团队管理经验, SpringCloud, MySQL, MyBatis, Redis, SQL Server, 架构设计经验, Spring', 'Java后端开发工程师', 'https://www.zhipin.com/job_detail/279b826bbf7443c01Hx52tu1FVNV.html', '带薪年假, 节日福利, 定期体检, 员工旅游, 年终奖, 五险一金, 零食下午茶, 全勤奖');
INSERT INTO `jobs` VALUES (452, '守赋科技', '电子商务', '20-99人', '未融资', '大专', '<p>职位名称：架构师和JAVA全栈工程师，1-2名工作地点：深圳南山科技园，项目所在地薪资范围：9-18K（⼯资</p><p><strong>福利</strong></p><p>+绩效奖⾦+项⽬提成+股权分红）上班时间：大小周制 早上9:00-12:30 下午14:00-18:00</p><p><strong>岗位职责</strong></p><ol><li>商业运营沟通和产品需求分析、技术调研和架构选型⽅案设计、数据库服务器及配套设置；</li><li>前后端全栈开发编写高质量代码 、性能优化、提升用户体验，搭建和训练数据AI模型；</li><li>响应式和前瞻性迭代计划和上线运维管理、确保项目按时交付和项目高效稳定运行；</li><li>有电商平台、新媒体内容社交、即时零售、数据算法和跨境经验优先；</li><li>协同管理、运营、产品和技术团队、推行OKR和SOP标准、实现组织成长、提升执行效率。</li></ol><p><strong>任职要求</strong></p><ol><li>基础要求：●大专及以上学历，计算机、数据科学或相关专业，5年以上互联网电商、内容社交和零售行业研发经验，5年以上SaaS、小程序、APP、H5、Web项目管理和落地经验；●精通Java/Python、vue、ts、css、springboot 、mysql 等全栈开发技术，熟悉前后端开发流程、微服务、分布式架构及主流云平台（AWS/Aliyun等）；●了解数据可视化、用户旅程埋点技术，优化UI呈现和UX体验，解决多端（PC/移动/跨浏览器）交互逻辑与兼容性问题，适配不同平台交互和用户的访问习惯；●较强的学习、沟通，压力管理和解决问题的能力，拥有从0到1组建技术团队的经验，擅长敏捷开发与跨部门协作，具备千万级用户产品或交易系统管理经验。</li><li>专业优势：●熟悉主流电商和社交平台（DTC交易、UGC内容、CPS联盟、O2O本地生活、ERP物流、SCRM服务营销、BI数据中台等）的开放生态与API对接逻辑，具备多平台整合能力；●开发数据采集、清洗与分析工具，搭建用户行为分析、A/B测试等数据管道，支持业务决策；●结合前端埋点与后端数据，设计可视化看板（如Tableau、ECharts），适配规则流程（如支付流程、表单交互）3、加分项：有头部平台（阿里/京东/抖音/微信）或SaaS服务商（有赞/微盟）核心系统研发背景；主导过AI工具（如图文视频、智能客服、推荐算法、数据模型）的规模化并发应用；跨境技术架构设计布局、数据管理、电商独立站设计搭建、本地化合规运维等。公司介绍： 守赋科技公司，作为推动中国品牌DTC全渠道增长的践行者，多年来，我们携手产研、商业、营销、新媒体、电商、私域、O2O、数据智能科技等顶流实战专家，由前阿里、京东、腾讯、华为、骑士卡、怡亚通和博时基金等高管团队亲自操盘，为企业提供以用户为中心的的品牌战略、全域增长、品牌出海、数智应用等专业赋能、科技革新和品效合一的运营服务。我们立志于守护和赋能中国品牌崛起，共同打造新零售时代标杆！待遇保障：</li><li>富有竞争力的薪资待遇：根据个人能力与经验提供优厚的薪资，充分体现您的价值。</li><li>绩效奖金：依据个人及团队业绩表现发放丰厚的绩效奖金，激励您创造卓越成绩。3.</li></ol><p><strong>福利</strong></p><ol><li>带薪年假：享有法定假期及带薪年假，让您在工作之余有充足的时间休息与放松。</li><li>节日</li></ol><p><strong>福利</strong></p><ol><li>培训与发展：提供顶级专家交流机会与广阔职业发展空间，助力您不断提升自我，实现价值。</li><li>团队活动：不定期组织丰富多彩的团队建设活动，增强团队凝聚力与员工归属感。</li><li>良好的工作环境和研讨氛围，在这里你将与一群充满活力和激情的同事共同成长。期待您加入，共同定义下一代品牌增长数智引擎！</li></ol>', '5-10年', '8de94d1038af077003x62tS1EFpU', '深圳 · 南山区 · 科技园', '13-18K', 'Java, 大数据经验, 全栈工程师, 不接受居家办公, 分布式经验, SpringCloud, MySQL, 云计算经验, 搜索/推荐/广告经验, 架构设计经验, Spring, Python', '架构师和JAVA全栈工程师', 'https://www.zhipin.com/job_detail/8de94d1038af077003x62tS1EFpU.html', '交通补助, 绩效奖金, 带薪年假, 五险一金, 底薪加提成, 保底工资, 零食下午茶, 股票期权');
INSERT INTO `jobs` VALUES (453, '拓维云途科技', '计算机软件', '20-99人', '', '本科', '<p><strong>任职要求</strong></p><ol><li>计算机或相关专业本科以上学历;</li><li>6年及其以上Java开发经验,相关互联网项目经验,能够独立完成项目开发及现有项⽬⼆次开发;</li><li>精通Java多线程开发和线程池使⽤,熟练掌握分布式,缓存,消息队列MQ,搜索等技术体系;</li><li>熟悉分布式后端服务开发流程和规范,熟练掌握Spring、Mybatis等框架,熟悉Dubbo、SpringBoot等开发框架;</li><li>掌握Redis,Elasticsearch等NoSQL技术,精通MySQL的开发设计和调优;</li><li>踏实靠谱;主动性和自我驱动意识强;并能持续钻研,不断成长的同学可加分;</li><li>有交易、支付研发经验者可加分;</li><li>有业务开发测试经验可加分；</li><li>可以接受出差出差马来西亚中⽂作为工作语言出差时长3~6个月</li></ol>', '5-10年', 'e82048f9abf6955d0nFy2920FlJU', '深圳 · 福田区 · 车公庙', '15-25K·13薪', 'Java, MySQL, Spring, Oracle, 区块链经验, 金融', '高级Java开发', 'https://www.zhipin.com/job_detail/e82048f9abf6955d0nFy2920FlJU.html', '');
INSERT INTO `jobs` VALUES (454, 'I Share For Life', '医疗健康', '0-20人', '未融资', '本科', '<ol><li>熟悉敏捷开发模式，具有独立负责模块设计；独立负责APP、小程序、⽹页的设计、开发、维护经验者优先；熟悉Figma；</li><li>熟悉微服务架构，有⼤中型分布式系统设计经验，具有医疗信息化系统各功能架构设计、开发经验者优先；</li><li>熟悉数据中台，具备⼤数据系统开发的经验。【</li></ol><p><strong>岗位职责</strong></p><ol><li>参与需求分析，与设计和业务团队紧密合作；</li><li>持续优化系统性能，提升⽤户体验，保障数据安全；</li><li>关注前沿技术，推动新技术在项目中的应用。【</li></ol><p><strong>工作内容</strong></p><ol><li>负责公司核心系统技术性重构，OCR产品研发、小程序产线研发迭代，AI技术的嵌入应用；</li><li>负责系统的架构规划，构建业界优秀的系统架构，灵活应对业务变化；</li><li>推动公司系统规划更新。如产品发展路线图、业务架构、产品架构、技术架构、安全架构等框架体系的落地。【</li></ol><p><strong>任职要求</strong></p><ol><li>具备新系统规划、新系统搭建等各功能架构设计、执行落地的项目经验；</li><li>具备良好的问题解决能力，能够独立承担模块和新系统开发任务；</li><li>具有优秀的沟通能力和团队合作精神，能够快速融入团队。--《后端技术》要求1、 必须会Java, Golang和Python 至少掌握一门；</li><li>精通Java（含JSP）, 熟练掌握Golang或Python（熟悉C++可加分）；</li><li>熟悉JAVA和Golang常用后端开发框架4、熟悉PyTorch、TensorFlow、Pandas等Python常用数据科学框架5、熟悉MySQL、PostgreSQL、SQLite、OceanBase等主流数据库，熟悉Kafka、Nginx、RabbitMQ、Redis等中间件；</li><li>’熟悉敏捷开发模式，具有独立负责模块设计、开发、维护经验者优先；</li><li>熟悉信创国产工程，熟悉UOS、OpenEuler、OpenAnolis等国产操作系统；</li><li>熟悉微服务架构，有大中型分布式系统设计经验（医疗信息化经验优先）；</li><li>熟悉数据库设计和优化，具备处理大规模数据（迁移）的经验；--《前端技术》要求必须会Uniapp、小程序原生、Vue3和JSP1、熟练前端技术（精通JS（ES5/ES6）、CSS3和HTML5；</li><li>掌握Vue3全家桶；</li><li>掌握Uniapp开发混合架构APP；</li><li>掌握小程序原生开发；</li><li>具有较强的UI设计能力。</li></ol>', '5-10年', '11c57d151b7225750nR-09y1GFFS', '深圳 · 南山区 · 科技园', '18-25K', 'SpringCloud, MySQL, Python', '全栈工程师', 'https://www.zhipin.com/job_detail/11c57d151b7225750nR-09y1GFFS.html', '员工旅游, 定期体检, 五险一金, 带薪年假');
INSERT INTO `jobs` VALUES (455, '深圳市乐道智云科技', '互联网', '20-99人', '', '大专', '<p><strong>岗位职责</strong></p><ol><li>精通springboot、Springcloud微服务框架，熟练掌握MySQL/SQLServer等数据库系统，熟练使⽤redis等缓存，Rabbit MQ队列 ；</li><li>熟悉TCP/IP、Websocket、MQTT等互联⽹和物联网的主流协议；</li><li>主导技术选型、难点攻关及核心JAVA程序的开发，能独挡⼀面；</li><li>跟进整个项目开发周期，保证项目顺利运营并不断优化和创新，及时提供技术解决方案；</li><li>负责开发过程中的相关文档审核，如：计划、需求规格、设计文档等；</li><li>对接产品经理，落实项目需求，向开发团队合理分配开发工作；</li></ol><p><strong>任职要求</strong></p><ol><li>计算机相关专业，全日制专科及以上学历，5年以上技术开发经验，2年以上技术管理经验；</li><li>负责过软件系统项目的总体设计、技术研发和项目管理，熟悉软件研发过程；</li><li>精通至少2门以上计算机编程语言、web端开发，精通通用设计模式、主流的关系、非关系型数据库、缓存等中间件，及微服务架构等技术，熟悉linux及内核、操作系统原理、网络、安全等领域技术；</li><li>业务理解能力强，具有高并发项目的架构经验，掌握容量规划、架构设计、性能优化；良好的组件级建模能力，能够设计复杂业务、大数据量的系统平台；</li><li>具备极强的团队精神和合作精神，优秀的表达、协调和组织能力。</li><li>优秀的项目管理能力，精通产品规划、业务需求、产品设计、系统开发、测试演练、运维支持、文档管理全流程管理；</li><li>有工作热情，具有良好的沟通技巧和团队合作精神，能承受工作压力、适应不同环境。</li></ol><p><strong>薪资福利</strong></p><ol><li>我们提供高于行业平均水平的薪酬，高薪+绩效奖金+项目奖金+股权激励；</li><li>员工依法享受国家的法定假日，如婚假、丧假、产假、工伤假等；</li><li>在公司连续服务满一年的员工可享受5天的带薪年假；</li><li>公司入职就买五险一金；</li><li>公司注重员工身心健康，鼓励劳逸结合，定期组织篮球、羽毛球等活动，6）国家法定节假日，如端午节、中秋节都会有精美礼品发放；</li><li>每月举办生日会，并有精美礼品赠送；</li><li>公司很重视团队建设，设立了团建基金，可享受拓展、市内外旅游等；</li><li>公司每年都会组织年会、发放年终奖和开工利是；</li></ol>', '5-10年', '73be74e1651f47c50nV72tS1EFZT', '深圳 · 南山区 · 科技园', '18-30K·13薪', 'Java, Spring, Redis, MySQL, 架构设计经验, 区块链经验', 'java架构', 'https://www.zhipin.com/job_detail/73be74e1651f47c50nV72tS1EFZT.html', '餐补, 员工旅游, 年终奖, 五险一金');
INSERT INTO `jobs` VALUES (456, '小牛智讯', '计算机软件', '0-20人', '未融资', '大专', '<p><strong>岗位职责</strong></p><p>1. 参与公司核心业务系统的设计、开发与维护工作2. 负责业务模块的技术方案实施和编码实现3. 编写结构清晰、可维护的代码，参与代码审查4. 协助进行系统性能优化，参与⾼并发场景的技术⽀持5. 基于Spring Cloud微服务架构参与系统设计和开发6. 参与分布式系统架构的实现，协助保障系统稳定性7. 配合团队完成技术选型和新技术的落地应⽤8. 按照规范编写技术文档9. 使用Docker参与应⽤容器化部署10. 参与Linux环境下的应用部署和日常运维</p><p><strong>技术要求</strong></p><p>1. 3-5年Java开发经验，熟悉JVM原理、多线程编程2. 掌握常用设计模式，具备面向对象编程能力3. 熟悉Java主流开发框架和工具4. 熟练掌握Spring Boot框架并有实际项目经验5. 熟悉Spring Cloud微服务架构及相关组件使用6. 掌握MySQL数据库设计和开发，了解性能优化7. 具备基本的SQL优化能力8. 熟练使用Docker进行应用部署9. 熟悉Linux系统，掌握常用命令和脚本编写10. 具备良好的团队协作和沟通能力11. 有较强的问题分析和解决能力备注：需在公司驻场，不接受远程具备以下经验者优先：- 有进销存系统开发经验- 有智慧食安相关项目经验</p>', '5-10年', '645d6d2a35bd893e0nF_39i-EVNU', '深圳 · 龙华区 · 观澜', '10-12K', 'Java, Spring, MySQL, Redis, 物联网经验, MES开发经验, 不接受居家办公', 'Java-短期', 'https://www.zhipin.com/job_detail/645d6d2a35bd893e0nF_39i-EVNU.html', '五险一金, 团建聚餐, 免费工装, 带薪年假, 节日福利');
INSERT INTO `jobs` VALUES (457, '杰诺科技', '企业服务', '100-499人', 'A轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责金蝶云苍穹平台（供应链、制造、财务、项目等模块）的定制化开发、架构设计与性能调优，交付高可用、⾼性能的企业级解决⽅案。</li><li>参与业务需求分析，主导技术⽅案设计、核心代码开发与数据库优化，编写高质量的技术⽂档与接口规范。</li><li>独立负责系统部署、监控与运维保障，熟练使用Linux、Docker、K8s及CI/CD工具链，制定并实施自动化部署、监控告警与故障应急方案。</li><li>深入分析系统性能瓶颈，主导生产环境的问题排查、性能优化与容量规划，确保系统稳定、高效运行。</li><li>积极引入AI编码助手（如Claude Code、CodeArts、通义灵码、Copilot）等效能工具，提升开发、测试与重构效率，推动团队工程实践升级。</li></ol><p><strong>任职要求</strong></p><ol><li>全日制本科及以上学历，计算机、软件工程等相关专业，5年及以上Java开发经验。</li><li>精通Spring Boot/Cloud、MyBatis等主流框架，深入理解微服务架构、分布式系统设计及高并发调优。</li><li>具备金蝶云苍穹平台实战经验，熟悉其底层架构、扩展机制与模块开发流程，能独立完成复杂业务模块或自定义组件的开发。</li><li>熟练使用MySQL/PostgreSQL/Oracle等关系数据库，具备SQL优化、索引设计与分库分表经验；熟悉Redis、Kafka、RabbitMQ等中间件。</li><li>具备较强的Linux运维能力，熟练使用Shell脚本、Docker、Jenkins、K8s，掌握CI/CD流水线设计与自动化运维，能独立保障生产环境稳定。</li><li>有AI编码工具使用经验，能将其融入日常开发，提升代码质量与交付效率。</li><li>责任心强，具备良好的系统思维、问题分析与项目交付能力，有制造、供应链、ERP等行业背景者优先。我们提供​：</li><li>竞争力薪酬：月薪 + 补贴 + 绩效奖金 + 项目提成 + 股权激励（核心岗位）。</li><li>多元发展：提供“技术专家→架构师”或“技术管理→项目总监”双通道晋升路径。</li><li>优质平台：参与行业标杆级项目，接触前沿技术体系与优质客户资源。</li><li>成长型团队：扁平化管理、技术分享文化、定期外部培训，与优秀伙伴共同成长。</li></ol>', '5-10年', 'ef2e0c79d33682d30nd83dW1GVRQ', '深圳', '17-25K·14薪', 'Java, Docker, 微服务经验, PostgreSQL, SpringCloud, MySQL, Redis, Dubbo, 架构设计经验, Spring', '高级Java开发工程师（金蝶云苍穹方向）', 'https://www.zhipin.com/job_detail/ef2e0c79d33682d30nd83dW1GVRQ.html', '股票期权, 意外险, 定期体检, 五险一金, 零食下午茶, 年终奖, 交通补助, 生日福利, 节日福利, 员工旅游, 带薪年假');
INSERT INTO `jobs` VALUES (458, '内蒙古猛犸国际物流', '跨境物流', '100-499人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><p>1. 负责商城类、⼆⼿车类平台的软件开发与维护2. 参与系统设计，改进技术架构3. 编写⾼质量的代码并对已有代码进行优化4. 协助团队成员解决技术难题5. 持续跟进Java领域的新技术</p><p><strong>任职要求</strong></p><p>1. 具备扎实的Java编程基础与实践经验2. 熟练掌握Java开发框架和工具3. 能够独⽴分析和解决问题4. 良好的团队合作能力和沟通技巧5. 对新技术有持续学习的意愿和能力6.5年以上物流行业经验</p>', '5-10年', 'cb45b3a4afa861c70nJ429i6F1FW', '深圳 · 龙岗区 · 坂田', '15-20K', 'Java, Spring, SpringCloud, MySQL, Redis, 微服务经验, ERP开发经验, 不接受居家办公', '高级全栈开发工程师', 'https://www.zhipin.com/job_detail/cb45b3a4afa861c70nJ429i6F1FW.html', '生日福利, 五险一金, 节日福利, 零食下午茶, 免费工装, 餐补, 团建聚餐, 包吃, 交通补助, 带薪年假, 年终奖, 定期体检, 员工旅游');
INSERT INTO `jobs` VALUES (459, '安侣医学', '医疗器械', '100-499人', 'B轮', '本科', '<p>【</p><p><strong>岗位职责</strong></p><ol><li>负责公司核心业务系统（前端 + 后端 + 数据库）的设计、开发、单元测试、部署与日常维护，按时保质交付产品需求。</li><li>负责编写技术方案、接口设计文档、数据库设计⽂档及代码规范⽂档，承担关键模块的技术评审与代码 Review。</li><li>配合产品经理进⾏需求分析与系统设计，输出技术实现方案、工作量评估及可⾏性分析。</li><li>负责技术调研、难点攻关，跟踪业界前沿技术，持续优化系统架构、性能与可扩展性。</li><li>编写并维护技术文档、用户使用手册及运维手册，沉淀团队技术资产。</li><li>配合测试团队完成功能与性能测试，配合运维团队完成产品发布、监控部署与故障应急响应。【</li></ol><p><strong>任职要求</strong></p><ol><li>学历：统招本科及以上学历，计算机科学与技术、软件工程、信息管理与信息系统、通信工程等相关专业。</li><li>经验：5年以上软件开发经验，其中至少3 年以上全栈开发经验。</li><li>必须具备 IVD（体外诊断）行业开发经验，熟悉体外诊断试剂/仪器的研发、生产、流通或使用环节的信息化需求。</li><li>有医疗信息化（HIPAA / 等保）、SaaS 平台或大型企业级应用开发经验者优先。</li><li>熟悉前后端开发技术栈及常用开发框架，熟悉数据库设计、SQL 优化、缓存策略，熟悉常用设计模式与软件工程方法论，了解 DevOps、CI/CD、敏捷开发流程。</li><li>后端：熟练掌握 Java（Spring Boot）/ Python（Django、Flask）/ Node.js（Express、Koa）/ Go 至少一种；具备 RESTful API、微服务架构设计与开发能力。</li><li>前端：熟练掌握 React / Vue / Angular 至少一种；熟悉 HTML5 / CSS3 / JavaScript（ES6+）/ TypeScript；熟悉 Webpack / Vite 等构建工具。</li><li>数据库：熟悉 MySQL / PostgreSQL 关系型数据库；熟悉 Redis / MongoDB 等 NoSQL。</li><li>中间件与运维：熟悉 Kafka / RabbitMQ 消息队列、Nginx 反向代理与负载均衡；熟悉Linux、Docker、Kubernetes、Jenkins / GitLab CI 等持续集成工具。</li><li>版本管理：熟练使用 Git 及常用协作流程（Git Flow）。</li><li>IVD 行业知识：熟悉 IVD（体外诊断）业务全流程。</li><li>加分项：了解 HL7、FHIR 等医疗数据互通标准；熟悉等保 / HIPAA / GDPR 合规要求；有开源项目贡献或技术社区影响力。</li><li>素质：具备良好的沟通协作能力与团队合作精神；对代码质量与系统稳定性有高要求；能适应多项目并行与紧急故障处理；对新技术保持敏感，能主动沉淀与分享；具备严谨的问题分析与抽象建模能力。【备注】：软件工程师有多个不同方向或全方向岗位，具体依据人选专业技能经验背景具体沟通适配和定薪；薪资除了12个月的固定月薪外，另外3薪为基数的年度浮动绩效奖金、额外项目奖金依据个人贡献度、参与度和绩效结果另计。</li></ol>', '5-10年', '7b04de4122110d430nFy2ty6EFtZ', '深圳 · 宝安区 · 西乡', '15-25K·15薪', 'Java, C++, Python, Golang, Spring, MySQL, Redis, 架构设计经验, 分布式经验, 微服务经验, 不接受居家办公, 全栈, 医疗器械, IVD', '全栈工程师', 'https://www.zhipin.com/job_detail/7b04de4122110d430nFy2ty6EFtZ.html', '团建聚餐, 外部培训, 五险一金, 高温补贴, 免费工装, 节日福利, 零食下午茶, 带薪年假, 绩效奖金, 工龄奖, 员工旅游, 意外险, 员工旅游, 年终奖, 生日福利, 股票期权, 定期体检');
INSERT INTO `jobs` VALUES (460, '上海谦莲科技有限公司', '企业服务', '0-20人', 'A轮', '本科', '<p><strong>岗位职责</strong></p><p>1.负责租赁系统核⼼功能模块的开发、测试与部署2.编写⾼质量、可维护的代码，完成代码审查和⾃测3.优化系统性能，保证系统稳定性与可扩展性4.协助解决生产环境中的技术问题5.参与系统架构设计和技术方案评审</p><p><strong>任职要求</strong></p><p>1.3-5年Java开发经验，扎实的Java基础2.熟练掌握Spring、Spring Boot、MyBatis等主流框架3.熟悉MySQL等关系型数据库，具备SQL优化经验4.了解Redis、MQ等中间件使⽤5. 掌握Linux基本操作命令6. 具备良好的面向对象编程思想和设计模式应用能力</p>', '5-10年', 'd80eba8e9fa28afc0nF939--GVtX', '深圳 · 福田区 · 上步', '15-20K', 'Java, SpringCloud, MySQL, 架构设计经验, Spring', 'java开发工程师(电商经验优先)', 'https://www.zhipin.com/job_detail/d80eba8e9fa28afc0nF939--GVtX.html', '五险一金');
INSERT INTO `jobs` VALUES (461, '上海恒格信息', '互联网金融', '100-499人', '不需要融资', '大专', '<ol><li>本料5年以上或专科7 年以上计算机、信息管理相关专业优先。</li><li>具备分布式系统开发和设计经验，熟悉缓存，消息、服务治理、容灾、分布式一致性等机制；</li><li>有扎实的 JAVA 基础，熟悉IO、多线程、集合，熟练使用 spring 框架进行編程；</li><li>熟悉dubbo 、redis、mongo 使用⽅法5、熟悉mysql、oracle、tdsal数据库使⽤，并能熟练进⾏表设计和SQL 优化；</li><li>熟悉常用的开源框架．对开源框架源码有研究，熟练运用 git，参与过银⾏贷款项目尤佳；</li><li>具有较强的学可能力，沟通协调能力，强烈的责住心、工作踏实，善开总结以及交档編写能力；</li><li>具备良好的分析解决向题能力，具有业务需求分析能力，责任感强、爱思考、沟通能力和抗压能力．能与各种背景人员合作；产品设计能力：理解用户体验，能够设计出满足用户需求的产品。</li></ol>', '5-10年', 'b9ef01d58c90051d0nB83dW5GFNY', '深圳 · 罗湖区 · 东门', '10-12K', 'Java, Nginx, Hibernate, SpringCloud, MySQL, MyBatis, Redis, MongoDB, Spring, Oracle, HBase', 'Java（平安银行）', 'https://www.zhipin.com/job_detail/b9ef01d58c90051d0nB83dW5GFNY.html', '定期体检, 带薪年假, 五险一金, 股票期权, 免费班车, 节日福利');
INSERT INTO `jobs` VALUES (462, '协卓软件', '计算机软件', '100-499人', '未融资', '本科', '<p><strong>一、工作内容</strong></p><ol><li>深入理解Web及移动APP软件系统的业务需求，制定软件开发整体框架；</li><li>开发和维护系统平台与框架，开发包含前后端的系统，发现和解决存在的技术问题；</li><li>持续改进流量调度平台的可用性、稳定性、安全性和扩展性；</li><li>持续优化前端和后端功能，提升流量调度平台和服务⽹关；⼆、能⼒要求：</li><li>计算机或软件工程等相关专业，专科及以上学历，2年以上全栈开发经验；</li><li>编程经验丰富，熟练掌握Python、Java等，熟悉 Linux、Spring、Mysql、Mybatis等框架；</li><li>具备系统调优、性能调优等技能，对疑难技术问题具备较强的排查能力者优先；</li><li>熟悉分布式系统的设计和应⽤，熟悉分布式、缓存、消息等机制；能对分布式常用技术进行合理应用，解决问题；</li><li>高并发分布式计算或海量数据应用经验者优先，有大型网站构建经验者优先；</li><li>在业界有创新性技术沉淀，github负责的类库或框架star超过500以上优先；</li><li>产品面向国际化业务，熟练掌握英语阅读和口语特别优先。</li></ol>', '5-10年', '5c20029eee0cb96103xy2Ny4ElpQ', '深圳 · 宝安区 · 西乡', '13-15K', '不接受居家办公, C, 分布式经验, SpringCloud, SQL Server, 架构设计经验, SRM', '全栈java开发工程师', 'https://www.zhipin.com/job_detail/5c20029eee0cb96103xy2Ny4ElpQ.html', '五险一金, 定期体检, 加班补助, 全勤奖');
INSERT INTO `jobs` VALUES (463, '神通天下', '其他新能源', '100-499人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>全栈开发执行：参与公司核心业务系统（如ToB管理平台、数据服务中台）的端到端开发，包括：后端：基于Java技术栈（如Spring Boot/Spring Cloud）完成业务逻辑开发、数据库设计（MySQL/PostgreSQL）、API接口设计与实现（RESTful/gRPC）、微服务模块拆分与集成；前端：使用React/Vue等框架开发用户界⾯，实现交互逻辑、数据可视化（如ECharts），对接后端API完成前后端联调；全链路协作：参与需求评审、技术⽅案设计（含架构草图），配合测试团队完成功能验证与线上问题修复。</li><li>AI⼯具提效：主动运用AI编程助手（如Cursor、GitHub Copilot）​ 优化开发流程，包括但不限于：通过AI⽣成基础代码框架、单元测试用例、接口文档注释利用AI辅助排查逻辑漏洞、优化性能瓶颈（如SQL查询、循环效率）；沉淀AI工具使用经验，推动团队共享最佳实践。</li><li>技术迭代与维护：负责所开发模块的日常维护、版本迭代，响应业务需求变更，保障系统稳定性与可扩展性。</li><li>有架构思维的优先</li></ol>', '5-10年', '75c67fef23d4a1540nB93tu_FFFY', '深圳', '12-24K', 'Java, Nginx, 大数据经验, Tomcat, PostgreSQL, SpringCloud, MySQL, MyBatis, SQL Server, Spring, Oracle', 'Java全栈工程师', 'https://www.zhipin.com/job_detail/75c67fef23d4a1540nB93tu_FFFY.html', '绩效奖金, 有无线网, 夜班补助, 节日福利, 年终奖, 补充医疗保险, 工龄奖, 保底工资, 股票期权, 餐补, 团建聚餐, 底薪加提成, 意外险, 定期体检, 宿舍有空调, 带薪年假, 零食下午茶, 全勤奖, 员工旅游, 五险一金');
INSERT INTO `jobs` VALUES (464, '深圳晨昏线科技', '人工智能', '100-499人', '天使轮', '本科', '<p>⼀，岗boss位</p><p><strong>职责</strong></p><p>负责多机异构平台业务代码开发⼆，</p><p><strong>任职要求</strong></p><p><strong>技术要求</strong></p><ol><li>熟悉java相关框架，spring,mybatis,springboot,springcloud等2.熟悉通⽤关系型数据库mysql,pgsql,oracle，及非关系型数据库mongodb等，并且具有sql调优经验3.熟悉http协议，https协议及相关安全算法4.熟悉通用中间件redis,rocketmq,es等5.熟悉liunx基础命令，k8s使⽤6.熟悉软件开发过程，包括但不仅限于计划管理，过程管理，目标管理，风险管理等条件要求：</li><li>计算机相关专业2.5年及以上IT一线编码工作经验3.本科211学历及以上4.有AI算法开发经验，agent开发经验优先</li></ol>', '5-10年', '72de9f0102c3eee80nF_0tm_GFZT', '深圳 · 福田区 · 石厦', '15-25K·13薪', 'Java, Python, Spring, MyBatis, SpringCloud', 'Agent开发工程师', 'https://www.zhipin.com/job_detail/72de9f0102c3eee80nF_0tm_GFZT.html', '员工旅游, 定期体检, 节日福利, 保底工资, 生日福利, 零食下午茶, 有无线网, 五险一金, 加班补助, 年终奖, 底薪加提成, 股票期权, 节假日加班费, 团建聚餐, 带薪年假, 绩效奖金');
INSERT INTO `jobs` VALUES (465, '合肥景彦科技有限公司', '环保', '100-499人', '', '大专', '<ol><li>计算机科学与技术、软件工程或相关专业；</li><li>具备扎实的JAVA开发技能。二、技术能力：</li><li>精通JAVA开发，具备扎实的编程功底；</li><li>熟悉微服务架构、分布式架构设计与实现；</li><li>精通数据库脚本编写及SQL调优；</li><li>熟悉groovy语⾔及相关开发经验者优先。三、业务能⼒：</li><li>熟悉车险业务流程及技术特点者优先；</li><li>具备优秀的分析问题和解决问题的能⼒。</li></ol><p><strong>四、综合素质</strong></p><ol><li>具备强烈的责任心和高效的执⾏力；</li><li>具备良好的沟通能力和团队协作精神；</li><li>具备较强的学习能力和抗压能力；</li><li>能够适应快速变化的工作环境和新的挑战。需要有完整项目项目经验</li></ol><p><strong>岗位要求</strong></p><ol><li>5年以上Java开发经验，精通主流开发框架、数据库。</li><li>了解信创技术栈，掌握Linux常用操作，沟通能力及问题排查能力强，能适应项目节奏。</li><li>有国产化改造、保险系统开发经验者优先。</li></ol>', '5-10年', 'bbdd83a7af078ae00nFz2Nq9EVtY', '深圳 · 罗湖区 · 东湖', '10-12K', 'Java, MySQL, Redis, Spring', '中高级Java开发（太平）', 'https://www.zhipin.com/job_detail/bbdd83a7af078ae00nFz2Nq9EVtY.html', '');
INSERT INTO `jobs` VALUES (466, '新锋龙', '计算机硬件', '20-99人', '', '本科', '<p>【</p><p><strong>岗位职责</strong></p><ol><li>负责泛微 E10（Ecology10）系统的定制化开发工作，包含工作流、表单、门户、集成接口等核⼼模块的设计与编码交付。</li><li>负责⾦蝶ERP的开发和运维⼯作，包含BOS表单、流程、报表及插件的二次开发与定制化扩展。</li><li>负责公司现有系统的功能迭代优化、故障排查与性能调优，解决开发及运行过程中的技术问题，保障系统稳定运⾏。</li><li>根据用户需求完成需求分析、方案设计，配合实施团队完成系统功能开发、测试与上线部署，保障项目按期交付。</li><li>负责与第三方业务系统（OA、ERP、PLM、MES、HR 等系统）的接口集成开发，支撑企业一体化信息建设。【</li></ol><p><strong>职位要求</strong></p><ol><li>经验与基础：5年及以上Java后端开发经验，具备扎实的Java基础，精通Spring、Spring boot、Spring Cloud、JVM、多线程等，有丰富的系统性能调优经验。</li><li>精通泛微E10核心模块：流程引擎、表单建模、逻辑控制、接口集成中心、门户、移动平台开发工作。</li><li>深入理解ERP业务逻辑，可独立完成金蝶ERP（BOS）进行表单、流程、报表及插件的二次开发与定制化扩展。</li><li>熟练 数据库Oracle、MySQL/SQL Server，掌握 SQL 编写与优化、存储过程、数据备份、数据迁移。</li><li>了解 Linux命令、Tomcat/Nginx、中间件配置与调优。</li></ol>', '5-10年', '7cded48c85ec6b510nJ73dW_E1pY', '深圳 · 南山区 · 科技园', '15-25K', '', '高级系统开发工程师', 'https://www.zhipin.com/job_detail/7cded48c85ec6b510nJ73dW_E1pY.html', '交通补助, 定期体检, 节假日加班费, 节日福利, 零食下午茶, 员工旅游, 底薪加提成, 加班补助, 保底工资, 股票期权, 夜班补助, 团建聚餐, 年终奖, 夜班补助, 定期体检, 底薪加提成, 餐补, 加班补助, 带薪年假, 五险一金, 五险一金, 住房补贴, 意外险, 保底工资, 法定节假日三薪, 补充医疗保险, 法定节假日三薪, 意外险, 节假日加班费, 股票期权, 年终奖, 补充医疗保险');
INSERT INTO `jobs` VALUES (467, '怡和祥云', '移动互联网', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责公司核心业务系统的后端开发与维护工作；</li><li>参与系统架构设计，优化现有系统性能，提升系统稳定性与可扩展性；</li><li>与团队紧密合作，共同解决技术难题，推动技术预研和新技术落地；</li><li>持续改进代码质量和开发流程，提升团队整体开发效率。</li></ol><p><strong>任职要求</strong></p><ol><li>精通Java编程语言，具备良好的面向对象编程思想；</li><li>熟悉常用的设计模式，有大型分布式系统开发经验者优先；</li><li>掌握Spring、MyBatis等主流Java框架，了解微服务架构；</li><li>具备良好的团队协作精神，优秀的沟通能力和问题解决能力。</li></ol>', '5-10年', '81e7685f654d45b303x93tq8EldY', '深圳 · 福田区 · 石厦', '18-25K', 'Java, SpringCloud, Spring, MySQL, 架构设计经验, 物联网经验, 不接受居家办公', '高级java后端开发工程师', 'https://www.zhipin.com/job_detail/81e7685f654d45b303x93tq8EldY.html', '节日福利, 加班补助, 零食下午茶, 带薪年假, 五险一金');
INSERT INTO `jobs` VALUES (468, '京威电子', '电子商务', '20-99人', '未融资', '本科', '<p>跨境电商智能业务管理系统 资深后端工程师</p><p><strong>职位亮点</strong></p><p>核心战略岗 主导全公司数字化 AI 化升级 | 跨境电商黄金赛道 精品大卖稳定现⾦流 | 技术话语权拉满 从 0 到 1 搭建核⼼系统 | 年度调薪 + 年度奖⾦</p><p><strong>岗位职责</strong></p><ol><li>深度调研梳理公司跨境电商全链路业务流程（覆盖平台运营、供应链采购、物流仓储、财务合规、客服管理、数据风控等全部门），输出全业务数字化、AI 化整体解决方案，主导搭建公司⼀体化、系统化、模块化的智能 AI 业务管理系统。</li><li>负责核心系统的后端架构设计、技术选型、核心模块开发与迭代优化，搭建高可用、高扩展性、高安全性的分布式架构，支撑公司多平台、多店铺、多区域的业务规模化增长。</li><li>负责全链路系统对接与数据互通落地，完成与飞书开放平台、主流跨境电商 ERP（积加 / 领星 / 店小秘等）、全球主流电商平台（亚马逊 / Temu / 速卖通 / Shopee/Lazada 等）、紫鸟浏览器、支付系统、财税管理系统等第三方平台 / 工具的接口开发、流程联动与数据打通。</li><li>主导 AI 能力在业务系统中的深度落地，结合大模型技术、RPA 自动化能力，搭建业务场景化 AI 模块（智能运营、智能风控、智能财务、智能供应链、智能客服等），实现全业务流程的 AI 化提效与自动化闭环。</li><li>负责系统数据库设计、接口规范制定、全流程技术文档编写，持续开展数据库优化、接口性能调优、线上故障应急排查与根因解决，保障系统 7×24 小时稳定高效运行。</li><li>协同各业务部门、IT 团队，推动数字化系统的落地推广、使用培训与持续优化，建立标准化的系统运维与迭代流程，全面提升全公司数字化运营效率与业务协同能力。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机、软件工程、电子信息等相关专业，5 年及以上软件后端开发全职工作经验，3 年及以上跨境电商行业数字化系统相关开发经验，有从 0 到 1 搭建企业级业务管理系统的完整成功案例。</li><li>精通 Java/Go 等主流后端开发语言，熟练掌握 SpringCloud/SpringBoot、Gin 等微服务开发框架，具备扎实的分布式、高并发、高可用系统架构设计与落地能力，有模块化系统搭建的成熟经验。</li><li>深度熟悉跨境电商全链路业务场景，精通跨境电商全生态工具的接口对接：包括但不限于飞书开放平台、跨境电商主流 ERP、全球主流电商平台开放 API、紫鸟浏览器 API、财税管理系统等，有相关对接落地经验者优先。</li><li>具备极强的业务流程梳理与技术转化能力，能独立完成跨部门业务需求调研、需求拆解、技术方案设计，精准识别业务痛点并通过系统化、数字化、AI 化方案解决。</li><li>熟练掌握 MySQL/PostgreSQL 等关系型数据库，具备优秀的数据库设计、SQL 优化、事务处理能力；熟练掌握 Redis 缓存、Kafka/RabbitMQ 消息队列等主流中间件，熟悉 Docker/K8s 容器化部署，具备完善的线上问题排查与性能调优能力。</li><li>有 AI 大模型应用开发、业务场景 AI 化落地、RPA 自动化流程搭建相关经验，能将 AI 技术与跨境电商业务流程深度结合，实现业务提效与智能化升级。</li><li>具备良好的编码规范、逻辑思维能力、跨部门沟通协作能力与项目推动能力，有强烈的责任心与 Owner 意识，能独立主导项目全流程落地，主动解决业务核心痛点。 加分项 1. 有跨境电商企业全链路数字化、一体化管理系统从 0 到 1 完整搭建经验者优先。</li><li>有 AI Agent、大模型在跨境电商运营、财税合规、供应链管理等场景的落地实践经验者优先。</li><li>熟悉跨境电商多平台多店铺运营、海外仓管理、财税合规、知识产权风控等核心业务逻辑者优先。</li><li>有飞书应用搭建、低代码平台开发、企业级 OA/ERP 系统定制化开发经验者优先。</li><li>具备系统架构师能力、技术团队管理经验，或有中大型企业数字化转型项目经验者优先。</li><li>有开源项目贡献、个人技术博客 / 技术社区输出者优先。</li></ol>', '5-10年', '22cf753788dfda5f0nV-0tm9EFVY', '深圳 · 龙华区 · 油松', '8-12K', 'Java, 分布式经验, Docker, SpringCloud, MySQL, Redis, 云计算经验, SQL Server, Spark, 架构设计经验, Spring, HBase', '后端系统开发工程师', 'https://www.zhipin.com/job_detail/22cf753788dfda5f0nV-0tm9EFVY.html', '年终奖, 团建聚餐, 餐补, 提供中餐晚餐, 员工旅游, 免费工装, 工龄奖, 带薪年假, 包吃, 节日福利, 五险, 有无线网, 底薪加提成, 全勤奖, 定期体检, 保底工资, 生日福利, 零食下午茶, 绩效奖金, 五险一金');
INSERT INTO `jobs` VALUES (469, '语利声', '互联网', '100-499人', 'A轮', '本科', '<p>薪资待遇：最高18K，面试根据经验能力定薪，，入职五险⼀⾦</p><p><strong>岗位职责</strong></p><p>负责线下收银系统后端开发业务迭代开发，系统技术架构升级等</p><p><strong>任职资格</strong></p><ol><li>数据库：熟练使用MySQL/MSSQL/Oracle，了解NoSQL（如MongoDB）。</li><li>中间件：熟悉消息队列（Kafka/RabbitMQ）、缓存（Redis）、搜索引擎（Elasticsearch）。</li><li>⼯具与平台：熟悉Git、Maven、Jenkins、Linux命令，了解云服务（AWS/Aliyun）。软技能：逻辑清晰，具备团队协作和沟通能力，能独立解决问题。</li></ol>', '5-10年', '4b5a21fc81f033590nJ42Nm-EVFY', '深圳 · 福田区 · 香蜜湖', '17-18K', 'Java, MySQL, Redis, Spring, 双休', '收银系统Java后端（2人）', 'https://www.zhipin.com/job_detail/4b5a21fc81f033590nJ42Nm-EVFY.html', '五险一金, 带薪年假, 绩效奖金, 节日福利, 年终奖, 生日福利, 法定节假日三薪, 夜班补助, 全勤奖');
INSERT INTO `jobs` VALUES (470, '康索特软件', '计算机软件', '20-99人', '未融资', '本科', '<ol><li>全栈开发与优化:负责公司产品的前后端开发，包括Web应用、移动端的设计与实现。提升产品的稳定性和可扩展性。</li><li>技术架构设计与创新:参与技术架构的设计与迭代，制定符合客户业务需求的技术方案。探索并引入前沿技术，拥抱AI，使用AI⼯具，推动公司技术创新和发展。</li><li>团队协作与技术⽀持:与产品经理、测试团队紧密合作，指导开发⼈员工作，确保项目按时⾼质量交付，提升团队整体技术能力。</li><li>文档编写与知识分享:为团队提供技术支持，解决开发过程中的技术难题。编写高质量的技术文档，包括设计文档、接口文档及开发指南。定期组织技术分享，推动团队技术水平的提升。【</li></ol><p><strong>任职要求</strong></p><ol><li>熟悉Java，Springboot，SpringCloud微服务等后端技术，熟悉Redis缓存，熟悉MySQL；</li><li>了解CSS，HTML，JS，TS，使用 Vue.js ，Element等框架开发 Web 应用；</li><li>熟悉linux系统和相关指令，熟悉Docker；</li><li>认真细心，良好的沟通协作能力，遇事积极主动；</li><li>拥抱AI，熟悉AI工具，使用AI提高工作效率；</li></ol>', '5-10年', 'e7a36c6078b680020nJ52ty1EVpX', '深圳', '16-20K', 'Java, Spring, SpringCloud, MySQL, Redis, 架构设计经验, 团队管理经验, 物联网经验, 分布式经验, 微服务经验', '高级开发工程师', 'https://www.zhipin.com/job_detail/e7a36c6078b680020nJ52ty1EVpX.html', '员工旅游, 零食下午茶, 补充医疗保险, 加班补助, 生日福利, 节日福利, 通讯补贴, 双休, 保底工资, 年终奖, 团建聚餐, 定期体检, 底薪加提成, 意外险, 五险一金, 带薪年假, 绩效奖金');
INSERT INTO `jobs` VALUES (471, '甄才智能', '人工智能', '0-20人', '', '本科', '<p><strong>岗位职责</strong></p><p>1. 负责Java相关系统的设计、开发和维护 2. 参与技术方案讨论并推动落地实施</p><p><strong>任职要求</strong></p><ol><li>熟悉Java编程语言，具备良好的编码习惯</li><li>能够独立完成模块开发任务</li><li>具备基本的问题分析与解决能力</li></ol>', '5-10年', '4e48bb8a83d1dd9e0ndy39q0F1FY', '深圳 · 南山区 · 科技园', '19-30K', 'Java, Spring, SpringCloud, MyBatis, JVM, MySQL, Oracle, 分布式经验, 微服务经验', 'Java', 'https://www.zhipin.com/job_detail/4e48bb8a83d1dd9e0ndy39q0F1FY.html', '五险一金');
INSERT INTO `jobs` VALUES (472, '幻彩潮玩', '其他消费品', '100-499人', '不需要融资', '本科', '<p>##</p><p><strong>岗位职责</strong></p><p>1. 负责潮玩/盲盒抽奖系统后端服务设计、开发、优化（PHP+Java）2. 支撑大促、新品限量发售、限时抽赏**等高并发场景，保证不宕机、不超卖、公平安全3. 设计实现抽奖概率、防刷风控、库存锁单、支付/退款/对账核⼼逻辑4. 优化 MySQL/Redis 性能、分库分表、分布式锁、消息队列、服务限流降级5. 与前端/产品协作，接口设计、联调、⽂档输出；负责线上问题排查与稳定性保障6. 代码 Review、技术沉淀、组件化/服务化改造，提升团队开发效率---##</p><p><strong>任职要求</strong></p><p>1. 3–5年+ 后端开发经验，本科及以上，计算机相关专业优先2. 精通 PHP/ Java ，熟悉常⽤框架（SpringCloud、Laravel等）3. 熟练 MySQL、Redis，懂索引优化、事务、缓存、分布式锁、消息队列（MQ）4. 有高并发、电商、抽奖、盲盒、营销活动、库存/订单/支付**经验优先5. 熟悉防作弊、风控、概率算法、超卖解决**⽅案，逻辑严谨、重视安全6. 良好系统设计能力，能独立负责核心模块从0到1落地--## 加分项（潮玩公司加分）- 做过盲盒/抽赏/一番赏/潮玩小程序**后端- 熟悉微信/支付宝支付、退款、对账流程- 微服务、云原生、Docker/K8s、CI/CD 实践- 懂一点前端/全栈，能快速理解交互与业务---薪资：视能力可谈）- 弹性工作、平时不加班 偶尔需要根据项目加班</p>', '5-10年', '614c3ebf72faa3190nd529i_FlNZ', '深圳 · 南山区 · 科技园', '15-25K', 'Java, PHP, MySQL, 架构设计经验', '高级后端研发工程师', 'https://www.zhipin.com/job_detail/614c3ebf72faa3190nd529i_FlNZ.html', '节日福利, 零食下午茶');
INSERT INTO `jobs` VALUES (473, '深圳市心智未来科技', '互联网', '0-20人', 'A轮', '本科', '<p><strong>招聘要求</strong></p><ol><li>5年以上实际开发经验，计算机基础扎实，熟练掌握HTTP、tcp/IP基础知识；</li><li>精通 JAVA 语言，熟悉 JVM 机制，熟练掌握多线程/IO与网络编程，有netty开发经验优先；</li><li>精通 SQL 语言，熟悉MySQL、PostgreSQL 、Redis、milvus、Elasticsearch等常见关系数据库及向量数据库的开发；</li><li>熟悉常用的java开发框架，包括但不限于Spring Boot，spring cloud、Dubbo及常见的分布式中间件开发；</li><li>熟悉javaScript，TypeScript语言，能熟练使用Vue框架开发；</li><li>熟悉AI生态知识及应用开发，有NLP、大模型部署、微调、训练、AI Agent开发等相关经验(特别是spring AI)优先；</li><li>了解机器学习算法与深度学习算法开发流程，了解Python基础编程，会python开发优先；</li><li>有过深度学习、强化学习、自然语义、数据挖掘、海量数据处理和并行计算应用经验者优先9. 有良好的编码规范和设计思想，具有技术突破攻关及独立工作的能力、较好的学习能力、沟通能力，工作负责，能承受一定的压力，对AI行业有浓厚的兴趣；</li><li>熟悉 Nginx、Tomcat 等 Web 应用服务，有 Linux 开发部署经验，有CI/CD，Docker经验优先；</li><li>具备一定的英文资料阅读和理解能力优先。</li></ol><p><strong>工作职责</strong></p><ol><li>参与AI模型的安全测评及平台开发；</li><li>负责产品的开发、测试、部署和集成；</li><li>参与需求分析，撰写相关技术文档及项目实施；</li><li>研究相关新技术，并努力提升项目研发的效率和质量；</li><li>支持公司相关产品在机器学习领域的研究；</li><li>与其它部门或岗位的工作协调，配合完成与本部门相关的工作。</li></ol>', '5-10年', '64858fc0291c30961Hx529S5GVtR', '深圳 · 南山区 · 科技园', '15-20K', 'Java, 大数据经验, 不接受居家办公, 分布式经验, 微服务经验, PostgreSQL, SpringCloud, MySQL, Kafka, Redis, Dubbo', 'java开发工程师', 'https://www.zhipin.com/job_detail/64858fc0291c30961Hx529S5GVtR.html', '团建聚餐, 年终奖, 五险一金');
INSERT INTO `jobs` VALUES (474, '深圳CA', '计算机软件', '100-499人', '未融资', '本科', '<p><strong>一、岗位职责</strong></p><ol><li>参与 CA数字证书平台（CA/RA）与PKI基础设施系统的架构设计与研发。</li><li>负责以下核心安全服务模块开发：证书签发系统（CA） SSL网关、ACME系统平台。</li><li>参与 电子签名、电⼦签章、数字⾝份认证系统研发。</li><li>负责 密码设备（HSM、PCI密码卡等）接口集成与安全封装。</li><li>实现以下密码算法在业务系统中的安全应⽤：国密算法（SM2 / SM3 / SM4）、国际算法（RSA / ECC）、抗量子密码算法（PQC）6. 参与 TLS / GMSSL 安全通信体系设计与实现。</li><li>参与密码产品研发及商用密码资质申请相关技术⼯作：商用密码产品认证、密码检测认证、密码安全评估8. 参与密码技术标准、行业规范、技术白皮书制定工作。</li><li>参与系统安全架构设计、代码安全评审及安全优化。</li><li>在研发过程中合理使用 AI辅助开发工具，提升开发效率与代码质量。</li></ol><p><strong>二、任职要求</strong></p><ol><li>本科及以上学历，计算机、信息安全、密码学相关专业。</li><li>8年以上Java开发经验。</li><li>精通以下技术栈：Java、Spring Boot、Spring Cloud、MyBatis、Redis、Kafka 、 RocketMQ、Kotlin、JQ4. 熟悉 Linux系统开发与部署。</li><li>熟悉PKI体系、CA系统、X.509证书、OCSP、CRL、证书生命周期管理6. 熟悉SM2 / SM3 / SM4、RSA / ECC、TLS / SSL、GMSSL密码技术7. 熟悉HSM服务器密码机、PCI密码卡、USBKey、密码服务平台8. 熟悉密码接口标准：PKCS11、SDF、SKF9. 熟练利用 AI工具提升研发效率，完成：代码生成与优化、单元测试生成、代码审查辅助、技术文档生成具备以下经验之一优先：</li><li>CA电子认证机构或PKI系统研发经验2. 电子签名 / 电子签章系统研发经验3. 密码机 / HSM / 密码卡接口集成经验4. 抗量子密码算法（PQC）相关研究或开发经验5. 参与商用密码产品资质申报或密码检测认证经验6. 参与密码行业标准或技术规范制定经验7. 具备Go语言开发经验</li></ol>', '5-10年', '1efefa5294c90d100ndy2tq7FlJZ', '深圳 · 福田区 · 梅林', '18-25K', 'Java, Golang, Spring, SpringCloud, MyBatis, Kafka, Redis', '高级Java开发工程师（CA认证、密码方向）', 'https://www.zhipin.com/job_detail/1efefa5294c90d100ndy2tq7FlJZ.html', '定期体检, 五险一金, 带薪年假, 员工旅游, 零食下午茶, 节日福利');
INSERT INTO `jobs` VALUES (475, '飞渡科技股份有限公司', '计算机软件', '100-499人', 'B轮', '本科', '<p>【</p><p><strong>岗位职责</strong></p><ol><li>构建高性能、高可用的空间数据服务接口（如要素服务、⽡⽚服务、三维数据服务等），⽀撑前端（Web/移动/桌面）与数字孪生引擎的调⽤；</li><li>设计并优化海量矢量、栅格、倾斜摄影、BIM、点云等数据的存储方案（如PostgreSQL/PostGIS、MongoDB、HBase等）及空间索引策略；</li><li>开发空间数据ETL流程，实现多源异构数据（Shapefile、GeoJSON、SHP、GDB、3D Tiles、S3M等）的自动化导入、坐标转换、切片与发布；</li><li>负责GIS服务性能调优，包括查询优化、缓存策略、负载均衡及并发控制；</li><li>与前端开发、产品及项目团队紧密协作，完成技术方案落地与线上问题排查。</li></ol><p><strong>任职要求</strong></p><ol><li>计算机科学、地理信息系统、软件工程或相关专业本科及以上学历，5年以上后端开发经验，其中至少3年专注于GIS后端开发。</li><li>精通Java/Go/Python中至少一门后端语言及其生态，具有扎实的数据结构、算法、操作系统和网络编程基础。</li><li>精通PostgreSQL/PostGIS的空间数据存储、查询优化与扩展开发。熟悉空间索引原理与优化。</li><li>丰富的GIS服务开发经验，熟悉OGC标准（WFS/WMS/WMTS等），有GDAL/OGR、GeoTools、GeoServer等库或平台的实际开发/调优经验。</li><li>具备分布式系统设计与开发经验，熟悉微服务架构、消息队列、缓存、负载均衡等相关技术。</li><li>英语流利，可作为核心工作语言。能无障碍阅读英文技术论文与源码，撰写设计文档，并参与国际技术会议或跨洋协作。</li><li>出色的系统设计、性能调优和复杂问题解决能力。优先考虑：</li><li>拥有大规模三维空间数据（如3D Tiles, I3S, 点云）处理与服务化（如Cesium ion, Esri Indexed 3D Scene Layers）的实战经验。</li><li>具有数字孪生、智慧城市、BIM/CIM类大型项目后端架构设计经验。</li><li>熟悉云平台（AWS/Azure/阿里云等）的GIS相关服务，并有云上大数据处理（如Spark, Flink）经验。</li><li>熟悉计算机图形学基础，或对WebGL/Cesium/Three.js等前端渲染技术有了解，具备前后端协同优化思维。</li><li>在GitHub上有知名的相关开源项目贡献。出差阿联酋中文作为工作语言出差时长3~6个月</li></ol>', '5-10年', '33e26cbc2b3995f80nJ629y8F1dR', '深圳 · 南山区 · 科技园', '15-30K', 'Java, SpringCloud, MySQL, 架构设计经验', 'java开发工程师', 'https://www.zhipin.com/job_detail/33e26cbc2b3995f80nJ629y8F1dR.html', '交通补助, 股票期权, 通讯补贴, 带薪年假, 餐补, 零食下午茶, 年终奖, 五险一金, 员工旅游, 节日福利, 定期体检');
INSERT INTO `jobs` VALUES (476, '深圳秉航汇通科技', '医疗健康', '20-99人', '', '本科', '<p><strong>任职要求</strong></p><p>5-10 年以上后端开发经验，有完整线上项目经验。熟悉 Python / Node.js / Go / Java 任一后端技术栈。熟悉 MySQL / PostgreSQL、Redis，有良好的数据库建模能力。熟悉 RESTful API 或 GraphQL 接口设计。有账号体系、RBAC 权限系统、组织架构、多角色管理经验。有 SaaS 平台、多租户系统、CRM、代理商系统、经销商系统、电商后台、企业管理后台经验者优先。熟悉 Docker、Nginx、Linux 服务器部署、CI/CD、⽇志监控。有 AI 应⽤、OpenAI API、LLM、AI Agent、MCP、⼯作流自动化、插件系统经验者优先。能独立完成从需求理解、技术⽅案、数据库设计、接口开发到上线部署的完整流程。具备较强的安全意识，能在平台架构、服务器、接口、AI 调用和数据隔离层面设计安全方案。看重服务器安全能力。</p><p><strong>岗位职责</strong></p><p>负责 OpenClaw 云端系统的二次开发、后端架构设计和接口开发。搭建面向经销商使用的 SaaS 平台，包括账号体系、组织架构、角色权限、经销商分级、门店/员工管理。设计多租户数据隔离方案，确保总部、代理商、经销商、门店、员工之间的数据权限清晰。对接 AI 模型、OpenAI API、Agent 工作流、插件系统、工具调用等能力。开发任务队列、异步执行、失败重试、调用记录、用量统计、额度控制、套餐管理等能力。设计后台管理系统接口，包括用户管理、模板管理、内容记录、数据看板、操作日志、客户资料、经销商管理等。负责数据库设计、接口安全、服务部署、日志监控、性能优化和故障排查。配合前端、产品和运营，把技术系统打磨成经销商可直接使用的平台。</p>', '5-10年', '0ee2c18a71c0b4760nF80tS4EFBQ', '深圳 · 宝安区 · 西乡', '13-18K', '不接受居家办公, Java, Docker, MySQL, Redis, PostgreSQL, 架构设计经验, 物联网经验', 'AI应用平台后端开发工程师', 'https://www.zhipin.com/job_detail/0ee2c18a71c0b4760nF80tS4EFBQ.html', '生日福利, 底薪加提成, 员工旅游, 节日福利, 带薪年假, 意外险, 绩效奖金, 五险一金, 保底工资, 股票期权, 全勤奖, 团建聚餐');
INSERT INTO `jobs` VALUES (477, '思特克技术', '计算机/通信/其他电子设备', '100-499人', '不需要融资', '本科', '<p><strong>一、岗位职责</strong></p><ol><li>负责公司充电桩平台系统的架构设计、平台新增功能模块的需求分析、设计、开发及测试工作；</li><li>负责公司充电桩运维管理平台（基于Steve开源框架二次开发）的日常维护与迭代升级；</li><li>负责OCPP协议相关功能的深度开发与调试，⽀持不同品牌充电桩的接⼊适配；</li><li>负责平台数据库的⽇常运维、性能调优及数据备份；</li><li>配合运维团队处理线上问题，保障平台7×24小时稳定运行；</li><li>参与部门研发技术⽅向规划，负责提供平台软件产品框架和技术路线，负责平台关键技术的预研与攻关，解决项目开发或产品研发中的技术难题。</li></ol><p><strong>二、任职要求</strong></p><ol><li>本科及以上学历，计算机、软件工程相关专业，5年以上工作经验；</li><li>3年以上Java后端开发经验，对计算机系统、网络和安全、应用系统架构等有全面的认识；</li><li>熟悉Spring Boot/Spring Cloud框架；</li><li>熟悉常用的中间件（Redis、RabbitMQ/Kafka等）；</li><li>熟悉MySQL/PostgreSQL等关系型数据库，有SQL优化经验；</li><li>熟悉Linux操作系统及常用命令，具备基本的Shell脚本编写能力，了解前端技术（Vue/React）者优先，具备全栈能力更佳；</li><li>英语4级以上，能够熟练阅读及编写外文资料；</li><li>熟悉OCPP协议（1.6/2.</li><li>1版本），具有新能源运营运维系统开发经验者优先；</li><li>有Steve（开源OCPP服务器框架）二次开发经验，熟悉其架构与核心模块；</li><li>有物联网平台（IoT）开发经验，熟悉MQTT、WebSocket等协议；</li><li>有Docker/Kubernetes容器化运维经验；</li><li>有DevOps实践经验，熟悉CI/CD流程；</li><li>精通设计模式和开源的框架，有面向对象分析、设计、开发能力；在可扩展、高性能、高并发、高稳定性系统设计、开发和调优方面有实际经验；</li><li>逻辑思维能力强，有良好的沟通协调能力和分析判断能力；</li><li>具有很强的工作责任感、上进心，热爱研发工作；</li><li>诚实肯干，吃苦耐劳，抗压能力强；</li><li>有创新意识和勇气，并具备高度责任心和敬业精神。</li></ol><p><strong>三、薪资福利</strong></p><p>1、</p><p><strong>薪资福利</strong></p><ol><li>购买五险一金；</li><li>每月享有全勤奖金；</li><li>不定期的培训和岗位提升；</li><li>不定期的团建活动、聚餐活动；精美下午茶点；</li><li>享有丰厚年终奖金；</li><li>节假日发放礼品；</li><li>公司配有冰箱、微波炉，可自行带饭；</li><li>上下班时间：8:30-12:00；13:30-18:00双休；</li><li>我们承诺：更多富有竞争力的薪酬</li></ol><p><strong>福利</strong></p><p>将随着公司的发展逐步完善。</p>', '5-10年', 'e382f3c6a3cef2340nJ529y0EVtX', '深圳 · 宝安区 · 西乡', '15-25K', 'Java, Spring, MySQL, 大数据经验, 架构设计经验, 物联网经验, 不接受居家办公', '平台软件工程师', 'https://www.zhipin.com/job_detail/e382f3c6a3cef2340nJ529y0EVtX.html', '团建聚餐, 意外险, 全勤奖, 员工旅游, 五险一金, 底薪加提成, 法定节假日三薪, 工龄奖, 年终奖');
INSERT INTO `jobs` VALUES (478, '钧雷光电', '仪器仪表', '20-99人', '未融资', '本科', '<ol><li>平台后端大数据框架设计、开发及维护工作， 制定和执行数据编码、测试和部署策略；</li><li>对数据进行清洗、提取和转换，确保数据质量和可靠性；</li><li>编写 SQL 查询、存储过程和触发器等数据库操作脚本；</li><li>协调与数据分析师、应⽤程序开发⼈员和其他团队成员合作完成项⽬。</li><li>根据项目需求，负责第三方应⽤接入平台。</li></ol><p><strong>任职要求</strong></p><ol><li>有完整的项目开发经验，掌握流行的java开源框架（spring cloud等成熟开发框架）；</li><li>熟悉物联网系统的标准设备模型，理解物联网平台架构；</li><li>在华为/阿里等大厂物联网中台的基础上，开发后端应用的经验；</li><li>具备较强的学习能力和自我管理能力，能够快速适应不同的数据技术和环境；</li><li>具备极强的团队协作和解决问题的能力具备较强的解决问题；</li><li>5年及以上工作经验，本科及以上学历。</li></ol>', '5-10年', '848b784d57d5438d031_09W6F1tR', '深圳 · 宝安区 · 西乡', '13-22K', 'JVM, Java, 不接受居家办公, 分布式经验, Docker, 微服务经验, SpringCloud, MySQL, MyBatis, Redis, 物联网', 'java开发工程师', 'https://www.zhipin.com/job_detail/848b784d57d5438d031_09W6F1tR.html', '交通补助, 五险一金, 年终奖, 股票期权, 绩效奖金, 零食下午茶, 团建聚餐, 生日福利');
INSERT INTO `jobs` VALUES (479, '海丰同就仓储物流', '装卸搬运和仓储业', '0-20人', '不需要融资', '本科', '<p>1、软件专业的，3、5年+开发经验，4、前后端开发5、会vibe coding无以上经验的务投</p><p><strong>一、岗位职责</strong></p><p>1、参与电商平台核心功能模块（如订单、支付、库存、促销、会员体系等）的架构设计、编码实现及持续优化2、搭建⾼并发、⾼可⽤、分布式的系统架构，确保服务稳定与良好的可扩展能力3、参与电商平台后端系统的开发与运维，保障系统高效稳定运⾏主导和参与系统的需求分析、架构设计、功能开发、代码评审、单元测试、发布上线等各环节的技术工作4、深入理解业务需求，分析和提炼业务模型，设计合理技术方案并实现二、工作经验3年以上Java后端开发经历，其中至少2年专注于电商系统研发三、技术能力1、编程语言：Java基础深厚，深入理解JVM原理、多线程编程、网络通信及常见设计模式2、开发框架：熟练运用Spring、Spring Boot/Spring Cloud、Dubbo、MyBatis等主流框架，具备大型微服务项目实战经验3、数据库：精通MySQL应用及性能调优，了解Redis、Elasticsearch、MongoDB等NoSQL技术4、中间件：了解消息中间件（Kafka/RocketMQ）的使用与调优高并发：了解高并发环境下的应对方案（如限流策略、服务降级、分布式锁实现）5、云服务：掌握主流云平台（如阿里云、腾讯云、AWS）相关云服务使用方式</p>', '5-10年', '58760928e62395210nJ529-9GVNR', '深圳 · 龙岗区 · 坪地', '11-12K', 'Java, SpringCloud, MySQL, 架构设计经验, Spring', '高级技术职位', 'https://www.zhipin.com/job_detail/58760928e62395210nJ529-9GVNR.html', '社保, 绩效奖金');
INSERT INTO `jobs` VALUES (480, '潮隐人工智能', '人工智能', '20-99人', 'A轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>全栈工程系统实现：主导 B2B 外贸数字员工系统的整体架构设计与核心代码实现，涵盖业务逻辑层、Agent 执行层及推荐算法接⼊层。</li><li>全渠道集成与连接：负责 WhatsApp、邮箱（SMTP/IMAP）、社交媒体等全渠道通信系统的深度集成，攻克跨境弱⽹环境下的⾼并发长连接稳定性。</li><li>数据资产沉淀：实现全链路客户数据采集与处理体系，负责用户精准画像（Profiling）及⾼可用知识库（Knowledge Base）的底层存储与检索架构。</li><li>系统性能与稳定性防线：全面负责整个系统的高可用（HA）设计、性能调优及容灾机制，确保在复杂业务逻辑下系统响应的流畅与稳定。</li></ol><p><strong>任职要求</strong></p><ol><li>2年以上后端开发经验，精通 Java/Go/C++/Python任何一门语言，熟悉分布式系统系统架构方案。</li><li>精通异步编程与消息驱动架构，深度掌握 Kafka、RabbitMQ 等消息队列在保证数据最终一致性中的应用。</li><li>具备深厚的网络协议功底，熟悉 WebSocket、TCP/IP、HTTP/3 及多渠道 API 集成规范，有处理大规模并发连接的实战经验。</li><li>有即时通讯（IM）或大型电商 ERP、CRM系统开发经验者优先。</li><li>有 AI Agent工程落地或Chatbot研发经验者优先。</li></ol>', '5-10年', 'f0b64309993a6d330nJ70ti-EFZX', '深圳 · 南山区 · 科技园', '15-28K·15薪', 'Golang, Java, C++, 分布式经验, 微服务经验, SpringCloud, MySQL, Kafka, Redis, Spring, Python', '后台开发工程师', 'https://www.zhipin.com/job_detail/f0b64309993a6d330nJ70ti-EFZX.html', '股票期权, 绩效奖金, 保底工资, 底薪加提成, 有无线网, 五险一金, 宿舍有空调, 年终奖, 住房补贴, 企业年金');
INSERT INTO `jobs` VALUES (481, '智慧林网络', '人工智能', '20-99人', '未融资', '本科', '<ul><li>熟练运用Spring⽣态技术栈，了解SaaS/PaaS平台开发模式，有AI⼤模型相关应⽤开发经验者优先；</li><li>配合完成代码质量管控、技术文档编写，协助进行团队技术分享，跟进⾏业技术趋势并应用于实际开发；</li><li>支撑业务快速迭代，协助进行系统性能优化和问题排查，保障业务系统平稳运行。</li></ul><p><strong>岗位职责</strong></p><ol><li>模块开发与实现- 参与业务需求评审，结合技术规范，完成Java后端业务模块的详细设计与开发实现；- 基于Java EE/Spring生态（Spring Boot、Spring Cloud/Spring Cloud Alibaba）进行后端服务开发，实现RESTful API、RPC服务等核心业务接口，支撑业务场景落地；- 协助完成SaaS/PaaS平台相关模块开发，包括租户管理、权限控制、服务监控等基础功能的实现与优化；- 配合完成AI大模型相关后端功能开发，协助实现模型调用接口、对话上下文管理等基础功能，保障大模型能力的稳定调用；- 编写规范的技术文档，包括接口文档、模块设计说明等，确保开发过程可追溯、团队协作高效。</li><li>代码质量与调试- 遵循团队编码规范，完成代码开发、单元测试、集成测试，确保代码质量符合要求；- 参与团队代码审查（Code Review），及时修正代码问题、性能隐患，配合提升团队整体代码质量；- 负责开发过程中的bug排查与修复，配合测试团队完成问题验证，确保模块功能正常运行。</li><li>系统维护与优化- 协助进行系统性能分析与调优，包括SQL优化、缓存策略调整等基础优化工作，提升系统运行效率；- 协助排查线上系统常见问题，配合技术负责人定位问题根因并落实解决方案，保障系统7×24小时稳定运行；- 配合运维团队完成系统部署、发布、扩容等工作，协助制定简单的部署和回滚方案；- 协助建立和完善系统监控体系，配合收集系统运行指标，及时发现并反馈潜在问题。</li><li>团队协作与技术提升- 配合初级开发工程师开展工作，解答基础技术问题，协助其提升开发能力；- 跟踪Java生态、分布式系统等领域的技术动态，学习成熟技术框架和最佳实践，应用于实际开发工作；- 与产品、前端、测试等跨团队紧密协作，对齐开发需求，反馈开发过程中的问题，保障项目按计划交付；- 参与敏捷开发流程，配合完成迭代任务拆分、开发进度跟进，参与每日站会、迭代评审等会议；- 协助进行技术债梳理，配合完成简单的系统重构工作，提升系统可维护性。</li><li>文档编写与其他工作- 编写并维护开发文档、接口说明等相关文档，保证文档的准确性和完整性；- 配合嵌入式工程师、测试工程师开展工作，确保技术方案落地可行性；- 完成上级领导交办的其他工作事项。</li></ol><p><strong>任职要求</strong></p><ol><li>统招本科及以上学历，计算机科学与技术、软件工程、电子信息工程、通信工程、自动化等相关专业；-</li><li>技术能力突出、有相关项目经验者，学历可适当放宽；-</li><li>经验要求 - 3年及以上Java后端实际开发经验，1年及以上微服务/分布式系统开发经验，有中小型项目开发落地经验； - 了解SaaS/PaaS平台开发流程，有云原生相关开发或使用经验优先； - 有AI大模型应用开发、模型调用相关经验者优先； - 有高并发系统开发与基础优化经验者优先。-</li><li>能力要求 - 熟练掌握JavaSE/JavaEE核心技术，理解JVM基本原理（内存模型、GC机制）、Java并发编程基础（线程池、锁机制），能配合完成JVM基础调优； - 熟练运用Spring生态技术栈，包括Spring Boot、Spring Cloud/Spring Cloud Alibaba（Nacos/Sentinel等）、Spring MVC、MyBatis-Plus，能独立完成微服务模块开发； - 熟练掌握关系型数据库（MySQL/Oracle），理解数据库基本原理、事务隔离级别，熟练编写优化SQL、设计基础索引，了解分库分表、读写分离等优化手段； - 熟练使用NoSQL数据库（Redis为主），了解Redis集群、持久化、缓存策略，能根据业务场景合理使用； - 了解分布式系统核心原理，熟悉分布式事务、分布式锁、服务注册发现等基础技术方案，能配合完成分布式模块开发。-</li><li>素质要求 - 具备良好的学习能力，能快速掌握新技术、新框架，并应用于实际开发； - 具备较强的问题分析和解决能力，能独立排查开发过程中的常见技术问题； - 具备基本的架构设计思维，能配合架构师完成模块设计，兼顾功能实现和代码可读性； - 具备良好的口头和书面沟通能力，能与跨团队高效协作，清晰反馈开发进度和问题； - 具备强烈的责任心和敬业精神，对代码质量、系统稳定性负责，能积极配合团队完成开发任务。</li></ol><p><strong>岗位职责</strong></p>', '5-10年', '8af938f8c6cac35b0nB929m7E1NQ', '深圳', '10-15K', 'Java, Spring, Kafka, JVM, SpringCloud, MyBatis, MySQL, SQL Server, PostgreSQL, 微服务经验, 大数据经验, 物联网经验, 分布式经验, 云计算经验, 大模型, 智能体, AI大模型', '中级java开发工程师', 'https://www.zhipin.com/job_detail/8af938f8c6cac35b0nB929m7E1NQ.html', '零食下午茶, 节日福利, 团建聚餐, 五险一金');
INSERT INTO `jobs` VALUES (482, '深圳市优普洛', '计算机软件', '20-99人', '未融资', '大专', '<p>自研岗，</p><p><strong>任职要求</strong></p><p>一、 基础能力要求Java核心技术：5年以上Java开发经验，精通Java 8+（含Lambda、Stream API），深⼊理解JVM原理（内存模型、垃圾回收、性能调优）。并发编程：精通Java多线程、锁机制，能处理⾼并发场景下的线程安全与性能问题。框架与架构：精通Spring Boot、Spring Cloud微服务架构，有RESTful API设计经验。熟悉常⽤ORM框架（如MyBatis、JPA）及数据库优化（MySQL/Oracle，分库分表、SQL调优）。掌握常用中间件：Redis、Kafka/RocketMQ、Elasticsearch等，并理解其底层原理。工程化能⼒：熟练使用Maven/Gradle、Git及CI/CD流程，熟悉Docker及Kubernetes容器化部署。二、 AI集成与应用能力1. 熟悉 OpenCode 集成应用OpenCode 是一款终端环境下的AI编程代理（CLI/TUI工具），对它的熟悉要求体现在：安装与配置：能够通过npm安装 opencode-ai，并完成AI服务提供商（如OpenAI兼容接口、Anthropic等）的配置认证。Provider配置：了解如何在 ~/.config/opencode/opencode.json 中自定义Provider，支持对接不同的AI模型（如智谱GLM、Kimi等），并能处理模型的多模态能力（如视觉输入）。应用开发：能够利用OpenCode辅助生成代码，例如根据自然语言描述生成完整的功能模块（如Excel数据解析结合拓扑图生成）。扩展能力：具备基于OpenCode开发插件的经验（如 opencode-feishu 插件），能实现AI能力与外部系统（如飞书、钉钉）的集成，实现消息的自动响应与上下文积累。2. 了解AI模型集成与Java应用结合API对接：熟悉使用Spring Boot 3 + WebClient 或 HttpClient 异步调用大模型API（如OpenAI、通义千问等），处理流式响应和非阻塞I/O。Spring AI 框架：了解Spring AI框架的使用，利用其抽象层统一管理不同AI提供商（OpenAI、Ollama等），实现基于Prompt Templates的智能问答或RAG（检索增强生成）应用。推理优化：了解ONNX Runtime在Java中的应用，能够将Python训练的模型转换为ONNX格式并在JVM内执行推理，从而降低延迟、简化部署（无需Python环境）。三、 加分项有构建AI Agent（智能体）或复杂工作流编排的经验。对LLM（大语言模型）的Prompt Engineering有深入理解，能够通过提示词优化输出效果。具备DevOps思维，熟悉如何将AI能力作为基础设施集成到CI/CD流程中。</p>', '5-10年', 'd1b5b2ae07f442510nZ_3dy1FldW', '深圳 · 福田区 · 市民中心', '11-17K·13薪', 'Java, 分布式经验, SpringCloud, Redis, Spring, OpenCode 集成, Elasticsearch, Docker, 微服务经验, MySQL, MyBatis, Oracle, Python, AI Agent, Spring AI', 'java高级研发工程师', 'https://www.zhipin.com/job_detail/d1b5b2ae07f442510nZ_3dy1FldW.html', '五险一金, 带薪年假, 年终奖, 定期体检, 节日福利, 员工旅游, 股票期权');
INSERT INTO `jobs` VALUES (483, '中集数能科技', '物联网', '20-99人', '不需要融资', '本科', '<p>公司直招，非外包，深圳蛇口总部办公。</p><p><strong>岗位职责</strong></p><ol><li>负责能源行业数字化解决方案相关功能模块开发，包括数据采集、存储、分析、可视化等核⼼业务场景的代码实现。</li><li>基于公司现有成熟平台，进⾏需求拆解、功能修改与定制化开发，适配类似能源⾏业新项目的业务场景与部署要求。</li><li>负责新项目的系统部署、环境配置、上线调试及后续优化⼯作，确保项目平稳落地与稳定运行。</li><li>参与数据库设计与优化，处理海量设备数据的高效存储与查询，保障数据处理的稳定性和实时性。</li><li>协同前端、测试及产品团队，完成跨部门项目协作，推进产品迭代、功能优化及新项目交付。</li><li>解决系统开发、修改、部署及运行过程中的技术难题，参与技术攻关和技术创新，提升系统性能与用户体验。</li><li>参与 API 接口设计与开发，支持系统集成与第三方对接，保障平台的开放性与兼容性，适配新项目的集成需求。</li></ol><p><strong>任职要求</strong></p><ol><li>精通 Java 核心技术，熟练掌握 Spring Boot、Spring Cloud、MyBatis 等主流开发框架，具备扎实的技术功底。</li><li>熟悉 MySQL、Redis 等数据库与缓存技术，具备数据库设计、优化及性能调优经验，能处理高并发场景下的数据存储问题。</li><li>了解微服务架构设计理念，具备分布式系统开发、部署及运维相关经验，熟悉服务注册与发现、负载均衡等机制，有项目部署上线实操经验者优先。</li><li>具备现有系统二次开发、定制化改造及适配新项目的相关经验，能快速理解原有架构并进行高效修改与部署。</li><li>熟悉物联网、大数据相关技术者优先（如 MQTT 协议、数据同步工具、流式计算框架等），有能源、化工、工业互联网行业项目经验者优先。</li><li>有基本的前端开发能力优先。</li><li>具备良好的编码规范和文档编写能力，逻辑思维清晰，善于分析和解决复杂技术问题。</li><li>具备较强的团队协作意识和沟通能力，工作积极主动，有责任心，能承受一定的项目压力。</li><li>认同公司 \"创新技术赋能能源行业数字化转型\" 的发展理念，热衷于技术创新与行业应用结合。</li></ol>', '5-10年', 'd92c7dc2da74e0f20nRz2tS-E1ZV', '深圳 · 南山区 · 蛇口', '8-13K', 'MES开发经验, Java, 物联网经验, 大数据经验, 不接受居家办公, 微服务经验, SpringCloud, MySQL, MyBatis, Redis, Spring', 'Java开发工程师', 'https://www.zhipin.com/job_detail/d92c7dc2da74e0f20nRz2tS-E1ZV.html', '意外险, 带薪年假, 节日福利, 生日福利, 餐补, 定期体检, 交通补助, 补充医疗保险, 年终奖, 五险一金');
INSERT INTO `jobs` VALUES (484, '深圳科先人工智能系统', '人工智能', '0-20人', '', '本科', '<ol><li>本科及以上学历，有3年及以上的项⽬团队管理经验 、计算机、⼈⼯智能、软件工程等相关专业本科及以上学历，2年及以上 AI Agent/LLM 应用开发经验；7年以上全栈开发经验2. 有架构设计能⼒，熟悉分布式架构设计，精通RabbitMQ/RocketMQ/Kafka等消息中间件，掌握Node.js底层机制，具备JVM调优实战经验3、前端技术：掌握或至少了解React18版本、Vue3、typescript、Electron等前端开发语言，掌握组件、路由、数据绑定、表单、组件间通信等操作。</li><li>后端技术：精通Java，同时了解Golang、Node.JS、Python等其他编程语言之一者优先框架：Spring Boot、Spring Cloud 阿里巴巴等微服务框架5、熟练使用关系型数据库，如Oracle，MySql，PostgreSql等、理解Redis集群架构与缓存击穿/穿透/雪崩解决方案6、熟悉常用代码管理工具Git，SVN等7：Ai爬虫。通用爬虫系统的编写。使用过PlayWright MCP等技术优先8. 擅长熟练：AI编程软件：Claude Code，Cursor，Trae.gemini3 擅长AI协同编程工作，整合AI协同编程工作9： Agent,langchain4j ,RAG大模型有了解个人的见解输出加分项（优先录用）1:熟练使用粤语沟通，香港工作过的经验优先2：有法律 ＋教育 +智能办公＋ AI 中台基座赛道开发经验优先，3：具备多 Agent， 协作框架设计经验，能落地复杂场景下的智能体协同；对AI Agent 技术发展趋势有深刻的理解和洞察4：熟悉企业文档系统对接逻辑，有文档检索、智能分类相关开发经验；5：大型系统架构开发经验6:积极关注紧跟：前沿技术并应用7：具备较强的逻辑思维与问题分析能力.整合性思维，拆分问题分析能力,系统性分析问题来构建系统软件，逻辑能力..独立能完成技术攻坚.复合型能力9：擅长敏捷开发{以市场客户角度 }10：具备较强的产品意识，从业务痛点/业务逻辑/跨部门协同的能力和解决问题的能力，能从用户体验角度思考 AI能力设计：以实际场景和业务场景逻辑结合的创立落地能力11：项目从0到1的经验{架构，开发，部署，运维..}12：有开源 AI 框架贡献经验或相关技术沉淀者13：有 AI应用从0到1的完整落地经验 14：在 AI社区有技术输出(博客/视频平台/开源项目/论文)15：自驱力，自学能力强。紧跟前言技术，学习用应用热爱的发心 Agent的经验：1：基于 Java+langchain4j 框架，负责 AI Agent 核心架构设计与落地开发，实现智能体的感知、规划、决策、执行全流程能力，适配律所案件办案、智能办公,教育核心场景；2:熟练使用 langchain4j 框架进行 AI Agent 开发，熟悉其核心组件（链、代理、工具、记忆）的设计与二次开发3:深入理解大语言模型（LLM）原理与应用，具备 GPT/Claude/Llama 等模型的对接、调优实战经验；4::掌握 RAG 检索增强生成核心技术，具备向量数据库（Milvus/Pinecone/Chroma）选型、部署与应用经验；构建法律场景专属知识库与向量检索体系，支撑证据梳理、文书生成等核心需求；5:具备 AI Agent 工具调用、知识库构建、记忆系统设计能力，能独立完成智能体从设计到落地的全流程；6:具备外部系统集成经验，能高效对接数据库、API 接口、文档系统，解决跨系统交互问题。7:构建 Agent 长短期记忆系统与多 Agent 协作框架，支撑单案多角色 Agent 分工（如证据梳理 Agent、文书生成 Agent），实现协同办公；岗位</li></ol><p><strong>福利</strong></p><p>1：双休、五险一金、法定节假日、{带薪年假}2：项目奖金，年终奖3：加班补贴4：定期学习培训5：Claude/Cursor等顶级AI工具全年订阅</p>', '5-10年', 'fa66a10c6140a3ab0nRy0tq1ElVW', '深圳 · 南山区 · 科技园', '16-30K', 'AI工具编程, Java, 不接受居家办公, 业务场景 业务逻辑, 创新灵活, 粤语, SpringCloud, MySQL, Redis, 架构设计经验, Spring, 香港户口', 'AI技术负责人', 'https://www.zhipin.com/job_detail/fa66a10c6140a3ab0nRy0tq1ElVW.html', '公司分润, 生日福利, 企业年金, 带薪年假, 全勤奖, 团建聚餐, 股票期权, 绩效奖金, 保底工资, 加班补助, 五险一金');
INSERT INTO `jobs` VALUES (485, '毅弘科技创新', '电子商务', '100-499人', '不需要融资', '大专', '<p><strong>岗位职责</strong></p><ol><li>负责公司业务系统的后端开发工作，参与需求分析、系统设计、编码实现、测试及维护等环节；</li><li>深入理解业务，根据需求能够制定并撰写技术方案，组织内部进行技术⽅案评审3、负责系统⽇常维护，并处理内部系统⼯单问题，确保系统能够稳定运行。</li><li>与产品经理、前端开发人员紧密合作，快速响应业务变化，优化现有系统性能;</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机相关专业，5年及以上Java后端开发经验；</li><li>有扎实的Java编程基础及良好的编码习惯，熟练掌握多线程、并发、分布式、事务、IO、多线程、集合等基础框架3、熟练掌握SpringBoot、SpringCloud 、Mybatis等开发框架，对框架原理有⼀定的理解；</li><li>熟练掌握Mysql数据库，熟悉数据层性能优化，具备数据库应用系统规划及设计能力；</li><li>熟练使用 redis,rabbitmq等常用组件，懂得Linux常用命令；</li><li>熟练Git、maven等管理⼯具的使用7、熟悉分布式系统的设计和应用，熟悉分布式、缓存、消息等机制，能对分布式常用技术进行合理应用，解决问题；</li><li>有良好的团队合作意识和逻辑分析能力，有强烈的工作责任心和技术上进心。【</li></ol><p><strong>福利待遇</strong></p><p>】1、上班时间：双休，8H工作/天2、保险</p><p><strong>福利</strong></p><p>一档社保，五险一金，年度免费体检3、团队活动：各种节日活动和团建活动4、吃好喝好：每月零食自由、每周下午茶、免费加班餐5、兴趣社群：羽毛球社、篮球社、桌游社、各种DIY活动6、礼品礼金：各种节日、生日、周年礼品7、其他</p><p><strong>福利</strong></p><p>优秀员工股权激励，见证你的高光时</p>', '5-10年', '8b024b68e637228b0nR_2d26FVVY', '深圳 · 宝安区 · 西乡', '17-20K', 'Java, SpringCloud, MySQL, Redis', '高级Java开发工程师（自研，非外包）', 'https://www.zhipin.com/job_detail/8b024b68e637228b0nR_2d26FVVY.html', '生日福利, 团建聚餐, 定期体检, 绩效奖金, 零食下午茶, 带薪年假, 节日福利, 意外险, 通讯补贴, 五险一金');
INSERT INTO `jobs` VALUES (486, '渴创技术', '消费电子', '100-499人', 'A轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>系统架构设计与演进 — 协助 ERP 核心模块（订单、仓储、物流、财务、商品等）的系统架构设计、技术选型及落地，推动系统从“能用”到“好维护”的演进。</li><li>技术攻坚与代码质量 — 主导关键业务场景的技术方案设计和核心代码编写。</li><li>技术规划与落地 — 协助制定技术路线图，识别当前系统的技术债务并推动偿还，平衡业务需求与技术投⼊。</li><li>AI 落地推动 — 推动 AI 能⼒与⽇常开发及业务场景的融合，探索大模型在开发提效（代码生成、Code Review、测试⽤例生成、故障排查）和业务赋能（智能客服、商品信息抽取、异常订单识别、运营数据分析）等方向的落地。</li><li>团队赋能 — 指导中级开发工程师成长，通过 Code Review、技术分享、结对编程等方式提升团队技术水位。</li></ol><p><strong>任职要求</strong></p><ul><li>计算机相关专业本科及以上学历，5 年以上 Java 开发经验，至少 1 年技术主导或架构设计经验。</li><li>扎实的 Java 基础，熟悉 JVM 原理、多线程编程、常用设计模式，能结合实际场景做合理取舍。</li><li>熟悉 Spring Boot / Spring Cloud Alibaba 技术栈，有微服务架构的实战经验。</li><li>熟悉 MySQL、Redis、RocketMQ/Kafka、Elasticsearch 等中间件的使用及调优。</li><li>有复杂业务系统的模块拆分、服务化改造经验。</li><li>熟悉 AI 技术栈并能在工作中落地 — 了解主流大模型（GPT、Claude 等）的能力边界和使用范式，掌握 prompt engineering，有 RAG、Agent/Function Calling 方向的实践经验，能独立搭建 AI 应用（如对接 LLM API、构建知识库问答、编排 Agent 工作流等）。加分项：- 有电商 ERP、WMS、OMS、供应链等相关领域经验。</li><li>熟悉多平台（Amazon、Shopify、TikTok Shop 等）对接和跨境业务特性（多语言、多币种、多仓、关税等）。</li><li>有 DDD 落地经验，或对事件驱动架构有深入理解。</li><li>能利用 AI 辅助编程工具（Codex、Cursor、Claude Code 等）提升开发效率，有实际的提效案例。软素质：- 能独立把模糊的业务需求转化为清晰的技术方案，而不是等“需求文档写好了再动手”。</li><li>有 Owner 意识，对系统的稳定性和可维护性有天然的追求。</li><li>沟通表达清晰，能向上对业务方讲清楚技术决策的 trade-off，也能带中级同学一起把事做成。</li><li>对新技术保持好奇心，能主动探索 AI 在业务和技术侧的应用场景并推动落地。</li></ul>', '5-10年', 'b18709481a2930490nF_39i_FlBQ', '深圳 · 龙岗区 · 坂田', '15-20K', 'Java, Spring, MySQL, Redis, 架构设计经验, ERP开发经验, 跨境ERP', '高级Java开发工程师(跨境电商ERP/双休)', 'https://www.zhipin.com/job_detail/b18709481a2930490nF_39i_FlBQ.html', '五险一金, 五险一金, 年终奖, 全勤奖');
INSERT INTO `jobs` VALUES (487, '天感智能', '大数据', '20-99人', 'A轮', '本科', '<p><strong>工作职责</strong></p><ol><li>执行公司业务发展战略，配合总监主导公司产品设计开发；</li><li>组建并带领研发团队，解决技术难题，提供技术支持和解决方案；</li><li>建立并执行研发流程和标准，确保产品质量和交付周期；</li><li>学习和研究新技术以满足产品需求，推动后端技术架构的持续优化和创新。</li></ol><p><strong>任职要求</strong></p><ol><li>计算机科学、软件工程或相关专业本科及以上学历；</li><li>具备大型系统架构设计经验，能够设计高可用、高并发的后端系统；</li><li>8年以上后端开发经验，3年以上后端团队管理经验，有微服务开发经验者优先；</li><li>精通Java编程语言，熟悉主流后端框架和工具（如Springboot、SpringCloud等），深入理解分布式系统、微服务架构、消息队列、缓存、数据库优化等技术，具备云计算平台使用经验，熟悉容器化技术（如Docker、Kubernetes）；</li><li>有生鲜食材供应链erp、oms、wms、tms等系统开发经验尤佳；</li><li>具备出色的沟通和协调能力，能够与各部门有效合作（非常重要）。</li></ol>', '5-10年', 'f3f89893fee6721403V_2dm_FFdU', '深圳 · 龙华区 · 民治', '15-25K', 'Java, 不接受居家办公, 团队管理经验, 有进销存/CRM系统经验, Docker, 懂SAAS业务架构, SpringCloud, MySQL, 架构设计经验', 'Java后端副总监', 'https://www.zhipin.com/job_detail/f3f89893fee6721403V_2dm_FFdU.html', '年终奖, 交通补助, 通讯补贴, 员工旅游, 节日福利, 带薪年假, 零食下午茶, 五险一金');
INSERT INTO `jobs` VALUES (488, '创世易明', '互联网', '0-20人', '未融资', '本科', '<p><strong>职位描述</strong></p><ol><li>独立负责运动健康类产品后端需求的设计和开发;</li><li>具有独立开发H5和小程序的技术能力;</li><li>独立负责业务平台的技术架构设计、产出设计方案，确保系统的架构质量，并能识别风险，保障产品可用性，提升产品响应效率；</li><li>具有项目把控能力，确保项目进度和质量;</li><li>负责产品代码以及相关文档的维护工作;</li><li>深入理解平台业务，能够有效的引入创新的技术和解决方案，并⽤用创新的思路解决业务问题。</li></ol><p><strong>职位要求</strong></p><ol><li>本科及以上学历，计算机或软件工程等相关专业，5年以上Java开发经验；</li><li>有扎实的Java编程基础，熟悉微服务相关的主流框架，会用SpringBoot、SpringCloud、My Batis、Kafka或Dubbo、Zookeeper等组件；</li><li>熟练掌握MySQL、Oracle、ES等存储技术，熟练掌握Redis缓存技术；</li><li>熟练掌握分布式架构，具备云原生架构设计经验，掌握微服务拆分原则和开发框架，熟悉开源的分布式中间件使用与调优，能了解到它的原理和机制；</li><li>具备云平台的架构设计经验，熟悉Azure或阿里云等主流平台功能，具备实施经验；</li><li>具备较强的业务理解能力和学习能力，对新技术和业务有很强的学习热情；</li><li>具备较强的团队协作能力和抗压能力；</li><li>工作有效率，有良好的沟通协调能力，同时热爱编程事业，有激情、对新技术有不懈追求。*注：与</li></ol><p><strong>岗位要求</strong></p><p>不符者，请勿投递； 此岗位必需全日制本科及以上学历，请慎投。</p>', '5-10年', 'f5ad11c5e0352cd61nV73Ny4FVpY', '深圳 · 南山区 · 科技园', '15-25K', 'Java, 企业级应用开发, Linux, 分布式技术, 后端开发', 'Java开发工程师', 'https://www.zhipin.com/job_detail/f5ad11c5e0352cd61nV73Ny4FVpY.html', '法定节假日三薪, 绩效奖金, 五险一金, 零食下午茶, 节假日加班费, 节日福利, 团建聚餐, 年终奖, 带薪年假, 全勤奖, 员工旅游, 股票期权');
INSERT INTO `jobs` VALUES (489, '马太科技', '互联网', '100-499人', '不需要融资', '本科', '<p>中高级后端（Java，其他后台语言都不合适），初级前端经验（偏C端侧，不用管理系统的前端经验）【</p><p><strong>岗位职责</strong></p><ol><li>架构与设计：参与系统架构规划与技术选型，主导核⼼模块设计；能识别系统瓶颈，保障系统在多租户/⾼并发场景下的稳定性与扩展性。</li><li>全链路性能优化：不局限于单端，能从SQL查询、接口响应、数据缓存到前端渲染进行全链路性能分析与调优，提升用户体验。</li><li>基础能⼒建设：搭建并维护权限管理、会话控制、日志监控、CI/CD流水线等基础设施，提升团队研发效能与系统安全性。</li><li>业务赋能：深入理解业务，将复杂需求抽象为可复用的技术模型或通用组件；对接产品/业务团队，输出可落地的技术方案并推动迭代。</li><li>安全合规：负责应用全链路安全设计与合规落地，能主动识别并防御SQL注入、XSS、越权访问、敏感数据泄露等常见风险；熟悉行业规范要求，将安全策略融入架构设计与开发流程。【</li></ol><p><strong>任职要求</strong></p><ol><li>后端：精通 Java、Spring Boot、Dubbo、Spring cloud 等主流技术栈，深刻理解微服务架构、RESTful API设计规范及常用设计模式。</li><li>前端：熟练使用 Vue3 + TypeScript，了解其生态与原理；熟悉组件化设计、状态管理及前端工程化；具备独立完成前端（面向用户端/C端产品）开发及常见问题排查解决能力。</li><li>数据存储：精通 MySQL 设计与调优（索引、事务、锁机制），熟练使用 Redis 进行缓存设计与分布式锁实现；了解 Elasticsearch 等NoSQL组件者优先。5、</li></ol><p><strong>综合素质</strong></p><ol><li>熟悉企业级复杂权限体系（RBAC/ABAC）、多租户架构或私有化部署方案。</li><li>有桌面端应用开发经验（Electron）。</li><li>有开源项目贡献、技术博客输出或团队技术规范制定经验。</li><li>熟悉 CI/CD 流水线搭建（Jenkins/GitLab CI）及自动化测试。</li></ol>', '5-10年', 'f3d5f97d0ff6b43f0nJ43tq9F1BZ', '深圳 · 南山区 · 科技园', '15-25K', 'Java, 不接受居家办公, 分布式经验, Elasticsearch, SpringCloud, MySQL, Electron, CICD, Redis, Dubbo, 架构设计经验, Spring', '全栈开发工程师', 'https://www.zhipin.com/job_detail/f3d5f97d0ff6b43f0nJ43tq9F1BZ.html', '生日福利, 节日福利, 绩效奖金, 团建聚餐, 员工旅游, 五险一金, 年终奖, 定期体检, 带薪年假, 零食下午茶');
INSERT INTO `jobs` VALUES (490, '飞悦达', '计算机软件', '20-99人', '', '大专', '<ol><li>5年以上Java开发经验。</li><li>精通Java与JVM调优，深入理解内存模型、GC，掌握常用设计模式。</li><li>精通Spring Boot、Spring Cloud、MyBatis等框架及原理，熟悉Sentinel/Nacos等组件。</li><li>扎实的分布式基础，精通Redis集群、RabbitMQ，有丰富的高并发落地能力。</li><li>精通MySQL，擅长索引与SQL优化，熟悉分库分表⽅案，有海量数据经验优先。</li><li>熟悉Linux、Docker与K8s，具备线上排查与CI/CD意识。</li><li>有⽀付对接经验，对于回调幂等场景有⾼要求，有支付系统开发经验。（重要）8、良好的数据结构和算法功底，能将复杂业务抽象为清晰模型。优先加分项：</li><li>有秒杀、抢购、直播等高并发极限场景实战经验。</li><li>深⼊研读过Redis、Netty、RocketMQ等主流中间件源码。</li><li>主导过微服务拆分、全链路压测或DDD落地。</li><li>会vue Ant Design Vue 熟悉。</li><li>有PHP开发工作经验优先。</li></ol>', '5-10年', 'd0d4eb8f498a1f040nB43NS_EltT', '深圳 · 宝安区 · 宝安中心区', '12-20K·13薪', 'Java, 不接受居家办公, 分布式经验, SpringCloud, MySQL, PHP, MyBatis, 架构设计经验, Spring, 游戏后端经验', '资深java开发工程师(支付系统)', 'https://www.zhipin.com/job_detail/d0d4eb8f498a1f040nB43NS_EltT.html', '');
INSERT INTO `jobs` VALUES (491, '深圳美丽魔方机器人', '人工智能', '20-99人', '未融资', '本科', '<p>关于我们：深圳美丽魔方机器人有限公司隶属于美丽魔方健康投资集团（注册资本2.3亿），是专注于“机器⼈+具⾝智能+⽴体生态场景”的潜力独角兽企业。在粤港澳⼤湾区布局深圳、香港研发中心（5000+m²）及惠州、东莞智造基地（20000+m²）。构建了建了覆盖具身人形、陪伴助残、理疗康复、医疗超声、脑机干预、物联网数据中台六大核心产品线，并拓展教育、潮玩等智能生态定制服务，形成“技术-产品-平台-数据”产业闭环，致力于成为具身智能立体生态可持续化发展的领航者。</p><p><strong>岗位职责</strong></p><ol><li>核心业务开发：负责公司核心业务系统的需求分析、系统设计及代码落地，主导完成高并发、高可用的微服务模块开发（基于Spring Cloud Alibaba体系）。</li><li>前端架构与交付：负责面向C端/B端的管理后台及官网系统，基于Vue 3 + Nuxt.js进行服务端渲染（SSR）及前后端联调，并负责微信/支付宝小程序的研发与性能优化。</li><li>跨语言协同：除主力Java开发外，负责部分高性能网关、Sidecar或运维工具的Go语言模块开发与维护，解决特定场景下的性能瓶颈。</li><li>技术攻坚：解决开发过程中的技术难点（如微服务链路追踪、分布式事务、前端首屏加载性能、k8s/K3s集群资源调度等），并参与代码评审，保障代码质量。</li><li>云原生部署与运维：有k8s/K3s 的应用容器化部署使用、服务编排及CI/CD流水线维护，具备基础的SRE（站点可靠性）思维，保障生产环境的稳定迭代。</li></ol><p><strong>任职要求</strong></p><ol><li>后端功底（Java & 生态）- 本科及以上学历，计算机相关专业，5年以上Java开发经验。- 熟练使用JDK 21特性（如虚拟线程、Pattern Matching等），有实际项目落地经验者优先。- 掌握Spring Boot 3及其自动装配原理，有Spring Cloud Alibaba全家桶实战经验，熟悉技术的底层逻辑。- 熟练使用MyBatis-Plus、Redis、RocketMQ/RabbitMQ等主流中间件。</li><li>前端能力（Vue & 小程序）- 熟练Vue 3及Nuxt.js。- 熟悉TypeScript、Vite、Pinia等现代前端工程化工具。- 具备小程序原生开发经验，熟悉其审核机制、开放能力及性能调优。</li><li>云原生与运维以及AI- 熟练使用AI实现高质量的代码。- 熟练掌握Docker容器化技术。- 了解GitOps理念，熟悉CI/CD工具。</li><li>跨语言加分项（Go）- 具备Go语言实际开发经验，熟悉Gin或Echo框架，能够看懂或编写简单的Operator或网关中间件。 【加分项（优先考虑）】- 有Service Mesh（Istio/Linkerd）与k8s/K3s结合的实际经验。- 对JDK 21虚拟线程在高并发场景下的性能调优有深入理解。- 主导过微服务拆分或遗留系统重构项目。- 有开源项目贡献者优先，或拥有个人高质量技术博客。- 熟悉WebAssembly（WASM）在边缘计算（K3s）场景的应用。岗位</li></ol><p><strong>福利</strong></p><p>13薪，季度奖金，团建，不定期体检，加班补贴，生日金，下午茶等</p><p><strong>福利</strong></p><p>，更多细节详聊~</p>', '5-10年', 'bfef5d8c8c67f59e0nJ409-_FlJZ', '深圳 · 龙岗区 · 平湖', '16-26K·13薪', 'Java, SpringCloud, MyBatis, MySQL, 物联网经验, 微服务经验, ERP开发经验, Nacos, vue, AI', '全栈开发（AI+双休+13薪！机器人行业）', 'https://www.zhipin.com/job_detail/bfef5d8c8c67f59e0nJ409-_FlJZ.html', '节假日加班费, 餐补, 意外险, 节日福利, 零食下午茶, 年终奖, 工龄奖, 加班补助, 员工旅游, 带薪年假, 定期体检, 绩效奖金, 全勤奖, 交通补助, 团建聚餐, 补充医疗保险, 五险一金, 生日福利, 免费工装');
INSERT INTO `jobs` VALUES (492, '迈思', '通信/网络设备', '20-99人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责公司核心产品（DashCam/车载视频监控终端）后端服务架构设计及核心代码开发，重点攻克高并发设备接入、海量数据吞吐等技术难题。</li><li>基于Netty构建和维护⾼性能、⾼可⽤的TCP长连接服务端，负责设备协议的编解码（Codec）、粘包/拆包处理及通信链路稳定性优化。</li><li>深度参与音视频流媒体数据处理流程，包括RTP推流、H264/H265视频流解析、定位数据融合以及实时报警推送逻辑的实现。</li><li>负责后端微服务架构（Spring Cloud）的设计与调优，保障系统在终端设备大规模并发场景下的⾼可用性。</li><li>编写技术设计文档，参与系统性能瓶颈分析与排查，解决生产环境中的复杂网络故障。</li></ol><p><strong>任职要求</strong></p><ol><li>学历专业： 全日制本科及以上学历，计算机、软件工程、通信工程等相关专业。</li><li>语言与基础： 5年以上Java开发经验，精通Java NIO、多线程编程，深入理解JVM内存模型及性能调优。</li><li>精通Netty底层架构（线程模型、EventLoop、Pipeline机制），具有实际解决TCP粘包/拆包、网络闪断、心跳保活问题的经验4.熟悉TCP/IP协议栈，具备通过Wireshark等工具分析网络报文的能力。</li><li>后端技术栈： 精通Spring Boot、Spring Cloud及MyBatis框架；熟悉常用中间件（Redis、RocketMQ/Kafka）及关系型数据库设计与优化。加分项（优先考虑）：</li><li>熟悉JT/T 808、JT/T 1078协议，具备基于Netty实现部标协议解析的实际项目经验，了解车辆监控业务逻辑（注册、鉴权、位置上报、报警附件上传等）2.有DashCam（行车记录仪）、MDVR或车载终端相关后端开发经验，熟悉音视频流媒体传输（如RTP/RTCP/RTMP）及处理流程。</li><li>有高并发物联网（IoT）平台架构经验，处理过万级及以上设备长连接管理。</li></ol>', '5-10年', 'd197c3e79e0247830nJ60ty4GVtW', '深圳 · 南山区 · 科技园', '15-20K', 'Java, Netty, MySQL, Redis, PostgreSQL, 大数据经验, 物联网经验, 架构设计经验, 音视频经验, 不接受居家办公', 'Java后端工程师(纯技术向)', 'https://www.zhipin.com/job_detail/d197c3e79e0247830nJ60ty4GVtW.html', '生日福利, 节日福利, 五险一金, 带薪年假, 零食下午茶, 员工旅游, 团建聚餐, 定期体检, 年终奖');
INSERT INTO `jobs` VALUES (493, '久雅科技', '计算机软件', '100-499人', '不需要融资', '本科', '<p>+**1. 业务经验（必须）**+- 深厚的信用卡（Credit Card）应用开发经验+- 深厚的个人信用贷款（Personal Loan）应⽤开发经验+- 熟悉银⾏信贷业务外围流程及风控体系++**2. 产品与需求能⼒**+- 具备产品意识，能从业务视角理解需求，而非单纯写代码+- 需求分析清晰、快速，能独⽴拆解FSD/TSD并转化为技术方案+- 接口设计能力强，字段定义准确规范++**3. 技术能力**+- 技术栈：Java（必须）+- 熟练掌握AI辅助编程工具（如Claude、Copilot等），提升开发效率+- 具备系统间对接集成经验（核心系统、风控系统、征信系统等）+- 排查问题能力强，能快速定位生产及联调环境问题++**4. 个人素质**+- 细心，接口对接和字段映射零容忍出错+- 抗压能力强，能适应项目紧节奏和高强度交付+- 沟通协作好，能与行方、微众多方高效对接</p>', '5-10年', '4d846caec59eaa290nBy3920F1FY', '深圳 · 南山区 · 科技园', '18-20K', '信用卡, Java, SpringCloud, MySQL, 信贷', 'Java开发（银行信贷/信用卡业务）', 'https://www.zhipin.com/job_detail/4d846caec59eaa290nBy3920F1FY.html', '五险一金, 节日福利, 零食下午茶, 餐补, 加班补助, 带薪年假, 股票期权, 工龄奖, 团建聚餐, 定期体检');
INSERT INTO `jobs` VALUES (494, '航帆睿成', '电子商务', '20-99人', '未融资', '大专', '<p>负责后端微服务架构开发；实现与底层PLC、DCS及IoT设备的数据对接；负责高并发下的数据处理，精通Spring Cloud、有物联网开发经验</p>', '5-10年', '3df056e88c577da40nF92dW4EVFV', '深圳 · 南山区 · 科技园', '12-15K', 'Java, SpringCloud, MySQL, 物联网经验', 'Java开发', 'https://www.zhipin.com/job_detail/3df056e88c577da40nF92dW4EVFV.html', '零食下午茶, 员工旅游, 底薪加提成, 团建聚餐, 五险一金, 餐补, 带薪年假');
INSERT INTO `jobs` VALUES (495, '义合信达', '计算机软件', '100-499人', '未融资', '大专', '<p><strong>岗位职责</strong></p><ol><li>负责核心业务系统的设计与开发，参与技术方案的制定与评审；</li><li>承担高并发、高性能系统的编码实现与优化⼯作；</li><li>参与微服务架构的维护与演进，保障系统稳定性与可扩展性；</li><li>编写⾼质量、可维护的Java代码，持续提升代码质量；</li><li>协同团队完成系统集成、测试及上线⽀持工作。</li></ol><p><strong>任职要求</strong></p><ol><li>精通Java语言，熟练掌握Spring/Spring Boot/Spring Cloud等主流框架；</li><li>熟悉常⽤数据库如MySQL、Oracle等，具备SQL调优和事务处理能力；</li><li>掌握分布式系统开发模式，了解缓存、消息队列、服务治理等核心技术；</li><li>具备良好的面向对象设计能力，熟悉常见设计模式；</li><li>有较强的问题分析与解决能力，能独立承担模块开发任务。</li></ol>', '5-10年', '80f311d9ecb149820nF63du9FVpU', '深圳 · 宝安区 · 西乡', '8-13K', 'Java, Python, 不接受居家办公, Spring, MySQL, ai工具', 'java高级研发工程师', 'https://www.zhipin.com/job_detail/80f311d9ecb149820nF63du9FVpU.html', '');
INSERT INTO `jobs` VALUES (496, '深圳华鲲智界科技', '物联网', '100-499人', 'A轮', '本科', '<ol><li>统招本科学boss历，5年以上相关⼯作经验，有⼤项⽬开发经验;</li><li>JAVA基础扎实，熟悉JVM工作原理并掌握常见性能调优方法;</li><li>熟悉Spring、Mybatis等开发框架，熟悉常⽤中间件Tomcat、Mq等;</li><li>具备良好的文档编制习惯和代码书写规范，有团队管理经验佳。</li></ol>', '5-10年', '5e9a19cc97c371da0nF909W0FFNZ', '深圳 · 龙岗区 · 坂田', '15-26K·13薪', 'JVM, Java, SpringCloud, MySQL, MyBatis, SQL Server, Spring', '资深java开发工程师', 'https://www.zhipin.com/job_detail/5e9a19cc97c371da0nF909W0FFNZ.html', '定期体检, 五险一金');
INSERT INTO `jobs` VALUES (497, '中迈致远', '工程施工', '100-499人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责公司 后端微服务架构 的设计、开发和优化，确保系统的高可用性、可扩展性和高性能；</li><li>负责 微服务架构 设计与开发，熟悉 Spring Cloud、Dubbo、gRPC 等微服务框架，优化 服务拆分、负载均衡、服务治理；</li><li>参与产品系统设计，负责核心代码的⾼质量开发，快速响应业务需求，及时交付⾼质量的后端功能。</li><li>参与系统架构设计，优化后端性能，提升⽤户体验。</li><li>参与项目需求分析、设计和评审，输出高质量的设计和实现⽅案；</li><li>优化系统架构和数据库性能，提升接口效率，确保系统高效运行。</li><li>解决高并发和复杂业务模型带来的技术挑战，提供创新解决方案。</li><li>监控系统状态，及时发现并解决潜在问题，提升系统可靠性。</li><li>撰写和维护项目代码，遵循项目开发规范和团队协作规范。</li><li>负责后端服务的设计、开发与维护，确保系统稳定性和扩展性。</li><li>参与系统架构设计，与前端团队紧密合作，优化后端性能，完成接口对接并确保项目的整体用户体验，提升用户体验。</li></ol><p><strong>岗位要求</strong></p><ol><li>本科及以上学历，计算机软件或相关专业，8年以上后台开发经验，有1年以上管理经验。</li><li>精通Java开发语言，对于JVM、Java多线程、并发以及网络通信有深厚的经验，扎实的计算机基础，如操作系统、计算机网络、算法、数据库等，并能熟练使用AI编程助手(如GitHub Copilot、通义灵码等)提升研发效率。</li><li>设计和开发高性能、高并发的RESTful API接口，支持前端、移动端及第三方系统集成；</li><li>熟练使用Spring Boot/Spring Cloud 进行微服务开发，确保服务的稳定性和可维护性；</li><li>熟悉MySQL\\PostgreSQL数据库，熟悉Redis、MongoDB、Elasticsearch等NoSQL存储及相关性能优化；</li><li>熟悉Linux系统及常用操作系统命令，具备Shell脚本编写能力。</li><li>熟悉 Kubernetes（K8s） 及核心组件（如 etcd），能够基于 K8s + etcd 进行 分布式配置管理、服务注册与发现、数据一致性维护；</li><li>理解分布式系统基本原理，对消息中间件（如rocketmq\\kafka）的使用及底层实现。</li><li>具备系统整体架构设计能力，能够从长远角度考虑系统的稳定性、可用性和扩展性。</li><li>有丰富的互联网电商业务的交易系统(商品订单/支付)。</li><li>有高并发、大数据量处理场景的解决思路和实际经验者优先。</li><li>懂本地化部署、API接口。</li></ol>', '5-10年', '8527e84c5759dbab0nJ739y7GFBV', '深圳 · 福田区 · 车公庙', '15-25K', 'Golang, MES开发经验, Java, 物联网经验, C++, 团队管理经验, 不接受居家办公, C, SpringCloud, Kafka, Redis, Spring, 大数据经验, MySQL, MyBatis, MongoDB, 架构设计经验, Python', 'JAVA高级工程师', 'https://www.zhipin.com/job_detail/8527e84c5759dbab0nJ739y7GFBV.html', '员工旅游, 五险一金, 带薪年假, 年终奖, 免费班车, 通讯补贴, 节日福利');
INSERT INTO `jobs` VALUES (498, '风行趋势科技', '互联网', '100-499人', '未融资', '本科', '<p><strong>岗位职责</strong></p><p>1.负责核⼼业务系统的Java开发与迭代维护2.负责与硬件通信相关功能开发</p><p><strong>任职资格</strong></p><p>1.5年以上Java项⽬开发经验，熟悉SpringMVC，Spring Boot框架体系，熟悉Redis,RabbitMQ,Mysql,SQLServer等⼯具2.掌握Linux/windows服务器环境配置4.计算机相关专业学历5.独立负责过一个完整的后端开发项⽬，并落地生产6.有过硬件通讯相关开发经验优先7.有c#或c++开发经验优先8.有AI相关项目或AI辅助编程开发经验优先</p>', '5-10年', '60b5329648a07c5b0nB70ty0FFNR', '深圳 · 宝安区 · 新安', '12-18K', '', 'java中级开发工程师', 'https://www.zhipin.com/job_detail/60b5329648a07c5b0nB70ty0FFNR.html', '餐补, 员工旅游, 年终奖, 定期体检, 带薪年假, 包吃, 交通补助, 五险一金');
INSERT INTO `jobs` VALUES (499, '钛马', '互联网', '100-499人', 'B轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>平台核心开发：负责大数据平台（如数据门户、指标平台、数据资产平台、数据集成、AB测试、埋点管理等）的需求分析、系统设计、核心模块编码与测试，并确保高质量的交付。</li><li>架构与优化：深⼊理解业务需求，设计并实现⾼可⽤、易扩展、高性能的平台架构与解决方案，持续优化平台性能与稳定性。</li><li>技术赋能：为数据开发、分析师及业务团队提供稳定、易⽤、可扩展的平台工具与服务，提升数据研发效率与数据质量。</li><li>运维保障：负责生产环境的部署、监控、故障排查与性能调优，快速响应并解决线上问题，保障平台SLA。</li><li>技术沉淀：编写清晰的技术文档，参与代码评审，分享最佳实践。</li></ol><p><strong>任职资格</strong></p><p><strong>任职要求</strong></p><ol><li>基本条件：计算机相关专业本科及以上学历，8年以上后端开发经验，5年以上大数据平台或数据中台相关系统开发经验。</li><li>核心技能： - 精通Java语言及生态，深入理解JVM、多线程、并发编程、网络IO。 - 精通Spring Boot、Spring Cloud等微服务框架，有大型分布式系统设计和开发经验。 - 熟练掌握MySQL/MSSQL/PostgreSQL等关系型数据库，以及Redis等缓存技术，具备优秀的SQL编写和优化能力。 - 熟悉Hadoop、Spark、Flink、Kafka等大数据组件原理，有相关应用开发经验。 - 熟悉Linux操作系统，能熟练使用常用命令进行问题排查和性能分析。 - 了解数据仓库建模理论、数据治理方法论或有相关平台（如数据质量、数据血缘）开发经验。</li><li>平台经验： - 熟悉大数据领域至少一个方向（数据集成、任务调度、数据治理、元数据管理）的常见技术栈。 - 有数据集成工具（如SeaTunnel、DataX、Sqoop）、任务调度框架（如DolphinScheduler、Airflow）的实际开发或集成经验者优先。</li><li>软性素质：具备优秀的问题分析解决能力、逻辑思维清晰、良好的沟通协作能力和强烈的责任心。加分项1. 熟悉K8S及vm运维，有相关项目经验加分。</li><li>对用户体验和开发者体验有追求，有前端（React/Vue）基础技能。</li><li>有开源贡献经验。</li></ol>', '5-10年', '2cc5c69c794678770nF80tS1GVNV', '深圳 · 福田区 · 车公庙', '17-18K', 'Java, Spring, SpringCloud, 不接受居家办公, MySQL, 微服务经验, 大数据经验, hive, spark, 数据中台, hadoop, 电商', 'Java大数据平台开发工程师', 'https://www.zhipin.com/job_detail/2cc5c69c794678770nF80tS1GVNV.html', '保底工资, 五险一金, 节日福利, 带薪年假');
INSERT INTO `jobs` VALUES (500, '亚太星通', '运营商/增值服务', '100-499人', '未融资', '本科', '<p>招聘岗boss位</p><p><strong>职责</strong></p><ol><li>核心开发:负责核心业务模块的需求分析、系统设计、代码编写及自测，确保项目按时⾼质量交付。</li><li>架构落地:参与系统架构的升级与优化，包括但不限于微服务治理、数据库分库分表、缓存架构设计、消息中间件应⽤等，解决系统性能瓶颈和⾼并发问题。</li><li>质量保障:编写单元测试、接口测试，参与Code Review，确保代码规范、逻辑清晰、健壮性高。对线上异常具备快速定位与修复能力。</li><li>⽂档沉淀:撰写清晰的技术设计文档(技术方案、接口文档、部署文档)，沉淀技术资产。</li><li>团队协作:与产品经理、前端工程师、测试工程师及运维人员紧密协作，理解业务痛点，提出合理的技术解决方案。</li><li>技术引领(高级侧重):指导初级工程师成长，主持技术方案评审，引入新技术或工具提升团队整体研发效招聘</li></ol><p><strong>岗位要求</strong></p><ol><li>学历专业:统招本科及以上学历，计算机、软件工程等相关专业。</li><li>经验年限:5年以上后端或核心系统研发经验。</li><li>语言基础:扎实的编程功底，精通Java (Spring Cloud/Spring Boot)、Go (Gin/Grpc)中的至少一种语言。熟悉JVM底层原理(针对Java方向)或Go的并发调度机制。</li><li>数据库:精通关系型数据库(MySQL/PostgreSQL)的SQL优化、索引优化;熟悉至少一种NoSQL(Redis/MongoDB/Elasticsearch)，并了解其应用场景与底层原理。</li><li>中间件:熟悉常用中间件，如Kafka/RocketMQ、Redis、Nginx等，具备实际调优经验。</li><li>架构能力:熟悉分布式系统设计原则(CAP理论、BASE理论)，有微服务、高并发、高可用系统设计实践经验。</li><li>工具链:熟练使用Git、Maven/Gradle、Docker、Jenkins等开发与持续集成工具。</li><li>AICoding:熟练使用至少一种AI编程工具，并掌握驱动AI进行编程的核心能力。加分项：</li><li>有高并发、低延时场景(如秒杀、支付链路、实时计算)的实际处理经验。</li><li>熟悉云原生技术栈(Kubernetes, Istio, Serverless)或有实际上云(AWS/Azure/阿里云)经验。</li><li>有大数据处理经验(Flink/Spark/HBase)或AI工程化(模型部署、Prompt Engineering)经验。</li><li>开源社区贡献者或活跃技术博主。</li></ol>', '5-10年', '4a9859fa29c1b2430nZz0t2_FVVY', '深圳 · 宝安区 · 宝安中心区', '16-26K·15薪', '', '软件研发工程师', 'https://www.zhipin.com/job_detail/4a9859fa29c1b2430nZz0t2_FVVY.html', '交通补助, 通讯补贴, 生日福利, 高温补贴, 带薪年假, 全勤奖, 补充医疗保险, 年终奖, 定期体检, 节日福利, 团建聚餐, 五险一金');
INSERT INTO `jobs` VALUES (501, '厦门乐创', '移动互联网', '20-99人', 'A轮', '本科', '<ol><li>本科以下请勿投递2.超过年限太多的请勿投递3.非移动互联网行业请勿投递目前简历筛选均为AI执⾏，以上情况投递简历，均是已读不回，即使投递了简历，AI也不会转发到内部IM，请⼤家留意。</li><li>负责视频直播平台的后端架构设计与核⼼开发，确保系统的高并发、高可⽤性和低延迟；</li><li>负责直播流媒体服务（如 WebRTC、RTMP、HLS、FLV） 相关的开发、优化与维护；</li><li>设计并实现直播业务相关功能，如推流、转码、录制、回放、弹幕、互动等；</li><li>负责直播数据存储、缓存、分布式架构设计，优化系统性能和稳定性；</li><li>研究并集成主流直播 CDN 方案，提高视频传输质量与用户体验；</li><li>编写高质量的代码和技术文档，优化后端工程化，提高开发效率；</li><li>与前端、产品、运维团队紧密协作，推动产品快速迭代与优化。</li></ol><p><strong>任职要求</strong></p><ol><li>计算机相关专业本科及以上学历，5年及以上后端开发经验，具备扎实的计算机基础；</li><li>、熟练JAVA语言开发，Golang、C++、Ruby、Python语言中至少一种熟练使用；并有大规模系统开发经验；</li><li>熟悉 WebRTC、RTMP、HLS、FLV、MSE 等视频流媒体协议，有完整的直播平台或短视频产品开发经验优先；</li><li>熟悉 FFmpeg、GStreamer 等音视频处理工具，有转码、编解码、推流等开发经验；</li><li>熟练掌握 MySQL、PostgreSQL、MongoDB、Redis、Kafka 等数据库和缓存技术；</li><li>具备微服务架构设计、分布式系统开发经验，熟悉Docker、Kubernetes 等容器化部署技术；</li><li>熟悉 WebSocket、gRPC、RESTful API设计，具备良好的 API 设计能力；</li><li>具备良好的代码质量意识和开发规范，能高效解决系统瓶颈和技术难题。加分项•有超低延迟直播、视频 AI 处理相关经验；• 了解 CDN、边缘计算、P2P 直播加速等相关技术；•有高并发、大规模直播系统优化经验；•参与开源项目或有技术社区贡献（GitHub、技术博客、开源工具等）。</li></ol>', '5-10年', '28711e948b5f81c90nZ539W_FlNZ', '深圳 · 南山区 · 科技园', '18-25K·16薪', '', '高级后端工程师（社交）', 'https://www.zhipin.com/job_detail/28711e948b5f81c90nZ539W_FlNZ.html', '交通补助, 带薪年假, 节假日加班费, 加班补助, 团建聚餐, 股票期权, 生日福利, 员工旅游, 五险一金, 零食下午茶, 年终奖, 绩效奖金, 餐补, 定期体检, 节日福利');
INSERT INTO `jobs` VALUES (502, '拓龙国际', '跨境物流', '100-499人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>参与AI开发*使用 Claude Code, Codex, Cursor, GitHub Copilot等AI编码工具，参与日常功能开发和问题修复。*将需求拆分为具体开发任务，并使用AI⼯具辅助完成代码编写。*对AI⽣成的代码进⾏阅读、测试、修改和补充，确保功能可以正常使用。*协助整理常用Prompt、开发规范、问题记录和项⽬文档。</li><li>参与后端、前端和数据库开发*开发Java后端接口、基础业务逻辑和数据处理功8。*开发React前端页面，包括列表页、表单页、详情页和基础后台管理页面。*根据已有设计稿、接口文档或需求说明，完成页面修改、字段调整、接口联调和Bug修复。*编写和维护SQL，包括建表、查询、数据核对和简单数据修复。*在Code Review指导下学习代码规范、模块划分和常贝多开发方式3.测试与项目支持*启动本地开发环境，完成基础功能测试和接口测试。*根据测试反馈定位问题，协助修复Bug并验证修复结果。*按团队要求维护功能清单、开发进度、问题记录和简单技术文档。*按Git 规范提交代码，通过分支和Pull Request参与团队协作。*完成基础 Docker部署、环境配置和日志排查工作。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历;计算机、软件工程、信息管理、数学、自动化等理工类专业优先。</li><li>有一定编程基础，熟悉至少一门编程语言;Java基础较好者优先。</li><li>了解Java Web 开发基础，接触过 Spring Boot、MyBatis、RESTful API等技术，能够完成简单接口开发或Batis、RESTfulAPI等技术，能够完成简单接口开发或项目练习。</li><li>了解前端基础知识，接触过React、TypeScript、JavaScript、HTML、CSS中的一部分即可;能够阅读和修改基础页面代码。</li><li>会写基础 SQL,了解 MySQL或 PostgreSQL,能够完成简单查询、表结构设计和数据处理。</li><li>会使用Git进行代码管理,了解clone、branch、commit、push、pull、merge等基础操作。</li><li>使用过至少一种AI编码工具，例如Claude Code、Codex, Cursor, GitHub Copilot, ChatGPT 或 Gemini;愿意学习如何通过AI提高开发效率。</li><li>具备基本英文阅读能力，能够借助翻译工具阅读技术。文档、报错信息和开源项目资料。</li></ol>', '5-10年', '90fc348f5347a12f0nF90tS-EFJQ', '深圳 · 龙岗区 · 大运', '15-25K·13薪', 'Java, 分布式经验, PostgreSQL, SpringCloud, SQL Server, Spring, 大数据经验, MySQL, MyBatis, 云计算经验, MongoDB, 架构设计经验, Oracle, 区块链经验, Python', 'AI 全栈开发工程师', 'https://www.zhipin.com/job_detail/90fc348f5347a12f0nF90tS-EFJQ.html', '补充医疗保险, 年终奖, 绩效奖金, 团建聚餐, 带薪年假, 员工旅游, 通讯补贴, 节日福利, 五险一金, 底薪加提成, 零食下午茶, 生日福利');
INSERT INTO `jobs` VALUES (503, '广州悦羚设计工程', '装修装饰', '20-99人', '未融资', '本科', '<p>要求6年以上开发经验，有SRM供应链系统开发经验，熟悉springboot、springcloud、Redis、MyBatis-plus</p>', '5-10年', '914675e936c8a5d70nFy2Ni_E1tT', '深圳 · 宝安区 · 石岩', '11-15K', 'Java, SpringCloud, Docker, MySQL, Redis, MES开发经验, ERP开发经验, SRM', 'Java', 'https://www.zhipin.com/job_detail/914675e936c8a5d70nFy2Ni_E1tT.html', '五险一金');
INSERT INTO `jobs` VALUES (504, '深圳沃浦思必特信...', '计算机软件', '0-20人', '不需要融资', '本科', '<p><strong>职位描述</strong></p><ol><li>参与系统的开发、优化与维护，确保系统在高并发、高负载的环境下稳定高效运行；</li><li>关键技术研究和攻关，提供技术指导和⽀持；</li><li>参与技术⽅案设计，主导关键技术难题的攻关与技术创新，与产品、前端、测试等紧密合作，确保系统的开发与上线顺利进⾏。</li><li>系统架构的持续优化和重构，提高系统的容错能力和可维护性，确保系统在复杂环境下的稳定运⾏；</li><li>参与分析性能瓶颈，定位系统问题，并通过代码优化、并发控制、数据库优化等手段，提升系统性能；</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机、软件工程、电子信息等相关专业；</li><li>5 年以上后端开发经验；</li><li>有高并发、低延迟系统设计和开发经验，熟悉系统的业务流程和核心技术；</li><li>熟悉分布式系统设计，掌握消息队列、数据库（如 MySQL、Redis，mongodb，PostgreSQL 等）及缓存技术，能够设计和优化大数据量高并发系统；</li><li>熟悉高性能计算、内存管理、并发编程，有独立解决问题的能力；</li><li>有 java 大数据查询、高并发优化及 jvm 性能调优的经验，能够有效解决系统瓶颈；</li><li>基础扎实，精通 Java 并发编程、JVM，理解网络通信、多线程等基础框架，对各种开源开发框架如 Spring boot、mybatis，springcloud，zk，kafka 等开发体系有深入的应用和优化经验，掌握它的原理和机制；</li></ol>', '5-10年', 'fd3c4d569724893f0nF93Ni7E1pT', '深圳 · 福田区 · 会展中心', '18-22K', 'Java, Golang, Spring, SpringCloud, Elasticsearch, JVM, MySQL, PostgreSQL, MongoDB, Redis, 架构设计经验, 大数据经验, 分布式经验, 微服务经验, 云计算经验, 后端开发经验, 并发编程', '高级Java开发工程师', 'https://www.zhipin.com/job_detail/fd3c4d569724893f0nF93Ni7E1pT.html', '节假日加班费, 保底工资, 绩效奖金, 年终奖, 五险一金, 全勤奖, 定期体检, 法定节假日三薪');
INSERT INTO `jobs` VALUES (505, '福瑞仕', '互联网', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><p><strong>任职要求</strong></p><ol><li>5年以上JAVA开发经验，计算机相关专业；</li><li>计算机基础扎实;</li><li>有大型系统的设计和开发经验，有大数据量、高并发、高可⽤系统的设计开发经验优先4、熟悉JAVA体系架构，精通主流的开源框架，熟悉基于J2EE的WEB架构设计，熟悉Web开发流程，有丰富的spring，mybatis，springboot，spring cloud，redis等经验；</li><li>熟悉Maven，Git，SVN，jenkins，nginx等相关软件⼯作经验；</li><li>曾任Team Leader，有相应的⼩团队项目管理经验7、熟悉数据库建模，并具有很强数据库设计、管理、优化经验和SQL功底，有丰富的MyCat，MySql使用和调优经验，有千万级数据量以上的应⽤研发经验；</li><li>逻辑分析能力、学习能力和创新能力强，具有团队合作精神.</li><li>负责领导小组进行项目开发，并按照开发规范，标准、严格地保证项目质量;</li><li>负责后端系统微服务化、组件化。</li><li>参与小组的产品需求设计讨论4、编写符合规范的技术文档及维护手册。</li></ol>', '5-10年', '58512a97b0b5f5540nF829u0F1BQ', '深圳 · 龙岗区 · 坂田', '14-21K', '不接受居家办公, Java, Spring, MyBatis, Nginx, Docker, MySQL, Redis, MongoDB, 团队管理经验, 架构设计经验, 微服务经验, 物联网经验', '资深Java工程师', 'https://www.zhipin.com/job_detail/58512a97b0b5f5540nF829u0F1BQ.html', '股票期权, 员工旅游, 年终奖, 项目奖金, 零食下午茶, 五险一金, 节日福利');
INSERT INTO `jobs` VALUES (506, '深圳惟创信息技术', '计算机软件', '20-99人', '', '大专', '<ol><li>参与公司核心系统的Java开发，确保代码质量和系统稳定性；</li><li>负责 ERP 系统架构设计、优化及维护，提升系统性能和可扩展性；</li><li>与产品、测试等团队紧密合作，确保需求的有效实现和快速迭代；</li><li>参与技术难题攻关，提出创新性解决方案，推动技术进步。</li></ol><p><strong>任职要求</strong></p><ol><li>计算机相关专业专科及以上学历，5 年以上Java开发经验；</li><li>精通Java语言及Spring Boot、Spring Cloud等主流框架；</li><li>熟练使用 Ts、vue3 等前端主流框架4. 具备良好的编码习惯，重视代码质量和系统优化；</li><li>具有较强的团队协作能⼒和问题解决能⼒，能够承受⼀定的工作压力。</li><li>必须要有熟练的 AI 协作能⼒</li></ol>', '5-10年', 'ae36bd5872c68e2e0nB62d61ElFT', '深圳 · 宝安区 · 西乡', '14-16K', 'Java, Spring, MySQL, vue3, Ai协作', '高级java', 'https://www.zhipin.com/job_detail/ae36bd5872c68e2e0nB62d61ElFT.html', '');
INSERT INTO `jobs` VALUES (507, '上海芷荆贸易有限公司', '证券/期货', '20-99人', '不需要融资', '本科', '<p>5年以上Core Java解决方案设计和应用开发经验扎实的Spring Framework、Spring Boot/Spring Cloud及事件溯源（Event Sourcing）实现知识熟悉常用Java框架和构建工具，如Spring、JPA/MyBatis/Hibernate、Maven等精通Kafka的使⽤，了解Kafka架构熟悉RESTful APIs/gRPC和WebSocket熟悉测试框架和库，如Junit5、Mockito熟悉PostgreSQL的操作熟悉微服务设计原则，有实际的微服务项⽬经验熟悉Docker和Kubernetes的使⽤理解OAuth 2.0或OpenID Connect 1.0者优先熟练掌握代码版本控制工具Git良好的沟通和人际交往能⼒积极的问题诊断能力和创造性的解决问题技巧良好的英语能力者优先计算机科学或相关学科学士学位在Github或其他SCM上有开源项目者优先有Python相关经验或知识者优先具备 AI 编程工具（例如 GitHub Copilot、Cursor、ChatGPT）的使用经验，并对大语言模型（LLM）的工作原理有扎实的理解，拥有此类经验者优先。拥有提示词工程（Prompt Engineering）经验，或具备将 LLM API 集成到企业级应用中的实战经验。有开源项目贡献经历，或在 GitHub/Stack Overflow 上拥有较高的活跃度/影响力。</p>', '5-10年', '16d508c31f772f5f0nd62Ny8FFJS', '深圳 · 福田区 · 会展中心', '15-30K', 'Java, 分布式经验, Docker, 微服务经验, SpringCloud, MySQL, Kafka, Redis, Spring', '中高级Java开发', 'https://www.zhipin.com/job_detail/16d508c31f772f5f0nd62Ny8FFJS.html', '零食下午茶, 加班补助, 节日福利, 团建聚餐, 餐补, 五险一金, 带薪年假, 员工旅游, 生日福利, 保底工资, 年终奖, 夜班补助, 节假日加班费, 有无线网, 法定节假日三薪');
INSERT INTO `jobs` VALUES (508, '深圳晟鸿科技', '移动互联网', '0-20人', '', '本科', '<ol><li>熟练使用java开发，mysql数据库2. 熟悉netty通信框架，spring boot, MQ,kafka通信等.</li><li>熟悉css，ajax，websocket，js前端开发者优先，熟悉vue者优先4. 有物联网，尤其是车联网后端开发经验者优先。</li><li>有高并发数据通信协议开发者优先。工作经验不足者勿扰，工作地点在深圳宝安西乡宝安，有意者联系本人：***********，应届毕业生不考虑</li></ol>', '5-10年', '0d975fe666b1014b03Fy09S7EFI~', '深圳 · 宝安区 · 西乡', '12-24K', 'Java, 后端开发', 'java 高级工程师', 'https://www.zhipin.com/job_detail/0d975fe666b1014b03Fy09S7EFI~.html', '');
INSERT INTO `jobs` VALUES (509, '好彩益', '智能硬件', '0-20人', '', '本科', '<p># 高级 Java 开发工程师（15K-25K / 可根据能力面议 招多名）##</p><p><strong>岗位职责</strong></p><ol><li>负责核⼼业务系统的架构设计、开发、性能优化及稳定性建设。</li><li>参与需求分析、技术⽅案设计及核⼼代码开发，推动系统持续演进。</li><li>负责高并发、高可⽤系统的设计与优化，解决线上复杂技术问题。</li><li>负责数据库设计、缓存设计、消息队列、分布式事务等核心技术方案落地。</li><li>推动代码质量建设，参与 Code Review，制定开发规范，提升团队研发效率。</li><li>配合测试、运维完成系统部署、监控、故障定位及性能调优。##</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，5年以上 Java 开发经验，具备大型互联网项目开发经验。</li><li>Java 基础扎实，熟悉 JVM、并发编程、集合、多线程、网络编程等核心知识。</li><li>熟练使用 Spring Boot、Spring Cloud（或 Spring Cloud Alibaba）、MyBatis 等主流框架。</li><li>熟悉 MySQL、Redis，具备 SQL 优化、索引设计、数据库性能调优经验。</li><li>熟悉 RabbitMQ、Kafka、RocketMQ 等至少一种消息队列，并了解其应用场景。</li><li>熟悉 Docker、Linux，具备线上系统部署、排障及性能优化经验。</li><li>具备良好的系统设计能力，能够独立完成模块设计及复杂业务开发。</li><li>具备较强的问题分析能力、责任心及团队协作能力。## 加分项- 有高并发、高可用系统开发经验。- 有微服务架构落地经验。- 有支付、订单、商城、游戏等核心业务开发经验。- 熟悉 Elasticsearch、ClickHouse 等中间件。- 熟悉 Kubernetes、Prometheus、Grafana 等云原生技术。- 有 AI Coding（Cursor、Codex、Claude Code、Copilot 等）实践经验。</li></ol>', '5-10年', '56eba55a9992b64f0nB9292-FFpZ', '深圳 · 宝安区 · 沙井', '15-25K', 'Golang, Java, 团队管理经验, 不接受居家办公, 分布式经验, SpringCloud, Redis, Spring, Docker, 微服务经验, MySQL, 架构设计经验, 游戏后端经验', 'Java', 'https://www.zhipin.com/job_detail/56eba55a9992b64f0nB9292-FFpZ.html', '');
INSERT INTO `jobs` VALUES (510, '舒特智杰', '通用设备', '100-499人', '不需要融资', '大专', '<p><strong>岗位职责</strong></p><ol><li>负责公司泛微OA系统的上线、实施及日常维护确保系统的稳定运行；</li><li>参与OA系统需求分析，根据业务需求设计并开发实现相关的管理系统，如：固定资产管理系统、绩效管理系统、员工生命周期管理系统、CRM系统、费控系统等；</li><li>通过OA系统打通ERP（用友）、SRM、MES系统，实现员工行为管理以及工作流程管理、数据统计与分析、工作决策；</li><li>日常工作协同流程优化。</li></ol><p><strong>任职要求</strong></p><ol><li>计算机、软件工程或相关专业大专及以上学历具备2年以上泛微OA系统开发经验，熟悉泛微OAEcology9的二次开发，如:表单定制、流程设计:接口集成、报表开发、单点登录、ecode组件开发等；</li><li>熟练掌握Java、SQL等开发语言，有较强的数据库设计及优化能力；</li><li>熟悉Web Service、API接口的开发及应用，具备集成系统的开发经验具备良好的沟通能力、团队合作精神和较强的分析问题和解决问题的能力;</li><li>对OA系统的功能、流程设计有深入理解，能够根据用户需求灵活实现相关功能有项目管理经验者优先；</li><li>能够独立完成项目的开发、实施和后续维护工作;具有强烈的责任心和积极的工作态度，能承受一定的工作压力。其它说明：公司处于高速发展阶段，机遇与挑战并存，诚邀有志之士加入。</li></ol>', '5-10年', '88f42dfb911a87a61H1z2NW1F1ZY', '深圳 · 宝安区 · 沙井', '13-16K', 'Java, PHP, Python, C#, Spring, SpringCloud, SQL Server, ERP开发经验, MES开发经验, 大数据经验', 'OA低代码开发工程师', 'https://www.zhipin.com/job_detail/88f42dfb911a87a61H1z2NW1F1ZY.html', '底薪加提成, 全勤奖, 有无线网, 定期体检, 生日福利, 通讯补贴, 宿舍有空调, 住房补贴, 带薪年假, 包吃, 保底工资, 法定节假日三薪, 意外险, 包住, 节假日加班费, 免费工装, 五险一金, 高温补贴');
INSERT INTO `jobs` VALUES (511, '港交所科技', '计算机服务', '100-499人', '不需要融资', '本科', '<p>Job Summary:We are seeking a highly motivated Java Developer to join our dynamic IT division. This role offers the opportunity to work on mission-critical systems that underpin Hong Kong’s financial infrastructure. You will be involved in the full software development lifecycle, collaborating with cross-functional teams to deliver innovative, secure, and scalable solutions.Job Duties:Design, develop, and implement next-generation clearing and settlement systems to support OTC derivatives.Maintain and enhance the OTC Clearing and Settlement System (OCASS), ensuring high availability and performance.Conduct unit, integration, and system testing; support user acceptance testing (UAT) phases.Work closely with business users, QA teams, and other IT units to ensure smooth implementation and delivery.Prepare and maintain comprehensive technical and functional documentation, deployment guides, and operational procedures.Identify opportunities for process automation and system optimization.Perform additional tasks assigned by the supervisor. Job Requirements:Bachelor’s degree in computer science, Information Systems, or related IT disciplines Minimum 5 years of hands-on experience in system development. Exposure to financial services or other highly regulated industries is an advantage.Strong proficiency in Java development. Experience in microservices architecture and cloud platforms (HCS preferred), including Kafka, Kubernetes, and containerized applications is preferred.Familiarity with DevOps tools and practices (e.g., Jira, GitLab, Nexus, JUnit, SonarQube, Docker).Knowledge of Spring Boot, GaussDB, Hibernate, and Linux scripting.Understanding of secure coding practices and performance tuning.Good command of written and good listening in English.Excellent analytical and problem-solving abilities.Strong communication and interpersonal skills; ability to work effectively in a team environment.Self-motivated with the ability to manage tasks independently under minimal supervision.</p>', '5-10年', 'd08f04737bcac3b90nB90tm4FlpX', '深圳', '19-30K', 'Java, Kafka, Docker', 'Systems Analyst - Post-trade Systems', 'https://www.zhipin.com/job_detail/d08f04737bcac3b90nB90tm4FlpX.html', '五险一金, 团建聚餐, 带薪年假, 年终奖, 定期体检, 节日福利, 补充医疗保险');
INSERT INTO `jobs` VALUES (512, '卡荟智能', '互联网', '20-99人', '不需要融资', '本科', '<p>【</p><p><strong>岗位职责</strong></p><ol><li>全端业务落地：具备独立完成H5/Web/APP前端界面的能⼒（Vue3/UniApp），能独⽴完成从前端交互到后端接口的全链路功能开发。</li><li>AI辅助研发落地（硬性门槛）：必须熟练使⽤Cursor或Claude Code等AI编程工具，能利用AI⼯具提升“前端页面编写”及“后端代码重构”效率，并能向团队输出AI最佳实践。</li><li>业务抽象与文档输出：能够直接对接管理层，将模糊的业务构想转化为详细的技术需求文档和开发任务。</li><li>团队规范与统筹：建立研发规范，具备团队管理经验或项目统筹潜力，推动系统长期平台化发展。【</li></ol><p><strong>任职要求</strong></p><ol><li>后端技术栈（必须精通）：</li><li>Java基础扎实，深入理解Spring Cloud Alibaba微服务生态。</li><li>熟悉PostgreSQL、Redis、Kafka/RocketMQ。</li><li>前端能力：熟练掌握Vue 3，UniApp，能独立搭建管理后台或移动端H5页面。</li><li>AI工具实操：拥有将AI融入日常编码的习惯。</li><li>软素质：极强的业务抽象建模能力，能从“写代码”上升到“做产品/搭平台”的思维层次。【优先条件】1.有支付、物联网、智慧社区/电商背景优先。</li><li>有0到1项目用AI全端开发经验者优先。</li></ol>', '5-10年', 'd44f3fa8719248cb0nd739--GFdW', '深圳 · 龙岗区 · 五和', '16-25K', 'Java, 物联网经验, 团队管理经验, Vue3, PostgreSQL, SpringCloud, Redis, SQL Server, 微服务经验, MySQL, 架构设计经验, UniApp, 区块链经验, Python', 'AI全端开发工程师（偏Java后端架构）', 'https://www.zhipin.com/job_detail/d44f3fa8719248cb0nd739--GFdW.html', '五险一金');
INSERT INTO `jobs` VALUES (513, '上海博达瑞科技', '互联网', '100-499人', '未融资', '本科', '<p>【岗位概述】负责开发和维护全球用户服务组相关系统的JAVA后端需求。</p><p><strong>任职资格</strong></p><ol><li>熟练使⽤ MySQL, Oracle 等至少一种数据库，具备良好的SQL编写及优化能⼒。</li><li>熟练使用 RabbitMQ, Redis, Kafka 等至少两种中间件，理解其使用场景与核心原理。</li><li>熟练使用 Linux 常用操作命令，能独立完成服务部署、日志排查及性能监控。</li><li>熟练使用 IDEA, Maven, Git 等开发与管理工具，具备良好的代码规范和工程化意识。</li><li>熟悉k8s的基本概念和操作流程，了解容器化部署。</li><li>有实际项目中使用AI代码助手的经验，熟悉基于大语言模型的代码生成、补全、解释及单元测试等常见AI辅助编程实践。其他1、有售后服务项目经验优先2、有AI智能体建设提效经验优先3、有.net 开发技术经验优先</li></ol>', '5-10年', '90f10cef01b1e9410nB439W5F1FT', '深圳 · 南山区 · 科技园', '15-20K', 'Java, 不接受居家办公, MySQL, Spring, Python', 'java开发', 'https://www.zhipin.com/job_detail/90f10cef01b1e9410nB439W5F1FT.html', '');
INSERT INTO `jobs` VALUES (514, '盛迪嘉支付', '互联网', '100-499人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>参与Java应用系统的开发与维护工作；</li><li>根据项目需求完成模块设计、编码实现及单元测试；</li><li>配合团队成员推进项目进度，完成阶段性开发任务；</li><li>对现有系统进⾏功能迭代、性能优化和问题修复；</li><li>编写相关技术⽂档，确保开发过程的规范性和可追溯性。</li></ol><p><strong>任职要求</strong></p><ol><li>具备扎实的Java编程基础，熟悉常⽤设计模式和开发框架；</li><li>能够在指导下独立完成开发任务，具备一定的问题分析与解决能⼒；</li><li>具有良好的沟通协作意识，能够融入团队并高效配合；</li><li>学习能力强，能快速掌握新技术并应用于实际工作；</li><li>对软件开发有热情，工作认真负责，注重代码质量。</li></ol>', '5-10年', 'd8435caad598815b0nd-2Ni0F1BX', '深圳 · 宝安区 · 西乡', '12-22K', '', '中级java开发工程师', 'https://www.zhipin.com/job_detail/d8435caad598815b0nd-2Ni0F1BX.html', '年终奖, 节日福利, 零食下午茶, 双休, 朝九晚六');
INSERT INTO `jobs` VALUES (515, '成都锋驰鸿科技', '批发/零售', '20-99人', '天使轮', '本科', '<p>【</p><p><strong>岗位职责</strong></p><p>】●参与后台服务的全生命周期研发，覆盖需求评审、技术方案设计、接口契约定义、编码实现、单元测试、联调与上线发布等环节，对交付物的性能、可用性、安全性与可维护性负责。●承担银行存款、贷款、账务等核⼼系统的接口开发与对接联调，跟进接口在⽣产环境的运⾏情况，保障接口稳定可用。●负责生产环境的问题排查与应急处理，通过⽇志分析、全链路追踪、数据核对等手段，独立完成账务差错的定位与处理，并推动事后复盘与改进。●参与系统的代码评审、技术文档编写、知识沉淀等团队协作工作，对历史代码或复杂模块进行安全、可控的重构与优化。●与产品、测试、运维以及业务方协同推进项目落地，对所负责模块的交付质量和上线效果负责。【</p><p><strong>任职要求</strong></p><p>】●计算机科学与技术、软件工程、信息系统、通信工程等计算机相关专业。从事5 年及以上 Java 后端开发经验。●有银行核心系统（存款、贷款、账务、清结算等任一方向）研发经验者优先。●精通 Java 及其主流生态，熟练运用 Spring Boot / Spring Cloud 进行微服务开发，深入理解 Spring 框架核心机制（IoC、AOP、声明式事务等）。熟练使用 Gradle 或 Maven 进行工程构建与依赖治理，能够独立处理多模块工程组织、私服配置等问题。熟悉 MySQL 或 TiDB，具备表结构设计、索引优化与 SQL 调优能力。●熟悉金融场景下的资金安全实践，包括长短款处理、幂等控制、对账机制等。具备较强的生产问题排查与应急处理能力，有过线上故障定位与修复的实战经验●编码规范，注重代码可读性与文档完备性，代码评审中能够主动发现并指出潜在风险。具备较强的代码阅读与逆向分析能力，能够在陌生代码库中快速厘清调用链路与业务逻辑。文档习惯良好，能够独立输出清晰的接口文档、设计文档、运维手册和复盘报告。薪资待遇：15-18k左右 面试定 入职五险一金上班时间： 早九晚六 午休2小时 双休</p>', '5-10年', '3663cffd600a8b570nJ429-4GFpZ', '深圳 · 南山区 · 科技园', '15-18K', 'Java, Spring, SpringCloud, JVM, MyBatis, MySQL, 架构设计经验, 分布式经验, 微服务经验, 不接受居家办公, 银行核心系统经验, TiDB', 'java开发工程师', 'https://www.zhipin.com/job_detail/3663cffd600a8b570nJ429-4GFpZ.html', '节日福利, 团建聚餐, 有无线网, 生日福利, 年终奖, 零食下午茶, 带薪年假, 餐补, 五险一金');
INSERT INTO `jobs` VALUES (516, '博铭维', '专用设备', '100-499人', 'B轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>分析项目业务需求，参与技术框架搭建以及技术选型，定期升级框架代码；</li><li>解决项目中相关的技术难题，问题分析，前后端系统性能优化及后期维护，维护系统稳定运行；</li><li>负责项目功能的开发，技术文档编写，参与代码评审及技术交流活动，促使提升技术团队整体水平。</li></ol><p><strong>岗位要求</strong></p><ol><li>计算机等相关本科及以上学历，5年以上工作经验，要求熟悉java全栈开发，精通前后端开发。</li><li>JAVA基础扎实，熟练io、多线程、集合等基础框架，并对JVM有一定深入了解，能对JVM做性能分析及调优；。</li><li>熟悉主流JavaWeb框架（Spring，springcloud，SpringBoot）；熟悉分布式消息队列（Kafka、RabbitMQ等），分布式缓存（Redis、Memcached），zookeeper等；掌握Mysql或Oracle数据库的开发、配置、管理、调试，熟练掌握SQL查询优化；</li><li>熟悉HTML.CSS.JAVASCRIPT等前端基础知识，熟练掌握Vue等相关技术5、 熟练常用的linux命令操作,常用shell指令,可以支撑开发、运维相关工作;</li><li>良好的面向对象设计能力，对互联网高并发、高可用和复用有一定的实践经验，有良好的代码编写习惯，逻辑思维清晰，能独立解决技术难点，工作认真负责；</li><li>对技术有所追求，善于学习，能够承受一定的工作压力，有自己的独立见解；逻辑思路清晰，工作认真负责，学习能力强，个性乐观开朗。</li></ol>', '5-10年', '3b628b0021a7394f03J_2tm0GVFZ', '深圳 · 龙华区 · 龙华', '17-20K', 'Java, 物联网经验, SpringCloud, MySQL, Spring, Oracle', 'java全栈工程师', 'https://www.zhipin.com/job_detail/3b628b0021a7394f03J_2tm0GVFZ.html', '节日福利, 团建聚餐, 带薪年假, 底薪加提成, 零食下午茶, 意外险, 绩效奖金, 生日福利, 年终奖, 定期体检, 五险一金');
INSERT INTO `jobs` VALUES (517, '致尚信息', '运营商/增值服务', '20-99人', '天使轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>独立对接产品与业务方，自主完成需求分析、技术方案与产品设计，并独⽴完成核⼼功能从0到1的开发落地，做到独当⼀面；</li><li>负责平台核心系统架构设计、演进与核⼼代码开发，为系统稳定性与技术方案最终兜底；</li><li>主导复杂业务技术方案设计与评审，确定服务拆分、数据模型及技术选型，支撑业务规模化发展；</li><li>熟练使用AI编程工具（如Copilot、Cursor、通义灵码等）辅助日常开发、代码生成与Review、测试脚本生成等，持续提升研发效率；</li><li>建立并推行开发规范，负责核心代码Review，指导初中级工程师，并具备团队管理能力，提升整体技术效能；</li><li>保障系统高可用与高性能，完成容量评估、预案制定，并作为线上问题第一响应人主导排查与复盘；</li><li>持续推动系统架构优化与研发流程改进，控制技术债务，提升工程质量与团队效率。</li></ol><p><strong>任职要求</strong></p><ol><li>计算机相关专业本科及以上学历，5年以上后端开发经验，具备高并发C端或复杂系统架构实战经验；</li><li>精通Java/Go等至少一门语言及生态，深入理解分布式、微服务、数据库、缓存、消息队列等核心技术；</li><li>具备复杂系统从0到1或大规模重构架构经验，有较强的技术判断力和决策能力；</li><li>具备日常大量使用AI编程工具辅助开发的实战经验，能显著提升个人与团队研发效率；</li><li>能独当一面：具备独立沟通业务、独立产品/方案设计、独立完成功能开发的能力；</li><li>具备系统稳定性建设、性能调优及复杂线上问题快速定位解决的经验；</li><li>逻辑严谨、理解能力强，抗压能力强，责任心强，具备良好的团队管理、技术指导及跨部门沟通协作能力。</li></ol>', '5-10年', 'e348eeafa329039c0nF909y7FlpV', '深圳', '15-20K', 'Java, 不接受居家办公, MySQL, 架构设计经验, Spring', '后端开发专家', 'https://www.zhipin.com/job_detail/e348eeafa329039c0nF909y7FlpV.html', '员工旅游, 带薪年假, 法定节假日三薪, 节日福利, 团建聚餐, 零食下午茶, 保底工资, 底薪加提成, 绩效奖金, 五险一金');
INSERT INTO `jobs` VALUES (518, '芯联天下', '互联网', '20-99人', '未融资', '本科', '<p><strong>岗位要求</strong></p><p>1 、 熟练掌握 Spring Boot、Redis、MySQL等，能够独立完成后端接口开发、数据库设计及性能优化2、 熟练掌握 Vue3 + Element Plus + CSS3，能够独立完成前端页面编写（从布局到样式到交互），并完成后端API对接3 、能够独立完成整个项⽬：后端使⽤ Spring Boot 搭建，前端使⽤ Vue3 开，独立完成从需求分析、技术选型、编码实现到部署上线的全流程4 、熟悉供应链业务场景（订单、库存、采购、财务等）或有类似复杂业务系统开发经验者优先5、具备良好的代码规范意识、问题排查能⼒及全栈自驱力</p><p><strong>任职要求</strong></p><ol><li>全日制本科及以上学历，计算机及相关专业，五年以上Java相关开发经验。（必须项）2、扎实的编程基础，精通Java开发语言，熟悉JVM、缓存、消息队列等;</li><li>熟悉分布式、多线程、高并发及高可用、设计、编码和调优;</li><li>有供应链行业经验优先.上班时间：周一至周五， 9:00--12:00 ，13:30---18:30</li></ol><p><strong>福利</strong></p><p>五险一金</p>', '5-10年', '4a7a069ad904878e0nF82dW8FFRQ', '深圳 · 罗湖区 · 笋岗', '10-15K', 'Java', 'Java+本科相关专业+5年开发经验', 'https://www.zhipin.com/job_detail/4a7a069ad904878e0nF82dW8FFRQ.html', '通讯补贴, 节日福利, 股票期权, 绩效奖金, 保底工资, 员工旅游, 零食下午茶, 双休, 带薪年假, 五险一金, 底薪加提成');
INSERT INTO `jobs` VALUES (519, '亿锦泰', '计算机软件', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责功能模块详细设计、架构设计及开发；</li><li>制定技术规范和操作流程，保障服务在高并发环境下的性能和稳定性；</li><li>解决各类潜在系统技术风险，保证系统安全、高可用、高性能运行；</li></ol><p><strong>任职要求</strong></p><ol><li>本科3年以上Java开发经验；</li><li>具备扎实的Java基础，熟悉JVM、多线程、NIO等技术的使用和原理3、精通SpringBoot、SpringCloud框架，了解前端框架vue4、熟悉MySQL数据库，熟悉Redis、MQ等组件，5、具有较强的沟通能力和学习能力，责任心和团队意识，能够承受较高强度的工作压力</li></ol>', '5-10年', 'e3892f9a03d2f65d1HN83dS7FFBQ', '深圳 · 龙华区 · 龙华', '10-13K·13薪', '不接受居家办公, Java, SpringCloud, MyBatis, Kafka, MySQL, Redis, 微服务经验', '中级java开发工程师', 'https://www.zhipin.com/job_detail/e3892f9a03d2f65d1HN83dS7FFBQ.html', '团建聚餐, 带薪年假, 绩效奖金, 五险一金');
INSERT INTO `jobs` VALUES (520, '紫金山互联网', '互联网', '20-99人', '', '本科', '<p>外派驻场岗位，目前是长期，具体看项目进度工作地点：深圳南山西丽负责业财⼀体化系统（如财务结算、预算管理、费⽤管控、税务申报等模块）的设计与开发，⽀撑集团级财务数据的高效处理与合规性要求。解决业财系统高准确性、数据⼀致性难题（如对账平账、审计追溯），保障交易数据的零差错处理。参与财务中台建设，推动模块化、配置化开发，支持多业务线（如电商、金融、供应链）的灵活接入与快速迭代。优化系统性能与稳定性。技术能力要求：本科及以上学历，计算机相关专业，4年以上Java开发经验，熟悉复杂业务系统架构设计。精通Java技术栈（Spring Boot/Cloud、MyBatis），熟悉JVM调优、多线程编程及高性能设计模式。掌握分布式系统开发（Dubbo/Spring Cloud Alibaba），熟练使用RocketMQ、Redis、Elasticsearch等中间件，熟悉MySQL/Oracle数据库，具备SQL优化经验，。有财务相关系统（如ERP、财务共享平台、费控系统）开发经验者优先。</p><p><strong>岗位职责</strong></p><p>1、负责核心业务系统（ERP系统、运营系统等）的设计、开发和维护工作2、参与系统架构设计，提供技术解决方案，确保系统的可扩展性、安全性和性能3、负责系统核心模块的代码编写，确保代码质量，编写技术文档4、解决系统运行中的技术难题，优化系统性能5、指导初级开发人员，促进团队技术能力提升6、跟进业务需求，参与需求分析和技术方案评审</p><p><strong>任职要求</strong></p><ol><li>本科及以上学历，5年以上Java开发经验，计算机相关专业优先2、精通Java核心技术，熟悉JVM原理及性能调优3、精通Spring、SpringBoot、MyBatis等主流框架4、熟练使用MySQL数据库，具备数据库设计和性能优化能力5、熟悉分布式系统设计，具备微服务架构实践经验6、熟悉Redis、RocketMQ等中间件的使用和优化加分项：</li><li>有跨境电商平台开发经验2、有大型分布式系统设计经验</li></ol>', '5-10年', '68db320c3b1ae5760nJ42tq9GFZS', '深圳 · 南山区 · 科技园', '12-15K', 'Java, 物联网经验, MySQL, Spring, 业财方向', 'Java开发工程师（业财方向）', 'https://www.zhipin.com/job_detail/68db320c3b1ae5760nJ42tq9GFZS.html', '');
INSERT INTO `jobs` VALUES (521, '某大型储能公司', '储能', '100-499人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责公司AI智能平台中ASR-Agent-TTS核心链路的后端架构设计与开发。</li><li>负责语音会话管理、流式交互、上下文管理、超时重试、失败降级、链路追踪等能力建设。</li><li>负责AI Agent核⼼能⼒开发，包括Prompt⼯程、Context工程、知识库检索、记忆管理、工具调⽤、工作流编排、MCP/Skill管理等。</li><li>负责多模型接入与模型路由能力建设，支持不同大模型供应商、不同模型能力和不同成本策略下的智能调度。</li><li>负责RAG知识库问答链路建设，包括文档处理、Chunk策略、Embedding、召回、重排、问答生成、效果评估等。</li><li>5AI链路质量指标建设，包括响应时延、召回命中率、问答准确率、失败率、Token成本、用户满意度等。</li><li>参与儿童内容保护、敏感词、合规审核、内容安全策略等平台能力开发。</li><li>与产品、前端、嵌入式、算法、硬件团队协作，完成AI玩具、AI音箱、桌面宠物等智能语音产品交付。</li></ol><p><strong>任职要求</strong></p><ol><li>5-8年以上后端开发经验，有iot或智能语音产品后端经验，Java基础扎实，熟悉Spring Boot、Spring Cloud或微服务架构。</li><li>熟悉HTTP、WebSocket、gRPC等通信方式，理解流式响应、异步任务、消息队列、超时控制、重试降级等工程设计。</li><li>熟悉MySQL、Redis、Kafka、MongoDB等常用中间件，具备良好的系统设计和问题排查能力。</li><li>有大模型应用、智能客服、知识库问答、RAG、Agent、工作流、搜索推荐、NLP应用等相关项目经验优先。</li><li>了解Prompt工程、上下文管理、Embedding、向量检索、模型调用、工具调用等AI应用开发概念。</li><li>精通Java，兼具Python或Go开发能力更好。</li><li>具备良好的产品理解能力和技术抽象能力，能够把AI能力工程化、平台化、可复用化。 加分项：</li><li>有AI智能硬件、AI语音助手、AI客服、知识库平台、Agent平台建设经验。 2</li></ol>', '5-10年', '7dd1b0076d9652470nJ739S-FFBR', '深圳', '15-25K·13薪', '不接受居家办公, Java, 物联网经验, 音视频经验', '后端开发工程师(iot/智能语音产品方向)', 'https://www.zhipin.com/job_detail/7dd1b0076d9652470nJ739S-FFBR.html', '绩效奖金, 定期体检, 员工旅游, 零食下午茶, 五险一金, 股票期权, 年终奖, 团建聚餐, 补充医疗保险, 带薪年假');
INSERT INTO `jobs` VALUES (522, '深圳云链数智科技', '互联网', '100-499人', '不需要融资', '本科', '<ol><li>计算机、软件工程等相关专业优先。</li><li>Java后端开发：精通Spring Boot/Cloud，具备8年以上微服务架构设计与开发经验，熟悉MySQL数据库设计与优化。</li><li>Vue前端开发：熟练使用Vue 2/3及相关技术栈，能够独立完成模块化、组件化前端开发，有大型管理系统前端实践经验。</li><li>系统设计能⼒：熟悉企业应⽤常见架构，能够进⾏数据库设计、API设计及系统性能优化，有高并发处理经验者优先。其他：</li><li>To B系统经验：拥有To B系统开发经验，参与过大型HR、SAAS、ERP、CRM等企业级系统的核⼼模块开发与迭代，参加主导开发过人力资源系统优先。</li><li>团队协作与沟通：具备良好的团队协作意识和沟通能力，能够与产品、测试等多角色高效配合，推动项目进展。</li><li>定位问题的能力：面对牵一发动全身的老系统，能精准定位，找到问题的真因。</li><li>主动完善的能力：不只是改问题，更要有心有力从技术层面提出“完善的解决方案”，主动推动系统好转，而不是恶性循环。</li></ol>', '5-10年', '6acea053d5dfae3e0nBy3t61EFFT', '深圳 · 福田区 · 车公庙', '15-30K', 'Java, Spring, MySQL, 架构设计经验', '高级java开发工程师', 'https://www.zhipin.com/job_detail/6acea053d5dfae3e0nBy3t61EFFT.html', '全勤奖, 绩效奖金, 五险一金, 年终奖, 补充医疗保险, 定期体检, 企业年金, 带薪年假');
INSERT INTO `jobs` VALUES (523, '拓能信息', '互联网', '20-99人', '未融资', '大专', '<p>JD如下所示：</p><p><strong>岗位职责</strong></p><ol><li>模块独立开发：负责产品核心业务模块的架构设计、前端页面实现与后端 API 接口开发，能够独⽴⾼质量完成需求交付。</li><li>全流程参与：参与产品从 0 到 1 的规划、设计、研发与上线全过程，协助梳理业务逻辑与技术⽅案。</li><li>技术栈维护：负责现有系统的维护、性能优化与重构，提升系统的可用性、稳定性和扩展性。</li><li>AI 赋能研发*：在日常开发中熟练运⽤ AI 编程工具（如 codex/opencode/workbuddy 等），提升代码产出效率与质量。</li></ol><p><strong>任职要求</strong></p><ol><li>基础条件与经验（1）工作年限：3年及以上全栈或后端/前端开发工作经验。</li><li>项目经验：具有完整参与 0 到 1 项目 的开发经验，具备独立按时完成模块研发的能力。</li><li>后端技术（主）（1）扎实的 Java*基础，熟悉面向对象设计原则与常用设计模式。</li><li>熟练掌握 Spring / Spring Boot / Spring Cloud等主流开发框架。</li><li>熟悉关系型数据库（如 MySQL、PostgreSQL），具备良好的数据库设计与 SQL 优化能力；了解 Redis 等缓存中间件。</li><li>具备良好的 RESTful API 接口设计与规范化文档编写能力。</li><li>前端技术（1）熟练掌握 HTML5、CSS3、JavaScript / TypeScript，熟悉响应式布局与跨浏览器兼容性。</li><li>具有实际 Vue (Vue 2 / Vue 3) 或 React 项目开发经验，了解相关生态（如 Router、Pinia/Redux、Axios）。</li><li>AI 编程与工程能力（重要）（1）熟练使用 AI 辅助编程：能有效利用 codex/opencode/workbuddy 等工具进行代码生成、重构、Debug 及单元测试编写，具备提炼高效 Prompt 的能力。</li><li>熟练使用 Git 进行代码版本控制与团队协作。了解基本 DevOps 流程，熟悉 Linux 基础命令及 Docker 容器化部署。</li><li>软实力（1）具备良好的业务理解能力、逻辑思维能力与沟通协调能力。</li><li>有强烈的主动性与责任心，具备良好的工程质量意识（注重代码规范与安全性）。</li><li>加分项（优先考虑）（1）熟悉微服务架构、消息队列（如 RabbitMQ/Kafka）或高并发优化经验。</li><li>具备 Node.js、Next.js 或 Nuxt.js 等全栈/SSR 框架开发经验。</li><li>有自己的开源项目、技术博客，或在开源社区有贡献者优先。</li><li>在实际项目中成功构建或搭建过基于 AI 的 Workflow / Agent 自动化流程。</li></ol>', '5-10年', 'd28e4d1d886feec60nJ709S-GVZY', '深圳 · 龙岗区 · 大运', '13-18K', 'Java, Python, SpringCloud, Docker, MongoDB, 微服务经验, 云计算经验, 分布式经验, 不接受居家办公, Node.js, AI Agent, AI coding', '全栈工程师-智能体开发', 'https://www.zhipin.com/job_detail/d28e4d1d886feec60nJ709S-GVZY.html', '节日福利, 团建聚餐, 五险一金');
INSERT INTO `jobs` VALUES (524, '遇创科技', '游戏', '20-99人', '未融资', '本科', '<p>职位概要： 负责手机物联网游戏项目后端开发及服务器运维工作。</p><p><strong>岗位职责</strong></p><ol><li>负责公司核⼼业务系统的设计、开发和持续优化；</li><li>和产品经理配合，深度参与产品需求讨论，功能定义等；</li><li>负责线上系统的运维保障⼯作，包括故障排查、性能调优及应急响应</li></ol><p><strong>任职资格</strong></p><ol><li>5年以上Java开发经验，深⼊理解JVM内存模型、GC调优、多线程并发编程、NIO/Netty网络编程，具备单体架构下高并发完整落地经验；</li><li>具备良好的问题分析与解决能⼒，有较强的责任心与团队协作精神，有过节假日/大版本上线重保经验，能在高压下快速定位并恢复线上故障；</li><li>熟悉腾讯云或其他云生态，熟练使用CVM、CLB、TKE（容器服务）、COS、MySQL、Redis、CKafka等核心产品进行云上部署与运维；熟悉Linux系统，有丰富的运维经验及线上故障快速定位能力；</li><li>精通MySQL、Redis及其他消息中间件，具备高并发SQL优化与缓存设计能力；熟悉游戏排行榜、实时计数、玩家状态缓存、设备异步上报、活动奖励发放等业务场景的方案设计。</li><li>熟悉前端技术栈，能排查并解决简单问题。优先：有手机游戏、IoT或智能硬件互动项目上线经验；熟悉Netty底层原理，具备长连接网关开发或调优经验；具备压测实战经验，能对长连接场景进行性能瓶颈分析与调优</li></ol>', '5-10年', 'e38ce2c280309b2d0nB82t--FlNS', '深圳 · 南山区 · 科技园', '12-16K·13薪', '', 'java开发工程师', 'https://www.zhipin.com/job_detail/e38ce2c280309b2d0nB82t--FlNS.html', '绩效奖金, 年终奖, 员工旅游, 节日福利, 带薪年假, 定期体检, 通讯补贴, 零食下午茶, 五险一金, 交通补助, 餐补');
INSERT INTO `jobs` VALUES (525, '深圳英弗拉斯科技', '大数据', '20-99人', 'A轮', '本科', '<p>本公司业务发展迅速,节奏紧紧张。候选人能接受单休再投递,谢谢!</p><p><strong>岗位职责</strong></p><ol><li>参与核心后端(下单/风控/赔率/报表等)功能迭代与重构,产出高质量API、批处理与异步任务,保证可灰度、可回滚、可观测。</li><li>在事件驱动架构下处理一致性:Kafka消费/幂等键、去重、Outbox/CDC、Schema演进。</li><li>进⾏性能与稳定性优化:SQL索引与执⾏计划、连接池、缓存策略、限流/降级/重试退避。</li><li>与QA/DevOps协同,完善测试⾦字塔(单测/契约/集成/e2e)与CI/CD流程。</li><li>完成WebSocket推送网关、分布式ID生成器（雪花算法变种）、动态线程池适配器等基础设施的开发。必备技能:</li><li>Java17+、Spring Boot,熟悉Maven/Gradle、分层架构、异常与错误码设计、配置分环境管理。</li><li>数据库与缓存:PostgreSQL(事务/隔离级别MVCC/VACUUM/索引策略)、Redis(TTL/⼀致性/热点Key治理)3、消息与并发:Kafka(分区/有序性/消费位点/再均衡/至少一次语义)、线程池与Future/CompletableFuture。</li><li>服务韧性:超时、重试、熔断、限流(如resilience4j),幂等策略与去重主键设计。</li><li>可观测性:结构化日志(Traceld)OpenTelemetry指标&链路、健康检查(liveness/readiness/startup)。</li><li>安全与合规:OAuth2/JWT基础、输入校验、防注入、密钥与凭据的最小授权与轮换。</li><li>容器与交付:Docker基础、K8s资源(Deployment/Service/ConfigMap/Secret),能读懂Helm/Kustomize输出。</li><li>有使用AI工具协助开发的实际经验(Cursor、Copilot等)进阶/加分项:</li><li>DDD基础(实体/聚合/仓储)、Protobuf/Avro+Schema Registry、Debezium CDC、ClickHouse报表。</li><li>灰度能力(蓝绿/金丝雀/特性开关)、契约测试(OpenAPI/PACT)。</li><li>体育数据/交易系统/封控系统经验。工作态度:</li><li>Owner意识:对交付结果和上线稳定性负责,能权衡\"速度vs质量\"。</li><li>创业心态:不确定场景下快速验证→复盘沉淀;避免\"个人秘笈\",偏好可复用与标准化。</li><li>节奏观念:关键里程碑/发布窗口可配合冲刺与阶段性加班(公司有调休/补贴政策);日常强调效率。</li><li>强文档意识:PRD/ADR/复盘(Postmortem)留痕可追溯。</li></ol><p><strong>福利待遇</strong></p><p>基础</p><p><strong>福利</strong></p><p>五险一金、带薪年假、法定节假日、定期体检、节日</p><p><strong>福利</strong></p><p>、生日</p><p><strong>福利</strong></p><p>；薪酬激励：绩效奖金、项目重构专项奖金、年终分红、定期调薪；成长</p><p><strong>福利</strong></p><p>技术培训、行业技术资料、内部技术分享、扁平化管理，无层级内耗；其他</p><p><strong>福利</strong></p><p>弹性工作制、下午茶、团建活动、加班补贴、内推奖励。</p>', '5-10年', '150b20b66f7d04e20nB-3du9GFBU', '深圳 · 南山区 · 科技园', '15-25K', 'Java, SpringCloud, MySQL, MyBatis, Spring, 体育赛事', '中/高级java工程师', 'https://www.zhipin.com/job_detail/150b20b66f7d04e20nB-3du9GFBU.html', '节假日加班费, 保底工资, 加班补助, 股票期权, 五险一金, 夜班补助, 法定节假日三薪, 全勤奖, 年终奖, 工龄奖, 绩效奖金');
INSERT INTO `jobs` VALUES (526, '云帆VR', '互联网', '0-20人', '天使轮', '大专', '<p>高级后端工程师招聘一、关于我们我们自研打造2.5D图像设计⼯具+AI模型聚合+Agent的设计效率⽣产⼯具，Mockuplabs.ai（海外访问+PC 端），服务海外千万级电商从业者，大幅提升电商设计效率与品质。 现诚邀资深后端工程师加⼊，独立负责后端及服务端相关工作，协同产品、前端等团队推进项目高效落地。</p><p><strong>二、岗位职责</strong></p><ol><li>负责海外用户体系、订单支付、资源管理等核心后端系统的架构设计、开发迭代与优化，结合 AI 工具产品特性，保障系统适配 AI 场景下的中型产品需求；</li><li>统筹海外服务器规划、环境部署、监控告警、数据备份及安全防护工作，结合 AI 服务的资源消耗特点，优化部署方案，保障服务端稳定运行，支撑 AI 功能的顺畅落地；</li><li>针对线上稳定性、性能瓶颈等各类技术问题，结合 AI 工具的业务逻辑，快速拆解复杂问题、做出合理取舍，高效完成排查与解决，保障 AI 服务的连续性；</li><li>协同产品、前端团队完成需求评估，重点对接图像 Agent相关功能需求，输出规范接口文档，保障 API 稳定可用，支撑 AI 功能的前端落地与交互；</li><li>独立完成中型需求的拆解、工时评估与风险预判，主动同步项目进度，及时暴露并协调解决项目风险，推动需求高效落地。</li></ol><p><strong>三、任职要求</strong></p><ol><li>具备互联网工具类产品后端开发相关经验，基础扎实，能够快速适配 AI工具类产品的开发节奏与业务逻辑；</li><li>熟悉后端开发语言，Python、Go、Java擅长任意一项均可，掌握后端开发核心技术，能够结合 AI 场景完成系统开发与优化；了解 MySQL、Redis、JVM 等基础原理，具备一定的设计与调优能力，满足 AI 服务的数据存储、缓存及性能优化需求；</li><li>熟练使用 Docker 容器化部署工具，熟悉 CI/CD 流程及监控体系，熟悉阿里云、Cloudflare 相关配置，能够保障海外 AI 服务的稳定运行；</li><li>具备 AI 工具使用经验，能够熟练运用 AI 工具辅助后端开发工作，包括但不限于代码编写、问题排查、需求分析等，借助 AI 提升开发效率与质量；</li><li>具备良好的跨团队沟通与协作能力；自驱力强，能自主规划工作，适配创业团队节奏，积极推动 AI 相关研究落地。四、加分项1. 拥有海外图形、图像处理类工具类产品开发经验。</li><li>重度使用 Claude Code/Codex 等 AI 编程工具，有 Agent 应用开发经验，熟悉 Agent 技术原理与落地场景，能够结合业务需求完成 Agent 相关功能开发；</li><li>有创业经历者优先，喜欢深度研究与探索，具备创业团队的工作思维与执行力，能够快速适配项目节奏，主动构建用户需求与价值；（配置团队期权）</li></ol>', '5-10年', '6a6ce59ea55c325f0nBz3d28GFNT', '深圳 · 福田区 · 上步', '18-28K·13薪', 'JVM, Java, 不接受居家办公, Docker, 微服务经验, 深度AI code, MySQL, Redis, 架构设计经验, Python, AI Agent', '高级后端工程师', 'https://www.zhipin.com/job_detail/6a6ce59ea55c325f0nBz3d28GFNT.html', '保底工资, 股票期权, 五险一金, 绩效奖金');
INSERT INTO `jobs` VALUES (527, '理想科技', '计算机软件', '20-99人', '未融资', '大专', '<p>职位概boss述：后端开发岗，参与业务数据流转全链路的开发，负责后端服务的设计与实现，同时承担数据采集、清洗及落库等数据开发工作，支撑上层业务的数据处理、统计与分析需求。</p><p><strong>岗位职责</strong></p><ol><li>后端服务开发:负责所属业务的后端功能设计、技术实现和日常维护，基于SpringBoot等主流框架搭建稳定、⾼效的业务服务。</li><li>数据全链路开发:参与业务数据流转全链路的开发，包括数据⾤集、清洗、转换(ETL)及落库;负责离线计算、实时计算等数据任务的开发与调度。</li><li>API接口开发4.性能与架构优化:负责复杂sQL调优、海量数据处理及系统性能优化;持续优化代码质量与系统架构，提升服务稳定性与扩展性5.数据治理与规范:参与数据治理⼯作，梳理业务数据链路，解决数据冗余、延迟、异常等问题，保证数据准确性、完整性和时效性。</li></ol><p><strong>任职要求</strong></p><ol><li>有3年以上Java后端开发⼯作经验2.精通Java 语言，熟练掌握 Spring Boot、Spring Cloud、MyBatis等主流开发框架3.熟悉Linux常用命令及Git协作工具数据开发能力:</li><li>熟悉数据全流程开发，了解ETL数据开发流程，具备数据清洗、转换、同步相关实战经验2.熟练掌握MySQL等主流数据库，精通SQL优化、索引优化、慢SQL治理3.了解数仓分层理论(ODS/DwD/DWS/ADs)，有调度平台(如DolphinScheduler)使用经验者优先</li></ol>', '5-10年', '583d7a7d96eb006d0nF_3t-8GVNQ', '深圳 · 福田区 · 石厦', '15-16K', 'Java, Spring, SpringCloud, MySQL, 大数据经验, 不接受居家办公', '高级java', 'https://www.zhipin.com/job_detail/583d7a7d96eb006d0nF_3t-8GVNQ.html', '五险一金');
INSERT INTO `jobs` VALUES (528, '点证科技', '互联网', '100-499人', '未融资', '大专', '<p><strong>岗位职责</strong></p><ol><li>负责核心交易系统技术架构设计与开发，解决系统存在的问题以及技术难点，设计、指导关键技术模块的开发，并对系统安全性、稳定性负责，确保产品的研发效率和质量；</li><li>对重大技术问题进行研发攻关，审核技术方案、规范和文档，保证技术成果质量；</li><li>与公司内部相关部门紧密配合，有效地促成跨部门合作，快速、高效推动各类系统项目落地。</li></ol>', '5-10年', '51b37e66ab47a3c503N82tq0GFFR', '深圳 · 福田区 · 车公庙', '16-20K', 'C#, Java, 团队管理经验, 不接受居家办公, 分布式经验, 证券, SpringCloud, Redis, Dubbo, Spring, 微服务经验, MySQL, MyBatis, 架构设计经验, Oracle, Python', 'java开发', 'https://www.zhipin.com/job_detail/51b37e66ab47a3c503N82tq0GFFR.html', '定期体检, 带薪年假, 女童鞋福利, 五险一金, 员工旅游, 餐补, 优厚奖金, 调薪, 年终奖, 节日福利, 包吃, 工作餐, 零食下午茶');
INSERT INTO `jobs` VALUES (529, '北京安信立融', '计算机软件', '100-499人', '不需要融资', '大专', '<ol><li>基于Java Web技术的企业级应用开发；</li><li>参与系统概要设计、数据库设计及系统核心编码；</li><li>参与需求、设计、代码及测试的评审；</li><li>快速，准确处理系统性能，生产等问题；</li><li>完成上级领导交办的工作、按时提交高质量代码，完成开发任务；</li><li>根据系统功能需求完成功能设计、表设计、开发方案文档及负责单元测试；</li><li>负责项目日常BUG排查和解决处理；【</li></ol><p><strong>岗位要求</strong></p><ol><li>熟悉并使用Vue、Element UI、Js、Jquery、Css、Jsp、Ajax、Json、Echarts等前端框架；</li><li>熟悉使用Tomcat/Eclipse/IDEA/SVN/Maven等工具的使用；</li><li>熟悉B/S架构，SpringMVC、MyBatis、JavaScript、Spring等常见开发技术，熟练使用Maven等项目构建工具，熟悉软件开发工程及设计模式；</li><li>掌握J2EE核心技术（包括JDBC、Java-mail、JMS、JSP、XML、Servlet、POI等）；</li><li>熟悉使用Linux操作系统并能完成系统部署；</li><li>能够参与撰写、整理设计和开发文档；</li><li>有较强的性能优化及问题排查、解决能力，能承受较强工作压力，责任心、计划执行能力强；</li><li>力和较强的团队合作意识；做事积极主动，勤奋好学，对互联网技术敏感，了解互联网最新技术；</li><li>有Activiti工作流实际开发经验优先、有过OA、CRM实际开发经验优先；</li><li>有金融相关系统经验优先；【薪资待遇】10k-15k，五险一金</li></ol>', '5-10年', 'ed9426ef8414231e03N63t25GVdR', '深圳 · 龙岗区 · 坂田', '10-15K', 'Java', 'Java', 'https://www.zhipin.com/job_detail/ed9426ef8414231e03N63t25GVdR.html', '五险一金, 带薪年假, 年终奖');
INSERT INTO `jobs` VALUES (530, '鲸舟', '电子商务', '0-20人', '天使轮', '本科', '<p>岗boss位</p><p><strong>职责</strong></p><p>负责信贷系统中渠道交易、资金风控等核心模块的设计、开发与迭代，保障系统稳定性与高性能；负责需求分析，进行系统架构、核⼼模块的详细设计，输出⾼质量技术⽅案；负责服务达到要求的功能性、性能、可靠性、可扩展性与可维护性标准，能承受高并发场景；负责解决系统中的关键问题与技术瓶颈，负责代码的部署、维护、监控与缺陷快速修复；负责根据开发计划，独立承担模块开发任务，并确保按时⾼质量交付。</p><p><strong>任职要求</strong></p><ol><li>统招本科及以上学历，计算机、软件工程等相关专业，5年以上Java服务端开发经验，有金融支付、信贷、风控等系统开发经验者优先；</li><li>Java核心、IO、多线程、集合；主流技术栈：SpringBoot、SpringCloud；必备中间件：至少一种消息队列（Kafka/RabbitMQ）、缓存（Redis）及Nginx；</li><li>熟悉Linux系统及常用命令，具备服务器部署、问题排查能力；</li><li>深入理解JVM原理、分布式系统设计、缓存与消息机制，具备高并发系统设计与调优经验；</li><li>代码规范严谨，具备良好的系统设计、性能优化及线上问题快速排查能力。岗位</li></ol><p><strong>福利</strong></p><p>薪资范围：18k-22k职位关键词 java,springboot ,springcloud</p>', '5-10年', '2bdbf211657fb6900nB52NS9EldR', '深圳 · 南山区 · 后海', '18-22K', 'Java, 不接受居家办公, SpringCloud, Redis, 架构设计经验', 'java 开发工程师', 'https://www.zhipin.com/job_detail/2bdbf211657fb6900nB52NS9EldR.html', '年终奖, 五险一金, 绩效奖金, 股票期权, 底薪加提成');
INSERT INTO `jobs` VALUES (531, '深圳市铨兴科技', '半导体/芯片', '100-499人', '', '大专', '<p>【</p><p><strong>岗位职责</strong></p><ol><li>负责WMS系统⽇常⽤户需求调研，设计性能良好、扩展性⾼、稳定可靠的IT模块和功能，并成功交付用户使用；</li><li>负责WMS与上下游系统（ERP、MES、OA等）的集成⽅案设计与实施；</li><li>负责WMS疑难问题分析和处理，及时响应，快速定位问题，解决问题；</li><li>组织用户进行系统功能测试及开展用户培训；</li><li>参与应用系统需求交付、代码开发、系统运维等相关管理流程的建设与刷新。【</li></ol><p><strong>任职要求</strong></p><ol><li>5年以上WMS系统实施项目管理经验，至少2年以上半导体行业WMS实施项目管理经验，有完整的半导体行业WMS项目从立项到上线验收、运维优化的全流程主导经验。</li><li>熟悉主流WMS系统（如SAP EWM、曼哈特、富勒、唯智等）的功能、架构及实施流程，具备WMS系统接口开发协调、数据迁移、系统配置相关经验。</li><li>精通.Net Core, Java等任一开发语言，熟悉Oracle、Sqlserver 、PostgreSQL等主流数据库的开发及运维；</li><li>具备良好的理解、沟通和协调能力，熟悉项目管理方法，具备PMP证书优先；</li><li>具备较强的抗压能力与服务意识，良好的团队合作精神。</li></ol>', '5-10年', '64a12bf6ed679cb90nF539y9GFFV', '深圳 · 坪山区 · 坪山', '14-19K', 'Java, 团队管理经验, 不接受居家办公', 'WMS系统开发工程师', 'https://www.zhipin.com/job_detail/64a12bf6ed679cb90nF539y9GFFV.html', '');
INSERT INTO `jobs` VALUES (532, '深圳文思智科科技', '计算机软件', '100-499人', '不需要融资', '大专', '<ol><li>统招专科及以上学历，3年以上Java开发经验。</li><li>熟练掌握Spring全家桶（Spring Boot, Spring MVC, Spring Cloud），具有分布式系统开发经验。</li><li>具备Vue实际项⽬经验，能完成后端接口开发及前后端联调。</li><li>有性能优化经验，熟悉Redis、RabbitMQ/Kafka等中间件的原理与使⽤。</li><li>熟悉MySQL/PostgreSQL等数据库开发，能编写⾼效SQL语句。</li><li>了解运用AI开发更优6. 具备良好的业务理解能力和逻辑思维能⼒，能快速理解ERP/MES等复杂业务场景。</li><li>具备良好的沟通能力和团队协作精神。</li></ol>', '5-10年', 'bcb049cae31bf6320nF90tS7EFpX', '深圳 · 宝安区 · 西乡', '13-16K', 'Java, SpringCloud, Spring, MySQL, ERP开发经验, 不接受居家办公', '中级全栈开发', 'https://www.zhipin.com/job_detail/bcb049cae31bf6320nF90tS7EFpX.html', '年终奖, 底薪加提成, 绩效奖金, 保底工资, 补充医疗保险, 五险一金');
INSERT INTO `jobs` VALUES (533, '深圳市数海云擎网...', '互联网', '20-99人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>深入理解业务需求，指导中级及初级工程师完成现有系统的升级改造，对系统架构进行中长期规划，给出路线图；</li><li>负责技术难题预研与攻关，解决系统中关键架构问题，保证系统稳定性。</li><li>负责核心技术问题攻关及新兴技术预研，组织内部和外部的培训，指导中⾼级⼯程师的研发⼯作，提升团队研发质量。</li></ol><p><strong>任职要求</strong></p><ol><li>全日制本科以上学历，5年以上互联网或软件企业Java研发经验，有2个中型以上项⽬的经验者优先；项目经验匹配者可放宽至大专 2、熟悉MySQL及数据库架构，具有实际的SQL调优经验，有Spark、ClickHouse、Doris、Flink、等国外常见大数据工具实战经验者优先；</li><li>基础扎实，深入理解java IO、多线程、JVM回收原理等，具有实际的jvm调优经验；</li><li>熟悉主流开源框架，如SpringCloud、SpringBoot、MyBatis、MyBatis-Plus等，熟悉Spring原理和实现机制；</li><li>熟悉常用的分布式中间件技术，包括消息队列、缓存等，例如rocketmq、rabbitmq、kafka、redis、zookeeper、es等；</li><li>熟悉分布式系统的设计与应用，对分布式、缓存、消息、事务处理有实际的应用及解决问题的能力，对微服务架构原理有较为深入的认识；</li><li>技术思路开阔，技术栈广，具有trade-off意识。掌握常用结构化存储优化能力；</li><li>对技术工作充满热情，有一定的抗压能力；</li><li>目前该岗位不考虑最近一份工作是外包的人员，只考虑做自研项目的。</li></ol>', '5-10年', '8eb90db54192d1450nF839q0F1tZ', '深圳 · 龙岗区 · 平湖', '18-25K', 'Java, 大数据经验, Elasticsearch, Zookeeper, SpringCloud, MySQL, Kafka, Redis, Spring', '中高级java后端开发工程师', 'https://www.zhipin.com/job_detail/8eb90db54192d1450nF839q0F1tZ.html', '团建聚餐, 年终奖, 底薪加提成, 保底工资, 员工旅游, 带薪年假, 五险一金, 零食下午茶, 绩效奖金');
INSERT INTO `jobs` VALUES (534, '深圳无疆技术服务', '互联网', '20-99人', '', '本科', '<p>Base：深圳 | 汇报对象：CTO关于这个岗位:我们是一家专注于租赁业务SaaS系统的科技公司，为租赁行业的商家提供从获客、签约、履约到资产管理的一站式数字化解决方案。租赁SaaS的业务形态有其特殊性——业务链路长、状态流转复杂、数据持续累积且极少物理删除。⼀笔租赁订单从创建到完结，可能跨越数⽉甚⾄数年，中间经历审核、签约、支付、出库、履约、到期处理、续租等多个环节，状态机设计复杂；与此同时，租约相关的流水、账单、操作⽇志等数据持续写入，几乎不删除，数据量只增不减，对数据库的压力日益明显。因此，我们需要的架构师不仅要懂高并发，更要懂复杂业务状态管理、长生命周期数据治理，以及如何通过AI提效来应对SaaS业务的多租户复杂场景。</p><p><strong>岗位职责</strong></p><ol><li>设计分布式事务方案，在高性能要求下保障租赁订单状态与财务流水的一致性。</li><li>建立全链路可观测性体系（日志、链路、指标三位一体），提升故障定位效率。</li><li>数据库治理与性能攻坚租赁业务的特殊性在于数据只增不减——每一笔租约产生的账单、操作日志、状态变更记录都持久保留。当前MySQL单表数据量已达千万级别，部分复杂查询（如多维度租约筛选、账单汇总统计）响应时间持续恶化。你需要主导数据库层面的整体治理方案，包括但不限于：</li><li>分析并优化慢查询与索引策略，梳理TOP SQL并逐条治理，重点关注多租户场景下的查询效率；</li><li>设计并落地分库分表方案，针对租约表、流水表、日志表等核心大表提前规划拆分策略，应对数据量持续增长带来的写入瓶颈与查询退化；</li><li>评估并引入异构存储方案（如Elasticsearch、ClickHouse、TiDB等），将全文检索、多维筛选、报表统计等场景从MySQL剥离，形成冷热分离、读写分离的混合存储架构；</li><li>制定数据库容量规划与监控体系，建立可预测的扩容机制。此项工作不限于DBA</li></ol><p><strong>职责</strong></p><ol><li>架构治理与系统重构1) 梳理现有微服务之间的调用关系，识别并优化因前期快速迭代形成的不合理依赖，降低系统耦合度，提升模块的内聚性。重点关注租赁核心域（订单域、计费域、库存域、履约域）的边界划分是否清晰。</li><li>参与核心业务域的领域建模与微服务边界梳理，推动合理的服务拆分与整合。租赁SaaS的状态机设计是重中之重，需要你参与设计并优化租约全生命周期的状态流转逻辑，确保状态变更的可追溯性与可维护性。</li><li>制定技术演进路线图，建立架构评审机制，持续推动系统可维护性的提升。</li><li>建立并维护架构决策记录（ADR），确保每一次重要技术选择都有据可查、有理可依。</li><li>技术团队赋能1) 通过架构评审、代码审查、技术分享等方式，提升团队整体设计能力与代码质量意识。</li><li>参与核心技术组件与中间件的选型决策，综合考量性能、成本、可维护性与团队技术惯性。</li><li>关注AI辅助研发工具的发展趋势，评估并引入适合团队的工具链，推动研发效能的持续提升。</li></ol><p><strong>任职要求</strong></p><ol><li>8年以上Java开发经验，3年以上分布式系统架构设计经验，有支撑百万级用户规模或万级TPS的实际项目经历。</li><li>深入理解Java并发编程模型与JVM内存管理机制，具备实际的性能调优经验，能够独立分析并解决GC问题、内存泄漏等底层故障。</li><li>熟练掌握Spring Cloud或Dubbo框架原理，具备阅读和排查框架源码的能力。</li><li>精通分布式事务常见方案（TCC、SAGA、本地消息表等），了解各自的适用边界与局限性。对Saga模式在长事务场景（如租赁签约流程）中的应用有实际经验者优先。</li><li>熟悉消息中间件（Kafka / RocketMQ）和缓存中间件（Redis）的底层机制，能够处理消息积压、热key、大key等典型问题。</li><li>对AI辅助开发工具有实际使用经验，能够熟练运用AI编程助手（如GitHub Copilot、通义灵码、Codeium等）提升日常编码效率，包括但不限于代码生成、重构建议、单元测试编写、文档生成等场景。</li><li>具备将AI能力引入研发流程的意识和实践经验，例如利用AI进行代码审查辅助、辅助生成技术文档、辅助慢SQL分析与索引建议等。</li><li>了解大语言模型（LLM）的基本原理与主流API（如OpenAI、通义千问、智谱等），能够评估并推动AI能力在业务场景或研发工具链中的落地。</li><li>具备基本的Prompt Engineering能力，能够通过结构化指令获得高质量的输出结果。</li><li>了解云原生技术栈（Kubernetes / Istio），有容器化部署经验者优先。</li></ol>', '5-10年', '37a56cc84bff096b0nFz3ty-GFNS', '深圳 · 福田区 · 车公庙', '15-20K', 'Java, Hibernate, 团队管理经验, SpringCloud, MySQL, Kafka, MyBatis, 云计算经验, 架构设计经验, Spring', '高级java架构师', 'https://www.zhipin.com/job_detail/37a56cc84bff096b0nFz3ty-GFNS.html', '');
INSERT INTO `jobs` VALUES (535, '广州九雏科技', '计算机服务', '20-99人', '', '本科', '<p><strong>工作职责</strong></p><ol><li>负责仓储机器人调度平台开发工作，根据业务规格说明书，能够快速进行代码实现；</li><li>主动按时⾼质量完成需求开发和⾃测；</li><li>配合PM⾼质量完成各项开发任务，包括不限于需求评审，系统测试用例编写，代码评审与问题或工单定位修改等。</li><li>熟练运⽤各种问题排查方法，快速定位系统问题根因并修复；</li><li>输出并分享高质量的交付文档进行知识沉淀。ESS方向6）对TCP通讯要有了解，因为要与硬件打交道如机器人、输送线、电梯等硬件；</li><li>需要了解一些算法；</li><li>会AI编程；</li></ol><p><strong>任职资格</strong></p><ol><li>全日制本科学历，计算机相关专业，3年及以上Java开发经验，JAVA基础扎实，熟练掌握io、多线程、集合等基础框架，熟悉JVM原理；</li><li>良好的团队合作能力，流畅的口头和书面表达能力，严谨的工作态度，有极客意识，求知欲强 ，思路活跃；</li><li>熟悉常用开源框架的原理和内部机制，如Spring Cloud等，能够熟练并合理使用；</li><li>熟悉数据库，redis、RPC等中间件，有良好的设计模式及实际落地能力；</li><li>自驱力强且有强烈的技术热情和钻研精神，热爱新技术；</li></ol>', '5-10年', '31560f70ab34aefb0nJ72dm9GVtS', '深圳 · 宝安区 · 西乡', '13-16K', 'Java, SpringCloud, JVM, Redis', 'java开发工程师（WES/ESS)', 'https://www.zhipin.com/job_detail/31560f70ab34aefb0nJ72dm9GVtS.html', '');
INSERT INTO `jobs` VALUES (536, '卓力', '计算机软件', '0-20人', '', '本科', '<ol><li>本科及以上学历，3年以上JAVA实际开发经验；</li><li>熟练掌握 Java 及面向对象设计开发，研究过优秀开源软件的源码并有心得者优先；</li><li>了解 SOA 架构理念、实现技术；熟悉常见MQ、Quartz，Axis等开源系统；</li><li>熟练掌握SQL语句的书写；</li><li>有较强的逻辑/概率思维能力，善于分析、归纳、描述、沟通、和解决问题；</li><li>高度的责任心和投入度，善于学习和与人沟通，为人正直、诚信，有较强的事业心，能够自我驱动；</li><li>要求到政府单位驻场开发。</li><li>优先考虑有软考证书的候选人（包括高级项目经理，架构师，设计师）</li></ol>', '5-10年', 'ea66b4f3b6b4e2bd1nV73N-6GVRT', '深圳 · 福田区 · 皇岗', '8-13K', '搜索引擎技术, Java, 分布式技术, 计算机软件, Redis, SSH, Struts, MVC开发', 'Java开发工程师', 'https://www.zhipin.com/job_detail/ea66b4f3b6b4e2bd1nV73N-6GVRT.html', '五险一金, 机关食堂');
INSERT INTO `jobs` VALUES (537, '纳贤猫技术公司', '广告营销', '0-20人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责AI驱动的全栈系统设计与开发，覆盖前端、后端及AI模型集成等核心模块。</li><li>参与智能化功能的研发，推动AI能力在产品各层的落地与优化。</li><li>编写高质量代码，构建稳定、可扩展的技术架构，保障系统高性能与⾼可⽤。</li><li>参与技术⽅案设计、需求分析和代码评审，确保研发流程规范高效。</li><li>探索并应用AI⼯具提升开发效率，包括代码生成、测试辅助、日志智能分析等场景。</li></ol><p><strong>任职要求</strong></p><ol><li>具备全栈开发能力，熟练掌握至少一种后端语言（如Go/Java/Python）和主流前端框架。</li><li>熟悉AI相关技术栈，有大模型应用或AI工具集成的实际项目经验。</li><li>具备良好的系统设计能力，能够独立完成模块设计与技术实现。</li><li>熟练掌握常见Web技术、数据库、缓存、消息队列等基础设施。</li><li>具备较强的学习能力和问题解决能力，能快速适应新技术与复杂业务场景。</li></ol>', '5-10年', '5221e928c6a83b250nF939W9EltR', '深圳 · 南山区 · 科技园', '18-25K', 'Java, 架构设计经验, 接受居家办公', '高级全栈AI开发工程师', 'https://www.zhipin.com/job_detail/5221e928c6a83b250nF939W9EltR.html', '有无线网, 定期体检, 底薪加提成, 绩效奖金, 保底工资');
INSERT INTO `jobs` VALUES (538, '深圳市盈凯鑫贸易', '互联网', '20-99人', '', '本科', '<p>一、岗位</p><p><strong>核心职责</strong></p><p>- 负责储能云平台前后端开发，聚焦设备数据上云、实时监控、数据可视化等核心功能- 基于Java技术栈实现后端接口，基于Vue实现前端页面开发- 对接储能设备（BMS/PCS等），处理简单协议解析与数据同步- 保障云平台稳定运⾏，排查常见技术问题，配合版本迭代⼆、</p><p><strong>任职资格</strong></p><p>- 本科及以上，计算机相关专业，3年左右前后端全栈开发经验- 后端：精通Java 8+，熟练使⽤Spring Boot、MyBatis，熟悉MySQL、Redis- 前端：熟练使用Vue（2/3）、ECharts，能独立开发后台页⾯与数据可视化- 有云平台、物联网或储能/电力相关经验者优先，能独立完成模块开发</p>', '5-10年', 'ab4852f3ff30b59d0nF939W6GFNX', '深圳 · 坪山区 · 坪山', '15-23K', 'Java, 物联网经验, MySQL, MyBatis, 云计算经验, Spring', '高级全栈开发工程师', 'https://www.zhipin.com/job_detail/ab4852f3ff30b59d0nF939W6GFNX.html', '');
INSERT INTO `jobs` VALUES (539, '商运通', '计算机软件', '0-20人', '未融资', '本科', '<p><strong>工作职责</strong></p><ol><li>独立承担Java后端模块的开发与迭代，确保代码符合规范并通过单元测试。</li><li>参与客户方的系统设计评审与需求拆解，输出可行性技术⽅案。</li><li>配合客户团队完成联调与上线⽀持，保障项⽬按时交付。</li><li>负责线上问题的排查与修复，维护系统的稳定性与安全性。</li></ol><p><strong>任职要求</strong></p><ol><li>计算机相关专业本科及以上学历，基础扎实。</li><li>具备3年以上Java后端开发经验，精通Spring Boot、MyBatis等主流框架。</li><li>熟悉MySQL/Oracle数据库设计与优化，掌握Redis等缓存技术的应用场景。</li><li>具备良好的沟通表达能力与服务意识，能快速理解客户需求。</li><li>接受驻场⼯作模式，适应客户现场的工作节奏与协作流程。</li></ol>', '5-10年', 'd15d7e9b5d62d5dc0nF80ti-FVpQ', '深圳 · 福田区 · 香蜜湖', '14-17K', 'Java, 微服务经验, MySQL, MyBatis, Spring', '高级Java后端工程师(驻场开发)', 'https://www.zhipin.com/job_detail/d15d7e9b5d62d5dc0nF80ti-FVpQ.html', '带薪年假, 五险一金');
INSERT INTO `jobs` VALUES (540, '中喻科技', '其他制造业', '20-99人', '未融资', '大专', '<p>我们正在寻找经验丰富、技术扎实的高级Java开发工程师。您将作为我们核心产品开发团队的关键成员，参与系统架构设计、核心模块编码与性能优化⼯作。如果您对⾼并发、分布式系统有深⼊理解，并且拥有电子商务，电子元器件B2B商城领域的开发经验，我们⾮常期待您的加入。</p><p><strong>岗位职责</strong></p><p>系统设计与开发： 负责公司核心业务系统（重点为电子元器件在线交易平台）的需求分析、架构设计、核心代码编写与重构。技术攻坚： 解决系统开发、运维过程中遇到的关键技术难题和性能瓶颈，保障系统的高可用性、高扩展性和安全性。性能优化： 对现有系统进行数据库优化、JVM调优、缓存策略优化等，提升系统响应速度和处理能力。团队协作与指导： 与产品经理、前端开发、测试工程师紧密协作，确保项目高质量交付；指导初中级工程师，进行代码审查，分享技术经验。技术预研： 关注业界新技术动态，并结合业务场景进行技术选型和落地实践</p><p><strong>任职要求</strong></p><p>工作经验： 8年及以上Java开发经验，具备大型分布式系统的设计和开发经验。核心基础： 精通Java，深入理解JVM原理、多线程、并发编程、集合框架、IO/NIO等。主流框架： 精通Spring Boot, Spring Cloud, MyBatis等主流开源框架，并了解其核心原理。数据库： 精通MySQL等关系型数据库，具备丰富的SQL优化、索引优化及分库分表经验。中间件： 熟练掌握Redis、RabbitMQ/Kafka、Elasticsearch等常用中间件的使用和原理。项目管理： 熟练使用Maven、Gradle构建工具，熟悉Git版本控制流程。架构能力： 熟悉分布式、微服务架构设计理念，对服务治理、熔断降级、链路追踪等有实践经验。问题解决： 具备优秀的分析问题和解决问题的能力，能独立承担复杂任务。带团队经验优先！！！有电子元器件、工业品或相关B2B领域的电商平台开发经验者优先。熟悉电商领域的核心业务流程，如商品SKU管理、库存管理、订单流程、支付对接、物流跟踪等。了解电子元器件行业的特殊业务场景，如型号匹配、参数搜索、替代料推荐、BOM单管理等。有从0到1主导或核心参与电商平台搭建经验者优先。</p><p><strong>综合素质</strong></p><p>具备良好的团队合作精神、沟通能力和强烈的责任心。有较强的学习能力和技术热情，能积极应对挑战。对代码质量有高标准、严要求。</p>', '5-10年', '7404992678aaf8a30nV83du_E1JR', '深圳 · 光明区 · 光明', '12-20K', 'Java, 物联网经验, 不接受居家办公, 团队管理经验, 分布式经验, PostgreSQL, SpringCloud, Redis, SQL Server, Spring, 微服务经验, MySQL, MyBatis, 架构设计经验', 'java工程师', 'https://www.zhipin.com/job_detail/7404992678aaf8a30nV83du_E1JR.html', '年终奖, 零食下午茶, 五险一金, 通讯补贴, 节日福利, 底薪加提成, 绩效奖金, 带薪年假');
INSERT INTO `jobs` VALUES (541, '中科飓风', '计算机软件', '20-99人', '', '本科', '<p>1、7年及以上相关⼯作经验，有项⽬从0~1建设经验的，可做系统架构设计2、Spring Boot与Spring Cloud Alibaba（Nacos / Sentinel / Gateway / Seata）全栈实战经验3、MyBatis-Plus、JPA 等主流 ORM 框架，具备复杂 SQL 编写与优化能⼒4、分布式事务（Seata AT/TCC、可靠消息最终一致），具备方案选型与落地经验5、数据库分区、读写分离、分库分表（ShardingSphere）、慢SQL与索引调优6、微服务治理体系：服务注册发现、配置中⼼、限流熔断、网关鉴权、链路追踪7、熟悉Kafka / RocketMQ / Elasticsearch 高并发中间件8、熟悉Mysql、Oracle、国产数据库、Redis等9、本科及以上学历，学信网可查</p>', '5-10年', '2321544184fa057e0nFy392-GFRZ', '深圳 · 南山区 · 蛇口', '10-12K', 'Java, 不接受居家办公, 微服务经验, SpringCloud, MySQL, SQL Server, 架构设计经验', 'java开发工程师', 'https://www.zhipin.com/job_detail/2321544184fa057e0nFy392-GFRZ.html', '节日福利, 年终奖, 五险一金, 带薪年假');
INSERT INTO `jobs` VALUES (542, '元凯科技', '生活服务(O2O)', '0-20人', '未融资', '本科', '<p><strong>职责描述</strong></p><ol><li>负责产品SaaS业务及其中台系统的总体设计与核心代码开发；</li><li>负责应用系统架构设计、系统框架搭建、开发规范制定，核心算法编写；</li><li>负责重构优化框架，解决现有技术框架的瓶颈，解决现有业务产品优化升级的技术问题等；</li><li>带领基础框架开发团队完成开发任务；</li></ol><p><strong>任职要求</strong></p><ol><li>统招本科及以上学历(学信网可查)，5年以上架构设计、重构优化经验，较强的沟通能力与团队协作能力；</li><li>有SaaS平台架构的经验和能力；有大数据、高性能、高并发、高可用系统的设计开发经验，有DDD经验者优先；</li><li>精通JAVA,扎实的Java编程基础，熟悉常用设计模式、多线程、JVM,包括内存模型、类加载机制以及性能优化，具有系统设计、系统架构能力；</li><li>熟练掌握数据库（mysql）、缓存（Redis）、消息队伍、负载均衡、分布式事务等技术，并能进行系统的调优和优化；</li><li>熟练掌握SpringBoot框架，两年以上SpringCloud微服务框架开发经验，深刻理解微服务原理及运行机制，并对服务拆分、服务间调用、服务治理有独特见解；不招聘所谓的民教网学历。一律做假处理。</li><li>有一定的服务器运维技术能力优先；</li></ol>', '5-10年', 'b0ea853bbfc55e191XJz3du9GFJR', '深圳', '14-17K', 'Java开发经验, 全栈工程师, 分布式系统开发经验, 中大型项目架构设计经验, MySQL, 架构师, Redis, 后端工程师, Spring', 'Java高级工程师', 'https://www.zhipin.com/job_detail/b0ea853bbfc55e191XJz3du9GFJR.html', '五险一金, 补充医疗保险, 全勤奖, 股票期权, 零食下午茶');
INSERT INTO `jobs` VALUES (543, '星创智己', '计算机软件', '20-99人', '', '大专', '<p><strong>岗位职责</strong></p><ol><li>精通springboot、Springcloud微服务框架，熟练掌握MySQL/SQLServer等数据库系统，熟练使用redis等缓存，Rabbit MQ队列 ；</li><li>熟悉TCP/IP、Websocket、MQTT等互联网和物联网的主流协议；</li><li>主导技术选型、难点攻关及核心JAVA程序的开发，能独挡一面；</li><li>跟进整个项目开发周期，保证项目顺利运营并不断优化和创新，及时提供技术解决方案；</li><li>负责开发过程中的相关文档审核，如：计划、需求规格、设计文档等；</li><li>对接产品经理，落实项目需求，向开发团队合理分配开发工作；</li></ol><p><strong>任职要求</strong></p><ol><li>计算机相关专业，全日制专科及以上学历，5年以上技术开发经验，2年以上技术管理经验；</li><li>负责过软件系统项目的总体设计、技术研发和项目管理，熟悉软件研发过程；</li><li>精通至少2门以上计算机编程语言、web端开发，精通通用设计模式、主流的关系、非关系型数据库、缓存等中间件，及微服务架构等技术，熟悉linux及内核、操作系统原理、网络、安全等领域技术；</li><li>业务理解能力强，具有高并发项目的架构经验，掌握容量规划、架构设计、性能优化；良好的组件级建模能力，能够设计复杂业务、大数据量的系统平台；</li><li>具备极强的团队精神和合作精神，优秀的表达、协调和组织能力。</li><li>优秀的项目管理能力，精通产品规划、业务需求、产品设计、系统开发、测试演练、运维支持、文档管理全流程管理；</li><li>有工作热情，具有良好的沟通技巧和团队合作精神，能承受工作压力、适应不同环境。</li></ol><p><strong>薪资福利</strong></p><ol><li>我们提供高于行业平均水平的薪酬，高薪+绩效奖金+项目奖金+股权激励；</li><li>员工依法享受国家的法定假日，如婚假、丧假、产假、工伤假等；</li><li>在公司连续服务满一年的员工可享受5天的带薪年假；</li><li>公司入职就买五险一金；</li><li>公司注重员工身心健康，鼓励劳逸结合，定期组织篮球、羽毛球等活动，6）国家法定节假日，如端午节、中秋节都会有精美礼品发放；</li><li>每月举办生日会，并有精美礼品赠送；</li><li>公司很重视团队建设，设立了团建基金，可享受拓展、市内外旅游等；</li><li>公司每年都会组织年会、发放年终奖和开工利是；</li></ol>', '5-10年', 'e0ab94487b06c1b31H142dy5F1NW', '深圳 · 南山区 · 科技园', '18-30K', 'Java, 不接受居家办公, 微服务经验, SpringCloud, MySQL, 架构设计经验, 区块链经验', '高级java架构师', 'https://www.zhipin.com/job_detail/e0ab94487b06c1b31H142dy5F1NW.html', '');
INSERT INTO `jobs` VALUES (544, '闪回科技', '互联网', '100-499人', 'D轮及以上', '本科', '<ol><li>参与国际部业务需求评审，完成boss后端技术方案设计、接口设计、数据库设计及开发排期评估。</li><li>负责 B2B回收相关业务模块开发，保证代码质量、性能、安全性和可维护性。</li><li>对接前端、测试、产品及第三方平台，完成接口联调、问题定位和上线支持。</li><li>负责订单、支付、商品、库存、⽤户等核⼼链路的稳定性建设，参与故障排查和性能优化。</li><li>编写必要的技术⽂档、接口文档和变更说明，沉淀可复用组件与开发规范。</li><li>持续关注线上监控、⽇志和告警，推动缺陷修复、技术债治理和系统迭代优化。\" 7. 5 年及以上 Java 后端开发经验，有海外项目、回收、电商、跨境、支付、订单、库存、营销或中后台系统经验优先；具备完整项目交付和线上问题处理经验。</li><li>技术栈为SpringCloud，微服务开发。注意：公司为大小周 需要有互联网公司经验 五年以上经验</li></ol>', '5-10年', '3fcd46e3c67de1c70nJ72dW4GFJZ', '深圳 · 南山区 · 科技园', '16-25K', '', 'Java', 'https://www.zhipin.com/job_detail/3fcd46e3c67de1c70nJ72dW4GFJZ.html', '交通补助, 夜班补助, 定期体检, 通讯补贴, 带薪年假, 零食下午茶, 股票期权, 绩效奖金, 节日福利, 五险一金');
INSERT INTO `jobs` VALUES (545, '阿甘到', '互联网', '20-99人', '不需要融资', '本科', '<p><strong>工作职责</strong></p><ol><li>负责公司软件平台的整体微服务架构设计、技术选型与核心模块搭建。</li><li>主导关键技术攻关，解决系统性能、并发、数据一致性等核心问题，搭建核⼼架构框架。</li><li>将业务需求拆解为清晰的技术任务，深度参与核⼼模块编码，编写结构清晰、可维护性的服务与接口逻辑。</li><li>主导代码评审，协同团队制定技术规范与⽂档标准，指导提升代码质量与项目意识。</li><li>结合公司业务需求，预研物联网⾏业前沿技术，推动新技术在项目中应用落地，提升平台的技术竞争力</li></ol><p><strong>任职资格</strong></p><ol><li>计算机或相关专业本科及以上学历，6年以上大型软件系统开发经验，3年以上架构师或技术负责人经验。</li><li>精通Java，了解前端技术栈，具备跨语言、跨平台架构设计能力，熟悉Spring Cloud 等主流微服务框架。</li><li>具有物联网平台架构经验，熟悉PLC、MQTT等常见工业协议与设备接入方案。</li><li>熟练掌握微服务与分布式系统设计，有高并发、高可用架构实战经验，熟悉Kafka、Redis、Kubernetes、Docker等微服务相关技术。</li><li>具备良好的业务抽象能力和系统建模思维，能独立完成技术方案设计、评审与落地推进。</li><li>强烈的责任心和自驱力，优秀的团队协作与沟通能力，能承受一定压力，对节能服务行业有热情。</li><li>熟悉AI编程，可利用AI开发工具完成， 项目架构设计，熟悉深耕AI开发提效，有完整落地AI开发经验，能够自主总结AI开发规范、提效方法论着优先。优先考虑：</li><li>有SaaS商城项目、RFID项目、水站项目、物联网项目相关项目等。</li><li>具备AI开发应用经验，熟悉机器学习平台架构或实时推理系统设计。</li></ol>', '5-10年', 'c158f1847f0bc7190nR93t-5EVFY', '深圳', '10-15K', 'Java, 物联网经验, 团队管理经验, 不接受居家办公, 分布式经验, SpringCloud, Redis, Dubbo, Docker, 微服务经验, Zookeeper, MySQL, MyBatis, MongoDB, 架构设计经验', 'Java微服务架构师（全栈）', 'https://www.zhipin.com/job_detail/c158f1847f0bc7190nR93t-5EVFY.html', '工龄奖, 生日福利, 五险一金, 员工旅游, 绩效奖金, 节日福利, 团建聚餐, 全勤奖, 零食下午茶, 年终奖, 带薪年假');
INSERT INTO `jobs` VALUES (546, '小豆互联', '互联网', '0-20人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><p>1，负责公司现有产品后端服务开发与维护，确保系统的高性能和高可用性。2，设计和实现高效的数据库结构，使用 MySQL 进行数据库开发与优化。3，利用 Redis、Kafka、RabbitMQ 等中间件实现高并发、低延迟的数据处理。4，负责服务器的部署、监控与维护，使用 Jenkins 进行持续集成和部署流程的自动化。5，通过 Docker 等容器化技术实现应用的打包与发布，提升系统的可移植性和部署效率。</p><p><strong>岗位要求</strong></p><p>1，5年左右的 Java 后端开发经验，扎实的 Java 基础，熟练掌握多线程、JVM 调优等技术。2，熟悉 Spring Boot、Spring Cloud 等微服务架构，具备高并发、高可用系统的设计与开发经验。3，熟练掌握 MySQL 数据库，具备数据库优化、索引调优等性能优化经验。4，熟悉 Redis、Kafka、RabbitMQ 等常用中间件的原理与使用，能够根据业务需求进行合理的技术选型与优化。5，具备服务器部署与维护经验，熟悉 Linux 操作系统，能够独立完成服务器环境搭建与应用部署。6，熟练使用 Jenkins 进行持续集成与自动化部署，有 Docker 容器化经验者优先。加分项：1，有大型分布式系统开发经验，熟悉分布式中间件，熟悉zookeeper优先2，熟悉云计算平台（如 AWS、腾讯云）的相关服务，能够在云环境中进行应用部署与维护。3，具备一定的前端开发能力，对 Vue、React等前端框架有一定了解、熟悉小程序、H5的开发优先。保险</p><p><strong>福利</strong></p><p>五险一金：公司按照国家法定政策规定，为员工在其工作地购买五险一金。假期员工可享受国家规定的法定节假日，转正后可享受带薪假期，包括婚假、丧假、生产假等；其他</p><p><strong>福利</strong></p><p>团建活动、不定期下午茶；上班时间:09:00-12:00 13:30-18:00，大小周法定节假日按照国家时间放假;</p>', '5-10年', '01e96fd0af5254701Hx_3dq1E1dR', '深圳 · 龙岗区 · 横岗', '15-25K', 'JVM, Java, 不接受居家办公, 分布式经验, Docker, 微服务经验, SpringCloud, MySQL, Redis, MongoDB, 架构设计经验', 'java中高级开发工程师', 'https://www.zhipin.com/job_detail/01e96fd0af5254701Hx_3dq1E1dR.html', '零食下午茶, 团建聚餐, 五险一金, 底薪加提成');
INSERT INTO `jobs` VALUES (547, '爵奇', '人工智能', '20-99人', 'A轮', '本科', '<p><strong>职位描述</strong></p><p>负责核心后台系统的开发、维护与优化，保障系统的高可用性和扩展性，同时与AI团队协作，探索LLM大语言模型等技术与后台服务的结合场景。</p><p><strong>岗位职责</strong></p><ol><li>负责基于SpringBoot/SpringCloud的后台系统开发、维护与性能调优。</li><li>设计并实现高并发、分布式架构，解决数据库、缓存、消息队列等核心技术问题。</li><li>参与系统监控与稳定性建设，快速定位并修复线上故障。</li><li>协助AI团队完成大语言模型（LLM）相关功能的API对接或服务集成。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机，数学相关专业优先。</li><li>5年以上Java后端开发经验，精通SpringBoot、MyBatis等主流框架。</li><li>熟悉MySQL/PostgreSQL等数据库设计及优化，掌握Redis、Kafka等中间件。</li><li>具备分布式系统开发经验（如微服务、容器化部署/Docker、nginx等）。</li><li>熟悉常用linux命令，能够编写shell脚本，有一定的linux运维基础。</li><li>对LLM大语言模型（如GPT、LLaMA等）有基本了解，能理解其技术原理及应用场景（发展方向）。加分项:</li><li>熟悉Python基础，能够用python进行项目开发，了解Flask/Django等。</li><li>接触过AI项目开发或模型API调用 OpenAI、LangChain，mcnnllm等。</li><li>了解HTML、CSS、JavaScript、jQuery，React、Vue等前端核心技术及框架，能够进行简单前端页面开发。</li></ol>', '5-10年', '5a2590047d0099a703Bz3ti5FldX', '深圳 · 福田区 · 福田保税区', '15-30K', 'Java, Python, Spring, MySQL, 微服务经验, 云计算经验, 搜索/推荐/广告经验', '高级java后端开发工程师', 'https://www.zhipin.com/job_detail/5a2590047d0099a703Bz3ti5FldX.html', '全勤奖, 年终奖, 意外险, 工龄奖, 五险一金');
INSERT INTO `jobs` VALUES (548, '秀蛋科技', '互联网', '20-99人', 'A轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>为公司自有产品App提供稳定、高效的后端服务；</li><li>研究和开发AI 应用系统后端服务，包括数据处理、模型训练、模型部署等模块，确保系统的稳定性和高性能。</li><li>负责内部综合管理后台、WEB站点、H5页⾯的开发和优化；</li><li>能够独⽴完成后端服务器软件的模块设计、编码、联调、维护等各阶段的开发任务；</li></ol><p><strong>任职要求</strong></p><ol><li>5年以上互联⽹产品Java后端实际开发经验；</li><li>精通 Java 编程语言，熟练掌握多线程、高并发、集群、分布式编程技术；</li><li>深⼊理解人工智能的基本概念和算法，包括机器学习、深度学习、自然语言处理等领域的算法和技术；</li><li>熟练掌握常见Java框架(Spring、Struts、Hibernate、Springmvc、JQuery)等；</li><li>熟练掌握AI 开发框架或工具，如 TensorFlow、Deeplearning4j、LangChain 等，能够使用这些框架进行模型的构建、训练和评估；</li><li>熟悉基于Java的TCP/IP网络通信编程，有socket长连接开发经验尤佳；</li><li>熟悉常用开源开发组件(Redis, MQ, memcache)等；</li><li>熟悉Mysql，具有数据库索引优化、查询优化和存储优化经验；</li><li>有实际AI应用系统后端服务经验，熟悉高并发长连接和音视频服务端开发经验优先；</li><li>具有创新意识和解决问题的能力，不断学习和掌握新的技术和算法，能够跟踪行业的最新发展动态，将新的技术应用到实际项目中。</li></ol><p><strong>福利</strong></p><ol><li>薪资结构：固定薪资+年终奖+项目奖金；</li><li>最高可享22天年假/年；享受各项法定带薪假，节假日不发月饼粽子，发京东购物卡，春节发盒马高端年货；</li><li>不内卷，没有加班文化，只有午休文化，还可以边上班边撸猫；</li><li>无限量免费提供饮料、现磨咖啡、茶叶等；不定时投喂各种零食；每周五丰富的下午茶；</li><li>入职即购买五险一金，关注员工健康，每年提供体检补助；</li><li>交通便利，不拥堵，地铁站南山站步行5分钟即可到达。</li></ol>', '5-10年', '76a5ad9b98efb5d40nB_3N-8GVNR', '深圳 · 南山区 · 科技园', '15-30K', 'Java, Spring, Netty, Redis, 语音房, 直播app, 社交app', 'Java开发工程师', 'https://www.zhipin.com/job_detail/76a5ad9b98efb5d40nB_3N-8GVNR.html', '节日福利, 夜班补助, 团建聚餐, 员工旅游, 法定节假日三薪, 带薪年假, 零食下午茶, 股票期权, 五险一金, 年终奖, 节假日加班费, 餐补, 生日福利, 交通补助, 加班补助');
INSERT INTO `jobs` VALUES (549, '芯大通', '半导体/芯片', '100-499人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责 AI应用、MPC集市/工作流/记忆系统、知识检索、RAG 架构、长期记忆与上下文、多 Agent 协作机管理等核心模块，开发与维护，确保代码质量和系统稳定性；</li><li>负责后端服务的设计与开发（Java+Go 语⾔），保障⾼性能与⾼可用，精通SpringCloud微服务框架，负责分布式系统的开发与性能优化；</li><li>负责前端页面与交互实现，⽀持 AI 应用场景的复杂交互与可视化；</li><li>负责MySQL数据库的优化工作，包括索引优化、查询优化及存储过程调优；</li><li>深入理解业务需求，设计并实现高质量的业务模块；</li><li>与产品、算法工程师、嵌入式团队紧密协作，快速迭代业务功能和技术方案，对现有系统进行性能分析和优化，提升用户体验和系统效率。</li></ol><p><strong>任职要求</strong></p><ol><li>扎实的Java基础，熟悉JVM原理、多线程编程、并发处理等；</li><li>熟练掌握SpringBoot、SpringCloud等主流框架，有实际项目经验(python、GO可加分)；</li><li>了解数据库原理，至少熟悉Mysql、Redis、MongoDB、etcd、Minio之一；</li><li>了解分布式系统原理，熟悉缓存(如Redis)、消息队列(如Kafka、RabbitMQ)等中间件；</li><li>熟悉前端主流技术栈（Vue/TypeScript 等），理解组件化等理念；</li><li>具备性能优化经验，能够对系统瓶颈进行定位和改进；</li><li>熟练使用AI，具备前端基础知识，可开发后台管理基本页面能力；</li><li>有API网关、计费、账号、权限、审计、运营、BI系统开发经验者优先；</li><li>现有相关MaaS 、智能体平台、大型AI应用、熟悉AI生态经验者优先。</li></ol><p><strong>综合素质</strong></p><ol><li>具备良好沟通能力，较好的沟通与团队协作能力，能消化用户需求，能够在跨部或多团队协作项目中发挥作用；</li><li>具备优秀的问题分析和解决能力；</li><li>能够有效地在团队环境中工作，同时具备良好的自我管理能力，自学能力；</li><li>责任心强，抗压能力突出，能接受应急值守及节假日加班，严格遵守团队纪律；</li><li>具备良好的服务意识、合规意识及成本意识，工作严谨细致，善于总结复盘。</li></ol>', '5-10年', 'c2c126c5db4fd1660nB63N60F1ZY', '深圳 · 南山区 · 科技园', '15-25K', 'Java, SpringCloud, MySQL, 架构设计经验, Spring', '后端工程师', 'https://www.zhipin.com/job_detail/c2c126c5db4fd1660nB63N60F1ZY.html', '年终奖, 生日福利, 节日福利, 餐补, 意外险, 节假日加班费, 五险一金, 法定节假日三薪, 股票期权, 零食下午茶, 带薪年假, 定期体检, 绩效奖金, 团建聚餐, 补充医疗保险, 交通补助');
INSERT INTO `jobs` VALUES (550, '深圳市椿上数智酒...', '酒店/民宿', '20-99人', '天使轮', '本科', '<p><strong>职位描述</strong></p><p>Java\nMySQL\nMyBatis\n架构设计经验\nERP开发经验\n后端开发\n熟悉前端流程\n能独立完成 APP 开发\n全栈熟悉\n熟悉 AI 编程\n管红伟\n刚刚活跃\n深圳市椿上数智酒...\n·\n招聘者\n竞争力分析\n查看完整个人竞争力\n个人综合排名：在人中排名第\n你在？位置\n一般 良好 优秀 极好\nBOSS 安全提示\n严禁用人单位和招聘者用户做出任何损害求职者合法权益的违法违规行为，包括但不限于扣押求职者证件、收取求职者财物、向求职者集资、让求职者入股、诱导求职者异地入职、异地参加培训、违法违规使用求职者简历等，您一旦发现此类行为， 请立即举报\n公司介绍\nA1酒店数字化平台和生态\n工商信息\n公司名称\n数旅文化科技（深圳）有限公司\n法定代表人\n韩世琴\n成立日期\n2026-03-24\n企业类型\n有限责任公司（自然人独资）\n经营状态\n存续\n注册资金\n100万元\n查看全部\n工作地址\n深圳罗湖区深圳国际贸易中心大厦1411\n点击查看地图\n更多职位\n看过该职位的人还看了\nJava开发工程师（珠海项目，线上面试）\n10-14K\n长亮科技\n深圳\njava开发工程师\n10-15K\n软通动力\n深圳\njava开发工程师\n10-15K\n中航信息\n深圳\n金融项目Java开发\n11-16K\n中电金信\n深圳\nJava/Python开发工程师（AI方向）\n10-15K\n云仓库\n深圳\n后端软件工程师（Java方向）\n10-15K\nCARVOO凯沃智能\n深圳\n精选职位\nJava\n10-15K\n峰峻智能\n深圳\njava开发工程师\n11-16K·13薪\n汇合发展\n深圳\nJava开发工程师-上市公司-自有大厦办公\n11-14K\n四方精创\n深圳\nrpa工程师亚马逊\n10-15K\n佳翔\n深圳\nJava（社保公积金全额）\n11-12K\n法本\n深圳\nJAVA开发工程师（驻场某券商）\n11-14K\n新华三技术有限公司\n深圳\n深圳\n搜索\n城市招聘 热门职位 推荐公司 热门企业\n焦作招聘\n梅州招聘\n铜陵招聘\n南平招聘\n淮安招聘\n十堰招聘\n德州招聘\n广元招聘\n贺州招聘\n莆田招聘\n首页深圳招聘·Java招聘深圳Java招聘深圳市椿上数智酒...Java招聘\n页面更新时间：2026-08-05\n企业服务热线和算法/未成年人等举报渠道 400 065 5799\n老年人直连热线400 661 6030\n工作日 8:00 - 22:00\n休息日 8:00 - 22:00\n企业服务\n职位搜索\nAPP\n投资者关系 Investor Relations\n直品公益基金会\n求职技巧\n使用与帮助\n协议与规则\n隐私政策\n防骗指南\n使用帮助\n联系\n北京华品博睿网络技术有限公司\n公司地址 北京市朝阳区太阳宫中路16号院1号楼18层1801内09\n违法和不良信息举报邮箱/未成年人举报渠道 jubao@.com\nCopyright © 2026 京ICP备14013441号-5京ICP证150923号 电子营业执照 京公网安备11010502032801 朝阳网警 人力资源服务许可证 网上有害信息举报专区 朝阳区人社局监督电话 算法备案信息</p>', '5-10年', '6469c1fa70f9dd250nFz3N2_EVpY', '深圳 · 罗湖区 · 东门', '10-15K', 'Java, 不接受居家办公, MySQL, MyBatis, 架构设计经验, ERP开发经验', 'Java', 'https://www.zhipin.com/job_detail/6469c1fa70f9dd250nFz3N2_EVpY.html', '五险一金');
INSERT INTO `jobs` VALUES (551, '环讯通', '计算机软件', '100-499人', '未融资', '本科', '<p>【</p><p><strong>岗位职责</strong></p><p>】1、负责公司软件产品研发工作，与客户良好有效的沟通，以专业的技术服务和热情的工作态度，保证项目实施的质量2、有良好的团队合作精神，能很好的与内部同事协作，沟通项目研发进展情况，确保项目实施工作顺利进行3、负责编撰和整理相关产品、项目文档4、有效及时解决客户反馈的问题，提升客户满意度5、具有政务相关的案例开发经验；【</p><p><strong>职位要求</strong></p><ol><li>熟悉java开发相关技术栈，熟练使用java开发工具及调优工具。</li><li>熟悉LINUX系统以及相关常用命令和工具。</li><li>熟悉使用 Spring Boot、Spring Cloud微服务架构，参与系统的设计与架构优化。</li><li>熟悉使用 Redis、MySQL等数据库进行数据的存储与处理。</li><li>熟悉运用主流非关系型数据库，有mongo、 ES、向量数据库或者同类型相关经验优先。</li><li>熟悉 Kafka、RabbitMQ 等主流消息队列，具备消息队列的选型、部署、调优及故障排查能力，能结合业务场景实现异步通信、削峰填谷等需求。</li><li>具有Docker相关的部署方案和实践经验。</li><li>了解Minio等分布式文件存储解决方案的部署和管理。</li><li>了解 Kubernetes（k8s）核心概念与架构，具备基于 k8s 的微服务部署、编排、扩缩容及日常运维经验的优先。</li><li>有强烈的责任心和使命感，有良好的沟通表达能力和团队协作能力。</li></ol><p><strong>职位福利</strong></p><p>五险一金、周末双休、不加班、每年多次调薪</p><p><strong>职位亮点</strong></p><p>公务员午休床、双休日公司总部地址：广东/深圳/龙华区 清湖北地铁站A出口华清大道200号半里大厦1901、1902、1907、1908</p>', '5-10年', '1dc0d9524bdeed771HVy3NS6GVBU', '深圳 · 龙岗区 · 坂田', '15-20K', 'Java, Nginx, Docker, SpringCloud, Redis', 'java开发工程师', 'https://www.zhipin.com/job_detail/1dc0d9524bdeed771HVy3NS6GVBU.html', '团建聚餐, 零食下午茶, 带薪年假, 五险一金');
INSERT INTO `jobs` VALUES (552, '飞的科技', '生活服务(O2O)', '100-499人', 'A轮', '本科', '<p><strong>岗位职责</strong></p><p>· 负责公司核心业务系统的后端架构设计、开发与维护，确保高并发、高可用。· 基于 Python 和 Java 进⾏服务端功能开发，参与微服务架构设计与治理。· 主导 AI Agent 的设计、开发与落地，结合⼤模型能⼒实现复杂任务自动化执行与智能决策。· AI业务场景挖掘与落地，完成 Agent ⼯具链、记忆模块、规划与推理流程的工程化实现。· 编写高质量代码，参与代码评审，持续优化系统性能和稳定性。· 熟练运用 AI 编程助手（如 claude code 、 codex 、 Cursor 等）提升日常开发效率，并推动团队 AI 工具落地实践。</p><p><strong>任职要求</strong></p><p>· 计算机相关专业本科及以上学历，5 年以上后端开发经验。· 精通 Python 和 Java，具备扎实的多范式编程能力，熟悉至少一种主流后端框架（如 Spring Boot、FastAPI）。· 有真实的 AI Agent 项目经验，熟悉 LangChain、LangGraph、Semantic Kernel 或类似框架，了解 Agent 推理、工具调用、记忆管理等核心机制。· 熟悉 MySQL、Redis、Kafka/ RocketMQ 等常用数据库与中间件，具备性能调优经验。· 熟练使用 AI 开发工具（如 claude code 、 codex 、 Cursor等），能将其融入需求分析、编码、测试等日常开发流程，切实提升生产力。有公司内部AI办公提效经验优先。· 具备良好的系统设计能力、问题分析与解决能力，有较强的技术好奇心和自驱力。· 具备一定的项目管理经验，曾在中大型项目担任过项目经理并按期交付项目。</p>', '5-10年', '6a1d33426b99c1870nFz2tq4FVpS', '深圳 · 南山区 · 科技园', '18-25K·13薪', 'Java, MySQL, Spring, Python', 'JAVA开发（AI经验）', 'https://www.zhipin.com/job_detail/6a1d33426b99c1870nFz2tq4FVpS.html', '员工旅游, 加班补助, 节日福利, 带薪年假, 五险一金, 年终奖');
INSERT INTO `jobs` VALUES (553, '星普云', '计算机软件', '100-499人', '', '大专', '<ol><li>4-6年经验，沟通能力好，理解能力强。</li><li>技术栈：spring全家桶，nacos、mysql、k8s、redis。熟悉rocketmq、mongodb且处理过大数据量的优先。</li><li>主要负责后端功能开发，代码重构、优化。</li><li>能使用vue进行简单前端页面开发、修改的优先考虑。</li><li>能根据业务需求进行简单的功能实现。</li></ol>', '5-10年', '7aef8627b38ce8981Hxz2Ni9GFBX', '深圳 · 福田区 · 会展中心', '15-18K', 'Java, Spring, Redis, MongoDB, MySQL, 不接受居家办公, 大数据经验, spring全家桶, 海量数据, k8s', 'Java工程师（高级）', 'https://www.zhipin.com/job_detail/7aef8627b38ce8981Hxz2Ni9GFBX.html', '');
INSERT INTO `jobs` VALUES (554, '澜潮科技', '通信/网络设备', '100-499人', 'A轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责云边端一体化的IOT物联网平台架构设计、核心功能开发、技术方案选型以及开放平台的建设；</li><li>规划系统的高并发、高可用、分布式架构，确保平台稳定性、可扩展性和安全性，主导容灾方案设计；</li><li>协调跨团队开发，制定技术规范（代码、架构、安全），主导Code Review与性能调优，提升团队工程能力；</li><li>参与业务需求研讨、业务需求分析、业务拆分、编写技术方案，负责技术攻坚，核心代码编写以及系统优化。</li></ol><p><strong>任职要求</strong></p><ol><li>具备5年及以上互联网项目Java开发经验，计算机专业重点本科以上学历；</li><li>Java基础牢固，熟悉设计模式及源码原理，深入理解JVM，了解Java性能调优和工具；</li><li>熟练掌握Java服务端的开发技术，熟练掌握Spring体系、netty、MyBatis、Redis、消息队列、多线程、任务调度等组件和中间件；</li><li>熟练掌握数据库技术，熟悉MySQL、IotDb、Hadoop、Spark等；</li><li>熟悉服务器集群高并发、负载均衡方案，熟悉分布式数据库，熟悉虚拟化技术；</li><li>熟悉Prometheus/Grafana/Skywalking等可观测性工具，或具备AI算法落地经验；</li><li>有物联网平台项目经验，熟悉协议开发、MQTT调优者优先考虑；</li></ol>', '5-10年', '488bcfa5fbc0349003J53tm6E1dR', '深圳 · 南山区 · 西丽', '16-30K·15薪', 'Java, 物联网经验, MySQL, Hadoop, Netty, MyBatis, Spark, 架构设计经验, Spring, 有前端经验/技能', 'java架构师', 'https://www.zhipin.com/job_detail/488bcfa5fbc0349003J53tm6E1dR.html', '保底工资, 住房补贴, 通讯补贴, 免费工装, 绩效奖金, 年终奖, 补充医疗保险, 加班补助, 股票期权, 交通补助, 带薪年假, 意外险, 底薪加提成, 餐补, 零食下午茶, 节日福利, 五险一金, 员工旅游, 定期体检, 法定节假日三薪');
INSERT INTO `jobs` VALUES (555, '正德良品', '互联网', '100-499人', '不需要融资', '大专', '<p>如果您具备跨境电商 ERP Java 开发经验，熟悉 Amazon Advertising 或其他同类广告平台完整投放链路（投放管理、竞价策略、流量分发、广告归因、转化分析）相关开发工作经验，欢迎自荐！</p><p><strong>岗位职责</strong></p><ol><li>负责系统核⼼业务模块的设计与开发，保障⾼可⽤、高性能交付；</li><li>参与并主导项目整体技术⽅案设计，推动技术方案落地实施与交付；</li><li>参与分布式系统设计与关键技术攻关，解决复杂业务场景下的技术问题；</li><li>协同产品、数据及业务团队，推动系统能力与业务目标一致性落地。</li></ol><p><strong>任职要求</strong></p><ol><li>5年以上Java开发经验，全日制理工科大专及以上学历；</li><li>扎实的Java编程基础，熟悉常用的Java开源框架，如Spring、SpringBoot、MyBatis；</li><li>熟悉常见的中间件、分布式解决方案及其原理，包括但不限于：Nginx、Redis、RabbitMQ、MySQL数据库优化技术；</li><li>熟悉Spring Cloud微服务体系，了解Gateway、Nacos等组件的使用与原理；</li><li>熟悉Linux操作系统、Docker容器化部署及Git版本管理；</li><li>具有较好的沟通协作能力、能独立分析问题和解决问题，注重代码质量，有良好的软件工程知识和编码规范；</li><li>熟悉Amazon Advertising 或类似广告平台的投放核心链路，包括投放管理、竞价策略、流量分发、广告归因及转化分析等模块。</li><li>具备大数据分析或数据平台开发经验，熟悉数据体系建设的优先。</li></ol>', '5-10年', '89053f949e2a82e90nF62N66GVVZ', '深圳', '15-22K', 'Java, 大数据经验, Amazon Advertising, 不接受居家办公, 广告平台, SpringCloud, MyBatis, SQL Server, Spring, ERP开发经验', '高级java开发工程师', 'https://www.zhipin.com/job_detail/89053f949e2a82e90nF62N66GVVZ.html', '股票期权, 绩效奖金, 零食下午茶, 全勤奖, 工龄奖, 五险一金, 年终奖, 员工旅游, 企业年金, 团建聚餐, 生日福利, 免费工装, 带薪年假, 节日福利, 保底工资, 定期体检, 底薪加提成');
INSERT INTO `jobs` VALUES (556, '中环柯昂', '计算机软件', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责公司To B/To G行业软件项目的后端架构设计、核心模块开发及系统优化；</li><li>根据客户业务需求，参与系统需求分析、技术方案设计，完成业务模块设计与开发；</li><li>独⽴负责项⽬模块从需求理解、技术设计、编码开发、测试联调到上线交付全过程；</li><li>配合项⽬经理完成客户需求沟通、技术交流及项目交付支持；</li><li>输出项⽬相关技术文档，包括系统设计文档、接口文档、用户操作手册等；</li><li>持续应用AI辅助开发工具，提高研发效率，探索AI在软件开发流程中的应用。</li></ol><p><strong>任职要求</strong></p><ol><li>全日制本科及以上学历，计算机、软件工程、信息技术等相关专业；</li><li>5年以上企业级软件、行业应用系统、政企项目开发经验，具备独立负责业务模块研发及交付能力；</li><li>精通Java / Python / Go等至少一种后端开发语言；熟悉Spring Boot、Spring Cloud等企业级开发框架；</li><li>能利用AI完成代码生成、代码优化、问题分析、技术调研，提高研发效率；</li><li>具备一定客户沟通能力，能够参与需求澄清及技术交流。【加入中环柯昂 您将获得】1、双休+五险一金+商业保险2、AI智能体行业发展机遇3、丰富的医疗、电网、双碳行业资源</li></ol>', '5-10年', 'c9300e2f847367e00nJ609S_F1dY', '深圳 · 龙华区 · 深圳北站', '13-15K·13薪', 'Java, C++, 不接受居家办公, 分布式经验, SpringCloud, MySQL, 云计算经验, Spring, Oracle, ERP开发经验, Python', '后端开发工程师（高级）', 'https://www.zhipin.com/job_detail/c9300e2f847367e00nJ609S_F1dY.html', '底薪加提成, 带薪年假, 团建聚餐, 年终奖, 绩效奖金, 保底工资, 生日福利, 节日福利, 定期体检, 员工旅游, 意外险, 五险一金');
INSERT INTO `jobs` VALUES (557, '深关通', '计算机软件', '20-99人', '未融资', '本科', '<p>有跨境电商、关务、舱单、物流系统经验者优先。</p><p><strong>一、岗位职责</strong></p><ol><li>核心业务系统研发• 负责公司关务 SaaS 平台（报关申报、审单、要素管理等）、舱单申报系统等核心模块的设计与开发。• 参与海运舱单对接、报关流程自动化、多业务场景逻辑整合等复杂业务的实现。• 负责接口开发、业务流程编排、数据结构设计以及后台管理系统建设。</li><li>系统稳定性与性能优化• 优化⾼并发场景下的系统性能，包括 MySQL 调优、线程池优化、缓存策略、异步化与限流策略等。• 负责线上问题排查（⽇志、调⽤链、GC、CPU/内存分析、.hprof 诊断等），保障系统稳定运行。• 对接内部监控系统，参与监控指标落地与优化。</li><li>自动化与平台化能⼒建设• 参与公司自动化体系建设：自动化测试系统、自动部署系统、任务监控系统等。• 根据产品需求，补充数据结构、API 交互、服务治理、RBAC 权限体系等。</li><li>版本交付与团队协作• 按“每周三迭代制”参与需求评审、接口联调、上线发布。• 与产品经理、前端、测试紧密协作，保证版本质量与交付效率。• 输出核心模块技术文档、开发规范、数据库设计说明。</li></ol><p><strong>二、岗位要求</strong></p><ol><li>专业能力• 3 年以上 Java 后端开发经验，掌握 Spring Boot、Spring Cloud、MyBatis/JPA 等技术。• 熟悉 MySQL，有良好的 SQL 优化能力，掌握慢查询分析。• 熟悉 Redis、消息队列（RabbitMQ/Kafka 任意一种）、缓存与异步处理机制。• 有良好的 API 设计能力与系统设计经验。</li><li>技术思维与责任感• 能独立完成模块开发、调试、上线，对结果负责。• 熟悉常见线上排障手段，如日志定位、线程分析、CPU 抽样、连接状态分析等。• 有代码整洁度、可维护性意识，愿意推动技术优化与重构。</li><li>加分项• 有使用过相关技术栈（Go 服务、爬虫、自动化工具等）加分。• 熟悉 Linux、Shell、Nginx、Tomcat 部署。• 对分布式系统、微服务架构、APM/监控体系有经验。• 了解 AI 推理服务对接（OCR、结构化识别、RAG）者更佳。</li></ol>', '5-10年', 'b74f43cf5ce5325e0nZ_3tS4EFBZ', '深圳 · 南山区 · 前海', '15-22K', 'Java, 大数据经验, 不接受居家办公, 分布式经验, Redis, 云计算经验, Dubbo, 架构设计经验, Spring, ERP开发经验, Spring boo 、Spring C, Python', 'java高级开发工程', 'https://www.zhipin.com/job_detail/b74f43cf5ce5325e0nZ_3tS4EFBZ.html', '年终奖, 节日福利, 零食下午茶, 生日福利, 餐补, 带薪年假, 全勤奖, 五险一金, 团建聚餐');
INSERT INTO `jobs` VALUES (558, '航路信息', '生活服务(O2O)', '100-499人', 'C轮', '本科', '<p>初试线上，复试需要线下参boss加。</p><p><strong>岗位职责</strong></p><ol><li>负责机票领域的软件应用设计，开发和维护；</li><li>参与方案讨论和技术调研，负责方案升级更新，提供关键技术评估及支持；</li><li>分析并解决软件开发过程中的问题。</li></ol><p><strong>任职要求</strong></p><ol><li>统招本科（统招/学信⽹可查），5年java开发经验；</li><li>技术栈要求，spring、boot、tomcat、mysql、redis、dubbo、zookeeper、kafka、rocketmq、httpclient；</li><li>具备优秀学习和适应能⼒，有良好的业务理解和沟通能⼒；</li><li>具备写出易读、易维护的代码的意识，有一定的技术钻研能力和抗压能⼒。岗位</li></ol><p><strong>福利</strong></p><ol><li>朝十晚七,周末双休，弹性打卡上下班；</li><li>每月部门团建经费和生日会，每年 2 次团建旅游，1 次员工体检；</li><li>购买六险一金、一档医保，当月薪资当月发；</li><li>按国家法定节假日休假，每年带薪年休假；</li><li>提供具有竞争力的薪酬，外加丰厚年终绩效。关于我们：深圳航路flightroutes24是全球规模最大的机票分销平台之一，公司基于自研技术，深度整合全球超过60个国家、700家航司、50万条航线的优势机票产品，目前业务量已在行业细分领域内处于全球top前三。</li></ol>', '5-10年', '2478af7d601ac3a80nZ83t61EFtX', '深圳 · 南山区 · 科技园', '15-25K·13薪', 'Java, MySQL, Dubbo, Spring', '中高级Java工程师（双休+自研项目+年终奖）', 'https://www.zhipin.com/job_detail/2478af7d601ac3a80nZ83t61EFtX.html', '节假日加班费, 带薪年假, 加班补助, 意外险, 生日福利, 夜班补助, 员工旅游, 节日福利, 五险一金, 年终奖, 零食下午茶, 定期体检, 团建聚餐');
INSERT INTO `jobs` VALUES (559, '蓝青教育集团', '人工智能', '100-499人', '不需要融资', '本科', '<p>注意: 非外包岗，学历要求 统招全日制本科以上</p><p><strong>工作职责</strong></p><ol><li>负责公司软件项目的架构设计，核心模块的开发与维护工作2、参与产品设计和需求分析3，有项目管理经验，按时提交高质量代码，完成开发任务；</li><li>能快速定位和解决系统运行中出现的问题缺陷；</li><li>规范文档的编写、维护，以及其他与项目相关工作；</li><li>其它如团队、项目、产品、技术等支持工作</li></ol><p><strong>任职资格</strong></p><ol><li>统招全日制本科及以上学历，计算机软件或相关专业2、5年以上java技术开发经验，2年以上软件项目管理经验，有教育平台项目经验者优先考虑3、掌握基于 J2EE的相关开源技术，精通Spring、Spring MVC、Spring boot、MyBatis/Hibernate等开源框架，精通RESTful和RPC，有上述技术的实际开发经验；</li><li>熟悉Spring Cloud，Dubbo等微服务框架，能够设计和搭建分布式微服务架构，有架构设计经验优先5、掌握Linux操作系统和MySql数据库；了解SVN的使用，熟悉Tomcat，Apache，Nginx等开源服务器，了解MongoDB等分布式数据库，有丰富的性能调优经验。</li><li>掌握多线程及高性能的设计与编码及性能调优，有高并发应用开发经验优先7、具备创新能力、广阔的视野、能保持高度工作热情；能承受较大工作压力，思路清晰，思维敏捷，有快速的学习能力。</li></ol>', '5-10年', '0febd312ff4b1f833nV83tS5FFY~', '深圳 · 南山区 · 南头', '16-25K', 'Golang, Java, Docker, SpringCloud, MySQL, Redis, MongoDB, Spring, Python', '高级JAVA开发工程师', 'https://www.zhipin.com/job_detail/0febd312ff4b1f833nV83tS5FFY~.html', '节日福利, 五险一金, 员工旅游, 年终奖, 带薪年假, 全勤奖, 零食下午茶, 通讯补贴');
INSERT INTO `jobs` VALUES (560, '深圳同耕科技', '计算机软件', '20-99人', '未融资', '本科', '<p>基于智能制造生产模型的本体模型结构设计。无此类经验的软件设计工程师请投其他岗位；该岗位接受科班出身在校参与过类似科研项⽬的应届⽣、在校研究⽣。</p><p><strong>岗位职责</strong></p><ol><li>分解并构建软件的产品、需求等结构模型；</li><li>对应知识图谱投喂给AI；</li><li>参与软件、业务模型的版本管理4、与训练智能体；</li><li>参与软件平台的开发与设计；</li><li>进行技术管理和开发人员的技术培训的⼯作；</li><li>技术任务分配及评估。</li><li>公司、部门交办的其他技术工作</li></ol><p><strong>任职资格</strong></p><ol><li>计算机相关专业本科学历以上；</li><li>5年以上软件产品研发经验，具有技术平台开发经验、如表单设计器、工作流程设计器、报表设计器等优先；</li><li>熟悉Uml建模工具、Sysml建模。对MBSE或系统工程体系有基础认知；</li><li>熟练JAVA及VUE等前后端技术，熟悉应用开发工具,技术框架,应用服务器，数据库等技术；</li><li>对本体论、AI、软件工程有清晰认知，具备OWL相关开发经验优先；</li><li>具有良好的领导能力，学习能力、沟通能力，承受压力能力，独立解决问题的能力；；</li><li>善于交流，勇于技术革新和创新，具有团队协作和敬业精神；具有较强的工作责任心和事业心。</li></ol>', '5-10年', 'cf72c47209d0177503xy2dS7GVtU', '深圳 · 南山区 · 科技园', '13-18K', 'Java, sysml, mbse, owl, uml, SpringCloud, MySQL, 架构设计经验', '软件产品本体模型设计（AI及Sysmal方向）', 'https://www.zhipin.com/job_detail/cf72c47209d0177503xy2dS7GVtU.html', '带薪年假, 五险一金, 年终奖, 员工旅游, 节日福利, 有无线网, 绩效奖金, 住房补贴, 底薪加提成');
INSERT INTO `jobs` VALUES (561, '深圳华资数智科技', '计算机软件', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>主导系统架构设计与核心模块开发，完成高质量的代码编写和单元测试；</li><li>根据项目任务完成相应功能模块的设计、开发与优化工作；</li><li>带领开发团队成员进⾏技术⽅案调研与⽂档编写，推动项目顺利实施；</li><li>对现有系统进行维护和性能调优，保障系统稳定性和可扩展性；</li><li>完成上级安排的其他技术开发相关⼯作。</li></ol><p><strong>任职要求</strong></p><ol><li>具备扎实的Java编程基础，熟悉常用设计模式和开发框架；</li><li>熟悉分布式系统设计与应用，了解主流中间件技术；</li><li>具备良好的沟通能力和团队协作意识，能高效配合项目推进；</li><li>有较强的学习能力和问题解决能力，能独立承担开发任务；</li><li>能够在规定时间内保质保量完成分配的</li></ol><p><strong>工作内容</strong></p><p>。</p>', '5-10年', '5d3c993bc2eb29aa0nZ92tm7F1ZQ', '深圳 · 福田区 · 车公庙', '16-22K', '不接受居家办公, Java, Python, Spring, Kafka, Nginx, Docker, MySQL, Redis, MongoDB, PostgreSQL, Hadoop, 团队管理经验, 架构设计经验, 分布式经验, 微服务经验, 大数据经验', 'java高级开发', 'https://www.zhipin.com/job_detail/5d3c993bc2eb29aa0nZ92tm7F1ZQ.html', '员工旅游, 零食下午茶, 法定节假日三薪, 五险一金, 通讯补贴, 团建聚餐, 节假日加班费, 定期体检, 生日福利, 意外险, 带薪年假, 夜班补助');
INSERT INTO `jobs` VALUES (562, '几素科技', '电子商务', '100-499人', '未融资', '本科', '<p>官网：http://www.jisulife.com.cn/</p><p><strong>岗位职责</strong></p><ol><li>负责公司APP后台系统、社区生态、用户体系、内容业务、智能设备互联服务的设计与开发，保障系统稳定、高性能、可迭代；</li><li>参与业务需求评审、技术⽅案设计、接口定义、数据库设计，独⽴完成模块开发、单元测试、上线交付；</li><li>负责核⼼业务功能迭代，包括用户社区、内容发布、互动评论、装备数据、智能硬件互联、商城/会员等后端服务开发；</li><li>持续优化系统架构、接口性能、数据库索引、缓存策略，解决高并发、⾼流量场景下的性能瓶颈；</li><li>配合前端、产品、测试团队推进版本迭代，跟进线上问题排查、修复、复盘，保障服务稳定可用；</li><li>参与技术沉淀、代码规范落地、公共组件封装，推动团队研发效率提升。</li></ol><p><strong>岗位要求</strong></p><ol><li>统招本科及以上学历，计算机、软件工程等相关专业，5年及以上Java后端开发经验，能力优秀可放宽；</li><li>扎实掌握Java基础、集合、多线程、JVM、IO、并发编程等核心知识；</li><li>熟练掌握SpringBoot、SpringCloud、MyBatis/MyBatis-Plus主流开发框架；</li><li>熟练使用MySQL，精通SQL优化、索引设计、事务机制，具备一定分库分表、大数据量处理经验；</li><li>熟悉Redis、MQ等中间件，了解缓存、消息队列业务场景与使用规范；</li><li>熟悉微服务、接口开发、RESTful接口设计，具备APP后端/社区平台/SaaS平台开发经验优先；</li><li>具备问题排查能力、逻辑思维清晰，代码规范，有良好的团队协作和迭代意识；</li><li>有智能硬件、社区内容、电商会员项目经验者优先。加分项：</li><li>有高并发社区、内容平台、用户体系、积分会员系统开发经验；</li><li>了解物联网、设备互联、智能硬件对接业务；</li><li>熟悉Docker、Linux、Git、CI/CD研发流程；</li><li>具备独立负责业务模块、从0到1搭建功能的经验。</li></ol>', '5-10年', '655cd6e750e1bd920nF92NW0FFNW', '深圳 · 龙岗区 · 坂田', '15-25K', 'Java, Spring, SpringCloud, Docker, JVM, 不接受居家办公, MySQL, Redis, SQL Server, 物联网经验, 大数据经验, 云计算经验, ERP开发经验, APP, 商城, IOT, 微服务', 'Java工程师（IOT/APP/双休）', 'https://www.zhipin.com/job_detail/655cd6e750e1bd920nF92NW0FFNW.html', '生日福利, 节日福利, 底薪加提成, 年终奖, 五险一金, 股票期权, 保底工资, 加班补助, 定期体检, 免费工装, 带薪年假, 交通补助, 团建聚餐, 绩效奖金, 员工旅游, 零食下午茶, 餐补');
INSERT INTO `jobs` VALUES (563, '深圳市世标创科检...', '检测/认证/知识产权', '20-99人', '不需要融资', '大专', '<p>适用场景：需要具备丰富的大模型工程化落地经验，能够独立主导⼤模型在⼯业场景的深度应⽤开发。</p><p><strong>岗位职责</strong></p><ol><li>负责ERP/MES产品中大模型应用的整体技术⽅案设计与核心代码实现主导大模型在玻璃行业场景（智能排产、质量预测、设备维护、工艺优化等）的落地开发；</li><li>负责大模型微调（LoRA/P-tuning）、私有化部署与推理优化负责RAG系统架构设计与知识库建设，解决大模型在工业场景中的幻觉控制、数据安全等关键问题；</li><li>负责核心业务模块全栈开发，以Java后端开发为主，Vue前端开发为辅指导团队技术能力提升与代码质量把控。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机、人工智能、软件工程等相关专业；5年以上Java开发经验，其中至少2年以上AI大模型应用开发经验；</li><li>精通Java技术体系，拥有大型分布式系统架构设计与开发实战经验大模型技能：</li><li>精通LLM技术生态，深入理解模型微调、推理优化、RAG、Agent框架等关键技术原理4、熟悉大模型工程化落地全流程，有大模型在工业场景落地经验者优先了解工业通信协议（如OPC UA、Modbus）者优先熟悉前端技术（Vue/React），具备全栈架构能力。</li></ol>', '5-10年', '9e7f31c35f646ec50nFy2N64GFtX', '深圳 · 宝安区 · 石岩', '12-18K', 'MES开发经验, Java, 不接受居家办公, ERP开发经验', '全栈开发工程师（AI方向）', 'https://www.zhipin.com/job_detail/9e7f31c35f646ec50nFy2N64GFtX.html', '五险一金, 年终奖, 全勤奖, 节假日加班费, 夜班补助, 团建聚餐, 企业年金, 零食下午茶, 宿舍有空调, 绩效奖金, 包吃, 加班补助, 餐补, 交通补助, 节日福利, 员工旅游, 底薪加提成, 保底工资, 有无线网, 带薪年假');
INSERT INTO `jobs` VALUES (564, '华仁智信', '计算机软件', '20-99人', '未融资', '本科', '<p>boss</p><p><strong>岗位描述</strong></p><ol><li>负责公司企业级web应用系统的规划、建设和升级；</li><li>按产品要求完成相应系统、模块的设计、开发、测试；</li><li>与前端开发人员进行沟通，统筹前后端的对接工作；</li><li>开发和维护系统平台与框架，发现和解决存在的技术问题；</li><li>规划技术路线，组建技术团队。</li></ol><p><strong>岗位要求</strong></p><ol><li>3年以上java 开发工作经验，熟练掌握java语言，具备软件架构的能力；</li><li>熟练使用J2EE框架，熟练掌握java语言，具备软件架构的能力；熟练使用Spring Cloud Alibaba，MyBatisplus，springmvc，Spring security ，springboot,Mybatis等开源框架原理和使用，拥有良好的框架设计和良好的编码风格；</li><li>熟练使用一种主流数据库(MySQL或PG)，掌握SQL编写，有一定的sql性能调优经验；</li><li>Java基础扎实，良好的编码风格，熟悉常用的设计模式，能够独立完成应用系统的开发；</li><li>具有良好的团队合作和沟通能力，逻辑能力强，有较强的抗压能力和较强的责任心；</li><li>具备较强的架构能力，有微服务，容器，消息中间件，分布式系统的设计开发经验优先。</li><li>有关务系统搭建者优先；</li><li>需有软考类证书；</li></ol>', '5-10年', '47fbdac41fbbbc241XV40ti8FlZY', '深圳 · 南山区 · 科技园', '13-18K', '分布式技术, SpringMVC, SpringBoot, Spring, SQL', 'JAVA开发工程师', 'https://www.zhipin.com/job_detail/47fbdac41fbbbc241XV40ti8FlZY.html', '度假休假, 节日福利, 团建聚餐, 五险一金');
INSERT INTO `jobs` VALUES (565, '幻方智联', '企业服务', '0-20人', '天使轮', '本科', '<p><strong>岗位职责</strong></p><p><strong>岗位职责</strong></p><ol><li>数据驱动与AI赋能​设计⼯业数据模型，打通设备层（IoT）、业务层（ERP/MES）与决策层数据管道，支撑实时分析与预测性维护等场景。集成轻量级AI模块（如视觉检测、工艺优化算法），推动智能化闭环（如⾃动调参、异常预警）。</li><li>全流程闭环管理​参与客户需求调研，将制造场景痛点转化为技术方案（B→D），并通过迭代验证管理闭环（M）。主导数据库架构设计（关系型/时序数据库混合部署），优化高并发场景下的数据读写效率。</li><li>技术协同与创新​推动DevOps实践，建立自动化测试与交付流水线，确保系统快速响应业务变化。跟踪工业软件前沿技术（如数字孪生、边缘计算），探索BDIM模式的技术升级路径。</li></ol><p><strong>任职要求</strong></p><p>​ 精通Java生态，深入理解Spring Boot/Cloud微服务架构； 熟练掌握前端开发（Vue/React + TypeScript）； 熟悉MySQL/PostgreSQL，了解时序数据库（InfluxDB/TDengine）； 掌握RESTful API设计，有GraphQL经验者优先。具备工业数据建模能力（如OPC UA、MQTT协议）；理解数据采集、清洗、可视化全流程，能设计数据血缘关系。了解主流AI框架（TensorFlow/PyTorch），能将预训练模型集成至业务系统；熟悉工业场景AI应用（如缺陷检测、能耗优化）。其它要求：业务敏感度：能快速理解生产制造流程（如离散/流程制造差异），将场景需求转化为技术语言。闭环思维：习惯从“问题定义→方案设计→效果验证→迭代优化”全流程推进工作。跨界沟通：能与工厂工程师、产品经理高效协作，避免“技术脱离业务”。</p>', '5-10年', 'aaaf74d581456d460nB50ti-ElVQ', '深圳 · 龙岗区 · 横岗', '16-20K·14薪', 'JVM, MES开发经验, Java, Docker, MySQL, MyBatis, Redis, 架构设计经验, Spring, ERP开发经验, Python', 'MES高级工程师', 'https://www.zhipin.com/job_detail/aaaf74d581456d460nB50ti-ElVQ.html', '股票期权, 交通补助, 定期体检, 保底工资, 零食下午茶, 年终奖, 五险一金, 学习自选, 包住, 法定节假日三薪, 团建聚餐, 带薪年假, 员工旅游, 绩效奖金, 节日福利, 意外险, 包吃');
INSERT INTO `jobs` VALUES (566, '魔方卫星', '铁路/船舶/航空/航天制造', '100-499人', 'A轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责运管&测试系统、地面系统的核心微服务架构设计与开发，构建高可用、⾼扩展性的后端业务系统；</li><li>针对多源异构数据（低频的卫星SAR影像、⾼频的地⾯传感器流数据），设计并优化基于 Kafka/RocketMQ 等消息队列的高吞吐数据接入与分发链路，确保数据流转的零丢失与低延迟；</li><li>研发⾼可靠的分布式任务调度中心，负责串联和编排底层的光学/雷达数据解算节点及地质力学模型，实现自动化、周期性的遥感数据生产流水线；</li><li>参与系统整体的容器化（Docker/K8s）部署方案优化，监控系统性能指标（链路追踪、日志分析），持续进行服务治理、内存调优和 SQL 优化。</li></ol><p><strong>任职要求</strong></p><ol><li>计算机科学、软件工程等相关专业统招本科及以上学历；</li><li>5年以上 Java 服务端研发经验，Java 基础极度扎实，精通 JVM 原理、并发编程、网络编程及常用数据结构；</li><li>深入理解微服务架构，精通 Spring Boot、Spring Cloud (Alibaba) 生态；熟练驾驭 Redis、Kafka/RocketMQ、ElasticSearch 等主流中间件，有明确的处理过千万级/亿级数据高并发场景的调优实战经验；</li><li>精通 MySQL/PostgreSQL 数据库设计与深度调优。熟悉时空数据库（如 PostGIS、时序数据库 InfluxDB/TDengine 等）者优先；</li><li>熟悉主流大模型 API 调用规范，了解 LangChain、LangGraph、Semantic Kernel 等 AI 应用开发框架，有大模型中间层（如 Prompt 管理、RAG 向量检索封装）开发经验者优先。</li></ol>', '5-10年', '68debdfce6ca62fb0nd-29m6E1tU', '深圳 · 罗湖区 · 东门', '19-30K·13薪', 'Java, 不接受居家办公, Spring', '高级Java后端开发工程师', 'https://www.zhipin.com/job_detail/68debdfce6ca62fb0nd-29m6E1tU.html', '股票期权, 节日福利, 员工旅游, 零食下午茶, 年终奖, 团建聚餐, 定期体检, 带薪年假, 五险一金, 意外险, 结婚礼金, 绩效奖金, 生育礼金');
INSERT INTO `jobs` VALUES (567, '巨沃科技', '计算机软件', '100-499人', '不需要融资', '本科', '<p>boss</p><p><strong>岗位职责</strong></p><ol><li>完成软件功能设计；</li><li>负责核心模块的开发，解决复杂的技术问题；</li><li>制定开发计划，并严格监控执行；</li><li>参与软件需求评审、测试用例评审；</li><li>对开发人员的代码进行定期走查，并提出改进意见；</li><li>指导其他开发工程师进行功能开发；</li><li>对开发的功能进行单元测试；</li><li>负责维护历史存储过程工作；</li></ol><p><strong>任职要求</strong></p><ol><li>具有3年以上B/S应用系统项目开发经验，充分理解面向对象编程思想，有较强的逻辑思维能力，有维护过历史存储过程工作优先 ；</li><li>熟练掌握J2EE相关技术和MVC设计模式，熟练掌握Spring，SpringMVC 常用开发框架，熟悉redis，ActiveMQ，dubbo，mongodb；</li><li>熟悉html，css，jquery，ajax开发等前端基本技术，有easyUI使用经验优先考虑；</li><li>熟练使用Eclipse开发工具，及SVN，Maven等项目管理工具 ；</li><li>熟练掌握Mysql，SQL SERVER 数据库开发，能编写复杂SQL语句，视图，存储过程 ；</li><li>能从事较复杂业务模块的设计和开发工作，对电商仓储物流行业有一定的了解， 从ERP，订单管理系统，仓储管理系统，物流管理系统，计费系统项目开发人员优先考虑；</li><li>有良好的学习能力、团队协作能力，主动沟通能力，能够在较大的压力下工作，愿意在团队中共享自己的经验与知识 ；</li><li>有良好的开发习惯，重视开发规程和基础文档制作，具有规范的开发文档编写能力 ；</li><li>有需求分析或系统分析设计经验者优先。</li></ol>', '5-10年', 'abbbfac1b5c75d9203Z63dW-ElBY', '深圳', '15-30K', 'Java, MySQL, Spring', 'Java软件工程师', 'https://www.zhipin.com/job_detail/abbbfac1b5c75d9203Z63dW-ElBY.html', '通讯补贴, 五险一金, 带薪年假, 餐补, 定期体检, 节日福利, 年终奖, 员工旅游, 交通补助, 零食下午茶');
INSERT INTO `jobs` VALUES (568, '快信云', '运营商/增值服务', '20-99人', '未融资', '本科', '<p><strong>工作职责</strong></p><p>1. 负责语音服务系统的开发和维护2. 音视频相关工作的技术方案输出及技术支撑3. 语音服务器如freeswitch的开发配置和维护4.负责呼叫中心系统的开发</p><p><strong>任职资格</strong></p><ol><li>计算机机相关专业全日制本科，5年同岗位工作经验。丰富的呼叫系统经验优先；</li><li>熟练掌握Java语言和数据结构等编程基础3.熟练掌握网络编程和多线程开发4.熟悉WebRTC技术，有Freeswithc二次开发经验5. 对SIP、RTP、SRTP等协议有研究和实际项目经验6.对常用语音编解码了解G711、G729、OPUS等7. 熟悉双向回拨号、隐私呼叫、呼叫中心业务熟悉8. 有语音质检项目经验和AI呼叫项目经验优先9. 熟练网络抓包常用工具的使用10. 熟悉linux常用操作，可编写简单的脚本11. 对工作质量要求高，做事踏实，对学习新事物保有激情。工作时间：9:30-18:30 （7.5小时工作制）周末双休+法定节假日同步完善薪酬</li></ol><p><strong>福利</strong></p><p>• 入职即缴纳五险一金• 带薪年假、节日礼金、年度健康体检</p>', '5-10年', '17e59ae2fb91b01503B_0t69FVpS', '深圳 · 南山区 · 科技园', '15-30K', 'Java, 呼叫系统, 团队管理经验, freeswitch, 语音, 呼叫中心, 语音网关', '语音开发工程师Java（呼叫系统方向）', 'https://www.zhipin.com/job_detail/17e59ae2fb91b01503B_0t69FVpS.html', '有无线网, 五险一金, 带薪年假, 通讯补贴, 生日福利, 零食下午茶, 绩效奖金, 团建聚餐, 全勤奖, 底薪加提成, 定期体检, 节日福利, 员工旅游, 年终奖');
INSERT INTO `jobs` VALUES (569, '英肯智能', '信息安全', '20-99人', '不需要融资', '本科', '<p>自要非外包项目。请注意我们只限统招本科或者以上，英语读写好，有很好的文档总结能力的优先考虑。</p><p><strong>岗位职责</strong></p><ol><li>参与产品需求讨论，负责后台系统的需求分析和功能设计，完成产品的开发和维护；</li><li>快速学习并理解业务知识，准确的实现业务需求，确保安全、质量、性能和可扩展性；</li><li>解决项目开发过程中遇到的技术和业务难题；</li><li>对现有系统持续进行优化和改进；</li><li>高并发系统架构和重构相关工作。</li></ol><p><strong>岗位要求</strong></p><ol><li>5-10年或者以上互联网项目Java开发经验，统招本科及以上学历；</li><li>熟练掌握Java，有扎实的编程功底，具备良好的编码规范，熟悉常用数据结构和算法；</li><li>熟练掌握Spring、SpringBoot、SpringCloud 、Mybatis等开发框架，对框架原理有深入的理解；</li><li>熟悉Mysql，POSTGRESQL数据库，有良好的数据库设计能力和sql编写能力；</li><li>熟悉密钥管理，电子签名等开发；</li><li>英语要求四级或者以上，有银行支付行业开发经验的优先考虑。薪酬说明：1，基本底薪+项目奖金+高额出差补助等，2，2-3年可以申请加入公司合伙人分红计划</li></ol>', '5-10年', '4fa296055dc654f11Xd52di-EFJY', '深圳 · 宝安区 · 西乡', '15-30K·14薪', 'C#, Java, PostgreSQL, SpringCloud, Hadoop, 分布式技术, 软件工程师, 数据结构, Docker, 微服务经验, Linux, MySQL, 服务器端开发, 架构设计经验, Python', 'Java开发工程师', 'https://www.zhipin.com/job_detail/4fa296055dc654f11Xd52di-EFJY.html', '带薪年假, 股票期权, 团建聚餐, 保底工资, 年终奖, 底薪加提成, 员工旅游, 绩效奖金, 交通补助, 五险一金');
INSERT INTO `jobs` VALUES (570, '蓝魔云', '计算机软件', '20-99人', '未融资', '本科', '<ol><li>不限专业 本科 及以上学历，计算机相关专业优先；</li><li>熟练掌握 软件开发理论、研发过程、开发工具，并能灵活应用java语⾔、面向对象、spring全家桶等，熟悉数据库SQL ；</li><li>有4年以上相关经验；</li><li>具备 团队合作、沟通协作能力；</li><li>具备敏捷项目经验 优先；</li><li>有证券公司账户、清算等领域相关经验的优先</li></ol>', '5-10年', 'c6a2a74b58cbbe2a0nJ73N28EVJU', '深圳 · 南山区 · 科技园', '13-14K', 'Java, SpringCloud, MyBatis, Hibernate, MySQL, Redis, 分布式经验, 微服务经验', 'Java（金融证券）', 'https://www.zhipin.com/job_detail/c6a2a74b58cbbe2a0nJ73N28EVJU.html', '五险一金, 保底工资, 绩效奖金, 底薪加提成, 意外险');
INSERT INTO `jobs` VALUES (571, '鼎汇通科技', '计算机软件', '20-99人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><p>1. 负责核⼼系统的设计与开发，参与⾼并发场景下的技术⽅案制定与实施 2. 承担关键模块编码工作，确保代码质量与系统稳定性</p><p><strong>任职要求</strong></p><ol><li>精通Java语言，熟悉主流框架和技术体系</li><li>具备券商⾏业项目经验者优先考虑</li><li>具有良好的逻辑思维和问题解决能力</li></ol>', '5-10年', '11215dc355b052060nBy3N61GFRY', '深圳', '12-16K', 'Java, Spring, SpringCloud, MySQL, 团队管理经验, 架构设计经验, 不接受居家办公', 'java高级研发工程师（必须券商经验）', 'https://www.zhipin.com/job_detail/11215dc355b052060nBy3N61GFRY.html', '绩效奖金, 年终奖, 餐补, 零食下午茶, 底薪加提成, 全勤奖, 带薪年假, 五险一金');
INSERT INTO `jobs` VALUES (572, 'Oceanpayment', '计算机服务', '100-499人', 'A轮', '本科', '<ol><li>本科及以上学历，计算机软件或相关专业，5年以上相关工作经验；</li><li>熟悉 Java EE 相关技术和主流框架及其技术原理，如 Spring、Spring MVC、Spring Boot、Spring Cloud、Tomcat、Maven、Redis、Mybatis 等常用框架和技术；</li><li>熟悉 Java 及多线程编程，有一定的高并发编程经验； 通用技能 （计算机/语言等） 熟悉 HTTP、Linux、SQL、JS、HTML、CSS、AJAX、SVN、GIT、Eclipse、IDEA 等基本开发；</li><li>责任心强，做事细心，有恒心有毅力，具备良好的团队协作精神和承压能力。</li></ol><p><strong>岗位职责</strong></p><ol><li>参与系统需求分析、评审和设计，独立完成功能模块的开发、测试及维护，保证系统性能、稳定性等；</li><li>参与相关开发管理制度和规范的制定，并负责应用到日常工作中；</li><li>指导初/中级开发人员完成系统设计和开发工作，能够根据团队要求对其他人设计和开发的内容进行把关并提出意见；</li><li>快速、准确定位和处理系统缺陷、性能等问题；</li><li>善于问题分析和总结，有一定的独立解决问题的能力；</li><li>根据相关规定编写相应的技术文档，如接口文档、技术说明文档等；</li><li>能对系统进行重构优化，提升系统性能和稳定性；</li><li>完成研发经理或者上级主管分配的其它工作。</li></ol>', '5-10年', 'e9ee1bb858d6fa7b03Rz29q8EVVX', '深圳 · 南山区 · 科技园', '15-25K', 'Java, SpringCloud, MySQL', '高级java工程师', 'https://www.zhipin.com/job_detail/e9ee1bb858d6fa7b03Rz29q8EVVX.html', '员工旅游, 五险一金, 带薪年假, 年终奖, 节日福利, 零食下午茶');
INSERT INTO `jobs` VALUES (573, '智现未来', '互联网', '100-499人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责EES产品后端系统与应用服务端架构设计、核心模块开发及通用组件构建。</li><li>参与产品需求分析和技术方案设计，确保系统具备⾼性能、⾼可⽤性与可扩展性。</li><li>遵循编码规范，编写高质量、可维护的代码，完成模块开发与系统集成。</li><li>协同前端及技术管理团队，明确接口与实现方案，推动功能落地。</li><li>负责现有系统的功能优化、问题排查、性能调优与⼆次开发。</li><li>参与技术文档编写、代码评审与系统部署，保障研发流程规范与系统安全。</li></ol><p><strong>任职要求</strong></p><ol><li>统招本科及以上学历，计算机或相关专业，5年以上Java开发经验。</li><li>具备扎实的Java编程基础，深入理解IO、多线程、集合、HTTP协议及面向对象设计，熟练运用常用设计模式。</li><li>精通Spring全家桶（Spring Boot/Cloud等），熟悉微服务架构设计。</li><li>熟练掌握MySQL、Oracle、Redis等数据库开发与优化，了解NoSQL存储方案。</li><li>熟悉Linux环境及常用命令，具备服务部署、配置与问题排查能力，了解Web安全常见问题与防护策略。</li><li>熟练使用Git进行协同开发，具备良好的代码规范意识和文档编写能力。</li><li>具备良好的沟通协作能力，能融入跨职能团队共同推进项目。</li><li>有非结构化数据处理、知识图谱相关开发或学习经验者优先。</li></ol>', '5-10年', 'b3b87786d431c074031z29i_ElpU', '深圳 · 南山区 · 西丽', '15-22K·13薪', 'Java, 大数据经验, 分布式经验, Markdown解析, 微服务经验, SpringCloud, MySQL, 流式数据, Redis, Dom操作与注入, Spring, Oracle', '后端java开发工程师（需要出差）', 'https://www.zhipin.com/job_detail/b3b87786d431c074031z29i_ElpU.html', '带薪年假, 定期体检, 团建聚餐, 员工旅游, 年终奖, 节日福利, 生日福利, 股票期权, 意外险, 补充医疗保险, 五险一金');
INSERT INTO `jobs` VALUES (574, '潮向数字科技', '广告/公关/会展', '100-499人', '未融资', '本科', '<ol><li>负责后端架构设计与开发，参与技术选型，构建支撑工业数据接入、实时推送与高可⽤集群的分布式系统。</li><li>开发数据接⼊⽹关，对接第三方数据平台，实现OPC UA、MQTT、Modbus TCP等工业协议适配与数据清洗转换。</li><li>负责MySQL/PostgreSQL或Vastbase G100等数据库主备集群搭建、⾼可用配置及增量数据同步策略设计。</li><li>开发权限管理、告警引擎、数据推送、日志审计等核心微服务模块，封装RESTful API与WebSocket实时推送接口。</li><li>与其他端紧密合作，确保技术方案顺利落地，保障业务高效迭代。</li><li>制定开发规范，进行代码评审，编写接口文档与运维手册，配合等保二级安全整改与渗透测试修复。</li></ol><p><strong>任职要求</strong></p><p>本科及以上学历，计算机相关专业，4年以上Java后端开发经验。具备扎实的Java基础，深入理解I/O、多线程、集合等机制，熟悉JVM调优，能独立排查CPU飙升、内存泄漏等线上故障。熟悉Spring Boot/Spring Cloud 框架，熟悉Nginx反向代理与负载均衡配置，具备高并发场景下的接口设计与性能优化经验。熟悉MySQL/PostgreSQL或Vastbase G100数据库，具备主备集群部署、流式复制配置及慢查询优化实战经验。熟悉OPC UA、MQTT、Modbus TCP中至少一种工业通信协议，具备工业数据采集或物联网项目开发经验。熟悉Redis底层数据结构及应用场景，能针对性解决缓存穿透/雪崩等复杂问题。熟练使用Kafka/RocketMQ消息中间件，理解其消息持久化、顺序消息及事务消息机制，有应对消息积压、保证消息可靠性等经验。熟悉Linux环境（银河麒麟V10优先），掌握Docker容器化部署，具备系统服务注册与开机自启配置能力。具备良好的技术文档撰写能力与跨团队协作沟通能力，有责任心与交付意识。加分项：有能源环保、工业数字孪生、智慧工厂项目经验者优先。熟悉Vastbase G100、海量数据库G100或国产数据库高可用集群部署者优先。有银河麒麟V10国产操作系统适配经验者优先。</p>', '5-10年', 'e31e28198f5fca330nFz2NW9FlFU', '深圳 · 福田区 · 新洲', '12-16K', 'Java, MySQL, Spring', 'Java后端开发工程师', 'https://www.zhipin.com/job_detail/e31e28198f5fca330nFz2NW9FlFU.html', '年终奖, 节假日加班费, 全勤奖, 餐补, 团建聚餐, 定期体检, 零食下午茶, 企业年金, 五险一金, 补充医疗保险, 交通补助, 员工旅游, 有无线网, 带薪年假, 节日福利');
INSERT INTO `jobs` VALUES (575, '壹票通科技', '互联网', '0-20人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责公司核心业务平台（Easy / 一票通）的整体技术架构设计与研发工作，能够从0-1搭建系统。</li><li>带领Java研发团队完成产品研发计划，制定开发规范、技术方案及项⽬排期，确保项⽬按时、⾼质量交付。</li><li>负责核心业务模块及核心代码开发，攻克⾼并发、高可用、高性能等技术难题。</li><li>负责系统架构设计，包括微服务、分布式、缓存、消息队列、数据库优化等。</li><li>推动研发流程规范化，负责代码Review、技术培训及团队能力提升。</li><li>与产品、测试、运维等部门紧密协作，保障项目快速迭代上线。</li><li>持续关注行业新技术，推动AI、大模型等新技术在产品中的应用。</li></ol><p><strong>任职要求</strong></p><ol><li>精通Java基础，熟悉JVM、多线程、集合、网络编程。</li><li>精通Spring Boot、Spring Cloud、MyBatis等主流开发框架。</li><li>熟悉MySQL、Redis、MongoDB等数据库及缓存技术。</li><li>熟悉RocketMQ、Kafka、RabbitMQ等消息队列。</li><li>熟悉Docker、Kubernetes、Linux、Nginx等部署技术。</li><li>熟悉Git、Maven、Jenkins等研发工具。</li><li>有高并发、大流量互联网项目经验者优先。管理能力1、具备优秀的项目管理能力，能够合理拆解任务并推动目标落地。</li><li>能带领5-20人的研发团队，高效推进研发进度。</li><li>能建立研发规范、代码规范及开发流程。</li><li>具有较强的沟通协调能力和跨部门协作能力。</li><li>具备结果导向意识，能够确保项目按计划交付。核心要求（重点）1、具备0-1产品研发经验，能够独立完成系统架构设计及项目搭建。</li><li>能够亲自编写核心业务代码，而不仅仅负责管理。</li><li>具备解决复杂技术问题的能力，关键时刻能够带领团队攻坚。</li><li>能够制定研发计划并确保按时完成目标。</li><li>具有创业公司经验或互联网平台经验者优先。加分项1、有AI、大模型、智能推荐系统开发经验。</li><li>有OTA、航空、旅游、电商、支付平台经验。</li><li>熟悉NDC、GDS、航旅业务。</li><li>有SaaS平台或国际化产品研发经验。</li><li>有AWS、阿里云、腾讯云等云平台经验。</li><li>强烈的责任心和主人翁意识。</li><li>良好的团队管理能力和执行力。</li><li>能够承担压力，推动项目快速落地。</li><li>热爱技术，愿意持续学习与分享。关键词：Java｜Spring Boot｜Spring Cloud｜微服务｜Redis｜MySQL｜Docker｜高并发｜技术架构｜团队管理｜0-1产品研发｜核心代码开发｜AI平台</li></ol>', '5-10年', 'b252d92a41f2c8c80nV9396-F1VY', '深圳 · 南山区 · 科技园', '13-18K', 'JVM, Java, Nginx, Tomcat, 团队管理经验, 分布式经验, Hadoop, Redis, SQL Server, Docker, 微服务经验, MySQL, MyBatis, MongoDB, 架构设计经验', 'JAVA开发工程师', 'https://www.zhipin.com/job_detail/b252d92a41f2c8c80nV9396-F1VY.html', '五险一金');
INSERT INTO `jobs` VALUES (576, '康比特信息技术', '计算机软件', '20-99人', 'A轮', '本科', '<p><strong>岗位描述</strong></p><ol><li>与需求分析、产品设计人员沟通确定详细设计方案、开发计划;</li><li>负责产品研发与维护，根据产品需求完成详细设计文档设计（包括数据库结构设计和接口设计);</li><li>协助解决系统常见技术故障，能按时、独立、⾼质量地完成⼯作；</li><li>具备对运⾏系统的性能调优，BUG分析及修正等优化工作，保证系统的稳定性；</li><li>按照设计要求，完成编码工作及单元测试。</li></ol><p><strong>任职要求</strong></p><ol><li>全⽇制本科学历或以上，计算机相关专业。</li><li>具备两年或以上java开发经验、具有规则引擎、报表引擎开发经验，熟悉面向对象思想，具有良好的规范开发习惯；</li><li>熟悉常用的开发工具idea、git、maven、jenkins等；</li><li>熟练主流开发框架: Spring、MyBatis等，熟悉redis等中间件，有分布式项目开发经验；</li><li>熟悉关系型数据库其中一种，精通sql语句的优化；</li><li>熟悉html、css、javascript等前端技术；</li><li>有良好的数据结构和算法设计基础优先；</li><li>深入了解软件开发、测试流程具备中型项目成功经验；</li><li>具备良好的沟通能力、组织能力及团队协作精神。</li></ol>', '5-10年', 'bfc8e4a33a1f2fa90nFy2ty1GFVU', '深圳 · 福田区 · 莲花', '16-25K', 'Java, C++, Spring, SpringCloud, MyBatis, MySQL, Redis, Oracle, 架构设计经验, 团队管理经验, 不接受居家办公, 医疗信息化, 架构师', '高级java研发工程师', 'https://www.zhipin.com/job_detail/bfc8e4a33a1f2fa90nFy2ty1GFVU.html', '节日福利, 带薪年假, 五险一金');
INSERT INTO `jobs` VALUES (577, '上海络岳咨询管理', '互联网', '20-99人', '', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责公司项目的后端开boss发工作，参与需求分析、系统设计、编码实现、测试及维护等环节；</li><li>根据项目需求，参与制定技术方案，负责完成系统模块的设计与开发；</li><li>参与编写项⽬相关技术⽂档，确保项⽬质量；</li><li>协同前端开发工程师完成系统功能调试与优化；</li><li>跟进新技术动态，根据项目需求引⼊新技术，提高系统性能和开发效率；</li><li>遵循公司开发规范，确保代码质量，参与代码审查；</li><li>完成上级领导交办的其他工作。</li></ol><p><strong>任职要求</strong></p><ol><li>计算机相关专业，全日制本科及以上学历；</li><li>良好的沟通、团队协作能力；</li><li>有良好的责任心4、3年以上相关开发经验；</li><li>熟悉javase，熟悉servlet原理6、熟悉springboot、mybatis等框架7、熟悉mysql数据库8、有react开发经验优先</li></ol>', '5-10年', '0e8cc4056a6cc2580nFz09S-EVJY', '深圳 · 福田区 · 梅林', '12-18K', '', 'Java开发(Base深圳银行财资系统）', 'https://www.zhipin.com/job_detail/0e8cc4056a6cc2580nFz09S-EVJY.html', '');
INSERT INTO `jobs` VALUES (578, '及时雨', '物联网', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>领导研发团队完成智慧消防软硬件产品开发，包括火灾预警算法优化、消防设备协议开发、可视化指挥系统搭建；</li><li>牵头攻克消防数据分析、多源传感器融合、应急响应决策等核心技术难题；</li><li>建立技术标准体系，确保产品符合国家消防信息化建设规范； 二、项目管理与交付 1. 统筹管理智慧城市消防物联网项目全生命周期，制定项目里程碑计划；</li><li>组建跨部门项目团队（研发/实施/运维），协调政府、消防部门及第三方供应商资源；</li><li>监控项目进度与质量，实施风险管控，确保项目按时交付验收；</li><li>建立项目知识管理体系，编制智慧消防系统部署及应急预案； 三、团队与生态建设 1. 搭建技术团队；</li><li>培养项目经理梯队，推行敏捷项目管理体系；</li><li>维护产学研合作关系，参与智慧消防行业标准制定； 四、业务协同工作 1. 协同市场/销售部门制定产品商业化方案，参与重点客户技术方案交付与招投标；</li><li>参与客户、合作商以及政府主管部门的业务技术沟通工作；</li><li>参与公司各类标准的制定工作。</li></ol><p><strong>任职要求</strong></p><ol><li>计算机/自动化/消防工程相关专业硕士以上学历，8年+物联网行业经验 2. 3年以上智慧消防/应急管理领域技术管理经验；</li><li>精通技术栈：物联网架构、大数据平台、微服务架构；</li><li>项目管理能力：熟悉智慧城市类项目管理特点，具有多项目并发管理经验。</li></ol>', '5-10年', '6f05201b68df828d03B52d-9FFZZ', '深圳 · 南山区 · 科技园', '15-30K', 'Java, 大数据经验, 物联网经验, SpringCloud, MySQL, Dubbo, SQL Server, 架构设计经验, Spring', '高级软件开发经理', 'https://www.zhipin.com/job_detail/6f05201b68df828d03B52d-9FFZZ.html', '带薪年假, 节假日加班费');
INSERT INTO `jobs` VALUES (579, '易美科', '计算机软件', '100-499人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责微服务架构的ERP、MES系统的开发和研发工作；</li><li>参与产品需求分析、模块设计，和文档编写；</li><li>根据开发进度和任务分配，完成编码开发、测试和持续完善更新;</li><li>定期汇总、分析技术问题，对产品优化提出改进建议。</li></ol><p><strong>任职要求</strong></p><ol><li>计算机及相关专业，本科及以上学历。</li><li>至少5年以上Java开发经验，同时具备3年以上前端实际项目开发经验。</li><li>具有扎实的计算机理论基础和Java基础知识功底。</li><li>熟悉Spring、Spring MVC、Spring Boot等；熟悉常⽤的设计模式。</li><li>熟悉SQLServer、Oracle、MySQL等关系数据库的应⽤与开发，熟练掌握各种SQL技巧，能够对⼤数据进行调优。</li><li>熟悉前端基础技术，包括HTML5、CSS3、JavaScript（ES6+），深刻理解浏览器渲染原理、DOM操作及事件循环机制，具备跨浏览器兼容性处理能力。</li><li>精通⾄少一种主流前端框架（Vue.js / React / Angular），熟练使用其生态工具（如Vuex/Pinia、Redux、React Router等），具备组件化设计与前端工程架构能力。</li><li>熟悉高并发系统的设计与应用开发。</li><li>熟悉Sping Clound、ZooKeeper等微服务和分布式技术。</li><li>熟悉Git、Maven、Jenkins，熟悉linux操作系统，熟悉常用Linux命令。</li><li>熟悉Docker、Tomcat、Nginx、Apache等常用的部署容器和方案。</li><li>有较强的专业知识学习能力，思维缜密逻辑清晰，有责任性。</li></ol>', '5-10年', 'e9637c9b827dd1170nF839i8FVtX', '深圳 · 宝安区 · 西乡', '15-25K', 'Java, Spring, SpringCloud, Nginx, Docker, SQL Server, MySQL, Oracle, 架构设计经验, 微服务经验, ERP开发经验, MES开发经验, 高并发系统, 金蝶, 鼎捷', '高级java开发工程师', 'https://www.zhipin.com/job_detail/e9637c9b827dd1170nF839i8FVtX.html', '带薪年假, 团建聚餐, 节日福利, 餐补, 定期体检, 五险一金, 员工旅游, 生日福利');
INSERT INTO `jobs` VALUES (580, '灵感游戏', '游戏', '100-499人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责海外休闲手游服务器功能开发、维护及性能优化，保障系统稳定、高效运行；</li><li>参与服务器架构设计、需求评审及技术方案制定；</li><li>优化⾼并发、⾼可⽤系统，提升性能、稳定性及资源利用率；</li><li>快速定位并解决线上问题，完善复盘与预防机制；</li><li>与客户端、策划、测试等团队协作，推动需求高质量交付。</li></ol><p><strong>岗位要求</strong></p><ol><li>全⽇制本科及以上学历，计算机相关专业；</li><li>5年以上Java服务端开发经验，具备高并发系统设计与性能优化经验；有游戏服务器开发经验优先；</li><li>扎实掌握Java、多线程、NIO及常用设计模式；</li><li>熟悉Spring Boot、Redis、MySQL、消息队列等主流技术栈；</li><li>熟悉JVM、数据库优化、Linux及CI/CD，了解Docker、Kubernetes；</li><li>具备独立分析和解决线上复杂问题的能力，责任心强，沟通协作良好。我们希望你具备1.较强的问题分析及解决能力，能够独立排查线上复杂问题，对线上质量负责，关注玩家体验和业务结果；</li><li>较强的主动性和责任心，能够主动推动问题解决及系统持续优化，对高并发、高稳定性系统有持续优化意识；</li><li>对游戏研发充满兴趣，关注系统稳定性及玩家体验。</li><li>良好的沟通协作能力，具备团队合作意识5.乐于学习新技术，能够推动团队技术持续提升。</li></ol>', '5-10年', '72f68441925249110nF50924E1JT', '深圳 · 南山区 · 科技园', '15-25K', 'Java, Netty, MySQL, 游戏后端经验, 不接受居家办公, 游戏服务端, 游戏Java, 高并发', '高级游戏Java开发工程师', 'https://www.zhipin.com/job_detail/72f68441925249110nF50924E1JT.html', '餐补, 知识库共享, 年度体检, 交通补助, 各种节日活动, 包吃, 住房补贴, 零食下午茶, 绩效奖金, 五险一金, 定期体检, 年终奖, 团建聚餐, 节日福利, 带薪年假, 股票期权, 租房补贴');
INSERT INTO `jobs` VALUES (581, '沃享国际', '跨境物流', '100-499人', '未融资', '大专', '<p><strong>岗位职责</strong></p><ol><li>参与业务需求分析，完成核心功能模块的详细设计与编码实现；</li><li>负责Java后端服务开发（Spring Boot/Spring Cloud体系），优化系统性能与稳定性；</li><li>参与数据库设计（MySQL等），编写高效SQL及存储过程，解决数据一致性与性能问题；</li><li>配合测试团队完成功能测试、性能测试，快速定位并修复线上问题；持续优化代码结构，推动技术落地（如微服务拆分、缓存策略、异步处理等）。</li></ol><p><strong>任职要求</strong></p><ol><li>计算机相关专业毕业， 5年以上Java开发经验能独立负责模块开发，有电商、物流、⾦融等⾼并发业务经验者优先；</li><li>有⾼并发、高可用系统开发经验（如分布式锁、限流、熔断）；</li><li>扎实的Java基础（集合、多线程、JVM内存模型），熟练使⽤Spring Boot/Spring MVC/MyBatis，了解微服务架构（Spring Cloud）；</li><li>熟悉MySQL（索引优化、事务隔离级别、SQL调优），了解Redis（缓存策略、数据结构）、MQ（Kafka/RabbitMQ）；</li><li>良好的编码习惯（代码可读性、设计模式应用），责任心强，能与产品、测试团队高效沟通，技术热情高，主动学习新技术（如容器化、云原生）。</li></ol>', '5-10年', '51c00d18104daba70nF63tm5FlJW', '深圳 · 龙岗区 · 坂田', '16-23K·14薪', 'Java, 架构设计经验, 大数据业务处理经验, 跨境相关行业, ToB系统, 独立系统模块架构设计', 'java开发工程师', 'https://www.zhipin.com/job_detail/51c00d18104daba70nF63tm5FlJW.html', '零食下午茶, 有无线网, 五险一金, 生日福利, 团建聚餐, 员工旅游, 带薪年假, 全勤奖, 年终奖, 节日福利');
INSERT INTO `jobs` VALUES (582, '擎创信息', '计算机软件', '100-499人', 'C轮', '本科', '<p>此岗位为外包项目，需要驻场，地点在研祥科技大厦，介意勿扰，谢谢。项目主要做湖仓一体运维数据中台开发。</p><p><strong>岗位职责</strong></p><p>1.能够按时完成分配的开发任务2.能够⾼效的完成任务的内容3.良好的沟通习惯4.良好的代码风格，良好的代码注释习惯5.有⼀定的⽂档编写能力</p><p><strong>任职要求</strong></p><ol><li>本科及以上学历，5年以上后端开发工作经验；</li><li>⼯作认真、严谨、敬业、较强的执行能力，良好的沟通协作能力；</li><li>有扎实的编程能力和良好的代码编写规范，数据结构和算法基础，有运维工具开发经验者优先；</li><li>擅长java编程语言，熟练使用常用后端开发框架SpringBoot；</li><li>熟悉数据库及中间件技术，如MySQL、ClickHouse、Redis、Kafka等6.有开源大数据开发相关经验dolphinscheduler，seatunnel优先</li></ol>', '5-10年', 'b60e414ef690a6cc0nJ72t-7FlBV', '深圳 · 南山区 · 科技园', '15-23K', 'Java, SpringCloud, Spring, Kafka, Redis, 大数据经验', '大数据高级java开发工程师', 'https://www.zhipin.com/job_detail/b60e414ef690a6cc0nJ72t-7FlBV.html', '员工旅游, 生日礼品, 带薪年假, 定期体检, 年终奖, 股票期权, 技术前沿, 晋升机会多, 通讯补贴, 技术大咖多, 绩效奖金, 五险一金, 零食下午茶, 补充医疗保险, 培育机制好, 团建聚餐, 节日福利, 生日福利, 氛围超好');
INSERT INTO `jobs` VALUES (583, '深圳市辉智云创科技', '互联网', '100-499人', '', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责解决支付系统运行过程中出现的各类技术问题，进行故障排查、性能调优，确保系统7×24小时稳定运行，降低因技术故障导致的业务风险。</li><li>关注行业技术发展趋势，引入先进的技术理念和解决方案，对现有支付系统的技术架构进行评估和升级，保持系统的技术先进性。</li></ol><p><strong>任职要求</strong></p><ol><li>技术能力： - 5年或以上支付系统或金融系统开发经验，熟悉支付行业技术架构； - 精通Java语言，熟悉Spring Cloud、Dubbo等微服务框架； - 掌握分布式事务、消息队列（RocketMQ/Kafka）、缓存（Redis）等核心技术； - 熟悉MySQL分库分表方案，有支付对账系统设计经验者优先。</li><li>领域知识： - 熟悉支付清算流程、四方/三方支付体系、金融合规要求； - 了解第三方支付接口、银行快捷支付、代扣代付等实现逻辑； - 对支付路由、通道稳定性优化、资金安全有实际项目经验。 加分项：- 有跨境支付、聚合支付、数字货币系统开发经验； - 熟悉金融级网络通信协议（如ISO8583、SWIFT）；</li><li>软性能力 - 具备极强的责任心，能承受支付系统的高压工作场景； - 逻辑严谨，并对复杂业务场景的代码实现有较强的抽象能力- 具备良好的团队合作意识，帮助团队成员，达成统一目标</li></ol>', '5-10年', '54ab60bab369141703Z63d-8FVZY', '深圳 · 南山区 · 科技园', '18-23K·13薪', 'Java, 不接受居家办公, 分布式经验, SpringCloud, MySQL, Redis, Dubbo, 架构设计经验', '支付平台研发工程师（中级/高级）', 'https://www.zhipin.com/job_detail/54ab60bab369141703Z63d-8FVZY.html', '');
INSERT INTO `jobs` VALUES (584, '成都淘购乐精选电...', '互联网', '20-99人', '', '本科', '<p>【</p><p><strong>岗位职责</strong></p><p>】●参与后台服务的全生命周期研发，覆盖需求评审、技术方案设计、接口契约定义、编码实现、单元测试、联调与上线发布等环节，对交付物的性能、可用性、安全性与可维护性负责。●承担银行存款、贷款、账务等核⼼系统的接口开发与对接联调，跟进接口在⽣产环境的运⾏情况，保障接口稳定可用。●负责生产环境的问题排查与应急处理，通过⽇志分析、全链路追踪、数据核对等手段，独立完成账务差错的定位与处理，并推动事后复盘与改进。●参与系统的代码评审、技术文档编写、知识沉淀等团队协作工作，对历史代码或复杂模块进行安全、可控的重构与优化。●与产品、测试、运维以及业务方协同推进项目落地，对所负责模块的交付质量和上线效果负责。【</p><p><strong>任职要求</strong></p><p>】●计算机科学与技术、软件工程、信息系统、通信工程等计算机相关专业。从事3年及以上 Java 后端开发经验。●有银行核心系统（存款、贷款、账务、清结算等任一方向）研发经验者优先。●精通 Java 及其主流生态，熟练运用 Spring Boot / Spring Cloud 进行微服务开发，深入理解 Spring 框架核心机制（IoC、AOP、声明式事务等）。熟练使用 Gradle 或 Maven 进行工程构建与依赖治理，能够独立处理多模块工程组织、私服配置等问题。熟悉 MySQL 或 TiDB，具备表结构设计、索引优化与 SQL 调优能力。●熟悉金融场景下的资金安全实践，包括长短款处理、幂等控制、对账机制等。具备较强的生产问题排查与应急处理能力，有过线上故障定位与修复的实战经验●编码规范，注重代码可读性与文档完备性，代码评审中能够主动发现并指出潜在风险。具备较强的代码阅读与逆向分析能力，能够在陌生代码库中快速厘清调用链路与业务逻辑。文档习惯良好，能够独立输出清晰的接口文档、设计文档、运维手册和复盘报告。薪资待遇：13-15K左右 面试定 入职五险一金上班时间：工作时间：9:00-9:30 18:00-18:30 弹性半小时打卡 周末双休 中午12:00-14:00午休上班地址：广东省深圳市南山区金港街88号</p>', '5-10年', '346a057b4873dc9f0nJ439q9FFdT', '深圳 · 南山区 · 科技园', '14-17K', 'Java, Spring, SpringCloud, MySQL, 微服务经验, 不接受居家办公', 'Java开发工程师', 'https://www.zhipin.com/job_detail/346a057b4873dc9f0nJ439q9FFdT.html', '生日福利, 保底工资, 有无线网, 加班补助, 五险一金, 带薪年假, 节日福利, 绩效奖金, 节假日加班费, 员工旅游, 定期体检');
INSERT INTO `jobs` VALUES (585, '云游千川', '游戏', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责服务端核心代码编写、文档编撰、性能调优；</li><li>负责游戏项目的逻辑设计、开发及维护工作；</li><li>优化后端服务架构，保证快速迭代及持续交付。</li></ol><p><strong>任职资格</strong></p><ol><li>JAVA基础扎实，具备5年以上的JAVA开发经验；</li><li>精通JAVA编程、多线程编程、线程安全、JVM；</li><li>具备服务端数据存储功能的设计能⼒， 有MySQL，Redis， mongoDB的 设计、开发、优化经验；</li><li>熟练掌握常⽤框架，如Spring Cloud，熟悉常⽤组件如Kafaka、Zookeeper 等，并理解其原理，有应用开源框架及组件扩展游戏服务器的能力；</li><li>熟练掌握⾄少一种长连接架构，如基于tcp协议的长连接6. 熟悉分布式技术（RPC框架、缓存、消息系统、热部署、JMX等），对高可用、高性能服务器开发有深入理解；</li><li>良好的沟通能力和团队合作精神，有责任心，能够承受较强的工作压力8. 熟悉Linux的基本操作，关注行业的技术发展方向；9 .海外游戏项目经历优先。</li></ol>', '5-10年', 'd6106364f6c97dc50nB629--FFZR', '深圳 · 南山区 · 科技园', '17-30K·15薪', 'Java, 不接受居家办公, 微服务经验, SpringCloud, MySQL, 游戏行业', '高级java研发工程师', 'https://www.zhipin.com/job_detail/d6106364f6c97dc50nB629--FFZR.html', '餐补, 生日福利, 团建聚餐, 节日福利, 绩效奖金, 交通补助, 年终奖, 定期体检, 五险一金, 零食下午茶, 带薪年假, 加班补助');
INSERT INTO `jobs` VALUES (586, '掌上智珠', '计算机软件', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>参与保险业务中台系统架构，以及需求分析、系统设计、开发/联调等工作；</li><li>负责平台技术预研、选型和难点攻关，保障系统高可用性、稳定性和可扩展性；</li><li>负责线上系统的维护，快速定位分析解决各类系统问题，保障系统稳定运营；</li><li>持续关注技术领域变化趋势，确保团队的技术规划满足业务高速增长的需求。</li></ol><p><strong>岗位要求</strong></p><ol><li>统招本科学历及以上，计算机软件相关专业，了解常见的数据结构和算法；</li><li>5年以上JavaEE应用开发经验，具备阿里云微服务环境项目经验者优先；</li><li>JAVA基础扎实，深入理解io、多线程、集合等，熟悉JVM、安全及性能调优；</li><li>熟练掌握 Spring框架全家桶，熟悉常见设计模式，熟悉通讯协议及网络编程；</li><li>熟练掌握MySQL数据库设计及性能调优，熟悉Redis应用及MyBatis、OAuth2；</li><li>熟悉Nacos、SpringCloud框架及常用组件，熟悉消息队列中间件的应用场景；</li><li>熟悉Git、Linux、Nginx、Tomcat、Jenkins，了解Docker、Drools、BladeX；</li><li>扎实掌握 Java NIO/BIO/AIO 编程模型，深入理解 Socket 通信原理，熟悉 TCP/IP、UDP 协议特性及调优；熟练使用 Netty 进行网络编程9.熟悉 Netty 的核心组件（Channel、Pipeline、Handler、EventLoop 等），能解决 Netty 相关的粘包 / 拆包、内存泄漏等问题；</li><li>具有较强的编程能力，能够完成较复杂的交互及流程设计和实现，具备良好的编程及单元测试习惯，能够编写高质量技术文档；</li></ol>', '5-10年', '98c30bd2dba39c571Xd_2t21GFFU', '深圳 · 南山区 · 科技园', '15-25K', 'Linux, 服务器配置, 微服务架构, 多线程, 架构师, 容器技术, 网络编程, 数据结构', '高级Java开发工程师', 'https://www.zhipin.com/job_detail/98c30bd2dba39c571Xd_2t21GFFU.html', '五险一金, 定期体检, 交通补助, 年终奖, 节日福利, 团建聚餐, 员工旅游, 带薪年假, 零食下午茶');
INSERT INTO `jobs` VALUES (587, '新永胜制衣厂', '服装/纺织', '100-499人', '未融资', '本科', '<p><strong>任职资格</strong></p><ol><li>大学本科及以上学历，计算机相关专业，有5年以上JAVA工作经验。</li><li>对技术充满热情，对业界新兴技术感兴趣，能主动调研和分享，并应用到业务中；对AI应用有强烈兴趣的优先。</li><li>具备良好的团队合作精神和沟通能力，能够承担压力，快速适应新环境。</li><li>扎实的Java编程基础，熟悉多线程、并发等基础架构；</li><li>熟悉缓存、消息机制和实现，有mongoDB、Redis、MQ、ES使用等经验的优先；</li><li>熟悉Java互联网领域相关及技术及框架，如Springboot、Spring Cloud、MyBatis等开源框架；</li><li>有线上高并发、JVM调优、大数据量处理经验优先；</li><li>熟悉主流数据库Oracle、MySQL、SQL server，能熟练编写SQL语句，熟悉数据库设计原理，能优化SQL；</li><li>有大数据处理分析经验，熟悉Spark、Hive、Flink等大数据处理平台；</li><li>熟悉htmlL、js、jquery，layui，vue等技术，能独立完成简单页面开发；</li><li>熟练使用linux常用命令；</li></ol><p><strong>工作内容</strong></p><ol><li>参与产品策划和立项，主导项目评审，对立项前的风险进行评估和管理。</li><li>负责项目计划的制定、管理和推动，确保项目按规划要求完成。</li><li>处理项目日常问题，主导项目各阶段关键评审和阶段性总结。</li><li>完成功能模块的需求调研、概要设计、详细设计、代码编写、单元测试、系统联调和集成测试。</li><li>核心代码与组件编写，共享重用代码库开发。</li><li>解决开发中所遇到的技术难题，并能给与同事技术指导。</li><li>学习和研究新技术以满足产品的需求，根据开发过程中的体验对产品提出改进建议。</li></ol><p><strong>福利待遇</strong></p><ol><li>本公司严格按照劳动法执行，为员工购买相关社会保险；</li><li>享有国家劳动法规的带薪年假及婚假、产假、病假等；</li><li>公司免费提供住，宿舍安装空调、热水、衣柜；</li><li>上班时间：实行5天八小时工作制；</li></ol>', '5-10年', 'b9f875bb538fd10603Vz3N25ElZR', '深圳 · 宝安区 · 沙井', '15-20K', 'JVM, MES开发经验, Java, SpringCloud, MySQL, Redis, MongoDB, Spring', '高级后端开发工程师', 'https://www.zhipin.com/job_detail/b9f875bb538fd10603Vz3N25ElZR.html', '节日福利, 五险一金, 带薪年假, 员工旅游, 餐补');
INSERT INTO `jobs` VALUES (588, '迈科思腾', '信息安全', '20-99人', '未融资', '本科', '<ol><li>有Java/J2EE开发经验；</li><li>熟悉主流Java开发框架，如Spring系列框架、iBatis/MyBatis；</li><li>熟悉常见的软件开发模式，并能够在项目中运用；</li><li>熟悉1-2种常见的关系型数据库的开发和设计，如MySQL、SQL Server、Oracle等；</li><li>具备如下技术的开发经验，或有能力快速学习掌握： MongoDB、Redis、ActiveMQ/RabbitMQ/Kafka；</li><li>熟悉Linux常见命令，能编写简单的Shell；</li><li>逻辑思维清晰，责任心强，沟通能力强，具备良好的团队合作精神；</li><li>有大型软件公司工作经验的优先考虑；</li><li>熟悉软件开发流程，熟悉单元测试开发，有敏捷开发经验者优先考虑；</li><li>了解云计算（如Spring Cloud）、微服务架构或者DevOps并有项目经验者优先考虑；</li><li>了解theamleaf、Ajax、Jquery等前端技术的优先考虑</li></ol>', '5-10年', 'f269bf165b89400133V52dW4FlY~', '深圳 · 南山区 · 西丽', '13-20K', 'Java, 物联网经验, 不接受居家办公, 分布式经验, SpringCloud, Redis, HTML, Spring, SQL, 微服务经验, MySQL, MyBatis, MongoDB, Memcached', 'Java高级开发工程师', 'https://www.zhipin.com/job_detail/f269bf165b89400133V52dW4FlY~.html', '年终奖, 五险一金, 员工旅游, 带薪年假');
INSERT INTO `jobs` VALUES (589, '未来清研', '人工智能', '20-99人', '未融资', '本科', '<p>工boss作地点：深圳南山工作经验：5 年以上学历要求：统招本科及以上</p><p><strong>职责描述</strong></p><p>深度参与用户需求调研，主导技术⽅案设计，完成系统架构设计及核⼼代码开发。构建基于 Java 的 AI 智能体框架，解决 Agent 框架中的 RAG 系统、上下⽂工程、各类工具建设等问题。建设⽀持多租户能力的管理平台，实现用户创建 / 编辑 AI 智能体、版本管理、报表生成等功能。</p><p><strong>任职要求</strong></p><p>一、基础经验要求3 年及以上工作经验，1 年以上大模型智能体从业经验，重点高校毕业。逻辑清晰，思路灵活，解决问题能力强，对 AI 应用有独特心得和见解，乐于拥抱 AI 技术。二、技术栈要求掌握 Java、Python 语言，熟练使用 Spring、Spring MVC、Spring Boot、Spring Cloud、MyBatis 等开源框架；对常用设计模式、设计原则、数据结构有一定理解，深入掌握面向对象思想。熟悉 Nginx、Redis、Kafka、Jenkins 等中间件的使用及部署；熟练使用 Linux 命令。掌握 HTML/CSS/JS 开发技术，有 React/Vue 主流框架开发经验。深入了解AI Agents技术栈，掌握Dify、OpenClaw、RAGFlow等开源框架，有丰富的智能体开发和Prompt Enginering经验。</p>', '5-10年', '936afc6f57f0ab8c0nZ82tu4E1tS', '深圳 · 南山区 · 科技园', '15-20K', 'Java, 不接受居家办公, Docker, 架构设计经验, Python', 'AI 智能体 Java 全栈开发', 'https://www.zhipin.com/job_detail/936afc6f57f0ab8c0nZ82tu4E1tS.html', '有无线网, 五险一金, 年终奖, 团建聚餐, 带薪年假, 免费工装, 绩效奖金');
INSERT INTO `jobs` VALUES (590, '深圳市中洲商置投资', '房地产开发经营', '100-499人', '', '大专', '<p>参与商业管理公司自建系统的全流程开发工作【</p><p><strong>岗位职责</strong></p><ol><li>协助复杂业务系统的技术方案设计与评审；</li><li>配合⾼级藁城市解决⾼并发、⾼可用、高性能场景下的技术难题；</li><li>参与系统重构、性能优化与技术选型；</li><li>参与系统稳定性保障与线上问题排查。【</li></ol><p><strong>任职资格</strong></p><ol><li>核心技术栈· Java：精通JVM、多线程、集合框架，深入理解Spring Boot/Cloud生态；· 数据库：精通MySQL，具备索引优化、SQL调优、分库分表实战能力；· 中间件：熟练掌握Redis、Kafka/RabbitMQ，能合理设计缓存与异步消息方案；· 部署与安全：熟悉Docker/Linux部署环境，了解接口安全及权限体系设计。</li><li>架构与工程能力· 高并发/高可用：具备限流、熔断、降级等系统稳定性设计经验，能独立完成性能压测与瓶颈定位；· 架构设计：擅长微服务拆分、分布式事务、系统分层与技术选型，能输出清晰可落地的技术方案；· 工程规范：能制定开发规范，通过工具链与流程提升团队交付质量。</li><li>前端协作能力· 熟悉前后端分离架构，了解Vue/React框架及Webpack/Vite等构建工具，可与前端团队高效协同。</li><li>软技能· 良好的业务理解能力，能将技术语言转化为业务价值；· 技术方案表达清晰，具备跨团队推动能力；· 责任心强，具备主人翁意识，主动承担稳定性保障与难点攻关。</li></ol>', '5-10年', '37b865f37d860d6c0nJ70ty6EFdW', '深圳 · 福田区 · 车公庙', '16-19K·15薪', 'Java, Spring, Kafka, MyBatis, MySQL, Redis, Oracle, 架构设计经验, ERP开发经验, 不接受居家办公', '高级开发经理', 'https://www.zhipin.com/job_detail/37b865f37d860d6c0nJ70ty6EFdW.html', '');
INSERT INTO `jobs` VALUES (591, '南京盛世安链云计算', '计算机软件', '100-499人', '', '本科', '<p><strong>岗位职责</strong></p><p>负责基于金蝶云星瀚（苍穹）平台的二次开发工作，包括业务插件开发、表单扩展、工作流定制及报表开发等，满⾜业务个性化需求。深⼊理解财务业务流程，将业务需求转化为技术⽅案，完成需求分析、概要设计和详细设计文档的编写。参与云星瀚平台已有二开功能的优化与改进，排查并修复系统运⾏中的技术问题，持续提升系统稳定性与用户体验。负责金蝶云星瀚平台与其他业务系统（如法务、影像系统等）的二开接口对接与集成开发，确保数据流转准确、高效。编写单元测试，参与代码评审，确保交付代码质量符合团队规范；配合测试团队完成联调与上线部署工作。</p><p><strong>任职要求</strong></p><p>本科及以上学历，计算机、软件工程或相关专业，3-5年软件开发工作经验。精通 Java 语言，熟悉 Spring Boot、Spring Cloud 等主流框架，具备良好的面向对象设计能力。具备至少1年以上金蝶云星瀚（苍穹）平台二次开发经验，熟悉苍穹开发平台的插件机制、扩展开发、BOS设计器、脚本开发等核心能力。熟练掌握关系型数据库（如 MySQL、PostgreSQL、Oracle）的使用与SQL调优，了解数据库设计范式及索引优化策略。具有良好的逻辑分析能力和问题定位能力，能够独立完成从需求分析到上线部署的完整开发流程。具备良好的文档编写习惯和团队协作意识，沟通表达清晰，责任心强。优先条件有金蝶云星瀚财务云费用共享、应收应付二开经验者优先。持有金蝶苍穹平台相关开发认证者优先。有大中型企业 ERP 系统实施或二次开发项目经验者优先。了解低代码/无代码开发理念，具备平台化扩展思维者优先。</p>', '5-10年', '8bc1c701619817a80nV73tW0EFRS', '深圳 · 南山区 · 蛇口', '14-24K', 'Java, MySQL, 金蝶, 云苍穹, Spring', '云苍穹中高级开发', 'https://www.zhipin.com/job_detail/8bc1c701619817a80nV73tW0EFRS.html', '');
INSERT INTO `jobs` VALUES (592, '斯维尔', '计算机软件', '100-499人', '已上市', '本科', '<p><strong>岗位职责</strong></p><ol><li>java低代码平台系统分析、选型、设计、代码编写；</li><li>公司平台类系统开发；</li></ol><p><strong>任职资格</strong></p><ol><li>全日制本科（硬性要求）及以上，计算机相关专业，5年及以上Java开发经验、熟练掌握常用的设计模式;</li><li>熟悉LowCodeEngine或类似低代码开发平台（最少一种）;</li><li>熟练掌握Jsp、Spring Boot、Spring Cloud、Spring、SpringMvc、Mybatis等技术；</li><li>掌握Html、Css、JavaScript等web开发技术，深入了解web/ajax的工作原理，熟悉Vue框架；</li><li>熟悉Linux操作系统，掌握常用Linux操作命令；</li></ol>', '5-10年', '4a178127729fac4903B539W7E1BY', '深圳 · 南山区 · 科技园', '15-22K', 'Java, SpringCloud, MyBatis, Spring', 'Java框架开发工程师', 'https://www.zhipin.com/job_detail/4a178127729fac4903B539W7E1BY.html', '餐补, 节假日加班费, 五险一金, 通讯补贴, 餐补, 带薪年假, 定期体检, 员工旅游, 绩效奖金, 节日福利, 团建聚餐, 生日福利');
INSERT INTO `jobs` VALUES (593, '广东国科城市大脑科技', '计算机软件', '20-99人', '', '本科', '<p><strong>岗位职责</strong></p><ol><li>参与智能服务的引擎建设(执行引擎，流程引擎，规则引擎)，负责服务端技术方案设计、需求把控及核心功能开发，细化拆解业务需求并实施；</li><li>搭建智能化的服务平台，提升用户交互体验。</li><li>参与智能数据能⼒建设，帮助业务精细化运营⼯具。</li><li>指导及参与产品架构规划、性能优化、故障排查和解决、安全加固等⼯作；</li><li>指导初级、中级工程师，组织团队技术分享，促进团队成员共同进步。协调及驱动业务团队间的配合协作；</li><li>能够深入理解复杂的业务场景，不断优化重构现有服务架构；围绕现有体系，探索构建智能服务体系平台的可⾏方案。</li></ol><p><strong>任职要求</strong></p><ol><li>统招本科及以上学历且学信网可查，具备扎实的编程基础和数据结构算法基础，优秀的编程能力和问题解决能力；</li><li>5年以上互联网行业研发经验，具备业务核心系统或高并发系统项目开发经验；</li><li>精通Java及面向对象设计开发，深入理解面向服务的架构，精通java web开发经验，熟悉JavaWeb应用框架和工具链，熟悉Linux/MySQL/NoSQL等；</li><li>优秀的模块设计、抽象能力，能独立的进行系统设计与思考；</li><li>熟练掌握网络通信原理，熟悉服务器端，数据端的主流技术或框架；</li><li>善于交流，具备良好的团队合作精神和协调沟通能力；</li><li>自我驱动，善于钻研，勤于思考总结，结果导向。</li></ol>', '5-10年', '849b060f1a8759a20nZ40tq7FFdV', '深圳 · 龙华区 · 民治', '15-28K', 'Java, Spring, SpringCloud, MyBatis, MySQL, Redis, 架构设计经验, 微服务经验, 物联网经验, 团队管理经验, 大数据经验, 不接受居家办公', 'Java（高级）', 'https://www.zhipin.com/job_detail/849b060f1a8759a20nZ40tq7FFdV.html', '团建聚餐, 绩效奖金, 带薪年假, 生日福利, 节假日加班费, 加班补助, 五险一金, 节日福利');
INSERT INTO `jobs` VALUES (594, '深圳宏景动力信息...', '计算机软件', '100-499人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>参与系统架构设计与核心模块开发，完成高质量的代码编写与单元测试；</li><li>根据业务需求进行技术方案设计与实现，推动系统性能优化与稳定性提升；</li><li>负责后端服务的设计、开发、部署及维护，保障系统⾼效稳定运⾏；</li><li>协同前端、产品、测试团队完成项⽬交付，持续优化开发流程与技术方案；</li><li>参与代码评审，确保代码质量符合规范，推动团队技术能力提升。</li></ol><p><strong>任职要求</strong></p><ol><li>具备扎实的Java编程基础，熟悉JVM原理及多线程编程；</li><li>熟悉主流开发框架如SpringBoot、SpringCloud、MyBatis等；</li><li>熟悉分布式架构设计，了解微服务、消息队列、缓存机制等核⼼技术；</li><li>能够独立完成模块设计与开发任务，具备良好的问题分析与解决能力；</li><li>具备良好的沟通能力和团队协作意识，有较强的责任心和执行力。</li><li>有AI或者金蝶苍穹平台开发经验尤佳。</li></ol>', '5-10年', '503657667e8d72d80nd52tW6EFJR', '深圳 · 南山区 · 科技园', '15-20K', 'JVM, Java, 不接受居家办公, Tomcat, PostgreSQL, Redis, SQL Server, Spring, ERP开发经验, 微服务经验, Zookeeper, MySQL, MyBatis, 架构设计经验, Oracle', 'Java开发工程师(中高级)', 'https://www.zhipin.com/job_detail/503657667e8d72d80nd52tW6EFJR.html', '年终奖, 定期体检, 加班补助, 带薪年假, 股票期权, 零食下午茶, 员工旅游, 通讯补贴, 五险一金, 节日福利, 交通补助');
INSERT INTO `jobs` VALUES (595, '数鑫科技', '计算机软件', '20-99人', 'A轮', '本科', NULL, '5-10年', '525e8fef94fe57991HZz2tW_GVpX', '深圳 · 南山区 · 蛇口', '18-19K', 'Java, Nginx, 大数据经验, 不接受居家办公, Docker, 微服务经验, SpringCloud, MySQL, Redis, Spark', '服务端高级工程师', 'https://www.zhipin.com/job_detail/525e8fef94fe57991HZz2tW_GVpX.html', '团建聚餐, 节日福利, 五险一金, 股票期权, 零食下午茶, 生日福利, 带薪年假, 员工旅游');
INSERT INTO `jobs` VALUES (596, '联新移动医疗', '医疗健康', '100-499人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责公司核心产品的前后端全栈开发，独立完成从需求分析到架构设计、编码实现、测试上线的全流程工作；</li><li>深度运用 AI 辅助编程⼯具（如 ClaudeCode、AugmentCode、Cursor等）提升开发效率，优化代码质量，探索 AI 在软件开发中的创新应⽤场景；</li><li>主导技术难题攻关，解决复杂业务逻辑、⾼并发、高可用等技术挑战，持续提升系统性能与稳定性；</li><li>参与技术架构设计与技术决策，推动研发流程优化，引⼊前沿技术与工具，带领团队提升整体研发效能；</li><li>结合 AI 工具特性，沉淀可复用的开发方法论、代码模板或工具链，赋能团队成员提升效率。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，计算机相关专业，5 年以上前后端全栈开发经验，有大型系统或高并发项目实战经验；</li><li>AI 工具应用能力：精通至少 2 种以上 AI 辅助编程工具的高级用法，能熟练运用 AI 进行代码生成、重构、调试、文档生成等，并有实际项目落地案例；</li><li>技术栈要求：- 前端：熟悉React框架，熟悉 HTML5、CSS3、TypeScript，了解前端工程化与性能优化；- 后端：精通 Java 等至少一种主流语言，熟悉微服务架构、RESTful API 设计，了解分布式系统原理；- 数据库：熟悉 MySQL等关系型数据库，以及 Redis/MongoDB 等 NoSQL 数据库的设计与优化；- DevOps：了解CI/CD 流程，能利用 AI 工具加速部署与运维脚本开发；</li><li>具备强烈的技术好奇心与学习能力，能快速掌握新技术并结合 AI 工具落地；</li><li>优秀的问题分析与解决能力，能通过 AI 工具辅助定位复杂 bug 并提出最优解决方案；</li><li>良好的沟通能力与团队协作精神，能清晰表达技术思路并推动跨团队合作。加分项：有软考的资格证书，如系统架构师、软件设计师。</li></ol>', '5-10年', '07336a587e7295f403xz39q6ElRX', '深圳', '15-27K', 'Java, 分布式经验, 微服务经验, MySQL, 接受无前端经验/技能, Redis, 其他, MongoDB', 'Java工程师（偏后端）', 'https://www.zhipin.com/job_detail/07336a587e7295f403xz39q6ElRX.html', '定期体检, 年终奖, 带薪年假, 股票期权, 补充医疗保险, 通讯补贴, 五险一金, 员工旅游');
INSERT INTO `jobs` VALUES (597, '星际通', '广告/公关/会展', '20-99人', '未融资', '本科', '<p>【</p><p><strong>岗位职责</strong></p><ol><li>根据需求进行数据库设计和开发，保障数据的完整性和安全性;</li><li>参与系统架构设计和技术选型，保持系统的可扩展性和可维护性;</li><li>进⾏代码编写、功能测试和编写相关⽂档，保证代码质量和项⽬进度;</li><li>协助老板及业务人员等进⾏项目需求讨论和问题解决;</li><li>积极参与团队技术分享，提升团队整体技术水平。【</li></ol><p><strong>任职要求</strong></p><ol><li>Java核心与架构:精通Java语言及JVM原理，深入理解面向对象设计与常用设计模式，具备大型分布式、高并发、高可用系统的完整设计、开发与调优经验；</li><li>分布式技术栈:*精通Spring Cloud微服务生态，熟悉其核心组件（Nacos, Sentinel, Seata, RocketMQ 等）*熟悉分布式系统理论（CAP,BASE），有分布式事务、分布式锁、服务熔断与降级、链路追踪的实际应用经验4、数据库核心能力:*精通MySQL，深入理解索引、锁、事务隔离级别、执行计划优化，具备丰富的SQL调优和慢查询处理经验*熟悉至少一种主流NoSQL数据库（如Redis、MongoDB），了解其适用场景、数据结构和集群部署模式*对数据库高可用方案（如主从复制、读写分离、分库分表中间件）有实际经验者优先。</li><li>高阶技能与经验：*熟悉多线程与高并发编程，对JUC、线程池、并发容器有深入理解*有服务编排、零代码/低代码平台、复杂企业级应用架构设计经验者优先*有业财结算、交易支付、金融相关系统开发经验者优先6、有前端开发或基础技能为加分项，英语阅读良好可支持基本沟通。岗位</li></ol><p><strong>福利</strong></p><p>五险一金（一档医保），双休，9：30-18：30，午休1.5小时，法定节假日，带薪年假，每周下午茶。</p>', '5-10年', 'd7f32010ef0f8d9a0nZ73Nq6FldX', '深圳 · 龙岗区 · 坂田', '12-15K', '', '高级开发工程师', 'https://www.zhipin.com/job_detail/d7f32010ef0f8d9a0nZ73Nq6FldX.html', '绩效奖金, 年终奖, 团建聚餐, 五险一金, 底薪加提成, 生日福利, 带薪年假, 员工旅游, 节日福利, 零食下午茶');
INSERT INTO `jobs` VALUES (598, '网度通信', '信息安全', '20-99人', '未融资', '本科', '<p><strong>岗位要求</strong></p><ol><li>负责OA系统的实施和日常运维支持；</li><li>协助对接业务部门沟通，分析业务部门需求，提出优化改善建议，并提供可行性解决方案；</li><li>协助完成与OA有关的信息化建设及流程优化工作；</li><li>根据需求对oa流程、功能权限进行优化推广；</li><li>负责oa与其他系统对接，比如如金蝶erp等岗位技能要求；</li></ol><p><strong>任职要求</strong></p><ol><li>熟悉泛微OA（E9）系统实施、开发上线或项目管理经验优先；</li><li>熟悉处理有较好的oa流程优化、ESB接口、表单建模经验；</li><li>熟悉Java,Jsp,Javascript等语言开发及脚本编写，熟悉SQL语言;</li><li>熟悉企业管理及日常运作流程；</li><li>具有金蝶erp接口对接开发经验。</li><li>做事积极主动，勤勉敬业，沟通协调协作能力佳 。</li></ol>', '5-10年', '8fa75b89c2704d7b03dy2tS0F1BZ', '深圳 · 龙岗区 · 坂田', '13-18K·13薪', 'Python, 不接受居家办公, MySQL, 团队管理经验, ERP开发经验, 大数据经验, 泛微OA, OA二次开发, 每周双休', '泛微OA实施开发', 'https://www.zhipin.com/job_detail/8fa75b89c2704d7b03dy2tS0F1BZ.html', '底薪加提成, 全勤奖, 五险一金, 团建聚餐');
INSERT INTO `jobs` VALUES (599, '深圳华筑通', '互联网', '20-99人', '未融资', '本科', '<p><strong>一、岗位职责</strong></p><p>1.技术架构与系统建设负责公司核心系统的整体技术架构设计与演进优化现有系统性能（高并发订单、库存、发票、Webhook等场景）规划微服务 / 分布式 / 数据分片 / 缓存 / 消息队列等架构体系推动系统从“可⽤”⾛向“⾼可用 + 可扩展 + 可商业化2.团队管理与技术建设搭建并管理后端 / 前端 / DevOps 技术团队制定开发规范、代码标准、发布流程提升团队工程能⼒（Code Review / 架构设计 / 性能优化）3.AI与产品技术融合参与 AI Agent 产品架构设计（多模型接入：OpenAI / Gemini / Qwen / DeepSeek 等）推动 AI 在公司项目场景中的落地设计可扩展的 AI 调度与路由系统（Multi-LLM Gateway）4.技术治理与稳定性负责线上系统稳定性（99.9%+）处理高并发、限流、消息堆积、数据一致性问题优化数据库结构与分库分表策略（或去分片重构）</p><p><strong>二、任职要求</strong></p><p>1.8年以上 Java / 后端开发经验（或等效技术背景），4年以上技术团队管理经验（带过5人以上团队）2.熟悉分布式系统架构设计（Spring Boot / 微服务 / MQ / Redis）3.有高并发系统经验（订单、电商、支付、交易系统优先）4.能独立负责复杂系统架构设计与落地加分项：有跨境电商系统 / ERP / SaaS经验熟悉海外电商生态（Mercado Livre / NF-e / 税务系统）有 AI 系统落地经验（LLM、多模型路由、RAG等）熟悉数据库分片 / ShardingSphere / 性能优化有创业公司技术负责人经验薪资面议 双休 入职购买六险一金 一档社保</p>', '5-10年', 'eae2aa355e34fba90nF-2964F1VU', '深圳 · 福田区 · 香蜜湖', '18-30K', 'Java', '技术总监', 'https://www.zhipin.com/job_detail/eae2aa355e34fba90nF-2964F1VU.html', '员工旅游, 绩效奖金, 节日福利, 通讯补贴, 餐补, 加班补助, 交通补助, 定期体检, 带薪年假, 工龄奖, 生日福利, 补充医疗保险, 五险一金');
INSERT INTO `jobs` VALUES (600, '广州中钦科技服务', '互联网', '20-99人', '', '本科', '<p><strong>岗位职责</strong></p><p>负责后端服务核心功能的设计与开发，支撑大规模实时通信场景，主要使用 java 语⾔ 进⾏开发；承担后端系统的架构实现、业务逻辑开发与性能调优，保障系统⾼可用与可扩展性；负责产品版本迭代发布、线上问题排查与应急处置，持续提升系统稳定性。</p><p><strong>岗位要求</strong></p><p>本科以上学历，计算机、软件工程及相关专业毕业；5年以上Java开发经验，了解java的开发和应⽤，熟悉高并发、高性能的分布式系统的设计及应用；熟悉Linux、Nginx、MySQL，了解并能使用k8s、docker、openstack，熟悉阿里云的云计算产品；熟悉MVC模式，熟练掌握Spring mvc，jpa，mycat；熟悉分布式服务框架：Dubbo、MQ、Zookeeper、Spring Cloud Config；有大型互联网后台服务设计经验；熟悉敏捷开发熟悉软件开发生命过程，熟悉软件优化及重构；精通面向对象分析设计，熟悉设计模式，具备平台领域大型系统设计、开发、调优经验；具备较强的工作主动性及创新精神；具有较强的沟通能力和协调能力，责任心强，良好的团队合作精神；思维敏捷、清晰，做事认真、有条理；</p>', '5-10年', '3a1fb08ef7e896580nBy3d25FldX', '深圳 · 福田区 · 车公庙', '15-16K', 'Java, SpringCloud, MySQL, k8s, Spring, Oracle', 'Java开发', 'https://www.zhipin.com/job_detail/3a1fb08ef7e896580nBy3d25FldX.html', '法定节假日三薪, 节假日加班费, 节日福利, 带薪年假, 五险一金');
INSERT INTO `jobs` VALUES (601, '小思科技', '电子商务', '100-499人', 'B轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>根据产品经理输出的业务需求内容，完成产品功能模块的设计、开发、单元测试；</li><li>编写高质量的代码，参与内部软件系统设计及代码评审工作；</li><li>负责基于Java技术的内部应用系统的开发实现、运维等工作；</li><li>独⽴负责相关功能的开发；包含不限于问题处理、Bug修复等；</li><li>与开发上下游⼈员密切协作，不断提升产品的品质；</li><li>承担部份⽇常系统技术支持工作。</li></ol><p><strong>任职要求</strong></p><ol><li>本科及以上学历，5年以上JAVA开发经验，JAVA基础扎实，理解IO、多线程、集合等基础框架，了解JVM原理；</li><li>掌握Spring、SpringBoot、Spring Cloud、Mybatis-Plus等框架；</li><li>熟悉web前端开发技术；如VUE、Element等；</li><li>掌握并熟练使⽤各种关系型、非关系型数据库（Mysql，MongoDB等）；了解事务、索引等技术及原理；</li><li>熟悉分布式系统的设计和应用，熟悉分布式、缓存、消息等机制；能对分布式常用技术进行合理应用，解决问题；</li><li>有一定项目管理经验或开发团队管理经验；</li><li>有跨境电商行业背景或SCM供应链、WMS仓储等系统开发经验优先。</li></ol>', '5-10年', 'bd93bd550d34c5aa031929i5GVJY', '深圳', '15-30K', 'Java, Spring, 不接受居家办公, SQL Server, MongoDB, MySQL, 团队管理经验, 跨境, SCM, WMS', '中/高级JAVA开发工程师（跨境电商）', 'https://www.zhipin.com/job_detail/bd93bd550d34c5aa031929i5GVJY.html', '绩效奖金, 员工旅游, 运动协会, 工龄奖, 外派学习培训, 定期体检, 年终奖, 通讯补贴, 月度评优, 全勤奖, 保底工资, 团建聚餐, 生日福利, 底薪加提成, 带薪年假, 五险一金, 节日福利, 零食下午茶');
INSERT INTO `jobs` VALUES (602, '华洲知识产权代理...', '检测/认证/知识产权', '0-20人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>参与公司软件系统的需求分析、架构设计及核⼼模块开发；</li><li>负责软件功能的编码实现、单元测试及系统集成；</li><li>根据项⽬进度完成开发任务，配合团队进⾏问题排查与技术优化；</li><li>编写相关技术文档，确保代码质量与系统可维护性；</li></ol><p><strong>任职要求</strong></p><ol><li>具备扎实的编程基础和良好的代码规范意识；</li><li>熟练掌握主流开发语言及相关技术框架，能够独⽴完成模块开发；</li><li>熟悉常用数据库操作及SQL优化，了解缓存、消息队列等中间件技术；</li><li>具备良好的沟通能力和团队协作精神，有较强的学习与问题解决能力；</li></ol>', '5-10年', '9ee73015538b90a80nBz2tu8GFVY', '深圳 · 宝安区 · 西乡', '10-11K', 'Java, C, C++, Golang, Python, Spring, SpringCloud, MyBatis, Hibernate, Kafka, MySQL, Redis, Oracle, MongoDB, HBase', '软件开发', 'https://www.zhipin.com/job_detail/9ee73015538b90a80nBz2tu8GFVY.html', '底薪加提成, 保底工资');
INSERT INTO `jobs` VALUES (603, '麟瞳视界', '互联网', '0-20人', '不需要融资', '本科', '<ol><li>需求分析、系统设计、代码编写及相关文档编写等开发工作；</li><li>参与公司项目的开发、测试、优化等工作；</li><li>独⽴完成个⼈承担模块或项⽬的开发和测试；</li><li>把控软件测试任务的进度和质量，使其满足项目schedule的要求；</li><li>按时整理发布测试报告，定期梳理测试管理⼯作存在的不足和改善方案；</li></ol><p><strong>任职要求</strong></p><ol><li>有Java 5年以上开发经验；</li><li>熟练运用Java常用类库以及其他框架（Gin、SpringCloud、Springboot、Hibernate、Mybatis、Kafka消息队列等）；</li><li>熟练使用关系型数据库，有NoSql数据库（redis/mongodb等）设计和应用经验；</li><li>有系统需求分析、设计经验以及项目管理经验；</li><li>有软件测试和调优经验；</li><li>具备良好的沟通能力和学习能力，责任心强，有一定的抗压能力。</li></ol>', '5-10年', '75ee910b8238c3460nRy3NW4FFBQ', '深圳 · 宝安区 · 西乡', '15-18K', '', 'java后端开发', 'https://www.zhipin.com/job_detail/75ee910b8238c3460nRy3NW4FFBQ.html', '绩效奖金, 五险一金');
INSERT INTO `jobs` VALUES (604, '鹏智瑞', '互联网', '100-499人', '未融资', '本科', '<p>岗位boss</p><p><strong>职责</strong></p><ol><li>负责营销平台以及经销商管理平台的后端核心开发、维护与性能优化，确保系统高可用性与稳定性，面对⾼并发导致的线上问题，有⼀套⾃己的处理思路及排查办法；</li><li>深入理解并持续优化现有业务系统，核⼼模块包括：营销活动平台、商户运营、经销商客户服务赋能等；</li><li>基于当前业务，主动思考ai赋能点并落地执行；</li><li>编写高质量的技术文档，参与系统架构设计评审，遵循Java、微服务(Cloud)​ 等技术栈规范，并保证代码质量；</li><li>配合完成系统上线部署、监控运维及故障排查，并协助团队完成从合作方到自主团队的知识转移与系统接管。</li></ol><p><strong>任职要求</strong></p><ol><li>4-10年 Java 后端开发经验，计算机相关专业优先；</li><li>精通SpringBoot、SpringCloud微服务架构，熟练使用MyBatis/MyBatis-Plus 等 ORM 框架；</li><li>熟练使用 MySQL，精通 SQL 优化、索引设计、事务处理，了解分库分表思路；</li><li>熟练使用 Redis、RabbitMQ/RocketMQ、Elasticsearch 等主流中间件，掌握缓存、消息队列、分布式锁等设计方案；</li><li>了解营销技术核心业务场景：用户拉新 / 促活 / 留存、优惠券 / 积分 / 会员体系、营销活动配置、进销存广告投放归因、私域运营、营销数据埋点与分析；</li><li>有进销存系统、营销系统、电商营销、用户运营平台、广告支撑系统开发经验优先；</li><li>了解主流大模型 API（豆包、通义千问、chatgpt、grok等），***会使用Claude Code、Cursor、codeX，有 Java 对接大模型 API 的实际项目经验；</li><li>掌握基础 Prompt 工程思路，能配合业务优化 AI 调用效果；对dify、coze等平台对接springcloud服务有一定了解及应用。</li></ol><p><strong>综合素质</strong></p><ol><li>良好的业务理解与沟通能力，能快速对接营销业务需求；</li><li>责任心强，具备线上问题排查与抗压能力，可支撑营销活动高峰期保障工作；</li><li>积极主动，具备团队协作精神与技术钻研能力；</li><li>关注 AI、营销技术、进销存/供应链行业趋势，有持续学习的意识。</li></ol>', '5-10年', '1d19f47b24b585070nB72ty0EltW', '深圳', '12-20K·13薪', 'JVM, Java, Tomcat, 微服务经验, SpringCloud, MySQL, MyBatis, Redis, MongoDB, Spring', 'Java开发工程师', 'https://www.zhipin.com/job_detail/1d19f47b24b585070nB72ty0EltW.html', '餐补, 定期体检, 有无线网, 年终奖, 带薪年假, 夜班补助, 零食下午茶, 生日福利, 绩效奖金, 员工旅游, 五险一金, 节日福利');
INSERT INTO `jobs` VALUES (605, '圣格灵', '信息安全', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>对项目需求进行分解、设计、编写计划、风险预估、实施及问题协调；</li><li>参与产品需求的讨论和梳理，撰写技术方案；</li><li>编写清晰、高效、可维护的代码，并对已有代码进⾏优化；</li><li>精通 HTTP/HTTPS 协议、TCP/IP ⽹络模型，具备⽹络编码、网络故障排查能力；</li><li>熟悉接口签名、加密传输、证书认证（X509、TLS）等⽹络安全编码实践；</li><li>负责核心模块的接口文档、技术设计文档编写与维护，配合前端完成前后端联调；</li><li>参与线上系统问题排查，保障系统稳定运行。</li></ol><p><strong>任职要求</strong></p><ol><li>全日制本科及以上学历，计算机相关专业，5年以上Java开发经验；</li><li>精通Java语言及 Spring Boot / Spring Cloud / MyBatis 等主流框架，具备高并发、高可用服务设计与调优经验；</li><li>具备扎实的网络编程基础，熟悉 HTTP/HTTPS、TCP、UDP 等网络协议，能独立完成网络层编码与调试；</li><li>熟悉Redis、MongoDB、Memcached等非关系型存储的使用；</li><li>熟练使用MySQL / PostgreSQL，具备业务表设计、索引优化、事务管理相关能力；</li><li>掌握 Linux 环境下的部署与故障排查，熟悉Docker / Kubernetes、Git、Maven等常用工具，了解 CI/CD 流程；</li><li>责任心强，具备良好的问题分析能力、团队协作能力，能独立承担核心模块开发并跟进进度。具备以下条件者优先：具备医疗、政务类项目实践经验。</li></ol>', '5-10年', '5f9167b932a0da9e0nBz3924ElVU', '深圳 · 福田区 · 车公庙', '15-20K', 'Java, Spring, SpringCloud, MyBatis, Nginx, MySQL, 微服务经验', '高级Java工程师(网络)', 'https://www.zhipin.com/job_detail/5f9167b932a0da9e0nBz3924ElVU.html', '节日福利, 生日福利, 高温补贴, 五险一金, 带薪年假');
INSERT INTO `jobs` VALUES (606, '君宏科技', '计算机软件', '20-99人', '', '本科', '<p>【</p><p><strong>技术要求</strong></p><ol><li>Java 基础扎实，熟练掌握 JavaEE 编程，拥有良好的编码习惯，有独立分析设计小型系统经验；</li><li>熟练掌握开发主流框架 SpringBoot、SpringMVC、Hibernate、Mybatis等，了解主流 MVC、ORM 框架的技术优缺点；</li><li>熟练使用构建工具 Maven、Ant等，熟练使⽤版本库⼯具 Git，熟练使⽤ Nginx、Tomcat 等；</li><li>熟练 SQL 分析及调优，有 Mysql、 Oracle、Elaticsearch 数据库和搜索引擎的开发和使用经验；</li><li>有丰富的第三方接口对接经验,包括且不限于公开的 OpenAPI、微信、地图；</li><li>熟悉基于 Centos、Ubuntu 等 Linux 平台的部署及维护⼯作；</li><li>能独立承担产品和应用的运行维护，分析并解决出现的问题，持续优化和改进；</li><li>熟练编写技术文档，评估项目工期的能力；</li><li>对前端开发和调试有一定了解；</li><li>了解集群、分布式、代码重构，具有相关经验。【</li></ol><p><strong>职位描述</strong></p><ol><li>我们希望TA是一个对开发有主见的攻城狮；</li><li>能对产品需求、系统架构以及现有业务提出改善意见以及合理技木实现方案,并高效实施落地；</li><li>能配合公司发展方向，及时有效的解决系统遇到的瓶颈与挑战；</li><li>能在代码复杂度与功能实现上权衡利弊，及时有效交付公司分派的技术任务；</li><li>关注业内动态、有开源社区贡献者优先，有可视化/BI产品开发经验者优先；</li><li>统招学信网本科学历。计算机相关专业，3年以上 Java 开发相关的工作经验，全栈工程师或有往全栈方向发展想法的优先;</li><li>热爱开发工作，对编码工作有高度热情，能独立承担并完成领导交付的工作；</li><li>工作认真、有责任心，踏实可靠，沟通表达能力较好，注重团队合作，良好的职业操守，学习能力强，有创新精神。</li><li>具有金融行业经验者优先</li></ol>', '5-10年', '4a6721bd16ab99be0nV539S9F1ZX', '深圳 · 福田区 · 车公庙', '14-18K', 'Java, Nginx, 不接受居家办公, Tomcat, 分布式经验, 监控类经验, PostgreSQL, Elasticsearch, Docker, 微服务经验, 金融相关经验优先, MySQL, 权限类经验, Oracle', '中/高级java开发工程师', 'https://www.zhipin.com/job_detail/4a6721bd16ab99be0nV539S9F1ZX.html', '');
INSERT INTO `jobs` VALUES (607, '拓必达科技', '人工智能', '100-499人', '未融资', '本科', '<p>有智能体，大模型 项目经验</p><p><strong>岗位职责</strong></p><p><strong>职责</strong></p><ol><li>优化后端服务代码结构、数据库查询逻辑及接口性能，引入Redis缓存、消息队列等中间件，降低数据库压⼒，提升接口响应速度，保障系统低延迟、高可用运行。</li><li>负责接口文档的编写、维护与更新，配合前端完成接口联调，及时响应并解决联调过程中的后端问题，确保前后端协同高效推进。</li><li>基于Dify低代码大模型平台源码进行二次开发（python），结合业务需求优化平台功能、适配内部业务场景，集成SpringAI、WebFlux相关能力，完善AIAgent构建、Prompt编排及ToolCalling相关功能，保障平台与后端服务的高效联动。</li></ol><p><strong>职责</strong></p><ol><li>负责线上问题排查与修复，快速定位后端服务异常、接口报错、数据库问题等，形成问题复盘报告，沉淀排查经验，避免同类问题重复出现。</li><li>配合运维团队完成系统监控、日志分析，优化服务稳定性，提升系统容错能力。</li></ol><p><strong>职责</strong></p><ol><li>持续跟踪Java后端领域新技术、新框架，结合项目实际运行数据迭代优化系统性能；沉淀开发经验，编写技术文档、接口手册，参与团队技术分享，完善技术体系。</li><li>协助完成代码评审，提出代码优化建议，规范开发流程，提升团队开发效率与代码质量。</li></ol><p><strong>岗位要求</strong></p><ol><li>精通Java编程，深入理解SpringBoot、MyBatis-Plus、SpringAI等主流框架的核心原理与应用场景，能独立完成后端项目及响应式流式AI接口开发；</li><li>掌握MySQL数据库设计与优化技巧，熟悉JDBC编程及事务管理；</li><li>熟悉Redis缓存、Kafka消息队列等中间件的使用与优化，能运用中间件解决业务痛点；</li><li>熟悉Linux操作系统，掌握Shell脚本编写、Docker容器化部署；</li><li>熟练使用 AI编码工具 开发代码（必须），IDEA、Git、等开发相关工具；</li><li>了解微服务架构理念，具备接口设计、业务拆解、需求分析能力，熟悉接口联调流程；</li><li>具备基础的代码优化、问题排查能力，了解常见的后端性能优化方案；</li><li>熟悉Dify等低代码大模型平台，掌握WebFlux响应式开发，能基于SpringAI与WebFlux实现响应式流式AI接口；</li><li>具备AIAgent构建、Prompt编排、自动化流程设计能力，掌握基于MCP协议的多智能体通信、上下文管理与ToolCalling集成技巧。</li></ol>', '5-10年', 'f8ba7834a137413f0nR82d6_FlpW', '深圳 · 盐田区 · 沙头角', '15-23K', 'Java, Spring, SpringCloud, MySQL, 智能体, dify', 'Java开发工程师', 'https://www.zhipin.com/job_detail/f8ba7834a137413f0nR82d6_FlpW.html', '生日福利, 员工旅游, 五险一金, 高温补贴, 节日福利, 意外险, 团建聚餐, 零食下午茶, 带薪年假');
INSERT INTO `jobs` VALUES (608, '德世普安', '计算机服务', '100-499人', '未融资', '本科', '<ol><li>扎实的javaboss编程基础，熟练掌握spring mvc、spring boot、spring cloud等框架，有参与过单体项目、前后端分离项目、微服务项目的开发和部署:</li><li>熟悉IDEA、Git、Jenkins、Nginx等工具使⽤;</li><li>熟悉常规数据库(SQLServer、0racle、MySql)操作，熟练使⽤SQL语⾔;</li><li>熟悉前端基础技术html/css/is，掌握至少一种主流前端框架(如React、Vue.is或Angular);</li><li>掌握soap、restful协议webservice开发和EXCEL导⼊导出POI/easyexcel技能;</li><li>有sap ui5/Fiori、hybris/commerce项目开发经验优先:</li><li>具备良好的沟通能力和逻辑思维以及良好的团队合作精神;能够承担一定的工作压力。</li></ol>', '5-10年', '05c52a8957fa529103N_39-9GFFV', '深圳 · 南山区 · 科技园', '16-30K', 'Java, Spring, SpringCloud, SQL Server', 'sap commerce开发', 'https://www.zhipin.com/job_detail/05c52a8957fa529103N_39-9GFFV.html', '节日福利, 法定节假日三薪, 定期体检, 员工旅游, 交通补助, 带薪年假, 通讯补贴, 五险一金, 年终奖, 生日福利, 带薪病假, 零食下午茶, 住房补贴, 意外险, 补充医疗保险');
INSERT INTO `jobs` VALUES (609, '易瑞通', '计算机软件', '0-20人', '', '本科', '<p><strong>主要职责</strong></p><ol><li>负责低代码平台的技术把控，确保平台的稳定性、安全性和可扩展性。监督外部供应商的技术执行，确保项目按照既定的时间节点和质量标准完成。</li><li>快速学习并掌握低代码平台（如Mendix），并能够进行高效的编码工作。</li><li>带领外包团队，进行日常的技术开发和维护工作，确保项目按时交付。</li><li>设计和实施系统架构，包括后端服务、数据库设计和API开发。</li><li>优化系统性能，提升用户体验，包括前端和后端的优化。</li><li>编写和维护技术文档，确保团队成员对系统有清晰的理解。</li><li>作为技术领导，指导团队成员，提升团队整体技术水平。</li><li>参与代码审查，确保代码质量和项目标准。</li><li>与产品经理、设计师和其他利益相关者紧密合作，确保技术决策与业务目标一致。</li></ol><p><strong>任职要求</strong></p><ol><li>计算机科学或相关领域本科及以上学历。</li><li>至少4-5年的后端Java开发经验，熟悉Java EE、Spring Boot、Spring Cloud、微服务架构等。</li><li>至少1-2年的前端React开发经验，熟悉React生态和相关工具链，包括Redux、React Router等。</li><li>熟悉Mendix或其他低代码平台，有实际开发经验者优先。</li><li>熟悉数据库技术，如MySQL、PostgreSQL，以及非关系型数据库如MongoDB。</li><li>熟悉Linux操作系统，能够进行基本的系统管理。</li><li>良好的编码习惯，包括单元测试、代码审查和文档编写。</li><li>具备良好的沟通能力和团队合作精神。</li><li>能够快速学习新技术，适应快速变化的技术环境。</li><li>具备良好的英语读写能力，能够阅读英文技术文档。</li></ol>', '5-10年', 'b4867b6657c2f99b1H1529m_FFVY', '深圳 · 宝安区 · 西乡', '18-20K', 'Java, Spring, SpringCloud, MySQL, 团队管理经验, 架构设计经验, ERP开发经验, 不接受居家办公, React, Mendix', 'Java高级全栈开发工程师（会react开发）', 'https://www.zhipin.com/job_detail/b4867b6657c2f99b1H1529m_FFVY.html', '');
INSERT INTO `jobs` VALUES (610, '港融科技', '计算机软件', '100-499人', '不需要融资', '本科', '<p>该岗位将参与香港金融系统研发工作，英语读写能力（硬性）、粤语听说可作为⼯作语⾔（优先），有测试环节。岗位</p><p><strong>福利</strong></p><p>早九晚六、周末双休，全额缴纳社保公积⾦，入职即购买深圳一档五险⼀金，入职当年享受司龄年假。需派驻集团办公（桂湾站），属于我司正式员工，业务发展稳定。</p><p><strong>一、岗位职责</strong></p><ol><li>负责分析用户需求，根据功能或程序规范开发高质量的软件程序；</li><li>负责所开发应用程序的代码质量，如进行单元测试、技术测试等；</li><li>配合其他团队开展用户验收测试（UAT）等测试活动；</li><li>基于功能或技术需求开展系统影响分析，参与软件问题的排查与解决；</li><li>与开发负责人密切协作，确保按时完成分配的任务与交付物；</li><li>持续跟进 IT 领域的最新技术趋势，保持技术能力的与时俱进。</li></ol><p><strong>二、任职要求</strong></p><ol><li>计算机科学、电子工程或相关专业本科/硕士学历；具备至少6年实操软件开发及测试支持相关工作经验。</li><li>精通 Java 语言，深入理解 Java 技术生态系统（RESTful、Spring 等）；</li><li>精通关系型数据库，熟练掌握 Guess DB、PostgreSQL、Oracle、MS SQL Server、MySQL 等数据库产品；</li><li>精通内存数据库如 Redis，熟练掌握 SQL 语法；具备扎实的数据结构与算法功底。</li><li>具备优秀的分析能力、口头与书面沟通能力；</li><li>优秀的英语读写能力（必须）；</li><li>具备 Linux 使用经验与相关知识；具备 TCP/IP、单播 / 组播等网络编程知识者优先考虑。</li></ol>', '5-10年', 'c2404a01b5d175ae0nFz39i_E1RS', '深圳 · 南山区 · 科技园', '17-26K·13薪', 'Java, Hibernate, 不接受居家办公, PostgreSQL, MySQL, MyBatis, Redis, SQL Server, Spring, Python', 'Intermediate Java Developer（Java开发）', 'https://www.zhipin.com/job_detail/c2404a01b5d175ae0nFz39i_E1RS.html', '法定节假日三薪, 节日福利, 生日福利, 节假日加班费, 团建聚餐, 五险一金, 定期体检, 员工旅游, 加班补助, 股票期权, 年终奖, 五险一金, 带薪年假');
INSERT INTO `jobs` VALUES (611, '道致科技', '互联网', '100-499人', '', '本科', '<p><strong>工作职责</strong></p><p>主导核心模块的架构设计与代码规范制定带领团队完成复杂项目排查并解决线上疑难问题（性能瓶颈、并发问题）推动工程效率提升，制定开发规范、CI/CD 流程参与项⽬，能做好安排，在⼯作范畴内对具体问题能够独⽴判断，并提出有效解决方案；结合当前工作场景灵活应⽤，并提出有效解决方案。熟悉业务整体流程，主动思考，能够输出合理的技术方案并落地\" \"</p><p><strong>任职要求</strong></p><p>精通 Java 并掌握高并发、分布式、缓存、消息等系统设计要点深入理解JVM、IO、多线程、集合等基础框架，熟悉分布式、缓存、消息等机制。能设计高可用、高扩展的业务架构熟悉分布式事务、服务治理、链路追踪、降级限流等机制熟悉常见微服务框架（Spring Cloud / Dubbo），理解其核心机制。熟悉主流中间件（如 kafka、nacos、Redis）的实现原理和应用场景。有较强的系统性能优化能力具备一定的项目管理能力，能够协调团队资源，推动项目进展。了解常见的安全漏洞及防范措施，能够保障系统的安全性。有较强的自驱能力，良好的沟通和团队协作能力，思路清晰、逻辑严谨。\"</p>', '5-10年', '642240c5348d04500nVz3du6GFpT', '深圳 · 南山区 · 科技园', '18-24K', 'Java, 能高扩展业务架构, 分布式经验, 风控支付金融相关项目, SpringCloud, Kafka, Redis, Dubbo, Spring, 微服务经验, 有高并发处理经验, MySQL, 能设计高可用业务架构', 'java高级开发工程师', 'https://www.zhipin.com/job_detail/642240c5348d04500nVz3du6GFpT.html', '');
INSERT INTO `jobs` VALUES (612, '中充服', '物联网', '100-499人', '天使轮', '大专', '<p><strong>职位描述</strong></p><ol><li>实现产品功能，完成开发任务，参与需求分析，编写接口技术文档；</li><li>参与技术需求的预研，技术可行性分析，系统架构的设计、优化；</li><li>根据业务需求，进行编码，调试，单元测试，解决核心技术瓶颈；</li><li>定期进⾏Code Review，提升代码质量和团队能⼒；</li><li>参与产品项⽬规划工作，设计架构相关技术方案，制定具体项⽬实施规则</li></ol><p><strong>任职要求</strong></p><ol><li>3年以上Java开发及应用经验，了解虚拟机相关知识，熟悉多线程编程；</li><li>熟悉常见的主流框架 Spring／SpingMVC／MyBatis／Spring Boot 等；</li><li>熟悉数据库相关技术，熟练掌握Mysql／Oracle／Redis等常用数据库使用和性能优化；</li><li>熟练使用Maven构建项目，使用Svn／Git进行版本控制；</li><li>具备较强的自学能力，逻辑分析能力及抗压能力；</li><li>具有团队开发经验，良好的代码书写和规范能力，能够独立承担模块级开发任务；</li><li>参与项目开发工作，配合产品经理完成软件开发任务。加分项：</li><li>了解前端技术（H5、JQuery、React、Vue等）优先2、熟练掌握Docker容器，SpringCloud微服务开发者优先</li></ol>', '5-10年', '25910b443713a7b80nB83NS9ElRW', '深圳 · 龙岗区 · 坂田', '15-20K', 'Java, 物联网经验, C++, 不接受居家办公, SpringCloud, MySQL, Redis, 架构设计经验, Spring, Oracle, Python', 'Java', 'https://www.zhipin.com/job_detail/25910b443713a7b80nB83NS9ElRW.html', '零食下午茶, 绩效奖金, 底薪加提成, 五险一金, 团建聚餐, 员工旅游, 节日福利, 高温补贴, 全勤奖, 法定节假日三薪, 保底工资, 节假日加班费, 免费工装, 加班补助, 通讯补贴, 带薪年假, 股票期权');
INSERT INTO `jobs` VALUES (613, '深圳市朱雀软件科技', '互联网', '100-499人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责教育产品开发，根据需求进行系统架构设计、概要设计、数据库设计和接口设计等；，2.根据需求，完成产品业务模块开发的代码编写、自测，并对代码质量负责；</li><li>参与公司产品的架构优化，性能优化并辅助其他模块进行技术实现；</li><li>根据需求编写开发文档，对接前端开发⼈员；</li><li>根据项⽬具体要求，按计划完成任务⽬标；</li><li>完成领导交代的其他事项。</li></ol><p><strong>岗位要求</strong></p><ol><li>6年以上Java实际开发经验，Java基础扎实，熟悉集合、多线程、IO等基础知识，有架构设计经验；</li><li>熟悉主流开源框架的设计和原理，如Spring MVC、Spring boot、SpringCloud、mybatis等，熟悉redis缓存机制。</li><li>熟练掌握常用数据库，有数据库设计、调优经验，熟悉MYSQL、MONGODB，ES等数据库4.掌握linux常见命令和定位问题方法，有较强的的定位问题能⼒；</li><li>对信息安全和常见的方案有一定的了解，有较强的逻辑分析能力和解决问题的能力；</li><li>有一定的程序性能分析和性能优化能力；</li><li>良好的沟通表达能力和解决问题能力，具有主观能动性；加分项：有C端项目经验，如课程类直播类高并发产品、AI项目落地并上线</li></ol><p><strong>福利待遇</strong></p><ol><li>早九晚六，周末双休，5天7小时工作制，不鼓励加班；</li><li>入职即购买五险一金；</li><li>依法享有国家劳动法婚假、产假、公休假等；</li><li>每年公司都有1-2次集体国内外出游活动；</li><li>定期行业培训、优秀者晋升调薪机会；</li><li>过节</li></ol><p><strong>福利</strong></p><p>、全勤奖、项目奖、工龄奖、年终奖等。</p>', '5-10年', '559d0875876abb4303x50tm1EVtU', '深圳 · 龙岗区 · 布吉', '18-25K', 'Java, Nginx, 不接受居家办公, Elasticsearch, SpringCloud, MySQL, Redis, MongoDB', '高级java开发工程师', 'https://www.zhipin.com/job_detail/559d0875876abb4303x50tm1EVtU.html', '零食下午茶, 工龄奖, 员工旅游, 保底工资, 全勤奖, 年终奖, 节日福利, 五险一金, 意外险, 团建聚餐');
INSERT INTO `jobs` VALUES (614, '拓店易', '计算机软件', '20-99人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责后端服务的设计、开发和优化，确保功能的有效实现。</li><li>参与系统架构设计，提升系统的性能和稳定性。</li><li>实现业务逻辑的建模与开发，保证业务需求的准确性。</li><li>优化现有系统代码，提高系统的可维护性和扩展性。</li><li>解决开发过程中的技术难题，保证项目按时交付。</li></ol><p><strong>任职要求</strong></p><ol><li>6~8年Java开发经验，熟练掌握 Java 语言，熟悉主流开发框架如 Spring 和 Spring Boot。</li><li>有复杂的流程类或者财务类经验优先，并且在此类项目上有3年以上沉淀，如ERP、OA、SPA、财务软件等 3、会做方案设计，包括：功能设计、数据库设计等，对UML图熟悉，会画时序图、流程图、等 4、熟悉关系型数据库（如 MySQL、PostgreSQL），掌握复杂查询与性能优化。</li><li>熟悉常用开发工具（如 Git、Maven）和开发流程，具备良好的代码管理习惯。</li><li>熟练掌握linux常用命令、nginx配置、docker部署等</li></ol>', '5-10年', '9a4fc5acfc3047e503Vz09S_FlpU', '深圳 · 龙华区 · 民治', '15-20K', 'Java, 物联网经验, 分布式经验, 方案设计, 复杂流程经验, PostgreSQL, SpringCloud, 接受无前端经验/技能, Drools/Easy Rules, Spring, ERP开发经验, 规则引擎, Docker, MySQL, 架构设计经验, 财务类经验', '高级后端研发工程师', 'https://www.zhipin.com/job_detail/9a4fc5acfc3047e503Vz09S_FlpU.html', '团建聚餐, 五险一金, 绩效奖金, 底薪加提成, 年终奖, 带薪年假');
INSERT INTO `jobs` VALUES (615, '链宇', '互联网', '100-499人', 'A轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责对现有系统进行功能维护和升级 。</li><li>负责根据新需求进行功能设计和开发 。</li><li>负责对改进和新研功能进行单元测试和系统测试 。</li><li>负责定期进行新版本发布和部署。</li><li>负责撰写项目所需文档。</li></ol><p><strong>任职要求</strong></p><ol><li>熟悉主流的Java web开发框架SpringBoot、MybatisPlus,对微服务SpringCloudAlibaba有一点的认识了解，有5-10年的java开发工作经验。</li><li>熟悉MySQL数据库, 熟练使用SQL语言进行数据操作。</li><li>对vue，js等前端技术有所了解，具有一定开发能力。</li><li>模块独立开发的能力,对产品的需求能进行独立的设计开发。</li><li>良好的沟通和团队协作能力，有java架构和项目管理经验优先！</li></ol>', '5-10年', '6aecfddb5acad83c1HR-29S5FltV', '深圳 · 南山区 · 科技园', '15-30K', '不接受居家办公', '高级后端开发工程师', 'https://www.zhipin.com/job_detail/6aecfddb5acad83c1HR-29S5FltV.html', '零食下午茶, 生日福利, 年终奖, 节日福利, 保底工资, 节假日加班费, 法定节假日三薪, 意外险, 带薪年假, 五险一金, 补充医疗保险, 股票期权, 定期体检, 团建聚餐');
INSERT INTO `jobs` VALUES (616, '中兴视通', '运营商/增值服务', '100-499人', '不需要融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责公司核心业务平台的设计、开发与维护，确保代码质量和系统稳定性；</li><li>参与系统架构设计，提供高性能、高可用的技术解决方案；</li><li>负责MySQL数据库的优化工作，包括索引优化、查询优化及存储过程调优；</li><li>深入理解业务需求，设计并实现高质量的业务模块；</li><li>熟悉Spring Cloud微服务框架，负责分布式系统的开发与性能优化；</li><li>推动团队技术能力提升，参与技术难题攻关，解决系统中的关键问题；</li><li>对现有系统进行性能分析和优化，提升用户体验和系统效率。</li></ol><p><strong>任职要求</strong></p><ol><li>计算机相关专业本科及以上学历，985/211院校优先；</li><li>3-5年以上Java开发经验，有大型互联网平台或复杂系统开发经验者优先；</li><li>扎实的Java基础，熟悉JVM原理、多线程编程、并发处理等；</li><li>熟练掌握Spring Boot、Spring Cloud等主流框架，有实际项目经验；</li><li>熟悉MySQL数据库，具备数据库设计、优化及调优经验；</li><li>了解分布式系统原理，熟悉缓存（如Redis）、消息队列（如Kafka、RabbitMQ）等中间件；</li><li>具备性能优化经验，能够对系统瓶颈进行定位和改进；</li></ol>', '5-10年', '30482b0c9d45bd0f1H1929W5FFNW', '深圳 · 南山区 · 科技园', '18-22K·15薪', 'Java, C++, SpringCloud, MySQL, Redis', '高级JAVA工程师', 'https://www.zhipin.com/job_detail/30482b0c9d45bd0f1H1929W5FFNW.html', '节日福利, 加班补助, 零食下午茶, 保底工资, 包吃, 股票期权, 定期体检, 免费班车, 员工旅游, 带薪年假, 餐补, 意外险, 法定节假日三薪, 五险一金, 绩效奖金, 团建聚餐, 工龄奖, 年终奖, 通讯补贴');
INSERT INTO `jobs` VALUES (617, '化化科技', '互联网', '20-99人', '', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责公司 后端微服务架构 的设计、开发和优化，确保系统的高可用性、可扩展性和高性能；</li><li>负责 微服务架构 设计与开发，熟悉 Spring Cloud、Dubbo、gRPC 等微服务框架，优化 服务拆分、负载均衡、服务治理；</li><li>参与产品系统设计，负责核心代码的⾼质量开发，快速响应业务需求，及时交付⾼质量的后端功能。</li><li>参与系统架构设计，优化后端性能，提升⽤户体验。</li><li>参与项目需求分析、设计和评审，输出高质量的设计和实现⽅案；</li><li>优化系统架构和数据库性能，提升接口效率，确保系统高效运行。</li><li>解决高并发和复杂业务模型带来的技术挑战，提供创新解决方案。</li><li>监控系统状态，及时发现并解决潜在问题，提升系统可靠性。</li><li>撰写和维护项目代码，遵循项目开发规范和团队协作规范。</li><li>负责后端服务的设计、开发与维护，确保系统稳定性和扩展性。</li><li>参与系统架构设计，与前端团队紧密合作，优化后端性能，完成接口对接并确保项目的整体用户体验，提升用户体验。</li></ol><p><strong>岗位要求</strong></p><ol><li>本科及以上学历，计算机软件或相关专业，8年以上后台开发经验，有1年以上管理经验。</li><li>精通Java开发语言，对于JVM、Java多线程、并发以及网络通信有深厚的经验，扎实的计算机基础，如操作系统、计算机网络、算法、数据库等，并能熟练使用AI编程助手(如GitHub Copilot、通义灵码等)提升研发效率。</li><li>设计和开发高性能、高并发的RESTful API接口，支持前端、移动端及第三方系统集成；</li><li>熟练使用Spring Boot/Spring Cloud 进行微服务开发，确保服务的稳定性和可维护性；</li><li>熟悉MySQL\\PostgreSQL数据库，熟悉Redis、MongoDB、Elasticsearch等NoSQL存储及相关性能优化；</li><li>熟悉Linux系统及常用操作系统命令，具备Shell脚本编写能力。</li><li>熟悉 Kubernetes（K8s） 及核心组件（如 etcd），能够基于 K8s + etcd 进行 分布式配置管理、服务注册与发现、数据一致性维护；</li><li>理解分布式系统基本原理，对消息中间件（如rocketmq\\kafka）的使用及底层实现。</li><li>具备系统整体架构设计能力，能够从长远角度考虑系统的稳定性、可用性和扩展性。</li><li>有丰富的互联网电商业务的交易系统(商品订单/支付)。</li><li>有高并发、大数据量处理场景的解决思路和实际经验者优先。</li><li>懂本地化部署、API接口等。</li></ol>', '5-10年', '9544a6eaf6fc7f470nJ409-7F1pX', '深圳 · 福田区 · 车公庙', '15-25K', 'Java, C++, Golang, Python, Spring, SpringCloud, MyBatis, Hibernate, Kafka, MySQL, Redis, MongoDB, HBase, 团队管理经验, 大数据经验, 微服务经验, 架构设计经验, 云计算经验, 不接受居家办公', 'AI Java高级工程师', 'https://www.zhipin.com/job_detail/9544a6eaf6fc7f470nJ409-7F1pX.html', '');
INSERT INTO `jobs` VALUES (618, '创智艾泰克', '计算机软件', '100-499人', '未融资', '本科', '<ol><li>全日制本科以上学历，计算机专业；</li><li>6年及以上工作经验，负责带领java开发小组根据产品开发计划，按时提交高质量代码，完成开发任务，有2年以上⼩组管理经验或者项⽬管理经验；</li><li>具备较强的逻辑思维能⼒、理解能力和交流能力，责任感强；</li><li>熟悉达梦、⼈大金仓、sqlserver、mysq、oraclel数据库。</li><li>熟悉微服务的各类组件、熟悉微服务部署和实施。</li><li>有参与过设计院信息系统、协同设计系统者优先。</li></ol>', '5-10年', 'bc4c9a0b8ab018ff0nJ43Ny7F1NV', '深圳 · 龙岗区 · 南联', '11-18K', 'Java, SpringCloud, MySQL, 团队管理经验, 不接受居家办公', 'Java工程师', 'https://www.zhipin.com/job_detail/bc4c9a0b8ab018ff0nJ43Ny7F1NV.html', '员工旅游, 五险一金, 节日福利, 年终奖, 定期体检, 带薪年假');
INSERT INTO `jobs` VALUES (619, '上海星光瀚澜智能科技', '医疗服务', '20-99人', '', '本科', '<p><strong>岗位职责</strong></p><p>负责企业统⼀⾝份 IAM 平台后端开发，搭建 SSO 单点登录、统⼀权限治理体系；落地 OAuth2.0/JWT/SAML 协议，设计 RBAC/ABAC 多租户权限模型；做高并发登录性能调优、账号安全风控，对接各业务系统，处理线上问题。</p><p><strong>任职要求</strong></p><p>1、本科，5 年 Java 后端，有 IAM/SSO 权限平台落地经验优先2、精通 SpringBoot/SpringCloud、Spring Security、JVM 调优3、熟悉 OAuth2、SAML 单点登录原理，熟练 MySQL、Redis、Kafka4、懂分布式、微服务，有 Keycloak 二次开发、Docker 使⽤经验加分岗位优势：负责企业核心身份安全平台，深耕权限架构，技术成长空间大</p>', '5-10年', 'e5f2b7e1ffdfc3090nFz0tq5EFpQ', '深圳 · 南山区 · 科技园', '15-16K', 'Java, Spring, SpringCloud, Kafka, Docker, JVM, MySQL, Redis, 架构设计经验, 分布式经验, 微服务经验, 云计算经验, IAM, 统一身份认证, SSO 单点登录', 'IAM身份访问管理 Java开发工程师', 'https://www.zhipin.com/job_detail/e5f2b7e1ffdfc3090nFz0tq5EFpQ.html', '');
INSERT INTO `jobs` VALUES (620, '国信技术', '计算机软件', '0-20人', '', '大专', '<p>本科及boss以上学历，计算机或相关专业，5年以上JAVA 开发经验。熟练掌握 JAVA编程 。熟练掌握 JAVA Sprint/ Spring boot/ Spring Cloud 开发框架,。熟练掌握 MySql，SqlServer 等关系型数据库使用。了解 Redis 或 Mongo Db 等 Nosql 技术。了解常用的消息队列中间件 RabbitMQ 或Kafka 使用。熟练掌握 Linux 运维，Docker, Git ，Nginx 等使用经验。精通Vue /UniApp/API Cloud 移动开发经验。</p>', '5-10年', '0a12ef32d7ed16650nF62NW-ElZT', '深圳 · 南山区 · 科技园', '10-12K', 'Java, SpringCloud, MySQL, 架构设计经验, 不接受居家办公', 'java开发工程师', 'https://www.zhipin.com/job_detail/0a12ef32d7ed16650nF62NW-ElZT.html', '');
INSERT INTO `jobs` VALUES (621, '版石控股集团有限公司', '互联网', '100-499人', '未融资', '大专', '<p>简历尽量筛选下有光储充平台开发经验，对并发有一定处理经验的Java开发工程师</p><p><strong>岗位职责</strong></p><ol><li>负责物联网平台及ToC端核心业务系统的架构设计与开发，保障⾼并发与⾼可⽤。</li><li>基于 JDK 21 及 Solon 框架进行敏捷开发，探索新技术以提升系统性能。</li><li>参与B端功能迭代，负责营销、现场运维类功能开发4、参与C端功能迭代，优化接口响应速度，保障流量高峰期的系统稳定。</li></ol><p><strong>任职要求</strong></p><ol><li>5年及以上Java开发经验，有完整的IoT或ToC应⽤落地经验优先。</li><li>熟练掌握Java基础、springboot、solon等开发框架3、熟练掌握 JDK 21 新特性并有实际应用经验。</li><li>熟练使用mysql、redis、Elasticsearch等数据库5、熟练使用rocketMQ中间件6、具备良好的代码规范和逻辑思维，沟通顺畅，能独立完成模块开发任务7、具备一定的抗压能力加分项：</li><li>参与过solon框架应用落地2、参与过物联网平台核心开发3、参与过数据平台核心开发早8点30 晚5点30双休，深圳的需要到面，实在道面不了也可以线上深圳市南山区中心路深圳湾段3331号南门，南山区中建科工大厦</li></ol>', '5-10年', '536b8c3c25c8ef970nJ43tS-EVVW', '深圳 · 南山区 · 科技园', '12-13K', 'Java, Spring, Netty, Docker, Elasticsearch, MySQL, Redis, SQL Server, 分布式经验, 微服务经验, 不接受居家办公', 'Java-物联网-ToC端-五险一金-双休_wb9zjkg', 'https://www.zhipin.com/job_detail/536b8c3c25c8ef970nJ43tS-EVVW.html', '全勤奖, 保底工资, 交通补助, 年终奖, 有无线网, 带薪年假, 团建聚餐, 绩效奖金, 节日福利, 五险一金, 免费班车, 工龄奖, 意外险, 生日福利, 底薪加提成');
INSERT INTO `jobs` VALUES (622, '美梦智能', '智能硬件', '0-20人', '未融资', '本科', '<p><strong>工作职责</strong></p><ul><li>参与软件架构设计和开发,包括系统设计、组件开发、性能优化和测试。</li><li>与团队密切合作,包括产品经理、设计师、测试人员和其他开发人员,确保软件产品的按时交付。</li><li>解决软件系统中出现的任何问题,包括技术问题和团队沟通问题。</li><li>定期更新和升级Java应用程序,保持对最新技术的了解并将其应用到项目中。</li><li>编写文档和示例代码,帮助其他开发人员了解和使用现有的软件系统。</li></ul><p><strong>职位要求</strong></p><ul><li>全日制本科学历，物联网、计算机相关专业，学信网可查- 5年以上Java开发经验,有1-2个或更多大型项目的独立开发经验；</li><li>熟悉Java编码规范和最佳实践,包括面向对象编程、多线程编程和Java安全机制；</li><li>熟悉Spring、Hibernate、MyBatis等Java框架,并能够使用它们开发Java应用程序；</li><li>熟悉数据库,包括MySQL和Oracle等；</li><li>熟悉前端技术,包括HTML、CSS和JavaScript,并能够将它们与Java应用程序集成；</li><li>良好的沟通能力和团队合作精神,能够与不同背景和经验的人合作；</li><li>熟悉敏捷开发方法；熟悉Git或其他版本控制系统；</li><li>有软硬结合的项目经历；</li><li>有医疗或者智能硬件行业的工作优先</li></ul><p><strong>福利待遇</strong></p><ol><li>不定期举办丰富多彩的员工活动（团建、生日聚餐）；</li><li>享有公司内部的岗位提升机会，人性化管理，同事和睦相处；</li><li>依国家法定执行休假，并享有带薪年假；</li><li>享受节假日</li></ol><p><strong>福利</strong></p><p>，生日</p><p><strong>福利</strong></p><p>，茶饮零食，绩效奖金；本公司不属于外包，欢迎您的加入！</p>', '5-10年', '814e389064ba8d9d1HZ_3Nm9FFRU', '深圳 · 光明区 · 光明', '10-15K', 'JAVA, 物联网经验, Hibernate, MySQL, 其他, Spring, 有前端经验/技能', 'java工程师', 'https://www.zhipin.com/job_detail/814e389064ba8d9d1HZ_3Nm9FFRU.html', '员工旅游, 团建聚餐, 绩效奖金, 节日福利, 年终奖');
INSERT INTO `jobs` VALUES (623, '美鸥跨境', '其他专业服务', '100-499人', '未融资', '大专', '<p><strong>一、岗位职责</strong></p><ol><li>独立模块负责：全权负责跨境合规模块（VAT/EPR/知识产权等）的技术架构设计、核心代码编写及迭代维护，确保业务逻辑的准确性与系统的扩展性。</li><li>服务商经验转化：基于过往在合规服务商（如税务所、EPR合规服务商）的实战经验，将复杂的各国税务/环保法规转化为标准化的技术解决方案。</li><li>平台深度对接：主导税务计算、合规申报数据同步等复杂场景的落地。</li><li>架构优化：基于Spring Cloud Alibaba微服务⽣态，持续优化系统的⾼并发处理能⼒，解决跨境业务中的多时区、多币种及数据一致性问题。</li><li>技术攻坚：解决合规业务中的技术痛点（如大规模订单税务重算、EPR注册号⾃动校验等），并指导团队成员提升业务理解力。</li></ol><p><strong>二、任职要求</strong></p><ol><li>计算机相关专业专科及以上学历，5年以上Java开发经验。具备2年以上跨境电商合规服务商（如VAT代理、EPR服务商）的开发背景。</li><li>模块独立负责能力： VAT领域：深刻理解欧盟、英国税务逻辑，有独立设计税务计算引擎或申报系统的经验。 EPR领域：熟悉WEEE、电池法、包装法等EPR业务流程，有相关注册号管理、申报数据清洗的实际落地经验。</li><li>技术深度： 精通Java及Spring Cloud Alibaba全家桶（Nacos, Sentinel, Seata），有处理分布式事务（如订单与税务状态一致性）的实战经验。 熟练使用MySQL（分库分表）、Redis、RocketMQ，具备SQL调优能力。 良好的编码习惯，有代码洁癖。</li><li>API对接能力： 熟悉Amazon SP-API的OAuth2.0授权流程及数据模型，有处理PII（个人隐私信息）数据安全合规的实战经验。 加分项1. 税局直连经验：有英国(HMRC)、德国(BZSt)、法国、意大利、西班牙等欧盟/欧洲税局API直连对接经验者优先。</li><li>有知名跨境合规SaaS平台核心合规模块开发经验者优先。</li><li>熟悉AI在合规领域的应用（如利用LLM自动解析各国税务政策文档）者优先。</li><li>具备英语读写能力，能直接阅读海外税务局/EPR官方技术文档者优先。</li></ol>', '5-10年', 'd583543db28ae77c0nd-09m7GVpS', '深圳 · 龙岗区 · 坂田', '10-15K', 'Java, SpringCloud, Spring, MySQL, SQL Server, 不接受居家办公, ERP开发经验, 跨境合规SaaS平台, RocketMQ, VAT/EPR', 'Java高级工程师', 'https://www.zhipin.com/job_detail/d583543db28ae77c0nd-09m7GVpS.html', '五险一金, 零食下午茶, 底薪加提成, 带薪年假, 团建聚餐, 生日福利, 年终奖, 员工旅游, 节日福利, 有无线网');
INSERT INTO `jobs` VALUES (624, '融聚汇', '大数据', '100-499人', 'A轮', '本科', '<p><strong>职位描述</strong></p><ol><li>参与后端产品技术选型、架构设计、核心代码开发；</li><li>研发港美股行情交易平台，包括核心模块的架构、设计和实现；</li><li>研究并实践分布式、高并发、安全性等技术⽅案；</li><li>主导解决系统技术难题。</li></ol><p><strong>任职要求 </strong></p><ol><li>JAVA基础扎实，深刻理解集合、NIO、并发等机制，有JVM调优经验，掌握线程池、连接池运作原理；</li><li>全⽇制本科及以上学历，计算机相关专业，5年以上相关⼯作经验，了解常用开源框架的原理和机制，对Spring、Hessian, Mybatis等框架熟悉；</li><li>熟悉分布式系统的设计和应用，熟悉序列化、分布式、缓存、MQ等机制，能熟练应⽤Zookeeper、Netty、Dubbo、RocketMQ、Kafka等技术；</li><li>掌握多线程及高性能系统设计原则，有高并发应用开发及性能调优经验；</li><li>有一定安全意识并了解常见的安全问题解决方案；</li><li>精通关系型数据库设计、熟悉SQLServer、MySQL、PostgreSQL、Redis等数据库的使用；</li><li>以下经验者优先：有证券行业从业经验、能系统使用AI相关技术或工具应用于项目开发。</li></ol>', '5-10年', 'b3c3bb8564ec2b290nVz09-6ElJS', '深圳 · 南山区 · 科技园', '15-25K', 'Java, MySQL, Kafka, MyBatis, Spring', 'java工程师', 'https://www.zhipin.com/job_detail/b3c3bb8564ec2b290nVz09-6ElJS.html', '员工旅游, 意外险, 五险一金, 零食下午茶, 带薪年假, 节日福利');
INSERT INTO `jobs` VALUES (625, '云集', '大数据', '20-99人', '天使轮', '本科', '<p><strong>岗位职责</strong></p><ol><li>负责平台级业务的服务端业务研发，平台级核心代码开发；</li><li>解决产品研发过程中碰到的各种技术难题，不断突破性能瓶颈；</li><li>能够在团队中完成code review的任务，确保相关代码的有效性和正确性，协同团队作战；</li><li>灵活支撑业务的同时，对于系统高可用、高并发、大数据等有较为深厚的理解；入职要求：</li><li>计算机及相关专业，统招本科及以上学历，IT或互联网行业的中大型项目研发经验；</li><li>扎实的JAVA基础，掌握JVM、并发编程、网络编程等基础知识；熟悉各种算法与数据结构；熟悉单元测试、WEB开发、数据库等基础技术；</li><li>熟悉Spring、SpringMVC、MyBatis或其他主流开发框架；掌握常用数据结构、常见设计模式，拥有领域模型抽象能力；</li><li>熟悉分布式系统设计、SOA、消息队列、缓存等技术；具备大型网站核心开发、设计经验者优先；</li><li>有强烈的技术热情和钻研精神，热爱新技术；有独立、主动的学习习惯和良好的沟通表达、团队协作能力；</li><li>具备较强的业务理解及业务抽象能力，能够快速从业务需求中找到技术设计的场景，有较强的业务sense；</li><li>个性乐观开朗，好奇心强，逻辑思维强，善于团队合作；</li><li>有golang项目经历者，优先考虑</li></ol>', '5-10年', '3df5e7e20d5ce13c1XB40tu-E1JT', '深圳 · 光明区 · 公明', '10-12K', '后端工程师, Java, Redis, 计算机/软件工程相关经验, golang', 'java开发工程师', 'https://www.zhipin.com/job_detail/3df5e7e20d5ce13c1XB40tu-E1JT.html', '节日福利, 五险一金, 住房补贴, 加班补助, 定期体检, 年终奖, 员工旅游, 带薪年假, 交通补助, 股票期权, 零食下午茶, 餐补, 通讯补贴, 全勤奖, 免费班车, 补充医疗保险');
INSERT INTO `jobs` VALUES (626, '汇信昌', '装修装饰', '100-499人', '未融资', '本科', '<p><strong>岗位职责</strong></p><ol><li>参与公司核心业务系统的需求分析、架构设计及代码开发，保障系统高性能、高可用性；负责Java后端服务开发，包括但不限于业务逻辑实现、接口设计、数据库优化等；</li><li>编写高质量、可维护的代码，参与代码审查和技术文档编写；</li><li>持续优化系统性能，解决线上问题，保障系统稳定性和安全性；</li><li>跟踪前沿技术，研究并落地新技术方案（如微服务、云原生、AI工程化等）；</li><li>与产品、测试、前端团队协作，推动项目高效交付；</li><li>领导安排的其他任务。</li></ol><p><strong>任职要求</strong></p><ol><li>学历与经验：本科及以上学历，计算机相关专业，3年以上Java开发经验（高级岗需5年+）；</li><li>良好的逻辑思维、问题分析与解决能力；</li><li>具备团队协作精神，能承受一定压力，对技术有热情。</li><li>熟练ai主流工具5、身体健康无传染项技术基础：</li><li>扎实的Java基础，熟悉JVM、多线程、集合、IO/NIO等核心机制；</li><li>熟练使用SpringBoot、SpringCloud、MyBatis等主流框架；</li><li>熟悉MySQL、PostgreSQL等关系型数据库，具备SQL优化能力；</li><li>熟悉Redis、Kafka、RocketMQ等中间件，了解其应用场景；开发能力：</li><li>熟悉Maven/Gradle、Git、Linux开发环境；</li><li>熟悉RESTfulAPI设计，了解OAuth2、JWT等安全方案；</li><li>熟悉分布式系统设计，如CAP理论、分布式事务（Seata等）；加分项：</li><li>有高并发、分布式系统开发经验（如分库分表、熔断降级）；</li><li>熟悉微服务架构（Dubbo、SpringCloudAlibaba），有容器化（Docker/K8s）经验；</li><li>熟悉云服务（AWS/Aliyun/TencentCloud）及Serverless架构；</li><li>有安卓开发经验；了解扫码枪、PDA等设备使用；</li><li>有开源项目贡献或技术博客/社区活跃经历；</li><li>了解前端技术（Vue/React）者优先。</li></ol>', '5-10年', '346f6e9fe8956fd01H1729q1FVpV', '深圳 · 宝安区 · 石岩', '18-25K', 'MES开发经验, Java, SpringCloud, 架构设计经验, Oracle, ERP开发经验', '高级java研发工程师', 'https://www.zhipin.com/job_detail/346f6e9fe8956fd01H1729q1FVpV.html', '节日福利, 高温补贴, 全勤奖, 员工旅游, 带薪年假, 五险一金, 绩效奖金, 交通补助, 有无线网, 春节超长假期, 股票期权, 免费工装, 通讯补贴, 零食下午茶, 团建聚餐');
INSERT INTO `jobs` VALUES (627, '达芬奇新能源', '计算机软件', '0-20人', '未融资', '本科', '<p><strong>一、岗位职责</strong></p><ol><li>负责公司智慧停车后端平台的设计、开发、迭代及维护，核心支撑车位管理、预约调度、无感⽀付、设备管控、数据统计分析等核⼼业务模块，保障平台⾼可用、高并发、⾼安全。</li><li>负责后端服务架构设计与优化，梳理业务逻辑，设计合理的数据模型、接口规范及业务流程，提升系统性能、可扩展性与可维护性，支撑业务快速迭代。</li><li>对接物联网设备，负责设备数据采集、解析、存储与同步，实现设备状态监控、远程控制等功能，保障设备与平台的数据联动稳定。</li><li>与前端开发、测试、产品等团队紧密协作，完成接口设计、开发与联调，处理前后端数据交互、异常排查等问题，配合完成产品功能落地与上线。</li><li>负责后端平台线上问题排查、bug修复、性能优化，监控系统运行状态，及时处理突发故障，保障平台7×24小时稳定运行，降低系统故障率。</li><li>参与智慧停车业务需求分析与技术方案讨论，结合后端技术特点，为产品优化、功能迭代提供合理建议，沉淀技术文档、开发规范及通用组件，提升团队开发效率。</li><li>负责数据库设计、优化与维护，处理数据备份、恢复及性能调优，保障数据安全与数据一致性；关注行业技术动态，将合适的新技术、新框架应用到项目中，推动技术升级。</li></ol><p><strong>二、任职要求</strong></p><ol><li>学历：本科及以上，计算机、电子通信、软件工程、物联网工程等相关专业优先，5年及以上后端开发经验，有物联网、智慧停车、智慧城市、平台开发相关项目经验者优先。</li><li>了解物联网基础原理、常见物联网协议，熟悉智慧停车业务流程者优先，能快速理解业务逻辑并转化为后端实现方案。</li><li>熟练掌握Java语言的核心特性、开发框架及生态体系。</li><li>熟练掌握关系型数据库，精通SQL语句编写、数据库设计、索引优化及性能调优；了解非关系型数据库，能熟练运用其解决业务场景问题。</li><li>了解物联网协议，能完成物联网设备数据对接、解析与同步，熟悉设备管理相关开发逻辑，有设备接入平台开发经验者优先。</li><li>熟悉后端工程化、微服务架构，了解服务注册与发现、负载均衡、熔断降级等机制，能参与架构设计与优化，提升系统可扩展性与稳定性。</li><li>熟悉Linux系统操作，能熟练使用命令行进行服务器部署、日志排查、服务监控；掌握Git版本控制工具，能规范进行代码提交、分支管理与协作开发。</li><li>了解分布式系统、高并发处理、数据加密等相关技术，能应对智慧停车高峰期的系统压力，保障平台稳定运行；有支付接口集成经验者优先。</li></ol>', '5-10年', '4dc991f0cb96a4d90nBy0tW7EVJV', '深圳 · 宝安区 · 石岩', '15-20K', 'Java, SpringCloud, MySQL, 智慧停车, 停车系统, 道闸系统', '停车系统平台Java开发高级工程师', 'https://www.zhipin.com/job_detail/4dc991f0cb96a4d90nBy0tW7EVJV.html', '五险一金, 绩效奖金, 年终奖');
INSERT INTO `jobs` VALUES (628, '凌宙云', '互联网', '20-99人', '不需要融资', '本科', '<p>【</p><p><strong>岗位职责</strong></p><p>】●参与后台服务的全生命周期研发，覆盖需求评审、技术方案设计、接口契约定义、编码实现、单元测试、联调与上线发布等环节，对交付物的性能、可用性、安全性与可维护性负责。●承担银行存款、贷款、账务等核⼼系统的接口开发与对接联调，跟进接口在⽣产环境的运⾏情况，保障接口稳定可用。●负责生产环境的问题排查与应急处理，通过⽇志分析、全链路追踪、数据核对等手段，独立完成账务差错的定位与处理，并推动事后复盘与改进。●参与系统的代码评审、技术文档编写、知识沉淀等团队协作工作，对历史代码或复杂模块进行安全、可控的重构与优化。●与产品、测试、运维以及业务方协同推进项目落地，对所负责模块的交付质量和上线效果负责。【</p><p><strong>任职要求</strong></p><p>】●计算机科学与技术、软件工程、信息系统、通信工程等计算机相关专业。从事5 年及以上 Java 后端开发经验。●有银行核心系统（存款、贷款、账务、清结算等任一方向）研发经验者优先。●精通 Java 及其主流生态，熟练运用 Spring Boot / Spring Cloud 进行微服务开发，深入理解 Spring 框架核心机制（IoC、AOP、声明式事务等）。熟练使用 Gradle 或 Maven 进行工程构建与依赖治理，能够独立处理多模块工程组织、私服配置等问题。熟悉 MySQL 或 TiDB，具备表结构设计、索引优化与 SQL 调优能力。●熟悉金融场景下的资金安全实践，包括长短款处理、幂等控制、对账机制等。具备较强的生产问题排查与应急处理能力，有过线上故障定位与修复的实战经验●编码规范，注重代码可读性与文档完备性，代码评审中能够主动发现并指出潜在风险。具备较强的代码阅读与逆向分析能力，能够在陌生代码库中快速厘清调用链路与业务逻辑。文档习惯良好，能够独立输出清晰的接口文档、设计文档、运维手册和复盘报告。</p>', '5-10年', '793bb0624a2b9e010nFy39-4FVZX', '深圳 · 南山区 · 科技园', '16-20K', 'Java, Python, Spring, SpringCloud, MySQL, SQL Server, PostgreSQL, 架构设计经验, 大数据经验', '高级java开发工程师', 'https://www.zhipin.com/job_detail/793bb0624a2b9e010nFy39-4FVZX.html', '五险一金, 定期体检, 生日福利, 全勤奖, 法定节假日三薪, 加班补助, 节日福利, 保底工资, 带薪年假');
INSERT INTO `jobs` VALUES (629, '普盛网络', '计算机软件', '20-99人', '未融资', '本科', '<p>1. 学历要求：全日制本科以上学历，学信网可查，4年以上实际项目开发工作经验（不含实习期）； 2.</p><p><strong>岗位职责</strong></p><p>负责央国企、政府应用开发（公司自研产品线，不是外包岗位）3.</p><p><strong>技术要求</strong></p><ol><li>工作时间：采用大小周工作制，周一到周五上午8:30-12:00,下午14:00-17:30,周六9:00-16:30。</li><li>加分项：</li><li>有微信公众号（小程序）项目经验、ERP项目、渠道分销项目经验优先 2. 熟悉 Linux 操作系统；达梦数据库；有K8S的实际部署运维经；熟悉VUE、TS等前端技术;</li><li>搭建APM（应用性能管理平台）监控平台的经验：链路、网关熔断、数据库、JVM、日志汇聚平台；本公司是国家高新技术企业，专精特新企业，科技型中小企业，发展前景广阔，</li></ol><p><strong>福利待遇</strong></p><p>中上，欢迎有志之士加入！</p>', '5-10年', 'b499db37fdc25f8603F_2d26EVpZ', '深圳 · 罗湖区 · 东门', '14-25K', 'Java, 物联网经验, 不接受居家办公, 分布式经验, MySQL, MyBatis, 云计算经验, 架构设计经验, ERP开发经验', '中级java开发工程师', 'https://www.zhipin.com/job_detail/b499db37fdc25f8603F_2d26EVpZ.html', '生日福利, 年终奖, 节日福利, 员工旅游, 带薪年假, 全勤奖, 底薪加提成, 零食下午茶, 补充医疗保险, 五险一金');
INSERT INTO `jobs` VALUES (630, '颢云芯科技', '互联网', '0-20人', '', '本科', '<p>投递前注意：必须要有英语四级及以上或相关英语证书</p><p><strong>岗位职责</strong></p><p>●负责金融 APP 后台系统的设计与开发 ●设计面向移动端的 API 服务，具备弱网场景下的可靠交互能力 ●负责⾦融交易链路的⼀致性保障，确保幂等控制和异常补偿 ●负责后台核⼼能力建设，包括统一鉴权、消息队列和监控告警等基础服务 ●负责数据安全治理，保障敏感数据的加密、脱敏和操作审计 ●与前端、Android 等团队协同推进接口联调、问题排查与版本发布 ●熟练使⽤ AI 编程工具辅助编码、排障、重构和文档整理</p><p><strong>任职要求</strong></p><p>●计算机相关专业统招本科及以上学历，5 年及以上 Java 后台开发经验 ●精通 Java，熟悉多线程、JVM、锁机制、并发控制等核心知识 ●精通 Spring Boot / Spring Cloud，具备中大型分布式系统设计与落地经验 ●熟悉 MySQL，具备 SQL 优化、索引设计、事务隔离和数据建模能力 ●熟悉 Redis、消息队列、定时任务、分布式锁等常见中间件 ●具备金融、支付、信贷、账务、风控等相关项目经验，理解幂等、一致性、审计、补偿等金融场景要求 ●具备弱网移动端接口设计经验，能针对重复提交、超时重试、断网恢复等场景设计可靠方案 ●英语 CET-4 及以上，能阅读英文技术文档【加分项】● 深度参与过存贷款、分期、支付、钱包、账务系统或风控等核心金融系统的开发建设。● 在实际项目中拥有深度使用 AI 编程辅助工具的实战经验。● 英语听说读写能力良好，能够流畅使用中英文进行日常协作与沟通</p>', '5-10年', '19532873e9661ce20nBz2Nq-E1pS', '深圳 · 南山区 · 科技园', '14-15K', 'JVM, Java, 分布式经验, AI编程, SpringCloud, MySQL, Redis, 架构设计经验, 金融', 'java开发工程师', 'https://www.zhipin.com/job_detail/19532873e9661ce20nBz2Nq-E1pS.html', '');
